window.D=window.D||{};D.bereshit=[{"slug":"בראשית","name":"פרשת בראשית","items":[{"id":"11","t":"אין חכמה ואין תבונה נגד ה', והמעוות דרכו מפסיד גם את מה שיש בידו","p":[{"t":"וַיֹּאמֶר קַיִן אֶל הֶבֶל אָחִיו וַיְהִי בִּהְיוֹתָם בַּשָּׂדֶה וַיָּקָם קַיִן אֶל הֶבֶל אָחִיו וַיַּהַרְגֵהוּ: (ד, ח)","b":true},{"t":"כתב הרמב\"ן ז\"ל (בסוף פירושו לפסוק), וז\"ל, ויתכן שנתכוין בו ההריגה שיבנה העולם ממנו, כי חשב שלא יהיה לאביו זרע אחר עוד. גם פחד שלא יהיה עיקר בנינו של עולם מאחיו שנתקבלה מנחתו. עכ\"ל.","b":false},{"t":"והעולה מן הדברים שמלבד הקנאה שנתקנא קין בהבל אחיו, וחרה לו מאד שנתקבלה מנחתו של הבל לפני ה', ואילו למנחתו לא שעה. עוד עלתה לו מחשבה, שמעתה שהבל רצוי לפני ה', הריהו עלול לבנות ממנו את כל העולם, והוא יהיה עיקר בנינו של העולם, וזה הבעיר כאש חמתו, וקנאתו גברה ועלתה למעלה למעלה, עד שקם עליו והרגו.","b":false},{"t":"ויש בזה מוסר גדול לבעלי מחשבות, שלא בוטחים על ה' שיעשה מה שנראה לו, ואין מי שיאמר לו למה תתן לזה ולא לזה, ולמה תעדיף זה ע\"ז, וכל כיו\"ב. וסומכים על השתדלותם וכחם, ואל בינתם הם נשענים. והנה קין ביקש לו חשבונות רבים למנוע את בנין העולם ע\"י הבל. ולכן עשה את הדבר היותר גדול שאפשר לו לעשות, שהרג את הבל אחיו, ומעתה א\"א לבנות את העולם מהבל כי איננו עוד. אבל מחשבות קין לא הועילוהו, כי לא ידע שיהיה לאביו עוד זרע כלשון הרמב\"ן ז\"ל.","b":false},{"t":"ולהלן (ד, כה), נאמר, וידע אדם עוד את אשתו ותלד בן ותקרא שמו שת, כי שת לי אלהים זרע אחר תחת הבל כי הרגו קין, וגם אחרי הולדת שת עוד נולדו לאדם בנים ובנות כמבואר בתורה (בראשית ה, ד). ונמצא שכל המעשה הנורא שעשה קין היה לחנם. כי הנה יש אחרים שבאו עוד לעולם, ומהם יתמלא ויתיישב העולם. ולעומת זאת קין נחקק לדראון עולם כרוצח אחיו רח\"ל, וגם שילם בנפשו, שהרי למך הרגו, ונתקיים בו (אבות ב, ו), על דאטפת אטפוך.","b":false},{"t":"וגם מה שחשב להועיל בהריגת הבל שלא יהיה בנין העולם מאחר אלא ממנו. גם זה לא עלה בידו, שהרי נאמר (בראשית ה, א), זה ספר תולדות אדם, ביום ברא אלהים אדם, בדמות אלהים עשה אותו, ושם (פסוק ג), נאמר, ויחי אדם שלשים ומאת שנה, ויולד בדמותו בצלמו, ויקרא את שמו שת וגו'. ולא הזכיר כאן בספר תולדות אדם, לא את קין ולא את הבל אלא את שת, שממנו הושתת עיקר העולם.","b":false},{"t":"ואעתיק לשונו של תרגום יונתן בן עוזיאל שם, וחיא אדם מאה ותלתין שנין, ואוליד ית שת דדמי לאקוניה ולדמותיה, ארום מן קדמת דנא אולידת חוה ית קין דלא דמי ליה, והבל אתקטיל על ידוי, וקין אטרד ולא אתייחסו זרעיתיה בספר ייחוס אדם, ובתר כן אוליד ית דדמי ליה וקרא ית שמיה שת, ע\"כ. הרי לך מפורש בדבריו שקין וזרעו לא נכללו בספר יחוס אדם, משום שקין לא דומה לאדם, והבל איננו, ורק שת שנולד אחר ק\"ל שנים הוא דומה לאדם הראשון בדמותו ובצלמו, והוא המשך יחוסו, והוא עיקרו של העולם.","b":false},{"t":"ובודאי שקורא הדורות מראש, גלוי וידוע לפניו ששת שיולד מאוחר יותר, הוא הממשיך של אדם הראשון, וממנו יהא עיקר בנין העולם, אלא שהאדם קצר רואי, ואינו יודע מה יהיה גם בעוד רגע כמימריה, ויושב ומחשב בדרכים שונות ומשונות להשיג את מטרותיו ולהסיר דאגותיו. אבל אינו יודע כי הרבה פעמים במו ידיו הוא מקרב את מה שרצה להרחיק.","b":false},{"t":"וכמו שמצינו באחי יוסף הצדיק שמכרוהו לעבד, כדי לגנוז לעד את חלומותיו שיהא מלך עליהם, אך לא כאשר דימו היה, כי במו ידיהם שלחו אותו למקום מלכותו, וכן כהנה רבות, ולא עת האסף (וראה מה שנתבאר עוד בענין זה להלן בפרשת ויגש מאמר ג' ופרשת ויחי מאמר כו).","b":false}]},{"id":"11","t":"עבודת ה' – מכל הלב ובכל הכח","p":[{"t":"וְהָאָדָם יָדַע אֶת חַוָּה אִשְׁתּוֹ וַתַּהַר וַתֵּלֶד אֶת קַיִן וַתֹּאמֶר קָנִיתִי אִישׁ אֶת ה', וַתֹּסֶף לָלֶדֶת אֶת אָחִיו אֶת הָבֶל וַיְהִי הֶבֶל רֹעֵה צֹאן וְקַיִן הָיָה עֹבֵד אֲדָמָה, וַיְהִי מִקֵּץ יָמִים וַיָּבֵא קַיִן מִפְּרִי הָאֲדָמָה מִנְחָה לַה', וְהֶבֶל הֵבִיא גַם הוּא מִבְּכֹרוֹת צֹאנוֹ וּמֵחֶלְבֵהֶן וַיִּשַׁע ה' אֶל הֶבֶל וְאֶל מִנְחָתוֹ, וְאֶל קַיִן וְאֶל מִנְחָתוֹ לֹא שָׁעָה וַיִּחַר לְקַיִן מְאֹד וַיִּפְּלוּ פָּנָיו, וַיֹּאמֶר ה' אֶל קָיִן לָמָּה חָרָה לָךְ וְלָמָּה נָפְלוּ פָנֶיךָ, הֲלוֹא אִם תֵּיטִיב שְׂאֵת וְאִם לֹא תֵיטִיב לַפֶּתַח חַטָּאת רֹבֵץ וְאֵלֶיךָ תְּשׁוּקָתוֹ וְאַתָּה תִּמְשָׁל בּוֹ: (ד, א-ז)","b":true},{"t":"עלה בדעתי לבאר את פרשת האחים הראשונים שהיו בעולם, \"קין והבל\", והנה כולם מכירים את המעשה הזה מקטנות, אך לא נותנים לב לזה ומשאירים את זה בצד כדבר שאינו נוגע לנו, שכן, קין \"עובד אדמה\", והבל \"רועה צאן\", ואנו כמו רוב העולם לא \"חקלאים\" ולא \"רועי צאן\", ואין לנו קרבן ולא מזבח, גם לא כהן שיכפר בעדינו, ואין אנו מקריבים קרבנות לא מן הצאן והבקר, ולא מפירות העץ והארץ.","b":false},{"t":"אך בודאי שהתורה לא כתבה סתם סיפורים בעלמא, אלא הכל מכוון ללמדנו דעת ה', כדת מה לעשות בחיי היום יום שלנו. והנה העסק שבו התעסקו אינו מעלה ואינו מוריד, מבחינת מה שהקריבו לפני הי\"ת.","b":false},{"t":"שהרי גם קין היה יכול לבחור את מיטב הפירות מאדמתו ולהביאם לפני ה' בכל לבו. ומאידך, גם הבל יכול היה לבחור את הכחושות והחלשות שבצאנו, לצאת ידי חובת ההודאה והעבודה לה'. והכל תלוי בבחירתו של העובד.","b":false},{"t":"ותחילה למדנו שבכל מה שעוסקים, צריכים מיד לחשוב איך מוציאים מזה עבודת ה', לעשות רצונו יתברך על הצד היותר טוב, ולקרבה אליו בכל האפשרי, ואחר שבאים אל המסקנא הזו, עדיין יש לפנינו להתכונן ולהתבונן במעשינו, שיהיו קרובים אל השלמות כמה שאפשר, ע\"י שנעשה את הדברים בתכלית הרצון הלבבי האפשרי, ולא כלאחר יד, ובדרך הזדמן, כדי לפרוק את עול החיובים שעלינו לעשות.","b":false},{"t":"וההנהגות האלו אינם רק בעניני עבודת ה' כמו תפלה ולימוד תורה, או כשבא לקיים את מצוות הי\"ת. אלא בכל דרכיך דעהו (משלי ג, ו), גם באכילתו גם בעבודתו, וגם בצאתו לסדר עניניו בעיר ובשדה, וגם בלכתו בדרכו ובשבתו בביתו, ובכל אשר יעשה, יכין לבו לעשותם על הצד הטוב ביותר שאפשר. כדי להשיג נעימות לה' ע\"י קיום רצונו ושמירת מִצְוָתוֹ. וכל מה שיעשה, תהיה העשיה היותר טובה ורצויה לפניו יתברך, ובזה זוכה לרצון מאתו יתברך שיתקבלו מעשיו ותפלתו לפני ה' ברצון, וישעה לתפלתו.","b":false},{"t":"וחז\"ל תקנו תפלה מיוחדת לזה, והיא:","b":false},{"t":"רְצֵה ה' אֱלֹהֵינוּ בְּעַמְּךָ יִשְׂרָאֵל וְלִתְפִלָּתָם שְׁעֵה, וְהָשֵׁב אֶת הָעֲבוֹדָה לִדְבִיר בֵּיתֶךָ, וְאִשֵּׁי יִשְׂרָאֵל, וּתְפִלָּתָם, מְהֵרָה בְּאַהֲבָה תְקַבֵּל בְּרָצוֹן, וּתְהִי לְרָצוֹן תָּמִיד עֲבוֹדַת יִשְׂרָאֵל עַמֶּךָ.","b":false},{"t":"כלומר, שאנו מבקשים מהי\"ת שיפיק רצון מעבודתינו, וישעה לתפלותינו ויקבל ברחמים וברצון את קיום מצוותיו, שנזכה לקיימן כדין וכהלכה.","b":false},{"t":"כי אם אדם מתפלל ולבו בל עמו, או טרוד מחמת עניניו הפרטיים, ולכן אינו מכוין כהוגן, א\"כ אינו כמקריב מ\"חלבי צאנו\" אלא הוא כמקריב בהמה חלשה ובעלת מום ח\"ו.","b":false},{"t":"וכן אם אדם לומד תורה בלא חשק ובלא להתייגע בה בכל כחו, הרי זה כמקריב מן הפחות שבפירותיו ומן הכחוש שבעדרי צאנו, ולא זו היא העבודה הרצויה לפני הי\"ת.","b":false},{"t":"וידון האדם קל וחומר בעצמו, שהרי אפילו כשהוא בא לפני בשר ודם, וחפץ לומר לו דבר מה, הריהו משתדל לומר את הדברים בצורה הכי ברורה והכי מובנת, כדי שחברו יבין את דבריו. ובפרט אם הוא צריך לחבירו, הרי הוא אומד ומודד את דבריו, ומשתדל להביא את דבריו ולאומרם בדרך המקובלת על אותו אדם, לפי השקפתו והבנתו. וק\"ו אם מדובר בשר ונגיד, שהוא מכין את דבריו מראש, ולומד את הענין היטב היטב, ומשנן את בקשתו כמה וכמה פעמים על הצד היותר טוב כדי לדעת באיזה אופן יבא לפניו, ואיך יפיק מהשר רצון וישיג את מבוקשו, אבל אם יביא את בקשתו בלי הכנה מוקדמת, ולא ישתדל כראוי, הרי מראש הוא מכשיל את מבוקשו.","b":false},{"t":"אמור מעתה קל וחומר בן בנו של ק\"ו לפני המקום ברוך הוא, כמה אנו חייבים להתאמץ ולהשתדל בכל מאמצי נפשנו להשיג רצון מלפניו. וככל שירבה עמל ושימת לב להיטיב ולשפר תורתו ותפלתו, הרי זה מ\"חלביהן ומהפירות המובחרים\" אשר יעלו לרצון לפני ה'. ותתקבל תפלתו ותענה עתירתו, וגם תורתו וקיום מצותיו, יהיו לנועם לפני הי\"ת, ועי\"ז יושפע עליו שפע רב מהאורות השייכים לאותה מצוה, או לאותו מעשה. ונמצא שפרשה זו היא כמורה דרך איך וכיצד לעבוד ה' בכל דרכינו. חיים עד העולם. אמן.","b":false},{"t":"(נאמר בס\"ד בפני בני הישיבה בלוס אנג'לס - ג' מרחשון התשס\"ז)","b":false}]},{"id":"11","t":"על חובת ההשתדלות","p":[{"t":"בְּזֵעַת אַפֶּיךָ תֹּאכַל לֶחֶם עַד שׁוּבְךָ אֶל הָאֲדָמָה כִּי מִמֶּנָּה לֻקָּחְתָּ כִּי עָפָר אַתָּה וְאֶל עָפָר תָּשׁוּב: (ג, יט)","b":true},{"t":"כתב הרב כלי יקר, יש סמך מכאן לדברי הרופאים שאומרים שקודם אכילה צריך האדם לעסוק באיזו מלאכה המחממת את בעליה (וראה בדברי הרמב\"ם בריש פ\"ד מהלכות דעות), כי זה עוזר לעיכול, וכמ\"ש (תהלים קכח, ב), יגיע כפיך כי תאכל אשריך וטוב לך, וזה שאמר בעצבון תאכלנה כל ימי חייך, כי עצבון הוא לשון מלאכה וכו'.","b":false},{"t":"ורש\"י ז\"ל כתב בזיעת אפיך, לאחר שתטריח בו הרבה. ע\"כ. ובפשוטו הכונה היא, שהאדם צריך לעשות השתדלות בעבודה או במסחר כדי להשיג את פרנסתו.","b":false},{"t":"ועידן ועידנים הייתי חוקר בהשתדלות זו שהיא הכרחית כדי לזכות בברכת ה', ומאידך צריך להאמין בה' שהוא הזן והוא המפרנס, ומשביע לכל חי רצון, ואליו עינינו נשואות שיטריפנו לחם חוקינו. וברוך הגבר אשר יבטח בה'. וא\"כ היכן הוא הגבול שבין ההשתדלות והעשיה, ובין החובה לבטוח בה', דאם בוטחים בו שהוא ימציא לנו כל צרכינו, למה נשתדל ונטרח, ומה פשר הענין.","b":false},{"t":"עד שמצאתי במסילת ישרים לרבינו הקדוש רמח\"ל ע\"ה. שכתב, (פכ\"א בדרכי קניית החסידות), שצריך להשתדל ולעשות, אך לא שההשתדלות הוא המועיל, אלא שהשתדלות מוכרח, וכיון שהשתדל הרי יצא ידי חובתו, וכבר יש מקום לברכת שמים שתשרה עליו ואינו צריך לבלות ימיו בחריצות והשתדלות, יעו\"ש.","b":false},{"t":"וביארתי בטעם הדבר דההשתדלות הכרחית, דהוא משום שהאדם התקלל מאתו יתברך באמור לו (בראשית ג, יט), בזיעת אפיך תאכל לחם, אבל לא שהזיעה היא המאכילה אותו לחם, אלא הי\"ת הוא שזן ברחמיו את הכל, ולא החריצות מרבה הון, כי אם, ברכת ה' היא תעשיר (משלי י, כב).","b":false},{"t":"ואשר ע\"כ אין להרבות ולדבוק בהשתדלות יתירה שאינה אלא קללה, וחושבים שהקללה היא עצם הטירחא שצריך לטרוח על הפרנסה להשיגה ואכן זה הוא הצד הקל שבקללה זו. והצד החמור שבה הוא שעל ידי שהוא משתדל ועמל על פרנסתו עד שמשיגה, הדבר מטעה אותו, והוא חושב שהשתדלותו וחריצותו היא המפרנסת אותו ומתרחק מהקב\"ה, ובטחונו נחלש ואמונתו מתרופפת.","b":false},{"t":"ועל האדם לדעת כי לא הריבוי בהשתדלות מרבה בפרנסה, כי ברכת ה' היא תעשיר. ואמר החכם מכל אדם בקהלת (ט, יא), לא לחכמים לחם, ולא לקלים המרוץ, ולא לגבורים המלחמה.","b":false},{"t":"ואכתוב בזה פירוש נורא של הקדוש רבינו משה אלשיך ע\"ה. על הפסוק בישעיה (א, ג) ידע שור קונהו וחמור אבוס בעליו, ישראל לא ידע, עמי לא התבונן. ופירש הרב ז\"ל, דהשור מכיר את קונהו, והחמור גם זה אינו יודע, והוא מכיר רק את ה\"אבוס\" שאוכל בו, אבל לא נאמר \"וחמור אבוסו\", אלא \"אבוס בעליו\", כלומר, שאפילו החמור יודע היטב ש\"האבוס\" אינו נותן אוכל מעצמו, אלא בעליו הוא שנותן אוכל ב\"אבוס\". וכשהחמור לא מוצא אוכל באבוסו הריהו נושא את עיניו לבעליו, כאומר לו הבא אוכל בבקשה. ואנחנו גם את זה לא תמיד יודעים. שכן, כל עבודה או מסחר אינם אלא \"אבוס\" בלבד, ולא הם המפרנסים, אלא הקב\"ה נותן לכל אחד פרנסתו תוך ה\"אבוס\" שלו. לאחד דרך מסחר, ולשני בעבודת רפואה, או בבנין ונגרות וכו'.","b":false},{"t":"אך כל זה אינו אלא \"אבוס\" ותו לא. ואם האדם תולה פרנסתו בעבודתו ובחריצותו, אז הוא משפיל את מדריגתו למטה ממדריגת השור והחמור, ועליו אמר הנביא, \"ישראל לא ידע\", וכי תשאל למה לא ידע, לזה משיב כי \"עמי לא התבונן\". והדברים נוראים למתבונן. ולה' הישועה ואליו עינינו נשואות תלויות, עד שיחננו (וראה עוד מה שנתבאר באורך להלן פרשת מקץ מאמר יג).","b":false}]},{"id":"11","t":"מדוע אחר חטא האדם לא הזכירה התורה שקיבל את עונש המיתה","p":[{"t":"וּלְאָדָם אָמַר כִּי שָׁמַעְתָּ לְקוֹל אִשְׁתֶּךָ וַתֹּאכַל מִן הָעֵץ אֲשֶׁר צִוִּיתִיךָ לֵאמֹר לֹא תֹאכַל מִמֶּנּוּ אֲרוּרָה הָאֲדָמָה בַּעֲבוּרֶךָ בְּעִצָּבוֹן תֹּאכֲלֶנָּה כֹּל יְמֵי חַיֶּיךָ, וְקוֹץ וְדַרְדַּר תַּצְמִיחַ לָךְ וְאָכַלְתָּ אֶת עֵשֶׂב הַשָּׂדֶה, בְּזֵעַת אַפֶּיךָ תֹּאכַל לֶחֶם עַד שׁוּבְךָ אֶל הָאֲדָמָה כִּי מִמֶּנָּה לֻקָּחְתָּ כִּי עָפָר אַתָּה וְאֶל עָפָר תָּשׁוּב: (ג, יז-יט)","b":true},{"t":"וקשה לי טובא דכשהזהיר הקב\"ה את האדם שלא יאכל מעץ הדעת אמר לו שאם יאכל יענש במיתה, כדכתיב ומעץ הדעת טוב ורע לא תאכל ממנו, כי ביום אכלך ממנו מות תמות (בראשית ב, יז), ולא הזכיר שום עונש אחר, וגם האשה אמרה כן לנחש, ומפרי העץ אשר בתוך הגן אמר אלהים לא תאכלו ממנו ולא תגעו בו פן תמותון (שם ג, ג). ואחר שאכלו אדם ואשתו מפרי העץ, ובא הקב\"ה להענישם, אנו רואים שהענישם בדברים אחרים, כמו שנאמר \"קוץ ודרדר תצמיח לך\" ושיצטרך האדם לעמול בזיעת אפים להביא את לחמו, ואילו עונש המיתה שהוא העונש העיקרי לא נזכר אלא ברמז, באמרו \"עד שובך אל האדמה\".","b":false},{"t":"ואחר החיפוש מצאתי להרמב\"ן ז\"ל לעיל (ב, יז), על הפסוק ביום אכלך ממנו מות תמות שכתב, וז\"ל, ועל דעת אנשי הטבע היה האדם מעותד למיתה מתחילת היצירה, מפני היותו מורכב (מד' יסודות), אבל גזר עתה שאם יחטא ימות בחטאו כדרך חייבי מיתה בידי שמים בעבירות, כגון זר האוכל תרומה (ויקרא כט, ט), ושתוי יין (שם י, ט), ומחוסר בגדים ששמשו (שמות כח, מג), וזולתם, שהכונה בהם שימותו בחטאם טרם בא יומם. ולכך אמר בעונש, \"עד שובך אל האדמה כי ממנה לוקחת כי עפר אתה ואל עפר תשוב\", בטבעך. וגם מתחילה היה אוכל מפרי העץ ומזרע הארץ, אם כן היתה בו התכה וסבת הויה והפסד. ועל דעת רבותינו (ראה שבת נה, ב) אלמלי שחטא לא מת לעולם, כי הנשמה העליונה נותנת לו חיים לעד, והחפץ האלהי אשר בו בעת היצירה יהיה דבק בו תמיד, והוא יקיים אותו לעד וכו', ודע כי אין ההרכבה מורה על ההפסד אלא לדעת קטני אמנה כי הבריאה היא בחיוב, אבל לדעת אנשי האמונה האומרים כי העולם מחודש בחפץ אלוהי פשוט, גם הקיום יהיה בו לעד כל ימי החפץ וזה אמת ברור.","b":false},{"t":"אם כן ביום אכלך ממנו מות תמות, שאז תהיה בן מות, כי האכילה היתה לו מתחילה לעונג, ויתכן שפירות גן עדן נבלעים באיברים כמן, ומקיימים את אוכליהם, וכאשר גזר עליו ואכלת את עשב השדה, ובזעת אפיו יאכל לחם האדמה, היה זה סיבה להפסד, כי עפר הוא, ועפר יאכל, ואל עפר ישוב. עכ\"ל.","b":false},{"t":"אלא דעדיין קשה, למה לא נזכר במפורש העונש העיקרי שנגזר על האדם, והיה לו לומר, ולאדם אמר כי שמעת לקול אשתך ותאכל מן העץ מות תמות. ואח\"כ יאמר, ארורה האדמה בעבורך וגו'.","b":false},{"t":"ואולי ניישב את זה ע\"פ דברי קדוש ה' הוא רבינו משה חיים לוצאטו ע\"ה בספר המאמרים (ראה מאמר העיקרים ומאמר הגאולה), שעמד במה שחקרו הראשונים ז\"ל בעונש המיתה שנתלה להם באכילת עץ הדעת ואם לא היו אוכלים ממנו לא היו מתים, (וכמ\"ש הרמב\"ן ז\"ל הנז'), ואם כן מה היא תכלית האדם, והרי אמרו חז\"ל (ראה עירובין כב, א וע\"ז ג, א ושם ד, ב), על הפסוק (דברים ז, יא), אשר אנכי מצוך היום, היום לעשותם ומחר לקבל שכרם, ואם יחיה האדם כאן לעולם מתי יקבל את שכרו האמיתי והנצחי, ומה תהיה מטרתו אם יחיה כאן בפרוזדור הזה לעולם, ולא יבא לטרקלין.","b":false},{"t":"והוא ז\"ל כתב דבאמת לפי טבע העולם, לאחר חיי האדם גופו צריך להתפרק מהרכבו ולשוב לעפרו. אלא שקודם החטא היה באדם כח אלהי שיכול לתת לו קיום לעד, וזאת בתנאי שיהיה עובד את הקב\"ה ודבק בו בכל כחו וחי לעולם. אבל אם ילך אחר הבלי עוה\"ז והנאותיו כטבע היסודות שמהם נוצר, אזי חלים עליו חוקות העוה\"ז שנקבעו על ידי יוצר העולם, כי כל דבר מורכב סופו להתפרק, וכל דבר סופו שישוב ליסודו הראשון, ורק ע\"י עבודת ה', האדם מקדש את עצמו עד שהופך את הגשמיות לרוחניות, ומגיע למצב מיוחד כמו אחר תחיית המתים. אבל אחר חטא עץ הדעת הפסיד האדם סגולה נפלאה זו, ושוב אינו יכול להפטר ממיתה ואפילו אם יקדש עצמו ביותר.","b":false},{"t":"עוד כתב רבינו הרמח\"ל בספרו דרך ה' (ח\"א פ\"ג), לבאר את ענין את תחית המתים, שהגוף עובר הזדככות ע\"י שמת ומתפרק מהרכבו ומתברר הדק היטב, ובינתים הנשמה נמצאת בעולם הנשמות ומקבלת את ההארות הראויות לה כפי עבודתה בעוה\"ז, ובעת התחיה היא שבה עם אורות גדולות ועצומים, ונכנסת לגוף שהזדכך ונטהר כ\"כ, ומאירה בו ומשפיעה בו שפע קדושה וטהרה, עד שגם הגשמיות שלו מתקדשת, (ואפשר שהוא כמו תוספת שבת ויו\"ט שמקדשים את החול), ומתעלה לדרגא של רוחניות וקם וחי לעולם ועד, ואילולי החטא של עץ הדעת, היה האדם יכול להגיע לזה בלא להזדקק למיתה. אלא חי על האדמה היה מתקדש וזוכה לחיות חיי נצח.","b":false},{"t":"ובזה י\"ל בעה\"ו, דהקב\"ה הזהיר את האדם שלא יאכל מעץ הדעת, ואמר לו כי ביום אכלך ממנו מות תמות. כלומר, שיפסיד בזה את הסגולה הנפלאה שניתנה בו, וממילא יהיה מוכרח למות ואין זה עונש, אלא מציאות. כי סגולה זו אינה יכולה להתקיים באדם אלא בהיותו פרוש מהבלי עוה\"ז ודבוק בה' ועבודתו בטהרה, אבל באוכלו מעץ הדעת טוב ורע, שמוליד באדם הרצון והחפץ שיבחרו אוכליו בדבר או בהיפוכו, לטוב או לרע (בראשית ב, ט), כי מעתה שהוא מסוגל לטוב ולרע. על כרחינו צריך לומר שע\"י האכילה מעץ הדעת, האדם נטע בעצמו מן הרע למינהו, ושוב אין אותה סגולת חיים יכולה להמשיך לשכון בקרבו, אלא עוזבתו מיד, והרי הוא בריה ככל הנבראים מבחינת גופו, וא\"א לו להשלים את תיקונו בלא שישוב לעפר.","b":false},{"t":"ועל כן כשאדם ואשתו אכלו מעץ הדעת לא אמר לו הי\"ת שימות עקב אותה אכילה, כי אין זה עונש, אלא נתן לו צער שאירר את האדמה בעבורו, ובזיעת אפו יאכל לחם וכו', וזאת על דבר עוזבו את מצות ה' שציוהו לבלתי אכול ממנו. עוד אמר לו \"ואכלת את עשב השדה\". כלומר, שמעתה האדם יהיה ככל הבריות המתקיימות מעשב השדה, והוא כל מהותו, ועל כן בעל כרחו ישיגוהו כל מגבלות הגוף, והוא אומרו \"עד שובך אל האדמה כי ממנה לוקחת\", כלומר, זהו יסודך וממנה נוצרת, ואין לך עוד דרך להנצל מן המות, כי במו ידיו הרחיק האדם מעצמו את סגולת החיים הנפלאה שניתנה לו ולא ידע לשמור עליה, וחזר להיות בן אדמה כשאר היצורים, ובעל כרחו ישוב לאדמתו.","b":false},{"t":"ובזה יובן מה שהקשו הקדמונים למה לא הועילה התשובה לאדם הראשון לבטל ממנו את עונש המיתה, והא אין לך דבר העומד בפני בעלי תשובה (ירושלמי פאה א, א זוהר ח\"ב קו, א ושם ח\"ג עו, א). והתשובה היא, כי ע\"י אותה אכילה נשתנה מהותו של האדם ונתערב בו הרע, ושוב אינו מסוגל ומוכשר שתשכון בו אותה סגולת חיים נפלאה, המרחיקה ממנו את חוקי הטבע וההפסד, וע\"כ אינו יכול לבא עד שלמות נפשו הראויה לו אלא אחר תהליך המיתה וההזדככות וכנ\"ל, ורק בתחיית המתים בב\"א, בשוב אליו נשמתו עם כל הארותיה הגדולים והגבוהים, אז יושלם ענינו ככל הראוי לו וחי לעולם.","b":false},{"t":"וידועים דברי רבותינו (שבת נה, ב), אמרו מלאכי השרת לפני הקדוש ברוך הוא, רבונו של עולם, מפני מה קנסת מיתה על אדם הראשון, אמר להם מצוה קלה צויתיו ועבר עליה. אמרו לו, והלא משה ואהרן שקיימו כל התורה כולה ומתו. אמר להם, מקרה אחד לצדיק ולרשע לטוב וגו'.","b":false},{"t":"וראיתי בספר כתם פז בשם הגה\"ק רבי יעקב אביחצירא זלל\"ה שהקשה ע\"ז, איך קורא לזה מצוה קלה, אחרי שנצטוו ע\"ז מפי הגבורה. ועוד הקשה למה שאלו על משה ואהרן דוקא. ויותר מכל קשה, מה מקום לשאלה העיקרית \"מפני מה קנסת מיתה על אדם\", זיל קרי בי רב הוא, כי הרי מפורש בתורה כל ענינו. וע\"ש מה שתירץ בזה בטוט\"ד.","b":false},{"t":"ולענ\"ד יש ליישב גם את זה ע\"פ האמור, דהגם דיודעים מלאכי השרת סיבת הדבר שהוא אכילת עץ הדעת טוב ורע, מ\"מ היו יודעים גם כן שאדה\"ר עשה תשובה, ואין דבר העומד בפני התשובה, ולכך שאלו את הקב\"ה כיון שאדם הראשון שב בתשובה שלימה א\"כ למה קנסת עליו מיתה. אמר להם הקב\"ה מצוה קלה ציויתיו, כלומר, נתתי לו סגולה נפלאה של חיים בקלות והיה לו לשמור עליה, והיא תשמרנו מכל הפסד ויחיה לעולם, אבל הוא לא שמר עליה, וע\"כ לא הועילה לו התשובה. שכבר נשתנתה מהותו בעצם אותה אכילה ופנים חדשות באו לכאן, ואין לו מנוס עוד מן העפר. אמרו לו, משה ואהרן מפני מה קנסת עליהם מיתה. כלומר, הרי משה ואהרן שהורידו את התורה לעולם, ובודאי ביטלו מעצמם את כל הנאות העוה\"ז, וכילו את כל רצונותיהם החומריים ופינו לבם מהבלי עולם, ויחדו את כל מהותם אליו יתברך דוקא, דבלא\"ה לא היו מסוגלים להביא תורה, דאין התורה נקנית אלא למי שממית עצמו עליה, (וראה מ\"ש בזה בפתיחה לשו\"ת שמע שלמה ח\"ב בעזהי\"ת), והרי הם ראויים לאותה סגולת חיים נפלאה. וע\"ז השיבם הקב\"ה שא\"א לחלק, אלא כל בני אדם שוים בזה משעה שנקבעה מהותו של אדם הראשון שעליו לשוב לעפר, כבר נקבע כן לכל יוצאי חלציו להשוותם בדבר זה. ודוק.","b":false},{"t":"(בעזהית\"ש. מוצש\"ק ואלה הדברים - ז' אב הרחמן התשס\"ז)","b":false}]},{"id":"11","t":"מלחמת היצר- מלחמה ללא הפסקה","p":[{"t":"וְאֵיבָה אָשִׁית בֵּינְךָ וּבֵין הָאִשָּׁה וּבֵין זַרְעֲךָ וּבֵין זַרְעָהּ הוּא יְשׁוּפְךָ רֹאשׁ וְאַתָּה תְּשׁוּפֶנּוּ עָקֵב: (ג, טו),","b":true},{"t":"ובתרגום אונקלוס תרגם בזה\"ל: הוא יהי דכיר לך מה דעבדת ליה מלקדמין, ואת תהי נטר ליה לסופא.","b":false},{"t":"וכנראה שכונת התרגום לומר, דהאיבה שתהיה בין הנחש לאדם, היא שהאדם זוכר מה שעשה לנו הנחש בתחילה, שעל ידו נקנסה מיתה על האדם \"וזהו הוא ישופך ראש\".","b":false},{"t":"ומה שנאמר \"ואתה תשופנו עקב\" תהי נטר לה לסופא, שהוא הנחש זוכר מה שיהיה בסופו, שהרי הנחש הוא היצה\"ר (כמבואר בזוהר בראשית לה, ב ועי' מורה נבוכים ח\"ב פרק ל' וראה בספורנו לבראשית ג, א ועי' פרקי דר\"א פי\"ג), ויודע שסופו להיות בטל לעתיד לבא, כמו שאמרו חז\"ל בסוכה (נב, א), שלעתיד לבא הקב\"ה שוחט ליצה\"ר, ואז הרשעה כולה כעשן תכלה לנצח, וידעו הכל כי ה' אחד ושמו אחד, ברוך הוא וברוך שמו.","b":false},{"t":"ומינה ידע האדם כי איבה ושנאה קיימת בין היצר הרע לאדם, ואעפ\"י שמראה פני אוהב, אינו אלא אויב ואורב, ובלבו ישים אורבו, ויעלים שנאתו וקנאתו, אשר כאש חמתו, שנאה מושרשת במהותו ועצמותו, מתחילת יצירתו, ויוכיחו מעשיו הראשונים, עם אדם הראשון ואשתו, אשר הראה להם פנים, כמו נושא ונותן עמם בעניני חכמה והשכל, ושואל להם, האם נכון שציוה לכם ה' לאמר, מכל עץ הגן וגו' ומעץ הדעת וגו'. ומענין לענין שלא באותו ענין, קפץ עליהם רוגזו, והצליח להכשילם, כי שינה את מראהו וצורתו ובא אליהם כידיד ואוהב, והם נחו ושקעו בים השקט והשלוה, עד שראו מה היה להם, אז הרגישו בתרמיתו, מאשר רימה אותם ושיחק בהם, והפכם כחומר בתוך ידו הגדולה, אשר מלאה ערמה ותחבולה.","b":false},{"t":"ועל כן אמרו חז\"ל ברוח קדשם (ברכות ה, א וזוהר בראשית רב, א), לעולם ירגיז אדם יצר הטוב על היצר הרע וכו'. ע\"ש.","b":false},{"t":"כלומר שעל האדם להיות כל הזמן במצב של נכונות למלחמה, ולא יתעצל מלנצח את יצרו בכל יום ויום וכאשר כתב בספר חובות הלבבות (שער יחוד המעשה פ\"ה, וכ\"ה בארחות צדיקים שער הגאוה), וזה לשונו הטהור בתוך דבריו, אמרו על חסיד, שפגע אנשים שבים ממלחמת אויבים, ושללו שלל אחר מלחמה חזקה, אמר להם, שבתם מן המלחמה הקטנה שוללים שלל, התעתדו למלחמה הגדולה. אמרו לו, ומה היא המלחמה הגדולה? אמר להם, מלחמת היצר וחייליו. ואל תתמה אחי, כי כל אויב שיש לך, כשתנצח אותו פעם ושתים, ירפה ממך ולא יעלה על לבו להלחם בך, לדעתו יתרון כחך על כחו, והוא מתיאש מלנצח אותך ומלגבור עליך. אבל היצר אין מספיק לו ממך נצוח פעם ומאה פעמים בין שנצח אותך, בין שנצחתו. כי אם ינצח אותך, ימיתך, ואם תנצחהו פעם אחת, יארב לך כל ימיך לנצח אותך, כמו שארז\"ל (אבות ב, ד), אל תאמין בעצמך עד יום מותך. ואינו מקיל בקטנה שבקטנות עניניך לנצח אותך בה, כדי שתהיה לו מדרגה לנצח אותך במה שלמעלה ממנה. ועל כן ראוי לך, שתהיה נזהר ממנו. ואל תמלא ממשאלותיו בך מאומה, רק יגדל בעיניך המעט שבמעט מנצוחו והמצער מהתגברותך עליו, כדי שתהיה לך מדרגה אל מה שלמעלה ממנו, כי במהרה תהיה תשוקתו אליך, ולא יעמוד לפניך בעמדך כנגדו, כמו שנאמר (בראשית ד, ז), ואליך תשוקתו ואתה תמשול בו. על כן אל יבהילך דברו, וגם אם עצמו חייליו, אל יפחידך ענינו, וגם אם רבו עוזריו, כי עיקר כונתו לאמת השקר ומגמת חפצו להעמיד הכזב. וכמה היא קרובה מפלתו ואיבודו מהר, אם תרגיש לחולשתו. ע\"כ.","b":false},{"t":"ולכן לא ישקוט האדם ולא ינוח, כי לא זה מקום המנוחה, אלא \"ושם ינוחו יגיעי כח\" (לעתיד לבא בחיי העוה\"ב), וכאן הוא מקום העשיה, וכל המרבה בעשיית תורה ומצוות, הרי זה משובח, ורק לא יתן לעצמו לשקוט על שמריו, כי יצר לב האדם רע מנעוריו, ללבו ימתיק אמריו, למושכו בכל כחו שילך אחריו. ועל כן צריך משנה זהירות, בענוה ולא ביהירות, ולא יסיר לבו מלימוד התורה, ולא יסיח דעתו מן הטהרה, ועל פי שנים אלה, יקום דבר ה' ויתקיים בידו, והוא ישלח דברו ויסייעהו, ועל דרכיו יזרח אור ה', וכבודו עליו יראה, וה' הטוב לא ימנע טוב להולכים בתמים.","b":false},{"t":"(מוצש\"ק בראשית התשמ\"ג)","b":false},{"t":"* * *","b":false},{"t":"ובתרגום יונתן ב\"ע איתא, ודבבו אישוי בינך ובין אתתא, בין זרעית בנך ובין זרעית בנהא, ויהי כד יהון בנהא דאתתא נטרין מצותא דאורייתא יהוין מכוונין ומחיין יתך על רישך. וכד שבקין מצוותא דאורייתא תהוי מתכוין ונכית יתהון בעקבהון, ברם להון יהא אסו ולך לא יהי אסו, ועתידין אינון למעבד שפיותא בעיקבא ביומי מלכא משיחא, ע\"כ. וזה פירושו, כשיהיו בני האשה שומרים מצות התורה, יהיו מכוונים ומכים אותם על ראשך, וכשעוזבין את מצות התורה תהיה אתה מכוין ונושך אותם בעקבם, אמנם להם תהיה רפואה, ולך לא תהיה רפואה, ועתידין הם לעשות שלום והשקט בעקבתא בימי מלך המשיח. ופירש בפירוש יונתן שם, שבימי המשיח יהיה שלום ומנוחה, כמאמר חז\"ל (ב\"ר כ, ה), שהכל מתרפאין, חוץ מן הנחש, ע\"כ. ונמצא דהכתוב מדבר על ימות המשיח.","b":false},{"t":"והרמב\"ן ז\"ל כתב, וטעם תשופנו עקב, שיהיה לאדם יתרון עליך באיבה, כי הוא ישופך ראש, ואתה לא תשופנו רק בעקבו, וירצץ מוחך, עכלה\"ק.","b":false},{"t":"ואולי לדברים הללו מכוונים דברי הפסוקים (תהלים פרק צא), יושב בסתר עליון כי אתה ה' מחסי עליון שמת מעונך לא תאונה אליך רעה ונגע לא יקרב באהלך וגו', על שחל ופתן תדרוך תרמוס כפיר ותנין וגו', ואראהו בישועתי. היינו אחר שידרכו בכח תורתם על \"שחל ופתן\", רק אז \"אראהו בישועתי\", היא הגאולה העתידה.","b":false}]},{"id":"11","t":"עבודת ה' – ללא תירוצים","p":[{"t":"בפרשה הראשונה שבתורה אנו קוראים ולומדים על בריאת העולם, ועל בריאת האדם נזר הבריאה כולה, וכל גדולתו והדרתו אשר גידלו והדרו הבורא ב\"ה מעל כל הברואים. וכן רואים בפרשה הזאת גם את חולשתו הרבה של האדם.","b":false},{"t":"גדולתו של האדם היא במה שהקב\"ה הניח אותו בגן עדן, ודיבר עמו כדבר איש אל רעהו, והשליט אותו על כל מה שברא בעולם, כאמור (בראשית א, כח), \"ורדו בדגת הים ובעוף השמים ובכל חיה הרומשת על הארץ\". והוא היה קובע את שמותם ומהלכם של כל הנבראים, כמו שנאמר (שם ב, יט), \"וכל אשר יקרא לו האדם נפש חיה הוא שמו\". ועוד כהנה מעלות רבות כאשר מבואר בפרשתינו.","b":false},{"t":"ובצד זה מיד מגלה התורה גם את חסרונותיו וחולשתו של האדם. בעוברו על הצו האלהי אשר צוהו ה' כאמור בפרשה (שם ב, יז), \"מעץ הדעת טוב ורע לא תאכל ממנו\", והוא צו יחיד שנאמר אליו, והוא עבר ואכל מעץ הדעת. מתוך תאוה שפלה.","b":false},{"t":"וטעם גדול יש בהזכרת ענינים אלו, שידע האדם ויִוָדַע ממעלותיו והשגותיו העצומות, שכמעט אינו מוגבל בתפישתו וביכולת השגתו, וכמו\"כ ידע ויתן אל לבו את חולשותיו וחסרונותיו, כדי שידע לנָוֶט את עצמו, בתוך המאבק הגדול והתמידי בו הוא נתון, כל ימיו עלי אדמות.","b":false},{"t":"כי יסוד החטא והכשלון הוא, בחולשת האדם נגד יצרו ותאוותיו, ובעצלותו ורשלנותו, ושאר המדות הרעות המוטבעות והמושרשות במהותו, ומקורן בעצם היסודות שמהם מורכב האדם, אש, רוח, מים, עפר, כידוע. אבל טבע לו לאדם שאינו מודה בחולשתו, ועל כן גם אם חטא ונשקע בעוונו עד צואר, הרי הוא מנסה בכל כחו להצדיק את עצמו ולתלות את האשם באחרים או בסיבות הזמן וקורותיו, וכן ע\"ז הדרך.","b":false},{"t":"ואם האדם הזה כל כך נכנע ליצרו עד שנהיה לו לעבד נרצע, והפקיר את עצמו ביד יצרו כחומר ביד היוצר, באופן שלא יספיקו לו עוד התירוצים הרגילים, אז הוא מתחכם ביותר, ומנסה להלביש את כל מעשיו תוך צורה של אידאולוגיה מתוחכמת, שכביכול האידיאה הזאת היא שמנחה אותו והיא שהביאתו עד הלום. ואז הוא ממשיך במרד ובמעל. ואף שלבו מלא חרטות, בכל זאת קשה לו מאד לשנות את מה שנהג והתרגל בו, ועוד יותר קשה לו להודות באשמו ובכשלונו.","b":false},{"t":"היו תקופות בהן השתמשו במטבע לשון ריקה מכל תוכן, האומרת, העיקר שיש לי לב טוב, ואני מטיב לבריות וכו', וכבר עמד ע\"ז הרב \"כתב סופר\" ז\"ל בפירושו לתורה בפרשת נצבים, על הפסוקים (דברים כט, יז-יח), פן יש בכם איש או אשה או משפחה או שבט אשר לבבו פונה היום מעם ה' אלהינו ללכת לעבוד את אלהי הגוים ההם פן יש בכם שורש פורה ראש ולענה, והיה בשמעו את דברי האלה הזאת והתברך בלבבו לאמור שלום יהיה לי כי בשרירות לבי אלך למען ספות הרוה את הצמאה. כלומר, שהאיש הזה טוען שיעשה כל מה שיחפוץ, וילך בשרירות לבו למען ספות הרוה את הצמאה, ועם כל זאת שלום יהיה לו ולא יאונה לו כל רע, ואימתי אמר זאת, אחר ששמע את כל דברי האלה הכתובה שם בפרשת בחוקותי, (צ\"ח קללות), וא\"כ על מה סומך השוטה הזה בשאננותו, אין זאת אלא שהוא סומך על לבו הטוב, והתברך \"בלבבו\" לאמר שלום יהיה לי. ע\"ש.","b":false},{"t":"סיסמא אחרת ריקה ושדופה מקודמתה אומרת \"אני לא מאמין\". ובמטבע פסול זה שכבר עבר עליו הכלח, מנסים לכסות על כל דבר פשע ועבירה, ועל רדיפת התאוות השפלות והפחותות ביותר.","b":false},{"t":"אבל המתבונן המחפש אחר האמת יודע את השקר והסילוף שבכל זה. כי אין יהודי בעולם שאינו מאמין, ואפילו הרחוק ביותר עדיין נשמת אלוה בקרבו, וכאשר יש בו הניצוץ הזה שהוא חלק אלוה ממעל איך לא יאמין. ועת צרה תוכיח, שבעתות כאל, מיד ישא היהודי תפילה לבוראו, ותקותו באמונתו נטועה עמוק עמוק, ומי יזיזנה ואפילו כמלא נימא. אלא שהכלל הוא כמאמר חז\"ל ברוח קדשם (סנהדרין סג, ב), בענין בעל פעור, יודעין היו ישראל בעבודה זרה שאין בה ממש, ולא עבדו עבודה זרה אלא להתיר להם עריות בפרהסיא. והרי כל יסוד ושורש הענין מונח כאן.","b":false},{"t":"הנה הם הלכו ועבדו ע\"ז, שזה השיא של הכפירה וחוסר אמונה, ואעפי\"כ חז\"ל ברוח קדשם גילו לנו שאין זה נכון שהם לא מאמינים בהי\"ת. אלא ודאי שהם מאמינים בה' וכופרים בע\"ז, ויודעים שכל ענין העבודה זרה הוא הבל ורעות רוח, ואע\"פ שאנו רואים שהם היו רצים לעבוד ע\"ז, ועבדו לה, והקריבו לה קרבנות (וגם את בניהם רח\"ל). בכל זאת מגלים לנו חז\"ל שכל זה הוא רק לבוש, שניסו להלביש לענין צורה פילוסופית, ולומר שאינם מאמינים בהי\"ת, ויכולים לטעון טענות ארוכות וגדולות, ולהרצות ע\"ז באורך וברוחב, וגם לכתוב ספרים וכו', אבל כל זה הוא פשוט שקר ולא אמת. והאמת היא \"חולשה\", חולשה שלהם נגד יצרם ותאותם, כי רצו להתיר לעצמם את העריות.","b":false},{"t":"חלשים היו מלהתגבר על יצר זה, ורצו להחזיק בהפקרות (עבדא בהפקרא ניחא ליה - גטין יג, א), אבל לא נעים ולא יפה לאיש המכבד עצמו, להאשים את עצמו בחולשה גדולה ושפלה כזאת, וחרפה היא לו, ועל כן מחפש הוא בוקי סריקי להתלות בהם ולכסות על בושתו וחרפתו. ומצהיר הצהרת שוא, לאמר, שאינו מאמין.","b":false},{"t":"וכאן בפרשתנו התורה מגלה בצורה פשוטה וישרה את החטא ומניעיו. כי הרי מדובר באדם הראשון וחוה אשתו, יצירי כפיו של הקב\"ה, ומקום מושבם היה בגן עדן ורוח ה' דיבר בם ומלאכים מהלכים ביניהם וכו', ובודאי שלא היה להם שום ספק באמונה ח\"ו, ולא תיתכן אפשרות שתהיה דומה למצב זה כלל ועיקר. והנה מצוה קלה ציוה להם הבורא ב\"ה (כמבואר במסכת שבת נה, ב), \"ומעץ הדעת טוב ורע לא תאכל ממנו כי ביום אכלך ממנו מות תמות\". והיא מצוה קלה בשמירתה, אבל חמורה מאין כמוה, אחר שנצטוו עליה מפי הגבורה, ובמיתה תלה להם את הדבר, ועברו עליה אחר פיתוי קל של הנחש, והסיבה מפורטת ומבוארת באר היטב בתורה.","b":false},{"t":"וַתֵּרֶא הָאִשָּׁה כִּי טוֹב הָעֵץ לְמַאֲכָל וְכִי תַאֲוָה הוּא לָעֵינַיִם וְנֶחְמָד הָעֵץ לְהַשְׂכִּיל וַתִּקַּח מִפִּרְיוֹ וַתֹּאכַל וַתִּתֵּן גַּם לְאִישָׁהּ עִמָּהּ וַיֹּאכַל: (בראשית ג, ו)","b":false},{"t":"טוב העץ, ותאוה לעינים, ונחמד וכו', זה הטעם וזו החולשה של האדם, לא חוסר אמונה ולא חוסר בטחון, ולא חוסר יכולת, ולא פילוסופיה ולא שום אידאולוגיה, כי אם תאוה שפלה, וחוסר רצון עז לכבוש את היצר, הוא שהביאם לחטא.","b":false},{"t":"* * *","b":false},{"t":"עוד יש לשים לב לטבע האדם, לתרץ את עצמו בכל מצב. וכבר בחטא הראשון התחילו התירוצים, במקום לעמוד על האמת ולהכיר בחטא, מיד החל למצא תירוצים (ושערי תשוב'ה לא ננעלו).","b":false},{"t":"כי הנה מצינו אחר החטא נאמר:","b":false},{"t":"וַיִּשְׁמְעוּ אֶת קוֹל ה' אֱלֹהִים מִתְהַלֵּךְ בַּגָּן לְרוּחַ הַיּוֹם וַיִּתְחַבֵּא הָאָדָם וְאִשְׁתּוֹ מִפְּנֵי ה' אֱלֹהִים בְּתוֹךְ עֵץ הַגָּן, וַיִּקְרָא ה' אֱלֹהִים אֶל הָאָדָם וַיֹּאמֶר לוֹ אַיֶּכָּה, וַיֹּאמֶר אֶת קֹלְךָ שָׁמַעְתִּי בַּגָּן וָאִירָא כִּי עֵירֹם אָנֹכִי וָאֵחָבֵא, וַיֹּאמֶר מִי הִגִּיד לְךָ כִּי עֵירֹם אָתָּה הֲמִן הָעֵץ אֲשֶׁר צִוִּיתִיךָ לְבִלְתִּי אֲכָל מִמֶּנּוּ אָכָלְתָּ, וַיֹּאמֶר הָאָדָם הָאִשָּׁה אֲשֶׁר נָתַתָּה עִמָּדִי הִוא נָתְנָה לִּי מִן הָעֵץ וָאֹכֵל, וַיֹּאמֶר ה' אֱלֹהִים לָאִשָּׁה מַה זֹּאת עָשִׂית וַתֹּאמֶר הָאִשָּׁה הַנָּחָשׁ הִשִּׁיאַנִי וָאֹכֵל: (בראשית ג, ח - יג)","b":false},{"t":"הנה האדם ואשתו נחבאו מפני ה'. ואז קרא הי\"ת אל האדם ואמר לו אַיֶּכָּה, ואדם השיבו אני מתבייש מפני קול ה' המהלך בגן כי אני ערום. מיד באה השאלה השניה, מה נשתנה הזמן הזה מהזמנים הקודמים, הרי קודם לא התביישת ומדוע עכשיו הנך מתבייש, שמא אכלת מעץ הדעת. ואז התחיל האדם בתירוציו, ואמר, רבש\"ע לא אני הוא זה שחטאתי אלא \"האשה אשר נתת עמדי נתנה לי מן העץ ואוכל\" (וכפר בטובתו של מקום, באמרו אתה נתת לי את האשה שהכשילתני, כמבואר במסכת עבודה זרה ה, ב), ואני אינני אשם. אז פנה ה' אל האשה ואמר לה, מה זאת עשית? ותאמר האשה \"הנחש השיאני ואוכל\". גם אני אינני אשמה, אלא הנחש אשם בכל. וכמובן ששלשתם באו על עונשם כמבואר בתורה ותירוציהם לא הועילו להם.","b":false},{"t":"ואמרתי משל למה הדבר דומה, למעשה באיש שהיה הולך ליד שדה בצלים, וישא עיניו וירא והנה לפניו שדה רחבת ידים, וגודלים בה בצלים רבים מאד, והם ירוקים ויפים, והעלים שלהם מתנועעים ברוח ומרהיבים כל עין. ועלה בדעתו ליכנס ולקחת מעט מהם. אך מיד דחה את הרעיון, וגער בעצמו איך חשב לגנוב. ואחר זמן התחיל לפלפל בענין, ואמר בלבו, יש לו לבעה\"ב הזה כל כך הרבה בצלים, כמה יכול לאכול, וכמה יכול למכור, והרי סוף סוף הרבה מהם יזרקו. ואמר לעצמו אני אקח רק מהפחותים שבהם, ומיד הורה היתר לעצמו ונכנס לשדה והתחיל לקטוף בצלים. וכיון שנכנס שכח את תנאו, והתחיל לבחור את הטובים והמעולים שבבצלים, והיה קוטף את הבצלים ומנערם מן העפר ושם בכיס התלוי לו מאחרי צוארו שהוא חלק מהג'אלאביה שלו. ואחר איזה זמן עבר שם בעל הבית, והוא רואה דבר נורא, איך אדם נכנס לשדהו וקוטף בנחת ובשלוה ושם בכליו, ומיד בראותו כן דהר על סוסו לקראת הגנב, וזה לא הרגיש עד שהגיע ממש קרוב אליו באופן שלא היה יכול לברוח, ומיד נשתטח מלא קומתו על הבצלים והתחיל להתגלגל. ובעה\"ב ניצב עליו וצועק בקול מר, חצוף וגנב! מיד עמד זה למולו וצעק נגדו, ואמר, אינך מתבייש לקרוא לי גנב. ואפילו לא שאלת מה היה לי. וזה השיבו, הרי עצם כניסתך לשדה שאינו שלך היא עברה חמורה. אמר לו, אדוני אני לא נכנסתי, אלא הייתי הולך בצד השדה ופתאום באה רוח סערה ודחפתני והפילתני, והלא בעיניך ראית איך הייתי מתגלגל. אמר לו בעה\"ב, תירצת את כניסתך, ומה תאמר על קטיפת הבצלים, אמר לו אני לא קטפתי את הבצלים, רק הייתי אוחז בהם שלא להתגלגל, אלא שהרוח היתה חזקה יותר והמשיכה לגלגלני ואז נעקרו. ואז שאלו בעל הבית, א\"כ איך נכנסו הבצלים לתוך הכיס הזה, השיבו הגנב, על זה בדיוק אני חושב כעת, ועדיין לא מצאתי תירוץ.","b":false},{"t":"זהו הדפוס של העבירות ושורשם.","b":false},{"t":"* * *","b":false},{"t":"וראה דבר נפלא מאד בפרשת יתרו אחר מתן תורה, שבה הראה הקב\"ה ישתבח שמו לעם ישראל, (את אשר ישנו ואת אשר איננו), כי אין בלתו ואפס זולתו, ואחרי שראו ישראל את המעמד הנשגב בקולות וברקים ולפידים ואת קול השופר השמימי ואת ההר עשן, נבהלו מאד ואמרו למשה:","b":false},{"t":"דַּבֵּר אַתָּה עִמָּנוּ וְנִשְׁמָעָה וְאַל יְדַבֵּר עִמָּנוּ אֱלֹהִים פֶּן נָמוּת: (שמות כ, טו)","b":false},{"t":"ומהי תשובתו של משה אליהם:","b":false},{"t":"וַיֹּאמֶר מֹשֶׁה אֶל הָעָם אַל תִּירָאוּ כִּי לְבַעֲבוּר נַסּוֹת אֶתְכֶם בָּא הָאֱלֹהִים וּבַעֲבוּר תִּהְיֶה יִרְאָתוֹ עַל פְּנֵיכֶם לְבִלְתִּי תֶחֱטָאוּ: (שם שם, טז)","b":false},{"t":"ותשובתו של משה אל העם מפליאה, באמרו להם שכל המעמד הנפלא שהם ראו, וכל האותות והמופתים היו כדי ל\"נסותם\". והדבר מפליא ומתמיה, איזה נסיון הוא זה? והלא עתה אחר שראו את כל המעמד הנורא של הר סיני, כלום יש מקום עוד לשאלות, והלא כמעט נתבטל מהם כח הבחירה החופשית, בראותם מופתים חותכים וברורים על אמיתותו יתברך, הלזה יקרא נסיון.","b":false},{"t":"ובאמת שרש\"י ז\"ל (שם), הוציא את המקרא מדי פשוטו, וכתב, לבעבור נסות אתכם, לגדל אתכם בעולם שיצא לכם שם באומות שהוא בכבודו נגלה עליכם, נסות, לשון הרמה וגדולה כמו הרימו נס וכו'. ע\"ש.","b":false},{"t":"אבל הרמב\"ן ז\"ל (שם), דחה את פירש\"י בזה, והאריך בדבר, וכתב בשם רבנו הרמב\"ם ז\"ל בספר מורה נבוכים (ח\"ג פרק כד), שזה נסיון ממש, אלא שהנסיון הוא לעתיד, אם יבא נביא שקר שירצה לסתור מה ששמעתם לא תמעד אשורכם לעולם מדרך האמת, כי כבר ראיתם את האמת בעיניכם, ואם כן יאמר בעבור שיוכל לנסות אתכם לעתיד בא האלהים עתה, כדי שתהיו עומדים לו בכל נסיון. והרמב\"ן ז\"ל כתב, ועל דעתי הוא \"נסיון ממש\", יאמר, הנה רצה האלהים לנסותכם התשמרו מצוותיו, כי הוציא מלבכם כל ספק, ומעתה יראה הישכם אוהבים אותו ואם תחפצו ובמצוותיו וכו'. ע\"ש.","b":false},{"t":"ועל פי דברינו נאמר אף אנו, שזה גופא הנסיון, שיש האומרים שמפני חולשת האמונה ורוב הספקות נחלשים בעבודת ה'. וכאן הוציא מלבם כל ספק, ואמר להם, עתה אחר שראיתם את כל הנפלאות נראה איך תעבדו את ה'. כי הנה במלחמת היצר העיקר תלוי בהתחזקות והתגברות, אשר באה לאדם ע\"י התבוננות בדרכיו, וכל שאר הדברים הם תירוצים ריקים אין בם מועיל.","b":false},{"t":"וכבר אמרו חכמי המוסר, שאין האדם מתחיל בעבודת ה', עד שיפסיק לתרץ תירוצים.","b":false},{"t":"(מהשיחות שאמרתי בס\"ד בפני תלמידי הישיבה הגדולה בתורה והוראה. ת\"א. התש\"ם)","b":false}]},{"id":"11","t":"הקב\"ה הטביע באיש את החשק לעזוב את בית הוריו","p":[{"t":"עַל כֵּן יַעֲזָב אִישׁ אֶת אָבִיו וְאֶת אִמּוֹ וְדָבַק בְּאִשְׁתּוֹ וְהָיוּ לְבָשָׂר אֶחָד: (ב, כד)","b":true},{"t":"כתב רבנו עובדיה ספורנו ז\"ל, וז\"ל, ראוי שישתדל האדם לישא אשה הוגנת לו, וראויה לידבק בו, גם שיצטרך לעזוב את אביו ואת אמו, כי לא יהיה דבוק אמיתי בבלתי דומים, אבל יהיה בדומים בלבד, כי אז יכונו לדעת אחד. עכ\"ל.","b":false},{"t":"ונראה דהקב\"ה הטביע בברואיו מדה זו, שבעת שיגיע האדם לפרקו, מתפתח בקרבו רצון עז לעזוב את בית אביו ואמו. וכן הוא בתרגום, על כן ישבוק גבר בית משכבי אבוהי ואִמֵה. ונעשה לו צר ומציק להמשיך לחיות בבית אביו ואמו, ומחפש להניחם, וע\"י זה מחפש לו בת זוג לגור עמה ולבנות ביתו.","b":false},{"t":"דאם לא כן, לא היה מסכים לעולם לעזוב את תפנוקי בית אביו ואמו, המספקים לו מזון ודיור בחום ובאהבה רבה, והוא יושב אתם לבטח, ואין לו דאגה ואין עליו עול כלל, ולמה זה יעזוב מקום מבטחים בו מפנקים אותו ואוהבים אותו לאין שיעור ובלי שום תנאי, וילך להכניס עצמו במשא בית ומשפחה, ויהיו ריחים על צוארו יומם ולילה לא ישבותו אך הקב\"ה לא רצה שיהא העולם נחרב, כי האדם ישב בטל מפריה ורביה, ולא יהיה קיום לעולם, ולא תהו בראה אלא שבת יצרה (ישעיה מה, יח).","b":false},{"t":"ע\"כ הטביע הקב\"ה באיש מדה זו, בבא עתו עת דודים, שירצה לעזוב את בית אביו ואמו, ומכח הרצון הזה, מתפתח בלבו הרצון לבנות בית עם אשתו.","b":false},{"t":"ואמר על כן יעזוב איש, ולא הזכיר האשה בענין זה, ואפשר דיש צורך בזה רק לאיש ולא לאשה, משום שהאשה גם בנעוריה בבית אביה, היא עובדת ומסייעת להוריה ואחיה, ובלבה פנימה היא מצפה לבנות ביתה, ולהיות עצמאית בעבודת ביתה, ובמקום לשרת תחת שרביט אמה ושאר בני המשפחה, היא תהיה שרה לעצמה, ולכן אינה צריכה דחף מיוחד כדי לבא לידי רצון לבנות בית משלה. ומה גם שעול הבית והפרנסה אינו מוטל על שכמה, אלא על הבעל.","b":false},{"t":"אבל האיש בהיותו בבית אביו ואמו, טבעו להתפנק ולהתרווח וכל היוצא מפיו עושים לו, ואין מי שיאמר לו מה תעשה, וכל העולה על רוחו הוא עושה באין מפריע ואין מכביד, ועלול לומר מה לי להקים בית ולהשתעבד לאשה ולילדים, למזונותיהם ושאר צרכיהם, וידחה את הדבר מיום ליום ומפקידה לפקידה, וישב בדד וידום.","b":false},{"t":"ע\"כ הקדים הקב\"ה רפואה למכה זו, ונתן בלבו תכונה מיוחדת, שבבא הזמן אינו יכול עוד לשבת בבית הוריו, ומתעורר בו הרצון לקום ולעזוב את ביתו, ועל כן יעזוב איש את אביו ואת אמו, ודבק באשתו.","b":false},{"t":"ואם לא ימאס אדם בבית אביו, גם לעת בה ישא אשה, לא יהיה הדבק טוב, כי תמיד תהיה דעתו על בית אביו ואמו, וישאף לשורשו ואל שער מקומו. אבל עתה שהוא מואס בבית אביו ואמו, זה מסייעו שיהיה הדבק ביניהם יציב ובר קיימא.","b":false},{"t":"וזה הוא \"ודבק באשתו\", כי ע\"י עזיבת אביו ואמו, יהיו הדבקות והיישוב שלו טובים ויציבים עם אשתו, דהא בהא תליא.","b":false},{"t":"[א\"ה - עוד נראה לומר, טעם למה הקב\"ה טבע באיש את החשק לעזוב את בית אביו יותר מן האשה, משום דהלכה ידועה היא לרוב מנין ורוב בנין הפוסקים, דרק האיש מצווה על פריה ורביה ולא האשה (טוש\"ע אהע\"ז סי' א סעיף יג), לכך טבע הקב\"ה את החשק באיש דווקא, יבח\"ר].","b":false}]},{"id":"11","t":"כח מעשיו הגיד לעמו","p":[{"t":"בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ: (א, א)","b":true},{"t":"כתב רש\"י ז\"ל, בראשית, אמר רבי יצחק לא היה צריך להתחיל את התורה אלא מהחודש הזה לכם (שמות יב, ב), שהיא מצוה ראשונה שנצטוו בה ישראל, ומה טעם פתח בבראשית משום (תהלים קיא, ו), כח מעשיו הגיד לעמו לתת להם נחלת גוים. שאם יאמרו אומות העולם לישראל, ליסטים אתם! שכבשתם ארצות שבעה גוים. הם אומרים להם, כל הארץ של הקב\"ה היא! הוא בראה ונתנה לאשר ישר בעיניו. ברצונו נתנה להם וברצונו נטלה מהם ונתנה לנו, עכ\"ל.","b":false},{"t":"והרמב\"ן ז\"ל הביא דברי רש\"י אלו, וכתב, זו אגדה שכתבה רבינו שלמה בפירושו, ויש לשאול בה, כי צורך גדול הוא להתחיל התורה בבראשית ברא אלהים, כי הוא שורש האמונה, ושאינו מאמין בזה וחושב שהעולם קדמון, הוא כופר בעיקר ואין לו תורה כלל. והתשובה, מפני שמעשה בראשית סוד עמוק אינו מובן מן המקראות, ולא יוודע על בוריו אלא מפי הקבלה עד משה רבינו מפי הגבורה, ויודעיו חייבין להסתיר אותו, לכך אמר רבי יצחק שאין להתחלת התורה צורך בבראשית ברא, והסיפור במה שנברא ביום ראשון ומה נעשה ביום שני ושאר הימים, והאריכות ביצירת אדם וחוה, וחטאם וענשם, וסיפור גן עדן וגירוש האדם ממנו, כי כל זה לא יובן בינה שלימה מן הכתובים, וכל שכן סיפור דור המבול והפלגה, שאין הצורך בהם גדול, ויספיק לאנשי התורה בלעדי הכתובים האלה, ויאמינו בכלל בנזכר להם בעשרת הדברות (שמות כ, יא), כי ששת ימים עשה ה' את השמים ואת הארץ את הים ואת כל אשר בם וינח ביום השביעי, ותשאר הידיעה ליחידים שבהם הלכה למשה מסיני עם התורה שבעל פה וכו', ע\"ש באורך ובעומק.","b":false},{"t":"והנה דבר ברור דכל מה שכתב רש\"י ז\"ל בשם רבי יצחק, הוא רק נתינת טעם על הקדמת הפסוקים הראשונים, המזכירים שהקב\"ה ברא שמים וארץ, שזה מראה על כח מעשיו, ונותן טעם להשיב לטוענים עלינו \"ליסטים אתם\". ואנו משיבים להם, כל הארץ של הקב\"ה, כי הוא בראה, והוא נתנה לאשר ישר בעיניו. ברצונו נתנה להם, וברצונו נטלה מהם ונתנה לנו.","b":false},{"t":"ואמנם לא בא רש\"י ז\"ל לתת טעם להקדמת כל ספר בראשית על שאר הספרים. כי לא רק הפסוקים בראשית וכו' נאמרו בתחילה, אלא כל ספר בראשית ותחילת ספר שמות, כל אלו קדמו לפסוק \"החדש הזה לכם\".","b":false},{"t":"ובודאי שלא בכדי האריכה התורה הקדושה במעשה בריאת האדם יציר כפיו של הקב\"ה, ואח\"כ בהשתלשלות הדורות עד אברהם אבינו ע\"ה, ומשם הרחיבה התורה הקדושה באר היטב את כל תולדות האבות ומעשיהם, המה ובניהם, ואפילו משיחת עבדי אבות לא חסכה התורה הקדושה פסוקים ופרקים. עד שאמרו חז\"ל (ב\"ר ס, ח), יפה שיחתן של עבדי אבות מתורתן של בנים.","b":false},{"t":"ומאחר וגם מעשה בראשית ויצירת כל היצורים נחקק בתורה, בודאי שהדברים חשובים כגופי תורה, וצריכים לימוד ועיון, בהתבוננות הראויה, כדי ללמוד ולהבין ולהשכיל, ולשמור ולעשות, וכל זה הוא בבחינת \"דרך ארץ שקדמה לתורה\" (ויק\"ר ט, ג תנדא\"ר א וילקו\"ש עה\"ת רמז לד), מפני שלימוד זה הוא הכלי הנחוץ לאדם כדי שיוכל לקבל תורה, ויהיה מסוגל להשיגה ולקלוט מלקחיה אל נפשו פנימה.","b":false},{"t":"כי מצוות התורה וחוקיה ומשפטיה, אינם נקלטים אלא למי שמכין את נפשו לשומעם ולקבלם בהכנעה גמורה, ואז יתקיים בו שמעו ותחי נפשכם (ישעיה נה, ג).","b":false},{"t":"ואם ילמד האדם את מצות התורה בלא הכנת הנפש הראויה, כדי להכניע דעתו בפני דעת התוה\"ק ולקבל את כל דבריה, לא יועיל לו לימודו מאומה. ועוד יכולה ליהפך לו לסם המות ח\"ו (כמבואר ביומא עב, ב ותענית ז, א), כי ישרים דרכי ה', צדיקים ילכו בם ופושעים יכשלו בם (הושע יד, י), והוא לא הכין את לבו ונפשו כראוי.","b":false},{"t":"ואולי זה הוא הסוד במה שהקדימו ישראל נעשה לנשמע (שמות כד, ז), שאמר הקב\"ה (שבת פח, א), מי גילה רז זה לבני. כי כאשר האדם מכין לבו כראוי, הריהו יכול להשיג את מצוות התורה גם בלי שישמע. וכמו שאמרו חז\"ל, שהאבות הקדושים קיימו כל מצות התורה. ואעפ\"י שלא קיבלוה. כי הכינו את עצמם בהכנה דרב'ה, עד שכליותיהם נעשו כשתי כדים מלאים מים והיו נובעות תורה ונעשות להם כשני רבנים ויועצות אותם ומלמדות אותם תורה עד שנעשו כמעין המתגבר (ב\"ר סא, א ושם צה, ג, ותנחומא ויגש פי\"א וילקו\"ש בראשית רמז ק\"ט ותהלים רמז תרי\"ד).","b":false},{"t":"ואולי זה מה שנאמר בדברי חז\"ל בהגדה של פסח, \"אילו קרבנו לפני הר סיני, ולא נתן לנו את התורה דיינו\". ולכאורה קשה מאד, איך יתכן לומר \"דיינו\" בלא קבלת התורה, והלא כל עיקר העולם הוא בשביל התורה, ועיקר יציאת מצרים היתה בעבור התורה, כמו שנאמר (שמות ג, יב), בהוציאך את העם ממצרים תעבדון את האלהים על ההר הזה. ומה תועלת לנו בקירוב לפני הר סיני בלא שתנתן לנו התורה.","b":false},{"t":"אמנם התשובה לזה היא, כי \"קרבנו לפני הר סיני\", היא בחינה נפלאה של הכנה גדולה ועצומה לקבלת התורה, וע\"י ההכנה הזאת היו יכולים לזכות לתורה גם בלא מתן תורה, וכענין האבות הקדושים שאחר שהיתה להם הכנה דרב'ה זכו וכליותיהם נבעו תורה, ואף ישראל היו זוכים לזה ע\"י ההכנה ההיא, כי פסקה מהם זוהמת הנחש, וזהו, אלמלי קרבנו לפני הר סיני ולא נתן לנו את התורה \"דיינו\", שכן היא מעלה גדולה ועצומה ויש בה משום השגת התורה, והיא היא הבחינה של אבותינו הקדושים. ואמנם הי\"ת הגדיל חסדו על עמו ישראל, ועשה כאשר קבע בטרם הרים יולדו, לברוא את כל העולם בשביל התורה שנקראת ראשית דרכו, ובשביל ישראל שנקראו ראשית תבואתה (ראה פסחים נד, א ונדרים לט, ב וויק\"ר לו, ד). ונתן את התורה הקדושה לעמו ישראל.","b":false},{"t":"והמתבונן בספר בראשית שהיא ההקדמה שהקדים הקב\"ה לפני גופי המצוות, יראה שיש בזה בנין נפלא בנוי לתלפיות, סוף מעשה במחשבה תחילה, מיד הי\"ת להבינו ולהכיננו, שנהיה מוכשרים לקבל משפע חכמתו יתברך. והבנין הזה כולל קומות רבות, נדבך על גבי נדבך, בסדר מופלא. וכל מי שמתבונן היטב בספר בראשית ועניניו הנפלאים הריהו בונה לעצמו מבנה רוחני, ומקנה לעצמו את הכלים הראויים, כדי שיהיה מוכשר להשיג את התורה, הפותחת לפניו שערים מגבהים עליונים, ומשפיעה בו שפע עליון המגביהו ומרוממו על כל המעשים.","b":false},{"t":"ותחלה מלמדת אותנו תורה שלמרות כל היופי וההדר הנראה לעין, ברחבי העולם הזה, אין מזה תועלת אמיתית לאדם, ואל ישים האדם מגמתו לעניני העולם הזה ההווה וחולף, כי אם לחיי הנצח תהא מגמתו, כי רק בעולם הבא האדם זוכה לנצחיות נשמתו אשר נפח בו בוראו.","b":false},{"t":"ולזה צריך שמיעה והכנעה לצו האלהי, לדעת מה טפל ומה עיקר. צא וראה איך בעבור תאוה רגעית עבר האדם על מצוה אחת יחידה וקלה שניתנה לו, ולא שמר עליה. וסופו שהביא על עצמו אסון כמו שנאמר (בראשית ג, כג - כד), וישלחהו ה' אלהים מגן עדן, לעבוד את האדמה אשר לוקַח משם. ויגרש את האדם, וישכן מקדם לגן עדן את הכרובים, ואת להט החרב המתהפכת, לשמור את דרך החיים. וכל זה כדי למנוע את כניסתו של האדם לגן עדן.","b":false},{"t":"ומן העת ההיא אין האדם שרוי בגן עדן, ועליו לחיות בעולם הזה עולם ההבל, עולם חולף, ולעבוד עבודה תמידית באדמה אשר ממנה לוקח, כדי לקיים נפשו בזיעת אפו, ואליה ישוב בבוא היום, כי הרוח תשוב אל האלהים אשר נתנה, והגוף ישוב אל האדמה, ויהיה לעפר שהוא יסודו מראש ומעיקרא. ואילו אל גן עדן שהוא ענין \"חיי הנצח\" חיי עולם, תגיע רק הנשמה לבדה. והוא יסוד גדול בחיי האדם, שידע ויזכור תמיד שכל העולם הזה הוא חיי שעה, והוא רק פרוזדור, שממנו אפשר להכנס לטרקלין. וזאת רק אם ישכיל ויקנה את הטרקלין בתורה ועבודת ה' שעשה בפרוזדור, בהכינו את עצמו לטרקלין. כמאמרם ז\"ל (אבות ד, טז), העולם הזה דומה לפרוזדור בפני העולם הבא. התקן עצמך בפרוזדור, כדי שתכנס לטרקלין.","b":false},{"t":"עוד הראתה לנו התורה, כי עמים ולאומים גדולים וחזקים, כולם חולפים ונעלמים, והיו כלא היו. כי אין עמם תורה ועבודת ה', ובשביל התורה נברא העולם, ואין העולם מתקיים אלא ע\"י התורה, כמו שנאמר (ירמיה לג, כה), אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. והתורה נבראה לפני בריאת העולם תתקע\"ד דורות (ראה זבחים קטז, א ותנדא\"ר פ\"ו ופי\"ג ופכ\"ו), וכשעלה ברצונו יתברך לברוא את עולמו, היה מסתכל בתורה ובורא את העולם, כמאמרם (זוהר ח\"ב קסא, א), קודשא בריך הוא אסתכל באורייתא וברא עלמא [תרגום: שהי\"ת הסתכל בתורה הקדושה וברא על פיה את העולם, וכשראה בתורה יהי אור, ברא את האור, ע\"ש], שלא כמו שחושבים שאחר שברא הי\"ת את העולמות ויצר את האדם וכו', אז התאים לו תורה לפי ענינו, כדרך בני אדם שבונים מערכת חוקים ומשפטים ותקנות לפי צורך הצבור, הזמן, והמקום. ועל זה נאמר (ישעיה נה, ח), כי לא מחשבותי מחשבותיכם ולא דרכיכם דרכי נאם ה'. והוא ישתבח שמו הקדים וברא את התורה שהיא מדעו שלו, והסתכל בה, ולפי הוראותיה ומצוותיה, יצק וקבע את תכונות העולם ומזגיו, לכל עניניו.","b":false},{"t":"וצייר את העולם הזה שהוא הבל וריק שאין בו ממש, והוא \"עולם השקר\", שהכל נראה בו קבוע וקיים, אך באמת אין בו שום דבר שאינו בר חלוף, וגם האדם עובר וחולף, ורוח עברה בו ואיננו, ולא יכירנו עוד מקומו. וכנגד כל זה אמר שלמה המלך בריש קהלת שבעה פעמים \"הבל\", שההביל את כל עניני העולם הזה. לבד הנשמה חלק אלוה ממעל שהיא חיה וקיימת לנצח.","b":false},{"t":"אך בתוך ההבל הזה יש מציאות אחת שאינה חולפת לעד, ואי אפשר להשיגה אלא כאן בעולם הזה בלבד, והיא התורה והמצות אשר לעד קיימים, וגם האוחזים בהם והולכים בדרך הזאת, מתקיימים גם הם, והיינו דכתיב (משלי ג, יח), עץ חיים היא למחזיקים בה וגו'. כי היא מקור חיינו, ונותנת חיים למחזיקים בה, והוא שאומרים בתפלה, \"כי הם חיינו ואורך ימינו\", וכתיב (ויקרא יח, ה ויחזקאל פרק כ' בכמה מקומות), \"וחי בהם\". ותנן באבות (ו, ז ומסכת כלה פ\"ח), \"גדולה תורה שהיא נותנת חיים לעושיה בעולם הזה ובעולם הבא\". ואת כל זה אנו רואים בדורות הרבים שעברו בעולם, אשר מפני שלא היו קשורים בתורה ועבודת ה' ברוך הוא, לא היה להם קיום, וכמו שאמרו באבות (ה, ב), עשרה דורות מאדם עד נח, להודיע כמה ארך אפים לפניו, שכל הדורות היו מכעיסים ובאים עד שהביא עליהם את מי המבול. עשרה דורות מנח ועד אברהם, להודיע כמה ארך אפים לפניו, שכל הדורות היו מכעיסים ובאים עד שבא אברהם אבינו וקבל עליו שכר כולם. וכן הוא בכל הדורות, אלפים אלפים עוברים וחולפים, וישראל הקדושים האוחזים בתורה ובמצוות נוטלים שכר כנגד כולם. ואין לו להקב\"ה בעולמו אלא התורה ומקיימיה. להודיע ולהוודע שאין לנו שיור אלא התורה הזאת, והיא מקור חיינו, והיא תכלית החיים כולם ומטרתם, ועל כן לא ניטוש חיי עולם מפני חיי שעה. ונדע מה עיקר ומה טפל, ואל מה צריכים לשים את מגמתנו, כדי לנצל לטוב ומועיל את החיים הניתנים לנו מאתו יתברך.","b":false},{"t":"ואחרי כל זה, הגיעה התורה להודיענו את קורות האבות הקדושים, וסיפרה לנו באורך וברוחב, את כל נסיונותיהם ומעשיהם, וגילתה לנו על החסדים והצדקות שעשו, ועל תוקף גבורתם ומסירות נפשם למען שמו באהבה, ומאמיתות דרכם ונקיות מחשבתם לפני המקום ב\"ה. והאריכה התורה בפרטות אמונתם ובטחונם בהי\"ת, ויושר דרכם עם הבריות, והתיחסותם אל העוה\"ז וטובותיו, ואשר כל ימיהם, ורוב ככל עמלם, הוא לעבוד את ה', ולקרב את לב הבריות ליראתו ואהבתו, עד שהגיעו לרום המעלות והקב\"ה נגלה עליהם, וכרת עמהם ברית עולם, אשר לא תמחה ולא תשכח ולא תמוש מזרעם וזרע זרעם עד עולם.","b":false},{"t":"ומכל מעשיהם אנו לומדים לדעת מה יתרון לאדם בכל עמלו בעוה\"ז, ומה זוכה בלכתו אחר עמל התורה ועבודת ה'. כי זה כל האדם.","b":false},{"t":"ועיקר הלימוד ממעשי אבותינו הקדושים הן המה המדות הטובות, אהבת הבריות, ואהבת חסד, ענוה, וסבלנות, רחמנות, וביישנות, צניעות, וחיפוש אחר האמת ללא פשרות. ואעפ\"י שאין קשה יותר מאשר ללמוד מדות טובות, והעולם אומרים שיותר קל ללמוד כל הש\"ס כולו מלתקן מדה אחת. והזקנים היו רגילים לומר, שנוי הצבע ולא שנוי הטבע.","b":false},{"t":"אבל מ\"מ כשאנו לומדים ומתבוננים במעשיהם והנהגותיהם של אבותינו הקדושים, אנחנו מושפעים מהם להלכה ולמעשה, והטעם הוא פשוט, דאנחנו בני בניהם, ויש בנפשנו מנפשם, ודמנו הוא דמם, ושורשי מדותיהם נמצאים ומושרשים עמוק בנפשנו פנימה, ואמרו חכמינו ז\"ל (ב\"ר נג, טו ושם פו, ו), זרוק חוטרא לאוירא אעיקרא קאי. ועוד אמרו, כי בשלשה דברים ניכרים ישראל, בישנים, רחמנים, גומלי חסדים (ראה יבמות עט, א וירושלמי קדושין פ\"ד הלכה א במדב\"ר ח, ד), והם ממדותיהם של אבותינו הקדושים, ונמצאות אצל כל אחד ואחד מזרע ישראל בלי יוצא מן הכלל.","b":false},{"t":"והרב הגאון מהר\"א שרים זצ\"ל ראש ישיבת תורה והוראה בת\"א ת\"ו, היה רגיל לומר אם תראה יהודי שאינו גומל חסדים, הריהו בעל מום, כי חסרון דבר זה אצל יהודי כמוהו כחסרון איבר.","b":false},{"t":"ומאחר ויש בתוכנו עמוק עמוק פנימה מן המדות הנפלאות של אבותינו הק', ממילא כשלומדים ומתבוננים, תיכף נדלק אותו ניצוץ פנימי ומאיר לכל האדם כולו, ומעט מעט מתרגל להתנהג בדרכי אבות ראשונים.","b":false},{"t":"וזה הוא הבסיס החזק ביותר לקבלה פנימית של התורה באהבה וברצון, והוא הנותן את המסוגלות להכשיר ולהפוך את האדם הגשמי להיותו רוחני יותר, עד שיהיה ראוי והגון לקנות את קניני התורה, ולחפוץ יותר ויותר בקרבת ה' ברוך הוא.","b":false},{"t":"ועוד יש מעלה גדולה מאד בלימוד מעשי אבותינו, וסיפור חייהם, שיש בזה משום \"שמוש\" בעבודת ה', בבחינת \"שאל אביך ויגדך זקניך ויאמרו לך\" (דברים לב, ז), שלא בכדי אמרו בגמרא (ברכות ז, ב וכ\"ה בתנדא\"ר פ\"ה), \"גדולה שמושה יותר מלמודה\". וע\"י למוד זה בדרכי אבותינו הקדושים, מתעורר לב האדם, לפקוח עיני לבו ללמוד ממוריו ורבותיו, ומזקני הדור יתבונן ויתכונן בעבודת ה'.","b":false},{"t":"ואי אפשר לאדם להשלים תפישתו בתורה, ובתפילה ובקיום המצות, בלא שיראה בעיניו כיצד מקיימים ומתבצעים דברים אלו בפועל. וגם הבנת האדם והשגתו ברוחניות לא תושלם לעולם, כי אם בהביטו אל חכמי הדור וזקניו, ללמוד מהם ולצפות על מעשיהם בעינא פקיחא, כדי לקלוט את הרוח החיה שבפנימיות הדברים. וככל שירבה להביט ולשים לבו, כן תרבה חכמתו וירבה קנינו הרוחני האמיתי.","b":false},{"t":"ושורש כל הענינים האלו הם האבות, דמכללם באים התולדות, וצריכים לראות שתהיינה תוצאותיהם כיוצא בהם.","b":false},{"t":"ואז נפקחים עיניו, ולבו מתבונן, ואזניו מתחילות לשמוע ולהאזין אל הקולות הפנימיים, ואז זוכה לסגולות התורה, וכשיתמיד בה עם ההכנות האלו, ושב ורפא לו.","b":false},{"t":"וככל שנרבה להתבונן נראה את חשיבות ונחיצות הקדמת ספר בראשית למצות התורה, שהוא הכרחי ביותר, ובלעדיו לא יוכל אדם להגיע להיות עובד ה'.","b":false},{"t":"ואם בכל המצות כך, הרי במצוות העיוניות, על אחת כמה וכמה, שאנו זקוקים למעשה האבות, כמו מצות אהבת ה', ומצות יראת ה', וכן יסודי האמונה והבטחון בה'. אשר באלו והדומה להם, לא יועיל לימוד בעל פה כלל, וצריך האדם לראות בעינים ולשמוע באזנים, עד שמתעוררת בלבו אהבת ה' ויראתו, ומתעלה מיום ליום, ואז תורתו תורת אמת, ויראתו יראה פנימית.","b":false},{"t":"ובזה פירשתי את הענין שאמרו בגמרא (קדושין נז, א בבא קמא מא, ב), תניא, שמעון העמסוני ואמרי לה נחמיה העמסוני היה דורש כל אתין שבתורה, כיון שהגיע לאת ה' אלהיך תירא (דברים ו, יג ושם י, כ), פירש. אמרו לו תלמידיו, רבי! כל אתין שדרשת מה תהא עליהם? אמר להם, כשם שקבלתי שכר על הדרישה כך אקבל על הפרישה. עד שבא רבי עקיבא ולימד, את ה' אלהיך תירא, \"את\" לרבות תלמידי חכמים.","b":false},{"t":"והנה ר\"ש או ר\"נ העמסוני היו יראים לרבות שום דבר שבעולם לפני ה' ברוך הוא, ואפילו ת\"ח נמי, כי מה ישוה לה' ברוך הוא. ולכן פירשו משיטתם זו לדרוש כל את ואת שנאמר בתורה, דהואיל וכאן לא היו יכולים לדרוש, חדלו משיטתם לגמרי. דאם תיבת \"את\" באה לרבות, א\"כ גם בפסוק \"את ה' אלהיך תירא\" צריך לרבות. וכיון דסברו ש\"את\" זה לא אתא לרבות, ממילא גם בשאר אֵתִין שבתורה אין לדרוש שבאו לרבות.","b":false},{"t":"אבל רבי עקיבא שהיה כחו גדול, בא ואמר, שגם \"את\" זה בא לרבות, ומה הריבוי? שצריך לירא מת\"ח. וכן נמי ואהבת את ה', לרבות שיש מצוה לאהוב ת\"ח (עי' בסיום למציעא למהרי\"ל פ\"ב הנדפס בסוף חידושי פנ\"י למציעא).","b":false},{"t":"והיה קשה לי ע\"ז, מה ראתה תורה ללמדנו את מצות אהבת החכמים ויראתם, מתוך דוחק וצער כזה, ע\"י כתיבת תיבת \"את\" בין הדבקים בתוך הפסוקים של יראה ואהבת הי\"ת. וכי חסרים מקומות בתורה לצוות אותנו על אהבת תלמידי חכמים ויראתם. עד שהוצרכה התורה לשים את הענין הזה במקום נורא שאפילו התנאים הגדולים ר\"ש ור\"נ העמסוני היו יראים לדרוש דרשה זו, עד שפרשו והניחו את שיטתם וחדלו ממנה לגמרי.","b":false},{"t":"וביארתי בס\"ד, דרבי עקיבא רוח אחרת עמו בדרשה זו, דר\"ש ור\"נ העמסוני, הבינו דקרא ד\"את ה' אלהיך תירא\" בא לרבות עוד במצות היראה, שיש עוד דבר שצריך להתיירא ממנו. ומזה נחרדו ופירשו לגמרי.","b":false},{"t":"אבל רבי עקיבא היה מפרש \"את\" ה' אלהיך תירא. דבא לרבות את הדרך האמצעית, שעל ידה יוכל האדם להגיע ליראת ה'. שכן, קשה איך התורה מצוה לנו אנו בני האדם קרוצים מחומר עכור, עפר מן האדמה, ואין לנו שום השגה באלהות, ואיך נגיע לאהבת ה' ויראתו, והרי צריך איזה סולם לעלות בו במעלות של קדושה עד שנגיע לרמה גבוהה זו, להשיג את אהבת ה' ויראתו.","b":false},{"t":"ועל זה בא רבי עקיבא ולימד, \"את\" לרבות תלמידי חכמים, כי הסולם הנכון שהעולה בו יגיע ליראה ולאהבה את ה' הגדול והנורא. הוא על ידי שמרגיל בלבו אהבת החכם ויראתו, בהערכה של אמת, ומזה תבא בלבו אהבה ויראה להי\"ת. כי עם הזמן תבא מחשבה בלבו לאמר, על מה אני אוהב חכם זה כל כך, ועל מה אני ירא ממנו, והרי הוא אדם כמוני. ואז הוא משיב אל לבו ואומר, תראה כמה תורה למד, וכמה עמל ויגיעה השקיע בה, ואיך הוא עבד נרצע לפני קונו וכו' וכו'. ומזה ידון קל וחומר בנפשו, ומה חכם זה שהוא רק אחד מעבדי הי\"ת ואני נכנע בפניו ומתיירא ממנו ואוהבו בלב ונפש, הי\"ת על אחת כמה וכמה, ומה אענה ומה אומר בשיעור שראוי לי להגביר אהבת הי\"ת ויראתו.","b":false},{"t":"ואשר ע\"כ הקדימה התורה את ספר בראשית לכל המצוות. וכן בתחילת ספר שמות התוה\"ק מספרת לנו כל הקורות את אבותינו בשעבוד מצרים הנורא, וכמו כן מספרת לנו מענין הנסים והנפלאות שעשה להם הי\"ת, אשר מהם לומדים על השגחת ה' פרטית בקרב הארץ. ורק אחר כל זה באו מצוות ה' עלינו לקדשנו בקדושתו ולהטיב לנו בזה ובבא.","b":false},{"t":"והנה רש\"י הביא בתחילת דבריו את דברי רבי יצחק, ובדבריו נתן נתינת טעם רק למעשה בראשית למה הוא נזכר בתחילת התורה. אמנם שומה עלינו לחקור ולדרוש עוד ככל אשר תשיג ידינו, ולכן כתבתי בזה מעט מזעיר מאשר מצאה ידי כדי לחזק עצמנו, ואידך זיל גמור.","b":false},{"t":"ואגב אנו למדים דברים נפלאים על דברי רבותינו שבאגדות, כי לפעמים נדמה לנו שהוא בבחינת דרוש וקבל שכר ותו לא. אך לא כן הוא. כי הן הן גופי תורה ויסודות חיינו.","b":false},{"t":"והנה דורות רבים לא יכלו להבין מה הוא הצורך הגדול בדברי רבי יצחק, שהתורה הקדושה צריכה לכתוב מעשה בראשית בכדי שאם יאמרו לנו העמים ליסטים אתם, נשיב להם כח מעשיו וכו'. והיה הדבר קשה בעיניהם, וכי מי מן הגוים יבא לדבר עמנו על זה בהיותינו בגלות. ועוד, מה תשובה אנו נותנים להם, שלכך הקדימה תורה ללמד שה' הוא הבורא שמים וארץ, והוא אשר נתן את הארץ לאשר ישר בעיניו, והוא נטלה מהם ונתנה לנו. וכי מה איכפת לעכו\"ם שכך כתבה התורה שה' נתן לישראל את ארץ ישראל. וגם היה קשה בעיניהם, שהרי העכו\"ם יאמרו מה אתם מביאים ראיה מן תורה שלכם וכו'.","b":false},{"t":"והנה בדורנו זה, עדים אנו ועד העולם כולו, כי מעל כל במה צבורית בכל העולם, נשמעת כנגד עם ישראל הטענה של \"ליסטים אתם\" שגזלתם את הארץ וכו'. וניסו אנשים מתוכינו לומר בפני האומות את כל התירוצים, ועוד הוסיפו לומר, שהעם הזה נע ונד אלפים שנות גלות, ונרדף עד צואר בגזירות ובהסתות איומות ונוראות, עד אחרון הגדיל \"השואה האיומה\", ולכן עלינו לקבל ארץ משלנו. אמנם כל זה אינו מתקבל על לב האומות, וממשיכים בטענתם \"ליסטים אתם\".","b":false},{"t":"ואז עולה במלא הדרה תשובת רבי יצחק ז\"ל שהקב\"ה ברא שמים וארץ, ונתן את הארץ. למי שרצה, והוא נטלה מהם ונתנה לנו\", כי הפה שאסר הוא הפה שהתיר, ומי יאמר לו מה תעשה ומי יאמר לו מה תפעל. ברוך הוא לעד, ברוך אומר ועושה.","b":false},{"t":"ודיברתי עם רבים שאינם בני ברית מגדולי האומות, ולא מצאתי מי שאינו מוקיר ומעריך את התורה, כי היא חכמתכם ובינתכם לעיני כל העמים. וכיון שכולם מקדישים ומעריצים את התורה, וכולם יודעים כי הי\"ת בחר בישראל לעמו ולחבל נחלתו, ע\"כ דוקא תשובתו של רבי יצחק היא היחידה המוצאת מקום בליבם של אומות העולם. כח מעשיו הגיד לעמו. ישתבח שמו לעד.","b":false}]},{"id":"11","t":"זיווגו של האדם משמים בלבד","p":[{"t":"וַיֹּאמֶר ה' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ: (ב, יח)","b":true},{"t":"הנה הפסוק הזה הוא הקדמה מיוחדת, שיחד הי\"ת מאמר מיוחד על ענין בריאת האשה, שיש לעשות עבור האדם, ונאמר בפסוק הזה שם הוי'ה ושם אלהים יחדיו. וצריכם להבין טעם ההקדמה הזאת, והרי היה מספיק במה שנאמר, ויפל ה' אלהים תרדמה על האדם וגו' (בראשית ב, כא ואילך), שהפסוקים מתארים בפרטות את בריאת האשה, וא\"כ מה צורך לנו בנתינת טעם לא טוב היות האדם לבדו וגו'.","b":false},{"t":"ונראה שכל הענין הזה בא ללמדנו, כי כל ענין זיווג איש ואשה נתון ביד הי\"ת ולא ביד שום אדם, כי רק הוא ית' לבדו, אשר יצר ועשה את האדם, הוא לבדו יכול להכין לו את זיווגו הראוי לו, ועל כן לא יתלה האדם בחכמתו ובכשרונותיו, שהוא לבדו יכול לחפש ולמצא את זיווגו. וכבר אמר החכם מכל אדם (משלי ג, ה), ואל בינתך אל תשען, ועל זאת יתפלל כל חסיד אליך לעת מצא (תהלים לב, ו). ואמרו רבותינו (ברכות ח, א), \"לעת מצא\" זו אשה, שנאמר (משלי יח, כב), מצא אשה מצא טוב וגו', והיינו כי צריך הרבה תפלה אל הי\"ת שיזכה לבת זוג ישרה וכשרה.","b":false},{"t":"כי רק התפלה והבטחון יעזרו לו, לקרב ישועתו, והסומך על חכמתו בזה, ידע! כי אין חכם שיכול לדעת איזו אשה תתאים לו למשך שנים רבות כל כך, ומי זאת שתוכל ללדת לו ילדים, ושיעמיד ממנה דור ישרים, ושיהיו ריעים אהובים זל\"ז, וכל זאת אין בכח אנוש להבין כלל וכלל. כי הוא מעשה האלהים לבדו. ומה' אשה לאיש (משלי יט, ד ועי' מו\"ק יח, ב). ועל כן אמר כאן, \"ויאמר ה' אלהים\", שהיא מדת רחמים שנוהג עם בריותיו, ורוצה בטובתם, והוא יודע את צרכי האדם, וקבע, שלא טוב היות האדם לבדו, ועל כן אמר אעשה לו עזר כנגדו.","b":false},{"t":"ובזה ישבתי את הקושיא המפורסמת, דפסוק אחד אומר (משלי יח, כב), מצא אשה מצא טוב ויפק רצון מה'. ופסוק אחר אומר (קהלת ז, כו), ומוצא אני מר ממות את האשה. ורבות דובר בה בקושיא זו (כמבואר בברכות ח, א ויבמות סג, ב וראה מה שנתבאר במאמר הקודם).","b":false},{"t":"ועפ\"י הדברים הללו יובן היטב, דאם אינו תולה בעצמו ובחכמתו, עליו נאמר, מצא אשה מצא טוב, כלומר שהוא רואה את זה כ\"מציאה\" ולא כהשגה שהשיג מעצמו, אלא סומך על הקב\"ה שהוא הממציא לו את זיווגו, ואינו מחשיב עצמו לראוי או מסוגל להשיג דבר זה, וע\"כ \"מצא טוב\" ויפק רצון מה', משום שאמר שמהשם יצא הדבר, ועל כן יפק רצון וימצא טוב.","b":false},{"t":"אבל זה שאומר אני חכם, ויודע לבדוק לבדי, והנני בקיא בענינים ואני אחפש, ואני אמצא, זה הוא, \"ומוצא אני\", כי הוא מכניס את ה\"אני\" שלו באמצע ונשען אל בינתו, ובוטח בחכמתו, ומסיר בטחונו מה' ברוך הוא. וזה \"מר ממות\" רח\"ל.","b":false},{"t":"ולכן על האדם לנהוג בתמימות בכל עניני הזיווג ולבקש ולהתחנן הרבה אל הי\"ת שיזמין זיווגים טובים ומאושרים לו וליוצאי חלציו. והולך בתום ילך בטח (משלי י, ט). ותכלית החכמה, לדעת שאין אנו יודעים, וככל שאדם משפיל עצמו ומבטל את תוקפו וגבורתו, ובוטח בה' לבדו, כן יעלה ויצליח, והלוך ילך ויגדל, ועלהו לא יבול, וכל אשר יעשה יצליח, והיה כעץ שתול על פלגי מים.","b":false}]},{"id":"11","t":"זיווגו השלם של האדם בגוף ונשמה תלוי במעשיו","p":[{"t":"וַיֹּאמֶר ה' אֱלֹהִים לֹא טוֹב הֱיוֹת הָאָדָם לְבַדּוֹ אֶעֱשֶׂה לּוֹ עֵזֶר כְּנֶגְדּוֹ: (ב, יח)","b":true},{"t":"ורבותינו אמרו (יבמות סג, א וב\"ר יז, ג), מאי דכתיב אעשה לו עזר כנגדו, זכה, עוזרתו! לא זכה, כנגדו!, ע\"כ. נמצינו למדים דהכל תלוי במעשיו של האדם, אם הוא מתנהג כשורה ויש לו זכות, הרי אשתו תהא לעזר לו, ואם אין מעשיו מתוקנים חלילה, אשתו נגדו.","b":false},{"t":"ברם מצינו בריש מסכת סוטה (ב, א), כשהיה ריש לקיש פותח בלימודו במסכת סוטה, היה אומר, אין מזווגין לו לאדם אלא לפי מעשיו, דהיינו, שאם הוא צדיק גם אשתו תהא צדקת, ולא רעה ורשעה ח\"ו, והביא ראיה ממה שנאמר (תהלים קכה, ג), כי לא ינוח שבט הרשע על גורל הצדיקים. ועל זה הוקשה להם בגמרא שם, מדברי רב יהודה בשם רב שאמר, ארבעים יום קודם יצירת הולד, בת קול יוצאת ואומרת, \"בת פלוני לפלוני\", והיינו, שאז עדיין לא ידוע מה יהיו מעשיו כי הרי הכל תלוי בבחירתו, ובכל זאת כבר בעת ההיא מחליטים בשמים על זיווגו, וזה דלא כריש לקיש. וע\"ז משיב בגמרא, לא קשיא! הא בזיווג ראשון הא בזיווג שני. והיינו שבזיווג ראשון אפשר שתפול רשעה בחלקו של צדיק או להיפך, אבל בזיווג שני הכל לפי מעשיו של אדם, ואם הוא צדיק לא תפול אשה רעה בחלקו ח\"ו.","b":false},{"t":"אמנם יש להקשות דתירוץ חז\"ל נסתר מדברי הגמרא שהבאנו בתחילת דברינו, \"זכה עזר לא זכה כנגדו\", כיון שהפסוק אעשה לו עזר כנגדו נאמר באדם וחוה יצירי כפיו של הקב\"ה, והיה זה זיווג ראשון, וא\"כ יוצא כי גם בזיווג הראשון של האדם, הכל לפי מעשיו.","b":false},{"t":"ויש ליישב את הדברים לפי מה שכתב הקדוש רבינו מהר\"ם אלשיך זיע\"א (בפירושו המופלא לתהלים פרק מה, ובפירושו למשלי לא, י), כי מה שאמרו בגמ' ריש סוטה \"הא בזיווג ראשון הא בזיווג שני\", שניהם בזיווג ראשון ממש. אלא שהזיווג הראשון הוא זיווג הנשמות אשר הקב\"ה מזווג שתי נשמות, אחת בחינת זכר ואחת בחינת נקבה, וזה הוא \"ארבעים יום לפני יצירת הולד\", כי אז אין שום גוף עדיין, והנשמות הללו נמצאות בעולם הבריאה, והקב\"ה מזווגם זו לזו, ובזה לא שייך עדיין מעשה של זיווג הגשמי, כי הרי אין כאן גוף ואין כאן שום מעשה.","b":false},{"t":"והזיווג שני הוא זיווגי הגופות, אחרי שנוצרו ובאו לכלל מעשים, ומגיעים לפרקם, אז הקב\"ה מזווגם יחד, אך זיווג זה הוא לפי מעשיהם, כי לא ינוח שבט הרשע על גורל הצדיקים.","b":false},{"t":"ויש מקור לדבריו אלו מספר הזהר הקדוש בכמה מקומות (ראה זוהר ח\"א רכט, א ושם פה, ב ושם צא, ב וראה גם בח\"ג מג, ב ושם רפג, ב), יעו\"ש.","b":false},{"t":"ובזה ישב רבינו מהר\"ם אלשיך את הקושיא המפורסמת, דפסוק אחד אומר (משלי יח, כב), מצא אשה מצא טוב ויפק רצון מה'. ופסוק אחר אומר (קהלת ז, כו), ומוצא אני מר ממות את האשה. ורבות דובר בה בקושיא זו (כמבואר בברכות ח, א ויבמות סג, ב).","b":false},{"t":"והוא ז\"ל מישבה עפ\"י האמור, דכאשר זוכה האדם ע\"י מעשיו הטובים ונותנים לו את האשה שכבר היתה לו בזיווג הראשון שהוא זיווג הנשמות, אזי הוא בא אל השלמות, וכל ימיו יהיו על מי מנוחות. וזה שאמר הפסוק, \"מצא אשה מצא טוב\", כלומר, מצא את האשה אשר זיווגו לו כבר בשמים, שע\"ז בא על נכון לשון \"מצא\", ואז מצא טוב. ויפק רצון מה'.","b":false},{"t":"אבל מי שקלקל את מעשיו, ואיבד את זיווגו שזיוגו לו מן השמים. הרי שמעתה הוא צריך לטרוח ולחפש לעצמו בת זוג אחרת, ולזה כיוון הפסוק באומרו, \"ומוצא אני\", שכיון שהפסיד את הזיווג שניתן לו מבורא העולם ומנהיגו, מעתה צריך שהוא יחפש אחריה, והוא ימצא לעצמו מן הבא לידו, ומשום זה הוא מר ממות רח\"ל. וע\"כ אמר, \"ומוצא אני\", כלומר, כיון שאיבד את מה שנתנו לו מן השמים, מעתה הרי הוא צריך לחפש בעצמו ולמצוא, וזה שהוא צריך למצא לעצמו הוא רע ומר רח\"ל. א\"כ נמצא כי זיווג ראשון הוא כשנושא את אותה אשה שזיווגו לו בעולם הנשמות. וזיווג שני הוא כשאיבד את אותו זיווג וצריך למצא לו אחרת. ושפתים יושק.","b":false},{"t":"[א\"ה - ויש להביא ראיה מפורשת לדברי רבינו מהר\"ם אלשיך ז\"ל מההיא דמועד קטן (יח, ב), דקאמר שמואל מותר לארס אשה בחולו של מועד שמא יקדמנו אחר, ומקשה בגמ' והא שמואל גופיה אמר, דכל יום יוצאת בת קול ואומרת בת פלוני לפלוני. ומשני, שמא יקדמנו אחר ברחמים. ע\"ש. והנה לא מצינו שיאמר דבר זה רק על זיווג שני, דהא שמואל לא חילק מאומה, ובכל מקרה התיר לארס אשה, ושמע מינה דאדם יכול לאבד את זיווג נשמתו שנקצב לו מן השמים. ובזכרוני שראיתי להגאון מהרי\"י קנייבסקי ז\"ל במכתב, דג\"כ כתב שאדם יכול לאבד את בחינת זיווגו הראשון. יבח\"ר].","b":false},{"t":"ועפי\"ז נבא לפרש את הפסוק הנזכר בתחילת דברינו ויאמר ה' אלהים לא טוב היות האדם לבדו, אעשה לו עזר כנגדו. היינו, שהקב\"ה ישתבח שמו, מכריז ואומר, אני הוא שבראתי ויצרתי ועשיתי את האדם, ויודע מה הם תכונותיו ומזגיו, ואני קובע שלא טוב היות האדם לבדו. ועל כן בראתי לו \"עזר\", אני ולא אחר, כי מה' אשה לאיש (משלי יט, יד ומו\"ק יח, ב), ואין מי שיכול לעשות זה זולתו יתברך (ראה ויק\"ר ח, א ובמדב\"ר ג, ו בעובדא דההיא מטרוניתא), ואכן הקב\"ה מזווג הזיווגים בעולם הנשמות, ארבעים יום לפני יצירת הולד, וזה הזיווג האמיתי והנכון, אלא שאח\"כ הריהו נותן את הדבר ביד האדם עצמו, שהרי הבחירה בידו, ואם מעשיו נכונים זוכה לזיווג ההוא העליון, ומתקיים בו, מצא טוב ויפק רצון מה', והוא אומרו \"עזר\" שעוזרתו. כי זוכה שנמשך לו העזר שהקב\"ה העמיד לו מתחילה.","b":false},{"t":"ואם קלקל האדם את מעשיו רח\"ל עד שגרם לאבד את זיווגו אשר ניתן לו מאת ה', מעתה הרי הוא צריך לחפש לעצמו, בבחינת ומוצא אני, ואזי הוא \"כנגדו\", והוא מר ממות, וכדרכו של האלשיך הקדוש זיע\"א.","b":false},{"t":"נמצא דפסוק זה קאי אכולהו אינשי, וגם על אדם וחוה, שכן בכל זיווג וזיווג של כל אדם, יש בו שני זיווגים זיווג הנשמות, וזיווג הגופות, והשלמות והעזר האמיתי היא רק בהתחבר שני הזיווגים יחד, זיווג גוף ונשמה. ונמצא א\"כ שכדי לזכות לזיווג המושלם של גוף ונשמה, הרי זה תלוי במעשים שלו. וזה שאמרו, \"זכה עזר\", היינו שמקבל את אותו זיווג שבו זכה קודם היצירה. \"לא זכה כנגדו\", היינו שאם קלקל מעשיו וגרם רעה לעצמו לאבד את זיווגו ולחפש לו זיווג אחר הרי זה \"כנגדו\" רח\"ל. ודברי הגמ' אינם סותרים.","b":false},{"t":"ואולי יש לפרש עוד את דברי רבותינו, דלעולם זיווגו של אדם הוא לפי מעשיו ואפילו זיווג ראשון, ומה שנאמר אעשה לו עזר כנגדו, זכה \"עזר\", לא זכה \"כנגדו\". הכי קאמר, זכה שה' רצה להטיב לו, אזי תהיה האשה \"עזר\" בעדו. ואם לא זכה, היינו שנגזר עליו לסבול יסורים אזי תהיה אשתו \"כנגדו\". ובזה א\"ש הכל.","b":false},{"t":"* * *","b":false},{"t":"שינוי הטבעים שבין איש ואשתו הם הגורמים את החיבור והשלימות","b":true},{"t":"ובדרך הפשט יש לפרש, \"אעשה לו עזר כנגדו\", דהיינו שיעשה לו אשה שתתאים לו בחכמה ותבונה והשכל, ובמזג נאה ויאה, ורצונות שאינם רחוקים וכו', עד שישלימו זה את זה, והיו לאחדים מאוחדים, ותיבת \"כנגדו\" פירושה \"לעומתו\", כלומר, שתהא האשה שקולה כנגדו ומתאימה לו, ובזה תהיה לו לעזר.","b":false},{"t":"ובאמת שראיתי לרבינו עובדיה ספורנו ז\"ל שפירש בדרך כזו, ודבריו בזה עמוקים ונפלאים, עיין עליו. והוסיף וכתב, אמנם לא ראוי שיהיה העזר שוה לו לגמרי, כי אז לא יהיה ראוי שיעבוד וישרת אחד מהם לחברו. עכ\"ל. ואולי זה רמוז במאמר חז\"ל (יבמות סג, א), חות דרגא וסיב איתתא, והיינו שתהא האשה שונה מן הבעל במעט. והיא חכמה נאצלה.","b":false},{"t":"ושמעתי מזה שנים רבות מאד מהרה\"ג רבי מסעוד ריוח זללה\"ה (הרב דעי\"ת שלומי), שהראב\"ע ז\"ל בפירושו הקצר (בראשית ב, יח), כתב, עזר כנגדו, שע\"י שטבע האשה מנוגד לטבעו של האיש, בזה נעשית לו לעזר. כלומר שאם האופי והמזג שלהם שוים זל\"ז, לא יוכלו להסתדר ולחיות יחד, דרך משל שניהם רתחנים, או שניהם אדישים וקרים, לא יהיו לעזר זל\"ז, אבל כאשר מדותיהם שונות ומזגיהם שונים, כל אחד משלים את השני ונעשים לעזר זו לזה, וגם לענין התולדה הוא כן. כי ע\"י שהיא כנגדו עי\"ז נעשית לו לעזר.","b":false}]},{"id":"11","t":"לא להתפעל מיופי העוה\"ז והנאותיו","p":[{"t":"וַיִּטַּע ה' אֱלֹהִים גַּן בְּעֵדֶן מִקֶּדֶם וַיָּשֶׂם שָׁם אֶת הָאָדָם אֲשֶׁר יָצָר, וַיַּצְמַח ה' אֱלֹהִים מִן הָאֲדָמָה כָּל עֵץ נֶחְמָד לְמַרְאֶה וְטוֹב לְמַאֲכָל וְעֵץ הַחַיִּים בְּתוֹךְ הַגָּן וְעֵץ הַדַּעַת טוֹב וָרָע: (ב, ח-ט)","b":true},{"t":"אולי יש לפרש בדרך רמז, שיש כאן ציור חי על העוה\"ז. מחד גיסא ירמוז אל הנסיונות העצומים, ומאידך גיסא ירמוז אל התועליות הנפלאות שאפשר להשיג. כי הקב\"ה נטע גן יפה ונהדר, והצמיח בו כל עץ נחמד למראה וטוב למאכל, כלומר, שהעוה\"ז מכוייר ומצוייר ומושך את לבו של האדם, ואם האדם יטה עצמו אחר יופי העוה\"ז ומחמדיו, לא תשבע עינו לעולם, כי ככל שירבו הישגיו החומריים, וככל שיתעצמו הנאותיו הגשמיות, כן תגדל תאותו וירבה תאבונו, ואין אדם מת וחצי תאותו בידו (קה\"ר ג, יג). ובסוף יתקיים בו, אם בגפו יבא (לעולם הזה), בגפו יצא (שמות כא, כג), ריקם ממש, שאין מלוין אותו בשעת מותו של אדם לא כסף ולא זהב וכו' (אבות ו, י).","b":false},{"t":"אבל אם יתעורר האדם לנצל את החיים ולהשיג קנינים רוחניים יכול לצאת מכאן ברכוש גדול עצום ורב, וישמח במקחו, ולזה אמר הכתוב, \"ועץ החיים בתוך הגן\", כלומר שלמרות שהגן הזה הרומז לעוה\"ז, הריהו מלא בדברים ריקים שאין להם אלא אותה הנאה רגעית, שאין לה המשכיות ולא ישאר בידו מאומה, כאדם הנכנס לארמון יקר ונהדר ומביט ורואה מימין ומשמאל, בכל שכיות החמדה, וסגולות המלכים, ויופי הציורים וקישוטים וכו', ועולה ויורד סובב הולך, לא תשבענה עיניו מהיופי וההדר, והתכנון המיוחד וכו', אך בסוף הטיול שב לביתו ולבקתתו, ונשאר עמו רק זכרון נעים ותו לא מידי.","b":false},{"t":"אך בתוך העולם הזה ורקבו, ישנו \"עץ החיים\", היא התורה ועבודת ה', המונחים בקרן זוית, ואין איש שם על לב לפנות אליה ולהשביע את נפשו מן הטוב האמיתי והנצחי שמרוה צמאונו בעוה\"ז, ומספק לו מרגוע נפשי אין דומה לו, וגם מלוהו לעולם הבא, וקנינים אלו לא יוכל אדם להשיגם אלא בעולם הזה דוקא.","b":false},{"t":"אלא שהמניעים מרובים ועומדים על כל פנה וזוית, הן המה העצים הנחמדים למראה ויפים למאכל, והפתאים נמשכים אחריהם ומוסרים עליהם את נפשם, ומתעלמים לגמרי מקיומו של עץ החיים, ולא נגשים אליו כלל.","b":false},{"t":"והמשיך הכתוב ואמר, \"ועץ הדעת טוב ורע\". כלומר שהקב\"ה שהוא יוצר אור ובורא רע, וזה לעומת זה הוא עשה. נתן באדם דעת נכונה, שיוכל להבחין ולדעת מה טוב ומה רע. ואם ישמור האדם דעתו מנגיעות ומשקיעה ברצונות ותאוות, יכול להביט נכוחה ולדעת, היכן נמצא הטוב והיכן הרע. ויבחר בטוב, אבל אם מגביר את תאוותיו על שכלו, אז דעתו קיימת במקומה, אבל אינה פועלת כלל, והולך אחר תאות לבו ומתרחק מעץ החיים, והולך אחר כל עץ נחמד למראה וגו', אבל כשישליט דעתו על מעשיו והגיגי לבו, עיניו לנוכח יביטו, ויעזוב רשע דרכו, וילך אחר עץ החיים, וימצא חיים.","b":false}]},{"id":"11","t":"מהו יצר הרע","p":[{"t":"וַיִּיצֶר ה' אֱלֹהִים אֶת הָאָדָם עָפָר מִן הָאֲדָמָה וַיִּפַּח בְּאַפָּיו נִשְׁמַת חַיִּים וַיְהִי הָאָדָם לְנֶפֶשׁ חַיָּה: (ב, ז)","b":false},{"t":"ופירש רש\"י ז\"ל, וייצר, [בשני יודי\"ן], שתי יצירות, יצירה לעולם הזה, ויצירה לתחיית המתים. אבל בבהמה שאינה עומדת לדין, לא נכתב ביצירתה שני יודי\"ן. ומקורו טהור בדברי רבותינו במדרש תנחומא (תזריע פ\"א).","b":false},{"t":"ורבינו יעקב בעל הטורים פירש את ענין שני היודי\"ן, דקאי על שני יצרים, יצר הטוב, ויצר הרע. אבל החיות שאין להם אלא יצר אחד נכתב ביו'ד אחד. ע\"ש.","b":false},{"t":"ומצינו בדברי הראשונים שחקרו מה הוא יצר הרע, ומה הוא יצר הטוב, אם שני מלאכים הם אחד טוב ואחד רע, או שהמשיכה אל הרע היא בעצם החומרים שמהם נוצר האדם, עפר, מים, אש, רוח, והם מושכים את האדם לחומריות ולתאוות הגשמיות, וזהו היצר הרע. ואילו הנשמה שהיא חלק אלוה ממעל שהקב\"ה נפח באדם, היא המחזקת אותו ומושכת אותו לטוב ולמועיל וזה הוא היצר הטוב.","b":false},{"t":"וזכורני שראיתי לגדול חכמי המוסר רבינו הרמח\"ל זיע\"א, (בספר המאמרים במאמר העיקרים - בתורה ובמצוות וראה גם במאמר הגאולה), שכתב, דשני הדברים נכונים הם, דעצם היצירה של האדם מורכבת משני כחות שונים המנוגדים זל\"ז, הגוף מושך אל הגשמיות ושאר הבלי עולם, ולעומתו הנשמה מושכת אל הקדושה וההישגים הרוחניים, ומואסת בעניני העוה\"ז, וכל הנאותיו היו לה לזרא.","b":false},{"t":"ולדברי רבינו יעקב בעל הטורים הנז', הדבר עולה יפה מתוך הפסוק. \"וייצר ה' אלהים את האדם\", היינו שיצר אותו עם שני יצרים יצר הטוב ויצר הרע, ונרמזו בשני היודי\"ן שביצירתו. והפסוק ממשיך לפרטם ולבארם באומרו, \"עפר מן האדמה\", והוא היצר הרע, שהוא קשור באדם כי מהחומריות ומהעפר נוצרו רמ\"ח אבריו ושס\"ה גידיו, והוא מלבושו בעודנו כאן בעולם הזה.","b":false},{"t":"ואח\"כ אמר, ויפח באפיו נשמת חיים, היינו חלק הקדושה והיא נשמת אלהים שבקרב האדם, וכמאמר הזוה\"ק (עי' זוהר ח\"א כז, א ודו\"ק, ובספר הפליאה ד\"ה שאל משה וכו' ובפירוש הרמב\"ן לתורה בראשית ב, ז ובספר התניא ח\"א פ\"ב מייתי כן מהזוהר), על הפסוק ויפח באפיו, דמדיליה קא נפח, כלומר, שהקב\"ה נפח באדם נשמת חיים, וא\"כ הנשמת חיים היא חלק מן השכינה העליונה, שהרי כל הנופח, משלו הוא נופח. וא\"כ זה הוא היצר הטוב שמנסה למשוך את האדם לצד של הקדושה, ולהרחיקו מן הנאות העולם הזה ותאוותיו. והיא המלחמה הגדולה והתמידית בה נתון האדם, כשהוא נתון בין שני הכחות הללו, אחד מושכו לכאן ואחד לכאן. ואע\"פ שההכרעה נתונה בידו להטות הכף ולהכריע הדין כאשר יחפוץ, מכל מקום, המלחמה נמשכת, וצריך עוז וגבורה לכבוש את יצרו ולהכניעו.","b":false},{"t":"עוד כתב רבינו הרמח\"ל ע\"ה שם, שמלבד הכחות הנ\"ל, עוד יש מלאך הממונה על הסטרא אחרא, שגם הוא נלחם באדם להחטיאו, ונוסף גם הוא על החומר העכור המצוי בנו, ומטרתו להלחם בנו, ואלמלא הקב\"ה עוזרו לאדם אינו יכול לו.","b":false},{"t":"ובזה ישבתי על נכון קושיא גדולה שנתקשיתי בה, על מה שאמרו רבותינו שהשטן שולט בכל ימות השנה מלבד יום הכפורים שאין לו שליטה כלל, ע\"ש. ושמו מעיד עליו, \"השטן\", שהרי בשנת החמה יש שס\"ד ימים לערך, והוא שולט רק בשס\"ד יום, כדאמר רבי רמי בר אבא (יומא כ, ב נדרים לב, ב ועי' בתוס' שם) \"השטן\" בחושבניה תלת מאה ושתין וארבעה, וימות החמה שס\"ה, א\"כ איכא חד יומא דלית ליה רשותא למשטן, דהיינו יוה\"כ. והנה ידוע שאלמלי היצר הרע שמשחק באדם ברוב תחבולותיו לא היה האדם חוטא, וכמו שאמרו חז\"ל (סוטה ג, א), אין אדם עובר עברה אא\"כ נכנסה בו רוח שטות. וא\"כ ביום הכיפורים שאין תוקף לשטן כלל אין יהודי שיעבור עברה.","b":false},{"t":"והיה קשה לי דהא בכ\"ז מצינו דיש עוברי עבירה גם ביום הכפורים בעוה\"ר. ואף בימי חז\"ל היה כדבר הזה, כההוא איש ובנו שבאו על נערה מאורסה ביוה\"כ (ראה גטין נז, א וב\"מ פג, א), ואיך אפשר להבין זאת.","b":false},{"t":"אמנם עפ\"י הנ\"ל אתי שפיר בס\"ד, דבאמת המלאך הממונה הוא היצה\"ר שהוא השטן, אין לו רשות ביוה\"כ להחטיא את האדם כלל. אבל החומר העכור שממנו בנוי ויצוק האדם לא בטל גם ביום הכיפורים, והגם שקל מאד לגבור על יצרו ותאוותיו ביום ההוא, מפני שאינו צריך להלחם גם עם המלאך. אך כל זה דווקא אם הוא רוצה ללחום ולהתגבר, אזי ביום ההוא קל לו הדבר, אבל אם אינו רוצה בכך, וחפץ בתאות לבו, בודאי שיוכל לחטוא. כי הרע שבו מתגבר תמיד למושכו לרע, אם לא יתחזק וילחם בו בכל כחו.","b":false},{"t":"ועכ\"פ הצלם האלהי שבו יצר ה' את האדם, עומד והלו עלי ראשו של אדם, ויכול האדם להטות את עצמו כלפי חסד וטוב, ולגבור על יצרו, ואפי' על המלאך הנז'. כי הבא להטהר מסייעין אותו (יומא לח, ב ע\"ז נה, א מנחות כט, ב), וה' עוזרו ויכול לגבור על יצרו ולעבוד את הי\"ת בטהרת לבו ובכל מאודו.","b":false}]},{"id":"11","t":"שבת קודש מקור הברכה","p":[{"t":"וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי וַיְקַדֵּשׁ אֹתוֹ וגו': (ב, ג)","b":false},{"t":"כמו שהקב\"ה ברא ויצר את האדם, ומכל זרעו בחר באברהם אוהבו, ונתן בידו את הברכה, כדכתיב (נחמיה ט, ז ואילך), אתה הוא ה' האלהים אשר בחרת באברם וגו', וכתיב (בראשית יד, יט), ברוך אברם לאל עליון. והוא מסר הברכה ליצחק, ויצחק מסרה ליעקב, ויעקב ליוסף ומשם לכל ישראל, ועל ידם משתלשלת הברכה לכל באי עולם.","b":false},{"t":"וכן בחר ה' בציון, ושם ציוה את הברכה חיים עד העולם (תהלים קלג, ג), ומארץ ישראל משתלשלת הברכה לכל ארצות תבל וכמבואר כל זה בזוה\"ק ושאר ספרים, כי שם ציוה ה' את הברכה.","b":false},{"t":"כמו כן היום השביעי נבחר מכל הימים, ובו נתן הי\"ת את הברכה, ויום השביעי משפיע ברכה לכל הימים, וזה שנאמר כאן, ויברך אלהים את יום השביעי, ויקדש אותו. וכן תקנו חז\"ל בנוסח התפלה, \"וברכתו מכל הימים\", היינו, שלקח יום השבת את הברכה של כל הימים. ואמרו רבותינו (ב\"ר יא, א), על הפסוק (משלי י, כב), ברכת ה' היא תעשיר ולא יוסיף עצב עמה, ברכת ה' היא תעשיר זו השבת שנאמר ויברך אלהים את יום השביעי וכו', ע\"ש.","b":false},{"t":"וכן אמר המשורר הקדוש רבינו שלמה הלוי אלקבץ ז\"ל, לקראת שבת לכו ונלכה כי היא מקור הברכה. כי כל הברכות לא באות אלא ממנה.","b":false},{"t":"והרוצה סיעתא דשמיא שואב מן השבת לכל ימי השבוע ומצאתי ששבת בגימטריא \"עזרת הוי'ה\", היינו שהשומר שבת קודש כהלכתה זוכה לעזרת ה' בכל אשר יעשה.","b":false}]},{"id":"11","t":"שבת קודש השלמת הבריאה ומיתוק הדינים","p":[{"t":"וַיְכֻלּוּ הַשָּׁמַיִם וְהָאָרֶץ וְכָל צְבָאָם, וַיְכַל אֱלֹהִים בַּיּוֹם הַשְּׁבִיעִי מְלַאכְתּוֹ אֲשֶׁר עָשָׂה וַיִּשְׁבֹּת בַּיּוֹם הַשְּׁבִיעִי מִכָּל מְלַאכְתּוֹ אֲשֶׁר עָשָׂה, וַיְבָרֶךְ אֱלֹהִים אֶת יוֹם הַשְּׁבִיעִי וַיְקַדֵּשׁ אֹתוֹ כִּי בוֹ שָׁבַת מִכָּל מְלַאכְתּוֹ אֲשֶׁר בָּרָא אֱלֹהִים לַעֲשׂוֹת, אֵלֶּה תוֹלְדוֹת הַשָּׁמַיִם וְהָאָרֶץ בְּהִבָּרְאָם בְּיוֹם עֲשׂוֹת ה' אֱלֹהִים אֶרֶץ וְשָׁמָיִם: (ב, א-ד)","b":true},{"t":"חז\"ל דרשו (ב\"ר יב, טו והובא נמי בדברי רש\"י ז\"ל בראשית א, א), על הפסוק ביום עשות ה' אלהים, שבתחלה עלה במחשבתו יתברך לברוא את העולם בדין, שנאמר בראשית ברא אלהים את השמים וגו' (בראשית א, א), ראה שאין העולם יכול להתקיים בדין, והקדים מדת הרחמים ושיתפה למדת הדין, והיינו דכתיב ביום עשות ה' אלהים ארץ ושמים.","b":false},{"t":"והנה הרואה בפסוקים יראה כי לא נזכר ענין הקדמת מדת הרחמים למדת הדין אלא אחר שנזכר ויכלו השמים, וינח אלהים וגו' היינו שנחה מדת הדין. ואולי המנוחה הזאת היא שהביאה להתמתקות הדינים, בהקדים שם הוי'ה לשם אלהים, כמו שנא' ביום עשות ה' אלהים ארץ ושמים. כי ביום השבת הגיעו שמים וארץ לתכליתם הנרצה, והמנוחה האמורה אינה רק בבחינת שב ואל תעשה, אלא היא משלימה את כל מעשה היצירה ומביאתה אל תכליתה, ובזה ממתקת את כל הדינים.","b":false},{"t":"משל למה הדבר דומה, לאדם שבא להכין סעודה למלך, ולקח מכל מאכל אשר יאכל, ובחר מן המשובח שבכל דבר, מן העוף למינהו, ומן הבשר של טלאים וגדיים וצבאים, וכן שאר ירקות ופירות, והיה מסדרם ומחתכם זה לעומת זה, בסדר יפה וצורה נאה מבית ומחוץ. אמנם עם כל זאת עדיין לא נשלמו הכנות הסעודה עד שיתן הכל תוך קדרה נאה ויבשלם כראוי להם עם מלח ותבלין לפי ענינם, ואז הריהו רואה את השלמת הענין ושמח במעשיו.","b":false},{"t":"והכא נמי בכל יום ויום מששת ימי המעשה ברא הי\"ת את אשר ראוי לו לאותו היום, אמנם עדיין לא באו אל מטרתם ותכליתם עד ליום השבת. וע\"כ נאמר בו, ויכולו השמים והארץ וכל צבאם, שרק אז הושלמו כל מעשה שמים וארץ ונגמרה מלאכתם, ובאו אל תכליתם. כי המנוחה שבאה ביום השבת היא משלימה מלאכתם וממתקת אותם במתיקות דקדושה ועונג עליונים, ומזה באה התמתקות שמו יתברך.","b":false},{"t":"ואולי זה נרמז במה שאמר, \"ויכלו השמים וגו' ויכל אלהים ביום השביעי\", לומר, כי על ידי שהשמים והארץ וכל צבאם באו אל תכליתם, ע\"י זה נסתיימה כביכול מדת הדין מן העולם, כי בזה נמתקו כל הדינים. וזהו, \"ויכל אלהים\", היינו אותה מדה שהיא מדת הדין הרמוזה בשם אלהים שהעולם לא היה יכול להתקיים בה, עתה כלתה גם היא, ובאה אף היא לתכליתה ע\"י מדת הרחמים שקדמה לה עתה.","b":false},{"t":"וכן מדוקדק בתפלה שתקנו חז\"ל בליל שבת, אתה קדשת את יום השביעי \"לשמך\", כלומר, שקדושת השבת ומנוחתה, היא למען שמך, כי על ידה משלימים את שמו יתברך ומתמתקים הדינים, ויש קיום לעולם.","b":false},{"t":"וזו הסיבה שרק אחרי ויכולו, נכתב הפסוק ביום עשות ה' אלהים וגו', והמשיכו חז\"ל לומר בנוסח התפלה, שהשבת היא \"תכלית מעשה שמים וארץ\", שזה הוא הנאמר בתורה ויכולו השמים והארץ, כלומר דע\"י שמעשה שמים וארץ באו אל תכליתם, דין גרמ'א להשלים את שמו יתברך, וזהו שממשיך ואומר בתפלה \"וברכתו מכל הימים, וקדשתו מכל הזמנים\". דאחר שיום השביעי הוא השלמת כל הבריאה שנבראה ונוצרה ונעשתה בששת הימים, כי כל הנעשה בכל יום ויום היה עדיין חסר ולא מושלם עד שבאה שבת, והשלימה את כולם, על כן ברכו מכל הימים, וגם קדשו וגידלו מכל הזמנים.","b":false},{"t":"כי הנה ידוע שכל המועדים מביאים קדושה המיוחדת להם, ועל ידם יורד שפע גדול ורב בכל העולמות. מ\"מ זה הוא בבחינת תוספת וגדולה, אבל עיקר השלמת כל הבריאה והיצירה והעשיה, והבאתם עד תכליתם נעשה ביום השבת דוקא.","b":false},{"t":"וזהו ויכל אלהים וגו', כמו שפירשתי, שכלו ונגמרו הדינים ובאו אל שלמותם, והושמו רחמים לראשם ונהיו הוי'ה אלהים. והמשיך ואמר, \"וישבות ביום השביעי מכל מלאכתו אשר עשה\", כלומר, שביום השביעי שבתו הדינים מהתגברותם בדינים קשים, ובאו אל המנוחה ע\"י שנמתקו כראוי. וכל זה היה ע\"י שביתה \"מכל מלאכתו אשר עשה\", היינו, שעשה את השביתה להשלים את כל מלאכתו, ולהביאה לתכליתה, ומזה נעשה מתיקות גם לשמו יתברך ומעתה הוא אחד ושמו אחד.","b":false},{"t":"ואחר כל זה נאמר, \"ויברך אלהים את יום השביעי\", היינו, שגם מדת הדין מודה ומברכת ליום השביעי, כלומר שמעלתה היא בדין ולא בחסד, וכיון שיש ליום השביעי ברכה ותוספת קדושה עפ\"י דין, זה הוא המיתוק היותר גדול. וסיים מעין ההתחלה \"כי בו שבת מכל מלאכתו אשר ברא אלהים לעשות\". ואולי רמז בזה לעליית העולמות שנעשית בשבת ועולים במעלות רמות, ושם מושפעים מט\"ל אורות, ואשר על כן נאסרו הט\"ל מלאכות, כי למרות שיש תיקון העולם במלאכות אלו, מ\"מ במקום בו עולים בשבת אין צורך לזה, כי כבר נתקן הכל מכח קדושה עליונה מעולמות העליונים, והעושה בו מלאכה יומת, שאינו מאמין בקדושתו ועלייתו של השבת, עד שחושב שהוא צריך לעסוק במלאכתו (וראה בטעמי המצוות פרשת בהר באורך). וזהו \"אשר ברא\" שהוא עולם הבריאה, עולם הנשמות. \"לעשות\", היינו כי משם יורד השפע עד לעשיה, והוא שנא' לעשות.","b":false},{"t":"ומיד נאמר אחריו, \"אלה תולדות השמים והארץ בהבראם\", כלומר שמיום שנבראו, מיועדים היו ליום הזה ולהשגה הזאת. וממשיך ואומר, \"ביום עשות ה' אלהים ארץ ושמים\". שביום הזה שהוא יום השבת נשלם שמו יתברך והוקדם הוי'ה לאלהים, ונמתקו הדינים. והקדים ארץ לשמים כאן (שלא כמו בפסוק בראשית), משום שהשפע הקדוש הזה תלוי בשוכני ארץ, הם עם ישראל ראשית תבואתו של הקב\"ה, שבשבילם ברא את השמים והארץ (ויק\"ר לו, ד), ונתנם בידם להשלימם ולהביאם אל תכליתם, וצדיקים במעשיהם הטובים מהפכים את מדת הדין למדת הרחמים (ב\"ר לג, ג). ובפרט כששומרים את השבת ושובתים ממלאכה, ומענגים ומקדשים אותו כראוי לו, על זה נאמר (שמות לא, טז), ושמרו בני ישראל את השבת, לעשות את השבת וגו'.","b":false}]},{"id":"11","t":"דקדוק הדין עם הקרובים אל הי\"ת","p":[{"t":"בְּרֵאשִׁית בָּרָא אֱלֹהִים אֵת הַשָּׁמַיִם וְאֵת הָאָרֶץ: (א, א)","b":false},{"t":"וכתב רש\"י ז\"ל (ומקור דבריו בבראשית רבה יב, טו), וז\"ל, ברא אלהים, ולא אמר ברא ה', שבתחילה עלה במחשבה לבראתו במדת הדין, ראה שאין העולם מתקיים, הקדים מדת רחמים ושתפה למדת הדין, היינו דכתיב (בראשית ב, ד), ביום עשות ה' אלהים ארץ ושמים. עכ\"ל.","b":false},{"t":"ורבינו הקדוש מהר\"ח ן' עטאר זלה\"ה וזיע\"א, כתב בספרו הקדוש אור החיים (בראשית א, א אות ג' ד\"ה גם), בזה\"ל, גם אנחנו נפרש שני מקראות הללו על זה הדרך, בראשית ברא אלהים את השמים, שם זה של \"אלהים\", פי' מדה זו של הדין בלא שיתוף שם של רחמים, זהו דוקא למה שנוגע ל\"השמים\", ואינו חוזר לאומרו ואת הארץ. כי הארץ בראה בשיתוף שם של רחמים, ועל כתוב אחר סומך, והוא אמרו (בראשית ב, ד), ביום עשות ה' אלהים ארץ, כי אין עולם בני אדם יכול להתקיים בדין גמור בלא שיתוף רחמים וכו'.","b":false},{"t":"והמשיך וכתב, ולא יקשה לך מה משפט יערוך ה' לבני אלים יושבי שמים, הלא תמצא שאמרו (חגיגה טו, א), במעשה מט\"ט, שדנוהו לפני אלישע ומחיוהו שתין פולסין דנורא, וגם אליהו וכו' (ב\"מ פה, ב), וכמה משפטים לשרי מעלה (עי' יומא עז, א). והגם שאין להם יצר, עם כל זה ימצא בהם הטעות. כי לפעמים לא יכונו לאמת וישגו, וצא ולמד ממעשה המלאך מט\"ט ואליהו כי שגגו, וכן יקר מקרה, ויענישם ה' אפילו על השוגג, מה שאין שופט במשפט זה ליושבי ארץ. ובזה יתאמת מה שפירשנו, ונכון. עכל\"ה.","b":false},{"t":"והוא חידוש גדול ונפלא, כי מחשבת ה' ברוך הוא לא תתחלף, כי לא אדם הוא להתנחם, ולא מחשבותיו מחשבותינו, דסוג אחר היא מחשבתו יתברך, לא מהסוג של המחשבה שלנו, דבבני אדם יש הבדלים במחשבותיהם, כי יש שמוחו חריף ביותר וברגע כמימריה מקיף ענינים שלמים ומסובכים וסוקרם לפרטי פרטיהם, ויש איש שמחשבתו איטית ועד שיחשוב אפילו בדברים של מה בכך, צריך לו עידן ועידנים ועוד חצי עידן. אך סוף סוף הכל הוא אותו סוג של מחשבה, רק מחשבה אחת מהירה והאחרת כבדה ואיטית וכו'. אך מחשבתו יתברך היא ענין בפני עצמו, ואין לנו השגה בה. וכשעלה במחשבתו לברוא את העולם בדין, זה נשאר למעלה בשמים, וכאשר ביאר הרב בעל אוה\"ח זללה\"ה.","b":false},{"t":"ונראה לומר דע\"ז אמרו (ראה מנחות כט, ב), \"כך עלה במחשבה\", כלומר, שמחשבת הי\"ת היא מחשבה אחרת נעלית מכל השגה, ואינו נוהג במחשבה הזאת עם אנשים פשוטים, כי אינה שייכת להנהגת עולמנו. וזה שנאמר, \"עלה במחשבה\", וזהו שפירש רבינו האוה\"ח זלה\"ה שהשמים נעשו במה ש\"עלה במחשבה\" [כלומר, במדת הדין], וזהו הענין שמצינו בההיא דרבי עקיבא (מנחות שם), כשהראהו הקב\"ה למשה את הדורות הבאים אחריו, ראה את רבי עקיבא ותורתו, ואמר לפני הקב\"ה, רבונו של עולם, יש לך אדם כזה ואתה נותן תורה על ידי, אמר לו, שתוק, כך \"עלה במחשבה\" לפני. אמר משה לפני הקב\"ה, רבונו של עולם, הראיתני תורתו, הראני שכרו, אמר לו, חזור לאחוריך. חזר לאחוריו, ראה ששוקלין בשרו במקולין, אמר לפניו, רבש\"ע, זו תורה וזו שכרה. אמר לו, שתוק, כך \"עלה במחשבה\" לפני. וזה מהנהגת השמים שהוא ענין \"עלה במחשבה\".","b":false},{"t":"ובזה אמרתי לרמוז בעזר האל וישועתו, בפסוק לעולם ה' דברך נצב בשמים (תהלים קיט, פט), דעל העולם הזה הגשמי שאינו יכול להתקיים בדין, אמר לעולם ה' בשם הוי\"ה, שהוא מדת רחמים. אבל \"דברך\" שהוא דבור והוא לשון קשה (כדמצינו במכות יא, א דכל דיבור לשון קשה הוא), והוא ממדת הדין, אותו הדבור \"נצב בשמים\", כלומר, נשאר נצב בשמים, כי את יושבי השמים דנים במדת הדין. וכנ\"ל.","b":false},{"t":"[א\"ה - ולפי\"ז נמי יש לפרש את הפסוק, צדקתך כהררי אל משפטיך תהום רבה אדם ובהמה תושיע ה' (תהלים לו, ז), היינו שצדק ה' ומשפטו הם כ\"הררי אל\" היינו גבוה על גבוה, ואין הי\"ת נוהג בהם בעולמנו, וכן משפטיו \"עד תהום רבה\", היינו בעומק שבעומק, שגם שם אין שייכות לבני אדם, ושם שולטת מדת הדין במלא תוקפה. אבל בעולם השפל, אדם ובהמה תושיע ה', בשם הוי\"ה שהוא שם של רחמים, כי הי\"ת נוהג עם הכל במדת הרחמים. וכן על זה הדרך יש לפרש את הפסוק, כי גדול עד שמים חסדך (תהלים נז, יא). היינו עד השמים שולטים החסדים אבל בשמים הוא דין. וזהו שנא' (שם שם, יב) רומה על שמים אלהים, היינו כיון שהוא על שמים, א\"כ זו מדת הדין, ולהכי קאמר \"אלהים\". ולפי ה'נחה ס'וברת זו יש לפרש הרבה מקראי קודש, ואין ע'ט האסף. יבח\"ר].","b":false},{"t":"ועפי\"ז אמרתי לישב בס\"ד, קושיא גדולה, שהכתוב אומר (תהלים נ, ג), וסביביו נשערה מאד. ואמרו חז\"ל (יבמות קכא, ב ב\"ק נ, א ובירושלמי ביצה ג, ח), מכאן שהקב\"ה מדקדק עם חסידיו כחוט השערה.","b":false},{"t":"והדבר תמוה מאד, וכי מפני שהם חסידיו עושי רצונו במסירות וגבורה, צריך לדקדק עמם עד כחוט השערה, האם זה שכרם חלף עבודתם בדבקות ובחסידות.","b":false},{"t":"אמנם לפי מה שנתבאר אתי שפיר, דאין זה עונש ח\"ו, אלא זו מדרגה גבוהה, שההנהגה בגובה כזה היא קרובה לשמים יותר מאשר לארץ, ובשמים נדונים במדת הדין, וע\"כ יש שם דקדוק בדין.","b":false},{"t":"משל למה הדבר דומה, לבן כפר שחשקה נפשו לעבוד עם אנשים גדולים ורמי מעלה, והיה משתדל על זה הרבה, עד שבסופו של דבר נתקבל לעבודה בארמונו של המלך, וכשבא לשם אמרו לו שעליו לבא בבגדים נאים ומגוהצים דבר יום ביומו, וגם עליו להקפיד הקפדה יתירה על נקיונו ומראהו החיצוני, ועוד הוסיפו לו תנאים כיד המלך, והיו מזהירים אותו שישים מחסום לפיו, ולא יחל דברו בדברים פשוטים לעין כל, רק כל דבורו צריך להיות במדה ובמשקל, דברים נאים ומדודים, ולא יאמר דבריו בקולי קולות, ולא ישא על פיו ביטויים זולים, ועוד כהנה רבות. וגם מוטל עליו להקפיד במילוי תפקידו ולא ישנה כחוט השערה, שכן כל שינוי, עלול להמיט עליו אסון. והוא כעס מאד על כל זה, באומרו, האם זו היא המעלה והיקר לעבוד בארמון המלך ולהיות קרוב אליו כל כך, הלא בעיני עצמי דומני כמי שצריך לחיות בתוך צינוק של זהירות וביקורת. ויאמר, אם כן למה זה אנכי כאן, הלא בהיותי בן כפר פשוט, לא הטילו עלי אפילו אחד ממאה מן העול הזה, וכי מפני שחשקה נפשי לשרת את המלך, כי אהבתי את אדוני ויקרה בעיני מלכותו, אני צריך לשאת עלי את כל המשא הכבד הזה.","b":false},{"t":"אמנם כל בר דעת יודע ומבין שאין זה משא של ענישה, אלא עול של דרך ארץ. כי אי אפשר לבא לבית המלך בלבוש שק, או כשאינו נקי ונאה וכו'. אלא שהכפרי הזה לפי הרגליו הפשוטים, נראה לו שמכבידים עליו, ודורשים ממנו דרישות גדולות ומופרזות שקשה לו לעמוד בהם.","b":false},{"t":"וכן הוא הדבר אצל חסידיו של הקב\"ה ישתבח שמו, שצריכים להתנהג בהנהגה גבוהה שדרישותיה מדוקדקות מאד, וזהו \"וסביביו\" שהמתנהג בחסידות וקרוב אל הי\"ת ומצוי \"סביביו\", הרי הוא יונק מגבהי מרומים, והרי הוא בבחינת סולם מוצב ארצה אך ראשו מגיע השמימה, ועליו לנהוג במשנה זהירות, כראוי למהלכים לפני ה' ברוך הוא, כי שם ההנהגה היא במדת הדין, שכבוד המקום דורש זאת, ואי אפשר אחרת. והרי הוא קרוב בהנהגתו ליושבי שמים שוכני מרום, ששם דנים במדת הדין, ואינו עונש ח\"ו, אלא זו היא הדרישה בגבהים אלו, ואי אפשר להיות ממשרתי עליון, ובו בזמן לנהוג בהנהגה כפרית זולה ופשוטה, ולכן עליו לנהוג במשנה זהירות, וגם לקבל עליו את חוק הנהגת העליונים ונימוסיהם, ושם נוהג הקב\"ה במדת דינו, ועל כן גם הנהגתו עם חסידיו ששוכנים \"סביביו\" נשערה מאד, ומדקדק עמהם.","b":false},{"t":"ובזה יובן מה שענתה האשה השונמית לאלישע בעת ששאל אותה מה לעשות לך, היש לך לדבר אל המלך או אל שר הצבא. והיא ענתה ואמרה \"בתוך עמי אני יושבת\" (מ\"ב ד, יג). והנה מצינו בזוהר הקדוש בכמה מקומות (בראשית סט, ב ושם קס, ב שמות לג, ב ועי' שם מד, ב ובזו\"ח רות כט, א), שאלישע רצה לדבר על האשה השונמית טובות לפני מלך מלכי המלכים הקב\"ה ישתבח שמו, להיטיב לה. ואמנם האשה השונמית יראה מזה יראה גדולה, וענתה לו \"בתוך עמי אני יושבת\", כי נתיראה שאם יעלו עניניה לגבהים כאלה, היא תדרש להנהגה גבוהה ומדוקדקת ויבקרו את מעשיה, וינהגו בה במדת הדין, ורצתה שימשיכו לנהוג עמה בהנהגה פשוטה השוה לכל נפש, שיש עמה מדת הרחמים, וזהו, \"בתוך עמי אני יושבת\". כלומר, יניח לי כבודו להשאר בפשיטותי.","b":false},{"t":"ואולי זו היא כונת יעקב אבינו ע\"ה, באומרו לבניו (בראשית מב, א), למה תתראו, היינו שלא יבליטו את עצמם מן הצבור, כי ע\"י שמתבלטים יותר מאנשים אחרים גורמים בזה שידונו אותם בנפרד, ובמדה גבוהה. ונוח לו לאדם להסתיר מעשיו, ולנהוג בפשטות ובענוה. וכך אמרו בגמרא (ראה תמיד לב, א), מה יעביד איניש ויחיה, ימית עצמו ופירש\"י ימית עצמו, ישפיל את עצמו (וראה מה שנתבאר להלן בפרשת וישב מאמר ב).","b":false},{"t":"[א\"ה - ראוי להביא בכאן מה שכתב הרב אבי עזר (ויקרא י, ב), על ענין מיתת בני אהרן, וז\"ל, וימותו לפני ה'. הנה רבים יתמהו, אם כונתם לשמים למה נענשו. אבל תדע כי עונש אדם לפי מדרגתו כטעם וסביביו נשערה מאד (תהלים נ, ג), כי כאשר יגביר השכל על אדם כאשר ירבה השפע כן ירבה ענשו.","b":false},{"t":"לכן ירא יעקב על נפשו באמרו קטונתי מכל החסדים (בראשית לב, יא), כי חשב היותו בקדושה עליונה ובמהרה ישגה בדבר קל מה שהוא חשב להיות רצוי לפני הבורא, ואין. וכן ראינו באנשים אשר סביב מלך בשר ודם, כמו שנענש שר האופים על דבר קל (ראה בראשית פרק מ).","b":false},{"t":"לכן אל תתמה על החפץ אם מצינו פעם אחת במקרא עונש וחטא בעבור שאמר לא אשאל ולא אנסה את ה' (ישעיה ז, יב), ופעם אחרת מצינו עונש עבור שאמר תן לי אות ומופת, כי אדם אשר יחזיק מעוזו בשכל, צריך לבחון בשכל בטרם שיעשה הדבר אם יהא הדבר רצוי או לאו, ואם שגה בו עונו ישא. ופעמים רוצה הקב\"ה ליתן אות, ופעמים רצונו להיפוך. ואם השכל וקדושה יחדיו ידבקו לא ישגו לעשות דבר היפך רצון הבורא ואם ישגו ונעלם מהם אז פסלו אותה במחשבת חוץ מבלי הזריח על האיש ההוא ידיעה שלימה וכו' וכו'.","b":false},{"t":"לא כן השכל והשפעה לעולם לא ימושו כי ה' עשם ויכוננם בלתי אם האדם מעקל דרכו ולא ישמרם כראוי או אז יעלו חלודה ויבוש מקורם, כן הקרבים אל ה' נענשו אשר קלקלו שכלם הזך בדבר מה ועל כן לא הזריחו עליהם כדת. וזה היה עונש בני אהרן וכן תמצא עונשים רבים בתורה על אופן זה לא אוכל לפורטם.","b":false},{"t":"וזה מדוקדק מאד בפסוק שאמר משה (ויקרא י, ג), הוא אשר דבר ה' לאמר בקרובי אקדש, מפני שנענשו על דבר קטן ושגגה תוכיח שהמה גדולים מאד בעיני המקום, כטעם סביביו נשערה. גם הפסוק גלה צדקתם באמרו לפני ה', כדברי הרב שכונתם היה לשמים. אתה הקורא הבט לדברים האלה כי בהמה תשמן חלקך להבין כמה ענינים במקרא. עכ\"ל הרב אבי עזר. יבח\"ר].","b":false},{"t":"(נכתב בעזהית\"ש, בשלישי בשבת שמנה עשר יום למרחשון התשס\"ה)","b":false}]},{"id":"11","t":"גדולתו של אדם","p":[{"t":"וַיֹּאמֶר אֱלֹהִים נַעֲשֶׂה אָדָם בְּצַלְמֵנוּ כִּדְמוּתֵנוּ וגו': (א, כו),","b":true},{"t":"ויונתן בן עוזיאל תרגם, ואמר ה' למלאכיא דמשמשין קומוי דאיתברי ביום תנין לבריית עלמא נעביד אדם בצלמנא בדיוקננא וכו'. ורש\"י ז\"ל כתב, נעשה אדם, ענותנותו של הקב\"ה למדנו מכאן, לפי שהאדם הוא בדמות המלאכים, ויתקנאו בו, לפיכך נמלך בהן וכו'. ע\"ש.","b":false},{"t":"והרב כלי יקר הביא את דברי הרמב\"ן ז\"ל, שהקדוש ברוך הוא אמר לארץ, נעשה אני ואת, כי הארץ נתנה יבול חומרה, כמו שנתנה לשאר בעלי חיים, והקדוש ברוך הוא נתן באדם את החלק הרוחני. ובצלמנו כדמותנו היינו שידמה לשניהם, בגופו לארץ, ובנשמתו לעליונים. ומ\"ש כי בצלם אלהים עשה את האדם. לספר הפלא שבו נבדל האדם משאר בעלי חיים, ע\"ש.","b":false},{"t":"ועפ\"י דבריו ז\"ל נלע\"ד לפרש את הפסוק בתהלים (תהלים סז, ז), ארץ נתנה יבולה, יברכנו אלהים וגו'. דהיינו שיש כאן חלק לארץ שנותנת את יבולה ומספקת החומריות, כדכתיב (בראשית ב, ז), ויצר ה' אלהים את האדם עפר מן האדמה, ואז האלהים יחננו ויברכנו, שהוא בחינת ויפח באפיו נשמת חיים (שם).","b":false},{"t":"ורבינו עובדיה ספורנו ז\"ל הוסיף, שיש באדם גם צד שדומה לבורא יתברך, במה שיש לו בחירה, וז\"ל, כדמותנו, בענין המעשיות שידמה בם קצת לפמליא של מעלה, בצד מה שהם פועלים בידיעה ובהכרח. אמנם פעולתם היא בלתי בחיריית, ובזה לא ידמה להם האדם, ובקצת ידמה האדם לאל יתברך הפועל בבחירה, אמנם בחירת האל יתברך לעולם לטוב, לא כן הבחירה האנושית. יעו\"ש.","b":false},{"t":"ויש להאריך ולהעמיק בזה, והעולה מכל זה, שהקב\"ה יצר את האדם בחכמה נפלאה, והיא ניכרת גם בצד הגשמי ממראה חילוק איבריו וגידיו, ומאופן פעולתם הפלאית, ומההשלמה שמשלימים זה את זה בתכלית הדיוק, והכל נעשה מאליו, בלי שאדם יטרח לחשב חשבונה של כל פעולה ופעולה, ולהוליכה, וליישב את כל הנדרש בכל עת ובכל שעה, וכמו שתקנו לנו חז\"ל בחכמתם בנוסח ברכת אשר יצר, וסיימוה בברכת \"רופא כל בשר ומפליא לעשות\".","b":false},{"t":"ויותר ממה שאנו רואים באיברי הגוף ופעולותיו, יש מן החכמה והפליאה במחשבת האדם ובחכמתו ותבונתו, אשר מכיל במחשבתו אין סוף מן החכמות ומן הידיעות, והוגה וחוקר בהם, ונושא ונותן, ומשדד מערכות בענינים רבים ומגוונים, ממעשה שמים וארץ, ומן החכמות הרבות, ועוד ועוד, והכל בסדר מופתי דבר דבור על אפניו. ועוד, שיש בו נשמה דקדושה, אשר על ידה יעלה ויתעלה, וילך מחיל אל חיל בהשגות אלהיות, להתקרב לה' וליהנות מזיו אורו המופלא.","b":false},{"t":"והכוחות הגשמיים כלולים מארבע יסודות, הלא המה, עפר, מים, אש, רוח. והמה מושכים אותו אל הגשמיות ותאוות העולם הזה והנאותיו על כל הכלול בהם לרבבי רבבות ענינים שונים ומשונים, לא הרי זה כהרי זה, ומרחיקים את האדם מן הקדושה ומן השפע האלהי, וככל שמעמיק לשקוע בעניני גשמיות, כך הוא מתרחק מן ההשגות הרוחניות, וכל מעשה של מילוי תאוותיו מוסיף נדבך המחזק ומעבה את החומה המפרידה בינו ובין קונו, ומתרחק מעט מעט ולא חלי ולא מרגיש, עד שיורד לבאר שחת רח\"ל, ואחריתו מי ישורנו.","b":false},{"t":"ועל זה נאמר (בראשית ב, כז), ויברא אלהים את האדם בצלמו, בצלם אלהים ברא אותו. ותירגם יונתן ב\"ע על זה, וברא ה' ית אדם בדיוקניה, בצלמא ה' ברא יתיה במאתן וארבעין ותמניא איברין, בתלת מאה ושיתין וחמשא גידין, וקרם עלוי משכא (עור), ומלוי יתיה בסרא ודמא (בשר ודם). ונוסף על זה נתן הי\"ת גדולה לאדם להיות מושל על דגת הים ועוף השמים כמו שנאמר (בראשית ב, כו-כח), וירדו בדגת הים ובעוף השמים וגו'.","b":false},{"t":"כי אעפ\"י שגם האדם עפר מן האדמה כשאר היצורים, מ\"מ הוא נברא בצלם אלהים, שהוא \"הכח הבחירי\", אשר ניתן לו לאדם בעת שנפח בו הי\"ת נשמת חיים, ואשר בכח זה יכול למשול ולשלוט בכל הברואים והיצורים. והחשוב יותר, שבכחו זה הוא מסוגל להתגבר על כל יצריו ותאוותיו, ולהיות שורר בביתו ומושל בכל אשר לו, ולהפוך את כל איבריו וגידיו, להיות לו לעזר בעבודתו הגדולה לפני הקב\"ה, וחכמתו ותבונתו ישמשוהו להשיג תורת אלהים חיים, ולחוקרה ולהבינה, כדי שיהיה דבק בה' ממש, ולא יסטה ימין ושמאל ממנו ח\"ו, ותהי מעלתו עולה מעל מלאכים, שהם אמנם גבורי כח עושי דבריו, אבל הם משוללי הבחירה, אבל האדם בעל בחירה ויכול לבחור ברע, ולזה נמשכים כוחותיו הטבעיים, והוא כובש את כל חומריותו וגובר על רצונותיו, ומחזיק בצלם האלהים שבו, ועושה רצון יוצרו, וגורם שמחה לפני הקב\"ה. וישמח ה' במעשיו.","b":false}]},{"id":"11","t":"יעוד המשיח לישראל עוד בטרם שנברא העולם","p":[{"t":"וְרוּחַ אֱלֹהִים מְרַחֶפֶת עַל פְּנֵי הַמָּיִם: (א, ב)","b":false},{"t":"ופירש\"י ז\"ל, כסא הכבוד עומד באויר ומרחף על פני המים, ברוח פיו של הקב\"ה ובמאמרו, כיונה המרחפת על הקן, ע\"כ.","b":false},{"t":"וצריכים להבין את משמעות הענין הזה, למה כסא כבודו ית' מרחף על פני המים. ואפשר דבא ללמד שעדיין לא הוכן כסאו כראוי, כי כל בריאת העולם הוא לצורך קיומה של תורה ע\"י עם ישראל, וכשישלימו את תיקון העולמות יתגלה משיח צדקנו, ואז יושלם השם והכסא יחד בעה\"ו. אבל עד אז הכסא לא מונח אלא מרחף. וכדרך שאמרו (תנחומא תצא פי\"א ועי' היטב סנהדרין כ, ב), נשבע הקב\"ה שאין השם שלם, ואין הכסא שלם עד שימחה שמו של עמלק, [א\"ה - זה שנא' (ירמיה יז, ב), כסא כבוד מרום מראשון מקום מקדשנו, דביהמ\"ק שהוא מקום כסאו ותלוי בביאת משיח הריהו מוכן ועומד מרום מראשון עוד קודם בריאת העולם. ועי' בדברי הרד\"ק שם. יבח\"ר].","b":false},{"t":"ובאמת ראיתי לרבינו יעקב בעל הטורים ע\"ה שכתב, ורוח אלהים מרחפת, בגימטריא, זו רוחו של משיח.","b":false},{"t":"ובודאי דזה קשור עם מאמר חז\"ל הנ\"ל, שכסא ה' מרחף על פני המים, כי הא בהא תליא, ולא יכון זה בלא זה, וכמו שכתוב בסוף פתיחת אליהו הנביא ז\"ל (תיקו\"ז יז, ב), על הפסוק (שה\"ש ה, ב), שראשי נמלא טל, מאי נמלא טל, אלא אמר קודשא בריך הוא, אנת חשיבת דמיומא דאתחרב בי מקדשא דעאלנא בביתא דילי, ועאלנא בישובא, לאו הכי, דלא עאלנא כל זמנא דאנת בגלותא, הרי לך סימנא שראשי נמלא טל ה\"א שכינתא בגלותא וכו' [תרגום: שהקב\"ה אומר לכנסת ישראל אל תחשבי שמיום שנחרב בית המקדש שנכנסתי לביתי, לא כן הוא, אלא מיום שנחרב בית המקדש אף אני לא נכנסתי לביתי, והרי לך סימן, שראשי מלא טל כביכול, וזה יעיד שמשכני בחוץ, ושהי\"ת משתתף עם ישראל בצערם]. והכא נמי כיון שרוחו של משיח מרחפת, גם כסא כבודו מרחף על פני המים.","b":false},{"t":"ובתרגום יונתן בן עוזיאל כתב, ורוח רחמין מן קדם ה' מנשבא על אנפי מיא. וכעי\"ז הוא בתרגום ירושלמי, והיינו שיש רוח רחמים מאתו יתברך המרחפת על פני המים וממתינה לעת מצא, להביא גאולה לישראל.","b":false},{"t":"ומכל זה נלמד שהקב\"ה מכין לבניו את הגאולה והמשיח עוד בטרם הרים יולדו, ואדם אין, ועדיין לא נבראו הברואים ולא נוצרו היצורים, כבר אז הקדים ה' את רוח משיחנו, והוא מרחף ומצפה לגאלינו, וגם כסאו של הקב\"ה מרחף, להראות שהקב\"ה בכבודו ובעצמו כביכול אין לו ישוב וכמ\"ש בפתיחה הנ\"ל.","b":false},{"t":"וכל זה תלוי בתורה ובלומדיה בעמל כיאות. ואולי לזה כיון בתרגום יונתן בן עוזיאל שכתב, וארעא הות תהיא ובהיא צדיא מבני נשא וריקניא מן כל בעיר וכו'. וכן בירושלמי, והיינו שעדיין לא נולד אדם לעמול בתורה ובעבודת ה', ועל כן רוח אלהים מרחפת על פני המים, אבל תיכף בהתרונן קול התורה נזכה לקול רינה וצהלה ולשמוע את קול שופרו של משיח.","b":false},{"t":"רק צריכים להבין את דברי התרגומים שתרגמו \"ורוח אלהים מרחפת\", ורוח \"רחמין\" מן קדם ה'. וקשה, דהא בפסוק נזכר ורוח \"אלהים\" מרחפת, והוא מדת הדין, וכיצד זה תרגמוהו רוח \"רחמין\", שהוא רחמים.","b":false},{"t":"וכפי הנראה למדו שהקב\"ה ממתק את אותם דינים, דהא כתיב ורוח אלהים מרחפת על פני \"המים\", ומים הם רחמים (ראה זוהר ח\"ג קפט, א), ור\"ל דהתמתקו הדינים ע\"י המים, והוי רוח רחמין.","b":false},{"t":"ואפשר שהמתיקות באה מעצם העובדא שגם כסא ה' מרחף על המים, כנגד רוחו של משיח שמרחף, שהוא בחינת שכינתא בגלותא עם עם ישראל, כמו שנאמר (תהלים צא, טו), עמו אנכי בצרה, ודבר זה עצמו ממתק את הדינים מעל ישראל.","b":false},{"t":"משל למה הדבר דומה, למלך שבנו יחידו סרח, ולפי חוקי המדינה צריך לעמוד למשפט, והיו מתיראים השופטים מן המלך. וכשנודע הדבר למלך, דרש מן השופטים לערוך משפט צדק לבנו, כדי שידעו כל בני המדינה שחוק אחד לכולם. ואולם כשגזר השופט להכניס את הבן לבית הסוהר, ביקש המלך מבית המשפט שיכינו גם לו מקום ע\"י בנו יחידו, כי נפשו קשורה בנפשו ועזב את בנו ומת, וכמובן שהעובדא שהמלך יהיה עם בנו יחד, המתיק מאד את עונשו של הבן.","b":false},{"t":"וזה מה שנעשה כאן, כי על ידי שגם כסא הכבוד נמצא באותו מצב שבו עומדת רוחו של משיח, ממילא מתמתקים הדינים, והוא רוח הרחמים שעל פני המים, וה' יעשה למען שמו ויקים שכינתא מעפרא, ויושלמו השם והכסא יחד.","b":false}]}]},{"slug":"נח","name":"פרשת נח","items":[{"id":"13","t":"על מעלת האחדות","p":[{"t":"וַיְהִי כָל הָאָרֶץ שָׂפָה אֶחָת וּדְבָרִים אֲחָדִים, וַיְהִי בְּנָסְעָם מִקֶּדֶם וַיִּמְצְאוּ בִקְעָה בְּאֶרֶץ שִׁנְעָר וַיֵּשְׁבוּ שָׁם, וַיֹּאמְרוּ אִישׁ אֶל רֵעֵהוּ הָבָה נִלְבְּנָה לְבֵנִים וְנִשְׂרְפָה לִשְׂרֵפָה וַתְּהִי לָהֶם הַלְּבֵנָה לְאָבֶן וְהַחֵמָר הָיָה לָהֶם לַחֹמֶר, וַיֹּאמְרוּ הָבָה נִבְנֶה לָּנוּ עִיר וּמִגְדָּל וְרֹאשׁוֹ בַשָּׁמַיִם וְנַעֲשֶׂה לָּנוּ שֵׁם פֶּן נָפוּץ עַל פְּנֵי כָל הָאָרֶץ, וַיֵּרֶד ה' לִרְאֹת אֶת הָעִיר וְאֶת הַמִּגְדָּל אֲשֶׁר בָּנוּ בְּנֵי הָאָדָם, וַיֹּאמֶר ה' הֵן עַם אֶחָד וְשָׂפָה אַחַת לְכֻלָּם וְזֶה הַחִלָּם לַעֲשׂוֹת וְעַתָּה לֹא יִבָּצֵר מֵהֶם כֹּל אֲשֶׁר יָזְמוּ לַעֲשׂוֹת, הָבָה נֵרְדָה וְנָבְלָה שָׁם שְׂפָתָם אֲשֶׁר לֹא יִשְׁמְעוּ אִישׁ שְׂפַת רֵעֵהוּ, וַיָּפֶץ ה' אֹתָם מִשָּׁם עַל פְּנֵי כָל הָאָרֶץ וַיַּחְדְּלוּ לִבְנֹת הָעִיר, עַל כֵּן קָרָא שְׁמָהּ בָּבֶל כִּי שָׁם בָּלַל ה' שְׂפַת כָּל הָאָרֶץ וּמִשָּׁם הֱפִיצָם ה' עַל פְּנֵי כָּל הָאָרֶץ: (יא, א-ט)","b":true},{"t":"ופירש רש\"י ז\"ל, שפה אחת - לשון הקדש. ובתרגום יונתן ב\"ע, כתב, בלשן קודשא הוו ממללין דאתבריא ביה עלמא מן שרויא.","b":false},{"t":"עו\"כ רש\"י ז\"ל, ודברים אחדים - באו בעצה אחת, ואמרו, לאו כל הימנו שיבור לו את העליונים, נעלה לרקיע ונעשה עמו מלחמה וכו', ע\"ש.","b":false},{"t":"והנה הקב\"ה ראה אותם שהם מתכנסים לעשות עמו מלחמה, ורצה להפר את עצתם ולקלקל את מחשבתם אשר חשבו לרעה [ועיין בדברי אוה\"ח הקדוש על זה]. והקב\"ה כביכול ירד לראות את מעשיהם, ואמר, \"הן עם אחד ושפה אחת לכולם\", ועתה לא יבצר מהם כל אשר יזמו לעשות. והדבר פלא וכי מפני שהם עם אחד ושפה אחת יוכלו להלחם בו ח\"ו, ובשלמא אם היתה מחשבתם להלחם בבני עם אחר, היה שייך לומר שמכיון שהם מאוחדים ומלוכדים, כחם גדול ורב, ולא יבצר מהם לעמוד נגד עמים אחרים. אבל על מחשבתם הרעה והאוילית שאמרו נעלה לרקיע ונעשה עמו מלחמה, העל זה שייך לומר, לא יבצר מהם.","b":false},{"t":"ויתרה מזו אמר הי\"ת, הבה נרדה ונבלה שם שפתם, ואח\"כ נאמר ויפץ ה' אותם על פני כל הארץ, ויחדלו לבנות העיר, ונלמד דרק ע\"י שבלבל הי\"ת את שפתם ונעשה ביניהם פירוד גמור, רק אז הפיצם, וכמ\"ש רש\"י שלא ישמעו זה את זה, זה שואל לבנה וזה מביא לו טיט, וזה עומד עליו ופוצע את מוחו. ורק אחר שנהיה פירוד ביניהם, בא הי\"ת והפיצם על פני כל הארץ וחדלו מבנינם. אבל בלאו הכי \"לא יבצר מהם\".","b":false},{"t":"ומזה רואים כמה גדול כחה של אחדות עד שאפילו שהתקבצו לעשות עברה חמורה, למרוד ולהלחם במלכות שמים, בכ\"ז, הקב\"ה לא מנעם, ורק אחר שגרם להם פירוד הפיצם. וכן איתא (ב\"ר לח, ו במדב\"ר יא, ז ומסכת ד\"א זוטא פ\"ט וראה מסכת כלה פ\"ח), על הפסוק (הושע ד, יז), חבור עצבים אפרים הנח לו, היה רבי אלעזר הקפר אומר אהוב את השלום ושנא את המחלוקת. גדול השלום, שאפילו עובדין עבודה זרה ויש שלום ביניהן, כביכול אין שכינה יכולה לנגוע בהן, שנאמר, חבור עצבים אפרים הנח לו, ומזה נלמד על מעלת האחדות כשהיא באה עבור עבודת הי\"ת, לעשות את רצונו.","b":false},{"t":"[א\"ה ראוי להביא בכאן דבר נורא שראיתי משם הרה\"ק ר' משולם פייבוש מזבאריז זלה\"ה מחבר ספר יושר דברי אמת, שכתב, כי כד נייח נפשיה דהרב הקדוש ר\"י בעש\"ט זיע\"א, היו יושבים תלמידיו לפניו, והיה הבעש\"ט ז\"ל נאנח ואומר, כי קודם ביאת משיח צדקנו יהיו נסיונות נוראים באמונה, ורבים לא יעמדו בנסיון ח\"ו, והיה מצביע על תלמידיו ואומר אף אנשים כמוכם ובדרגתכם לא יוכלו לעמוד, והתחילו בני החבריא קדישא לבכות, ואמרו רבינו מה יהא עלינו, ואז אמר להם שיש להם תקוה רק אם יהיו יחד בחבורה אחת בעבודת ה', אזי ינצלו מהנסיונות הנוראים האלו. והדברים נוראים למתבונן בהם. יבח\"ר].","b":false}]},{"id":"13","t":"לא לתת ליצה\"ר מקום אפילו במחשבה","p":[{"t":"וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כָּרֶם, וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה: (ט, כ-כא)","b":true},{"t":"ובתרגום יונתן בן עוזיאל איתא, ושרי נח למהוי גבר פלח בארעא, ואשכח גופנא דמושכיה נהרא מן גינוניתא דעדן ונצביה לכרמא וביה ביומא אניצת ובשילת ענבין ועצרינון, ע\"כ. [תרגום: נח חשב להיות עובד אדמה ומצא גפן שמושכת מן הנהר מגן עדן ונטע מהם כרם, ובו ביום הנצו ענבים והִבְשִילוּ וסחטם]. והנה באמת כך נראה מלשון הפסוק שתיכף ומיד כשנטע כרמו, מיד שתה ונשתכר וכו'. וע\"כ למדו חז\"ל שבאותו יום גדלו הענבים והבשילו, ובאותו היום סחטם והיו ליין, ושתה והשתכר ויתגל בתוך אהלו.","b":false},{"t":"ואם נפרש כפשוטו של מקרא, שהחל בנטיעה שבודאי התארכה ימים, ואח\"כ המתין עד שצמחו פירות ועד שהבשילו וכו' ובודאי היה זמן של חדשים לא מעטים, ואח\"כ דרך את הענבים בגת והוציא מהם משקה, ואחר כך סיננו, ואחר הכניסו לשימור, וכל זה היה בזמן ארוך, וא\"כ צריך להבין את הקיצור המופלג שנקטה התורה בספרה את הדבר הזה, עד שנראה שבאותו יום נעשה הכל.","b":false},{"t":"ונראה בזה דהתורה באה לעורר הלבבות, שאל יאמר אדם, מה לי להבהל מכל דבר, אדרבא, אחל בנטיעת הכרם, ועד שיצמח ויעשה פירות יעברו עידן ועידנים, ועד אז תאוותי תשתכך. ולימדתנו התורה הק' שאין הדבר כן. וחובה על האדם לגדוע את מחשבת החטא בעודנה באיבה, ואם לא יעשה כן הוא עלול למצוא את עצמו טובע בים חטאו, וזהו שנאמר \"ויחל נח ויטע כרם\" שנח חשב ליהנות מן היין, ועוד קודם שראה את היין היוצא מכרמו, כבר נאמר בו \"ויחל\" לשון חילול, שנתחלל מקדושתו וצדקתו שהיו בו קודם, ובעודו חושב מחשבת חטא, כבר לא היה בו כח לעצור את עצמו, ונאמר בו וישכר ויתגל וגו', ונשאר הדבר לדראון עולם, רח\"ל.","b":false}]},{"id":"13","t":"השאננות שאחרי ההתעלות","p":[{"t":"וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כָּרֶם, וַיֵּשְׁתְּ מִן הַיַּיִן וַיִּשְׁכָּר וַיִּתְגַּל בְּתוֹךְ אָהֳלֹה: (ט, כ-כא)","b":true},{"t":"האדם הוא בבחינת \"מהלך\", ואינו עומד כמלאכים, שלעולם נשארים באותה מדריגה, אלא עשוי להשתנות בכל עת, הן לטובה והן לרעה, וזו תוצאה ישירה מעצם היות האדם בעל בחירה חופשית, לבחור בעצמו את הדרך בה ילך.","b":false},{"t":"הרבה עמל ויגיעה, והתבוננות תמידית ברב זהירות וזריזות, משקיע אדם עד שעולה במדריגה, וכשכבר הצליח ה' בידו ועלה, מיד צריך שוב להתחיל בעבודה מחודשת לעלות למדרגה יותר גבוהה, תוך כדי ביסוס וחיזוק המדריגה אותה השיג זה עתה, בבחינת ילכו מחיל אל חיל (תהלים פד, ח).","b":false},{"t":"אכן דוקא אחר התעלות והתרוממות הנפש צריך עירנות גדולה לעמוד על המשמר, שלא יתן האדם ליצרו מקום, לבא ולקלקל את הבנין שאותו בנה זה עתה, בעמל ויגיעה.","b":false},{"t":"כי כל זמן שהאדם עסוק במלחמת היצר כדי להשיג את אותה מדריגה עליונה, הריהו הולך ומתחזק ומתגבר כדי להשיג את מה ששם לו למטרה. אמנם אחר שהשיג את הדבר מיד בא לו רפיון, כי האדם רוצה לנוח מעט מן המתח ומן ההתאמצות, ואז נכנס לשלוה מסוכנת, בחושבו שהוא כבר בעל המדריגה הנכספת, ושוב אין מפריע בעדו, והוא מניח את נשקו מעליו, ומסיח את דעתו מיצרו.","b":false},{"t":"אך דוקא אז היצה\"ר מתגבר ומתחזק לנצל את הרפיון הזה כדי להפתיעו ולקררו, בחינת אשר קרך בדרך (דברים כה, יח), ויכול מיד להורידו ממדריגתו. וכל הישגיו הופכים לאין והיו כלא היו. וכמו שדרשו רז\"ל (חגיגה טו, א ואדר\"נ פכ\"ד), על הפסוק לא יערכנה זהב וזכוכית ותמורתה כלי פז (איוב כח, יז). שדברי תורה קשה להשיגם יותר מן הזהב, ונוח לאבדם ככלי זכוכית.","b":false},{"t":"ואת זה ראינו בענין נח, שמתחילה היה בעל מדריגה גבוהה, איש צדיק תמים וכו' (בראשית ו, ט). ועוד עלה ונתעלה למדרגת נבואה. וזכה שהקב\"ה ידבר עמו ויגלה לו עתידות, ועוד זכה לינצל הוא ובניו מכל בני דורו. וזכה שעל ידו ניצל העולם, וממנו הושתת העולם מחדש. ולאחר המבול עלה עוד מדריגה, ע\"י עבודת ה' בהקריבו את הקרבנות, עד שהקב\"ה כרת עמו ברית שלא יביא עוד מבול לעולם. וזו ודאי מדריגה גבוהה ביותר, שבזכותו ניצל העולם כולו ממבול עד סוף ימי העולם, וא\"כ הרי אדם שהגיע לגדולה כזאת, לכאורה אין לו יותר מה לפחד.","b":false},{"t":"וכן קרה עם נח, אחרי כל העמל הגדול שהשקיע בבנין התיבה במשך מאה ועשרים שנה, ואחר השנה שישב בה עם חיות ובהמות וכו', רפו ידיו ממלחמת האדם ביצרו, וישב בשקט ושלוה, וירא מנוחה כי טוב, ונצטייר בדמיונו שהגיע אל השלוה ואל המנוחה. ואז מצא היצה\"ר מקום לחדור ללבו ולהורידו ממדרגתו.","b":false},{"t":"ותחילה בא אליו בעצה לנטוע כרם, כשהכונה ליהנות ולמלאת את תאוותיו החומריות, שכן עתה כבר אין מבול, והוא ובניו יחידים עלי אדמות באין מפריע, וא\"כ זו השעה הכשרה שישתה וישכח רישו, [וכפי שהדגשתי לעיל במאמר א' שעצם הנטיעה כבר היתה מצד \"איש האדמה\" שבו]. וכשכבר התחיל בזה, אז ירד עוד עד שהגיע למה שהגיע, עד שנכתב עליו בתורה וישכר ויתגל וגו' (בראשית ט, כא), והונצח הדבר לדראון עולם, רח\"ל. וכ\"ז דוקא אחר עלותו למעלות כ\"כ גבוהות.","b":false},{"t":"ובזה אמרתי ליישב מה ששמעתי להקשות בשם הגה\"צ ר' שלום מרדכי שבדרון זצ\"ל, בענין מה שאומרים ביום כיפור, ברוך שם כבוד מלכותו לעולם ועד בקול, כי אנו דומים למלאכים. והוא ז\"ל הקשה, איך במוצאי יום כיפור, אחר התענית של כל היום וכל החמשה ענויים, ואחר כל התפילות והוידויים, אנו אומרים בשכמל\"ו בלחש, והלא אז אנו קרובים ודומים למלאכים יותר מליל כיפור בו היינו שבעים וחזקים, וא\"כ היה צריך לנהוג בהיפך ולומר במוצאי יוה\"כ בשכמל\"ו בקול רם. ובמקום אחר כתבתי את התירוץ שלו. וגם תירוץ אחר עפ\"י שיטת הרמב\"ם ז\"ל, והוא בעניני יום הכיפורים.","b":false},{"t":"ברם ע\"פ הנ\"ל ניתן להבין את הדבר בטוב בחמלת ה' ברוך הוא. כי דוקא אחר כל התפילות והוידויים, והרהורי התשובה המתעוררים בנו בכל עוז ביום הכיפורים, ואחר כל הקבלות שאדם מחליט ומקבל על עצמו, דוקא אז יש סכנה שיבא לידי רפיון מתוך הרגשת סיפוק, שב\"ה התפללנו טוב וחזרנו בתשובה, וה' הטוב קיבל ברצון את תפילותינו. ויש סכנה שהיצה\"ר ימצא מקום לקרר את כל העבודה, בה התחלנו עוד מימי אלול, והגענו לשיאה ביוה\"כ. ויתחיל היצה\"ר להורידנו מטה מטה. על כן, כבר אז אנו אומרים בשכמל\"ו בלחש, להזכירנו שוב, שאנו בנ\"א שיכולים לעלות ויכולים גם לרדת, ולא כמלאכים העומדים במקומם. וממילא צריך תמיד להיות נכונים למלחמה הגדולה בכל עת ללא הרף וללא מנוחה.","b":false},{"t":"כי לא כמלחמות בני האדם היא המלחמה הזו, שבשאר המלחמות יש זמן שצריך לנוח ולהרפות מן המתח, כדי להתחזק ולהמשיך הלאה, משא\"כ במלחמה זו אם יאמר האדם לעצמו אנוח מעט, מיד קם עליו היצה\"ר ומקררו בעבודת ה', כמו שנאמר (דברים כה, יח), אשר קרך בדרך ואתה עיף ויגע, במה מקרר אותך, בזה שנותן לך הרגשה של \"עיף ויגע\". וכשיש עייפות מהמלחמה אז אין יר\"ש. \"ואתה עייף ויגע ולא ירא אלהים\", שכשאתה חושב עצמך שכבר הינך עייף ויגע וצריך לנוח, אז ולא \"ירא אלהים\", כי אז מתחזק היצר בכל כחו, להפוך הקערה על פיה, ומתוך ההתעלות והתרוממות הנפש שבו נמצא האדם אחר יום הכיפורים, שזה צריך להוות מקור עידוד, להמשיך ולהתעלות מחיל אל חיל, יכול היצה\"ר להפוך את זה ח\"ו לתחילת ירידתו וניתוקו מהמלחמה, והיצה\"ר לא נח ולא שוקט, רק הולך ומתגבר עליו, עד שכובשו כליל, רח\"ל.","b":false},{"t":"ואולי גם זה כלול בתוך תפלת \"השכיבנו\" שאומרים בערבית, והסר השטן מלפנינו ומאחרינו, \"מלפנינו\" שלא יעכבנו מעשות המצוה, ולא ימנע אותנו מלעלות בעבודת ה' ומלימוד התורה בעמל. \"ומאחרינו\" שלא נתקרר ונרד אחר שכבר עלינו לאותה דרגה, או אחר שעשינו איזו מצוה או מעשה טוב, שעליו נלחמנו עם יצרנו. והי\"ת יעזרנו שלא נפול בידו, אלא נמשיך ונתמיד בעלייתנו להתקרב אל ה' ולדבקה בו כל הימים אמן.","b":false}]},{"id":"13","t":"מתי נבראה הקשת","p":[{"t":"וַיֹּאמֶר אֱלֹהִים זֹאת אוֹת הַבְּרִית אֲשֶׁר אֲנִי נֹתֵן בֵּינִי וּבֵינֵיכֶם וּבֵין כָּל נֶפֶשׁ חַיָּה אֲשֶׁר אִתְּכֶם לְדֹרֹת עוֹלָם, אֶת קַשְׁתִּי נָתַתִּי בֶּעָנָן וְהָיְתָה לְאוֹת בְּרִית בֵּינִי וּבֵין הָאָרֶץ: (ט, יב-יג)","b":true},{"t":"יש לדקדק כי בתחילה נאמר \"אשר אני נותן\" והוא לשון הווה ולא לשון עבר, ואילו תיכף אח\"כ אומר \"את קשתי נתתי בענן\" והוא לשון עבר ומשמע שכבר היה קודם.","b":false},{"t":"ורבינו אברהם ן' עזרא ז\"ל כתב, שאין פירושו כאשר אמר הגאון כי בתחלה היתה הקשת, אלא נתתיה עתה. עו\"כ על הפסוק (בראשית ט, יד), ונראתה הקשת, אילו היינו מאמינים בדברי חכמי יון, שמלהט השמש תולד הקשת, יש לומר כי השם חיזק את אור השמש אחר המבול, והיא דרך נכונה למבין. עכתד\"ק.","b":false},{"t":"והנה מתחילה כתב שדברי הגאון אינם מוכרחים, דאע\"ג דכתיב \"נתתי\", אין להכריח מזה שכבר היתה בתחילה, אלא אפשר לפרש נתתי עתה. ומ\"מ שב וכתב את דברי חכמי יון שמפרשים איך נוצרים צבעי הקשת וצורתה, שהוא ע\"י להט השמש אל תוך העננים, ואז משתקפת הקשת מכח הטבע שהטביע הקב\"ה בבריאה מראשית בריאת העולם. וע\"ז אמר שאם נקבל דבריהם, אזי יש לפרש שהי\"ת חיזק את אור השמש אחר המבול, ובזה נתגלתה הקשת לעין כל רואה, וזה הוא שאמר הכתוב \"את קשתי נתתי בענן\".","b":false},{"t":"והרמב\"ן ז\"ל גם כן חקר בדבר, אם הקשת היתה במעשה בראשית, או שהי\"ת יצר אותה מחדש בזמן הברית הזאת, וכתב שמהפסוק, אשר אני נותן, משמע שלא היה קשת במעשה בראשית, ועתה ברא ה' חדשה לעשות קשת בשמים ביום ענן, וע\"ש עוד מש\"כ בזה.","b":false},{"t":"ואחר זה כתב שבעל כרחינו נאמין לדברי היונים, שמלהט השמש באויר הלח יהיה הקשת בתולדה, כי בכלי המים לפני השמש יראה כמראה הקשת. וכשנסתכל עוד בלשון הכתוב נבין כן, כי אמר, את קשתי \"נתתי\" בענן, ולא אמר \"אני נותן\" בענן, וגם מלת \"קשתי\" מורה שהיתה לו הקשת תחלה, וכך הפירוש, הקשת אשר נתתי בענן מיום הבריאה, תהיה מן היום הזה והלאה לאות ברית ביני וביניכם. ואם תבקש טעם נתינת האות בקשת, הוא כטעם עד הגל הזה ועדה המצבה וגו' (בראשית לא, נב), וע\"ש שהאריך בזה, וכתב שיש לרבותינו בבראשית רבה סוד בענין, ע\"ש בדב\"ק.","b":false},{"t":"והעולה מדבריו ז\"ל דמסכים לדברי היונים שאכן נראית הקשת מכח להט השמש באויר בלח, וזה מכלל מעשה בראשית, וכתב שכן נראה מהפסוק, שהרי כתוב \"נתתי\", היינו, שכבר נתן מעת שברא העולם, ואותה קשת שהיתה מאז, קבעה מעתה לאות ברית בינו ובינינו.","b":false},{"t":"וכבר קדמו בזה הראב\"ע ז\"ל, וכתב דאחר המבול חיזק הקב\"ה את אור השמש. וזה בנוסף למה שכתב הרמב\"ן ז\"ל, שהי\"ת קבע את הקשת לאות ברית, עוד זאת עשה, שחיזק את אור השמש, וכנראה שעל ידי חזוק זה, מתגלים צבעי הקשת ביתר חוזק עד שהקשת נראית לעיני בני אדם.","b":false},{"t":"וכתב רבנו עובדיה ספורנו ז\"ל, את קשתי נתתי בענן, סדרתי שיהיה בטבע. והיתה לאות ברית, בהיות הקשת כפולה כי אמנם נלאו חכמי המחקר לתת טעם לצבעי הקשת השנית, אשר הוא על היפך סדר צבעי הקשת הראשונה המורגלת, והיא תהיה אות לצדיקי הדור שדורם חייב, כאומרם (כתובות עז, ב), כלום נראתה הקשת מימיך, ויתפללו ויוכיחו וילמדו דעת את העם. ע\"כ.","b":false},{"t":"ונמצא שעיקר האות הוא להודיע לצדיקי הדור שיעוררו לב העם לשוב אל ה', ולהתפלל על הדור.","b":false}]},{"id":"13","t":"חיוב בן נח בהריגת עוברין ומצות פריה ורביה","p":[{"t":"שֹׁפֵךְ דַּם הָאָדָם בָּאָדָם דָּמוֹ יִשָּׁפֵךְ כִּי בְּצֶלֶם אֱלֹהִים עָשָׂה אֶת הָאָדָם, וְאַתֶּם פְּרוּ וּרְבוּ שִׁרְצוּ בָאָרֶץ וּרְבוּ בָהּ: (ט, ו-ז)","b":true},{"t":"ותירגם אונקלוס, דישוד דמא דאנשא בסהדין, דמיה יתשד וכו'. ובתרגום יונתן בן עוזיאל תירגם, דיישוד דמא דאנשא בסהדין, דייניא מחייבין ליה קטול, ודיישוד בלא סהדין, מרי עלמא עתיד לאתפרעא מיניה ליום דינא רבא וכו'. וכעין זה כתב רש\"י, וז\"ל, אם יש עדים המיתוהו אתם, למה, כי בצלם אלהים וכו'. עכ\"ל. וגם הרמב\"ן ז\"ל כתב ויהיה דמו נדרש בבית דין ובידי שמים. ע\"ש.","b":false},{"t":"ובגמרא (סנהדרין נז, ב), תני משום ר' ישמעאל אמרו, בן נח חייב על העוברין, שנא' שופך דם האדם באדם דמו ישפך. איזה הוא אדם באדם, הוי אומר עובר שבמעי אמו.","b":false},{"t":"והנה לפי זה יובן למה נאמר בפסוק הסמוך לו, ואתם פרו ורבו וגו'. לומר דהזהיר על העוברים, והסמיך לזה מצות פרו ורבו, כלומר להמנע מהריגת עוברים, וגם לעסוק בפו\"ר. ודו\"ק.","b":false},{"t":"* * *","b":false},{"t":"חומר המלבין פני חברו ברבים","b":true},{"t":"הבושה היא כפרת עוונות","b":true},{"t":"וראיתי להקדוש רבינו מהר\"מ אלשיך ז\"ל שפירש פסוק זה על המלבין פני חברו ברבים דאזיל סומקא ואתי חיורא, כי בשעה שמביישו הדם רותח ועולה במהירות לראשו ופניו מאדימים, וכיון שעלה הדם שלא לפי הרגלו ומחזורו, לכך הריהו יורד במהירות אל הגוף, ואז הפנים מחוירות ונעשות לבנות, ועל כן המלבין פני חברו ברבים שהבושה גדולה חשוב כשופך דם. וזה פירוש הכתוב שופך דם האדם באדם, כלומר ששפך דמו, אך לא על הארץ, אלא שפך דמו בתוך גופו, כי הדם יורד מהראש אל הגוף למטה. וזה שיעור הכתוב, \"שופך דם האדם\", והיכן שפיכות הדם הזאת, \"באדם\"! הי\"ת יצילנו מזה. כי עונש המלבין מפורש אחריו, דמו ישפך, רח\"ל.","b":false},{"t":"ולפי\"ז י\"ל דלכך נאמר בפסוק, שטעם הדבר שנקרא שפיכות דם, לפי שהאדם במראה פניו נבדל מכל בעלי החיים, והמבייש שפך את הדם שבצלם אלהים בהלבינו את פניו, ולכך דמו ישפך רח\"ל (וראה עוד פר' וישב מאמר ח).","b":false},{"t":"ושמעתי שהרה\"ק רבינו משה קורדובירו זיע\"א כתב באחד מספריו, שכשנגזר על אדם מיתה רח\"ל, והוא שב בתשובה, ומתעוררים עליו מן השמים ברחמים, והקב\"ה רוצה לכפר לו ע\"י יסורים, אזי מביא עליו בזיונות ומכפר לו על המיתה, ונותן לו דבר החולף, ומעביר ממנו גזרת המות. והטעם כתב שם, כי הבזיון ובפרט ברבים הוא אחד הדברים הקשים ביותר, והוא קרוב למיתה רחמנא ליצלן מכולם, אלא שהוא חולף בעבור הזמן, ומכפר גזירת המות. והאדם מצטער ולפעמים גם מתרעם על הבזיון שנפל עליו, ולא ידע שבזה היתה לו הצלה גדולה שנתבטלה מעליו גזירת מיתה, וזכה לחיים, ועל כגון זה אמרו חז\"ל (נדה לא, א), אין בעל הנס מכיר בנסו.","b":false},{"t":"ויש להביא בזה עוד את דברי החסיד מהר\"א פאפו ז\"ל בספרו הנפלא פלא יועץ (ערך בזיון), וז\"ל, אם יבזוהו אחרים אל יקפיד כלל ואל יצא לריב, אלא אז ידכה ישוח. ויאמר, זה לי האות שאני נתעב ונאלח לפני הבורא מחמת עוונותי ושלח לבזות אותי ע\"י האיש הזה, כי ה' אמר לו קלל. ומצד אחר ישמח לבו, כי ה' חפץ דכאו ביסורין קלים כאלו שאין בהם חסרון כיס, לכלה פשע ולהתם חטאת, וכבוד גדול עשו לו מן השמים, ובלבד שיקבלם מאהבה, ויהא שמח ביסורין כאלו. וכבר אמרו רבותינו (גטין לו, ב), שעל אנשים כאלה הכתוב אומר (שופטים ה, לא), ואוהביו כצאת השמש בגבורתו. עכ\"ד ודפח\"ח.","b":false}]},{"id":"13","t":"הדבקות בהי\"ת היא מקור החיים","p":[{"t":"וּמוֹרַאֲכֶם וְחִתְּכֶם יִהְיֶה עַל כָּל חַיַּת הָאָרֶץ וְעַל כָּל עוֹף הַשָּׁמָיִם בְּכֹל אֲשֶׁר תִּרְמֹשׂ הָאֲדָמָה וּבְכָל דְּגֵי הַיָּם בְּיֶדְכֶם נִתָּנוּ. (ט, ב)","b":true},{"t":"רבותינו אמרו (שבת קנא, ב בראשית רבה לד, יז), רבי שמעון בן אלעזר אומר, תינוק בן יומו חי, אין צריך לשומרו מן החולדה ומן העכברים, אבל עוג מלך הבשן מת, צריך לשומרו מן החולדה ומן העכברים, שנאמר, ומוראכם וחתכם יהיה וגו', כל זמן שאדם חי, אימתו מוטלת על הבריות, כיון שמת בטלה אימתו. ע\"כ.","b":false},{"t":"וראיתי בחומש רב פנינים (בראשית ט, ב), שהביאו על הענין הזה מספר שער בת רבים שהקשה, והלא ראינו כמה אנשים שהמית אותם אריה וכיוצא בו.","b":false},{"t":"ותירץ דהי\"ת ברא את האדם בצלם אלהים על פניו, וכשהוא שומר תורה ומצות, הריהו שומר בזה את צורתו וצלמו צלם אלהים שבו בקדושה ובטהרה. ואז יראים ממנו כל הבעלי חיים ולא ישלטו בו, וכמו שנאמר (תהלים צא, יג), על שחל ופתן תדרוך וכו'. וכמו שמצינו ביוסף הצדיק שהשליכוהו לבור מלא נחשים ועקרבים ולא הזיקוהו כלום, ודניאל הנביא הושלך לגוב האריות ולא הזיקוהו. והרב אוה\"ח הק' הושלך לגוב אריות וניצול ממנו, והיה ע\"ז קידוש ה' גדול [ובשם הגדולים לרבינו החיד\"א ז\"ל הביא מעשה זה על רבינו יהודה בן עטר מעי\"ת פאס שהיה גדול הדור בימיו של הרב הקדוש בעל אור החיים והיו קוראים אותי \"רבי אלכביר\" (הרב הגדול). והוא ובית דינו כתבו את כתב ההסכמה הראשונה לספר אור החיים הקדוש, וכתב לו החכם השלם כה\"ר חיים ן' עטאר. והרב אור החיים עליו השלום ביקש שיוסיף לו אות אחת כדי שיקנו את הספר, ובמקום כה\"ר יכתוב לו כמוה\"ר, ושם היו מדקדקים מאד בתוארים עד כחוט השערה. והשיבו במליצה ואמר לו אני אמרתי \"כה'ר ה' \" ואתה רוצה \"כמוה'ר הבתולות\", ולבסוף לא הוסיפו לו האות. והרב רבי יהודה היה אב\"ד מקודש בפאס. ועמו ישב בדין היעב\"ץ ה\"ה רבי יעקב ן' צור בעל שו\"ת משפט וצדקה ביעקב ועוד. ועי' בספר מלכי רבנן לר\"י ן' נאיים ז\"ל בערך רבנו חיים בן עטר, ודו\"ק], אמנם האדם אשר יחטא ונמשך תמיד אחר תאוות העוה\"ז, אז נשתנה צורת פניו והוא נמשל כבהמה, והוא קטן ושפל מהבעלי חיים, והיה כל מוצאו יהרגהו עפ\"י דרך הטבע, שהגיבור יעוז על החלש, ורוב הבעלי חיים חזקים מהאדם, עכת\"ד יעו\"ש דברים מתוקים מדבש.","b":false},{"t":"[א\"ה - כאן המקום להביא מעשה נפלא שהיה עם הרב הגדול מלך ירושלים וראשון לציון הגאון הקדוש רבי רפאל מאיר פאניז'יל זצוק\"ל מחבר הספר הנפלא לב מרפ\"א, והמעשה הזה נזכר בספר זכות אבות להג\"ר מנחם נתן נטע אוירבאך ז\"ל נכדו של הגאון בעל \"אמרי בינה\" ששמע את המעשה מפי הגאון המרפ\"א ז\"ל, וסיפר אותו בהספדו עליו. וזה הענין, כי בשנת תר\"א יצא הגאון המרפ\"א בשליחותא דרבנן לערי תוניסיה לקבץ ממון עבור חכמי ירושלים ובניה שרובם עסקו בתורה, ובהיותו בעיר תונס שמע כי ישנו שם גן נפלא ליד ארמון המלוכה, והרב הקדוש רצה לפוש מעט, וביקש מן הרב מרא דאתרא אם יוכל ללוותו אל הגן, הרב מרא דאתרא נענה לבקשתו, וצירף עוד כמה גבירים עמו, וילכו יחד אל הגן, כדי להנעים את שהותו של הרב המרפ\"א ז\"ל, והנה בהגיעם אל הגן ראו שומרים עומדים חוצה, ואין מניחים לשום אדם להכנס, באומרם כי תם זמן הביקור והגן סגור למבקרים, ויפצירו בהם מלוי הרב להכניסם אל הגן פנימה. אך השומרים אמרו כי לא יוכלו להכניסם, כיון שבשעות הסגירה מסתובבים בגן שני כלבים איומים, ובראותם אדם זר תיכף יתנפלו עליו ויקרעוהו לגזרים. עודם מדברים עמהם, והרב המרפ\"א חמק עבר ונכנס אל הגן לבדו, והנה כל מלוי הרב המרפ\"א ושומרי הגן חרדו מאד, כי הנה עוד מעט קט יקפצו עליו הכלבים ויקרעוהו לגזרים רח\"ל. אך להפתעתם כי רבה, אחר כמה רגעים ראו את הרב הקדוש המרפ\"א צועד לו בנחת והכלבים אחריו, ושלשלאותיהם תפוסות לו בידיו, ונראים ככבשים ולא ככלבים. והמה ראו כן תמהו על המראה הנורא, וישאלהו הרב מרא דאתרא אם השתמש בקבלה מעשית כדי להכניעם או הזכיר איזה שם קדוש, ויאמר לו הרב הקדוש מרפ\"א ז\"ל, חלילה! חלילה לי מעשות כן! אלא שמימי לא פגמתי באות ברית קודש, ומקרא מלא כתיב (בראשית ט, ב), ומוראכם וחתכם יהיה על כל חית הארץ ועל כל עוף השמים וגו', ואני ששמרתי על קדושתי נשאר בי צלם אלהים בשלימות ולכן אינני ירא משום בריה בעולם שתזיקני, ע\"כ המעשה. ובאמת מצינו לרבותינו שאמרו (שבת קנא, ב סנהדרין לח, ב), אין חיה שולטת באדם אלא אם כן נדמית לו כבהמה. ע\"ש.","b":false},{"t":"ובזוה\"ק (בראשית עא, א), הרחיבו דברים בזה, וז\"ל הקדוש, ומוראכם וחתכם יהיה, מכאן ולהלאה יהא לכון דיוקנין דבני נשא דהא בקדמיתא לא הוו דיוקנין דבני נשא וכו' כיון דחטו אשתנו דיוקנייהו מההוא דיוקנא עלאה, ואתהפכו אינון למדחל מקמי חיוון ברא, בקדמיתא כל בריין דעלמא זקפן עיינין וחמאן דיוקנא קדישא עלאה, וזעאן ודחלין מקמיה, כיון דחטו אתהפך דיוקניהו מעינייהו לדיוקנא אחרא, ואתהפך, דבני נשא זעין ודחלין מקמי שאר בריין.","b":false},{"t":"תא חזי כל אינון בני נשא דלא חטאן קמי מאריהון ולא עברין על פקודי אורייתא, זיו דיוקנא דלהון לא אשתני מחיזו דדיוקנא עלאה, וכל בריין דעלמא זעין ודחלין קמיה, ובשעתא דבני נשא עברין על פתגמי אורייתא, אתחלף דיוקנא דלהון, וכלהו זעין ודחלין מקמי בריין אחרנין, בגין דאתחלף דיוקנא עלאה, ואתעבר מנייהו, וכדין שלטי בהו חיות ברא, דהא לא חמו בהו ההוא דיוקנא עלאה כדקחזי. ועל כן השתא כיון דעלמא אתחדש כמלקדמין, בריך לון ברכתא דא, ושליט לון על כלא וכו'. ע\"כ. יבח\"ר].","b":false},{"t":"ונמצינו למדים מכל זה, דח\"ו כשהאדם חוטא הריהו פוגם בצלם אלהים ומשתנים פניו עד ששולטים בו החיות, ואם הוא שומר על צלם אלהים שבו, הכל יראים ממנו.","b":false},{"t":"ונחזור לעניננו דמ\"מ יש עדיין הבדל בין אדם חי לאדם מת, כמו שמצינו בדברי רבותינו שנזכרו בתחילת דברינו, שתינוק חי בן יומו אינו צריך שמירה מן העכברים, מה שאין כן \"מת\" אפילו אם הוא עוג מלך הבשן הריהו צריך שמירה. והנה החילוק וההבדל הזה שבין חי למת הוא במובן הפשוט של החיים והמות.","b":false},{"t":"ואולם כידוע ישנו מושג אחר של חיים דהיינו החיים האמיתיים, שעליהם נאמר (ויקרא יח, ה), ושמרתם את חוקותי ואת משפטי אשר יעשה אותם האדם וחי בהם. ובלעדיהם אין החיים קרויים חיים, עד שאמרו רבותינו (ברכות יח, ב), רשעים בחייהן קרויים מתים. וכשזוכה האדם לחיים הללו גם כאשר ימות במיתה טבעית, וגופו ישוב לעפר, מ\"מ חי יקרא, וכמ\"ש צדיקים במיתתם נקראים חיים. ומה נפלאו דברי רבי יהודה הלוי (הנאמרים בפי הכל בתפילת יוה\"כ):","b":false},{"t":"אֱלֹהַי! בְּרַחֲקִי מִמְּךָ מוֹתִי בְּחַיָּי. וְאִם אֶדְבַּק בְּךָ חַיַּי בְּמוֹתִי.","b":false},{"t":"ובודאי שכשזוכה האדם לחיים האלו, להיות דבוק במקור החיים, בבחינת ואתם הדבקים בה' אלהיכם חיים כולכם היום (דברים ד, ד), אז הצלם שלו נשמר בקדושה וטהרה, ופניו מאירים ומזהירים בקדושה דלמעלה, כמו שמצינו בזוהר הקדוש (שמות לח, א), דפני צדיק נקראים פני שכינה, כמו שאמרו שם על הפסוק (שמות לד, כג), יראה כל זכורך את פני האדון ה', מאן פני האדון ה', דא רבי שמעון בר יוחאי, ע\"ש והדברים נפלאים. וכן מצינו לרבינו הקדוש מהר\"מ אלשיך ז\"ל בפירושו לישעיה על הפסוק (ישעיה א, יב), כי תבואו לראות פני. שכתב בתוך דבריו, שהקב\"ה רוצה שנהיה צדיקים וישרים, עד שיראה בפנינו את פניו שלו, דהיינו אפי דשכינתא, כיעו\"ש בדבריו הנוראים. ובודאי דאם האדם זוכה להגיע לזה, כי אז, לא יוכל שום בעל חי לפגוע בו, וכנ\"ל.","b":false},{"t":"ואכן גם בענין ההבדל בין חי למת שאמרו רבותינו, מצינו להם שהזכירו לסימן, אם העכברים מפחדים ממנו או אינם מפחדים. ויש להבין את טעם הדבר שזכרו דוקא \"עכברים\" ו\"חולדה\".","b":false},{"t":"וי\"ל על פי דברי הגמ' שילהי הוריות (יג, א), דעכברים סורן רע, ובירושלמי הובא בתוספות דב\"מ (מ, א ד\"ה וכי מה), איתא דהני עכברי רשיעי נינהו, וראה בספרי המקובלים (ראה אדיר במרום ח\"ב במאמר ז' מלכין – חנן בן עכבור), דהעכברים רומזים על כחות הטומאה והסטרא אחרא. ואף החולדה היא בחינת נוקבא מהסט\"א (וראה חס\"ל מעין ה' נהר ל'), והיא קשה וחזקה יותר מן הזכר, וכמ\"ש האוה\"ח הקדוש בפרשת ויחי (בראשית מט, יא), על הפסוק אוסרי לגפן עירה ולשורקה בני אתונו, יע\"ש שהביא כן מדברי הזוה\"ק (ח\"ג רלא, ב).","b":false},{"t":"ולפי\"ז י\"ל, דהכי קאמר, ד\"תינוק בן יומו חי עכברים יראים ממנו\", היינו שהוא עדיין חי שלא ניתק עצמו ממקור החיים, ולכן אינו צריך שמירה מהעכברים, דהדביקות שלו בה' שהוא מקור החיים נותן לו חיות, ובכחה ניצל מכל העכברים והמזיקים ושאר כחות הטומאה והקלי', אבל אם הוא \"מת\" בחינת רשעים בחייהן קרויין מתים, לא יועיל לו כלום ויאחזו בו כל הטומאות והקלי', ואפי' אם הוא גדול כעוג מלך הבשן, מכל מקום הריהו בבחינת מת, ואז צריך לשומרו מכל אותם כחות הטומאה וסט\"א, ואז כמובן גם יכולים לשלוט עליו האריות והנמרים וכו', ולא יוכל ללכת בלי שמירה. כי אך בצלם יתהלך איש (תהלים לט, ז).","b":false},{"t":"ורבינו חיים פלאג'י זצ\"ל בספרו ובחרת בחיים (פר' נח), הוסיף ואמר דרך דרש, כי מצינו לרש\"י שכתב ומוראכם וחתכם, ואגדה לשון \"חיות\" וכו', ולשון \"חיות\", הוא רמז להם שיהיו צדיקים, על דרך מה שאמרו רבותינו שהצדיקים נקראים חיים. ודו\"ק.","b":false},{"t":"והביטוי האמיתי לחיותו של אדם, היא במה שהאדם שולט בלבו ובתאוותיו ורצונותיו. כי בזמן שלבו שולט עליו, נעשה עבד ליצרו ואסיר תאותו, ושוב אינו נקרא חי, אלא הרי הוא בבחינת מת, דאין חיותו ניכרת כלל, ושלטונו נופל שבי בידי היצר והתאוה, ואין לך מיתה גדולה מזה.","b":false},{"t":"ומצינו במדרש רבה בפרשה זו (לד, י), ויאמר ה' אל לבו, הרשעים הן ברשות לבן, אמר נבל בלבו (תהלים יד, א ושם נג, ב), ויאמר עשו בלבו (בראשית כז, מא), ויאמר ירבעם בלבו (מ\"א יב, כו), ויאמר המן בלבו (אסתר ו, ו), אבל הצדיקים לבן ברשותן, וחנה היא מדברת על לבה (ש\"א א, יג), ויאמר דוד אל לבו (ש\"א כז, א), וישם דניאל על לבו (דניאל א, ח), ויאמר ה' אל לבו לא אוסיף (בראשית ח, כא).","b":false},{"t":"וכנראה דזה מה שקובע אם האדם חי או ח\"ו מת, כי כל זמן שהוא שולט בעצמו ועניניו מתנהלים עפ\"י שיקול דעתו והכרעת שכלו, חי מקרי, לא כן כשחדל לשלוט בעצמו אז נאמר בו אין שלטון ביום המות (קהלת ח, ח), מי שלא שולט בעצמו דומה כאילו מת. \"חוסר שליטה עצמית\" זה הסימן למיתה ומי שהוא כזה שולטים בו אפילו העכברים על הדרך הנ\"ל (וראה עוד מה שנתבאר בזה בפרשת וישלח מאמר ד).","b":false},{"t":"והי\"ת יזכנו להיות תמיד שולטים בלבנו, ומוחנו יהיה תמיד למעלה מהלב, בבחינת ויהי בישורון מלך (דברים לג, ה), \"מלך\" בר\"ת מח, לב, כבד. שהמח ישלוט על הלב והכבד, ונזכה להיות דבוקים בה', וחיים כל הימים אמן.","b":false},{"t":"(מוצש\"ק נח ה' תשמ\"א)","b":false}]},{"id":"13","t":"הליכה בדרכי אבות","p":[{"t":"וַיִּבֶן נֹחַ מִזְבֵּחַ לַה' וַיִּקַּח מִכֹּל הַבְּהֵמָה הַטְּהֹרָה וּמִכֹּל הָעוֹף הַטָּהוֹר וַיַּעַל עֹלֹת בַּמִּזְבֵּחַ: (ח, כ)","b":true},{"t":"ובתרגום יונתן בן עוזיאל כתב, ובנא נח מדבחא קדם ה', הוא מדבחא דבנא אדם בעידן דאיטרד מן גנתא דעדן ואקריב עלוי קרבנא, ועלוי אקריבו קין והבל ית קרבניהון, וכד נחתו מיא דטובענא איתצד, ובנייה נח, ונסב מכל בעירא דכיא ומן כל עוף דכי ואסיק ארבע על ההוא מדבחא, ע\"כ. כלומר, הוא אותו מזבח שבנה אדם הראשון, בעת שגורש מגן עדן, והקריב עליו קרבן, ועליו הקריבו קין והבל את קרבנם. וכשבאו מי המבול נהרס אותו מזבח, וחזר נח ובנה אותו, וזה שאמר ויבן נח מזבח לה', ולקח מכל בהמה טהורה, ומכל עוף טהור, והקריב ארבע על אותו המזבח.","b":false},{"t":"ומזה נראה ונבין את חשיבות ההליכה בדרכי הקדמונים, ולא לחפש אחר דרכים חדשות. צא ולמד מנח, שאפילו שהיה קודם מתן תורה, בכל זאת הבין בדעתו שיש להמשיך ולהקריב על אותו מזבח שזבחו בו הקדמונים. ואף אנו יש לנו ללמוד מהם ולדון ק\"ו בכל הקשור בדרכי אבותינו ורבותינו הקדושים, וכמאמר הכתוב (שה\"ש א, ח), אם לא תדעי לך היפה בנשים, צאי לך בעקבי הצאן ורעי את גדיותיך על משכנות הרועים.","b":false},{"t":"ומעין זה רמזו חז\"ל במאמרם (ברכות ו, ב), כל המשמח חתן וכלה כאילו בנה אחת מחורבות ירושלים, ללמד ששמחת חתן וכלה הצעירים, צריכה להיות מושתתת על יסודות העבר ודרכי אבות קדמונים, ולבנות ולהוסיף נדבך על הבנין הישן, ולא לבנות דברים חדשים אשר לא שערום אבותינו.","b":false}]},{"id":"13","t":"דמיון התיבה לסוכה מדות התיבה - סוד ענינם","p":[{"t":"וְזֶה אֲשֶׁר תַּעֲשֶׂה אֹתָהּ שְׁלֹשׁ מֵאוֹת אַמָּה אֹרֶךְ הַתֵּבָה חֲמִשִּׁים אַמָּה רָחְבָּהּ וּשְׁלֹשִׁים אַמָּה קוֹמָתָהּ, צֹהַר תַּעֲשֶׂה לַתֵּבָה וְאֶל אַמָּה תְּכַלֶּנָּה מִלְמַעְלָה וּפֶתַח הַתֵּבָה בְּצִדָּהּ תָּשִׂים תַּחְתִּיִּם שְׁנִיִּם וּשְׁלִשִׁים תַּעֲשֶׂהָ: (ו, טו-טז)","b":true},{"t":"והגאון הרב מלבי\"ם ז\"ל כתב בפירושו (שם), שמדות התיבה מלמדים על שילוב הוי\"ה ואדנות, בהכפלה זה עם זה, והיינו, י' של הוי\"ה כפול א' של אדנו\"ת עולה עשר. וה' דהוי\"ה כפול ד' דאדנו\"ת, עולה עשרים, ועם העשר הקודמים, הם שלושים כגובה התיבה. ו' דהוי\"ה כפול נ' דאדנו\"ת, עולה שלש מאות והוא אורך התיבה. וה' אחרונה דהוי\"ה כפול י' דאדנו\"ת הם חמשים כמו רחבה של התיבה, עכתד\"ק.","b":false},{"t":"וידוע ומפורסם שהשילוב של הוי\"ה אדנו\"ת הוא מיתוק הדינים, ששם אדנו\"ת הוא אותיות \"דינא\" שהוא מדת הדין, ושם הוי\"ה כולו רחמים, ובשילוב של שם הוי\"ה עם אדנו\"ת מתמתקים הדינים. והן ידוע דדינים ממותקים חשובים ומועילים יותר מרחמים פשוטים.","b":false},{"t":"וכבר אמרו חז\"ל (בראשית רבה יב, טו), שחשב הקב\"ה לברוא עולמו בדין, שנאמר (בראשית א, א), בראשית ברא אלהים וגו', וראה שאין העולם יכול להתקיים בדין, ושיתף רחמים עם הדין, שנאמר (בראשית ב, ד), ביום עשות ה' (הוי\"ה), אלהים ארץ ושמים, ועל כן כשרצה הקב\"ה לרחם על עולמו ולא להשחית את הכל, אמר לו לנח עשה לך תיבת וגו', דהיינו שיעשה תיקון לעולם ולימדו את המדות של התיבה, ורמז לו בה את ענין מיתוק הדינים.","b":false},{"t":"והנה לפי חשבונו של הרב מלבי\"ם ז\"ל נשארה יתרה אמה אחת, דכתיב ואל אמה תכלנה מלמעלה. ולדבריו לא נרמזה אמה זו בחשבון הנ\"ל.","b":false},{"t":"ויש לומר דאין צריך לומר בתחילה י' דהוי\"ה כפול א' דאדנו\"ת, דא\"צ לזה, כיון דבלא\"ה ישאר מנינו עשר, ולכן די לנו לומר שהאות י' הראשונה דשם הוי\"ה היא עשר, ועם ה' דהוי\"ה כפול ד' דאדנו\"ת שהם עשרים, סך הכל שלשים, שהוא גובה התיבה. ונשארה אות א' דאדנו'ת יתרה, לרמוז על האמה ההיא שבגג התיבה. וי\"ל דהאות אל\"ף היא מיתוק, וכמו שמצינו בדברי רבנו האר\"י ז\"ל דשם אדנו\"ת הוא \"דין\" ואות אל\"ף הבאה בתחילתו הריהי ממתקת את הדין, א\"ה וזהו ואל אמה תכלנה מלמעלה. ודו\"ק [א\"ה – כדי להבין דברי מרן המחבר נר\"ו אעתיק לך בזה דברי רבנו האר\"י בעץ חיים שער י\"ח פרק ה' (מהדו\"ת) וז\"ל בתוך דבריו, כי הנה שם אדנ\"י מורה על הדין כנודע, וכן ג' אותיות האחרונות הם \"דין\", ונשאר אות ראשונה שהוא אל\"ף, והוא בחינת הרחמים המשותפים עם הדין שבה, ואות אל\"ף זה מורה ע\"ש אהי\"ה שהוא רחמים, וזה הטעם שנקרא מלכות בספר הזוהר דינא רפיא, לפי שמתחברת דין עם אל\"ף שהוא רחמים כנ\"ל, ואז הוא \"דינא רפיא\" וכו'. ע\"כ לשונו הנצרך לנו. יבח\"ר].","b":false},{"t":"ובאו אותיות הוי\"ה אדנו\"ת משולבים בתיבה, כי צריכים אנו לשלב את הוי\"ה ואדנו\"ת כדי למתק את הדינים, כי שם אדנו\"ת לבד הוא דין (אם כי דינא רפיא, וראה עוד בע\"ח שער לח פ\"ד במהדו\"ת, וטעמי המצוות פרשת קדושים, ופרשת בהר, ובליקוטי תורה פר' האזינו, דשם אדנ\"י הוא אותיות \"דינא\", ועי' שער מאמרי רשב\"י פ' בלק), ולכן באו שניהם יחדיו כדי שיומתקו הדינים מעל הצדיקים.","b":false},{"t":"וידוע דגם בסוכה רמוזים הוי\"ה ואדנו\"ת יחד, כיון דשניהם עולים יחד צ\"א כמנין \"אמן\", וכן \"סוכה\" מלאה וי\"ו עולה צ\"א כמנין הוי\"ה אדנו\"ת.","b":false},{"t":"[א\"ה - אמנם בתהלים (עו, ג), מצינו ויהי בשלם \"סוכו\" ומעונתו בציון, וחוץ מזה לא מצינו סוכה מלא, והנה \"סוכו\" עולה בגימ' צ\"ב ולא צ\"א. אמנם נראה דאין זה מן הקושי, כי \"סוכו\" דתהלים היינו סוכה שלו, כאשר תוכיח אות וי\"ו אחרונה, אבל כשלעצמה הוא \"סוכה\" מלא וי\"ו, שהרי נזכר גם אות וי\"ו בראשונה. ועי' היטב בשער הכונות בענין סוכות דרוש ד' וכנראה שעל זה סמך. ע\"ש. ואולי יש לרמוז בפסוק ויהי בשלם \"סוכו\" היינו שיושלם שם הוי\"ה אדנות, ויתקיים בנו ביום ההוא יהיה ה' (אדנו\"ת), אחד ושמו (הוי\"ה), אחד, היינו ששמותיו יתברך והוא יהיו הכל אחד וזהו \"סוכו\" הוי\"ה אדנו\"ת ועמו יתברך עולה כמנין צ\"ב, או אז יושלם הענין, ונזכה ל\"ומעונתו בציון\", ונבנתה עיר על תילה, ירושלים בנויה בנין עולם, בב\"א. יבח\"ר].","b":false},{"t":"וכן הוא מאמר המשורר שנתפרסמו שיריו בישראל הוא ניהו הרב הגדול רבי דוד חסין ע\"ה בשירו המפורסם \"סוכה ולולב\", וזה לשונו:","b":false},{"t":"ישמח ישראל בצל סוכתו / יסתופף יחסה תחת אברתו / השם ככתבו וכקריאתו / כמספר \"סוכה\" מספרו עלה.","b":false},{"t":"ואמר השם ככתבו (הוי\"ה), וכקריאתו (אדנו\"ת), כמספר \"סוכה\" מספרו עלה. כי מנין שניהם הוא צ\"א.","b":false},{"t":"ונראה לענ\"ד דבתיבת נח שהיא הצלה לכל באי עולם, לכך \"הכפילו\" בה אותיות הוי\"ה באותיות אדנו\"ת. אבל הסוכה שהיא פרטית לכל בית ובית, נרמזו בה שם הוי\"ה ואדנו\"ת ללא הכפלה. וכמו שהתיבה הגינה על נח ובניו מפני מבול המים, גם בסוכה נאמר (תהלים כז, ה), כי יצפנני בסכֹה ביום רעה וגו', וכן הפורש סוכת שלום עלינו (חתימת ברכת ערבית של שב\"ק, ועי' בתיקו\"ז תיקון ו' דף כב ע\"ב), ופרוש עלינו סוכת שלומך, ואומר (ישעיה ד, ו), וסוכה תהיה לצל יומם מחורב ולמחסה ולמסתור מזרם וממטר, וכמו שבתיבה ההגנה וההצלה נעשו ע\"י שתי שמות הקודש האלו, כן נרמזו נמי בסוכה.","b":false}]},{"id":"13","t":"הפרכת טענות החוקרים על \"קדמות העולם\"","p":[{"t":"וַיְהִי הַמַּבּוּל אַרְבָּעִים יוֹם עַל הָאָרֶץ וַיִּרְבּוּ הַמַּיִם וַיִּשְׂאוּ אֶת הַתֵּבָה וַתָּרָם מֵעַל הָאָרֶץ, וַיִּגְבְּרוּ הַמַּיִם וַיִּרְבּוּ מְאֹד עַל הָאָרֶץ וַתֵּלֶךְ הַתֵּבָה עַל פְּנֵי הַמָּיִם, וְהַמַּיִם גָּבְרוּ מְאֹד מְאֹד עַל הָאָרֶץ וַיְכֻסּוּ כָּל הֶהָרִים הַגְּבֹהִים אֲשֶׁר תַּחַת כָּל הַשָּׁמָיִם, חֲמֵשׁ עֶשְׂרֵה אַמָּה מִלְמַעְלָה גָּבְרוּ הַמָּיִם וַיְכֻסּוּ הֶהָרִים, וַיִּגְוַע כָּל בָּשָׂר הָרֹמֵשׂ עַל הָאָרֶץ בָּעוֹף וּבַבְּהֵמָה וּבַחַיָּה וּבְכָל הַשֶּׁרֶץ הַשֹּׁרֵץ עַל הָאָרֶץ וְכֹל הָאָדָם, כֹּל אֲשֶׁר נִשְׁמַת רוּחַ חַיִּים בְּאַפָּיו מִכֹּל אֲשֶׁר בֶּחָרָבָה מֵתוּ, וַיִּמַח אֶת כָּל הַיְקוּם אֲשֶׁר עַל פְּנֵי הָאֲדָמָה מֵאָדָם עַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמַיִם וַיִּמָּחוּ מִן הָאָרֶץ וַיִּשָּׁאֶר אַךְ נֹחַ וַאֲשֶׁר אִתּוֹ בַּתֵּבָה, וַיִּגְבְּרוּ הַמַּיִם עַל הָאָרֶץ חֲמִשִּׁים וּמְאַת יוֹם: (ז, יז-כד)","b":true},{"t":"כתב רבינו בעל אוה\"ח הקדוש זיע\"א, וימח את כל היקום, פירוש, מלבד הגויעה הרמוזה בפסוק שלפני זה, גם נמחה כל מה שהיה עומד מהם באמצעות ריבוי המים, חם וקר (רומז לדברי חז\"ל שנפתחו גם מעינות חמים מן הארץ ראה סנהדרין קח, ב), ונמחה כל הויתן ונעשו כמים, והיו כלא היו בעולם, ובזה נשכיל דברי רבותינו ז\"ל (ברכות סא, א), וז\"ל, אמר רבי אמי אחור וקדם צרתני וגו'. ע\"ש בדברות קדשו.","b":false},{"t":"והנה יש חכמים בעיניהם הטוענים לקדמות העולם, והדברים עתיקים. וכבר השיבו עליהם חכמינו לדורותם, ובימינו נוספו גם חכמי הארכיאולוגיה החוקרים באתרים עתיקים למצא כלים וחפצים וגם עצמות של אדם ובעלי חיים, ובודקים וקובעים זמן לכל דבר ופעמים מדברים באלפים ופעמים גם במליוני שנים, וקובעים את הדבר בבטחון מלא, כאילו היו הם עומדים בעת בריאת אותו בעל חי, או לפחות בעת מיתתו. וזוכרים היטב את מספר השנים שעברו עליו מאז. וכן בחפצים שונים נותנים וקוצבים שנותיהם.","b":false},{"t":"ובהיותי דורש בפני בני הנוער במקומות שונים, היו מעלים קושיות מדברי החוקרים והארכיאולוגים, שהוא מנוגד לאמונתינו הטהורה שהעולם נברא ע\"י הבורא יש מאין, לפני חמשת אלפים ושבע מאות וס\"ז שנים, והארץ היתה תהו ובוהו ולא היה בה מאומה, וה' עשה שמים ויצר ארץ וכל צבאם. כידוע לנו בבירור גמור בלי שום פקפוק כלל.","b":false},{"t":"ויש שתירצו עפ\"י דברי חז\"ל (ב\"ר ג, ז ושם ט, ב וקה\"ר ג, יד), שהקב\"ה היה בורא עולמות ומחריבן, וניסו לומר שהדברים העתיקים הללו הם משארית אותם העולמות. ולא מסתבר כלל, ש\"מחריבן\" פירושו מאבדם, ומלבד שזה לא היה במתכונת זו, ואולי גם לא גשמי כלל, ואפי' תאמר שהיו העולמות ההם גשמיים והיו בהם יצורים, הנה כשהחריבם לא נשאר מהם לא שורש ולא ענף, וע\"כ אין מהם דבר שנשאר בעולמנו זה, שנברא ע\"י הקב\"ה יש מאין ללא יוצא מן הכלל.","b":false},{"t":"ואמרתי בזה, כי הנה אלו החוקרים, למדו ממחקרם סימנים שונים שעל פיהם אפשר לספור את מספר שנותיהם, וכך חוקרים כל דבר, וכשמוצאים את הסימנים ההם מחשבים את חשבונותיהם ומסיקים על מספר השנים שחלפו על הדבר ההוא.","b":false},{"t":"וזה דומה לשינים שבפה של הבהמות, שמהם אפשר לדעת גיל הבהמה, וכן בעצים יש בתוכם כעין טבעות שמהם ניתן ללמוד על גיל העץ וכן על זה הדרך בשאר דברים.","b":false},{"t":"ואולם יש דבר שלא הביאו החוקרים בחשבון, וגם אין שום שייכות לאמוד אותו, והוא, שאפשר לומר, שהדברים הללו בעת שנבראו, כבר אז נבראו בצורה ההיא כאילו עברו עליהם מיליוני שנים, ואת זה אין אדם שיכול לדעת, וזה שייך באבנים ובעצים, ובבני אדם, ובשאר בעלי חיים, ואפשר שכאשר בא לידי החוקרים חלק מדברים אלו עומדים ונפעמים מרוב התפעלות, ובודקים לפי הסימנים ומחשבים ומסיקים שלפי החשבון הוא עתיק שבעתיקין.","b":false},{"t":"ועוד אחרת תיתכן, שבעקבות מאורעות שהיו בעולם שאינם רגילים כלל ועיקר, כמו המבול שהיה גובר ומתגבר בחמים וקרים מלמטה ומלמעלה, עד שנמחה הכל כמים. ואין לך אדם שיכול לשער מהלכים כאלו, ומה גדולה השפעתם על כל הדברים שהיו שם ועברו תהליך זה. והמתבונן בפסוק הנ\"ל, יראה כמה פעמים כתוב על התגברות המים, נאמר \"גברו המים וירבו מאד\". ועוד נאמר, \"והמים גברו מאד מאד\". ונאמר עוד, \"חמש עשרה אמה מלמעלה גברו המים\". ונאמר עוד, \"ויגברו המים על הארץ חמשים ומאת יום\". ועוד לשונות אחרים, אשר כל זה הוא מאד לא מצוי בתורה לפרש כל כך, ובודאי שזה מלמד על התהליכים הנוראים שהעולם עבר במשך ימי המבול, אשר לא יאומן כי יסופר. ומי יכול לתאר ולשער את מדת השפעת התופעה הזאת על אבנים ועצים ועצמות ועוד, שאפשר שבאותם עשרות ימים שבהם נמשך המבול, נעשו הדברים כמו שעברו עליהם עידן ועידנים. ועוד, שבמשך שנות קיום העולם עברו מאורעות שונים בחלקים שונים בעולם, כמו התפוצצויות של הרי געש בקנה מדה שאינו ידוע, וכן רעידות אדמה רח\"ל, ושטפונות (כגון צונמי) בעוצמות שאינן ידועות, וכל זה מצטרף למגוון דברים שאי אפשר לצפות ולשער את גודל השפעתם. ודברים אלו מטעים את החוקרים בטעויות מופלגות, כיון שאינם בעלי תורה, ואין להם השגה באמונה, לפיכך אינם טורחים להעמיק ולפשפש אולי היו תופעות שגרמו לדברים האלו להזדקן בערך אלפי אלפים שנים יותר מגילם האמיתי, רק מיד קובעים רוב שנים. וכל זאת הוא משום שאין להם שום ידיעה בהנהגת הבורא ב\"ה.","b":false},{"t":"והדבר דומה לאדם שמצא קומקום עתיק, ורצה לברר את גילו של הקומקום, ובדק באבן המצטברת בשוליו, וחקרו ומצאו שבמשך רתיחה של שבוע מתהוה דרך משל מילימטר אחד של אבנית, ואחר שביררו את זה באר היטב, מדדו את עובי האבן שבקומקום והכפילו, עד שקבעו את גילו המדוייק של אותו קומקום. ופשוט שאין מסקנתם יכולה להיות מדוייקת מכמה טעמים, דאפשר שהקומקום הזה היו מרתיחים בו מים על האש במשך כל הזמן ברציפות, יומם ולילה לא ישבות. ואפשר שהיו מרתיחים בו רק במשך שעה אחת בכל יום, ואפשר עוד שהיו מרתיחים בו רק פעם אחת לחדש, עוד אפשר שהיה מכלי חג הפסח, ולא השתמשו בו רק מפסח לפסח, ועוד יש ספקות רבים וגדולים, שאי אפשר לבררם כלל, והם יכולים לשנות את המסקנא על גיל הקומקום בשינויים מופלגים מאד זה מזה, לפי רוב תשמישו ותדירות השימוש בו.","b":false},{"t":"וזו רק אחת מאפשרויות רבות שיכולות לשנות את הענין מן הקצה אל הקצה, דגם תלוי בטיב המים, יש מים שהם מכילים סיד במדה רבה, ויש פחותים, וכן תלוי באש ובחומר שממנו עשוי אותו קומקום, ובמזג האויר שם, ועוד ועוד, באופן שאי אפשר לעמוד על טיב הדבר לברר מספר שנותיו בבירור, בשום פנים שבעולם, קל וחומר לדברים עתיקים בני אלפי שנים, שלא נוכל לדעת את גילם האמיתי.","b":false},{"t":"ועוד דאפשר דבתחילת בריאת העולם היו הדברים בעלי עוצמות שונות לגמרי מאלו המוכרים לנו כהיום, עד שאפשר שאז היה מתבלה הדבר ומשתנה במשך יום אחד מה שלא קורה בימינו אפי' במשך שנה ויותר.","b":false},{"t":"וזכורני שראיתי להגאון הנצי\"ב ז\"ל בפירושו העמק דבר על התורה על הפסוק (דברים לב, מ), כי אשא אל שמים ידי, שתוך דבריו כתב, כי בשנות הבינים כאשר כסה אופל הבערות בעולם לא היו חכמי אוה\"ע חוקרים בחכמת הטבע, ולא חקרו אלא באמונתם ובמה שלמעלה מן הטבע רק בכח המדמה. וע\"כ היתה חכמת ישראל נלוזה אצלם, וארחותם בזוים בעיניהם. כי לא ידעו את ה' וישראל עמו וכח חכמתם. אבל כאשר אשא אל שמים ידי, היינו בעת שהי\"ת יראה את כחו לגלות כל סתרי הטבע כמה השפעה יש בכל יסוד ובכל בריאה להשפיע ברכה וטובה בעולם, ויהיו אז חכמי אוה\"ע חוקרים בזה הרבה, עד שיעמדו על נפלאות הבורא ית'. ובזה שיהיו עסוקים בחכמת המשפיעים יכירו כח ישראל וחכמתם, שגם בזה לא נגרע כחם. ואדרבה מעתה יכירו וישכילו חכמת ישראל ותעודתם מכבר לעבוד אך את ה' יוצר כל הבריאה וממילא יתגדל שמו ית' בעולם, וזהו שמסיים המקרא אשר ע\"י זה. \"ואמרתי חי אנכי לעולם\". וכבר נתבאר שלשון חיות לא שייך לומר על הקב\"ה אלא על תכלית הבריאה בהתמלאות כבודו ית' בכל הארץ. ומן אז שברא העולם נוכל לחשוב שהוא חי וקיים. משא\"כ לפני היצירה לית מחשבה תפיסא ביה כלל. ומשום הכי אמר דבזה שיגלה סתרי הטבע המשפיעים בשפע רב אשר לא ידע אדם מזה עד כה, אז יתגלה כבודו וחי לעולם, וממילא יכירו כל האומות בחשיבות ישראל עמו, עכת\"ד הנפלאים.","b":false}]},{"id":"13","t":"בחיוב הציפיה המתמדת לגאולה ולימודה מנח","p":[{"t":"עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר קִנִּים תַּעֲשֶׂה אֶת הַתֵּבָה וְכָפַרְתָּ אֹתָהּ מִבַּיִת וּמִחוּץ בַּכֹּפֶר: (ו, יד)","b":true},{"t":"ומצינו לרש\"י ז\"ל (שם), שכתב, וז\"ל, הרבה ריוח והצלה לפניו ולמה הטריחו בבנין זה, [אלא] כדי שיראוהו אנשי דור המבול עוסק בה מאה ועשרים שנה, ושואלין אותו מה זאת לך, והוא אומר להם, עתיד הקב\"ה להביא מבול לעולם, אולי ישובו. עכ\"ל. ומקור הדברים נזכר בדברי רבותינו במסכת סנהדרין (קח, ב).","b":false},{"t":"והנה מסתמא שכבר בשנה הראשונה לעבודת התיבה, היו שואלין את נח אנשי דורו, מה העבודה הזאת לך נח, ובפרט שהיו יודעים שהוא חכם ונביא, ולא זו בלבד, אלא אף ממציא המצאות להקל עליהם מקושי העבודה, כי עד שלא בא נח לא היו לבני אדם כלי מחרישה, ונח הכינם להם, להקל מעליהם את טורח החרישה (תנחומא בראשית סי' י\"א ורש\"י לתורה בראשית ה, כט ועי' ב\"ר כה, ב), עד שאמרו עליו בני דורו, זה ינחמנו ממעשינו ומעצבון ידינו (בראשית ה, כט ועי' רש\"י וראב\"ע שם). והנה הם רואים את נח מחפש עצים גדולים ביותר, להכין תיבה גדולה, שלש מאות אמה ארכה, ורוצים לדעת מה מעשיו, ולמה עושה תיבה כה גדולה, והוא משיבם, שהקב\"ה עתיד להביא מבול מים על העולם, למחות את כל היקום ולהשחית כל בשר, ומן הסתם גם שאלוהו למה עושה ה' ככה, והשיבם, מפני שהשחית כל בשר וכו'.","b":false},{"t":"ואמנם בני דורו רואים כי כלה קיץ וגם חורף עבר ומבול אין, ואמרו בליבם, נח חולם לו חלומות. אבל הם רואים את נח ממשיך בעבודת התיבה בכל המרץ, ואומרים לו היכן המבול שאמרת, ובינתים חולפת לה עוד שנה שלימה ומבול אין. ולכל השואלים נח משיב, אם הקב\"ה אמר כך יהיה, ועוברים עוד ימים ושנים ומבול אין. ואחר עשר שנים, אומרים בני הדור לנח, כמה אתה מתעקש, והלא עיניך הרואות כי חלפו עשר שנים ואין מבול, חדל לך מעבודתך, והתעסק בדברים מועילים. אך נח עומד בשלו. ואחר עשרים ושלשים שנה, ממשיכים להתוכח עמו, ומנסים ידידיו וחבריו להניאו מהמשך העבודה הקשה, בטענה שאין זה נכון, ורוב השנים יוכיחו. וחלק מן האנשים כבר התחילו לחשוב שנח לקה בנפשו, או עברה עליו רוח שטות, וחי לו בתוך עצמו, ולא מוכן להביט אל המציאות. וכך יכולים אנו לתאר לעצמנו מה קרה בחלוף שנה ועוד שנה, איך פנו אליו בני דורו, ומה חשבו עליו.","b":false},{"t":"וגם כשכבר עברו מאה שנה והוא עדיין עומד בעקשנותו וסרבנותו לחדול ממעשיו, וממשיך בעבודת בניית התיבה בכל הלהט ובכל המרץ, בודאי כבר היו רבים מאד שאמרו, חבל על נח, הוא השתגע לענין הזה. ועברו עוד כעשרים שנה אחרי המְאַת שנים, ולא רואים שום זכר למבול, וכבר נשתקע הדבר מהם לגמרי, ואפילו אלו האנשים שהיתה קצת אמונה בלבם, ובתחילה היו חרדים מפני המבול, הרי שעם הזמן נשכח מהם הענין ונרגעו לגמרי.","b":false},{"t":"אך דבר אלהינו יקום, הוא אמר ויהי, הוא ציוה ויעמוד, ונאמר:","b":false},{"t":"בִּשְׁנַת שֵׁשׁ מֵאוֹת שָׁנָה לְחַיֵּי נֹחַ בַּחֹדֶשׁ הַשֵּׁנִי בְּשִׁבְעָה עָשָׂר יוֹם לַחֹדֶשׁ בַּיּוֹם הַזֶּה נִבְקְעוּ כָּל מַעְיְנֹת תְּהוֹם רַבָּה וַאֲרֻבֹּת הַשָּׁמַיִם נִפְתָּחוּ, וַיְהִי הַגֶּשֶׁם עַל הָאָרֶץ אַרְבָּעִים יוֹם וְאַרְבָּעִים לָיְלָה: (בראשית ז, יא-יב)","b":false},{"t":"וזה מה שאמרו חז\"ל (אבות א, ז), ואל תתייאש מן הפורענות, רח\"ל. כי הנה גם אחר זמן כה רב, שכולם היו בטוחים שלא יהיה מבול, הנה קמה וגם נהייתה.","b":false},{"t":"ומזה נלמד בק\"ו למדה טובה המרובה, כי הנה הקב\"ה הבטיחנו להושיענו. ועברו על ראשינו מים הזדונים, דורות על גבי דורות. ועדיין לא נושענו, אך אנו עדיין מצפים לו, ואליו עינינו נשואות ותלויות, אסורים וכלואים בציפיתינו, ובטוחים ובוטחים בהבטחתו, ואל לנו להתייאש מן הרחמים. ואעפ\"י שיתמהמה עם כל זאת אנו מחכים לו בכל יום שיבא בב\"א, וההמתנות הם לצורכנו להשלמת תיקוני נפשנו רוחנו ונשמותינו, ולהשלים מלאכת תיקון העולם כאשר הושת על שכמינו, מבורא העולם ומנהיגו, אשר לו נתכנו עלילות, וצופה ומביט עד סוף כל הדורות, ואין דבר נעלם מלפני כסא כבודו.","b":false},{"t":"ורק זאת עלינו לדעת, שיש כח במעשינו לקרב את קץ ישועתינו, וכמו שיש בכח מעשינו והנהגתינו, לקבוע באיזו דרך תתבצע הגאולה, ובאיזה רמה, אם בבחינת עני ורוכב על חמור (זכריה ט, ט), או בבחינה הנה ה' נגלה על עב קל (ישעיה יט, א). וכמו שמצינו לרבותינו (סנהדרין צח, א), שאמרו: אמר רבי אלכסנדרי, רבי יהושע בן לוי רמי, כתיב (ישעיה ס, כב), בעתה, וכתיב (שם), אחישנה, [הא כיצד]? זכו - אחישנה, לא זכו - בעתה. אמר רבי אלכסנדרי, רבי יהושע בן לוי רמי, כתיב (דניאל ז, יג), וארו עם ענני שמיא כבר אנש אתה, וכתיב (זכריה ט, ט), עני ורוכב על חמור [הא כיצד]? זכו - עם ענני שמיא, לא זכו - עני ורוכב על חמור. ע\"כ.","b":false},{"t":"וראה בספר אוה\"ח להקדוש רבינו חיים ן' עטאר ע\"ה בפרשת ויחי (בראשית מט, יא), מה שביאר בזה. ע\"ש. וליה עינינו מיחלות שיחיש ישועתנו בקרוב, וכמאמר הכתוב (ישעיה ל, טו), בשובה ונחת תִּוָּשֵׁעוּן. בב\"א.","b":false}]},{"id":"13","t":"נח ודור המבול - הקדושה למול הטומאה","p":[{"t":"וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ: (ו, יג)","b":true},{"t":"ופירש רש\"י ז\"ל (שם), קץ כל בשר, כל מקום שאתה מוצא זנות ועבודה זרה, אנדרלמוסיא באה לעולם והורגת טובים ורעים. כי מלאה הארץ חמס, לא נחתם גזר דינם אלא על הגזל. ע\"כ. וכן מבואר בדברי רבותינו במסכת סנהדרין (קח, א).","b":false},{"t":"ובזמנו ראיתי במפרשים שהקשו, איך אמרו חז\"ל שלא נחתם גזר דינם אלא על הגזל, והנה למעלה כתב רש\"י (וראה ב\"ר כו, ה), כל מקום שאתה מוצא זנות ועבודה זרה אנדרלמוסיא באה לעולם וכו'. ע\"ש. ומאחר ובני דור המבול היו עובדים ע\"ז, וגם גילוי עריות היה בהם, א\"כ למה לא נחתם גזר דינם אלא על \"הגזל\" שהוא קל מהם הרבה.","b":false},{"t":"וכתבו לתרץ, דבאמת החיוב מיתה היה על עוון ע\"ז וגילוי עריות, אך הקב\"ה ברחמיו חס על מעשה ידיו שלא להשחית דור שלם, ועל כן רצה לכפר להם בממונם, דעני חשוב כמת (נדרים סד, ב), אך הואיל והממון שנמצא אצלם אינו שלהם כי גזלנים הם, אם כן אי אפשר לכפר להם על עונשם בממון של אחרים הגזול בידם, ועל כן אין מנוס אלא לבצע את גזר דינם, אשר נגזר עליהם מכח העונות החמורים שבידם, וזהו אומרם, \"לא נחתם גזר דינם אלא על הגזל\". אבל הפסק דין שלהם למיתה, באמת היה מפני העוונות של ע\"ז, וגילוי עריות.","b":false},{"t":"אלא דעדיין קשה, א\"כ למה קורא הכתוב לזה \"חמס\" ולא גזל כמו שנא' כי מלאה הארץ \"חמס\", והרי גזל חמור יותר מחמס, כי גזלן לא יהיב דמי, וחמסן יהיב דמי (ב\"ק סב, א).","b":false},{"t":"ונראה דבא הכתוב וטמן ברמ'ז, שהיו בני דור המבול כל כך רעים שאחזו רק ברע, בלא שום טוב כלל. שהרי גם הרע יש בו מעט טוב, והם לקחו את הרע שברע בלא הטוב שבו, ועל זה נאמר עליהם בסוף פרשת בראשית (בראשית ו, ה), וירא ה' כי רבה רעת האדם בארץ, וכל יצר מחשבות לבו, רק רע כל היום. \"רק רע\", כלומר, רק הרע שברע בלבד.","b":false},{"t":"וראיתי בספר קרית ארבע למהר\"א קליין ז\"ל שכתב דזה נרמז בתיבת \"חמס\", שהאות חי\"ת דחמס היא מהנחש. והנה ידועים המה דברי הגה\"ק מהר\"ש מאוסטרופולי ז\"ל הי\"ד, על הנחש שהוא המחטיא הראשון, ונהפך לסמל הרע, וגם הוא אין כל אותיותיו רעות, אלא רק האות חי\"ת שבו היא הרע שלו, אבל אותיות נו\"ן ושי\"ן שבו, הן אותיות המיתוק, וזה שאמר רבי יהודה במסכת ב\"ק (כג, ב), ובסנהדרין (עח, א), \"ארס נחש בין שיניו\". כלומר הארסיות של ה\"נחש\" היא באות חי\"ת שבו, העומדת בין שיניו, כלומר, בין אותיות שי\"ן ונו\"ן (ובביאור הגר\"א לתקו\"ז ת\"ט דל\"ט ע\"ב כ' שנחש אות אמצעית שלו היא ח\"ת ושטן אות אמצעית שלו היא טי\"ת ויוצא מנייהו ח\"ט וזהו ארס נחש בין שיניו. ועי' בזה להרי\"א חבר בפי' לאידרא הנקרא בית עולמים דקל\"ו ע\"א ד\"ה יתכין קוצין, ע\"ש).","b":false},{"t":"והנה בני דור המבול לקחו רק את האות חי\"ת לבדה מהנחש דאיהו יצה\"ר, והניחו אותיות נו\"ן ושי\"ן, ונשארו אותיות מ - ס מחמס, והן אותיות ס\"מ, שהוא השר הממונה על הסטרא אחרא (ראה דברים רבה יא, ט), ושמו ס\"מ עם א-ל, וגם בשם זה, הרע שבו הן אותיות סמ\"ך ומ\"ם, אבל אותיות אל\"ף ולמ\"ד הם ממתקים ומטהרים, לפי שאותיות אל\"ף למ\"ד אותיות של חסד הם, כדכתיב (תהלים נב, ג), חסד אל כל היום. ורשעים אלו הניחו אותיות א - ל, ולקחו אותיות ס - מ וחיברום לאות חי\"ת של נחש, ונעשה חמ\"ס, רח\"ל. וזהו \"רק רע\". כי מלאה הארץ חמס. [וראה זה פלא, שגם בימינו הדבר חוזר על עצמו, רח\"ל].","b":false},{"t":"ואמר לו הקב\"ה לנח שיתקן את המצב, ע\"י עשיית התיבה. אשר במדותיה מתוקן הרע ההוא, כי בני דור המבול לקחו רק את הרע ממש, והוא כנגדם יקח רק את הטוב בלבד בלא שום רע, וזה שאמר לו:","b":false},{"t":"וְזֶה אֲשֶׁר תַּעֲשֶׂה אֹתָהּ שְׁלֹשׁ מֵאוֹת אַמָּה אֹרֶךְ הַתֵּבָה חֲמִשִּׁים אַמָּה רָחְבָּהּ וּשְׁלֹשִׁים אַמָּה קוֹמָתָהּ, צֹהַר תַּעֲשֶׂה לַתֵּבָה וְאֶל אַמָּה תְּכַלֶּנָּה מִלְמַעְלָה וּפֶתַח הַתֵּבָה בְּצִדָּהּ תָּשִׂים תַּחְתִּיִּם שְׁנִיִּם וּשְׁלִשִׁים תַּעֲשֶׂהָ: (בראשית ו, טו-טז)","b":false},{"t":"\"שלש מאות\" אמה אורך התיבה \"וחמשים\" אמה רוחב התיבה הם כנגד אותיות שי\"ן ונו\"ן, של נח'ש, שעולין בגימטריא ש\"נ, והן אותיות המיתוק של נחש. וזה כנגד הח' דטומאה שלקחו הרשעים מתיבת נח\"ש והחסירו אותיות ש - נ. ו\"שלשים\" אמה קומתה ואל \"אמה\" תכלנה מלמעלה, הן עולין כמנין אותיות א\"ל, וזה כנגד אותיות ס\"מ דטומאה שלקחו הרשעים, והחסירו אותיות א\"ל. וזה לעומת זה עשה אלהים (קהלת ז, יד), שנתן לנח את דרך התיקון, באותו ענין שבו קלקלו בני דורו, ובמקום שהם לקחו את הרע לבדו, ואת הטוב השליכו אחרי גַוָּם נתן לו הקב\"ה לנח את דרך התיקון שיקח רק את הטוב, בלא תערובת של רע, ומזה נעשה ריוח והצלה לעולם, להמשיך להתקיים עם בריותיו ברחמים. זת\"ד הרב קרית ארבע הנ\"ל משם מהר\"ש אוסטרופולי זלה\"ה הי\"ד, ודפח\"ח, ש\"י.","b":false},{"t":"ומזה ניתן לראות מה רמוז וטמון בדברי תורתנו הקדושה, שאפילו המדות של התיבה, שלכאורה לא באו אלא ללמד את נח על הגודל של התיבה, כדי שתוכל להכיל בתוכה, מכל חי מכל בשר, מן האדם ומן הבהמה והחיה והעוף למינהו, כמפורט שם בפסוקים, ומכל מקום הטמינה התורה ברמ'ז בתוך המדות, סודות נפלאים, שיש בהם כדי לתקן את הקלקול הגדול של אותו הדור, ולעשות שם ושארית לעולם. וק\"ו בגופי תורה ומצוותיה, מי יכול להכיל בדעתו מה גדלו אמריו יתברך, ומה עמקו מחשבותיו, ומי יעמוד בסוד ה'.","b":false},{"t":"[א\"ה - כדי להבין הענין יותר עי' מאורי אור מערכת ס' אות י\"ג שכ' סמל: סמא\"ל, בחסרון הטוב שבו שהוא הניצוץ המחייהו \"א\" שלו, שהוא חיותו, ואם יחסר \"א\" אז כולו רע. ע\"ש. ובשל\"ה הקדוש בתולדות אדם בית דוד אות ה' הביא מהקדוש מהר\"א גלאנטי ז\"ל, וז\"ל בתוך דבריו, וזהו נמי סוד בלע המות לנצח (ישעיה כה, ח), שלא אמר בלע מלאך המות אלא המות, המות תבולע וישתאר מלאך קדוש. וכן \"סמאל\" יוסר ויבוטל ממנו בחינת \"סמ\", וישאר \"אל\" שהוא קדוש, כלומר אלהי ורוחני. וזהו סוד הנחשים שהיו נמצאים במערת הצדיקים, כדאמרו בגמרא (ב\"מ פד, ב), עכנא עכנא פתח פיך ויכנס הבן אצל האב, שיצר הרע שלהם כבר נמתק עד שנעשה להם לשומר ולשמש. וכן נמי אמרו רבותינו ז\"ל (סנהדרין נט, ב), חבל על שמש גדול שאבד מן העולם, שאלמלא לא חטא אדם היה מכניס לנחש רצועה תחת זנבו ומוציא זבל לאשפה, והיה מביא לו מרגליות מארץ מרחקים. להורות על מה שאמרנו, שאלמלא לא מרד סמאל ונעשה מר, היה העולם משתמש על ידו והיו קונים עולמם על ידו, כי היה מסייעו להוציא זבלו, היינו טינוף העבירות ולהרחיקו מעשות רע, והיה לו התועלת להביא מרגליות ולעשות מצוות, כמו שנאמר (בראשית ב, טו), ויניחהו ה' אלהים בגן עדן לעבדה ולשמרה, \"לעבדה\", מצות עשה, \"ולשמרה\", לא תעשה. אמנם הטתו ברוב לקחה ומרד ויצא וחטא והחטיא את האדם. וזהו נמי שאמר בפרקי רבי ישמעאל, עד שהיו כל שריו נשחטים ומוטלים במרום כגדיים וטלאים של יום כפורים, רמזו ז\"ל אומרם \"של יום כפורים\", על סוד המיתוק שיתמתקו וישתארון במרום ויכנסו פנימה אל הקודש. וזהו סוד דם נדות שמתמתק ומתהפך מדם נדות הטמא אל החלב הטהור (נדה ט, א), והוא סימן למה שעתיד להיות. ע\"כ. ועוד הוסיף וכתב בשל\"ה שם אות ו', וז\"ל, סמאל היה מלאך טהור, ואמרו המקובלים שהוא היה מהשרפים, אשר נראה שעל זה בא הרמז שנקרא הנחש \"שרף\", ולבש קנאה היא קנאת סופרים שהיה מקנא במעלת האדם, כי רצה להתקרב אל הקודש פנימה. וקנאת סופרים תרבה חכמה להעושים לשמה, רק על כל פנים היה בו כח מהמותרות, כאשר רמזתי למעלה כי כל נברא יש בו קצת חסרון אף שאינו גשמי, ואפשר להיות שיבוא לידי חטא. ומלאכי סדום יוכיחו שתלו הגדולה בעצמם, הגם כי זה אינו אלא באקראי בטל במיעוטו, מכל מקום סמאל אפשר היה בו יותר בנעלם ענין התמורות. ובקנאתו באדם התעורר האדם לנגדו, וזה מסייע לדבר עבירה, עד שנעשה הוא מקטרג ויצר הרע. ע\"כ. והדברים נפלאים להבנת הענין. יבח\"ר]","b":false}]},{"id":"13","t":"הבושה מצלת מן החטא","p":[{"t":"וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ: (ו, יב)","b":true},{"t":"אמרו רבותינו ז\"ל (ב\"ר כח, ח. ועי' סנהדרין קח, א. וכנראה שהוא פלוגתא), שאפילו בהמות וחיות נזקקין לשאינן מינן, והובאו הדברים גם בפירוש רש\"י ז\"ל.","b":false},{"t":"וזכורני שראיתי בהעמק דבר להגאון הנצי\"ב מואלוזין ע\"ה, שכתב (בפירושו לויקרא יט, יט), שכאשר האדם משחית דרכו ומקלקל את מעשיו, הדבר משפיע על כל החיות והבהמות והעופות, שגם הם משחיתים דרכם, כי האדם תפארת היצירה ומושל בכל חי אשר על פני האדמה, ויש לו השפעה עליהם, ולכן כשהשחית האדם את דרכו וקלקל מעשיו, השפיע במעשיו על כל היצורים, עד שנאמר, כי השחית כל בשר את דרכו על הארץ. ואחר זמן ראיתי שכבר קדמו בזה הקדוש רבינו משה אלשיך ע\"ה, שהוא כתב כן על הפסוק הזה.","b":false},{"t":"ושוב ראיתי הדבר מפורש בזוה\"ק, כי מעשי האדם משפיעים על כל היצורים, וז\"ל (ח\"א סא, א ואילך), וירא אלהים את הארץ והנה נשחתה, אמאי נשחתה, בגין כי השחית כל בשר את דרכו וכו' והאריכו בזה הרבה, ע\"ש. והיינו שהשחיתות שבאה לארץ היא בעבור עברותיו של האדם, וטבע הארץ תלוי בטבעו של אדם.","b":false},{"t":"ובעיני ראיתי שבמקומות שעדיין נותרה בושת פנים על פניהם של בני אדם, כי אז גם העופות והחיות המצויות בעיר בין בני האדם גם הם מתנהגות בצניעות וביראה. ובמקומות שיש חוצפה בבני אדם ולא יתבוששו, גם העופות והחיות שם מתנהגים בהתאם לאדם. ומזה ילמד האדם את חובתו לנהוג בדרך ארץ ובפרט במדת \"בושת פנים\" שהיא חומה חשובה בעד האדם מפני כל חטא ועון.","b":false},{"t":"וכמו שמצינו (ראה ברכות כח, ב), ברבי יוחנן קודם פטירתו, שאמרו לו תלמידיו, רבינו ברכנו. אמר להם, יהי רצון שיהא מורא שמים עליכם כמורא בשר ודם. אמרו לו תלמידיו, עד כאן. אמר להם, ולואי, תדעו, כשאדם עובר עבירה אומר הלואי שלא יראני אדם. והנה עכ\"פ למדנו כי כל זמן שאדם מתבייש מחבריו, הוא בסיס גדול ויסוד ליראת ה' ג\"כ. וכבר אמר יהודה בן תימא (אבות ה, כ), בושת פנים לגן עדן. ומיום שהבושה הוסרה מעל פניהם של בני אדם, סר צילם מעליהם, ויר\"ש אזלא ומידלדלא והחסרון גבר. וחובה על כל איש ישראל לשמור מדת הבושה שלא תסור מעל פניו, כי היא אחת מהסימנים של בני ישראל (ראה יבמות עט, א וירושלמי קדושין פ\"ד הלכה א במדב\"ר ח, ד).","b":false}]},{"id":"13","t":"\"כל אחד צריך לבנות תיבה לעצמו\"","p":[{"t":"וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים וַתִּמָּלֵא הָאָרֶץ חָמָס, וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ, וַיֹּאמֶר אֱלֹהִים לְנֹחַ קֵץ כָּל בָּשָׂר בָּא לְפָנַי כִּי מָלְאָה הָאָרֶץ חָמָס מִפְּנֵיהֶם וְהִנְנִי מַשְׁחִיתָם אֶת הָאָרֶץ, עֲשֵׂה לְךָ תֵּבַת עֲצֵי גֹפֶר קִנִּים תַּעֲשֶׂה אֶת הַתֵּבָה וְכָפַרְתָּ אֹתָהּ מִבַּיִת וּמִחוּץ בַּכֹּפֶר. (ו, יא-יד)","b":true},{"t":"אפשר שבא הקב\"ה ללמדנו, דבמקום שאין אפשרות להציל את כל הדור, אזי יש להשתדל על הצלת הפרט לפחות. וזהו אומרו \"עשה לך\" תיבת וגו'. ואמנם גם בציווי עשיית התיבה לימדו לעשותה במלאכה גדולה וארוכה מאד. כי עשיית התיבה התארכה על פני מאה ועשרים שנה (כמבואר בסנהדרין קח, ב), כדי שישאלו בני הדור את נח למה מאריך הוא במלאכתו, ואז ישמעו את תשובותיו, על מה שעתיד הקב\"ה לעשות בעולמו, ואולי יתעוררו מתרדמתם, ויקיצו ממשוגתם בהבלי הזמן ויעזבו את מעלליהם, וישובו אל ה' בכל לב, אולי ישוב וניחם האלהים.","b":false},{"t":"אך יחד עם זאת ציוה הי\"ת את נח להתחיל בבניית תיבה להצלה של יחידים, אותם אנשים שעדיין ניתן להציל.","b":false},{"t":"והנה אנחנו בניו של אברהם אבינו ע\"ה, האמונים על דרכו בקודש לדאוג לעשות נפשות גם במצבים הקשים, ולקרב את בניו של המקום ב\"ה בעבותות אהבה ונדבה, ולהשיב את הבנים התועים לשלחן אביהם. שומה עלינו לשים מול עינינו גם את מה שציוה הי\"ת לנח, שגם זה נחקק בתורה לדורות עולם, שבמקום שאין יכולים להשיג תיקון לרבים, יש לכל הפחות לדאוג ליחידים אשר ה' קורא, ולבנות להם תיבה מפני המשחיתים המקיפים עליהם, ומאיימים לעמוד עליהם לטבעם בבאר שחת, ויש לדאוג שתהיה התיבה הזאת מסוגלת לעמוד בפני רוחות הזמן וסערותיו, העומדות על כל דבר שבקדושה לטבעו ולהשחיתו, ומאיימות להרוס כל חלקה טובה.","b":false},{"t":"ואפילו אם על ידי זה מתבדלים מתוך ההמון, מכל מקום, זהו התיקון של אותה שעה, וזהו מעשה התיבה.","b":false},{"t":"ועוד צריכים לדעת ולהשריש היטב בלב, כי גם כשמצילים רחוקים, גם אז צריכים אנו לבנות תיבה מיוחדת, לבעלי מדרגה, שיהיו במקום שבו יכולים להתגדל בו כפי הראוי להם.","b":false},{"t":"וכבר מצאנו בזמן משה רבינו ע\"ה בפרשת קרח, כאשר נקהלו עליהם כל העדה, נאמר בתורה (במדבר טז, כ-כא), וַיְדַבֵּר ה' אֶל מֹשֶׁה וְאֶל אַהֲרֹן לֵאמֹר, הִבָּדְלוּ מִתּוֹךְ הָעֵדָה הַזֹּאת וגו'. ועוד נאמר (שם שם, כג- כד), וַיְדַבֵּר ה' אֶל מֹשֶׁה לֵּאמֹר, דַּבֵּר אֶל הָעֵדָה לֵאמֹר הֵעָלוּ מִסָּבִיב לְמִשְׁכַּן קֹרַח דָּתָן וַאֲבִירָם. כי לפעמים צריך להתבדל מן העדה הרעה, ופעמים צריך להתרומם ולהתעלות מעליהם.","b":false},{"t":"והנה בדורנו אנו, ישנו מבול של שחיתות ותאוות, אשר שוטף את העולם כולו בסערה גדולה ונוראה, והיצה\"ר הכין לו כלים רבים לקרב את ההרס והשחיתות לכל אחד ואחד בנפרד, בכלים מכלים שונים, וכמה פנים וכמה אופנים יש תחת ידו, לאין קץ ואין תכלה. והעומד במקום פרוץ בלא הגנה, הרי הוא בחזקת סכנה רח\"ל מפני המים הזדונים. וגם האיש החזק והחרד על דבר ה', לא תמיד יכול לעמוד נגד אותם רוחות.","b":false},{"t":"ועל כן חובת השעה היא לעשות תיבה שתגן ותשמור את אלה שמחפשים את דרך ה' וישועתו. והם הנקראים מבקשי ה', ויש להצילם מן המים הרעים הסוערים וגועשים ומאיימים להטביע את הכל. וצריך לדאוג לחזק את התיבה בכל מה שאפשר, וסוף מעשה במחשבה תחלה.","b":false},{"t":"ובזה נבין את ענין הקמת הישיבות בדורות האחרונים, אשר בהם מתאספים בחורי חמד, החפצים בתורת ה' בכל לבם, ומתנזרים מתאוות הזמן, ומהאוירה המצויה ברחובות קריה, שהיא ספוגה ורוויה בפגעי הזמן וקורותיו, והם מתרחקים מכל זה וממיתים עצמם באהלה של תורה, והם מוגנים שם בהגנת התורה, שהיא מגנא ומצלא (סוטה כא, ב), ומפני שראו חכמי הדורות האחרונים שחלה הדרדרות רוחנית גדולה, ונפרצו פרצות בכרם ה' צבאות, וראו שיש צורך בתיבה מוגנת, שתהיה להם לחומה ולמחסה נגד הרוחות הרעות המנשבות בעולם. ע\"כ התחילו להקים בתי מדרשות וישיבות, שיש בהם כדי לעצור את מגפת הקלקול והשחיתות, אשר אחריתה מי ישורנו. ובכל מקום נעשו הדברים לפי הצורך, וכפי הראוי באותו מקום ובאותו זמן.","b":false},{"t":"ומלבד התיבות הכלליות שהן הבתי מדרש ובתי אולפנא לתורה ומוסר, עוד יש לכל אחד לבנות לעצמו תיבה פרטית, בביתו ובחומותיו, ותהיה הנהגת הבית מבוססת על מבועי התורה. ומראש ומעיקרא ייסד את ביתו על יסודות נאמנים, ועל דרכי אבות ראשונים, יהיו סמוכים ונשענים, ואז יהיה לבו סמוך ובטוח, שבחסדי ה' לא יאונה להם כל רע, ורק בעיניך תביט וגו', לא תאונה אליך רעה, ונגע לא יקרב באהלך (תהלים פרק צא).","b":false},{"t":"ומתוך התחזקותם של מעטים, יבא חיזוק גם לכלל, לפי שאין בכלל אלא מה שיש בפרט, ומעט מן האור דוחה הרבה מן החשך (חוה\"ל שער יחוד המעשה פ\"ה), וכאשר ראינו ורואים בדורנו זה, את התפשטות האור של התורה צפונה ונגבה, וכך דרכו של אור שאינו פוסק לעולם, שנאמר (משלי ד, יח), ואורח צדיקים כאור נוגה הולך ואור עד נכון היום.","b":false},{"t":"ויה\"ר שנזכה במהרה לראות בבא לציון גואל בשובה ונחת.","b":false}]},{"id":"13","t":"בחובת כשרון המעשים","p":[{"t":"אֵלֶּה תּוֹלְדֹת נֹחַ נֹחַ אִישׁ צַדִּיק תָּמִים הָיָה בְּדֹרֹתָיו וגו', וַיּוֹלֶד נֹחַ שְׁלשָׁה בָנִים אֶת שֵׁם אֶת חָם וְאֶת יָפֶת: (ו, ט-י)","b":true},{"t":"כתב רש\"י ז\"ל, אלה תולדות נח, נח איש צדיק וגו' למדך הכתוב שעיקר תולדותיהם של צדיקים, מעשים טובים, ע\"כ. ומקורו טהור בדברי רבותינו (ב\"ר ל, ו).","b":false},{"t":"והרה\"צ רבי ישראל בהרה\"צ רבי משה דנינו ע\"ה היה אומר, שהמעשים צריכים להיות בבחינת \"את שם את חם ואת יפת\". \"את שם\" שיהיו כל המעשים לשם שמים, ולא לתועלת ונטילת שכר. \"ואת חם\", שיעשה האדם את המצוה בחום הלב וברצון גמור, ובזריזות גדולה ובשמחה רבה. \"ואת יפת\", שיעשה את המצות ביופי ובהידור, בבחינת זה אלי ואנוהו (שמות טו, ב), וכדרשתם ז\"ל (מס' סופרים ג, יג סוכה יא, ב נזיר ב, ב), התנאה לפניו במצות ועשה טלית נאה, מזוזה נאה וכו'.","b":false}]},{"id":"13","t":"כונה רעה מקלקלת את המעשה גם אם הוא טוב","p":[{"t":"וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה וּבָנוֹת יֻלְּדוּ לָהֶם, וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה וַיִּקְחוּ לָהֶם נָשִׁים מִכֹּל אֲשֶׁר בָּחָרוּ, וַיֹּאמֶר ה' לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם בְּשַׁגַּם הוּא בָשָׂר וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה וגו', וְנֹחַ מָצָא חֵן בְּעֵינֵי ה' אֵלֶּה תּוֹלְדֹת נֹחַ נֹחַ אִישׁ צַדִּיק תָּמִים הָיָה בְּדֹרֹתָיו אֶת הָאֱלֹהִים הִתְהַלֶּךְ נֹחַ: (ו, א-ח)","b":true},{"t":"הנה עצם לקיחת אשה היא מצוה גדולה וחשובה, שיש בה צורך וקיום העולם, ובה תלויה מצות פריה ורביה, אבל כאן כשלקחו נשים מכל אשר בחרו, הדבר גרם לכעס והביא עליהם חרון אף, רח\"ל.","b":false},{"t":"והטעם הוא, משום שלא התכוונו למצוה, ולא לקיום העולם היתה מטרתם, אלא הלכו אחרי עיניהם, ונטו אחר תאות לבם, כמדוקדק בלשון הפסוק, \"ויראו את בנות האדם כי טובות הנה ויקחו להם נשים מכל אשר בחרו\". (ועי' בדברי רש\"י ז\"ל).","b":false},{"t":"ובתרגום יונתן בן עוזיאל כתב, וחמון בני רברביא ית בנת אנשא ארום שפירן אינון וכחלן ופקסן ומהלכין בגילוי בשרא והרהירו לזנו ונסיבו להון נשין מכל דאתרעיו, ע\"כ. הרי שמפרש שהיו נשות הדור ההוא כוחלות ומפרכסות והולכות בגילוי בשר, והרהרו בהם האנשים לענין זנות ונשאו מאשר בחרו. ולכן נאמר בפסוק שלאחריו (בראשית ו, ג), ויאמר ה' לא ידון רוחי באדם לעולם וגו'. ותרגם אונקלוס, ואמר ה', לא יתקיים דרא בישא הדין קדמי לעלם וגו', ועיין עוד בהמשך הפסוקים, עד שנאמר (שם שם, ז), ויאמר ה' אמחה את האדם אשר בראתי מעל פני האדמה, וגו'.","b":false},{"t":"ולמדנו מזה כי אף שלקיחת הנשים היתה נראית כנישואין רגילין, אבל כיון שהלכו אחר תאות לבם, ולא שמו את שם ה' לנגד עיניהם, והרהרו לזנות, אעפ\"י שלקחו את הנשים ההן בדרך נישואין, זה דרדר את מצבם והגיעו לשפל המדרגה.","b":false},{"t":"ובפרשה ההיא נאמר (שם שם, ח), ונח מצא חן בעיני ה'. ולהנ\"ל צריך לומר דהיו מעשיו ישרים ומחשבותיו וכונותיו נכונות. וזהו ונח מצא חן בעיני ה', שגם בעיני הי\"ת שהוא בוחן לבות וחוקר וכליות מצא נח חן, לפי שהיה תוכו כברו, ולכן גם מעשיו היו טובים וזה שממשיך הכתוב ואומר אלה תולדות נח וגו'.","b":false}]},{"id":"13","t":"\"אומנותו של יצר הרע\"","p":[{"t":"\"כך היא אומנותו של יצר הרע, היום אומר לו עשה כך, ומחר אומר לו עשה כך, עד שאומר לו עבוד עבודה זרה והולך ועובד\". (שבת קה, ב נדה יג, ב)","b":false},{"t":"במאמר זה תיארו לנו חז\"ל את דרכי עבודתו של היצה\"ר נגדנו, כדי להכשילנו בעבודת ה'. וזו אחת מתחבולותיו הגדולות, להתחיל בקטנות, כדי שלא לעורר את תשומת לבנו על המצב, וכדי שלא נרגיש כלל בירידה המתחוללת בנו מעט מעט, ולא נתנער ממנו.","b":false},{"t":"והנה כשקוראים את מאמר חז\"ל הנ\"ל בפשטות, חושבים שכונתם ז\"ל באמרם, היום אומר לו עשה כך וכו'. זאת אומרת, שהיצה\"ר מתחיל להסית את האדם בעבירות קלות, וכשכבר מרגילו לזלזל בקיום המצוות בשלימותן ובדקדוקיהן. אז הוא מסיתו לעבור עבירות יותר חמורות, עד שלבסוף אומר לו לך עבוד עבודה זרה, והאדם הזה הולך ועובד.","b":false},{"t":"אמנם כאשר נדקדק היטב במאמרם ז\"ל, נראה שלא הגדירו במפורש באלו דברים מתחיל היצה\"ר להסית את האדם, וגם לא אמרו חכמים את דבריהם בלשון כללות לאמר היום אומר לו עבור עבירה קלה וכיו\"ב, רק נקטו לשון מופשט יותר באמרם \"היום אומר לו עשה כך, ומחר אומר לו עשה כך\".","b":false},{"t":"ונראה לי דאין כונתם דוקא שהיצה\"ר מתחיל מיד להסית את האדם לעבירה, אלא שהיצר הולך לפי השגתו של כל אדם ומדרגתו, ופעמים שמתחיל להסית את האדם גם בדברים המותרים היתר גמור, ואפילו בדבר מצוה. והיינו, כשאינו מוצא דרך למשוך את האדם לעבירה ואפילו עבירה קלה, אז הוא מתחיל לנהלו בדברים המותרים, ואפילו בדבר מצוה, ומתחיל לייעץ לו ולהדריכו כיצד ומתי יעשה דבר זה, ומתי יעשה מצוה זו, ומתחיל לתכנן לו את סדר היום שלו. ואפילו אם בתחילה יהיה הכל על דרך ההיתר הגמור, מכל מקום הוא מרגיל את האדם לשמוע לו, והוא הוא זה שמכתיב לו לאדם מה לעשות, עד שהוא מנהל אותו כרצונו. וזהו \"היום אומר לו עשה כך ומחר אומר לו עשה כך\". ובזה מרגילו ללכת אחריו ולשמוע בקולו, ואחר שהשיג מטרה זו שהוא מנהלו ואומר לו עשה כך, כלומר, מצוה זו עשה אותה באופן זה, ובזמן כזה וכו'. והלה שומע לו ועושה רצון יצרו, הגם שאין שום עבירה כלל ועיקר באותם עשיות, מכל מקום זו כבר ירידה עצומה, וזו היא ההתחלה של ההידרדרות, ומעתה הרי הוא כחומר ביד היוצר, ויכול לעשות בו ככל אשר יחפוץ, עד שהיצה\"ר יכול להרשות לעצמו לומר לאדם הזה \"לך עבוד ע\"ז והולך ועובד\".","b":false},{"t":"ועצם היסוד הזה שהיצה\"ר מתחיל לנהל את האדם גם בדברים המותרים לגמרי, ואפילו בדבר מצוה ממש, מצאתיו אחר איזה שנים בפירוש של הקדוש רבינו משה אלשיך ע\"ה, בסוף פירושו ליונה הנביא. יעו\"ש [ואם כי לא על מאמר זה אמרו הרב ז\"ל עכ\"פ עצם היסוד כתוב שם].","b":false},{"t":"ועפי\"ז יובן היטב הלשון של מאמר חז\"ל, שכך \"אומנותו\" של יצר הרע, שנקט לשון \"אומנות\" שהוא לשון טיפוח וגידול הילד, כמו שנא' (במדבר יא, יב), כאשר ישא האומן את היונק, וכן ויהי אומן את הדסה (אסתר ב, ז). וכן היצה\"ר, הריהו \"אומן\" את האדם באיטיות עם הרבה סבלנות, כמו שאומנים לתינוק בצעדים איטיים מעט מעט, כך היצה\"ר אומן את האדם ומחנכו ליכנס תחת צילו, ומנסה להנהיגו בכל צעדיו כדת מה לעשות, ומתי לעשות כל דבר, עד שהאדם נכנס תחת חסותו ואז הוא עושה בו כחפצו, וזהו, \"היום אומר לו עשה כך ומחר אומר לו עשה כך, עד שאומר לו עבוד ע\"ז ועובד\". רח\"ל.","b":false},{"t":"וכשנתבונן בפרשיות בראשית ונח, נראה דוגמאות רבות, המלמדות על יסוד חשוב זה. והנה בפרשתינו התורה מדברת על המבול, והשחיתות שגרמו להביא את המבול כמו שנאמר:","b":false},{"t":"וַתִּשָּׁחֵת הָאָרֶץ לִפְנֵי הָאֱלֹהִים וַתִּמָּלֵא הָאָרֶץ חָמָס: (בראשית ו, יא)","b":false},{"t":"והנה השחיתות היתה בדברים חמורים מאד, עד שבגללן נתחייבו כליה כל בני הדור ההוא. אבל לכשנתבונן, נווכח כי תחילת המעידה שהיתה אצלם, היתה בדברים קטנים, שאפשר שאין בהם איסור כלל, שכן מצינו בסוף פרשת בראשית נאמר:","b":false},{"t":"וַיְהִי כִּי הֵחֵל הָאָדָם לָרֹב עַל פְּנֵי הָאֲדָמָה וּבָנוֹת יֻלְּדוּ לָהֶם, וַיִּרְאוּ בְנֵי הָאֱלֹהִים אֶת בְּנוֹת הָאָדָם כִּי טֹבֹת הֵנָּה וַיִּקְחוּ לָהֶם נָשִׁים מִכֹּל אֲשֶׁר בָּחָרוּ: (בראשית ו, א-ב)","b":false},{"t":"ומי הם אותם בני האלהים. תרגם אונקלוס (שם), \"וחזו בני רברביא\". וגם רש\"י (שם), פירש בני האלהים - בני השרים והשופטים, וגם רבינו הראב\"ע כתב בני האלהים - בני השופטים, שהיו עושים בארץ משפט אלהים, ועוד הוסיף לפרש כעין זה. ע\"ש. וכ\"כ רבינו הרמב\"ן, והביא שכן הוא במדרש רבה (כו, ה), בני האלהים בני האנשים החשובים שבאותו דור. ע\"ש.","b":false},{"t":"והנה לכאורה אין רואים כאן שום עבירה במעשיהם, ואפילו היה ניתן לומר שקיימו מצוה של נישואין ופריה ורביה כמו שנאמר, \"ויקחו להם נשים מכל אשר בחרו\".","b":false},{"t":"אך עם כל זאת, הפסוקים אח\"כ אומרים לנו אחרת:","b":false},{"t":"וַיֹּאמֶר ה' לֹא יָדוֹן רוּחִי בָאָדָם לְעֹלָם, בְּשַׁגַּם הוּא בָשָׂר וְהָיוּ יָמָיו מֵאָה וְעֶשְׂרִים שָׁנָה, הַנְּפִלִים הָיוּ בָאָרֶץ בַּיָּמִים הָהֵם וְגַם אַחֲרֵי כֵן אֲשֶׁר יָבֹאוּ בְּנֵי הָאֱלֹהִים אֶל בְּנוֹת הָאָדָם, וְיָלְדוּ לָהֶם, הֵמָּה הַגִּבֹּרִים אֲשֶׁר מֵעוֹלָם אַנְשֵׁי הַשֵּׁם, וַיַּרְא ה' כִּי רַבָּה רָעַת הָאָדָם בָּאָרֶץ וְכָל יֵצֶר מַחְשְׁבֹת לִבּוֹ רַק רַע כָּל הַיּוֹם, וַיִּנָּחֶם ה' כִּי עָשָׂה אֶת הָאָדָם בָּאָרֶץ וַיִּתְעַצֵּב אֶל לִבּוֹ, וַיֹּאמֶר ה' אֶמְחֶה אֶת הָאָדָם אֲשֶׁר בָּרָאתִי מֵעַל פְּנֵי הָאֲדָמָה, מֵאָדָם עַד בְּהֵמָה עַד רֶמֶשׂ וְעַד עוֹף הַשָּׁמָיִם, כִּי נִחַמְתִּי כִּי עֲשִׂיתִם: (שם שם ג - ז)","b":false},{"t":"וצריך להבין איזו רעה היתה כאן, אדרבא, הרי לקחו להם נשים ובזה קיימו את מצותו יתברך, \"ואתם פרו ורבו\" (בראשית ט, ז). \"ולא לתהו בראה לשבת יצרה\" (ישעיה מה, יח).","b":false},{"t":"אכן למראה עינינו אין כאן רעה, אך הקב\"ה שהוא בוחן לבות וכליות, ויודע מאיזו כונה פנימית נובע כל מעשה, הוא ראה והביט אל מחשבותיהם, והנה לא מתוך כונה טובה ויושר לב היתה פעולתם זו, כי אם בעצת היצר הרע, וכל מגמתם להרע, וממילא תוצאות המעשים האלו יהיו קשות ורעות, והגם שבמעשיהם האלו לא היתה עבירה, אבל מכל מקום בזה התחילו להמליך את יצרם עליהם, ולהיות תחת פקודתו, שהוא אומר להם עשו כך והמה עושים, וע\"ז נאמר \"וירא ה' כי רבה רעת האדם\", שהקב\"ה ראה את הרעה הרבה והגדולה, שהיא תוצאה בלתי נמנעת ממעשיהם אלו, \"וכל יצר מחשבות לבו רק רע כל היום\". כי בדרך זו הפקירו עצמם ביד יצרם הרע, וחדלו מלהילחם בו, וזה שורש רע פורה ראש ולענה, ומעתה תרבה רעתם ללא גבול, ורק רע כל היום, וכאשר הוכיח סופם על תחילתם:","b":false},{"t":"וַיַּרְא אֱלֹהִים אֶת הָאָרֶץ וְהִנֵּה נִשְׁחָתָה כִּי הִשְׁחִית כָּל בָּשָׂר אֶת דַּרְכּוֹ עַל הָאָרֶץ: (בראשית ו, יב)","b":false},{"t":"כי כאשר היצה\"ר שולט כבר באדם ומנהיגו, והוא זה שאומר לו מה לעשות, אזי אפילו כשאומר לו לעשות מצוה, מ\"מ הוא מלמדו לעשותה פגומה וחסרה, הן מבחינת שלימות המעשה, וכל שכן בכונות של המצוה, כי הוא מלמדו לעשות הדבר רק למילוי תאוותיו החומריות, או כדי שישיג שם טוב וכבוד וכיו\"ב, ובדברים אלו שהם פנימיים ודקים, נוח לו להכשיל את האדם בקלות, ולא רבים יחכמו לעמוד על המשמר בכגון זה, וכשכבר נכנס היצה\"ר ללבו פנימה וקבע משכנו אצלו, סופו של היצה\"ר שנעשה בעה\"ב עליו, וממשיך להשתלט עליו, עד שאומר לו לך עבוד ע\"ז. ומה נפלאה הגדרת רבא במסכת סוכה (נב, ב), על היצה\"ר:","b":false},{"t":"\"בתחילה קראו הלך ולבסוף קראו אורח ולבסוף קראו איש\", ופירש רש\"י שם, הלך - עובר דרך עליו, ואינו מתאכסן עמו. אורח - אכסנאי. איש - בעל הבית. ע\"כ.","b":false},{"t":"היינו שהיצר מתחיל כהלך שאינו מתערב בכלום, ואח\"כ נעשה כאכסנאי, ולבסוף נעשה בעל הבית על האדם.","b":false},{"t":"ולכשנתבונן בסוף הפרשה שלנו נראה שוב את היסוד הזה, ביתר עוז ויתר שאת:","b":false},{"t":"וַיָּחֶל נֹחַ אִישׁ הָאֲדָמָה וַיִּטַּע כָּרֶם: (בראשית ט, כ),","b":false},{"t":"ורש\"י ז\"ל (שם), פירש בשם מדרש רבה (ב\"ר לו, ג), \"ויחל נח\", עשה עצמו חולין, שהיה לו לעסוק תחלה בנטיעה אחרת. ע\"כ.","b":false},{"t":"וצריך להבין למה פירשו חז\"ל \"ויחל\" מלשון חולין, שחילל את עצמו, ולא פירשו כמשמעות הענין ש\"ויחל\" הוא לשון התחלה. וגם צריך להבין במה חילל נח את עצמו, והרי בינתיים, לא שתה יין ולא עשה עדיין שום דבר רע, שהרי הענבים עוד לא גדלו, ומה זאת, שכבר בנטעו את הנטיעה נאמר בו \"ויחל\" שחילל את עצמו ומהותו.","b":false},{"t":"אלא שחז\"ל, באו ללמדנו שהנטיעה היתה מתוך כונה לא טהורה, אלא כדי למלאות את תאוותיו החומריות, ועל כן אעפ\"י שלא עשה שום מעשה רע עדיין, מכל מקום נטיעה זו נעשתה בעצתו והדרכתו של היצה\"ר, ובזה נח מסר והפקיר את עצמו ליצרו, ואז כבר אין קץ וגבול לאן שיוכל היצה\"ר להובילו, ולכן תיכף בנטיעה נעשה נח חולין. ומשום כך פירשו תיבת \"ויחל\" נח, שחילל את עצמו מיד בתחילתה של הנטיעה.","b":false},{"t":"ונראה שלמדו כן מהפסוק עצמו, שנאמר \"ויחל נח איש האדמה ויטע כרם\". כי הנה לשון זה לא נאמר על נח כשהלך לבנות התיבה, ולא כשהלך לבנות מזבח ולהקריב קרבן, ולא בשום מקום אחר, כי אם בנטיעת הכרם, וללמד בא, שנטיעה זו לא נבעה מצד איש האלהים שבו, אלא מצד החומר העכור, מעצת יצרו, וע\"כ דקדק הכתוב לומר כאן, \"איש האדמה\", כי מה שהביאו לנטוע כרם, ולמלאת את תאוותיו החומריות, היה החלק של היצה\"ר שהוא החלק הבהמי וחלק ה\"אדמה\" שבו. ומאחר וכך עשה, א\"כ כבר בזמן נטיעת הכרם ירד ממדריגתו ועשה עצמו חולין, עוד בטרם שחטא, וסופו הוכיח על תחלתו.","b":false},{"t":"וזו היא אומנותו של היצה\"ר, \"היום אומר לו עשה כך\", בדברים שאין בהם חטא, אבל הוא נשאר מלמדו ומדריכו, וגם כאשר בא האדם לעשות מצות ומעשים טובים, הוא הראשון לייעצו כדת מה לעשות, ובאיזה אופן וצורה יעשה את המצוה, ואומר לו עשה כך, וגורם לו לעשות את המצוות בדרך מעוותת ומקולקלת מלאה תאוות. וכשהאדם נשמע לו, והולך בעצתו, הריהו מושכו ומדרדרו, ואחריתו מי ישורנו.","b":false},{"t":"ומן הראוי להעתיק בזה את דברי רבינו עובדיה ספורנו בפירושו לתורה (בראשית ט, כ), וזה לשונו: ויחל נח, התחיל בפועל בלתי נאות, ולכן נמשכו מזה מעשים אשר לא יעשו. כי אמנם מעט מן הקלקול בהתחלה, יסבב הרבה ממנו בסוף, כמו שיקרה בחכמות מהטעות בהתחלה, וזה בעצמו הורה [הכתוב] באמרו (במדבר כה, א), ויחל העם לזנות. ע\"כ.","b":false},{"t":"והואיל ועבודתו ואומנותו של היצה\"ר, להשתלט עלינו ולנהל את חיינו כרצונו, לכך עבודתינו עבודת הקדש צריכה להיות מכוונת לאידך גיסא, להיות בעלי בית על עצמינו, ע\"י שנפרוק את עול היצה\"ר משכמנו ולהכניעו ולכובשו, בבחינת איזהו גבור הכובש את יצרו (אבות ד, א), ולזכות להיות מן הצדיקים אשר לבם ברשותם ושולטים עליו (ראה ב\"ר סז, ח), ולפעול מתוך לב טהור ומחשבה זכה, כדי לכוין בכל מעשינו לעשות רצון בוראינו.","b":false},{"t":"וכמו שאמר שלמה המלך ע\"ה, בכל דרכיך דעהו (משלי ג, ו). וכמה צריך האדם להתבונן ולהעמיק לחשוב בכל מעשה ומעשה ובכל מצוה ומצוה שבא לעשות, שלא תהיה ע\"פ עצת היצה\"ר והכונתו, אלא מתוך הצד האלהי שבו, ובפרט במצות שיש בהם גם הנאה לגוף, כמו אכילה, ושתיה, ונישואין, וכל כיוצא בהן, כי במצוות הללו צריך משנה זהירות ויותר הכנה נפשית לפני שמקיים את המצוה, והבא ליטהר מסייעין אותו (יומא לח, ב ע\"ז נה, א מנחות כט, ב).","b":false},{"t":"ומצינו להגאון רבינו יוסף חיים זצוק\"ל (בן איש חי שנה שניה פרשת בראשית), שרמז במאמר רבותינו (פסחים קא, א), \"אין קידוש אלא במקום סעודה\". שאין קדושתו של אדם ניכרת אלא במקום סעודה, שזה דבר שקרוב ללבו של אדם, ואם גם בזה הוא מתעלה ומכוין לש\"ש ולא למלאת תאותו, אז ניכרת קדושתו. וראה בזה עוד, מה שכתב רבינו החיד\"א ז\"ל, בספר שמחת הרגל (בעניני פסח, לימוד ג'), וזה לשונו: ואני שמעתי מפי מגידי אמת, שבזמן הרב הגדול קדוש יאמר לו, מלומד בנסים כמוהר\"ר יוסף קובו זצ\"ל בשבתו על כסא מלכותו בשאלוניקי, איש אחד צנוע, אמרו עליו שהיה לו מגיד ומגלה לו רזין, והלכו אצלו מגדולי ישראל רבני העיר, המה ראו כן תמהו, שהיה אומר סודות ונסתרות, והן קודם לא היה בר הכי כלל. והגיעה השמועה להרב הגדול הנזכר מפום רבנן. וכה ענם, צאו וראו כיצד איש זה מתנהג באכילה ושתיה, והשיבוהו, ידענו שהוא אוכל הרבה יותר משאר בני אדם, והשיב הרב הגדול הנזכר, אם כן, אין צריך בדיקה וחיפוש, פומיה מחכים עלוהי, כי הוא מהסטרא אחרא, ד\"הקדושה אינה שורה באדם שאוכל הרבה\", ואני גוזר ששום אחד לא ילך אצלו, וכך היה, דפירשו ממנו, ונתגלה דהיה מסטרא אחרא. ע\"כ.","b":false},{"t":"ולאידך גיסא, אם אדם מקדש עצמו בדבר הרשות הריהו מושך על עצמו קדושה וכח טהור מלמעלה. וכבר אמרו חז\"ל במסכת ברכות (סא, ב), צדיקים יצר טוב שופטן, רשעים יצר הרע שופטן. ע\"ש. כי בשעה שהאדם פורק את עול יצרו הרע מעליו, אז ממילא זוכה שהיצר הטוב שופטו ומנהיגו. ויה\"ר שנזכה לזה, אכי\"ר.","b":false},{"t":"(יום חמישי לסדר פרשת נח התש\"מ)","b":false}]}]},{"slug":"לך-לך","name":"פרשת לך לך","items":[{"id":"15","t":"מעלת מילת אברהם אבינו","p":[{"t":"בְּעֶצֶם הַיּוֹם הַזֶּה נִמּוֹל אַבְרָהָם וְיִשְׁמָעֵאל בְּנוֹ: (יז, כו)","b":true},{"t":"כדי ללמד על מעלת המילה ראיתי להעתיק לשון חז\"ל, הובא בדעת זקנים מבעלי התוספות. וז\"ל, בעצם היום הזה, רבן גמליאל אומר, שלח אברהם וקרא לשם בן נח ומל אותו ואת ישמעאל בנו, ומהו בעצם, בגבורתו של יום. ולא עוד, אלא בעשור של חדש השביעי הוא יום הכפורים, נאמר כאן בעצם ונאמר להלן תענו את נפשותיכם בעצם היום הזה (ויקרא כג, כט), מה להלן יום הכפורים, אף כאן יום הכפורים. ובכל שנה ושנה הקב\"ה רואה דם בריתו של אברהם אבינו ומכפר לנו על כל עונותינו. ואתמר בבראשית רבה (מט, ב), שנטל אברהם סכין ואחז בערלתו, וכשבא לחתוך היה מתיירא מפני שהיה זקן, וסייעו הקב\"ה כביכול, שלח ידו ואחז עמו, שנאמר (נחמיה ט, ח), וכרות עמו הברית מלמד שעזרו, עכ\"ל.","b":false},{"t":"[א\"ה מקור דברי המדרש שהביאו התוס', הוא בפרקי דר\"א פכ\"ח, וכתב שם כי במקום שנטף דמו של אברהם בעת המילה שם נבנה המזבח, ועוד יש שם אריכות פלאי פלאות במעלת המילה ושבחה, לך נא ראה ולנפשך יונעם. יבח\"ר].","b":false}]},{"id":"15","t":"בעת הזאת נסתיימה אחיזת ישמעאל בארץ הקדושה שבאה לו בזכות המילה","p":[{"t":"וַיִּקַּח אַבְרָהָם אֶת יִשְׁמָעֵאל בְּנוֹ וְאֵת כָּל יְלִידֵי בֵיתוֹ וְאֵת כָּל מִקְנַת כַּסְפּוֹ כָּל זָכָר בְּאַנְשֵׁי בֵּית אַבְרָהָם וַיָּמָל אֶת בְּשַׂר עָרְלָתָם בְּעֶצֶם הַיּוֹם הַזֶּה כַּאֲשֶׁר דִּבֶּר אִתּוֹ אֱלֹהִים, וְאַבְרָהָם בֶּן תִּשְׁעִים וָתֵשַׁע שָׁנָה בְּהִמֹּלוֹ בְּשַׂר עָרְלָתוֹ, וְיִשְׁמָעֵאל בְּנוֹ בֶּן שְׁלשׁ עֶשְׂרֵה שָׁנָה בְּהִמֹּלוֹ אֵת בְּשַׂר עָרְלָתוֹ: (יז, כג-כה)","b":true},{"t":"ומצינו בזוהר הקדוש (ח\"ב לב, א), בענין הזה דברים נוראים, וזה לשונו הקדוש. תא חזי ארבע מאה שנין קיימא ההוא ממנא דבני ישמעאל, ובעא קמי קודשא בריך הוא א\"ל מאן דאתגזר אית ליה חולקא בשמך, א\"ל אין, א\"ל והא ישמעאל דאתגזר (ולא עוד אלא דאתגזר בר תליסר שנין), אמאי לית ליה חולקא בך כמו יצחק, א\"ל דא אתגזר כדקא יאות וכתיקונוי ודא לאו הכי, ולא עוד אלא דאלין מתדבקין בי כדקא יאות לתמניא יומין ואלין רחיקין מני עד כמה ימים, א\"ל ועם כל דא כיון דאתגזר לא יהא ליה אגר טב בגיניה, ווי על ההוא זמנא דאתיליד ישמעאל בעלמא ואתגזר, מה עבד קודשא בריך הוא, ארחיק להו לבני ישמעאל מדבקותא דלעילא, ויהב להו חולקא לתתא בארעא קדישא בגין ההוא גזירו דבהון, וזמינין בני ישמעאל למשלט בארעא קדישא כד איהי ריקניא מכלא זמנא סגי כמה דגזירו דלהון בריקניא בלא שלימו, ואינון יעכבון להון לבנ\"י לאתבא לדוכתייהו עד דישתלים ההוא זכותא דבני ישמעאל וכו', ויעו\"ש עוד בעתיד בני ישמעאל במלחמותיהם, ומלחמת בני אדום עליהם, וארעא קדישא לא יתמסר בידי אדום, והמלחמות על רומי וכו', ביום ההוא יהיה ה' אחד ושמו אחד. ע\"כ.","b":false},{"t":"כלומר, שרו של ישמעאל היה עומד ארבע מאות שנה לפני ב\"ד של מעלה, ותובע שכר לישמעאל, ושאל את הקב\"ה האם מי שמל יש לו חלק בשמך. והי\"ת השיבו, כן. אמר לו הממונה והרי ישמעאל מל, ועוד שנימול לשלשה עשר שנים, ולמה אין לו חלק בך כיצחק. אמר לו הקב\"ה, זה נימול כתיקון הראוי שצריך לעשות, והיא כנראה מילה ופריעה, אבל ישמעאל אינו נימול כראוי שאינו עושה פריעה. ולא עוד, אלא שישראל מלין מיד אחר שמונה ימים משנולד, ואילו בני ישמעאל מושכים את זמן המילה. ושוב טען הממונה של ישמעאל, עם כל זאת, מכל מקום כיון שנימול, האם לא תתן לו שכר. אוי על הזמן שנולד ישמעאל ואוי על הזמן שנימול, מה עשה הקב\"ה הרחיק את ישמעאל מן הדבקות העליונה, ונתן להם חלק למטה בארץ הקדש, בזכות אותה ברית שיש בהם, ולכן עתידים בני ישמעאל לשלוט בארץ הקדש כשהיא ריקה מכל זמן מספיק. מפני שגם הברית שלהם בריקנות היא עשויה ואינה מושלמת. והם יעכבו את בני ישראל לשוב אל מקומם, עד שתושלם אותה זכות של בני ישמעאל.","b":false},{"t":"ואעפ\"י שאלו הם דברים העומדים ברומו של עולם, ואת אשר ה' עושה באחרית הדורות, גילה ע\"י עבדיו הצדיקים, עכ\"פ נתבונן בדברים, כמציצים בין החרכים, עד כמה שגם פשוטים כמונו יכולים לראות. ונראה כי יש בזה גדולות ונפלאות. ובפרט בימים אלו אשר זיכנו ה', וראינו איך התקיימו דברי הזוה\"ק עד לאחת, ולא נפל דבר אחד מכל דברו הטוב.","b":false},{"t":"כי מזמן שנכתבו הדברים עברו עידן ועידנים, ואין שם על לב. ועתה בימינו אלה, הנה קמה אלומתי וגם נצבה, ובעינינו ראינו איך ארץ ישראל היתה נתונה מאות שנים בידי בני ישמעאל ושלטו בה, וגם ראינו וידענו שהיתה ריקה ושוממה בידיהם משך כל הדורות, וכמו כן זכינו לראות שעברה מידיהם לשלטון ישראל, ותרבי ותגדלי ותבואי בעדי עדיים, כרכים וכפרים, פורחים ומשגשגים, וגם מקומות התורה, שהיא לנו ראש ועטרה, אחת מהנה לא נעדרה, והתרבו והתרחבו מרכזי התורה למאד מאד, ונתקיים בנו הכתוב (ישעיה ב, ג), כי מציון תצא תורה ודבר ה' מירושלים, כי עתה ארץ ישראל היא מרכז התורה, ומרכז הישיבות הגדולות והטובות, בנויות וחצובות, לבנים ואבות, וגם בתי מדרשות ובתי הוראות, היו למופת ולאות, מאת ה' צבאות. ובני ישמעאל שהיו מעכבים את בני ישראל, כבר קבלו שכר בריתם, הם ואבותם, ושבים לאחוזתם, שהיא נועדה לנחלתם.","b":false},{"t":"אמנם עדיין אנו עומדים תמהים, למה עדיין מתמהמהים, ולא נושעים, הן קיץ כלה קציר עבר, ואין מדבר דבר, וצרות מלגיו ולבר, ועד מתי יתעבר, ומתי יושלם דבר, אשר הבטיחנו, ע\"י נביאנו וחכמינו, אשר הם מאירים את עינינו, ודבריהם הם תקותינו.","b":false},{"t":"והנה עלה בדעתי שאולי, יש עוד עיכוב בדברי המקטרגים עלינו, אשר תחילה השלמנו הקטרוג הראשון בעצם הברית של ישמעאל, אשר על זה אמרו בזוה\"ק, \"וי לההוא יומא דאתיליד ישמעאל בעלמא ואתגזר\", אשר דין הוא דינא דגרמי לעיכוב גאולתנו, ועתה שעברנו זה המעבר, עוד יש קטרוג אחר, שישמעאל נימול בן י\"ג שנה והיה מקנטר את יצחק לאמר לו, אותך מלו בן שמנת ימים ולא ידעת בין ימינך לשמאלך, ולא היית מסוגל להתנגד, אבל הוא היה גדול בן י\"ג שנה והיה יכול להתנגד ומרצונו קיים את המצוה הזאת. וכמו שמצינו לרבותינו שאמרו (סנהדרין פט, ב והובא גם בדברי רש\"י ז\"ל בראשית כב, א): אמר לו ישמעאל ליצחק אני גדול ממך במצוות, שאתה מלת בן שמנת ימים ואני בן שלש עשרה שנה. אמר לו יצחק, ובאבר אחד אתה מגרה בי, אם אומר לי הקדוש ברוך הוא זבח עצמך לפני אני זובח וכו'.","b":false},{"t":"והנה קטרוג זה נשאר גם אחר שקבלו ישמעאל את שכר הברית, שישמעאל נימולים בני י\"ג מתוך רצון חופשי, ואפשר שהדבר הזה מעכב עדיין.","b":false},{"t":"ובזה אפשר להבין את התופעה שהיתה בדורנו, מה שלא היה מעולם, שרבבות רבות מאד מבני ישראל אשר ברוסיה, לא נימולו כלל, ובעלייתם ארצה נימולים מהם רבבות בני עשרים וארבעים ויותר, ואעפ\"י שאין להם שום ידיעה, בעניני תורה ומצוות, והם רחוקים מאד מאד עדיין, ועם כל זה הם באים לבתי הדין ולוחצים שהם רוצים אישור בשביל לקיים בעצמם ברית מילה, ורבבות אלפי ישראל נימולו בני ארבעים וחמשים ויותר וגם פחות, ונדמה שכל זה לא נעשה בכדי.","b":false},{"t":"ומשום כך עלה בדעתי הדלה לומר שמאת ה' היתה זאת, כדי לסתום ולחתום פי שטן, שבא בטענותיו של ישמעאל, לומר שהוא היה גדול וכמו שאמרו בזוה\"ק שם, \"ולא עוד אלא דאגזר בר תליסר שנין\". שגם במשך הארבע מאות שנים, שהיה במהלך המשפט בבית דין של מעלה, היה ממשיך לטעון כך. ובשביל לסתום ולחתום פי שטן ולא ישטין עלינו, הביא הקב\"ה מצב זה. שהוא עילת העילות וסיבת הסיבות. וסיבב ענין זה לדורנו, שאחר שנסתיימה זכותם של בני ישמעאל בעצם המילה, הסמיך הקב\"ה לזה, מצב מיוחד זה שעל ידו נימולו בני ישראל בגיל כל כך מבוגר, להראות אהבתם של ישראל לה' ברוך הוא, ואת נכונותם למסור עצמם על קיום מצוותיו. וכן יש בזה כדי ללמדנו את אהבת הי\"ת לעם ישראל, אשר אין דומה לה.","b":false},{"t":"ויש קשר הדוק בין הברית ובין גאולת ישראל, וכמו שמצינו על הפסוק (יחזקאל טז, ו), ואעבור עליך ואראך מתבוססת בדמיך ואומר לך בדמיך חיי ואומר לך בדמיך חיי, ואמרו רבותינו, שבזכות הברית נחיה ונגאל גאולת עולמים (במדבר רבה יד, יא), והנה מצינו בהרבה מקומות לרבותינו (שמו\"ר יז, ג ושם יט, ה. ושהש\"ר א, לד ושם ה, ג. ורו\"ר ו, א. ותנחומא וירא פ\"ד. ומדרש תהלים פ' קי\"ד. ותנדא\"ר פכ\"ז. ופסיקתא דר\"כ ז, ד. ופרדר\"א פכ\"ח), שדרשו שבזכות דם מילה ודם פסח ישראל נגאלים. וראינו דדמים בדמים נגעו דם מילה עם דם פסח שהוא הגאולה. והיינו דמישך שייכי נינהו אחד לחבירו. וגם מצינו, כי אליהו ז\"ל מלאך הברית, הוא זה הממונה לבשר את גאולתינו. יראו עינינו וישמח לבנו, בישועת מלכינו בב\"א.","b":false}]},{"id":"15","t":"ישראל בצרתם ובגלותם מתקנים את העולם כולו","p":[{"t":"בַּיּוֹם הַהוּא כָּרַת ה' אֶת אַבְרָם בְּרִית לֵאמֹר לְזַרְעֲךָ נָתַתִּי אֶת הָאָרֶץ הַזֹּאת מִנְּהַר מִצְרַיִם עַד הַנָּהָר הַגָּדֹל נְהַר פְּרָת: (טו, יח)","b":true},{"t":"הנה ביארנו לעיל (מאמר הקודם והארכנו שם בסגנון אחר), מדוע אמר הקב\"ה לאאע\"ה בעת ברית בין הבתרים ידוע תדע וגו'. ורבינו הרמב\"ן ז\"ל (שם), בפירושו הזכיר את ההבטחות הקודמות שהבטיח ה' לאברהם אבינו ע\"ה על מתנת הארץ, וביאר שכולם היו לצורך, ובפעם הזאת השלישית הי\"ת ביאר לאברהם את תחומי הארץ וכו', והוסיף לכרות לו ברית עליהם שלא יגרום החטא. וכאשר ציוה הי\"ת את אברהם על המילה, אמר שתהיה לו ארץ ישראל ל\"אחוזת עולם\", לומר, שאם יגלו ממנה עוד ישובו וינחלוה, והוסיף, \"והייתי להם לאלהים\", שהוא בכבודו ינהג אותם, ולא יהיו בממשלת כוכב ומזל או שר משרי מעלה, יעו\"ש.","b":false},{"t":"והנה אברהם אבינו ע\"ה שהיה נכנע לרצון ה' כעפר הארץ, ומעולם לא שאל ולא הרהר אחר מדותיו יתברך, וכפי שראינוהו בכל נסיונותיו, וכמו שאמר על עצמו (בראשית יח, כז), ואנכי עפר ואפר, כלומר, שהעפר נרמס ונדרס ואינו מתרעם על הדורס אותו, כך אברהם אבינו ע\"ה שם עצמו כעפר ואפר וביטל את כל ישותו לפני רצון ה' ואמרותיו, אותם קיבל וקיים בהכנעה גמורה.","b":false},{"t":"וזאת למרות גודל דעתו ועומקה, אשר בדעתו תהומות נבקעו, וכבר אמרו חז\"ל (ע\"ז יד, ב), מסכת ע\"ז של אברהם אבינו ארבע מאות פרקים יש בה, שלא הניח שום ע\"ז ושם פילוסופיה שלא העמיק בהם וסתרם, והרמב\"ם ז\"ל כתב בהל' עבודת כוכבים (פ\"א ה\"ג), על גדולתו ועומק השגתו הנפלאה של אברהם אבינו ע\"ה, שהשיג דרך האמת והבין קו הצדק מתבונתו הנכונה. יעו\"ש בדבריו הנפלאים ותרוה נחת (והובאו חלק מהם לעיל בפרשתנו מאמר א). ועם כל זה אברהם אבינו ביטל את כל חכמתו והשגתו כעפרא דארעא ממש, מפני כבוד ה' והדר גאונו, והלך בשמחה ובזריזות לקיים רצון ה', בלי להתחשב בסברותיו והגיוניו.","b":false},{"t":"וגם כשהי\"ת שהבטיחו על הבנים, אע\"פ שהדבר היה רחוק מן הדעת, בכל זאת קיבל את הדברים והאמין בהי\"ת ויחשבה לו לצדקה.","b":false},{"t":"אמנם למרבה הפלא, בעת שהבטיח הקב\"ה לאברהם את הארץ, פתאום ביקש סימן, ואמר, במה אדע כי אירשנה. והנה מצאנו לרבותינו (נדרים לב, א ועי' בעל הטורים בפירושו לתורה בראשית טו, ח), שאמרו, כי מפני שאמר אברהם במה אדע כי אירשנה לכן נענש בידוע תדע כי גר יהיה זרעך וגו'. אמנם הרב בעל כלי יקר (בראשית טו, ח), עמד מתמיה בדברי רבותינו אלו, היתכן כי אברהם ישאל סימן ומשך ארבע מאות שנה יסבלו זרעו והוא לא יסבול מאומה, האמנם, אבות אכלו בוסר ושיני בנים תקהינה, אתמהה. ולכן פירש בטוב טעם, כי הגזירה נגזרה כבר מאת הי\"ת אשר לו נתכנו עלילות. אך בעוון ששאל אברהם במה אדע שלא היה בו צורך לידע, אף עמו נהגו כן מדה כנגד מדה והודיעוהו מה יהיה לזרעו. ונצטער אברהם בזה. והיינו, שהעונש הוא מה שהודיעו לאברהם את ענין גלות זרעו, אך לא ששאלתו היא סיבת הגלות ח\"ו. ודפח\"ח.","b":false},{"t":"ויש להבין על איזה ענין שאל אות, ולמה דוקא בארץ ישראל שאל אברהם אבינו מאת הי\"ת שיתן לו אות. והנה רש\"י ז\"ל (בראשית טו, ו), פירש ב' פירושים, פי' א' שעל ירושת הארץ שאל אות. דבר אחר, במה אדע - לא שאל אות, אלא אמר לפניו, הודיעני באיזה זכות יתקיימו בה בני, א\"ל הקב\"ה בזכות הקרבנות.","b":false},{"t":"ואפשר לומר שאברהם נתחכם ושאל אות, כדי שהי\"ת יכרות עמו ברית, וכמ\"ש הרמב\"ן ז\"ל בפירושו לתורה (שם שם, ז ואילך), שאברהם אבינו ע\"ה חשש שמא יגרום החטא. וביקש לדעת באיזה זכות יחזיקו בניו בארץ ישראל, למען יצוה את ביתו ואת בניו אחריו לזרזם על זה (וראה מה שנתבאר עוד באריכות לעיל במאמר הקודם).","b":false},{"t":"ואח\"כ מצינו שהי\"ת הראה לאברהם אות וכרת עמו את ברית בין הבתרים, ויאמר אליו קחה לי עגלה משולשת ועז משולשת וגו', ואחר כל זאת נאמר (בראשית טו, יב-יג), ויהי השמש לבא ותרדמה נפלה על אברם, והנה אימה חשכה גדולה נופלת עליו, ויאמר לאברם ידוע תדע כי גר יהיה זרעך בארץ לא להם, ועבדום וענו אותם ארבע מאות שנה.","b":false},{"t":"ומהי החשכה הגדולה שנפלה על אברהם, פירש\"י ז\"ל (שם), רמז לצרות וחשך של גליות. והרמב\"ן ז\"ל כתב (בפסוק י\"ב), וז\"ל, והנה אימה חשכה גדולה נופלת, דרשו בו רמז לשעבוד ארבע גליות, כי מצא הנביא בנפשו אימה, ואחר כך בא בחשכה, ואחר כך גדלה החשכה, ואחר כך הרגיש כאילו היא נופלת עליו, כמשא כבד תכבד ממנו. אמרו (ראה ב\"ר מד, יז במעט שינוי), אימה, זו בבל. חשכה, זו מדי, שהחשיכה עיניהם של ישראל בצום ובתענית. גדולה, זו מלכות אנטיוכוס. נופלת עליו, זו אדום. והיה הענין הזה לאברהם, כי כשהקב\"ה כרת עמו ברית לתת הארץ לזרעו לאחוזת עולם, אמר לו כמשייר במתנתו, שארבע גליות ישתעבדו בבניו וימשלו בארצם, וזה בעל מנת אם יחטאו לפניו ואחרי כן הודיעו בביאור גלות אחרת שיגלו תחילה, שהוא גלות מצרים, שכבר נענש בו כאשר פירשתי, יעו\"ש (וראה מה שנתבאר עוד במאמר הקודם).","b":false},{"t":"ויש להבין האם ביקש אברהם אבינו לראות את מעמד האימה הזה, או האם ביקש לשמוע את ה\"ידוע תדע כי גר יהיה זרעך\". ועוד צריך להבין במה קשורים ענינים אלו שהראהו הי\"ת ושאמר לו, עם מתנת הארץ שאותה ביקש אברהם.","b":false},{"t":"ואשר נראה לענ\"ד ע\"פ דברי המקובלים (ראה בשער הכונות דרושי הפסח דרוש א' בארוכה וע\"ע בלקוטי תורה פר' מקץ, והובאו הדברים באריכות לעיל במאמר הקודם), שאמרו על שעבוד מצרים, שהוא לצורך גבוה, כי שם נקבצו ובאו כל ניצוצות הקדושה מאדם הראשון בק\"ל שנים שפירש מאשתו, ואשר על כן נקראה מצרים ערות הארץ (בראשית מב, ט ושם יב), והתיקון להעלות את הניצוצות דקדושה שנפלו ונדחו לשם הוא תיקון עצום וקשה עד מאד, ודורש עבודה גדולה וקשה לרדת עד עפר, בחומר ובלבנים ובכל עבודה בשדה (שמות א, יד), ומשם לבררם בבירור אחר בירור, אוכל מפסולת בנפה ובכברה ובכל כלי מלאכה, ואחרי כן יצאו ברכוש גדול (בראשית טו, יד), דאין לך רכוש גדול ויקר מאותם ניצוצות דקדושה, להעלותם ממקום טמא ולפדותם מבית מאסרם ושבים, ופדויי ה' ישובון ובאו ציון ברינה ושמחת עולם על ראשם, ששון ושמחה ישיגו ונסו יגון ואנחה (ישעיה נא, יא), [א\"ה - ואגב נימא בה מילתא, דהנה אמר ופדויי ה' ישובון, והן ניצוצות הקדושה שנפלו למקומות חושך ואפילה, ובאו ציון ברינה, והנה ציון גימ' יוסף ונאמר (ישעיה יד, לב), כי ה' יסד ציון. היינו שיתוקנו כנגד מדת יסוד שבהם ויעלו אל הקדושה, כי הנה ידוע כי סיבת ירידת יוסף הצדיק למצרים בעבור שהוא היה גדור והדור בקדושתו, ולכן ירד הוא ראשונה למצרים לתקן פגם \"ערות הארץ\" ועמד בכחות איתנים נגד הקלי' והצליח במלחמתו, ולכן יוסף הוא המשביר בר (בראשית מב, ו), והוא אומרו ובאו ציון, שחזרו למקומן, ואמר \"ברינה\", בבחינת (תהלים ל, ו), לערב ילין בכי ולבקר רינה, כי הבכי שורשו בקלי' ובפגם היסוד כידוע בסה\"ק, והרינה היא התיקון. ואין להאריך יותר. וכשתתבונן בזה היטב, תבנה לך בית נאה ותפרש הרבה מקראי קודש הנוגעים לזה, ואין לי זמן להאריך. ואגב אוסיף לך עוד מרגניתא חדא, הנה כתב מרן החיד\"א בספר ככר לאדן (ליקוטים סי' ו מערכת ב' אות ד דף רב ע\"ב), משם הגהות לירושלמי לחד קדוש כי מי שאין בניו מתקיימין לו, יקרא בשם בנו הנולד לו \"בן ציון\" ויתקיים וכ\"כ בקונטרס אחרון לשם הגדולים במערכת הבי\"ת, ע\"ש. והביא דבריו מרן החבי\"ף, וכן הובא ביפה ללב ח\"ג יו\"ד סי' רס\"ה אות ז' וכ\"ה בספרו יפה תלמוד, ונתן טעם בדברים כיעו\"ש, ועי' במזכרת משה מזה\"ג סי' קי\"ד. ואמרתי בעניי ליתן בה טעם, והוא דידוע כי הבנים מתים בעוון פגה\"ב ושם \"ציון\" שהוא גימ' יוסף הריהו מסוגל לתקן הפגם, ולא יהא שולט בילד מלאך דמותא, כי שמו דבוק בחי החיים, ואכמ\"ל. יבח\"ר]. וידוע גם כן דזהו ענין ובני ישראל פרו וישרצו וירבו ויעצמו במאד מאד ותמלא הארץ אותם (שמות א, ז). כי כל נשמה דקדושה היוצאת לאור העולם הרבה הצלה וישועה יש בה, להוציא מהסט\"א וגונדא דיליה את בלעם מפיהם, ולהתיש ולשבר את כחם, וכמ\"ש רבותינו (יבמות סב, א ע\"ז ה, א), אין בן דוד בא עד שיכלו נשמות שבגוף. ע\"ש. והיינו דע\"י ההולדה מקרב את התיקון והגאולה, ולכן פרו וישרצו במצרים (וראה עוד להלן בהגה שבסוף מאמר טז מפר' ויגש ודוק).","b":false},{"t":"ודבר פשוט וברור דענין בירור הניצוצות גדול הוא עד למאד, ולאו כל מוחא סביל דא, ולא כל הבא ליטול השם ולברר הניצוצות יבא ויטול. וכי יעלה בדעת שיבא טמא ויציל ניצוצות דקדושה ויעסוק בתיקון העולם ועוד טומאתו בו, חלילה! חלילה, הס מלהזכיר! ורק עם ה' וסגולתו אשר אותם בחר ובירר מכל עם ולשון, להם ניתנה סגולה זו, והיא עבודתם עלי אדמות בכל אשר יהיו ובכל אשר יעשו, והדברים פשוטים. ואשר על כן כששאל אברהם אבינו ע\"ה את הי\"ת \"במה אדע\", א\"ל הקב\"ה, \"ידוע תדע\", ועצם ירידת מצרים זה גופא הסימן שבניו של אברהם אבינו הם העם אשר בחר לו יה, שהרי עליהם דוקא הוטל תיקון העולם אשר היה כרוך בשעבוד מצרים, ופשוט דרק לעם הנבחר מיועדת הארץ הנבחרת, כי בחר ה' בציון (תהלים קלב, יג), ונתנה ליעקב אשר בחר בו, ומזה ומתוך ענין השעבוד, היינו מן הדבר המר הזה יוציא אברהם את המתיקות ויבין, כי זרעו ירש את הארץ, ושעבוד מצרים הוא לו לאות כי זרעו ירש את הארץ הקדושה ונחלה לעולם.","b":false},{"t":"וזהו שכתב הרמב\"ן הנ\"ל שכשהקב\"ה כרת ברית עם אברהם אבינו לתת את הארץ לזרעו לאחוזת עולם, אמר לו כמשייר במתנתו, שארבע גליות ישתעבדו בבניו וימשלו בארצם, וזה בעל מנת אם יחטאו לפניו ואחרי כן הודיעו בביאור גלות אחרת שיגלו תחילה, שהוא גלות מצרים. ע\"ש. ונראה דזה היה כנגד מה ששאל אברהם אבינו ע\"ה באיזה זכות יתקיימו בה זרעו, כי אאע\"ה ידע את מעלת ארץ ישראל והשיג בנבואתו את גודל קדושתה ויקרתה. ויחד עם זה ידע את הקושי הגדול להתקיים בה, ולכן היה ירא מה יהיה לבניו, שהרי אפילו יכנסו לארץ וינחלוה, מכל מקום במה יתקיימו בה, כי הרי יצר לב האדם רע מנעוריו (בראשית ח, כא), ואם יחטאו ישראל, הלא הארץ תקיא אותם ח\"ו.","b":false},{"t":"ולחזק הדברים אביא מדברות הרמב\"ן ז\"ל בפרשת וירא (בראשית יט, ה), שביאר למה היה עונש סדום כל כך קשה, ובתוך דבריו כתב, וז\"ל, ודע, כי משפט סדום היה למעלת א\"י, כי היא מכלל נחלת ה' \"ואינה סובלת אנשי תועבות\", וכאשר תקיא הגוי כולו מפני תועבותם הקדומה וקאתה את העם הזה שהיו רעים מכולם לשמים ולבריות, ושממו עליה השמים והארץ, ונשחתה הארץ בלא רפואה לעולם, מפני שבעבור הטובה נתגאו, וראה הקב\"ה שיהיה אות לבני מרי, לישראל העתידים ליורשה, כאשר התרה בהם גפרית ומלח שרפה כל ארצה כמהפכת סדום ועמורה אדמה וצבויים אשר הפך ה' באפו ובחמתו (דברים כט, כב). כי יש באמת רעים וחטאים מאד ולא עשה להם ככה, אבל למעלת הארץ הזאת היה הכל, כי שם היכל ה' וכו'. ע\"ש.","b":false},{"t":"וע\"ז היה שואל אברהם אבינו ע\"ה אחר שבצפייתו צפה את העתידות, והיה חושש שמא יגרום החטא וינחם ה' על ההבטחה ח\"ו, לזה השיבו הי\"ת, כי לעולמי עד ישארו ישראל העם הנבחר, וכרת עמו ברית עולם, ועל מה שחשש אברהם מחטאי בניו ונתירא שמא יפסידו הכל, על זה הראהו \"אימה חשכה גדולה\" שהוא שעבוד המלכיות והגליות. לומר, דאם יגרום החטא יצאו לגלות, אך לא לעולם יזנח ה' (איכה ג, לא), אלא מעמיד להם מלך קשה שגזרותיו קשות (ראה סנהדרין צז, ב ובירושלמי ריש תענית), והם שבים אל הי\"ת בצר להם, והוא יתברך ברחמיו הרבים פושט להם את יד ימינו ומקרבם אליו באהבתו וחמלתו, כי לא יטוש ה' עמו ונחלתו לא יעזוב (תהלים צד, יד), ולזה כיון הרמב\"ן ז\"ל, שאמר לו הי\"ת לאברהם אבינו כמשייר במתנתו, שארבע מלכיות ישתעבדו בבניו וימשלו בארצם וזה בעל מנת אם יחטאו וכו'. וכנ\"ל.","b":false},{"t":"ואפשר דכל ענין הירידה למצרים הוטל על בני ישראל עוד קודם מתן תורה, מפני שאז היו ישראל עדיין תחת השפעת כחות הסט\"א, ודוקא אז היו יכולים לבטל את כחה ולהשבית אויב ומתנקם, דאין הדין נמתק אלא משורשו כידוע (ראה ע\"ח שער י\"ג פי\"א ושעה\"כ דרושי העמידה דרוש ה' ובלקוטי תורה פרשת וישב ופע\"ח שער השופר פ\"א), וכמ\"ש קדוש ה' מכובד רבינו הרמח\"ל ע\"ה בספרו דרך עץ חיים הנדפס בסוף מסילת ישרים ד\"ה ועתה נחזור לשרש הענין וכו' ובתוך דבריו בירר הענין הזה, וזה חלק מדבריו שם:","b":false},{"t":"\"מפי עוללים ויונקים יסדת עוז\" (תהלים ח, ג), וזה כי המלאכים, כיון שאין להם יצר הרע, אין מעשיהם יכולים להעביר אותו. אבל בני אדם שיש להם יצר הרע, הם יכולים להעביר אותו [היינו את היצה\"ר], וכדי לתת להם כח יותר שיעשו זה התיקון בכח גדול, מה עשה הי\"ת, נתן להם שני הערלה, שהן כל הזמן עד שהאדם נכנס למצוות, ואז הסיטרא אחרא מתדבקת בהם יותר. וזה סוד \"אולת קשורה בלב נער\" (משלי כב, טו). אך באותו הזמן העוונות אינם נחשבים, והתורה אדרבה היא חשובה יותר, והוא ענין הבל פיהם של תינוקות, וההבל משבית את הסטרא אחרא לגמרי, וזהו \"מפי עוללים ויונקים יסדת עוז, להשבית אויב\". וזהו לשון \"להשבית\", שהוא, כאחד שעומד במלאכה אחת ושובת ממנה. ובמלאכים אין שייך זה, כי כיון שאין יצר שולט בהם, אינם משביתים אותו אלא מגרשים אותו, אבל בני האדם להם נוגע \"להשבית\". ע\"ש עוד דברים נפלאים בזה4","b":false},{"t":"והכי נמי י\"ל דהתיקון של מצרים יש צורך לעשותו קודם מתן תורה דוקא, לכן ירדו ישראל למצרים לפני מתן תורה. [ומה שהוצרכו ישראל גם במצרים ללימוד תורה ולכך ניתנה להם פרשת קרבן הפסח להתעסק בה. הוא משום שאי אפשר כלל ליגאל אפילו גאולה זמנית בלא תורה כלל כאמור בדברי רבינו הקדוש בעל אור החיים הק', (ראה לו בראשית א, א ושם מט, יא ושמות כז, כ ועי' לו שמות יב, טו ושם כא, יא), ודי בזה לע\"ע].","b":false},{"t":"ונמצא דגם השעבוד דמצרים וגם שעבוד ארבע מלכיות הכל מכוון לטובת עם ישראל בחמלת ה' עלינו, ורק באותה שעה לא רואים את הטובה הטמונה בצרות, וכבר אמרו דורשי רשומות על הפסוק (ירמיה ל, ז), ועת צרה היא ליעקב וממנה יושע. שמן הצרה עצמה צומחת הישועה. ויש דוגמאות רבות גם בחיי היום יום, ולא עת האסף.","b":false},{"t":"בעהית\"ש. בחמישי בשבת חמשה ימים לחדש אייר התשס\"א","b":false}]},{"id":"15","t":"מדוע אברהם אבינו ע\"ה ביקש סימן מהי\"ת על הבטחת הארץ לזרעו","p":[{"t":"אַחַר הַדְּבָרִים הָאֵלֶּה הָיָה דְבַר ה' אֶל אַבְרָם בַּמַּחֲזֶה לֵאמֹר אַל תִּירָא אַבְרָם אָנֹכִי מָגֵן לָךְ שְׂכָרְךָ הַרְבֵּה מְאֹד, וַיֹּאמֶר אַבְרָם אֲדֹנָי ה' (אלהים ק'), מַה תִּתֶּן לִי וְאָנֹכִי הוֹלֵךְ עֲרִירִי וּבֶן מֶשֶׁק בֵּיתִי הוּא דַּמֶּשֶׂק אֱלִיעֶזֶר, וַיֹּאמֶר אַבְרָם הֵן לִי לֹא נָתַתָּה זָרַע וְהִנֵּה בֶן בֵּיתִי יוֹרֵשׁ אֹתִי, וְהִנֵּה דְבַר ה' אֵלָיו לֵאמֹר לֹא יִירָשְׁךָ זֶה כִּי אִם אֲשֶׁר יֵצֵא מִמֵּעֶיךָ הוּא יִירָשֶׁךָ, וַיּוֹצֵא אֹתוֹ הַחוּצָה וַיֹּאמֶר הַבֶּט נָא הַשָּׁמַיְמָה וּסְפֹר הַכּוֹכָבִים אִם תּוּכַל לִסְפֹּר אֹתָם וַיֹּאמֶר לוֹ כֹּה יִהְיֶה זַרְעֶךָ, וְהֶאֱמִן בַּה' וַיַּחְשְׁבֶהָ לּוֹ צְדָקָה, וַיֹּאמֶר אֵלָיו אֲנִי ה' אֲשֶׁר הוֹצֵאתִיךָ מֵאוּר כַּשְׂדִּים לָתֶת לְךָ אֶת הָאָרֶץ הַזֹּאת לְרִשְׁתָּהּ. וַיֹּאמַר אֲדֹנָי ה' (אלהים ק'), בַּמָּה אֵדַע כִּי אִירָשֶׁנָּה: (טו, א-ח)","b":true},{"t":"ופירש\"י ז\"ל, והאמין בה'. לא שאל לו אות על זה, אבל על ירושת הארץ, שאל לו אות, אמר לו במה אדע. וכו' דבר אחר, במה אדע, לא שאל לו אות, אלא אמר לפניו, הודיעני באיזה זכות יתקיימו בה, א\"ל הקב\"ה בזכות הקרבנות. עכ\"ל.","b":false},{"t":"וזו הפעם הראשונה שאברהם אבינו \"האדם הגדול בענקים\" ע\"ה, שעמד בנסיונות גדולים ועצומים כאלה, ולא חת ולא זע, ולא הרהר ולא שאל מאומה, ובהכנעה גמורה ומוחלטת קיבל כל מאמר ה' ברוך הוא, מבלי לעורר תמיהות ותהיות, למרות חריפות שכלו, אשר בדעתו תהומות נבקעו, ועמקים אשר לא נודעו, כי לבו של אברהם אבינו ע\"ה רחב לו כאולם, וכמו שהאריך הנשר הגדול רבינו הרמב\"ם ז\"ל לתאר את מעשי אברהם (בהלכות עבודת כוכבים פ\"א ושם בהלכה ב' כתב אברהם עמודו של עולם).","b":false},{"t":"וחז\"ל גילו על גודל חקירותיו הנוראות, באומרם (ע\"ז יד, ב), שמסכת עבודה זרה של אברהם אבינו ע\"ה, ארבע מאות פרקים היו בה, ולא הניח ע\"ז או פילוסופיה שלא חקרה, עד שהפריכה מעיקרה וסתרה סתירה גמורה ויסודית. אבל בשמעו את דבר ה' היה מבטל עצמו לגמרי, כמו שאמר על עצמו (בראשית יח, כז), ואנכי עפר ואפר. ולא מליצה היא, אלא כך היתה מציאותו של אברהם אבינו ע\"ה להתבטל ביטול גמור שאין אחריו כלום נגד רצון הי\"ת, ומאבינו אברהם למדו ישראל את היסוד לסוד הנפלא שעשאם אהובים לפני הי\"ת באמרם, כל אשר דיבר ה' נעשה ונשמע (שמות כד, ז), כי תמיד הקדים אברהם אבינו ע\"ה וקיים את דבר ה', ולא חיכה לשמוע ולהבין ענינו, וכאן באופן יוצא מן הכלל, מצינו שאברהם אבינו ע\"ה שואל את הי\"ת, לאמר, \"במה אדע כי אירשנה\".","b":false},{"t":"והתשובה לזה, כי רצה אברהם אבינו ע\"ה להשיג את הבטחת ארץ ישראל לזרעו אחריו, כי ידוע ידע אברהם אבינו את הערך העליון של ארץ ישראל, והיה שמח כל כך על הבטחה זו, והיה מפחד שמא חלילה יגרמו מעשיהם ויאבדוה. ומשל להורים חשוכי בנים אשר לעת זקנתם נפקדו בבן נחמד ונעים, והיו אוהבים אותו מאד מאד, והיו דואגים שמא ח\"ו יקרהו אסון ה' ישמור, ומחזקים שמירתו ומחפשים לו סגולות וברכות להאדיר את כחו, ולהגדיל שלמותו שלא יאונה לו כל רע ח\"ו. כן הדבר הזה באברהם אבינו ע\"ה, שמתוך שהבין את גודל ענין ארץ ישראל ורוב חשיבותה, היה שואל אות מאת ה', להבטיח את ארץ ישראל שתהיה שייכת לזרעו לעד.","b":false},{"t":"ולפירוש השני שהזכיר רש\"י ז\"ל, שאל אברהם מעם הי\"ת שיורהו במה יוכלו ישראל להתקיים בה. באיזה זכות. והקב\"ה הסכים על ידו תיכף, כמו שנאמר, ויאמר אליו קחה לי עגלה משולשת, ועז משולשת ואיל משולש, ותֹר וגוזל, ועיין בדברי רש\"י ז\"ל שם. שפירשם על עניני הקרבנות (וראה מגילה לא, ב).","b":false},{"t":"ואולם חז\"ל אמרו (עי' נדרים לב, א), כי בעבור שאמר במה אדע, נענש בידוע תדע. והכלי יקר שם (בראשית טו, ח), כתב, שהשכל ימאן לקבל דרוש זה שיסבלו בניו עונש גדול כזה, בעבור האות שביקש אברהם, ואברהם עצמו לא קיבל שום עונש ושיני בניו תקהינה, ואחר כמה קושיות כתב, וז\"ל, ואני אומר שהאות אשר שאל, לא שהיה אברהם מסופק בייעוד האל יתברך, וזולת שרצה שיכרות לו הקב\"ה ברית לסלק מעליו כל טוען ומערער, לפי שלמעלה אמר לזרעך אתן, משמע מתנה בעלמא, וע\"ז לא היה מבקש אברהם כריתת ברית כי מי יערער על המתנה אשר נתן לו ה', כי לו יתברך תבל ומלואה וכו'. אבל כשאמר לו \"לרשתה\" בתורת ירושה, אז חשב אברהם, שמא שאר יורשיו של שם יערערו על חלקם וכו', על כן אמר במה אדע כי אירשנה, מה האות שאני לבד היורש בלי ערעור. ובאה לו התשובה קחה לי עגלה וגו'. כדרך שכרת ה' לאהרן ברית מלח עולם וכו'. עכ\"ל.","b":false},{"t":"והוא חיזוק גדול למה שפירשתי בס\"ד, שחיזוק והבטחת המתנה אברהם היה מבקש, ולא נתינת אות, אלא אחת שאל מאת ה' ואותה היה מבקש על עמו ועל נחלתו, להבטיחם עליה באין מפריע, וישבו בה ואין מחריד.","b":false},{"t":"והקב\"ה ישתבח שמו קיבל את בקשתו, וכרת עמו ברית בין הבתרים, והבטיחו על ארץ ישראל, כאמור להלן (בראשית טו, יח), ביום ההוא כרת ה' את אברם ברית לאמר, לזרעך נתתי את הארץ וגו'.","b":false},{"t":"* * *","b":false},{"t":"מדוע במעמד ברית בין הבתרים גילה הי\"ת לאברהם שזרעו עתיד לגלות","b":false},{"t":"ואולם זאת צריכים להבין, מה שנאמר בשעת הברית, שאחר שהכין אברהם אבינו את כל מה שאמר לו הקב\"ה ויבתר אותם וגו', נאמר:","b":false},{"t":"וַיְהִי הַשֶּׁמֶשׁ לָבוֹא וְתַרְדֵּמָה נָפְלָה עַל אַבְרָם וְהִנֵּה אֵימָה חֲשֵׁכָה גְדֹלָה נֹפֶלֶת עָלָיו, וַיֹּאמֶר לְאַבְרָם יָדֹעַ תֵּדַע כִּי גֵר יִהְיֶה זַרְעֲךָ בְּאֶרֶץ לֹא לָהֶם וַעֲבָדוּם וְעִנּוּ אֹתָם אַרְבַּע מֵאוֹת שָׁנָה: (בראשית טו, יא-יג)","b":false},{"t":"ופירש\"י ז\"ל, והנה אימה חשכה - רמז לצרות וחשך של גלויות. עכ\"ל. ועיין בדברי הרמב\"ן ז\"ל שם, וז\"ל, והנה אימה חשכה גדולה נופלת, דרשו בו רמז לשעבוד ארבע גליות, כי מצא הנביא בנפשו אימה, ואחר כך בא בחשכה, ואחר כך גדלה החשכה, ואחר כך הרגיש כאלו היא נופלת עליו, כמשא כבד תכבד ממנו, אמרו (עי' ב\"ר מד, יז בקצת שינוי), אימה, זו בבל. חשכה, זו מדי, שהחשיכה עיניהם של ישראל בצום ובתענית. גדולה, זו מלכות אנטיוכוס. נופלת עליו, זו אדום. והיה הענין הזה לאברהם, כי כשהקב\"ה כרת עמו ברית לתת הארץ לזרעו לאחוזת עולם אמר לו כמשייר במתנתו, שארבע גליות ישתעבדו בבניו וימשלו בארצם, וזה בעל מנת אם יחטאו לפניו, ואחרי כן הודיעו בביאור גלות אחרת שיגלו תחלה, שהוא גלות מצרים, שכבר נענש בו וכו', עכ\"ל הקדוש.","b":false},{"t":"ועדיין צריכים אנו להבין, דאחר שהסכים הקב\"ה ונתרצה ליתן אות לאברהם אבינו ע\"ה, שהוא וזרעו ירשו את הארץ, ואחר שאברהם אבינו ע\"ה עבד את ה' כל ימיו בהכנעה גמורה כעפר ואפר ממש, אם כן עד שמבקש בקשה ונתקבלה בקשתו, א\"כ, היה לו להקב\"ה להראותו את יופיה של א\"י ואת רוב טובתה והדרה, כדי לשמחו במתנת ה' אליו, ובמקום זה מראהו, \"אימה וחשכה גדולה\". האם זהו הזמן וזה המקום. ואם לא די לו באלו, הנה מוסיף לו עוד, ויאמר לאברם ידוע תדע כי גר יהיה זרעך בארץ לא להם ועבדום וענו אותם ארבע מאות שנה. והקורא תמה לאמר, עד שאברהם אבינו ביקש לדעת, והקב\"ה הסכים על ידו באמרו לו קחה לי עגלה וגו', ואחר כל אלה מראה לו את חשכת הגלות ותלאותיה, ולא גלות אחת, אלא על אחת כמה וכמה.","b":false},{"t":"ותחילה יש לומר, דהקב\"ה מלמדנו בזה דגם בראותינו חשך גדול ואימה גדולה, בזמנים קשים ומרים. גם אז אין להתיאש מישועת ה', ולא תעלה על לבנו מחשבה שהקב\"ה לא חפץ בנו ח\"ו, כי את אשר יאהב ה' יוכיח (משלי ג, יב), ומשלם לאוהביו נגד פניו (שלא כרשע הנזכר בספר דברים ז, י), כדי להעביר מהם את רעתם ולהביאם להשגת עיקר החיים, לזכות בחיי עולם, וסוף הכבוד לבא (נדרים סב, א). וא\"י נקנית ביסורין (ברכות ה, א), שממרקים עונותיו של אדם, ומטהרים אותו, להכינו ולהכשירו לזכות במעלותיה והשגותיה של ארץ ישראל, שלא לאכול מפריה ולשבוע מטובה, הוא היעוד העיקרי (ראה סוטה יד, א). אלא הבטיחנו הקב\"ה לתת לנו הארץ הזאת, אשר עיני ה' אלהיך בה תמיד (דברים יא, יב), והיא גבוהה מכל הארצות (זבחים נד, ב), וממנה מקבלים כל הארצות את השפע הראוי להם, גם ברוחניות וגם בגשמיות. וגם אם יחטאו ועונותיהם יביאום למרורות אלו, של אימה חשכה וכו', בכל זאת אל יאבדו תקותם מישועת ה', ולא יסירו ממנו את מבטחם, כי חנון ורחום ה' ארך אפים ורב חסד וניחם על הרעה (יואל ב, יג יונה ד, ב), והישועה קרובה, ישועת ה' כהרף עין (וראה עוד מה שנתבאר להלן במאמר הבא).","b":false},{"t":"* * *","b":false},{"t":"הגלות היא הוכחה גדולה שעם ישראל הוא העם הנבחר","b":false},{"t":"עוד נלע\"ד שבעצם הנבואה אשר הראה הי\"ת לאברהם אבינו ע\"ה את גלות מצרים, בזה גופא הראהו שבניו הם העם אשר בחר ה' לנחלה לו, ושהם עם סגולה וגוי קדוש. שכן מבואר בדברי רבינו האר\"י ז\"ל (ראה בשער הכונות דרושי הפסח דרוש א' בארוכה וע\"ע בלקוטי תורה פר' מקץ), שעיקר ירידתנו למצרים, היא לקבץ הניצוצות דקדושה, אשר נפלו שם, שכל ק\"ל שנים שהיה אדם הראשון פרוש מאשתו, יצאו ממנו ניצוצות דקדושה, ונפלו אותם ניצוצות, טלי אורות לבורות נשברים אשר לא יכילון המים (כמבואר היטב במסכת עירובין יח, ב ובזוהר בראשית יט, ב), ואותם צריכים לקבץ, ועיקרם נאספו שמה במצרים, שהיא ערות הארץ, והיו צריכים לרדת עד מקורם בחומר ובלבנים, ובכל עבודה בשדה, תחת מושל ורודה, ומי הוא זה ואיזה עם הוא, אשר לו יאתה מלאכה זו, להביא ישועה להניצוצות ולקבצם, ולהשיב הים לאיתנו, כאשר היה בתחילה, הרי בודאי דאין בכל זה שום אפשרות לעשות מלאכת בורר זו, לברור אוכל מן הפסולת, אלא העם אשר לו ייעד קוב\"ה את היעוד המיוחד, ובחר בהם מכל העמים וחיי עולם נטע בתוכם, ורוממם ונישאם, וקרא שמו עליהם, והאציל מרוחו ונתן בהם, והוסיף להם כחות רוחניים גבוהים, עמוק עמוק מי ימצאנו, רחוק רחוק מי ישיגנו.","b":false},{"t":"ועל כן בזה שאמר לו ידוע תדע וגו', בעצם הידיעה הזאת אותה מסר לו, ובעצם הענין גילה לו לאברהם אבינו ע\"ה, שבניו ובני בניו הם עם ה' ונחלתו. אשר לקחם לסגולתו, ועל כן ירדו ישראל מצרימה, ונתפזרו שם כדי לעסוק במלאכת \"בורר\", ואחרי כן יצאו ברכוש גדול, שיטלו עמם אותם רוחות וניצוצים נקבצים, וממילא הן הם העם שיזכה לרשת את הארץ הנבחרת, כי בחר ה' בציון אוה למושב לו (תהלים קלב, יג), והוא ישתבח שמו בחר בנו, כי יעקב בחר לו יה (שם קלה, ד), ונתן את הארץ הנבחרת לעם הנבחר, יבא טוב ויקבל טוב (מנחות נג, ב), מידו הרחבה של הטוב והמטיב, אך גם זה בא בדרך קשה של שעבוד קשה בחומר ובלבנים וכו'. ורבותינו הקדושים תלו את זה במה ששאל אברהם אבינו ע\"ה \"במה אדע\", כלומר, שאל את הי\"ת האם יש אפשרות למעט ביסורים, גם בקניית א\"י, והכל לפי רוב המעשה. והי\"ת השיב לו \"ידוע תדע כי גר יהיה זרעך\", כלומר, דע לך, כי מה שבחרתי בישראל זרעך למלאכה קשה זו של בירור ניצוצות הקדושה שהיא שייכת רק לעם הנבחר על ידו יתברך, בזאת גופא תדע שהם עם ה' וסגולתו, ורק להם לבדם יאתה תהלת הארץ הנבחרת, ואי אפשר לזה בלא זה.","b":false},{"t":"וישראל הצליחו בדבר, והצליחו להעלות את כל ניצוצות הקדושה שנפלו במצרים, לא נשאר בהם עד אחד, ובספר פרי עץ חיים (שער קריאת שמע פ\"ג), נתבארו בזה דברים נפלאים, ולחשיבותם נעתיק מן הדברים המבוארים שם, וזת\"ד, כי הטעם שיותר נזכיר יציאת מצרים משאר יציאות, כגון, בבל מדי, ויון, וכיוצא. דע, כי הלא ארץ מצרים ארץ טומאה הוא מכל הארצות, והשכינה היתה גולה שם בגלות ישראל, וכבר ידעת, איך אותו הגלות היה ע\"י חכמה נפלאה של כשפים שעשו המצרים, שלא יכלו ישראל לעלות משם כנז' בזוהר, ואמנם כבר הודעתיך ענין גלות השכינה באמיתות מה ענינו, כי הלא ע\"י חטא אדה\"ר נפלו כל הניצוצין של נשמות הקדושות לתוך הקליפות, ואין בהם כח לצאת משם לולי רחמי הש\"י שגלתה שכינה עמנו, ואז ע\"י הכנסתה תוך הקליפות, היא מלקטת אותן הנשמות הקדושות, וכאשר יסתיים קיבוץ גלות זה מבלוע הקליפות, אז הוי עידנא דהוי מטא רגלין ברגלין, ואז יתקיים הכתוב בלע המות לנצח כנז' בזוהר פ' פקודי.","b":false},{"t":"אמנם, בכל הגאולות שנגאלו ישראל נקראים על שם העיקר, אך אינה גאולה שלימה, כמו בבל מדי יון לא היה גאולה שלימה, כי נשארו קצת ניצוצות הקדושה שלא יכלו להתברר, אך נקרא גאולה. אך גאולת מצרים היתה גאולה שלימה, כי אז וינצלו את מצרים שעשאוה כמצולה שאין בה דגים, ולא נשאר בהם שום ניצוץ קדושה והיתה גאולת השכינה לגמרי, משא\"כ בשום גאולה אחרת. וזהו הטעם לזכור יציאת מצרים יותר מכל שאר הגאולות, כי היא גאולה שלימה, אך הגליות האחרות צריכין עדיין תשלום וכו' וכו', ובפרט כאשר תסתכל בכתוב (שמות יד, יג), כאשר ראיתם את מצרים היום לא תוסיפו לראותם עוד עד עולם, וכתיב (דברים יז, טז), לא תוסיפו לשוב בדרך הזה עוד, ולמה נאסר דירת מצרים מכל שאר ארצות, רק סוד הדבר, כי הלא גם זה לעומת זה עשה אלהים, וכאשר חטא אדה\"ר פגם בכל העולמות, וא\"כ היה מוכרח שנפלו ממנו ניצוצי הקדושים ונתערבו בכל ד' רוחות העולם ובכל ע' אומות, כל א' נטל את חלקו, והנה אותן הניצוצין, אין בהם כח לצאת משם, רק ע\"י ישראל העושין מצות ותפלות, וע\"י תפלותיהן מעלין אותן בסוד מ\"נ כנודע ליודעי חן, ומתבררין אז כולן. ודוגמת זה הוא ג\"כ בעוה\"ב אחר פטירת הצדיק מהעה\"ז, שאין לך כל צדיק וצדיק מישראל שאינו עובר ונכנס בגיהנם, אע\"פ שהוא אינו ראוי אליו. אך הענין, כשמעבירין אותו בתוך גיהנם, לחטוף ולהוציא משם נשמות בכח מעשיו, לאיזה רשע מישראל אשר בגיהנם, וזה ג\"כ עושין הצדיקים בחייהם בעה\"ז וכו', וזה ענין גלות מצרים כי אדרבא תוקף הגלות הוא סיבת הגאולה, כי כיון שנשתלמו הרגלים להתברר, אז בלע המות לנצח וכו' וכו' והנה בכל הגאולות לא היו שלימות, כי עדיין נשארו איזו ניצוצין קטנים אשר גברה יד הקליפה בהם מאוד, ולא יכלו להתברר כי אם באריכות הזמן, ולכן לא הוצרכו ישראל להתאחר שם ויצאו מן הגלות ההוא, ואמנם לטעם זה לא אסרה תורה חזרה למקום ההוא, כי עדיין צריך שיגלו לשם אותו אדם הבא משורש אותן ניצוצין שנשארו שם, כדי להוציאם משם, אך במצרים לא נשאר בה שום שורש ועיקר כלל, וא\"כ מה צריך לחזור שם. וכו' וע\"ש עוד דברים נפלאים (וראה עוד מה שנתבאר במאמר הבא בסגנון אחר ובתוספת כמה ענינים ובפרשת ויגש מאמר טז).","b":false},{"t":"וגם ידועים דברי קדוש ה' רבינו הרמ\"ק זללה\"ה בפירושו אור יקר על הזוה\"ק שביאר את טעם הדבר מדוע גזר פרעה לאמר, כל הבן הילוד היאורה תשליכוהו (שמות א, כב). וביאר, כי פרעה עשה כן, לפי שראה בקסמיו שהכח שממנו הוא יונק את כחו, הולך ומתמעט, כי עם ישראל היו מבררים ומעלים את ניצוצות הקדושה הספונים שם מכח עבודתם וצערם, והוא היה אומר, לי יאורי ואני עשיתיני (יחזקאל כט, ג), ועל כן אמר להשליך הנשמות הטהורות אל היאור, בחושבו שע\"י כך יגדיל את כחו וכח יניקתו. ולא ידע כי בא זמן גאולתם והגיע עת ישועתם. ולא יועיל כלום במעשיו, אלא אדרבא יקרב קץ ישועתם.","b":false},{"t":"ויה\"ר שנזכה בימינו אנו להעלות כל ניצוצות הקדושה מכל המקומות לשם נפלו אל המקום שממנו חוצבו ויתוקן הכל, ואז נזכה לגאולת עולם שאין אחריה הפסק כלל, אכי\"ר.","b":false}]},{"id":"15","t":"ירושלים העיר המובחרת מכל ערי העולם","p":[{"t":"וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן וְהוּא כֹהֵן לְאֵל עֶלְיוֹן: (יד, יח)","b":true},{"t":"שלם היא ירושלים וכמו שכתב בתרגום יוב\"ע (וראה מה שנתבאר עוד במאמר הקודם). ואוסיף להזכיר שבחה של ירושלים מתוך דברי הרמב\"ן ז\"ל בפירושו שכתב, \"שלם\" היא \"ירושלים\", כענין שנאמר (תהלים עו, ג), ויהי בשלם סוכו וכו', כי מאז ידעו הגוים כי המקום ההוא מבחר המקומות באמצע הישוב, או שידעו מעלתו בקבלה שהוא מכוון כנגד בית המקדש של מעלה ששם שכינתו של הקב\"ה שנקרא \"צדק\", ובבראשית רבה (מג, ו), המקום הזה מצדיק את יושביו, ומלכי צדק אדוני צדק, ונקראת ירושלם צדק, שנאמר (ישעיה א, כא), צדק ילין בה, ע\"כ.","b":false},{"t":"וכמה נאמנו דברי קדוש ה' רבינו הרמב\"ן ז\"ל, שהרי כן הוא הדבר גם בימינו, שכל הגוים יודעים את מעלת קדושת של עיר הקדש העיר שחוברה לה יחדיו המכוונת נגד ירושלים כל מעלה. ועל כן כל הדתות בחרו להעמיד כנסיותיהם בירושלים, וכמעט אין דת שלא העמידה בירושלים בית לתפלתם, והכל מתוך הכרה שזו העיר הקדושה המכוונת כנגד מקור הקדושה שבשמים, ואשר ממנה תבא ברכה לכל אתר ואתר, כי מציון תצא תורה ודבר ה' מירושלים (ישעיה ב, ג), וכל זה ויותר מזה ידוע להם היטב, ולכך הם רודפים אחריה כדי שיהיה להם חלק בה, ורוצים לינוק אפי' מעט מקדושתה, שכן דרך הסט\"א לרדוף תמיד אחר כל אפשרות ואפי' הקלושה ביותר כדי לינק דבר מה מהקדושה, כי זו היא חיותם, שכן גם הטומאה אין לה קיום מצד עצמה ח\"ו, שהרי רק רשות אחת יש ותו לא מידי, ואתה מחיה את כולם כתיב (נחמיה ט, ו), ואין יוצא מכלל זה. ואלה שיכלו לשלוט יותר התקרבו יותר ויותר, ערו ערו עד היסוד בה, שפחה כי תירש גבירה, ושכינתא בגלותא. ואנו ליה וליה עינינו נשואות תלויות, עד בא דברו לאמר לנו, עורי עורי, לבשי עוזך ציון, לבשי בגדי תפארתך ירושלם עיר הקדש, כי לא יוסיף יבא בך עוד ערל וטמא (ישעיה נב, א). ובמהרה נחזה אנן בבנין הבית נוה שאנן, וארמון על משפטו ישב, בביאת גוא\"צ בב\"א.","b":false}]},{"id":"15","t":"למה בטלה הכהונה מזרעו של שם וניתנה לאברהם","p":[{"t":"וּמַלְכִּי צֶדֶק מֶלֶךְ שָׁלֵם הוֹצִיא לֶחֶם וָיָיִן וְהוּא כֹהֵן לְאֵל עֶלְיוֹן, וַיְבָרֲכֵהוּ וַיֹּאמַר בָּרוּךְ אַבְרָם לְאֵל עֶלְיוֹן קֹנֵה שָׁמַיִם וָאָרֶץ, וּבָרוּךְ אֵל עֶלְיוֹן אֲשֶׁר מִגֵּן צָרֶיךָ בְּיָדֶךָ וַיִּתֶּן לוֹ מַעֲשֵׂר מִכֹּל: (יד, יח-כ)","b":true},{"t":"וכתב בתרגום יונתן בן עוזיאל ע\"ה, ומלכי צדיקא הוא שם בר נח, מלכא דירושלֶם וכו'. ע\"כ. וכן כתב רבינו יעקב בעל הטורים ז\"ל, \"מלך שלם\" ר\"ת \"שם\", לומר לך שהוא שם בן נח.","b":false},{"t":"וצריך להבין למה הקדים שם ובירך את אברם, לפני שבירך לאל עליון. ובאמת שראיתי בדעת זקנים מבעלי תוספות שכתבו, שבתחלה היה שם כהן כמה דאת אמר, והוא כהן לאל עליון, ואבד כהונתו על שהקדים ברכת אברהם לברכתו של הקב\"ה הדא הוא דכתיב (תהלים קי, ד), נשבע ה' ולא ינחם על דברתי מלכי צדק, כלומר, על דבורו של מלכי צדק, והיינו דכתיב \"והוא כהן\", הוא כהן, ואין זרעו כהן כך מסיק בנדרים (לב, ב וכן הוא בויק\"ר כה, ו), ע\"כ.","b":false},{"t":"ובנדרים שם, איתא, אמר רבי זכריה משום רבי ישמעאל, ביקש הקדוש ברוך הוא להוציא כהונה משם, שנאמר והוא כהן לאל עליון, כיון שהקדים ברכת אברהם לברכת המקום הוציאה מאברהם, שנאמר ויברכהו ויאמר ברוך אברם לאל עליון קונה שמים וארץ וברוך אל עליון. אמר לו אברהם וכי מקדימין ברכת עבד לברכת קונו, מיד נתנה [הכהונה שוב] לאברהם שנאמר (תהלים קי, א), נאם ה' לאדני שב לימיני עד אשית אויביך הדום לרגליך, ובתריה כתיב (שם שם, ד), נשבע ה' ולא ינחם אתה כהן לעולם על דברתי מלכי צדק, על דיבורו של מלכי צדק, והיינו דכתיב והוא כהן לאל עליון, הוא כהן ואין זרעו כהן. ע\"כ.","b":false},{"t":"ברם עדיין קשה מה הביא את שם להקדים את ברכת אברהם לברכתו של הקב\"ה. וראיתי לקדוש ה' מכובד מהר\"ח ן' עטאר ז\"ל באוה\"ח (בראשית יד, כ), שכתב וז\"ל, וברוך אל עליון, רבותינו ז\"ל אמרו, שנענש שם על אשר איחר ברכת ה' והקדים ברכת אברהם וניטלה ממנו הכהונה. ואפשר שטעם שם הוא, שלקח סדר המעשה, כי אברהם הוא מעצמו הכיר בוראו והשתדל באמונתו יתברך, ואליו יאות הברכה, ואח\"כ ברך לה' שנתרצה בו, וכן ראוי לעשות. וללמד הוא בא, שאין הקב\"ה מתרצה אלא במי שמתרצה בו קודם, והוא אומרו ברוך אברם לאל עליון, שהוא הכשיר עצמו להיות עבד לאל עליון, ולזה ברוך הוא אל עליון אשר מגן וגו', ודרך זה לא יוצדק אלא במבורך קודם. וכפי זה לא נענש שם, אלא הוא מעצמו נתנה לאברהם, וכמו שפירשתי בפסוק והוא כהן, או אפשר שנענש על הנשמע משטחיות המאמר שנראה שלא חש להקדים עבד לרבו הגם שנתכוין לטובה, ומצינו שיעניש ה' על כיוצא בזה בכמה מקומות, עכ\"ל.","b":false},{"t":"ואולי י\"ל דשם ידע תורה והיה מלמדה, ובבית מדרשו היה לומד יעקב אבינו ע\"ה י\"ד שנים (ראה ב\"ר סח, יא), ושם ראה שהכהנים נצטוו לברך את עם ישראל כמו שנאמר (במדבר ו, כג), כה תברכו את בני ישראל, ועתה שנזדמן לפניו אביהם של ישראל, הקדים לברכו. אמנם טעה בזה, כי רק הכהנים מצווים ועומדים לברך את ישראל ואין קפידא בזה שמברכים את ישראל ולא מברכים את הי\"ת, כי הי\"ת ציוה אותם על זה.","b":false},{"t":"אבל שם, היה כאן לאל עליון, והיתה עליו קפידא לפי שהוא לא מכהן לצורך עם ישראל, אלא תפקידו לשמש לפניו יתברך, והיה לו להקדים ברכת אל עליון, שהרי לפניו הוא מכהן וזו היא כל כהונתו, והיה לו לברך את הי\"ת תחילה ואח\"כ להמשיך ברכה לאברהם מכח ברכת ה', אך הוא לא עשה כן ונהג כברכת בני אהרן הכתובה בתורה, ולכן לא נמשכה כהונתו לזרעו אחריו. והמדקדק בנוסח הברכה שבירך שם את אברהם יראה כי יש כמה שינוים בין הברכה הזאת לברכה שמברכים הכהנים לעמו ישראל באהבה.","b":false}]},{"id":"15","t":"על חובת ההודאה להי\"ת על כל טובה","p":[{"t":"וַיֵּרָא ה' אֶל אַבְרָם וַיֹּאמֶר לְזַרְעֲךָ אֶתֵּן אֶת הָאָרֶץ הַזֹּאת וַיִּבֶן שָׁם מִזְבֵּחַ לַה' הַנִּרְאֶה אֵלָיו: (יב, ז)","b":true},{"t":"ופירש\"י ז\"ל, שבנה אברהם מזבח כדי להודות להי\"ת על בשורת הזרע ועל בשורת הארץ [כי ממה שהבטיח הי\"ת לאברהם שיתן לזרעו את הארץ ש\"מ שיזכה גם לזרע]. ורואים כמה חייבים להודות ולפאר לשמו יתברך על כל בשורה ועל כל טובותיו נפלאותיו.","b":false},{"t":"ורבינו בעל אוה\"ח הקדוש זיע\"א כתב על זה, וירא ה' אל וגו' ויבן שם וגו'. כוונת הכתוב להודיע הפלגת חיבת אברהם בקונו, כי ה' נגלה אליו ובשרו בזרע ובנתינת הארץ, והוא לא החשיב בשורת ב' מעלות טובות לכלום בערך שמחתו בגילוי שכינתו יתברך אליו, לקיים מה שנאמר (תהלים טז, יא), שובע שמחות את פניך, והוא אומרו ויבן מזבח לה' הנראה אליו, כאן פירש סיבת שמחתו אשר עליה בנה מזבח הוא לצד הראותו יתברך אליו, והבן. וזה אות לבניו כמה מהם אשר הרחיקו חשק הזרע בערך חשק התורה והמצות, וצא ולמד מבן עזאי בטענתו ומה אעשה ונפשי חשקה בתורה (יבמות סג, ב), ע\"כ.","b":false},{"t":"והכלל העולה שחייב אדם להודות ולהלל על כל טובה וטובה, ועל בשורה טובה, יודה, ויחזור להודות כאשר תבא הטובה עצמה, וזקנינו נוחי נפש היו עושים סעודות כדי לפאר לשם האל ברוך הוא, ומביאים ספרי הזוה\"ק וקוראים בהם בגילה וביראה וכו'. ובזה האדם מתחזק והולך בתומתו ואמונתו מחיל אל חיל.","b":false},{"t":"וכאן לימדנו רבינו בעל אוה\"ח הקדוש זיע\"א, שצריך להקריב קרבן ולהודות לה', על גילוי שכינתו יתברך, ובימינו שנסתם חזון, ג\"כ יש לאדם לשמוח שמחה עצומה כשזוכה האדם להארה בתורה ע\"י פירוש אמיתי, או פסק דין אמיתי, או איזה הישג בעבודת ה', או שזיכהו הי\"ת להשיג איזו דרגה בזיכוי הרבים, ויודה ויהלל מקרב לבו לפני ה', שזיכהו להשיג השגה בעבודתו יתברך, ונגילה ונשמחה בו, אכי\"ר.","b":false}]},{"id":"15","t":"הבטחת הארץ לאברהם אבינו רק אחרי ההפרדות מן הרשעים","p":[{"t":"וַה' אָמַר אֶל אַבְרָם אַחֲרֵי הִפָּרֶד לוֹט מֵעִמּוֹ שָׂא נָא עֵינֶיךָ וּרְאֵה מִן הַמָּקוֹם אֲשֶׁר אַתָּה שָׁם צָפֹנָה וָנֶגְבָּה וָקֵדְמָה וָיָמָּה, כִּי אֶת כָּל הָאָרֶץ אֲשֶׁר אַתָּה רֹאֶה לְךָ אֶתְּנֶנָּה וּלְזַרְעֲךָ עַד עוֹלָם, וְשַׂמְתִּי אֶת זַרְעֲךָ כַּעֲפַר הָאָרֶץ אֲשֶׁר אִם יוּכַל אִישׁ לִמְנוֹת אֶת עֲפַר הָאָרֶץ גַּם זַרְעֲךָ יִמָּנֶה: (יג, יד-טז)","b":true},{"t":"ופירש\"י ז\"ל, אחרי הפרד לוט - כל זמן שהרשע עמו היה הדבור פורש ממנו. (ולעיל שהיה לוט אצלו, וכתיב וירא ה' אל אברם, באותה שעה כשר היה וק\"ל.), עכ\"ל.","b":false},{"t":"ורבינו מוהר\"ח ן' עטאר ז\"ל באוה\"ח הקדוש, כתב שהי\"ת היה יושב ומצפה אל הדבר, ותיכף ומיד שנפרד הרשע, דיבר עמו והראהו את הארץ, והוא מה שאמר לו \"אשר אראך\" וכמו שפירשוהו במקומו.","b":false},{"t":"ורבנו עובדיה ספורנו ז\"ל כתב, שלא אמר לו זה, בהיות לוט עמו, פן בכבודו יתימרו ויתגאו לוט ורועיו ויתאמצו לגזול. ע\"כ.","b":false},{"t":"ועל כל פנים נראה שיש קשר הדוק, בין פירוד הרשע מעל הצדיק, ובין הבטחת הארץ לנחלת עולם, ואפשר דהארץ המבורכת מכל ארצות תבל, אשר עיני ה' בה תמיד, ושם ציוה את הברכה וממנה משתלשלת הברכה ובאה לכל הארצות, ונתנה לעם הנבחר מכל העמים בירור אחר בירור.","b":false},{"t":"והארץ הקדושה אין לה נחמה ואין לה שמחה אלא בבניה, וכמו שמעידים פסוקים רבים מדברי נביאנו ע\"ה, וכן תקנו חכמים במטבע ברכת ברכות הנשואין, ובברכות שאחר ההפטרה, \"משמח ציון בבניה\". כי ציון דומה לאמא שלקחו ועקרו ממנה את בניה בכח הזרוע, והיא זועקת וממררת בבכי ודמעתה על לחיה, ולא תנוח ולא תשמח עד שישיבו לה את בניה.","b":false},{"t":"והיא יושבת ומצפה לבניה שישובו אליה בכבודם והדרם כאשר כל רואיהם יעידון עליהם, כי שם ה' נקרא עליהם, ושומרים על צלם אלהים בו נבראו, בלא השפעות זרות אשר לא מאת ה' הם, ובלא שמץ מחוקות הגוים ותרבויותיהם, אשר מזה התורה מרחיקה אותנו, בציוויים חזקים, ויחודנו בזה שאנו שומרים על היותנו עם לבדד ישכון ובגוים לא יתחשב, ואיננו לומדים ממדותיהם, ומעשיהם, וממנהגיהם, ומלבושיהם וכו'.","b":false},{"t":"וזה שבא הכתוב להזהירנו כאן, ולומר לנו כי לא נתנה לאברהם אבינו ע\"ה ההבטחה הגדולה של ארץ ישראל אלא עד אחרי הפרד לוט מעמו.","b":false}]},{"id":"15","t":"הכהנים המברכים את ישראל מתברכים מהי\"ת","p":[{"t":"וַאֲבָרְכָה מְבָרֲכֶיךָ וּמְקַלֶּלְךָ אָאֹר וְנִבְרְכוּ בְךָ כֹּל מִשְׁפְּחֹת הָאֲדָמָה: (יב, ג)","b":true},{"t":"ותירגם יונתן בן עוזיאל ע\"ה, ואברך ית כהניא דפרסין ידיהון בצלו, ומברכין ית בניך, ובלעם דמלטט יתהון אילוט, ויקטלוניה לפתגם דחרב, ויתברכון בך כל זרעית ארעא. [תרגום: שהקב\"ה יברך את הכהנים שפורסים ידיהם בתפילה ומברכין את ישראל, ואילו את בלעם הרשע שבא לקלל את ישראל, יקלל אותו הי\"ת וסופו שימות בחרב וכו'].","b":false},{"t":"וראה פלא בדברי רבינו יעקב בעל הטורים ז\"ל, שגם הוא כתב כן, ומצא שהוא גימטריא של הפסוק הזה, וז\"ל, ואברכה מברכיך, בגימטריא \"כהנים המברכים בניך\", על כן \"מברכיך\" לשון רבים, \"ומקללך\" לשון יחיד. \"ומקללך אאור\", בגימטריא \"בלעם הבא לקלל בניך\".","b":false},{"t":"ובדעת זקנים מבעלי התוס' כתבו כן משם מדרש תנחומא (סדר לך לך פ\"ד), וז\"ל, ואברכה מברכיך, אמר לו הקב\"ה לאברהם, ממך יצא שבט שמברך את בני, זהו שבט לוי שיצאו ממנו כהנים שמברכים את ישראל, אמר לו אברהם, ואותו שבט מי מברכו אמר לו אני אברכנו, כדכתיב (במדבר ו, כז), ואני אברכם, ההוא דכתיב ואברכה מברכיך. ונראה לי דהיינו מה שאמרו ז\"ל במס' חולין (מט, א), ברכה לכהנים מנא לן מואברכה מברכיך, עכ\"ל.","b":false}]},{"id":"15","t":"מדוע לא סיפרה התורה את חיי אברהם קודם היותו בן ע\"ה, וכן דילגה על מעשה אור כשדים","p":[{"t":"וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ, וְאֶעֶשְׂךָ לְגוֹי גָּדוֹל וַאֲבָרֶכְךָ וַאֲגַדְּלָה שְׁמֶךָ וֶהְיֵה בְּרָכָה, וַאֲבָרְכָה מְבָרֲכֶיךָ וּמְקַלֶּלְךָ אָאֹר וְנִבְרְכוּ בְךָ כֹּל מִשְׁפְּחֹת הָאֲדָמָה, וַיֵּלֶךְ אַבְרָם כַּאֲשֶׁר דִּבֶּר אֵלָיו ה' וַיֵּלֶךְ אִתּוֹ לוֹט וְאַבְרָם בֶּן חָמֵשׁ שָׁנִים וְשִׁבְעִים שָׁנָה בְּצֵאתוֹ מֵחָרָן: (יב, א-ד)","b":true},{"t":"מצאנו להגאון רבי יצחק בלאזר זללה\"ה שהקשה בזה קושיא עצומה, והיא, מדוע דילגה התורה על סיפור חייו של אברהם אבינו ע\"ה, בשבעים וחמש שנותיו הראשונות, כי בסוף פרשת נח כתוב, שאברם נולד ונשא אשה. ומיד מתחילה התורה בלך לך, שזה היה בהיות אברם בן חמש שנים ושבעים שנה. ומאז התורה מספרת עליו בפרטות, ובאורך גדול, ומתעלמת לגמרי מכל חמשה ושבעים שנותיו הראשונות.","b":false},{"t":"ואין לומר שבאותם שנים לא היו דברים מיוחדים בחיי אברהם אבינו ע\"ה, שיש לנו ללמוד מהם חכמה ומוסר ועבודת ה', וע\"כ התורה דילגתם, שאין התורה כותבת סיפורים בעלמא. דהא מצאנו בדברי חז\"ל בגמרא ובמדרשים, דברים נוראים ונפלאים מחיי אבינו הראשון, אשר בודאי יש לנו הרבה ללמוד מהם, כגון חקירתו של אברהם אע\"ה בהשגת אמיתותו יתברך, כנגד העולם כולו ונגד אביו ואמו, ואשר לא הניח איזו דעה פילוסופית שלא סתר אותה, ולא הניח איזו עבודה זרה בעולם שלא הפריך וביטל אותה, עד שאמרו חז\"ל (ע\"ז יד, ב), מסכת ע\"ז של אברהם אבינו ע\"ה ארבע מאות פרקים היו בה, ולא זו בלבד שסתר ופרך את כל דעותיהם וערער את יסודותיהם, וכל זאת מדיליה בלא שקיבל משום אדם את האמונה שלו, אלא רק מסקנותיו שלו שהגיע אליהם בכחות עצמו. אך הוא לא נסתפק בזה, אלא ערך נגד בני דורו מלחמה גדולה וחכמה, עד שתפשו בו אביו ואמו, ומסרוהו לנמרוד, וזה ניסה להחזירו אל דרכם ואמונתם של כל הדור ההוא, אך ללא הועיל. ואז עמדו עליו להורגו, ואיתא בפרקי דרבי אליעזר (פרק כ\"ו), שאברהם אבינו ע\"ה ברח והסתתר במערה י\"ג שנים, ואח\"כ גילו אותו ונתנוהו עשר שנים בבית האסורים (ועי' עוד בבא בתרא צא, א), ואח\"כ הביאוהו לפני נמרוד, והדליק כבשן של אש, ואמר לו או שתשתחוה לצלם, או שנשליך אותך לתוך האש. ואברהם אבינו ע\"ה לגלג עליהם ועל אלוהיהם, והכריז בקול גדול ויציב, קבל עולם ומלואו. שמעדיף להשרף ולהיות עפר ואפר, ולא לבגוד באמונתו בה' אלהי השמים והארץ. והשליכו אותו לתוך אש התופת בשצף קצף ובכעס גדול, והקב\"ה פשט את יד ימינו והצילו מתוך הכבשן, ויצא אברהם משם באופן פלאי, ונתקדש שם שמים ברבים. והאם יעלה בדעת שמכל זה אין לימוד גדול, שכל בניו אחריו ילמדו אמונת ה', ויהיו נכונים למסור נפשם עליה. כמו שעשה אברהם אבינו, ומעשה אבות סימן לבנים.","b":false},{"t":"ולרוב הפלא, התורה מדלגת על כל זה, ומתחילה להכיר לנו את אברהם אבינו ע\"ה, רק מגיל שבעים וחמש שנה האם בכל זה אין די לימוד לנו ולבנינו, ללמוד ארחות חיים וקרבת אלהים.","b":false},{"t":"והגר\"י בלאזר ז\"ל תירץ קושיא זו בטוב טעם ודעת, באומרו, שזה הלימוד הגדול מעצם העובדא שהתורה דילגה על כל מה שקרה לאברהם ע\"ה עד אז, בזה התורה מלמדת אותנו שצריכים לשים את עיקר לימודינו מאברהם אבינו ע\"ה רק ממה שהיה מגיל ע\"ה ומעלה, כי אז דיבר עמו הי\"ת בראשונה. ורק מאז הוא עיקר לימודינו. משום שכל מה שחקר ודרש עד אז היה משום שעד אז עדיין לא נגלה ה' אליו, שכן תחילת דיבור ה' לאברהם היה כאן, ויאמר ה' אל אברם לך לך וגו' ואברם בן חמש שנים ושבעים שנה, ואחר שדיבר הי\"ת עם אברהם אבינו ע\"ה, שוב לא היה אברהם זקוק לחקירות ולדרישות, ושוב לא היה צריך לבקש ולחפש את ה', כי בשעה שדיבר עמו, כבר נתמלא כולו קדושה והכרה בה' בתכלית האמיתות, ושוב אין צורך לדרוש ולחקור, וכל השאלות בטלו וחדלו. והואיל וגם בנו דיבר ה' בעמדנו לפניו במתן תורה, ואת קולו שמענו מתוך האש, גם נפשנו יצאה בדברו אלינו, עד שהביא טל של תחיה, שבו עתיד להחיות את המתים והשיבנו לחיים (שבת פח, ב וראה שמו\"ר כט, ד ושהש\"ר ו, ג), וא\"כ אין לנו שום ספקות, ואין אנו צריכים לחקירות ודרישות, ואיננו צריכים לסתור ולפרוך את דברי הפילוסופים וטענותיהם, ולא לדחות מעלינו את הבלי העבודות זרות למיניהם, כי ברגע מתן תורה נתבהר הכל. וע\"כ איננו צריכים לימוד מאברהם אבינו ע\"ה בענין זה של השגת האמונה, והמלחמה על שמירת האמונה, מתוך חקירות גדולות ועמוקות, שבזה עסק אברהם אבינו ע\"ה בשנותיו הראשונות.","b":false},{"t":"וכל הלימוד הנדרש לנו אנחנו שכבר זכינו שידבר הי\"ת בנו, הוא ללמוד איך קיים אברהם אבינו ע\"ה, את מאמר הי\"ת, באיזה מסירות, ובאיזו התבטלות, וע\"כ תחילת הכרתנו עם אברהם אבינו ע\"ה, מתחילה מן הפסוק, ויאמר ה' אל אברם וגו'.","b":false},{"t":"כי לפני שהי\"ת אמר לאברהם אבינו ע\"ה כדת מה לעשות, ומה הוא דורש ממנו, היה צריך אברהם לחפש ולבקש את ה', ולהעמיק ברעיונותיו, איך להשיג את רצונו יתברך כדי לעשות נחת רוח לפניו, אבל מיום שהחל דבר ה' לפעמו, ולומר לו את מה ששואל מעמו, מכאן התורה כתבה בפרטות, כל קורותיו של אברהם כדי שיהיה לנו לאות ולמופת, שנדע איך לקיים את דבר ה' ומצוותיו כאשר קיים אברהם אבינו ע\"ה, ואת זה לומדים מכל מעשיו של אברהם ומכל נסיונותיו, אשר ניסהו ה', וזה שאמר הכתוב (בראשית יח, יט):","b":false},{"t":"כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט לְמַעַן הָבִיא ה' עַל אַבְרָהָם אֵת אֲשֶׁר דִּבֶּר עָלָיו:","b":false},{"t":"כי זה עיקר חיבתו של אברהם אבינו לפני המקום, שהוא מצוה לבניו עד סוף הדורות, והוא האיש אשר סלל את המסילה לכל הבאים אחריו, וקרא בשם ה' אל עולם. ודברי פי חכם חן, וראויים הדברים למי שאמרם.","b":false},{"t":"עוד אפשר לומר בס\"ד, שהסיבה שדילגה התורה על כל מה שעשה ופעל אברהם אבינו ע\"ה בשנות חייו הראשונות, עד הגיעו לשנת השבעים וחמש לחייו, הוא כדי שלא תחלש דעתנו ונתייאש, בראותנו את גודל גבורתו של אברהם אבינו ע\"ה, האדם הגדול בענקים, אשר עמד בעוז וחיל נגד כל בני דורו, ואפילו נגד אביו ואמו, והיה יחיד בדורו, עד שנקרא שמו אברהם העברי, שכל העולם עמדו מעבר אחד והוא מהעבר השני, ונלחם בכל כחו להבזות בע'ליהם בעיניהם (היינו את עבודה זרה שלהם הקרויה בעלים), ולגנות פסיליהם ואליליהם, בלא פחד, ומורא לא יעלה על ראשו, והיה הולך ומשפיע ומלמד דרך ה' ואמונתו, ועושה חיל בעבודתו עבודת הקדש האמיתית, ויקרא שם בשם ה' אל עולם. ונרדף עד צואר, וגם כשנשלח לתוך כבשן של אש, לא השיב ימינו אחור. ועוד ועוד. ואם היתה התורה מפרטת כל הפרטים הללו, היו דעותינו נחלשות ומתרופפות, כי מי בדורות אלו יכול לעמוד בכל הנסיונות הללו, וחז\"ל אמרו (תנדא\"ר פרק כה), חייב אדם לומר, מתי יגיעו מעשי למעשה אבותי, והיינו נופלים ביאוש, בחשבינו שצריכים לחדש ולהשיג את רצון ה' מכח עמל ויגיעה עצמית, ועל כן הקב\"ה כתב בתורתו, את סיפורו של אברהם אבינו ע\"ה רק מאז שהתחיל לצוותו, ללמדנו שחובות הדורות שלנו, היא לקיים את מאמר ה' שנצטוינו בו \"באהבה\", ואין אנו צריכים לחפש את דרך ה' במופלא ממנו, שאין הקב\"ה בא בטרוניא עם בריותיו (ע\"ז ג, א), וחובתנו להגיע למעשה אבותינו, היא, בניצול כל הכח שיש בנו לעבודתו יתברך.","b":false},{"t":"וגם אם כחנו דל וחלש, מ\"מ לא ידרשו מאתנו יותר מכחנו, וכשאנו נותנים את כל מה שיש בידינו לתת, הגענו בזה למעשי אבותינו אברהם יצחק ויעקב ע\"ה.","b":false},{"t":"* * *","b":false},{"t":"ועוד אפשר לומר שלכך נמנעה התורה מלספר את כל מעשיו, הראשונים של אברהם אבינו ע\"ה, כדי שלא יחשבו בני אדם שאפשר ללמוד ממעשיו, לחדש חידושים בהנהגה ובעבודת ה', אשר אינם כתובים בתורה, ויהיה בבחינת כל המוסיף גורע. על כן כתבה התורה על אבינו הראשון, רק מה שעשה לקיים את מצוות הי\"ת ממה שנצטוה דוקא ולא ממה שעשה מעצמו, וזה היה בהגיע אברהם לגיל שבעים וחמש, שאז דיבר בו ה', וציוהו כדת מה לעשות. ומלמדתנו תורה ללמוד ממנו את הקיום של הצו האלהי, ועיקר העיקרים, לעשות את אשר נצטוינו.","b":false},{"t":"[א\"ה וכעין זה ראיתי בשל\"ה הקדוש (הגהות לעשרה הלולים), שכתב על ענין מיתת רבי עקיבא (ברכות סא, ב), שאמרו רבותינו, בשעה שהוציאו את רבי עקיבא להריגה זמן קריאת שמע היה, והיו סורקים את בשרו במסרקות של ברזל והיה מקבל עליו עול מלכות שמים. אמרו לו תלמידיו, רבינו עד כאן, אמר להם, כל ימי הייתי מצטער על פסוק זה, בכל נפשך אפילו נוטל את נשמתך, אמרתי מתי יבא לידי ואקיימנו ועכשיו שבא לידי לא אקיימנו, היה מאריך באחד עד שיצתה נשמתו באחד וכו'. והנה מה שאמר רבי עקיבא, \"מתי יבא לידי ואקיימנו\", הראה לנו במליצת לשונו דין אחד מענין מסירת נפש, והוא זה, שלא יחשוב אדם מאחר שהוא כן מצוה רבה מצות קידוש השם, אהדר אחר מצוה זה כדרך שמהדרין אחר כל המצות, ואביא את עצמי לידי כך. דהיינו למשל כשרואה צלמי עכו\"ם ירוק עליהם וכיוצא בהן בזיון, כדי שיתפסוהו וישרפוהו, או אם יוכל להמלט יאמר לא אמלט כדי לקדש השם. העושה כן הוא מתחייב בנפשו. רק המצוה היא אם בעל כרחו בא עליו דבר זה, אז יקדש את השם יהרג ואל יעבור. וזהו שדייק ר' עקיבא \"מתי יבא לידי\", כלומר לא שאני אביא עצמי לדבר זה, רק אם יבא לידי. ובזה מתורץ למה לא הוזכר בתורה בהדיא הקידוש השם שעשה אברהם אבינו באור כשדים, כי מה שנאמר, אני ה' אשר הוצאתיך מאור כשדים, זה אינו אלא רמז בעלמא, והא ראיה הרבה מפרשים פירשו על פי פשוטו בענין אחר, וקידוש השם של חנניה מישאל ועזריה ודניאל הוזכר בהדיא. אלא הי\"ת לא כתב את מעשהו של אברהם כדי שלא ילמדו הדורות ממנו, כי הוא היה מביא את עצמו לידי דבר זה, דהיינו ששיבר צלמי תרח, וזהו אסור לדורות לעשות כן. אבל דניאל חנניה מישאל עזריה שהדבר בא להם והוצרכו לקדש השם, נכתב כדי שילמדו הדורות מהם וכן יעשו. ואם תאמר מאחר שמעשה אברהם אסור, איך עשה אברהם אבינו ח\"ו איסור. ויש לומר הוראת שעה שאני, שהוצרך לעשות כן כדי להודיע ולפרסם האמונה האמיתיית בעולם, שבאותו הזמן עדיין לא היתה נודעת ומפורסמת. עכ\"ל.","b":false},{"t":"ודבריו ישרים ונכוחים וראויים למי שאמרם. ולפי\"ז יישב רבינו חיים פלאג'י ז\"ל בספר ובחרת בחיים סדר תשא, למה לא סיפרה לנו התורה את מעשה חור שהוכיח את ישראל על עשותם את העגל ועמד נגדם עד שהרגוהו, כמו שמבואר דבר זה במדרש (ויקרא רבה י, ג), ובדברי רש\"י (שמות לב, ה). ולמה לא כתבה התורה מעשה נורא זה של חור שמסר נפשו על קדוש ה' וממנו יראו בני הדורות וכן יעשו. ותירץ דאין התורה חפצה שילמדו ממעשה חור, כי לא היה לחור להמסר להריגה על שהיה מוכיח, כיון דמצינו דהוכחה עד הכאה (עי' ערכין טז א, והלכתא כרב, וכמו שכתב רבינו הרמב\"ם בפ\"ו מהל' דעות הלכה ז'), ולכן לא היה צריך חור למסור נפשו, ולכך אין התורה מביאה את המעשה הזה כדי שלא ילמדו ממנו. ונסתייע מדברי השל\"ה הנזכרים. ע\"ש. וראה עד כמה התורה זהירה בכל דבר ודבר שכתבה, כדי להשכילנו ארחות חיים. יבח\"ר].","b":false},{"t":"ויה\"ר שנדע לשמור ולעשות ולקיים, את כל תורתו ומצותיו באהבה ובדבקות, לטוב לנו כל הימים, וגם את בנינו ובני בנינו נלמד לאהבה את ה' בכל לבם ונפשם, ולדבקה בו כל הימים.","b":false}]},{"id":"15","t":"\"אין אדם עובר עבירה אא\"כ נכנסה בו רוח שטות\"","p":[{"t":"וַיֹּאמֶר ה' אֶל אַבְרָם לֶךְ לְךָ מֵאַרְצְךָ וּמִמּוֹלַדְתְּךָ וּמִבֵּית אָבִיךָ אֶל הָאָרֶץ אֲשֶׁר אַרְאֶךָּ: (יב, א)","b":true},{"t":"כאן התורה מקצרת כדרכה ומיד אחר שנתבשרנו בסוף פרשת נח, על לידתו של אברהם אבינו ע\"ה, פותחת התורה כאן בנסיון הראשון של אברהם כשהקב\"ה אומר לו לך לך. ופשוט הדבר שאברהם אבינו ע\"ה עבר כברת דרך בעבודת ה', שכבר עברו עליו שבעים וחמש שנים, מלאות בפעילות גדולה, לעשות נפשות לה' ודרכו, ובמלחמתו הגדולה נגד האלילים ועובדיהם עד הגיעו לדרגה שהקב\"ה מדבר עמו, ומנסה אותו, וכל זאת, כדי להעלותו מעלה מעלה.","b":false},{"t":"וחז\"ל תיארו לנו באורך במדרשיהם (ראה פרקי דר\"א פרקים כו-לא וראה אבות ה, ג ואדר\"נ פל\"ג ובראשית רבה לח, יג ותנדא\"ז פרק כה ובספר הישר פרשת נח), את כל תלאותיו, עד שגדל והיה לנביא ה'. ובזה הם פירשו לנו מה שהתורה סתמה. ואמרו בן ג' הכיר אברהם את בוראו [א\"ה - כמבואר כ\"ז בנדרים לב, א ואמנם בבראשית רבה ל, ח מייתי מ\"ד בן ארבעים ושמונה הכיר את בוראו וכן הוא בעוד מקומות ברבה ותנחומא. והרמב\"ם הוב\"ד להלן נקט כמ\"ד בן ארבעים שנה היה אברהם כשהכיר את בוראו, ואמנם הראב\"ד השיגו מדברי הגמ' הנ\"ל. אך מצאתי חידוש בדברי רבינו המאירי בפתיחתו לאבות, שכתב שאברהם התחיל להכיר את בוראו בן שלש שנים, אבל עד שנשלמה אצלו הידיעה בתכלית ויצא לפרסם אלהותו יתברך ברבים היה בהיותו בן ארבעים, ע\"ש. וכן עולה מדברי הרמב\"ם דלהלן. יבח\"ר], וזה בא לו ע\"י שהתחיל לחפש את מנהיג העולם ומחוללו, אחר שהבין את השטות וההבל שבעבודת האלילים, שאנשים אומנים מפסלים בעצים ואבנים, ואחרי כן עובדים ומשתחוים להם, ומבקשים מהם. כמאמר הנביא (ירמיה ב, כז), \"האומר לעץ אבי אתה, ולאבן את ילידתני\".","b":false},{"t":"וראה את דברי רבינו הרמב\"ם (פ\"א מהל' עכו\"ם הלכה ג'), אחר שפירש מה היה קודם זמן אברהם, כתב וזה לשונו: כיון שנגמל איתן זה, התחיל לשוטט בדעתו והוא קטן והתחיל לחשוב ביום ובלילה, והיה תמיה היאך אפשר שיהיה הגלגל הזה נוהג תמיד ולא יהיה לו מנהיג, ומי יסבב אותו, כי אי אפשר שיסבב את עצמו. ולא היה לו מלמד ולא מודיע דבר, אלא מושקע באור כשדים בין עובדי כוכבים הטפשים, ואביו ואמו וכל העם עובדי כוכבים והוא עובד עמהם, ולבו משוטט ומבין עד שהשיג דרך האמת, והבין קו הצדק מתבונתו הנכונה, וידע שיש שם אלוה אחד, והוא מנהיג הגלגל, והוא ברא הכל, ואין בכל הנמצא אלוה חוץ ממנו, וידע שכל העולם טועים, ודבר שגרם להם לטעות זה שעובדים את הכוכבים ואת הצורות עד שאבד האמת מדעתם. ובן ארבעים שנה הכיר אברהם את בוראו.","b":false},{"t":"כיון שהכיר וידע, התחיל להשיב תשובות על בני אור כשדים, ולערוך דין עמהם ולומר שאין זו דרך האמת שאתם הולכים בה. ושיבר הצלמים, והתחיל להודיע לעם שאין ראוי לעבוד אלא לאלוה העולם, ולו ראוי להשתחוות ולהקריב ולנסך, כדי שיכירוהו כל הברואים הבאים. וראוי לאבד ולשבר כל הצורות כדי שלא יטעו בהן כל העם כמו אלו שהם מדמים שאין שם אלוה אלא אלו.","b":false},{"t":"כיון שגבר עליהם בראיותיו, ביקש המלך להורגו ונעשה לו נס ויצא לחרן, והתחיל לעמוד ולקרוא בקול גדול לכל העולם ולהודיעם שיש שם אלוה אחד לכל העולם ולו ראוי לעבוד, והיה מהלך וקורא ומקבץ העם מעיר לעיר ומממלכה לממלכה עד שהגיע לארץ כנען והוא קורא, שנאמר (בראשית כא, לג), ויקרא שם בשם ה' אל עולם, וכיון שהיו העם מתקבצין אליו ושואלין לו על דבריו, היה מודיע לכל אחד ואחד כפי דעתו, עד שיחזירהו לדרך האמת. עד שנתקבצו אליו אלפים ורבבות, והם אנשי בית אברהם, ושתל בלבם העיקר הגדול הזה, וחבר בו ספרים, והודיעו ליצחק בנו וכו'. ע\"ש.","b":false},{"t":"והנה כשאנו מתבוננים בדברים אלו עולה השאלה הגדולה, איך כל העולם כולו עבדו ע\"ז, בלי לחשוב מחשבה פשוטה לאמר, והרי פה להם ולא ידברו, עינים להם ולא יראו (תהלים קטו, ה), ולמה הם עובדים ומשתחוים להבל וריק, ומה גם שהיו גם אנשים חכמים ונבונים שנכשלו בזה, כמו ירבעם ואחאב ועוד, והן היום אפילו אנשים פשוטים שבפשוטים, מבינים כמה טפשי הוא הדבר, עד שאפילו אם לא היתה התורה אוסרת את זה, שום אדם לא היה עושה כן, באשר נחשב לשטות שאין גדולה ממנה בעיני כל בר דעת.","b":false},{"t":"ועוד שהיו מקטירים ומזבחים את בניהם ובנותיהם לפסילי עץ ואבן, ואנו עומדים ושואלים האם עד כדי כך נשתטו אותם בני אדם וננערו מבינת אדם.","b":false},{"t":"ובאמת מצינו בגמרא (סנהדרין קב, ב), מעשה נפלא, ברב אשי שהיה עוסק עם חבריו בדברי המשנה האומרת כל ישראל יש להם חלק לעוה\"ב, ומונה את אלה שאין להם חלק לעוה\"ב וכשהגיעו למנשה מלך יהודה, ראו שנחלקו החכמים בענינו אם יש לו חלק לעוה\"ב או אין לו חלק לעוה\"ב. והיה רב אשי אומר מחר נפתח בענין מנשה חברינו. ובאותו לילה נגלה לו מנשה בחלומו, ואמר לו וכי חברך אני או חבר בית אביך שאתה קורא לי כן, והמשיך ואמר לו, מאחר שאתה גדול בעיני עצמך, א\"כ אמור לי מהיכן בוצעים את הפת, ולא ידע רב אשי להשיבו. אמר לו מנשה, אינך יודע דבר זה ואתה קורא לי חברך. ביקש ממנו רב אשי שיודיענו דבר זה, ולמחרת ידרשנו בביהמ\"ד משמו, כדי לעשות נחת לנשמתו. ואמר לו מנשה, מהיכן שנתבשל ונאפה יותר טוב. ואז שאל רב אשי את מנשה, וכי מאחר שאתה ובני דורך הייתם חכמים כל כך, א\"כ מדוע הלכתם ועבדתם לעבודה זרה שאין בה שום תועלת. והשיבו מנשה, דע לך! שאם היית בזמן ההוא היית מרים את שפת חלוקך, כדי שייקל עליך לרוץ יותר מהר כדי לעבוד עבודה זרה, וזאת מפני יצר עבודת כוכבים שהיה שולט אז בתוקף כיעוי' שם כ\"ז בגמ' ובדברי רש\"י ז\"ל.","b":false},{"t":"והנה עולה מדברי מנשה, דרק בזמנו היה יצה\"ר של עבודה כל כך חזק, מה שאין כן עכשיו, והיינו מה שאמרו בגמ' דיומא (סט, ב), על הפסוק (נחמיה ט, ד), ויזעקו בקול גדול אל ה' אלהיהם (ועי' הגהות הב\"ח וגליון הש\"ס שם), ומקשה בגמ' מה אמרו בעת ההיא. ומשני, אמר רב ואיתימא רבי יוחנן ויי אהה, קובלים וזועקים אנו על יצר הרע של עבודת כוכבים שיש בינינו, כי הלא בעבורו נחרב בית המקדש ונשרף היכל ה' ונהרגו הצדיקים, וגלו ישראל מארצם, ועדיין יצר זה מרקד בתוכנו. ואתה הי\"ת הלא לא נתתו לנו אלא כדי שנגבר עליו ונקבל שכר, אם כן, איננו חפצים לא בו ולא בשכרו. נפל להם פתק מן השמים שכתוב בו \"אמת\" כלומר שהסכים הקב\"ה עמהם. ורב חנינא למד מזה שחותמו של הקב\"ה אמת. וכשקבלו הפתקא התענו אנשי כנסת הגדולה שלשה ימים ושלש לילות ואז מסרוהו בידיהם. ויצא מבית קודש הקדשים גור אריות בדמות אש, ואמר להם זכריה הנביא תפסוהו, זהו יצר של עבודה זרה, תפסוהו, ובעת שלכדוהו נפלה ממנו שערה ושאג הארי ונשמע קולו ארבע מאות פרסה, ואמרו אנשי כנה\"ג מה נעשה שלא יצעק עוד ולא יתעוררו עליו ברחמים מן השמים, אמר להם הנביא לשימו בתוך דוד עופרת וכו', עד שלבסוף ביטלוהו, כיעו\"ש. והעולה מכל זה דבזמנינו אין יצה\"ר דע\"ז, שכבר בטלוהו. ומשום כך, אצלינו, מובן מאליו הטפשות והשטות הגדולה שבעבודה זרה.","b":false},{"t":"אבל בזמנם שהיה היצר דעבודה זרה קיים, אפילו אנשים גדולים ועצומים כירבעם ומנשה, רצו לעבוד ע\"ז, ולא חשבו את הדבר לשטות, ולא בושו בזה. ולא בכדי אמרו רבותינו (סוטה ג, א), אין אדם עובר עבירה אא\"כ נכנסה בו רוח שטות [א\"ה - ומטעם זה, המסייע ביד עובר עבירה אפילו אם הוא במזיד עובר אלאו דלפני עור לא תתן מכשול (ויקרא יט, יד), כי החוטא דומה לעור, שהרי נכנסה בו רוח שטות, ועי' שו\"ת אחיעזר ח\"ג סי' סה. יבח\"ר].","b":false},{"t":"כי היצה\"ר יש בו כח לשבש מוחו של אדם ולהפך טעמו, עד שיאמר על טוב רע ועל רע טוב. כמו שצועק הנביא ישעיה (ישעיה ה, כ), הוֹי הָאֹמְרִים לָרַע טוֹב וְלַטּוֹב רָע שָׂמִים חֹשֶׁךְ לְאוֹר וְאוֹר לְחֹשֶׁךְ שָׂמִים מַר לְמָתוֹק וּמָתוֹק לְמָר.","b":false},{"t":"וכל כך היצר מטעה את האדם עד שאפילו שטות גדולה כזו של ע\"ז, לעשות צלם במו ידיו ולומר לו אבי אתה, ולפסל באבן ולעשות ממנה צורה ולקרא בפניה את ילידתני. ולעשות שאר צלמים ולהשתחות להם ולבקש מהם על נפשם ועל מצבם, ואפילו בניהם ובנותיהם יזבחו להם ולא יתעוררו ולא יתבוששו.","b":false},{"t":"אכן היום שאין היצה\"ר דע\"ז, לא תמצא אפי' ברחוקים ביותר מי שיתאוה לזה, או מי שיחשוב דבר זה למעלה, ואצל הכל דבר זה נחשב לשטות גמור. והוא שאמר לו מנשה מלך יהודה לרב אשי, \"אי הוית התם הוית נקיט בשפולי גלימא ורהטת אבתרה\".","b":false},{"t":"והחלק יעיד על הכל, כי מעבירה זו שנסתלק יצה\"ר שלה, נלמד על שאר המצות כולם, שנראים לעתים בעיני בני אדם כלא מובנים ח\"ו, וכן עבירות אחרות שנפשו של אדם מחמדתן שהכל הוא משום שהיצר הרע של אותה עברה עדיין קיים. ועלינו לדעת שראייתנו אינה ראיה אמיתית ונכונה, כל עוד לא סילקנו את היצר מקרבנו, אבל כל זמן שהוא עדיין שוכן בתוכנו, הוא משטה בנו ומשבש את שכלנו, עד שמסתלק ההגיון והטעם הטוב, והוסר הדעת. ולא מבדילים בין טוב לרע, ובין ישר למעוות. ויכולים לחשוב את הדברים הגרועים ביותר לדברים הגונים, או לפחות לדברים של מה בכך, כי כבר נכנסה הרוח שטות של אותה עבירה.","b":false},{"t":"ומזה נוכל לשער ולהתבונן, שלעתיד לבא, כאשר יסתלק היצר הרע גם משאר העבירות, אז יעמוד האדם ויתמה על עצמו, איך חטא חטא פלוני, ואיך עבר עבירה פלונית, אוי לה לאותה בושה.","b":false},{"t":"וכן כשהאדם יעבוד את ה' בלבב שלם, ויסלק מלבו את כל העקמימות, עד שיסלק את היצה\"ר לגמרי מתוכו, או אז הוא יתמה תמיהה גדולה על עצמו, ולא יבין איך חשב על עבירה פלונית שאיננה עבירה, ועל עבירה פלונית שהיא רק דבר קל וכדו'. כי בהסתלק היצה\"ר מתוכנו חוזרת הראיה הברורה לנשמה, ותיכף היא מבחינה בין טוב לרע, ודוגמא לדבר הזה, הוא, מה שהיום אנו תמיהים איך הראשונים עבדו ע\"ז.","b":false},{"t":"וזה מה שהיה אצל רבי שמעון בר יוחאי ורבי אלעזר בנו (כמבואר במסכת שבת לג, ב), שנחבאו במערה י\"ב שנים ועסקו בתורה, ונזדככו כל כך, עד שכשיצאו מן המערה אחר י\"ב שנים, וראו אנשים חורשים וזורעים, אמרו אוי לאלו שמניחים חיי עולם ועוסקים בחיי שעה, וכל מקום שנותנין עיניהם בו מיד נשרף, עד שיצאה בת קול ואמרה להם להחריב עולמי יצאתם חזרו למערתכם וכו'. כיעו\"ש.","b":false},{"t":"כי מי שזכה ועסק בתורה כרשב\"י ובנו עד שהוציאו כל ריח ואבק דיצה\"ר מלבם, כבר לא היו יכולים להבין איך אנשים עוסקים בחיי שעה, דהרי מלאכת עוה\"ז יכולה להתקיים ע\"י גוים, כמ\"ש רש\"י שם (וכדברי רשב\"י בברכות לה, ב). ודבר זה בא אצל האדם כשהוא מצליח לבטל את יצרו ממנו שאז יתמה האדם ויתפלא על מעשיו שעשה מכבר.","b":false},{"t":"ובזה אמרתי בס\"ד להסביר מה שאמרו חז\"ל (יומא כח, ב וקדושין פב, א ותנדא\"ר פ\"נ), שאברהם אבינו קיים את כל התורה כולה. וצריכים להבין מנין ידע את כל המצות בכדי שיוכל לקיימן, והרי עדיין לא נתנה תורה, והקב\"ה לא ציוהו, ומהיכן ידע אברהם מה אסור ומה מותר, ומה חובה ומה מצוה. אך לפי האמור לעיל יוצא חידוש, דבעצם כל המצוות והאיסורים של תורה הם דברים הגיוניים ומובנים, שהאדם הישר והנקי משיג אותם בהגיונו מצד עצמו, גם אם לא ציותה התורה ע\"ז. אלא שהיצר הרע מכניס באדם רוח שטות עד שדברי התורה נראים לו כלא הגיוניים, וגם אחר שלומד ויודע מהתורה בכ\"ז יצרו מנסה לבלבל אותו, וק\"ו שלא יתעורר האדם מאליו לקיים את המצוות כל זמן שהיצר מקשקש בקרבו, אך בדבר שאין בו יצר הרע, כמו העבודה זרה בימינו, הרי כל אחד מאתנו מבין כמה הדבר טפשי ומכוער, ואפילו אם התורה לא היתה מצוה על זה, היו מתרחקים ממנה.","b":false},{"t":"ועל כן אברהם אבינו ע\"ה שעמד ונתגבר, עד שכבש את יצרו כליל, בבחינת \"ויחבוש את חמורו\" (בראשית כב, ג), שחבש ושיעבד את ה\"חומר\" שבו, ושלט בו שליטה מוחלטת, וכל כך התרחק מכל רע, עד שכל רצונותיו הגשמיים התבטלו מפני רצונו יתברך, וכל מחשבותיו וכמיהותיו היו מכוונים מעתה רק לדבר אחד ויחיד, איך לעשות רצון קונו. ברוב אהבה ויראת ה', ונפשו היתה טהורה ונקיה מהשטות שהיצה\"ר מכניס באדם. א\"כ לא יפלא איפה, שכל המצוות ואיסורי תוה\"ק היו בעיניו כמובנים מאליהם אף בלי כל ציווי, וקיימם בעונג ואהבה.","b":false},{"t":"וזה מה שאמרו חז\"ל בגמ' דסוכה (נב, א), לעתיד לבא, מביאו הקדוש ברוך הוא ליצר הרע ושוחטו בפני הצדיקים ובפני הרשעים, צדיקים נדמה להם כהר גבוה ורשעים נדמה להם כחוט השערה, הללו בוכין והללו בוכין. צדיקים בוכין ואומרים, היאך יכולנו לכבוש הר גבוה כזה. ורשעים בוכין ואומרים, היאך לא יכולנו לכבוש את חוט השערה הזה וכו'. ע\"ש.","b":false},{"t":"והנה כאן חז\"ל מתארים שתי ראיות שונות, על המאבק שבין האדם ויצרו. הרשעים מבטאים את הראיה של זמן העתיד אחר שחיטת היצה\"ר, ואז היצה\"ר נראה להם כחוט השערה. ובוכים וזועקים איך לא התגברו ואיך לא קלטו דברים כה פשוטים והגיוניים, שלפי מה שהם רואים אותו בעת שה' מבטל אותו, כבר נגלה לעינם האמת של התורה ועבודת ה', וההגיון הצרוף והברור של כל מצוה ומצוה, ואחרי שנודעה להם האמת הפשוטה הזו, אז יגדל כאבם, והם צועקים ובוכים על מחדליהם, וחלישות עמידתם בעניני הרוח. והצדיקים בבכייתם מבטאים את הראייה שאדם רואה בעת המאבק, כל עוד היצר קיים, שאז נראה כהר תבור ועל זה הם בוכים, כי אף שנצחו את היצה\"ר, מכל מקום, היה להם הדבר קשה כהר תבור, ועתה הם תמהים האם על דברים אלו היו צריכים להלחם כ\"כ הרבה, והלא כ\"כ פשוטים ומובנים הם.","b":false},{"t":"ועל כן טוב לגבר כי ישא עול זה מנעוריו, להיות שליט ברוחו בעוז ותעצומות, לעמוד נגד תאוותיו, ונגד עצותיו של היצר הרע, אשר בא בלבוש של ידיד ורע, עם פנים מאירות ושוחקות, ומראה לנו אותות של ידידות ואהבה, ובלבו ישים אורבו, כי כל מגמתו להפיל את האדם ברשתו, ולהדיחו מדחי אל דחי ולהורידו לבאר שחת רח\"ל.","b":false},{"t":"וע\"כ יאזור חיל וגבורה, לעמוד כנגדו בכל עוז, וגם כי יחנן קולו, לא יתפתה לו ולא יאבה לו, רק ישים שם ה' לנגד פניו. כמאמה\"כ (תהלים טז, ח), שויתי ה' לנגדי תמיד, והוא יעמוד לימינו, עזרו ומגינו, והבא ליטהר מסייעין אותו (יומא לח, ב ע\"ז נה, א מנחות כט, ב).","b":false},{"t":"(אור ליום ו' י\"ב מר חשון התש\"מ)","b":false}]}]},{"slug":"וירא","name":"פרשת וירא","items":[{"id":"16","t":"ע\"י העבירות הגוף נעשה \"בסיס לדבר האיסור\" וע\"י המצוות נהפך הגוף ל\"בסיס לדבר מצוה\"","p":[{"t":"וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וַיַּחֲבשׁ אֶת חֲמֹרוֹ וַיִּקַּח אֶת שְׁנֵי נְעָרָיו אִתּוֹ וְאֵת יִצְחָק בְּנוֹ וַיְבַקַּע עֲצֵי עֹלָה וַיָּקָם וַיֵּלֶךְ אֶל הַמָּקוֹם אֲשֶׁר אָמַר לוֹ הָאֱלֹהִים: (כב, ג)","b":true},{"t":"בכמה מקומות בגמ' ופוסקים מובא ענין \"בסיס לדבר האסור\" (מבואר במס' שבת בהרבה מקומות כיעוי' שם מז, א ושם קיז, א ושם קכ, ב ושם קמב, ב ובשו\"ע או\"ח סי' שט וסי' שיא), דגם הבסיס שעליו מונח הדבר המוקצה, הריהו מקבל את הדינים של האיסור המונח עליו. וכן הדבר באדם שעובר עברה, שאז גופו נעשה \"בסיס לדבר האיסור\", וטומאת האיסור חלה עליו. אבל כשעוסק במצוה בגופו, גופו נעשה \"בסיס למצוה\" ולקדושה העולה ממנה, וגופו מתקדש מאותה קדושה.","b":false},{"t":"ומצינו בשו\"ע או\"ח סי' ש\"ט סעיף ד' באם הניח אבן או מעות על הכר או על החבית, שאסור לנענע את הכר או החבית, ואע\"פ שהכר או החבית הם היתר גמור וצריך להם בשבת, מ\"מ נאסרים הם עצמם מחמת המוקצה שעליהם וכ' שם הרמ\"א ז\"ל (בהג'ה שם), דכשיש לזה דין בסיס לדבר האסור, אז אפילו אם נוטל את החפץ המוקצה מן הבסיס שהיה מונח עליו, מכל מקום אסור לטלטל את \"הבסיס\", דמאחר שנעשה בסיס לדבר האיסור למקצת השבת אסור כל השבת כולה. וכתב הרב משנ\"ב (שם ס\"ק כ'), וז\"ל, אסור להטות ולנער, דנעשה החבית והכר בסיס להמוקצה שעליהם \"והם גופא מוקצה\", עכ\"ל.","b":false},{"t":"ואעפ\"י שהדברים נאמרו בעניני שבת ויו\"ט, מכל מקום יש להתלמד מהם לענין עבודת הי\"ת. ויש ללמוד יסוד חשוב עד כמה צריך האדם להתרחק מדבר עבירה רח\"ל, כי כאשר האדם עוסק בעבירה נעשה כל גופו בסיס לדבר האיסור, וכמו שהעבירה היא מוקצה מחמת מיאוס, כן נעשה כל גופו מוקצה, וכגודל חומרת העבירה וטומאתה כן גודלת טומאת גופו של העוסק בה, אשר משים את עצמו בסיס אליה. כי העבירה מטמטמת את לבו של אדם כי הוא בסיס ומשכן לעבירה, וכל טומאתה שורה עליו ומטמטמת את לבו, רח\"ל.","b":false},{"t":"וכן הוא בהיפך כאשר עוסק במצוה אז נעשה גופו בסיס לקדושה, שבכל לימוד ובכל מצוה שעושה יש קדושה השייכת לאותה מצוה, וכשעוסק במצוה ההיא גופו נטהר ומתקדש באותה קדושה ועולה מדרגה לדרגה. צא וראה מה שכתב הרמב\"ם ז\"ל (פ\"ד מהל' תפלין הלכה כה), קדושת תפילין, קדושתן גדולה היא, שכל זמן שהתפילין בראשו של אדם ועל זרועו, הוא עניו וירא שמים, ואינו נמשך בשחוק ובשיחה בטילה, ואינו מהרהר מחשבות רעות, אלא מפנה לבו בדברי האמת והצדק, לפיכך צריך אדם להשתדל להיותן עליו כל היום שמצותן כך היא, אמרו עליו על רב תלמידו של רבינו הקדוש שכל ימיו לא ראוהו שהלך ארבע אמות בלא תורה או בלא ציצית או בלא תפילין, ע\"כ. והוא פשוט כי בזמן הנחת התפילין נעשה הגוף בסיס ומשכן לקדושה של התפילין, כי בכל תפלה יש כ\"א אזכרות של הוי'ה ב\"ה, מלבד יתר השמות הקדושים, וכגודל כוונתו והכנתו כן תגדל השפעת הקדושה עליו עד אין קץ, וכן הוא בכל מצוה ומצוה שעוסק בה.","b":false},{"t":"[א\"ה - הוא דמצינו בסנהדרין (צט, ב), אמר רבא כולהו גופי דרופתקי נינהו טובי לדזכי דהוי דרופתקי דאורייתא. ופירש רש\"י ז\"ל, וז\"ל, דרופתקי, כיס ארוך שמשימין בו מעות, כל הגופין נרתיקין הם לקבל ולהכניס דברים, אשריו למי שזכה ונעשה נרתיק לתורה. והן הן הדברים, שהאדם הוא נרתיק, ואם יאחז בדרך טובה יהפוך להיות נרתיק דקדושה. יבח\"ר].","b":false},{"t":"ואולי זהו מ\"ש חז\"ל (קדושין מא, א), \"מצוה בו יותר מבשלוחו\", וכ' רש\"י בריש פרק האיש מקדש (קדושין שם), דמצוה בו שיהיה גופו עוסק במצוה, היינו, שיש מעלה גדולה בזה שגופו של אדם עוסק במצוה, ולכן פשוט וברור היתרון שיש למקיים את המצוה בגופו על המקיים את המצוה ע\"י שליח, משום שכשהאדם עוסק בגופו בעשיית המצוה, אז גופו נעשה משכן לקדושתה והשפעתה של אותה מצוה, ועולה במדרגות הקדושות, מה שאי אפשר לו לאדם כשהוא מקיים המצוה ע\"י שליח.","b":false},{"t":"ואולי זה הטעם במצוות שהן חובת הגוף כמו ציצית ותפילין וכיו\"ב שאי אפשר לעשותן ע\"י שליח, אלא ע\"י בעצמו, כי מצוות אלו נועדו להשפיע שפע מיוחד על רמ\"ח אבריו ושס\"ה גידיו של אדם, לסייעו ולעודדו במלחמתו הגדולה נגד היצה\"ר וחילותיו. ואי אפשר להשיג המעלות הללו ע\"י שליח, כי אין הגוף נעשה בסיס לדבר מצוה כשהמצוה נעשית ע\"י שליח, ולכן במצוות הללו לא שייך כלל למנות שליח.","b":false},{"t":"וזהו ענין וישכם אברהם בבקר \"ויחבוש את חמורו\", שחבש בעצמו את חמורו כדי לטרוח בעסק המצוה ולהתקדש על ידה, ואמרו רבותינו (ראה ב\"ר נה, ז), שהיו לאברהם הרבה עבדים, ועכ\"ז לאהבת הי\"ת ולקדושת המצוה, חבש הוא בעצמו את חמורו. כדי להשיג שפע קודש עילאי ע\"י עסקו במצוה.","b":false},{"t":"ובזכות העסק במצוה נעשה האדם מקודש יותר, ומסוגל יותר לקיים את יתר המצוות בעומק ובטהרת הלב והולך מחיל אל חיל כי שכר מצוה מצוה, עד שמשיג השגות גבוהות ודרגות נעלות. [א\"ה וזה שאמרו (אבות ד, ב), מצוה גוררת מצוה, ועבירה גוררת עבירה. כי אחר שעשה האדם מצוה, גופו התקדש, והגוף מבקש לעשות עוד מצוה להרוות את צמאונו, וה\"ה בהיפך ח\"ו, אם עושה עבירה, חלה טומאה על הגוף, ומעתה הוא מתאוה ביותר לעבור עוד עבירה רח\"ל. יבח\"ר].","b":false},{"t":"ואולי זהו הענין שאמרו ישראל (שמות כד, ז), \"נעשה ונשמע\", והיינו, כי ע\"י העשיה מתקדש הגוף כנ\"ל, ומעתה יכולים לשמוע ולהבין יותר ויותר את דברי התורה הקדושה.","b":false}]},{"id":"16","t":"ע\"י העמידה בנסיונות מתמתקין הגבורות","p":[{"t":"וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וְהָאֱלֹהִים נִסָּה אֶת אַבְרָהָם וגו': (כב, א)","b":true},{"t":"המלה נסיון בפשוטה בחינה, שהי\"ת בוחן את לב אברהם. ועיין בתרגום יונתן בן עוזיאל שמבאר מה הוא אחר הדברים האלה, ובתרגום ירושלמי כתב וה' מנסי ית אברהם בנסיונא עשיראה. אך אפשר לפרש ג\"כ נסיון מלשון \"נס להתנוסס\", שנשאו ורוממו, והעלהו במעלה גדולה, וכמו שפירש\"י ז\"ל על הפסוק (שמות כ, יז), כי לבעבור נסות אתכם בא האלהים, ע\"ש.","b":false},{"t":"ולמעשה שניהם נכונים, שהנסיון באמת הוא בחינה שהקב\"ה בוחן לבות וכליות של עבדיו, לדעת הישנם אוהבים את ה' באמת ובתמים, וכשעומדים בנסיון, מתנשאים ומתרוממים למדרגה גבוהה.","b":false},{"t":"ובשני המקומות נאמר \"האלהים\", שהנה בתחילה היה נראה הנסיון הזה כבא להציק לאברהם ולצערו, באמור לו קח נא את בנך את יחידך אשר אהבת, את יצחק, והעלהו לעולה וגו' (בראשית כב, ב). ואין לך צער גדול מזה, ונראה שבא הנסיון הזה מצד מדת הדין הרמוזה בשם אלהים.","b":false},{"t":"אך באמת כל זה הוא לטובת האדם ולתועלתו, כדי לרוממו ולזכותו, וזוכה ע\"י זה לדברים הרבה, ומשום כך כתב בשינוי, ולא אמר ואלהים ניסה את אברהם, אלא \"והאלהים\" ניסה וגו'. כי אלהים עולה למנין פ\"ו, ובתוספת אות ה'א בראשו יהיה חשבונו צ\"א, כמנין הוי'ה אדנו'ת, שהוא התמתקות הדינים כידוע (א\"ה – עי' שער הפסוקים פרשת תולדות דאי' שם דהאלהים הוא בינה עילאה, והנה מהבינה דינים מתערין, וכיון שהוא בחינת בינה עילאה אפשר דהוא רחמים. יבח\"ר).","b":false},{"t":"והנה אעפ\"י שנראה שהנסיון הזה בא ממדת הדין הקשה, כמו שכתב הרב אור החיים הקדוש זיע\"א, וז\"ל, אמר \"והאלהים\", בתוספת וא\"ו ותוספת ה\"א, לומר, כי מלבד הנסיונות שקדמוהו עוד הוסיף לנסותו בגבורת הדין נסיון עצום. עכלה\"ק. אך זה רק בשעת הנסיון שחושב שכן יקום וכן יהיה שיצטרך להקריב את בנו, אבל סופו של דבר הוכיח על תחלתו שהכל היה לטובה ולישועה, שאמר לו עתה ידעתי כי ירא אלהים אתה וגו' (בראשית כב, יב), ומאז עומדת זכות העקדה לכל בני ישראל לדורות עולם.","b":false},{"t":"ומדת \"האלהים\", היא גבורות ממותקות, שהה\"א הם ה' חסדים שממתקים את הגבורות (ראה מה שנתבאר להלן פרשת תולדות מאמר יב ופרשת ויחי מאמר י), וזה בא ע\"י אתערותא דלתתא, וזה שנאמר (בראשית כב, ג-ד), וישכם אברהם בבקר, ויחבוש את חמורו וגו', ויקם וילך אל המקום אשר אמר לו האלהים. שע\"י מעשיו אלה שהשכים וחבש הגיע אל המקום שבו נתמתקו ה' גבורות דאלהים ונהיה \"האלהים\".","b":false},{"t":"וזה שממשיך ואומר (שם שם, ז), ויאמר יצחק אל אברהם אביו וגו', הנה האש והעצים, שהנה יצחק מדתו גבורה והוא שואל את אביו, אבא הנה \"האש והעצים\" שהם גבורות, ואיה \"השה\" שהוא חסד הבא למתק הדינים. ואברהם משיב ואומר לו (שם שם, ח), אלהים יראה לו השה לעולה בני. כי מדת הדין בחרה ביצחק להיות לעולה, ואח\"כ ערך אברהם את העצים והאש על גבי המזבח, ויעקוד את יצחק (שם שם, ט), והיינו כפיית הדינים והכנעתם וע\"י כן מתמתקים, וישלח אברהם את ידו וגו' (שם שם, י).","b":false},{"t":"ואז נאמר (שם שם, יא), ויקרא אליו מלאך ה', \"מלאך\" ג\"כ גימטריא צ\"א כמו האלהים, וגם כתיב בתריה שם הוי'ה. ואמר לו (שם שם, יב), \"עתה ידעתי כי ירא אלהים אתה\", שמתוך יראתו מוכן להקריב את בנו, כדי לעשות רצון קונו, ועי\"ז נכללו באברהם שהוא חסד, גם מדת הגבורה ונהיה \"האלהים\", שהתמזגו בו חסדים וגבורות יחד, והשלים את כל זה בהעלותו את האיל לעולה, וקרא שם המקום \"ה' יראה\" בחינת אהבה ובחינת יראה, שם הוי'ה הוא חסד ורחמים, ויראה הוא הגבורות.","b":false},{"t":"גם ראיתי משם האר\"י ז\"ל שיראה גימטריא גבורה (ראה פע\"ח שער עולם העשיה פ\"ה ובלקוטי תורה לישעיה אות ו). ממילא יוצא שהוי'ה יראה, הם חסדים וגבורות שנתמזגו יחד במקום הזה הלא הוא הר המוריה, שהוא מקום מקדשנו, ושם התמתקו.","b":false},{"t":"וסופו של הענין, וישב אברהם בבאר שבע (בראשית כב, יט), דרק אחר שזכה לעמוד בנסיון הוא יושב בשובע ובנחת.","b":false},{"t":"ואולי לזה ירמוז השם ירושלם, יר\"ו הם אותיות רי\"ו גימטריא גבורה כידוע, ושלם פירושו מיזוג דינים וגבורות שזהו ענין השלמות, והתפארת שכלולה משניהם, היא שלמות, אמצעי שלם.","b":false},{"t":"ושו\"ר בס\"ד בספר דעת זקנים מבעלי התוספות שם על הפסוק (שם שם, יד), ויקרא שם המקום וגו', והוא הר המוריה ונקרא כן לפי שמיראה נעשה הר, שהיה בתחלה עמק ומיד נעשה הר גבוה ותלול ומתנשא, ולפי שמתחלה נקרא שלם שנאמר (בראשית יד, יח), ומלכי צדק מלך שלם. ואברהם קראו יראה, נקרא עתה ירושלים שיש במשמעות יראה ושלם. ע\"כ דברות קדשם ז\"ל.","b":false}]},{"id":"16","t":"על הזהירות בחינוך הילדים","p":[{"t":"וַתֵּרֶא שָׂרָה אֶת בֶּן הָגָר הַמִּצְרִית אֲשֶׁר יָלְדָה לְאַבְרָהָם מְצַחֵק, וַתֹּאמֶר לְאַבְרָהָם גָּרֵשׁ הָאָמָה הַזֹּאת וְאֶת בְּנָהּ כִּי לֹא יִירַשׁ בֶּן הָאָמָה הַזֹּאת עִם בְּנִי עִם יִצְחָק, וַיֵּרַע הַדָּבָר מְאֹד בְּעֵינֵי אַבְרָהָם עַל אוֹדֹת בְּנוֹ, וַיֹּאמֶר אֱלֹהִים אֶל אַבְרָהָם אַל יֵרַע בְּעֵינֶיךָ עַל הַנַּעַר וְעַל אֲמָתֶךָ כֹּל אֲשֶׁר תֹּאמַר אֵלֶיךָ שָׂרָה שְׁמַע בְּקֹלָהּ כִּי בְיִצְחָק יִקָּרֵא לְךָ זָרַע, וְגַם אֶת בֶּן הָאָמָה לְגוֹי אֲשִׂימֶנּוּ כִּי זַרְעֲךָ הוּא, וַיַּשְׁכֵּם אַבְרָהָם בַּבֹּקֶר וַיִּקַּח לֶחֶם וְחֵמַת מַיִם וַיִּתֵּן אֶל הָגָר שָׂם עַל שִׁכְמָהּ וְאֶת הַיֶּלֶד וַיְשַׁלְּחֶהָ וגו': (כא, ט-יד)","b":true},{"t":"והנה רבותינו מפרשי התורה כתבו לפרש את הענין הזה כל אחד לפי דרכו, כמו שיעוי' בדברי רש\"י ז\"ל והרמב\"ן ז\"ל, ובדברי רבינו בעל אור החיים הקדוש ז\"ל, ובדברי שאר המפרשים.","b":false},{"t":"והנה בדרך פשוטה יש מקום להבין כך, מחד גיסא עומדת לה שרה אמנו ע\"ה ורואה כי ישמעאל יצא לתרבות רעה, והיא יראה מאד שלא ישפיע לרעה על יצחק בנה שעודנו רך בשנים, ומתוך דאגה לבנה, גזרה אומר, ואמרה לאברהם אבינו, גרש את האמה הזאת ואת בנה. כדי שלא ילמד יצחק ממעשיו הרעים.","b":false},{"t":"ומאידך גיסא עומד לו אברהם אבינו, והיה רע בעיניו עד מאד לגרש את בנו, שמא אחר שיגרשנו יתקלקל יותר, וגם שהדבר היה מנוגד לדרכו שהרי אברהם אבינו היה אוהב את הבריות ומקרבן לתורה בדרכי נועם, וכיצד יעשה היפך מדתו וינהג ההיפך בבנו היוצא מחלציו. והיה אברהם מתקשה בפסיקת הדין הזה כדת מה לעשות.","b":false},{"t":"ואז קיבל פסק דין עליון על כל עליון, בצו אלהי מפורש, ויאמר אלהים אל אברהם, אל ירע בעיניך על הנער ועל אמתך, כל אשר תאמר אליך שרה שמע בקולה.","b":false},{"t":"וא\"כ ראינו שהי\"ת הצדיק את דברי שרה, שאכן יש סכנה מוחשית ליצחק בהיותו בקרבת ישמעאל, והוסיף הי\"ת ואמר לאברהם הוי יודע, כי ביצחק יקרא לך זרע, כלומר, אעפ\"י שהנך צודק בדאגתך לישמעאל בנך, מ\"מ אין מקום לספק, ואין לך להשאירו בסמוך ליצחק, כי ביצחק יקרא לך זרע, וכל מה שהבטחתיך על הזרע ועל הארץ ועל חיי עולם, כל זה הוא בבנך יצחק, כי הוא אבי עם סגולה מבחר המין האנושי אשר בחר לו יה לעמו ולסגולתו, ואליו תשים את עינך ולבך.","b":false},{"t":"וכדי לפייס את אברהם שלא ירע לבבו על גורל בנו ישמעאל, אמר לו הי\"ת, וגם את בן האמה לגוי אשימנו כי זרעך הוא.","b":false},{"t":"ולמדנו מכאן עד היכן מגיעה מדת הזהירות, להזהר ולהשמר מכל שמץ השפעה רעה על הילדים. והבא להטהר מסייעין אותו (שבת קד, ב ע\"ז נה, א מנחות כט, ב).","b":false}]},{"id":"16","t":"הולך את חכמים יחכם","p":[{"t":"וַיְהִי בְּשַׁחֵת אֱלֹהִים אֶת עָרֵי הַכִּכָּר וַיִּזְכֹּר אֱלֹהִים אֶת אַבְרָהָם וַיְשַׁלַּח אֶת לוֹט מִתּוֹךְ הַהֲפֵכָה בַּהֲפֹךְ אֶת הֶעָרִים אֲשֶׁר יָשַׁב בָּהֵן לוֹט: (יט, כט)","b":true},{"t":"ראינו כי הצלת לוט באה לו בזכות דודו, אברהם אבינו ע\"ה. ואין המכוון שנשאו לו פנים מן השמים רק משום שהיה קרובו של אברהם. אמנם הטעם האמיתי הוא, מפני שלוט היה הולך עם אברהם ולמד ממעשיו, ואפילו שלמד רק מעט ממעשיו, בכל זאת, הושפע לטובה, כאדם שנכנס לחנותו של בשם שאפילו אם יצא כלעומת שבא, בכל זאת נדבק בו מן הריח הטוב.","b":false},{"t":"וכן מצינו בלוט שלמד את דרכי הכנסת אורחים מאברהם אבינו, ואפילו שבא לידי סכנה, בכל זאת הכניס אורחים לביתו בהיותו בסדום, כמבואר בפסוקים (בראשית יט, א-ח), ולא הפקירם אל ההמון הפרוע אשר ביקשו לעשות בהם שפטים. והוא שנאמר (בראשית יג, ה), וגם ללוט ההולך את אברם היה צאן ובקר ואהלים. ולא רק צאן גשמי הרויח לוט מהליכתו עם אברהם אבינו, כי אם גם נכסי צאן ברזל רוחניים שבאו לו מורשה ממדותיו הטובות של דודו אברהם, בבחינת איקרב לגבי דהינא ואידהן (שבועות מז, ב ורש\"י שם).","b":false},{"t":"ואפשר שגם ע\"י הקירבה לצדיק, זוכים לנקיות המדות, וכמו שמצינו שאמר אברהם לאליעזר עבדו המושל בכל אשר לו, בשלחו אותו לקחת אשה לבנו ליצחק, כי אם אל ארצי ואל מולדתי תלך וגו' (בראשית כד, ד), כי נדבקו כמה מדות טובות בבני משפחתו של אברהם, ולכן צריך אליעזר לקחת דוקא אשה משם ולא מבנות כנען שהיו חסרות כל מדה טובה. וזהו שנאמר כאן ויזכור אלהים את אברהם, וישלח את לוט מתוך ההפיכה, שזכר את המדות הטובות של אברהם שנדבקו בלוט, ולכן וישלח את לוט.","b":false},{"t":"ואפשר שזהו הענין בהזכרת זכות אבות לבני בניהם, דכיון שאנו חלק מהם, בודאי שהשורש הוא טוב וטהור, ויש תקוה.","b":false}]},{"id":"16","t":"אור וחושך משמשים בערבוביא אצל לוט","p":[{"t":"וַיָּבֹאוּ שְׁנֵי הַמַּלְאָכִים סְדֹמָה בָּעֶרֶב וְלוֹט ישֵׁב בְּשַׁעַר סְדֹם וַיַּרְא לוֹט וַיָּקָם לִקְרָאתָם וַיִּשְׁתַּחוּ אַפַּיִם אָרְצָה, וַיֹּאמֶר הִנֶּה נָּא אֲדֹנַי סוּרוּ נָא אֶל בֵּית עַבְדְּכֶם וְלִינוּ וְרַחֲצוּ רַגְלֵיכֶם וְהִשְׁכַּמְתֶּם וַהֲלַכְתֶּם לְדַרְכְּכֶם וַיֹּאמְרוּ לֹּא כִּי בָרְחוֹב נָלִין, וַיִּפְצַר בָּם מְאֹד וַיָּסֻרוּ אֵלָיו וַיָּבֹאוּ אֶל בֵּיתוֹ וַיַּעַשׂ לָהֶם מִשְׁתֶּה וּמַצּוֹת אָפָה וַיֹּאכֵלוּ: (יט, א-ג)","b":true},{"t":"מן הפסוקים האלו רואים כמה הושפע לוט מדרך החסד של אברהם אבינו ע\"ה, בבחינת וגם ללוט ההולך את אברם היה צאן ובקר (יג, ה), וכעין שאמרו רבותינו (מדרש משלי פי\"ג וילקו\"ש קהלת רמז תתק\"נ), על הפסוק (משלי יג, כ), הולך את חכמים יחכם וגו'. משל למי שנכנס לחנותו של בשם, אף על פי שאינו מוכר לו ואינו לוקח ממנו הוא יוצא וריחו וריח בגדיו מבושמין, ואין ריח זז ממנו כל היום. עליו הוא אומר, הולך את חכמים יחכם, וכך היה עם לוט שלמד ממדותיו ומהנהגותיו של אברהם, הן בעצם החסד שעשה בכל לב, כמו שנאמר \"ויפצר בם מאד\", וגם קיים מצות הכנסת אורחים מתוך מסירות נפש, שכן ידע לוט מן החוק שחוקקו בסדום, שהנותן פת לעני יהרג. וגם מצוות אחרות קיים, כמו שנא' וגם מצות אפה, לכבוד פסח, וכמ\"ש רש\"י ז\"ל (שם). והולך את חכמים יחכם, וכנראה שזה חוק קבוע בטבע שהאדם לומד ממי שהוא הולך לידו.","b":false},{"t":"אך הואיל ולוט היה מתאוה גם להנאות העולם, ונתן דעתו על הרכוש ועל האדמות וכו', עד שהיה נותן לצאנו לרעות בשדות אחרים, ולא חש לגזל, כי אמר הארץ נתנה לאברהם ואברהם אין לו בנים ואני הוא יורשו, והגיע לריב עם אברהם, עד שהגיע למצב נורא, שאברהם איש החסד, שמקרב את כל באי עולם ומכבדם ומעריכם, הוכרח לומר לו, הפרד נא מעלי וגו' (בראשית יג, ט), כדי שלא תהיה מריבה ביניהם, ולוט בחר לו את כל ככר הירדן, כמו שנאמר (בראשית יג, יא), ויסע לוט מקדם, ובדברי רבותינו איתא (ב\"ר מא, ז), שהסיע לוט את עצמו מקדמונו של עולם, ואמר אי אפשי לא באברהם ולא באלהיו. והלך לדור עם אנשי סדום שנאמר בהם (בראשית יג, יג), ואנשי סדום רעים וחטאים לה' מאד, ובחר בהם לשבת עמהם, והושפע מדרך זו, עד שנחשב לרשע כמותם וכמו שהעיד עליו הכתוב (שם שם, י\"ד), וה' אמר אל אברם אחרי הפרד לוט מעמו, וכתב רש\"י ז\"ל שם, כל זמן שהרשע עמו היה הדבור פורש ממנו.","b":false},{"t":"ומכאן רואים את ההשפעה הכפולה שהושפע לוט, הן מאברהם והן מאנשי סדום, באומרו לאנשי סדום, אחי אל נא תרעו, הנה נא לי שתי בנות וגו' (בראשית יט, ז-ח), וכתב הרמב\"ן ז\"ל מתוך שבחו של האיש הזה, באנו אל גנותו, שהיה טורח מאד על אכסניא שלו להציל אותם מפני שבאו בצל קורתו, אבל שיפייס אנשי העיר בהפקר בנותיו, אין זה כי אם רוע לב, שלא היה ענין הזימה בנשים רחוק בעיניו, ולא היה עושה לבנותיו חמס גדול כפי דעתו, לכך אמרו רבותינו (ראה תנחומא וירא פי\"ב), בנוהג שבעולם אדם מוסר עצמו על בנותיו ועל אשתו והורג או נהרג, וזה מוסר בנותיו להתעולל בהן, א\"ל הקב\"ה לעצמך אתה משמרן. עכ\"ל.","b":false},{"t":"וזה נורא למתבונן לראות איך מצד אחד לוט מוסר את נפשו כדי להציל את אורחיו, ומאידך מפקיר את בנותיו, ופוסח על שתי הסעיפים. וכך נראים אלו שפורשים מדרכי תורה ומוסר, שהם מלאים סתירות וחרטות, אחת למעלה ושבע למטה כענין הרשעים שמלאים חרטות כל ימיהם. וראינו כי גם שגדל לוט עם אברהם, אך כיון שנתן את עיניו לתאוות העולם והבליו, זה וזה לא נתקיימו בידו, ואור וחושך משמשים אצלו בערבוביא. והחזרה בתשובה רחוקה ממנו, כי אינו מכיר בחטאיו ומרבה בתירוצים ומיישב בהם את סערות לבו ומצפונו, בכך שמדי פעם עושה צדקה או חסד. ומאידך מעשיו במחשכים, עד שהיה קל בעינו הפקר בנותיו, ודין גרמ'א ליה שבנותיו ילדו ממנו בנים למוא'ב יזעקו ונזכר שמו לדראון עולם, ואף אברהם נתרחק ממנו מפני שמו הרע, כאשר אמרו רבותינו (ב\"ר נב, ג-ד), על הפסוק (בראשית כ, א), ויסע משם אברהם, להתרחק מלוט שיצא עליו שם רע.","b":false}]},{"id":"16","t":"אנשי סדום היו מצדיקים את מעשי הרשע שלהם בכל מיני תירוצים ודרכים, ולכן לא יכלו לשוב בתשובה","p":[{"t":"וַיֹּאמֶר ה' זַעֲקַת סְדֹם וַעֲמֹרָה כִּי רָבָּה וְחַטָּאתָם כִּי כָבְדָה מְאֹד: (יח, כ)","b":true},{"t":"מקצת ממעשיהם הרעים של אנשי סדום ועמורה, יכולים אנו ללמוד מהתנהגותם עם לוט, בעת שאירח את המלאכים בביתו, שכל אנשי העיר צרו על ביתו כמבואר בפסוקים (בראשית יט, א-ט). וביתר שאת רואים אנו בגמ' דסנהדרין (קט, ב), מעשה מזעזע בההיא רביתא, דהות קא מפקא ריפתא לעניא בחצבא, אגלאי מילתא, שפיוה דובשא, ואוקמוה על איגר שורא, אתא זיבורי ואכלוה, והיינו דכתיב זעקת סדום ועמורה כי רבה, ואמר רב יהודה אמר רב על עסקי ריבה (תרגום: מעשה היה בסדום בנערה שנכמרו רחמיה על עני ונתנה לו פת ועשתה זאת בהחבא שהטמינה את הפת תוך כד מים ובעת שיצאה לשאוב נתנה לו את הפת בלא שישגיחו בה, ואנשי סדום היו תמהים על העני הזה שלא מת ברעב, והשגיחו אחריו, ואז ראו את מעשה הנערה, לקחוה וסכו אותה בדבש ושמו אותה על חומת העיר ובאו דבורים ועקצוה ואכלוה עד שמתה, וזוהי זעקת סדום, זעקת הנערה מסדום במיתה האכזרית שגזרו עליה).","b":false},{"t":"וממעשה זה ומשאר דברי חכמים שם, משתקפת בפנינו תמונה קודרת מאד, על מעשיהם של אנשי סדום ועמורה, ועל רוע לבם, ומלבד שקלקלו והשחיתו מעשיהם עד שעברו כל גבול של צדק והגיון אנושי. הנה פשעם עוד יותר חמור כיון שזו לא היתה תופעה של יחידים, או כנופיות פשע למיניהם, שזה מצוי בכמה מקומות בעולם. אבל בסדום הפשע היה \"ממוסד\", שזה נעשה ע\"י בתי משפט של סדום ועמורה, ועל דעת ממשלתם ומנהיגיהם, אשר חוקקו חוקים כאלה המשוללים כל יסוד של צדק והגיון, ובאין אומר ואין מוכיח מכל העם מקצה. ורואים כאן דבר משונה מאד, שאנשי סדום לקחו את המעשים הנבזים והשפלים ביותר, וקבעום לחק ומשפט, ועל פי זה ניהלו את כל חייהם.","b":false},{"t":"ואז מתעוררת תמיהה גדולה, איך לא נמצא שום אחד בכל חמשת הכרכים הגדולים, שיקום ויזעק חמס, כנגד השוד והשבר, המתהלך בריש גלי בראש כל חוצות, הלא גם בגויים שאין בהם תורה, מ\"מ תמיד ימצאו בהם אנשים שיצעקו על כגון דא, ולו רק מפני הסדר הטוב, שהחיים יתנהלו כשורה.","b":false},{"t":"ובטרם ניישב תמיהה זו, צריך עוד להתבונן בהמשך הפרשה, שאחר שהקב\"ה הודיע לאברהם על הפורענות הצפויה לסדום ועמורה, כתיב, ויגש אברהם ויאמר, האף תספה צדיק עם רשע. (בראשית יח, כג), וכתב רש\"י ז\"ל (שם), ויגש - מצינו \"הגשה למלחמה\", \"הגשה לפיוס\", ו\"הגשה לתפילה\", כיעו\"ש. ומקור הדברים בדברי רבותינו במדרש רבה (ב\"ר מט, ח). וכאן אנו רואים את רחמיו המרובים של אברהם, שהוא תמיד הצטיין במידה נעלית זו, שלא רק את עצמו ביקש להציל, אלא דאג להציל לכל בני דורו, בכל מיני דרכים. ואפילו על אנשים רשעים ושפלים כאנשי סדום, גם מהם לא נתייאש, וניגש להתפלל ולהתחנן עליהם, ואפילו לדבר קשות כלפי מעלה, כאומרו האף תספה וכו', ולא חסך שום מאמץ כדי להצילם (וכאשר נתבאר במאמר הקודם), ורק אחר הויכוח הארוך, ואחר שנתברר שאין בערי סדום אפילו עשרה צדיקים, שב למקומו.","b":false},{"t":"אכן כאן מתעוררת שאלה גדולה, על אברהם אבינו ע\"ה, למה לא ניגש לסדום עצמה, לנסות להחזירם בתשובה, כמו שהיה עושה בכל מקום בו היה הולך, בבחינת ואת הנפש אשר עשו בחרן (בראשית יב, ה), שהיה מחזיר בתשובה את בני דורו. ואדרבא עתה שכבר הסכים הקב\"ה לבטל הגזירה אם ימצאון עשרה צדיקים בעיר, א\"כ אברהם אבינו ע\"ה היה צריך ללכת מיד לסדום לעשות נפשות ולהחזירם בתשובה, כדי להשיב מעליהם את חרון אף ה' וחמתו, אולי ישוב וניחם האלהים (יונה ג, ט), כי רחמי הי\"ת מרובים. וכן יש לשאול, למה הקב\"ה לא שלח את אברהם להשיב בתשובה את אנשי סדום, וכאשר שלח את יונה בן אמתי לנינוה. ומה ראו על ככה.","b":false},{"t":"ואולם מכל מה שנתבאר צריכים אנו לומר, שאנשי סדום היו מאלה שדרכם ישרה בעיניהם, ומנסים לעטוף את מעשיהם הרעים בעטיפת צדק ויושר, וכך הטיפו לבני עמם, וכך חינכו את בניהם ובנותיהם, שזה הוא הצדק והיושר, וכל מי שנוהג היפך מעשיהם קראוהו חוטא ומורד באמת. והן יצר לב האדם רע מנעוריו (בראשית ח, כא), והרע נקלט בו במהרה, עד שנעשה הדבר להגיונם הרגיל של כל תושבי סדום ועמורה.","b":false},{"t":"וכמו ששמעתי בשם איזה מפרשים שכתבו, שאנשי סדום אמרו, הלא ידוע כי מה שהביא את המבול לעולם היה עון \"גזל\", כי מלאה הארץ חמס (בראשית ו, יא ושם יג), ואם הקב\"ה ברא עניים וברא עשירים, א\"כ זה רצונו יתברך. וכל המשנה ונותן לעני אוכל ומשקה או כסף וכדו', הריהו כגוזל מהקב\"ה, והוא עלול להביא מבול לעולם, וא\"כ הרי הוא בגדר הבא להורגך השכם להורגו, על כן הוא חייב מיתה. ובאמת שטענת הבל זו כצלמה ודמותה ממש, טען טורנוסרופוס הרשע לרבי עקיבא (ראה בבא בתרא י, א), אם אלהיכם אוהב עניים הוא, מפני מה אינו מפרנסם, ורבי עקיבא השיבו כדרכו, כיעו\"ש. ובמקום שאין תורה ויר\"ש, אז גם זה יכול להחשב הגיון בריא ונכון, בבחינת רק אין יראת אלהים במקום הזה והרגוני על דבר אשתי (בראשית כ, יא). וממילא לא יפלא כיצד הצליחו רשעי עולם אלה לחנך את כל אנשי סדום ועמורה בהשקפה מעוותת כזאת, עד שלא נמצאו אפילו עשרה אנשים צדיקים בכל הכרכים ההם. ועוד דמסתמא באו בטענה של \"קידמה ועבודה\" באומרם, שמצב הגון הוא שכל אחד משיג את לחמו בעמל כפיו, ואם יתנו לאנשים לחם חינם, יהיו הרבה בטלנים שיסמכו ע\"ז, ויתרבה הפשע והרשע וכו'. כי הבטלה היא אם כל חטאת, ויש בבטלה כדי להרוס את חיי החברה, ולהמיט אסון על כל האיזור. ועוד טענות נוספות כהנה וכהנה, שהן היפך האמת ודעת תורתנו הקדושה שהיא תורת אלהים חיים,","b":false},{"t":"[א\"ה - וגם בימינו אנו, ראינו איך הרשעים הגדולים, רשעי עולם, באו בשיטות שונות ומשונות כדי לגזול את חייהם וממונם של אנשים אחרים, והנה הרשעים הגדולים ביותר בדורות הללו ג\"כ נהגו מנהג זה, וכל אחד מהם אחראי ישירות לרצח של עשרות מליוני בני אדם, והנה אחד מהם ימ\"ש כתב ספר שלם המכונה \"מיין קמפף\" להסביר מהו המאבק שלו נגד היהודים ומהן דעותיו, ואחד הדברים הבולטים ביותר בספרו, הוא מלחמתו במדת הרחמים והחסד, בספרו זה הוא טוען, כי לדוגמא, משפחה שיש בה אדם מוגבל, הריהו מונע מבני משפחתו לעסוק בעיסוקיהם, כי צריכים לטפל בו ולהשגיח עליו, ולשיטתו יש להמית את המוגבלים והחולים, ולטענתו, עם ישראל הם אלו שנותנים צדקה לעני ולחולה ומחזיקים בידו ומשאירים אותו קיים בחברתינו, וזו טענה אכזרית ומרושעת שאין דוגמתה. ויותר מזה, הוא טוען בספרו כי מדת הרחמים והחסד עוברים אצל היהודים בתורשה ואינם יכולים להמנע ממדתם זו, ואז הוא מדבר על מכשיר \"האינקובטור\", שהוא אחד מפלאי הדורות, כי בעבר, תינוק שהיה נולד בטרם שכלו חודשי הריונו היה מת, ומכשיר זה מהוה תחליף לבטן האם שבה נמצא העובר, ויש לו במכשיר הזה תנאים הקרובים לבטן אמו, וכך הוא מתפתח בפנים עד שיגדל ויהיה בריא. והנה המכשיר הזה, אומר אותו רשע ימ\"ש, מי מסוגל להמציא אותו, רק יהודי שרגש הרחמים והחמלה על הדל פועמת בלבו, כי גוי לא יכול לחשוב בכלל על דבר כזה, ובאמת ממציא \"האינקובטור\" היה יהודי, ואכן מיום שעלה אותו רשע לשלטון עד עת נפילתו, נאסר על בתי החולים בגרמניה הנאצית, להחזיק מכשיר \"אינקובטור\" זה, וכל עובר שנולד בטרם זמנו מת. אכן דומים רשעים אלו לרשעי סדום וגרועים מהם. וכן עשו אחרים במדינות אחרות, ואפילו אם לא הגיעו עד למימדי הרשעות ההיא, אבל דרכם היא אותה דרך, וזה חוזר בכל דור ודור, פעם במקום פלוני ופעם במקום אחר. הצד השוה שבהם, שכולם אבות נזיקין ורבי קטוליא, שופכי דם אדם כמים, ומנסים לתת למעשיהם דימוי של מעשה נכון וצודק. והרואה יראה כי תורותיהם המעוותות של הרשעים האלו קנו שביתה ומשכו את לבות ההמונים אחריהם. ואין זאת אלא מן הטעמים האמורים ומבוארים באר היטב במאמר שלפנינו. יבח\"ר].","b":false},{"t":"ובזה יובן למה הי\"ת לא ציוה לאברהם להוכיחם, וגם אברהם לא ניסה לעשות כן, כמו שנהג לעשות בכל מקום. כי בכל המקומות היו רשעים ועובדי אלילים וכו'. אך הם ידעו שמעשיהם רעים ואינם רצויים, רק שתאותם גברה עליהם לעשות כן, וכיון שידעו שאין זו הדרך, היה אברהם מוכן לעבוד ולהשתדל עמהם להשיבם, והצליח להשיבם ולהוציא פירות מעמלו המבורך. אך אנשי סדום דרכם היתה מוצדקת וישרה בעיניהם, ולפי שיבוש דעתם, אדרבה, אברהם הוא הטועה, ודרכיו אינם נכונים, והיו שופטים את שופטיהם, כמו שראינו בלוט שאירח את המלאכים בביתו, וכל אנשי העיר נסבו על ביתו. ואמרו לו עתה נרע לך מהם, ועוד דברים קשים ומרים. והם היו מתנגדיו המובהקים של אברהם אבינו ע\"ה, ושל דרכו בקדש, וחרטו על דגלם אידיאולוגיה ריקה ושדופה, להלחם במדת החסד, שהיא מדתו של אברהם אבינו ע\"ה, ובכהאי גונא לא מקבלים תוכחה, והם בבחינת לצים ופוחזים, ונאמר (משלי ט, ח), אל תוכח לץ וגו'. וכשם שמצוה לומר דברים הנשמעים, כך מצוה שלא לומר דברים שאינן נשמעים (יבמות סה, ב). ולא הרי אנשי נינוה כאנשי סדום ועמורה, שאנשי נינוה חטאו ונתחייבו כליה, אכן תיכף שבא יונה והוכיחם, ידעו את חטאם והכירו בו, ובזה היתה רפואה למכתם. שכן ההודאה בחטא הוא היסוד לבנין התשובה. אבל אנשי סדום ועמורה היו חכמים וצדיקים בעיניהם, ובחרו לדרוש ולפלפל כדי להצדיק את רשעם. ושום תוכחה לא תועיל להם, כי הם אוטמים עצמם נגד כל הגיון אמיתי וכל דעה ישרה, ונאמר (משלי כו, יב), חכם בעיניו תקוה לכסיל ממנו. ולא נותר לו לאברהם אבינו ע\"ה, אלא להתפלל בעדם אל ה' ברוך הוא, אשר לו נתכנו עלילות, ושליט בדעות בני אדם, והוא יודע לשובב לבות בני אדם, וכך עשה עמד והתפלל עליהם, וה' שופט כל הארץ יעשה הישר בעיניו.","b":false},{"t":"ואכן עמד והתפלל עליהם כמדת חסדו (חסד לאברהם), והתחנן לפני המקום לקיימם, והאריך בתפלה, עד שלא היה יכול עוד להתפלל, ואחר שנסגרו כל האפשרויות, הניח הענין בידי מי שאמר והיה העולם, אשר הוא יודע את שרשי הנפשות, ומה ראוי לכל אחד ואחד, ומה לפנים ומה לאחור, ואין אנו יכולים לרחם יותר ממנו, שהוא מקור כל הרחמים, צדיק וישר הוא, אל אמונה ואין עול, צדיק וישר הוא (דברים לב, ד).","b":false},{"t":"(אור ליום ו' י\"ט מר חשון התש\"מ).","b":false}]},{"id":"16","t":"רחמנותו של אברהם אבינו על אנשי סדום","p":[{"t":"וַיֹּאמֶר ה' זַעֲקַת סְדֹם וַעֲמֹרָה כִּי רָבָּה וְחַטָּאתָם כִּי כָבְדָה מְאֹד, אֵרֲדָה נָּא וְאֶרְאֶה הַכְּצַעֲקָתָהּ הַבָּאָה אֵלַי עָשׂוּ כָּלָה וְאִם לֹא אֵדָעָה, וַיִּפְנוּ מִשָּׁם הָאֲנָשִׁים וַיֵּלְכוּ סְדֹמָה וְאַבְרָהָם עוֹדֶנּוּ עֹמֵד לִפְנֵי ה', וַיִּגַּשׁ אַבְרָהָם וַיֹּאמַר הַאַף תִּסְפֶּה צַדִּיק עִם רָשָׁע, אוּלַי יֵשׁ חֲמִשִּׁים צַדִּיקִם בְּתוֹךְ הָעִיר הַאַף תִּסְפֶּה וְלֹא תִשָּׂא לַמָּקוֹם לְמַעַן חֲמִשִּׁים הַצַּדִּיקִם אֲשֶׁר בְּקִרְבָּהּ, חָלִלָה לְּךָ מֵעֲשׂת כַּדָּבָר הַזֶּה לְהָמִית צַדִּיק עִם רָשָׁע וְהָיָה כַצַּדִּיק כָּרָשָׁע חָלִלָה לָּךְ הֲשֹׁפֵט כָּל הָאָרֶץ לֹא יַעֲשֶׂה מִשְׁפָּט, וַיֹּאמֶר ה' אִם אֶמְצָא בִסְדֹם חֲמִשִּׁים צַדִּיקִם בְּתוֹךְ הָעִיר וְנָשָׂאתִי לְכָל הַמָּקוֹם בַּעֲבוּרָם, וַיַּעַן אַבְרָהָם וַיֹּאמַר הִנֵּה נָא הוֹאַלְתִּי לְדַבֵּר אֶל אֲדֹנָי וְאָנֹכִי עָפָר וָאֵפֶר, אוּלַי יַחְסְרוּן חֲמִשִּׁים הַצַּדִּיקִם חֲמִשָּׁה הֲתַשְׁחִית בַּחֲמִשָּׁה אֶת כָּל הָעִיר וַיֹּאמֶר לֹא אַשְׁחִית אִם אֶמְצָא שָׁם אַרְבָּעִים וַחֲמִשָּׁה, וַיֹּסֶף עוֹד לְדַבֵּר אֵלָיו וַיֹּאמַר אוּלַי יִמָּצְאוּן שָׁם אַרְבָּעִים וַיֹּאמֶר לֹא אֶעֱשֶׂה בַּעֲבוּר הָאַרְבָּעִים, וַיֹּאמֶר אַל נָא יִחַר לַאדֹנָי וַאֲדַבֵּרָה אוּלַי יִמָּצְאוּן שָׁם שְׁלשִׁים וַיֹּאמֶר לֹא אֶעֱשֶׂה אִם אֶמְצָא שָׁם שְׁלשִׁים, וַיֹּאמֶר הִנֵּה נָא הוֹאַלְתִּי לְדַבֵּר אֶל אֲדֹנָי אוּלַי יִמָּצְאוּן שָׁם עֶשְׂרִים וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֶשְׂרִים, וַיֹּאמֶר אַל נָא יִחַר לַאדֹנָי וַאֲדַבְּרָה אַךְ הַפַּעַם אוּלַי יִמָּצְאוּן שָׁם עֲשָׂרָה וַיֹּאמֶר לֹא אַשְׁחִית בַּעֲבוּר הָעֲשָׂרָה, וַיֵּלֶךְ ה' כַּאֲשֶׁר כִּלָּה לְדַבֵּר אֶל אַבְרָהָם וְאַבְרָהָם שָׁב לִמְקֹמוֹ: (יח, כ-לג)","b":true},{"t":"הנה אנשי סדום ועמורה הפליאו ברשעם וחטאתם לפני ה', ובחרו להם בדרך רשע ופשע, לדכאת עניים ואביונים, וללחום בבעלי החסד והרחמים, לרודפם ולהמיתם, וכמעשה הנורא הנזכר במסכת סנהדרין (דף ק\"ט ע\"ב), בנערה אחת מסדום שנכמרו רחמיה על איזה עני שנקלע לשם, ובכל פעם שהיתה יוצאת לשאוב מים, היתה מחביאה בכדה פרוסת לחם, ובצאתה לשאוב מים מן הבאר היתה מבטת כה וכה, וכראותה כי אין איש צופה במעשיה היתה משליכה לעני את הלחם והולכת לה, ואנשי סדום בראותם את העני הזה שנשאר בעיר ואינו גווע ברעב, הבינו מיד, כי יש אדם בעירם שמחיה אותו, והחלו לעקוב אחר העני הזה ואחר זמן גילו כי הנערה היא הנותנת לו לחם. מה עשו, לקחו את הנערה ומשחו אותה בדבש וקשרוה על החומה, והיו הדבורים באות ועוקצות אותה בכל גופה עד שיצאה נפשה ביסורים נוראים, וזהו שאמר הכתוב \"זעקת סדום ועמורה\", כלומר, זעקת הנערה מסדום ועמורה באה אלי, ונתמלאה סאתם, כי מרוב רוע לבם, לא זו בלבד שלא עזרו לעני, אלא אף רדפו והמיתו למי שגומל חסד לעניים.","b":false},{"t":"וכשנתמלאה סאתם של אנשי סדום ונידונו לכליה, אמר הקב\"ה, המכסה אני מאברהם את אשר אני עושה, וגילה לו שעתידה לבא פורענות גדולה על אנשי סדום ועמורה. ואברהם אבינו בשמעו כן. מיד, ויגש אברהם ויאמר, האף תספה צדיק עם רשע. (בראשית יח, כג), וכתב רש\"י ז\"ל (שם): ויגש, מצינו \"הגשה למלחמה\", \"הגשה לפיוס\", ו\"הגשה לתפילה\", כיעו\"ש. ומקור הדברים בדברי רבותינו במדרש רבה (ב\"ר מט, ח).","b":false},{"t":"וכל המתבונן בדברים אלו עומד ומרעיד, בראותו איך אברהם אבינו שם את נפשו בכפו, ומדבר דיבור קשה לפני הי\"ת ונלחם ומבקש פיוס ומתפלל ומתחנן, ובעבור מי כל זאת, עבור אנשי סדום הרעים והחטאים לה' מאד. בעבורם הוא מסתכן, בעבורם הוא עורך את מלחמתו ומשנן את לשונו באש שלהבת, ומסכן את נפשו לומר \"השופט כל הארץ לא יעשה משפט וגו' ועוד ועוד.","b":false},{"t":"והמביט בזה רואה עד היכן מגיעים רחמיו של אברהם אבינו ע\"ה, ועד היכן מתפשטת מדת חסדיו, חסד אמיתי, חסד פשוט ושלם, חסד נקי מכל חשבון ופניה. חסד שאינו מצטמצם רק למכריו ולאנשי שלומו בלבד, ואפילו לא חסד לצדיק וחסיד, אלא חסד גם עם אנשים רשעים וחטאים לה' ולאדם. ולכן גם על סדום ועמורה נכמרו רחמיו ויהמיון, ולא יכל לעצור בנפשו, וניגש בכל המסירות נפש, להושיעם בתפלתו.","b":false},{"t":"ואולם יש בזה עוד גילוי נפלא מאד, במעשה החסד של אברהם אבינו ע\"ה, \"עמוד החסד\" לדורות עולם.","b":false},{"t":"שכן מלבד הרשע שהרבו אנשי סדום כלפי שמיא וארעא, עוד יש במעשיהם הרעים, הכרזת מלחמה על דרכו ושיטת חייו של אברהם אבינו ע\"ה, אשר כולו היה חסד וצדקה עם כל באי עולם, בממונו בגופו ובנפשו, ורשעים אלו נלחמו בכל עוז נגד שיטתו של אברהם. הוא קורא בשם ה' אל עולם, ומרבה להיטיב עם כל באי עולם, ולעומתו הם חרטו על דגלם למרוד בהי\"ת ובכל דרכיו, ולהלחם נגד הטוב והחסד בכל כחם.","b":false},{"t":"והנה טבע הוא באנוש שכאשר שני אישים, או שתי קבוצות מתנגדות זו לזו, ומתנצחות זו עם זו, והאחד מהם מפסיד, הרי שחברו העומד כנגדו שש ושמח. וקל וחומר בן בנו של קל וחומר, כשהויכח הוא אידיאולוגי, וזה דורש וממליץ על דרכו, שראוי ליישם אותה כדרך חיים, ובא זה שכנגדו, וסותר את דבריו עד היסוד, וממליץ על מרכולתו וסחורתו שלו, לאמור זו הדרך וזו השיטה, אשר בצילה יתקיימו שוכני תבל לטוב להם. וכשהאחד מצליח להוכיח לעיני הכל עד כמה טעה חבירו, הרי שהוא מתמלא בשמחה, שמעתה יראו הכל כי הוא זה שצדק בדבריו וחבירו טעה.","b":false},{"t":"והנה בודאי שהיה ראוי לאברהם אבינו לשמוח על מפלת סדום, כי אנשי סדום יסדו את חוקיהם על אדני הרשע והשחיתות, ונתקיים בהם מאמר הנביא (מלאכי ג, טו), וגם נבנו עושי רשעה וגו', כלומר, שכבר נהפכה דרכם הרעה לחק ומשפט, ובחמשת כרכי סדום ועמורה הנהיגו את חוקיהם על אדני הרשע והשחיתות. ובודאי בנפול סדום ועמורה היה לאברהם אבינו לשמוח, כי הנה עתה נתגלתה שחיתותם, ונתפרסם קלון סדום ועמורה ברבים, ומעתה יכירו וידעו כל באי עולם, כי לה' מצוקי ארץ, והוא חפץ בטובת בני האדם, ומיישר את אורחותם בחוקים ומשפטים צדיקים אשר יעשה אותם האדם, וחי בהם.","b":false},{"t":"ואם כן בעת שהקב\"ה גילה את דברו לאברהם, כפי טבע העולם היה לו לשמוח ולצהול, על הבשורה הגדולה של מפלת סדום ועמורה, כי בזה יוודע דבר ה' ודתו בכל העולם כולו, ויכירו וידעו הכל שאברהם אבינו עבד נאמן לבורא העולם ומנהיגו, ודרכו תנצח ותתפשט ימה וקדמה צפונה ונגבה, ויתרחבו ללא היכר גבולות הקדושה, ומעתה שמחת עולם תהא על ראשו של אבי השיטה האמיתית של עשיית צדקה וחסד, והעולם בחסד יתכונן.","b":false},{"t":"אבל הוא ע\"ה לא שש ולא שמח אל הבשורה הזו, אלא מיד נגש להתפלל עליהם בכל כחו, וכאן התגלתה מדת החסד של אברהם אבינו, בכל עומקה והדרה, כי גם עתה לא שש לבו, ולא שמח במפלת אויביו בנפש, אלא עמד והתפלל עליהם, בכל כחו ונפשו, ומסר את נפשו כדי לגמול עמהם חסד ולהצילם מרדת שחת. ואף למלחמה הכין את עצמו, ובכל כחו עמד להגן עליהם. אלו הן קצות דרכיו של האדם הגדול בענקים, אבי האומה. ויה\"ר שנלך בדרכו, ונדבק במדת החסד לטוב לנו כל הימים.","b":false}]},{"id":"16","t":"לימוד מוסר מתוך התבוננות בעונשי הרשעים","p":[{"t":"וַה' אָמָר הַמֲכַסֶּה אֲנִי מֵאַבְרָהָם אֲשֶׁר אֲנִי עֹשֶׂה, וְאַבְרָהָם הָיוֹ יִהְיֶה לְגוֹי גָּדוֹל וְעָצוּם וְנִבְרְכוּ בוֹ כֹּל גּוֹיֵי הָאָרֶץ, כִּי יְדַעְתִּיו לְמַעַן אֲשֶׁר יְצַוֶּה אֶת בָּנָיו וְאֶת בֵּיתוֹ אַחֲרָיו וְשָׁמְרוּ דֶּרֶךְ ה' לַעֲשׂוֹת צְדָקָה וּמִשְׁפָּט לְמַעַן הָבִיא ה' עַל אַבְרָהָם אֵת אֲשֶׁר דִּבֶּר עָלָיו: (יח, יז-יט)","b":true},{"t":"לכאורה צריכים להבין מה הקשר בין הדברים, ומה שייכות יש בין הענין שאברהם יצוה את בניו ואת ביתו אחריו, ובין הצורך להודיעו את משפט סדום ועמורה. והנה מדברי רש\"י משמע שבגלל שהוא עתיד לצוות את בניו ואת ביתו על דרך ה', על כן הי\"ת אוהבו ומחבבו, וזהו לשון ידעתיו לשון חיבה, ועל כן צריך אני להודיעו.","b":false},{"t":"וראיתי לרבותינו בעלי התוספות שם, שכתבו, ולפי שיהיה לגוי גדול אגלה לו דין של סדום, כי יודע אני בו כי למען דין שאעשה ברשעים הללו יצוה את בניו לשמור דרך ה' ולעשות צדקה ומשפט, למען הביא ה' וגו', ויזכו לירש את הארץ, שאם לא יהיו שומרים משפט וצדקה לא יזכו לזה.","b":false},{"t":"נמצא דמשום שידעתיו שיצוה, צריך להודיעו משפטן של הרשעים, ומזה ילמד את בניו, שידעו מהן תוצאות העונש של הרשעים, ועד כמה צריך להתרחק מהם ומדרכם. ויצוה אותם לשמור את דרך ה', ויזכו על ידי זה לירש את הארץ. שהוא התנאי לירושת א\"י.","b":false},{"t":"ורבינו יעקב בעל הטורים ז\"ל כתב, \"אשר יצוה את ביתו\", ס\"ת \"תורה\", \"אשר יצוה\" גימטריא \"תורה\", וגימטריא \"ברית\".","b":false}]},{"id":"16","t":"הכנסת אורחים של אברהם אבינו","p":[{"t":"וַיֵּרָא אֵלָיו ה' בְּאֵלֹנֵי מַמְרֵא וְהוּא ישֵׁב פֶּתַח הָאֹהֶל כְּחֹם הַיּוֹם, וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו וַיַּרְא וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אָרְצָה, וַיֹּאמַר אֲדֹנָי אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ אַל נָא תַעֲבֹר מֵעַל עַבְדֶּךָ, יֻקַּח נָא מְעַט מַיִם וְרַחֲצוּ רַגְלֵיכֶם וְהִשָּׁעֲנוּ תַּחַת הָעֵץ, וְאֶקְחָה פַת לֶחֶם וְסַעֲדוּ לִבְּכֶם אַחַר תַּעֲבֹרוּ כִּי עַל כֵּן עֲבַרְתֶּם עַל עַבְדְּכֶם וַיֹּאמְרוּ כֵּן תַּעֲשֶׂה כַּאֲשֶׁר דִּבַּרְתָּ, וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה וַיֹּאמֶר מַהֲרִי שְׁלשׁ סְאִים קֶמַח סֹלֶת לוּשִׁי וַעֲשִׂי עֻגוֹת, וְאֶל הַבָּקָר רָץ אַבְרָהָם וַיִּקַּח בֶּן בָּקָר רַךְ וָטוֹב וַיִּתֵּן אֶל הַנַּעַר וַיְמַהֵר לַעֲשׂוֹת אֹתוֹ, וַיִּקַּח חֶמְאָה וְחָלָב וּבֶן הַבָּקָר אֲשֶׁר עָשָׂה וַיִּתֵּן לִפְנֵיהֶם וְהוּא עֹמֵד עֲלֵיהֶם תַּחַת הָעֵץ וַיֹּאכֵלוּ: (יח, א-ח),","b":true},{"t":"איתא בגמרא (בבא מציעא פו, ב), וירא אליו ה' באלוני ממרא והוא יושב פתח האוהל כחום היום, מאי כחום היום, אמר רבי חמא ברבי חנינא, אותו היום יום שלישי של מילה של אברהם היה, ובא הקדוש ברוך הוא לשאול ולדרוש בשלומו של אברהם. והוציא הקדוש ברוך הוא חמה מנרתיקה באותו היום כדי שלא יטרח אותו צדיק באורחים, וכיון שראה אברהם שלא נזדמנו אורחים לביתו אותו היום, שלח את עבדו אליעזר שיצא החוצה ויחפש אורחים. יצא אליעזר ולא מצא אורחים. חזר ואמר לאברהם לא מצאתי אורחים, אמר לו אברהם איני מאמין לך ואין אמונה בעבדים. הכין אברהם את עצמו לצאת לחפש ולבקש אחר עוברי אורח להכניסם אל ביתו. בעת צאתו ראה את השכינה ניצבת על פתחו, והוא שנאמר, אל נא תעבור מעל עבדך. ראה הקב\"ה שאברהם טרוד בקשירת התחבושות והתרתן מחמת כאב המילה. אמר, אינו דרך ארץ לעמוד עליו בעת הזאת להפריעו, ונסתלקה השכינה משם, ואז מיד מצינו דכתיב, וישא עיניו וירא והנה שלשה אנשים נצבים עליו, וירא וירץ לקראתם, והם באו שם כבר בתחילה ורק אחר שנסתלקה שכינה נגלו אליו, וגם הם ביקשו לילך כיון שראוהו חולה וסובל, ואז הפציר בהם אברהם אל נא תעברו בלא להכנס לביתי, ומי הם שלשה האנשים. מיכאל, וגבריאל, ורפאל, מיכאל שבא לבשר את שרה, רפאל שבא לרפא את אברהם, וגבריאל שהלך להפוך את סדום וכו'. ע\"ש.","b":false},{"t":"והנה במסכת שבת (קכו, ב), תנן, מפנין אפילו ארבע וחמש קופות של תבן ושל תבואה, מפני האורחים, ומפני ביטול בית המדרש. ובגמרא (שם קכז, א), אמרו על זה, אמר רבי יוחנן גדולה הכנסת אורחים כהשכמת בית המדרש, דקתני, מפני האורחים ומפני ביטול ביהמ\"ד, ורב דימי מנהרדעא אמר יותר מהשכמת ביהמ\"ד, שהרי הקדים את האורחים לבית המדרש. אמר רב יהודה אמר רב גדולה הכנסת אורחים מהקבלת פני שכינה, דכתיב ויאמר אדני אם נא מצאתי חן בעינך אל נא תעבור וגו', א\"ר אלעזר בא וראה שלא כמדת הקב\"ה מדת בשר ודם. מדת בשר ודם, אין קטן יכול לומר לגדול המתן עד שאבא אצלך, ואילו בהקב\"ה כתיב, ויאמר אדני אל נא תעבור, ופירש\"י ז\"ל, שהניח אברהם לשכינה והלך לקבל אורחים. ע\"כ.","b":false},{"t":"והנה מדת החסד בכלל והכנסת האורחים בפרט שנהג אברהם אבינו ע\"ה, הם הפכו לנחלתנו לדורות עולם, ומהסימנים של בני ישראל היא מדת החסד.","b":false},{"t":"ועד עצם היום הזה בני ישראל פועלים וגומלים חסדים יותר מכל אומה ולשון, וכן נמי בהכנסת אורחים. וזכורני ששמעתי מהרה\"ג הצדיק רבי אליהו שרים זצ\"ל ראש ישיבת תורה והוראה בתל אביב ת\"ו, שהיה רגיל לומר, שאם יש יהודי שאינו בעל חסד, אזי הוא בעל מום, כי כמו שטבע באדם שיהיו לו שני עינים ושני אזנים וכו', כן הוא טבע בבן ישראל שיהיה גומל חסדים, ואם חסר לו הדבר הזה, הרי זה דומה לחסרון אחד מהאברים.","b":false},{"t":"ועינינו הרואות שגם הרחוקים מיהדות, הן המה בעלי חסדים מופלגים ואוהבים את מעשי החסד והצדקה, משום שזה טבוע בנפשנו ובדמנו וירושה היא לנו מאבינו הזקן ע\"ה.","b":false},{"t":"ואולם חובתינו לשים לב למעשה אבינו אברהם ע\"ה, שהכנסת אורחים שלו היתה לכבוד האורחים וטובתם, ולא לשם עצמו, אלא מאהבת חסד בנקיות הדעת, וללא שום חשבונות, ובלי שום ציפיה לגמול כל שהוא.","b":false},{"t":"ואקח לדוגמא איך אנו נוהגים באורחים הבאים בצל קורתינו. כי אם בא אדם גדול וחשוב, אנו מתרגשים ומתחילים להכין עצמנו בעוד מועד, במחשבה ובמעשה, וככל שהאישיות המתארחת אצלינו היא מכובדת יותר ומפורסמת יותר וכו', כן תגדל ההתרגשות לקראת קבלת פניו, וכן תגדל ההכנה. ואם יאמרו לאדם שעומד לבקרו ראש ממשלה, או מלך, או גדול הדור, הרי הוא וכל בני ביתו, לא ינוחו ולא ישקוטו לרגע, וכל אשר יעשו וישתדלו, יהיה בעיניהם כאפס וכאין, וכל דבר גדול שהם עושים, הוא קטן בעיניהם ולא נחשב למאומה, ויחפשו עוד ויבדקו שוב מה ביכולתם לעשות, וכשנכנס אותו הנכבד אל ביתם לא יסיחו דעתם ממנו, וכל מגמתם ומאויים הוא להפיק רצונו, כדי שיהיה מרוצה ושמח, וינהגו בו מנהג הכנסת אורחים בכל הדר ויקר, ובשמחה ושלמות הלב.","b":false},{"t":"אך כשיבא איש עני ונכה רוח, דך ונכלם, ויעמוד מול הפתח ובושה תכסה פניו, ובקול חלוש ונדכא, מתחנן ומבקש דבר מה להשיב את נפשו, הנה גם אם נענה לו והואיל להכניסו אל ביתו, למרות שהדבר לא רצוי לו כל כך, אזי מכניסו ושם לפניו מאשר יעלה המזלג, בצורה פשוטה ביותר, באין אומר ואין דברים. ולפעמים מכניסו לביתו כמי שכפאו שד, ובמקרה הטוב כמי שרוצה לצאת ידי חובתו, וכמו שעושה דבר שאינו אוהב לעשותו, אך הוא מחוייב בדבר לעשותו, ועושהו כאנוס עפ\"י מצפון לבו, המזכיר לו את חובתו כלפי שמיא. וכל דבר קל וקטן שנותן לו, נראה בעיניו כהר תבור, ובעה\"ב דרוך בציפייתו שיסתיים הביקור מהר ככל האפשר.","b":false},{"t":"ואם יתקן אותו הלך את מקום ישיבתו ויתרווח מעט על הכסא, כי אז יהיה הדבר לצנינים בעיניו, משום שחושש שהעני הזה מתכוין להאריך ביקורו אצלו, ומיד עולות במחשבתו טרדותיו ורוב עניניו, ופגישותיו הרבות, ויתר עבודתו החשובה, ואז הוא מגיע לכלל כעס, איך זה הבטלן חסר המעש יושב ומתרווח לו, וחושב בדעתו שאין לו לבעה\"ב בעולמו, אלא הטיפול בו בלבד, ולבו יבער בקרבו, ככל אשר יאריך העני את מושבו אצלו, ואינו מעלה בדעתו כלל וכלל, שאולי העני הזה עייף ולאה עד שקשה לו לעמוד על רגליו, ואולי הרעב והצמא הכריעוהו והפילוהו מבלי שיוכל קום. ומה גם אפשר שהעני הזה מרגיש בגיצי האש הניתזים מבין ריסי עיניו של בעה\"ב שהם נתקעים בין צלעותיו ולא נותנים מנוח לנפשו העייפה והשבורה, והיה משלם כל מחיר להפטר מזה, אלא שאיבריו כבדו עליו מרוב רעב ועינוי עד שאינם נשמעים לו, וממשיך לשבת עוד זמן מועט עד שיאסוף את שארית כחותיו, אחת אל אחת ידובקו, ואיבר את רעהו יעזור, ויהיו סייענים אחד לחברו עד שיסכינו לשאת את משא גופו אם רב ואם מעט הוא.","b":false},{"t":"ואם הוא עני בן טובים ורגיל בכלים נקיים וגם נאים, ולא יוכל לאכול בכלים פשוטים ובלוים, ויבקש להביא לו גם סכין וגם מפית, מיד יצטייר בעיני מארחו כמפונק המפריז על מדותיו, ושיש בו גאות עם דלות, עד שיאמר עליו בעה\"ב זהו דל גאה שאין הדעת סובלתו (ראה פסחים קיג, ב), ויברך עליו ברוך משנה הבריות, והיטב יחרה בו בעל הבית בחרי אף גדול, וגם אם יכבוש כגבור את יצרו, וישיב את כעסו ולא יעיר כל חמתו, הרי מ\"מ לא ימלא מבוקשו במלואו, ולא יעבור על הדבר בשתיקה גמורה, שכן לא יעשה, ומיד יזכיר לעצמו מצות הוכח תוכיח. ויכוין לטובת אורחו היקר, שלא ימשיך בדרכו הנלוזה וימאיס עצמו על מארחיו, ויהיה עליהם למשא, ויפתח פיו בחכמה ובהתאפקות ובאמירה רכה ונעימה, ויוכיחו על פניו על חוצפתו ועזות רוחו, וינסה ללמדו פרק בהלכות דרך ארץ, כדי שיהיה נושא חן וחסד בעיני כל רואיו. והבעה\"ב הזה אינו מבקר את עצמו כלל, שאולי לא זו השעה הנכונה להניח גחלים בוערות עלי לבו השבור והחרוך בלאו הכי. ויש אשר יתחיל לדבר אתו באותה עת ממש על שיקומו, וירבה עליו הפצרה שילמד לו מקצוע ויחפש פרנסה לעצמו, לטובתו ולטובת משפחתו. וכל זאת, במקום לפייסו ולנחמו על מר גורלו, ולפתוח תקוות טובות לפניו ולומר לו, עוד יבואו ימים טובים יותר, וישועת ה' כהרף עין. וכן ע\"ז הדרך, ויכבדו בלב שלם ובנפש חפצה. וישים לנגד עיניו שאל שדי עומד על ימין העני הזה הדופק בפתחו, והקבלת פניו גדולה יותר מהקבלת פני שכינה, ויותר מהשכמת בית המדרש.","b":false},{"t":"ואם יתבונן גם לגופו של ענין ישכיל להבין, שזה העני זקוק לאוכל טוב ומשקה טוב, הרבה יותר מאותו איש רם מעלה העשיר ונכבד, אשר כל ימיו חג ומועד, ומאכלו מאכל מלכים ויינו יין נסיכים, ומארחיו גדולים ורבים הם, ומה יתן ומה יוסיף לו לזה האיש עוד ארוחה גדולה ואירוח חשוב, ואע\"פ שאין קץ לתאות הכבוד של אדם, מ\"מ התועלת שתבא לעני מסעודה דשנה והלבנת שינים בשמחה ובטוב לבב גדולה לאין ערוך מאותה סעודה שיטרח ויכין לאדם הנכבד.","b":false},{"t":"וכשמביטים בכובד ראש במעשה זה של אברהם אבינו ע\"ה, שמלמד על דרכו בקדש בהכנסת אורחים מכל העולם, כאשר הקים אהל על אם הדרך, ועשה בו ארבעה פתחים לקלוט עוברים ושבים מכל הרוחות, בלא שום הבחנה מאין באו ומה מעשיהם, וקבלו ממנו את כל הכבוד, ואת כל תשומת לבו נתן לזה, ובכבוד רב היה עומד ומשמש לפניהם למלאת את כל מבוקשם, ומעולם לא הבדיל בין גדול לקטן, ובין עשיר לעני, ובין מכובד לפשוט וקל, כי כל הבא אל ביתו התקבל בכל הכבוד האפשרי.","b":false},{"t":"והנה מצינו בפסוקים שלפנינו, כי גם כשהיה אברהם ביום השלישי למילתו, כשהוא בן תשעים ותשע שנים, והקב\"ה חס עליו שלא יטריחוהו האורחים כדרכו בכל יום, והוציא חמה מנרתיקה עבורו, לא שמח בזה אברהם, ונצטער על שאין בידו מצות הכנסת אורחים, ושלח את אליעזר עבדו נאמן ביתו המושל בכל אשר לו להביא אורחים לשמח את נפשו, וכשלא מצא אליעזר שום אורח ובא להודיעו שאין אורחים ואין עובר ושב כלל, אברהם אבינו ע\"ה מיאן להאמינו על זה. ואמנם לא בעבור שלא היה מאמינו, שהרי את כל אשר לו נתן בידו, אבל מפני שהמצוה הזאת היתה חשובה עבור אברהם אבינו כאויר לנשימה, לא רצה להאמין, ויצא הוא, וישם אל המדבר פניו, אולי ימצא אורחים, והקב\"ה זימן לו שלשה מלאכים, הנראים לו כשלשה ערביים שהיו עובדי ע\"ז, ומהם שעבדו לאבק עפר שברגליהם, ועל כן הניח אברהם לפניהם מים ויבקשם שירחצו את רגליהם, והכל בכבוד ויקר, ובזריזות ובמהירות, ולא המתין לרוב עבדיו ומשרתיו שיקבלו הם את האורחים, אלא הוא עצמו רץ ומתרוצץ, \"וימהר אברהם האהלה אל שרה, ויאמר מהרי שלש סאים קמח סולת לושי ועשי עוגות\", הוא ממהר, ומבקש גם מאשתו שתמהר, ומפרט לאמר לה מה תכין ואיך תכין לכבודם, ולא סמך על טוב לבה והרגלה וכו', ומיד אחר זה, \"ואל הבקר רץ אברהם ויקח בן בקר רך וטוב\", ולקח שלשה פרים כדי להפריש מכל פר את לשונו ולבשלו בחרדל עבור האורחים שהוא מאכל יקר ונכבד עד מאד (ראה ב\"מ פו, ב), ומיד נתן הוראות להכינו, ועד שיכינו ועד שיביאו לפניהם, מיד, \"ויקח חמאה וחלב ובן הבקר ויתן לפניהם והוא עומד עליהם תחת העץ ויאכלו\".","b":false},{"t":"והנה כל הרואה את דברי הפסוקים אפילו בדרך העברה בעלמא, לבו יבין ועיניו יראו, באיזה כבוד והדר היה מקבל אברהם אבינו את אורחיו, ועשה הכל בעצמו ולא ע\"י שליח, כדי שהדברים יעשו על הצד היותר טוב.","b":false},{"t":"ועבור מי עשה כל זאת, עבור שלשה אנשים שנדמו לערביי המדבר שהיו עובדי עבודה זרה, מן הדרגא הפחותה ביותר, שמשתחוים לאבק שברגליהם, ואת אלו קיבל בכבוד ויקר.","b":false},{"t":"ולכבודם של אלו ביקש מהקב\"ה שימתין לו באומרו לו, \"אדני אל נא תעבור מעל עבדך\", אלא נא בקשה ימתין לי כי אני צריך להקביל פני האורחים. עד שלמדו רבותינו מזה, על מעלת הכנסת אורחים, שהיא גדולה מהקבלת פני שכינה, ואכן הכנסת אורחים כזו הנעשית לכבוד ה', כדי לקיים את מצותו ולעשות רצונו בשלמות, היא מטרת האדם בעולם, והיא גדולה מהקבלת פני שכינה, כי זה כל האדם.","b":false},{"t":"ומי שמכבד רק אנשים עשירים ונכבדים ומקיים בהם מצות הכנסת אורחים בכל ההוד וההדר, אבל לעני לא יפתח דלתו, זה אינו לכבוד ה', אלא לכבוד עצמו, כדי שמחר יוכל לספר באזני חבריו ומכריו, מי האיש שביקר אצלו בצל קורתו, ויאריך להטעים על כל מלה ועל כל צעד, כי בזה מגדיל את כבודו ויקר תפארת גדולתו, שיאמרו הבריות, ראו כמה חשוב אדם זה, וראו מי הם באי ביתו, ויתנו לו יקר וגדולה. אבל בבא אליו עני ונכה רוח, למי יספר ומה יוסיף לו, ואין לו מזה שום מעלה בעיני הבריות, ועל כן מקבל את פניו כלאחר יד, וללא רצון.","b":false},{"t":"אבל על זה נאמר (תהלים מא, ב), אשרי משכיל אל דל, שאם יתבונן וישכיל במצוה המעולה והחשובה הזאת שאין לו בה שום הנאה, ועושה אותה רק לכבודו יתברך לעשות נחת רוח לפניו במעשה החסד האמיתי, מצוה כזו, היא גדולה מהקבלת פני שכינה. ומעשה אבות סימן לבנים.","b":false}]},{"id":"16","t":"\"חסד לאברהם\"","p":[{"t":"וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה שְׁלשָׁה אֲנָשִׁים נִצָּבִים עָלָיו וַיַּרְא וַיָּרָץ לִקְרָאתָם מִפֶּתַח הָאֹהֶל וַיִּשְׁתַּחוּ אָרְצָה, וַיֹּאמַר אֲדֹנָי אִם נָא מָצָאתִי חֵן בְּעֵינֶיךָ אַל נָא תַעֲבֹר מֵעַל עַבְדֶּךָ, יֻקַּח נָא מְעַט מַיִם וְרַחֲצוּ רַגְלֵיכֶם וְהִשָּׁעֲנוּ תַּחַת הָעֵץ, וְאֶקְחָה פַת לֶחֶם וְסַעֲדוּ לִבְּכֶם אַחַר תַּעֲבֹרוּ כִּי עַל כֵּן עֲבַרְתֶּם עַל עַבְדְּכֶם וַיֹּאמְרוּ כֵּן תַּעֲשֶׂה כַּאֲשֶׁר דִּבַּרְתָּ, וַיְמַהֵר אַבְרָהָם הָאֹהֱלָה אֶל שָׂרָה וַיֹּאמֶר מַהֲרִי שְׁלשׁ סְאִים קֶמַח סֹלֶת לוּשִׁי וַעֲשִׂי עֻגוֹת, וְאֶל הַבָּקָר רָץ אַבְרָהָם וַיִּקַּח בֶּן בָּקָר רַךְ וָטוֹב וַיִּתֵּן אֶל הַנַּעַר וַיְמַהֵר לַעֲשׂוֹת אֹתוֹ, וַיִּקַּח חֶמְאָה וְחָלָב וּבֶן הַבָּקָר אֲשֶׁר עָשָׂה וַיִּתֵּן לִפְנֵיהֶם וְהוּא עֹמֵד עֲלֵיהֶם תַּחַת הָעֵץ וַיֹּאכֵלוּ: (יח, ב-ח)","b":true},{"t":"אברהם אבינו ע\"ה קרוי \"איש החסד\" וזו היא המדה שלו, כמו שנאמר (מיכה ז, כ), תתן אמת ליעקב \"חסד לאברהם\". ובודאי שהחסדים של אברהם ע\"ה הם גדולים ועצומים בכמותם ואיכותם, וחסדו היה חסד של אמת לשם ה' ב\"ה.","b":false},{"t":"כי הנה ידוע אצל בני אדם, וגם אצל הרבה אנשים הקרוים בעלי הכנסת אורחים, שתמצא אצלם חילוק והבדל בין אורח לאורח, כי כשיבא אצלם אורח רם מעלה ונכבד, כולם רצים ואצים, נרגשים וגועשים, לכבדו בכל מאי דאפשר. ואילו כשיבא עני פשוט וכיוצא בו, גם אם יכבדוהו באיזה ארוחה, מכל מקום הרי זה נעשה באדישות ופשטות כאילו עושים כן רק כדי לצאת יד\"ח ותו לא, והדברים ידועים (וראה מה שנתבאר עוד במאמר הבא).","b":false},{"t":"ואמנם אצל אברהם אבינו ע\"ה, גם כשבאו שלשת המלאכים ונדמו לאברהם אבינו כישמעאלים, אנשי מדבר פשוטים המשתחוים לאבק רגליהם שלהם, שאין לך חסרון דעת ופחיתות גדולה מזו. ואברהם אבינו רץ לקראתם ופונה אליהם בתחינה, \"אל נא תעבור מעל עבדך\" והמשיך ואמר להם, \"יוקח נא מעט מים ורחצו רגליכם\", שירחצו רגליהם מן האבק של עכו\"ם, והרואה יראה איך הוא חרד לכבודם של הישמעאלים עובדי ע\"ז הללו, והוא דואג לשחוט עבורם שלשה עגלים כדי להאכילם שלש לשונות בחרדל, וחלב וחמאה ועוגות וכו' (כמבואר בפסוקים ובמסכת בבא מציעא פו, ב). וכל מעשיו של אברהם אבינו ע\"ה היו בריצה ובמרץ ובחשק גדול כמו שנאמר, \"ואל בן הבקר רץ אברהם\", הוא בעצמו רץ, ומזרז את שרה \"מהרי שלש סאים וגו' לושי ועשי עוגות\". כי אברהם אבינו לא נהג ככל בני אדם שעושים את מעשיהם עם מחשבות ופניות שונות, המחשבים חשבונות בכל דבר וענין, לאמר מה יצא לי מן הדבר הזה ואיזה ריוח יבא לי ממנו, ואיזה קשר מועיל יש לי בזה, וכן על זה הדרך. אבל אצל אברהם אבינו ע\"ה הכל היה לשם ה' ב\"ה, ועל כן לא חשוב מי היה האורח, ולכל אדם שבא אצלו השתדל לכבדו בכל כחו.","b":false},{"t":"ומדה נפלאה זו של אברהם אבינו ע\"ה בולטת עוד יותר בכל תפארתה והדרה, כאשר עמד להתפלל על אנשי סדום ועמורה שהיו רעים וחטאים לה' מאד (בראשית יג, יג). ומנהגיהם היו ההיפך הגמור ממנהגו של אברהם אבינו ע\"ה, עד שחוקקו חוקים שכל מי שיתן לחם לעני אחת דתו להמית, וכאשר מובא במסכת סנהדרין (קט, ב ונתבאר היטב במאמר הבא), עי\"ש. ובאופן טבעי היה לו לאברהם לומר באבוד רשעים רינה (משלי יא, י), כי מעשיהם הרעים גרמו להם, וה' שילם להם כפעלם הרע, ובזה יוכל להוכיח קבל קהל ועולם את צדקת דרכו, בראותם את תוצאות דרכי סדום ועמורה. ולא זו בלבד שלא שמח, אלא להיפך, היה מיצר ומתפלל עליהם, ושם נפשו בכפו ונתוכח עם השכינה בעבורם, כמו שאמרו רבותינו במד\"ר (בראשית רבה מט, ח), על הפסוק (בראשית יח, כג), ויגש אברהם, ויגש - לשון פיוס, ולשון תפלה, ולשון מלחמה, וראינו בזה את גדולת נפשו של אברהם אבינו, שהיה מוכן אפי' לדבר קשות כביכול כלפי מעלה, וכל זאת בעבור מי. בעבור החטאים האלה בנפשותם, יריביו המובהקים ביותר. וכל זאת באה לו מאמיתת חסדו הגדול (וראה עוד להלן מאמר ד).","b":false},{"t":"כמו כן מצאנו בענין לוט שלמרות שהיה בן אחיו של אברהם והיה הולך עמו לכל מקום ועל ידו נתעשר, כדכתיב (בראשית יג, ה), וגם ללוט ההולך את אברם היה צאן ובקר וגו'. והיה רואה בעיניו את העבודה הגדולה שהיה אברהם אבינו ע\"ה עושה כדי לקרב את הבריות לאמונת ה' ב\"ה ולעבודתו. ועם כל זאת, קינא לוט בדודו, והיה מייחל למותו כדי שיהא הוא היורש היחידי (כמבואר בב\"ר מא, ה), ויהי ריב בין רועי מקנה אברהם ובין רועי מקנה לוט (בראשית יג, ז), ותחת הריב בא אברהם וקורא ללוט \"אחי\" (שם שם, ח). ולוט כפר בטובתו של אברהם, והלך לו אל סדום, אל ההיפך הגמור ממדות אברהם אבינו, ונהיה להם לשר ושופט. ואילו בזמן מלחמת המלכים כשנשבה לוט, מה עשה אברהם, מיד וירק את חניכיו (בראשית יד, יד), שהוציא את כספו וזהבו, ואמר לנעריו אם ממון אתם מבקשים, הרי לכם, ועתה בואו עמי להציל את לוט (כמבואר בתנחומא לך לך פי\"ג). ויצא במסירות נפש למלחמה נגד מלכים גבורים ועצומים כדי להציל את לוט בן אחיו. וכל זאת אחר שלוט בגד בבריתו, ועשה היפך ממה שלמד אצלו.","b":false},{"t":"אכן זו מדתו של אברהם, חסד ללא שום חשבונות. ויה\"ר שאנו בניו של אברהם אבינו נדבק במדותיו הנפלאות לטוב לנו כל הימים.","b":false},{"t":"(מוצ\"ש וירא מר חשון התשמ\"ג)","b":false}]}]},{"slug":"חיי-שרה","name":"פרשת חיי שרה","items":[{"id":"17","t":"אחר נפילת ישמעאל תצמח גאולת ישראל","p":[{"t":"וְאֵלֶּה שְׁנֵי חַיֵּי יִשְׁמָעֵאל מְאַת שָׁנָה וּשְׁלשִׁים שָׁנָה וְשֶׁבַע שָׁנִים וַיִּגְוַע וַיָּמָת וַיֵּאָסֶף אֶל עַמָּיו, וַיִּשְׁכְּנוּ מֵחֲוִילָה עַד שׁוּר אֲשֶׁר עַל פְּנֵי מִצְרַיִם בֹּאֲכָה אַשּׁוּרָה עַל פְּנֵי כָל אֶחָיו נָפָל: (כה, יז-יח)","b":true},{"t":"כתב רבינו יעקב בעל הטורים, \"על פני כל אחיו נפל\", וסמיך ליה, ואלה תולדות יצחק, לומר, כשיפול ישמעאל באחרית הימים, אז יצמח בן דוד שהוא מתולדות יצחק. עכ\"ל.","b":false},{"t":"וברוך שבחר בתורה ובחר בנביאים טובים, וברוך שבחר בחכמי הדורות ובמשנתם, והוא מקיימם, הם ותלמידיהם וכל אשר להם, והוא מאיר את עיניהם לראות ולצפות מתוך אור התורה, את אשר יהיה לדורות עולם. והנה במלים אלה דרש הסמוכות וגילה את העתידות בבירור, יראו עינינו וישמח לבנו בישועתך מלכנו, בב\"א.","b":false}]},{"id":"17","t":"הטומאה שולטת במקום העדר תורה וקדושה","p":[{"t":"וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ בְּעוֹדֶנּוּ חַי קֵדְמָה אֶל אֶרֶץ קֶדֶם: (כה, ו)","b":true},{"t":"וכתב רש\"י זל נתן אברהם מתנות, פי' רבותינו (סנהדרין צא, א), שם טומאה מסר להם, דבר אחר, מה שניתן לו על אודות שרה, ושאר המתנות שנתנו לו, הכל נתן להם שלא רצה ליהנות מהם. ע\"כ.","b":false},{"t":"ובדעת זקנים מבעלי התוספות כתבו, וז\"ל, נתן אברהם מתנות, אמרו בפרק חלק (סנהדרין שם), שמות טומאה מסר להם, פי' שיהיו יכולין להזכיר שם המפורש בטומאת הגוף ולא יזיק להם, וגם היום יש ישמעאלים שבקיאין בשם ומזכירין אותו בטומאה. וקשה לה\"ר משה היאך אדם וצדיק חשוב כאברהם ילמד השם לרשעים לכן פי' ה\"ר יעקב בה\"ר נחמן שם טומאה, \"שם השדים\" שמשביעין אותן באדוניהם הממונים עליהם לעשות כל מה שרוצים כמו ספר בילא\"ד, ושם טומאה נקרא על שם רוח הטומאה, כדאמרינן במסכת חגיגה (ג, ב), הלן בבית קברות כדי שתשרה עליו רוח טומאה. רמז לזה שהרי מתנות כתיב חסר וא\"ו והוא עולה בגימטריא \"למדם להשביע השדים\". מה\"ר משה. ע\"כ.","b":false},{"t":"ולמדנו כאן דהיכא דליכא אות וא\"ו הרומזת לתורה כאשר כתבנו בכמה מקומות (ראה הקדמת שמע שלמה ח\"א ובספרנו פרשת תולדות מאמרים ח, יג ופרשת וישב מאמר ב ופרשת ויחי מאמר יז), לא נשאר אלא ריקנות וטומאה, ולכך כתיב \"מתנת\" חסר וא\"ו. ודוק.","b":false},{"t":"* * *","b":false},{"t":"אל לו לאדם לפנות בעת צרה אל אנשים מפוקפקים שיעזרוהו","b":true},{"t":"עוד למדנו שלא להתפעל מעושי מופתים, אשר מלבד שבימינו רובם ככולם הוא שקר ורעות רוח, ורק במשחק ידברו להערים איש על רעהו, כדי למשוך ממון וכבוד, מ\"מ גם אם המצא ימצא מהם בעלי מעשים, בני אל יפתוך חטאים, הוקר רגליך מביתם, מנע דרכיך מנתיבתם. ויתבונן כל אחד בנאמר כאן, ויתחזק ואל ישעה להבלים שאין בהם מועיל, ולה' הישועה.","b":false},{"t":"[א\"ה - יש להוסיף בכאן הערה רבתי, על אנשים שבעת שיש להם צרה תוך ביתם רח\"ל, נתלים בקורי עכביש, ותחת להרבות בצדקה ותחנונים אל ה', תיכף עושים מסע מדן ועד באר שבע, וילכו לכל מאן דמתקרי \"מקובל\" ומקבל קהל ומאחז עינים, כדי שיעשה להם איזה \"תיקון\" להסיר חרון אף, וה\"מקבלים\" הללו, מוליכין אותם מדחי אל דחי, לא הרי זה כהרי זה, ומשנים שמות, ועושים להם כל מיני בדותות, לא יאומן כי יסופר, הצד השוה שבהן שכולם מזיקין, וצריך להתרחק מהם.","b":false},{"t":"ומצינו בבבא בתרא (קטז, א), דרש ר' פנחס בר חמא, כל מי שיש לו חולה בתוך ביתו ילך אצל חכם ויבקש עליו רחמים שנאמר (משלי טז, יד), חמת מלך מלאכי מות ואיש חכם יכפרנה. והנה לא אמרו ילך אצל \"צדיק\" אלא ילך אצל \"חכם\" שעוסק בתורה, ודבוק בחי החיים, שרק הוא בכחו לרפאות.","b":false},{"t":"ובתולדות הרה\"ק רבי לוי יצחק מברדיטשוב זיע\"א הנדפס במונקאטש בסוף ספר קדושת לוי, כתבו, שכך היה מפרש דברי המשנה (ברכות סוף פ\"ו), השותה מים לצמאו, אומר שהכל נהיה בדברו. רבי טרפון אומר, בורא נפשות רבות. היינו, דמי שלומד תורה כאדם צמא המבקש לשתות מים, ואמרו רבותינו (ב\"ק פב, א), שהתורה נמשלה למים, שנא' (ישעיה נה, א), הוי כל צמא לכו למים. והאדם הזה השותה את מי הדעת לרויה, אם מברך מאן דהוא, כי אז \"שהכל נהיה בדברו\", וכל ברכותיו מתקיימות. ובא רבי טרפון לחלוק על זה ואמר, דזהו מילתא זוטרתי, אלא שבכחו לברוא נפשות רבות ולהחיות מתים. ודפח\"ח.","b":false},{"t":"ורבינו מהר\"ח מוואלאזי'ן בספר רוח חיים על מסכת אבות (פרק א משנה א), סיפר, כי פעם אחת בהיות הגאון בעל ט\"ז ז\"ל יושב ולומד עם תלמידיו, נתפרצה אשה בוכיה לחדר לימודו וזעקה, אהה אדוני הושיעה נא לבני הגוסס ואל ימות. ויען הגאון ויאמר לה, התחת אלהים אני להחיות מתים. ותאמר לו, הן אמרו (ראה זוהר ח\"ג עג, א), דקוב\"ה ואורייתא וישראל חד הוא, ואל התורה שבך אני מבקשת. ואז אמר לה בעל הט\"ז לו יהי כדבריך, ובכן הנני נותן לבנך החולה את זכות התורה שאני לומד ומלמד עתה בחבורה, ואמרו, כי לא הספיקה האם לשוב לביתה וכבר יצאו בני הבית והודיעוה כי חלצתו חמה לבנה, וכי יצא משערי מות לחיים טובים. זיע\"א. ישמע חכם ויוסיף לקח. יבח\"ר].","b":false}]},{"id":"17","t":"פלגשם - פלג שם","p":[{"t":"וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וגו': (כה, ו)","b":true},{"t":"ורש\"י ז\"ל כתב, הפילגשים, חסר כתיב, שלא היתה אלא פילגש אחת, היא הגר היא קטורה (ומקור הדברים בב\"ר סא, ד), נשים בכתובה, פילגשים בלא כתובה, כדאמרן בסנהדרין (כא, א), בנשים ופילגשים דדוד. עכ\"ל רש\"י.","b":false},{"t":"ושמעתי בשם הגר\"א ז\"ל (כן הוא בספרו קול אליהו), שפירש ענין זה, דהנה ידוע שכתובה, הוא אותיות כתב ו-ה, היינו, כי איש ואשה שזכו שכינה ביניהם (סוטה יז, א וברש\"י שם), כי באיש יש אות יו\"ד, ובאשה אות ה', ויחדיו עולין י-ה שהיא השכינה שביניהם, אמנם עדיין חסרות להם אותיות ו-ה כדי להשלים את שמו יתברך שיהיה שלם, ולזה באה הכתובה להשלים את השם, ולכן הוא אותיות כתב ו-ה ובזה נשלם שמו יתברך.","b":false},{"t":"ולפי\"ז בלוקח פילגש שיש בה רק קידושין ואין כתובה, הרי יחסרו לו אותיות ו-ה, וזה מ\"ש רש\"י פילגשם חסר כתיב, כלומר חסר יו\"ד, ורצונו לומר \"פלגשם\", פלג - שם, כלומר חצי שם שאין עליהם רק חצי משם הוי\"ה ברוך הוא, שהוא י-ה בלבד, אבל ו-ה אין להם, שהוא בא ע\"י הכתובה, ולאלה אין כתובה, ודפח\"ח.","b":false},{"t":"[א\"ה - גם מרן החבי\"ף ז\"ל בספרו ובחרת בחיים (פרשת חיי שרה), הביא את דברי רש\"י ז\"ל, \"פלגשם כתיב\" והביא דברי מקשים, דהא בס\"ת כתיב פילגשים מלא ביו\"ד, ותירצו דבמסורת הוא כך. והביא משם רבני אשכנז, דטעם שם \"כתובה\", דאין קורין לזה כתב או שטר, משום דשם כתובה בא להשלים שם י\"ה של האיש והאשה, דע\"י הכתובה נכנס אות וי\"ו באמצע, וה\"א לבסוף, ואז נשלם שם הי\"ת. ואמנם בפלגש שאין בה כתובה, נשאר רק חצי שם, וזהו פלגשם, נוטריקון \"פלג שם\", היינו חצי שם. ולפי\"ז פירש את מענה יוסף לאביו כששאל אותו מי אלה לך, השיב לו בני הם אשר נתן לי אלהים בזה (ראה בראשית מח, ח-ט). ופירש רש\"י ז\"ל (שם שם, ט), שהראה יוסף לאביו שטר אירוסין ושטר כתובה. והנה אמרו בזוה\"ק (ראה ח\"ג יא, ב ושם לד, א וראה שם רצא, א), דהוי\"ו וה\"א אחרונה משתלם ע\"י בן ובת, ועל כן, כששאל יעקב את יוסף מי אלה לך, השיבו, שהם בנים כשרים ע\"י חופה וקדושין והראיה לכך, היא הכתובה, דלכך נקראת כתובה, להשלים שם הוי\"ה ב\"ה, דזה נשלם ע\"י ההולדה. זת\"ד. יבח\"ר].","b":false},{"t":"ובתשובה בענין תרגום הכתובה שבשו\"ת שמע שלמה ח\"א (חאהע\"ז סוף סי' ז), כתבתי דבזה יתפרש מאמר רבותינו ז\"ל במסכת שבת (קל, א), דמצוה שקיבלו ישראל בשמחה עדיין מקיימים אותה בשמחה, והיא ברית מילה, דכתיב (תהלים קיט, קסב), שש אנכי על אמרתך וגו', ומצוה שקיבלו בצער עדיין מקיימים אותה בצער, אלו נישואין, דכתיב (במדבר יא, י), העם בוכה למשפחותיו, על עסקי משפחותיו, דלית כתובה דלא רמו בה תיגרא. ע\"כ. ושאלתי למה תלו את התיגרא בכתובה דוקא, והלא הכתובה היא רק חוזה המסדיר את התנאים שבין בני הזוג, והיה להם לומר, לית נשואין דלא רמו בהו תיגרא, או לית חופה דלא רמו בה תיגרא, ולמה תלו את זה בכתובה דוקא, ברם לפי הדברים הנ\"ל אתי שפיר, דהנה כתיב (שמות יז, טז), כי יד על כס יה מלחמה לה' בעמלק מדור דור, ואמרו חז\"ל (תנחומא תצא פי\"א ובמדרש תהלים מזמור ט' ובילקו\"ש שם וראה פסיקתא דר\"כ ג, טז ועי' תוס' ברכות ג, א ד\"ה היה לך), נשבע הקב\"ה שאין השם שלם ואין הכסא שלם, עד שימחה שמו של עמלק, והיינו שבשם השם חסר אותיות ו - ה, והשלמת אותיות אלו לשמו יתברך תלויה במלחמת ה' בעמלק, כי כל עצם קיומו של עמלק מורה שאין השם שלם, כי אילמלי היה שמו יתברך שלם ממילא היתה מתבטלת כל קליפת עמלק שלא היה לה כבר שום אחיזה בקדושה והיתה בטלה מאליה. ולכן צריך מלחמה כדי להשלים את שמו יתברך ולבטל ולבער את הרע מן העולם.","b":false},{"t":"וכנראה שכשם שבשמו יתברך שהוא השם דכלל העולמות, השלמתו תלויה במלחמה. וכן לימוד התוה\"ק תלוי במלחמה, בקושיות ומשא ומתן וריתחא דאורייתא, וזאת, כדי לשבר ולהכניע את הקליפות (ועי' בהקדמת מוהרח\"ו לשער ההקדמות). כמו כן השלמת שם ההוי\"ה הפרטי הנקרא על בני הזוג, ג\"כ תלוי במלחמה זוטרתי היא התיגרא כלשון חז\"ל, וכיון שהשלמת שם ההוי\"ה הוא ע\"י הכתובה וכנ\"ל, ע\"כ תלו את התיגרא דוקא בכתובה, וע\"כ אמרו, לית כתובה דלא רמו בה תיגרא. כיון דהכתובה משלים שם הוי\"ה ב\"ה, לכך היצה\"ר שהוא נרגן מפריד אלוף מנסה לעשות תיגרא בכל כחו לבל יושלם שמו ית', ולהכי בכל כתובה ממציא תיגרא, והי\"ת יצילנו מידו, אכי\"ר.","b":false},{"t":"(בעהית\"ש אור ליום ב' כ\"ד מר חשון התשמ\"ח)","b":false}]},{"id":"17","t":"בת היתה לאברהם ו\"בכל\" שמה","p":[{"t":"וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל: (כד, א)","b":true},{"t":"אמרו חז\"ל (בבא בתרא טז, ב), בת היתה לאברהם אבינו ע\"ה ובכל שמה. והנה רש\"י ז\"ל, בפירושו לתורה (כאן), כתב, בכל גימטריא ב\"ן, ומאחר שהיה לו בן היה צריך להשיאו אשה. עכ\"ל. ורבינו אברהם אבן עזרא ז\"ל, כתב, וה' ברך את אברהם בכל, באורך ימים, ועושר וכבוד, ובנים, וזו חמדת כל האדם, ודרשו שבתו היתה ושמה בכל, צריך להוסיף בי\"ת משרת עכ\"ל, וכונתו פשוטה להקשות, שאם כדברי הדרש שהיתה לאברהם בת ששמה בכל, א\"כ היה לו להוסיף בי\"ת משרת ולכתוב וה' ברך את אברהם בְּבַכֹּל. ועיין באבי עזר שיישב קושיא זו, וז\"ל, ומצינו כמה פעמים נחסר בי\"ת המשרת, כמו הנמצא בית ה' (מ\"ב יב, יא). עכ\"ל. והיינו דשייך לשון זה, ויש פסוקים שלא נכתב בהם ב' המשרת.","b":false},{"t":"ונראה תמוה קצת לפרש שאברהם אבינו קרא את שם בתו \"בכל\", ולמה לא שמענו ולא ראינו בכל הדורות שיקראו את שם הבנות על שם בתו של אברהם אבינו ע\"ה. וגם לשון \"ברך את אברהם בכל\" לא מתפרש בהכי, כי היה לפסוק לומר שהי\"ת ברך את אברהם בבת ואח\"כ יאמר את שמה.","b":false},{"t":"והנראה בס\"ד דרבותינו למדו מתיבת \"בכל\" שאברהם אבינו ע\"ה זכה גם לבת, דאי לאו הכי אין ראוי לומר שהי\"ת ברכו \"בכל\" שהרי לא קיים מצות פריה ורביה, ולכן כשאמרה התורה בכל, יש במובן הזה גם שנולדה לו בת.","b":false},{"t":"ומזה שנים פירשתי בס\"ד דודאי היה לבתו של אברהם אבינו שם ככל הנשים. ומה שאמרו רבותינו ז\"ל \"בכל\" שמה, הכי קאמר, דהיה לה שם טוב לתפארת, כפי הראוי לבתו של אברהם אבינו עליו השלום, שנאמר עליו (בראשית יח, יט), כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו וגו'.","b":false},{"t":"אמנם השם \"בכל\" בא לבטאות את מהותה של הבת הזו, כי יש בת שיש לה שם טוב במקום לימודיה, מפני כשרונותיה וחריצותה בלימודים במרץ ובזריזות, אבל במלאכות הבית היא עצלה ולא תצלח. ויש בת שהנהגתה הפוכה, בביתה היא מוצלחת ויעילה ומסודרת ומתוקנת בכל מעשיה, בהוד והדר, וכל בני הבית והאורחים מתפעלים מזריזותה וחן מעשיה הטובים, עד שיצא לה שם טוב על זה, אך בלימודים היא חלשה ועצלה, וגם תעודותיה הניתנות לה בסוף שנות הלימודים היו לה לחרפה ובוז. ויש בנות המושלמות בזה ובזה, אך מדותיהן והליכותיהן לא טובות הנה, ויש בנות שיש בהן כל המעלות האמורות, אבל הן חסרות ביראת שמים וכו' וכו'.","b":false},{"t":"אבל הבת של אברהם אבינו ע\"ה \"בכל\" שמה, כלומר בכל הענינים היה אותו השם הטוב והמעולה, בבית ובחוץ, ביר\"ש ובמדות, בחכמה ובמלאכה, בדבור ובמעשה, בכל הענינים שמה הולך לפניה לתהילה. כנאה וכיאה לבתו של אברהם אבינו ע\"ה. תדע שמעולם לא נשמע שיקרא אדם לבתו בכל, על שם בתו של אברהם אבינו ע\"ה, והוא הוכחה שאין זה שמה ממש, אלא בכל היה שמה בכתר שם טוב עולה.","b":false},{"t":"[א\"ה - הנה כתב רבינו הגר\"א ז\"ל בספר ברק השחר (ונדפס בפירושו למשלי), על הפסוק (משלי לא, י), אשת חיל מי ימצא, כי \"חיל\" בגימ' מ\"ח שהם מ\"ח קנייני התורה, היינו שירמוז בזה אל הת\"ח המושלם בכל קנייני התורה. והוסיף על זה תלמיד הגר\"א הלא הוא הגרמ\"מ משקלוב ז\"ל, כי \"אשת חיל\" היינו שמהותה הוא \"חיל\", שהיא שלמה בכל מ\"ח קנייני התורה, ואינה כבנות שנאמר בהן (משלי שם, כט), רבות בנות עשו חיל ואת עלית על כולנה. והנה לכאורה יש סתירה בין הפסוקים כי בתחילה אמר \"אשת חיל מי ימצא\", ואחרי כן אמר \"רבות בנות עשו חיל\". אמנם אין זו סתירה, כי בבנות נאמר \"עשו חיל\", היינו שאין הבנות הללו נשות חיל במהותן, אלא רק \"עושות חיל\", כלומר, מיוחדות במדה אחת או כמה מדות, אבל לא שלמות בכל, אמנם ה\"אשת חיל\" שלמה בכל, וזהו שאומר רבות בנות עשו חיל, אמנם את האשת חיל שמהותך \"חיל\" ואת שלמה בכל, עלית על כולנה, ואת עלית, מילת \"את\" באה לרמוז את השלימה בכל מאל\"ף ועד תי\"ו, עולה על הכל. זת\"ד ודפח\"ח. והדברים עולים לכיוון אחד. יבח\"ר].","b":false},{"t":"(בעהית\"ש אור ליום ה' כ\"א אדר התשמ\"ח)","b":false}]},{"id":"17","t":"תפלת מנחה והלימוד ממנה להנהגה הראויה לאדם בעוה\"ז","p":[{"t":"וְיִצְחָק בָּא מִבּוֹא בְּאֵר לַחַי רֹאִי וְהוּא יוֹשֵׁב בְּאֶרֶץ הַנֶּגֶב, וַיֵּצֵא יִצְחָק לָשׂוּחַ בַּשָּׂדֶה לִפְנוֹת עָרֶב וַיִּשָּׂא עֵינָיו וַיַּרְא וְהִנֵּה גְמַלִּים בָּאִים, וַתִּשָּׂא רִבְקָה אֶת עֵינֶיהָ וַתֵּרֶא אֶת יִצְחָק וַתִּפֹּל מֵעַל הַגָּמָל וגו': (כד, סב-סד)","b":true},{"t":"ובמסכת ברכות (כו, ב), איתא, יצחק תקן תפלת מנחה, שנאמר, ויצא יצחק לשוח בשדה לפנות ערב ואין שיחה אלא תפלה שנאמר (תהלים קב, א), תפלה לעני כי יעטוף ולפני ה' ישפוך שיחו.","b":false},{"t":"וידוע, דתפלת מנחה יש בה נסיון גדול, כי זמנה הוא באמצע היום, וצריך האדם להפסיק את כל עיסוקיו ולהתרכז בתפלה, שלא כמו תפלת שחרית שעדיין האדם בשלוה אחר מנוחת הלילה, ודעתו צלולה עליו, כי עדיין לא יצא לפעלו ולעבודתו. וגם תפלת ערבית נסיונה יותר קל מתפלת מנחה, משום שלעת ערב כבר סיים את כל עסקיו. אך בתפלת מנחה צריך להפסיק את כל עניניו באמצע, וקשה לצאת מענין לענין שלא באותו ענין, וגם להתרכז בתפילה בתוך כל העסקים. שלזה צריך גבורה לכבוש את יצרו ולשלוט ברוחו. ואולי הוא מאמר רבי חלבו בשם רב הונא (ברכות ו, ב), לעולם יהא אדם זהיר בתפלת המנחה, שהרי אליהו לא נענה אלא בתפלת המנחה שנאמר ויהי בעלות המנחה ויגש אליהו הנביא ויאמר וגו' ענני ה' ענני וכו', כי תפלת מנחה מיוחדת בזה מכל התפלות. ועל כן יצחק אבינו ע\"ה שמדתו גבורה, הוא זה שתיקן את תפילת מנחה. ואולי לזה אמר ויצא יצחק לשוח, שבשביל תפלת מנחה צריך להוציא את עצמו מכל עניני החולין, ועל האדם להרגיש שאין לו שום קשר עם עניני העולם הזה, ולחשוב כאילו הוא עומד בשדה.","b":false},{"t":"אלא שצריך להבין את סמיכות הפסוקים המתארים את יציאתו לשדה לתקן את תפלת מנחה, לבין הפגישה עם רבקה. והגם שלפי פשוטו של מקרא יצא יצחק לשדה ואז הזדמן לו לראות את הגמלים באים ועמם רבקה. אבל מכל מקום, אם התורה ראתה להדגיש את דבר הסמיכות הזו, הדבר אומר דרשני.","b":false},{"t":"ואולי יש לרמוז בזה, על הזמן הראוי לאדם לצאת לקראת חתונתו, שהוא אחר שזכה לתקן תפלת מנחה, שהרי הבן יושב ועוסק בתורה ומסתופף בצילא דמהימנותא, וכל היום עוסק בלימוד התורה ועבודת ה', וכשמגיע יום חופתו, צריך להתחיל לצאת אל העולם הרחב עם כל נסיונותיו, ובודאי צריך הכנה גדולה לזה. וכאן לימדה אותנו התורה בסמיכות הענינים, דלפני יציאה זו צריך לתקן תפלת מנחה, דאם האדם זכה להגיע לאותה מעלה שיכול לתקן תפלת מנחה, דהיינו ששום עסק לא מפריעו מעבודת בוראו, ויכול להניח את כל עניני החולין, ולעמוד להתפלל מנחה כדבעי בעוז וגבורה, איש כזה הוא המוכשר והמסוגל לצאת לקראת בנין ביתו, ובנינו יהיה יציב וקיים בעה\"ו, ולבו סמוך ובטוח בה', שגם בהיותו טרוד ועסוק על המחיה ועל הכלכלה וכיו\"ב, שהוא בבחינת רחיים על צוארו (ראה קדושין כט, ב), מ\"מ הוא ישאר בקביעותו בעבודת ה' ללא מפריע, ותורתו תהיה שלימה כאשר היתה באמנה אתו, והיא תהיה לעזר לו בתורתו ובעבודת ה', ויעלה ויתעלה עוד עוד, דלא דומה תורה של ילדות ונערות, לתורה של בגרות וטהרה (כמבואר בגמ' קדושין כט, ב). אבל אם עדיין אינו יכול לתקן תפילת מנחה כדבעי, עדיין אינו מוכשר כראוי לצאת למערכת החיים הקשה והממושכה.","b":false},{"t":"וזהו הרמז, \"ויצא יצחק לשוח בשדה לפנות ערב\", אחר שיצא והרגיש שבכחו לתקן ולהתפלל תפלת מנחה, או אז, וישא עיניו וירא והנה וגו' ונשא את רבקה לאשה.","b":false},{"t":"(נתחדש בשמחת חתן וכלה פרשת חיי שרה)","b":false}]},{"id":"17","t":"חינוך הבנים- והזהירות מהשפעה רעה","p":[{"t":"וְאַבְרָהָם זָקֵן בָּא בַּיָּמִים וַה' בֵּרַךְ אֶת אַבְרָהָם בַּכֹּל, וַיֹּאמֶר אַבְרָהָם אֶל עַבְדּוֹ זְקַן בֵּיתוֹ הַמּשֵׁל בְּכָל אֲשֶׁר לוֹ שִׂים נָא יָדְךָ תַּחַת יְרֵכִי, וְאַשְׁבִּיעֲךָ בַּה' אֱלֹהֵי הַשָּׁמַיִם וֵאלֹהֵי הָאָרֶץ אֲשֶׁר לֹא תִקַּח אִשָּׁה לִבְנִי מִבְּנוֹת הַכְּנַעֲנִי אֲשֶׁר אָנֹכִי יוֹשֵׁב בְּקִרְבּוֹ, כִּי אֶל אַרְצִי וְאֶל מוֹלַדְתִּי תֵּלֵךְ וְלָקַחְתָּ אִשָּׁה לִבְנִי לְיִצְחָק, וַיֹּאמֶר אֵלָיו הָעֶבֶד אוּלַי לֹא תֹאבֶה הָאִשָּׁה לָלֶכֶת אַחֲרַי אֶל הָאָרֶץ הַזֹּאת הֶהָשֵׁב אָשִׁיב אֶת בִּנְךָ אֶל הָאָרֶץ אֲשֶׁר יָצָאתָ מִשָּׁם, וַיֹּאמֶר אֵלָיו אַבְרָהָם הִשָּׁמֶר לְךָ פֶּן תָּשִׁיב אֶת בְּנִי שָׁמָּה, ה' אֱלֹהֵי הַשָּׁמַיִם אֲשֶׁר לְקָחַנִי מִבֵּית אָבִי וּמֵאֶרֶץ מוֹלַדְתִּי וַאֲשֶׁר דִּבֶּר לִי וַאֲשֶׁר נִשְׁבַּע לִי לֵאמֹר לְזַרְעֲךָ אֶתֵּן אֶת הָאָרֶץ הַזֹּאת הוּא יִשְׁלַח מַלְאָכוֹ לְפָנֶיךָ וְלָקַחְתָּ אִשָּׁה לִבְנִי מִשָּׁם, וְאִם לֹא תֹאבֶה הָאִשָּׁה לָלֶכֶת אַחֲרֶיךָ וְנִקִּיתָ מִשְּׁבֻעָתִי זֹאת רַק אֶת בְּנִי לֹא תָשֵׁב שָׁמָּה, וַיָּשֶׂם הָעֶבֶד אֶת יָדוֹ תַּחַת יֶרֶךְ אַבְרָהָם אֲדֹנָיו וַיִּשָּׁבַע לוֹ עַל הַדָּבָר הַזֶּה: (כד, א-ט)","b":true},{"t":"הנה הכתוב הפליג כאן בתאוריו של אליעזר, לומר לנו שאליעזר היה חשוב מכל בית אברהם, וגם נאמן ביתו ואיש סודו, ועל פיו התנהלו כל עניני אברהם אבינו ע\"ה, כמו שנאמר, המושל בכל אשר לו, ולא מעט נכסים היו לו לאברהם, ובכולם משל אליעזר, ומעולם לא מצאנו שאברהם השביעו או חשדו לאליעזר באיזה ענין. אך עם כל זאת כשבא אברהם לעשות את אליעזר שליח לקחת אשה ליצחק בנו. כאן אינו סומך על הנאמנות והיושר של אליעזר, רק דורש ממנו, שים נא ידך וכו', ואשיבעך בה' אלהי השמים ואלהי הארץ וגו'. ומשביעו שבועה חמורה בנקיטת חפץ ובשם ה', שלא יקח אשה ליצחק מבנות כנען.","b":false},{"t":"לומר לך, שלא כפי המקובל היום, שבעניני ממון דואגים ומתענינים ובודקים וכו', ואלו בחינוך הבנים ושאר עניני שמים, נוטים לסמוך ולהאמין בלי חקירות ודרישות. אבל אצל אברהם אבינו ע\"ה הכל היה הפוך. כי בעניני כסף ומקנה היה כבד מאד, ועם כל זה הממון לא תפס אצלו כלל שום חשיבות, ולכן נתן את הכל ביד אליעזר באמונה ללא דרישות וחקירות, ובודאי בלי שבועות. אבל בדבר ששייך לעבודת ה', אין אברהם סומך ולא מאמין, ואפי' על אדם נאמן וישר כאליעזר שהיה דולה ומשקה מתורת רבו לאחרים (ראה יומא כח, ב ורש\"י בראשית טו, ב), ושעליו נאמר (ראה ב\"ר ס, ח ובילקוט שמעוני בראשית רמז ק\"ט), יפה שיחתן של עבדי אבות וכו'. (וראה מזה עוד בספר קרית ארבע).","b":false}]},{"id":"17","t":"\"כחה של השפעה\"","p":[{"t":"והנה מצינו כי אחר השבועה החמורה שנשבע אליעזר לאברהם אבינו, מצינו את אליעזר שואל, \"אולי לא תאבה האשה ללכת אחרי, ההשב אשיב את בנך אל הארץ אשר יצאת משם\". ואברהם ענה לו בלשון תקיפה והחלטית, \"השמר לך פן תשיב את בני שמה\". ואחר שנתן לו ברכה שיצליח למצוא בת זוג המתאימה ליצחק, סיים ואמר לו, ואם לא תאבה האשה ללכת אחריך, ונקית משבועתי זאת, \"רק את בני אל תשב שמה\". והננו רואים את אברהם חוזר ומדגיש לאליעזר שלא יוציא את בנו יצחק מארץ ישראל. ורש\"י ז\"ל פירש, ונקית משבועתי זאת, וקח לו אשה מבנות ענר אשכול וממרא, ע\"כ (ועי' קדושין סא, ב). והמתבונן בפרשה תמה על דברי אברהם אבינו. הלא בתחילה אברהם אבינו ע\"ה הזהיר כל כך את אליעזר שיקח רק מבנות משפחתו אשה ליצחק, וכ\"כ היה חשוב בעיניו היחוס, ואיך עתה הריהו מוכן לוותר על יחוס המשפחה, ולקחת לבנו מבנות ענר אשכול וממרא, וזאת מסיבה אחת, שהיא, \"רק את בני אל תשב שמה\", וצריכים להבין מה הטעם להקפדה זו.","b":false},{"t":"וצריכים לומר שאברהם אבינו ע\"ה, ידע את כחה ועוצמתה של ההשפעה הרעה, וכמה האדם מושפע מסביבה רעה, ומשום זה נתיירא אברהם כל כך על יצחק שלא יעבור למקום אחר, ואפי' שהמדובר היה באיש גדול קרוב לארבעים שנה, ולא סתם אדם, אלא יצחק אבינו ע\"ה, אשר לא מכבר עמד בנסיון גדול ונורא בעקידה, ששם גילה את מסירות נפשו העצומה לקיים את רצון ה', וכאשר אומרים בפיוט המופלא של רבינו אפרים \"אם אפס\".","b":false},{"t":"רָאָה יָחִיד כִּי הוּא הַשֶׂה / נָאַם לְהוֹרוֹ הַמְּנֻסֶּה / אָבִי אוֹתִי כַּכֶּבֶשׂ תַּעֲשֶׂה / לֹא תַחְמֹל וְלֹא תְכַסֶּה/ בִּי חָפֵץ וְנִכְסֹף / לְבָבִי לוֹ לַחֲשׂף / אִם תִּמְנָעֵנִי סוֹף / רוּחִי וְנִשְׁמָתִי אֵלָיו יֶאֱסֹף.","b":false},{"t":"ובמעשה העקידה נתקדש יצחק בקדושה עליונה. והנה עם כל זאת מצינו לאברהם אבינו שהוא מתמלא ביראה ומפחד על עתיד בנו יצחק, ואינו מסכים שישיבו את בנו לארם נהרים, כי גם בגיל כזה, עדיין צריך ליזהר מהשפעה רעה רח\"ל. והיה קל בעיני אברהם אבינו ע\"ה, לוותר אפילו על היחוס, ובלבד שיצחק בנו לא ימצא בסביבה רעה.","b":false},{"t":"ואם ביצחק נהג אברהם אבינו כך, זה מלמדנו כמה עלינו ליזהר מהשפעה רעה. ואם אפילו על יחוס שהיה כ\"כ חשוב בעיני אברהם, יותר מכל נכסיו. עד שהיה צורך להשביע את אליעזר, מה שלא עשה אתו בכל ימיו בעניני ממון ורכוש. ומ\"מ כשעמדה לפניו הברירה, להעמיד את יצחק בסכנת השפעה רעה כדי להשיג את היחוס, לא היסס, אלא מיד מזהיר את אליעזר בלשון חד משמעי שאינו משתמע לשתי פנים, \"רק את בני אל תשב שמה, ק\"ו שאין לאדם להעמיד עצמו בנסיון זה של השפעה רעה בשביל עניני ממון ונוחות וכיו\"ב.","b":false},{"t":"* * *","b":false},{"t":"עוד מצאנו דוגמא אחרת בפרשה, המלמדת אותנו כמה עלינו להתרחק מסביבה רעה, והיא ברבקה, כי אחר שהלך אליעזר למקום רבקה, וראה את רבקה והוטבה בעיניו בעבור יצחק, מיד הלך לבית הוריה, ואחר שאליעזר סיפר את כל המעשה ללבן ובתואל, והם אמרו לו, אם מה' יצא דבר לא נוכל לומר רע או טוב, והוציא אליעזר מגדנות ותכשיטים וכו' ואח\"כ מתארים לנו הפסוקים (בראשית כד, נד-נח):","b":false},{"t":"וַיֹּאכְלוּ וַיִּשְׁתּוּ הוּא וְהָאֲנָשִׁים אֲשֶׁר עִמּוֹ וַיָּלִינוּ וַיָּקוּמוּ בַבֹּקֶר וַיֹּאמֶר שַׁלְּחֻנִי לַאדֹנִי, וַיֹּאמֶר אָחִיהָ וְאִמָּהּ תֵּשֵׁב הַנַּעֲרָה אִתָּנוּ יָמִים אוֹ עָשׂוֹר אַחַר תֵּלֵךְ, וַיֹּאמֶר אֲלֵהֶם אַל תְּאַחֲרוּ אֹתִי וַה' הִצְלִיחַ דַּרְכִּי שַׁלְּחוּנִי וְאֵלְכָה לַאדֹנִי, וַיֹּאמְרוּ נִקְרָא לַנַּעֲרָה וְנִשְׁאֲלָה אֶת פִּיהָ, וַיִּקְרְאוּ לְרִבְקָה וַיֹּאמְרוּ אֵלֶיהָ הֲתֵלְכִי עִם הָאִישׁ הַזֶּה וַתֹּאמֶר אֵלֵךְ וגו':","b":false},{"t":"ולכאורה הבקשה של בני משפחת רבקה היתה מוצדקת, דהגם שהסכימו לתת את רבקה לאליעזר עבור יצחק, אבל מכל מקום, רוצים הם עוד לשבת עמה בטרם תלך, וגם מעוניינים היו להכין לה צרכי חופה וכיו\"ב. ומה היה לו לאליעזר לטעון, ולומר להם אל תאחרו אותי וה' הצליח דרכי, כאילו הם באו לקלקל את הצלחתו. ושמא תאמר שממהר היה, כי איחר לשוב לאדוניו, ואינו רוצה שידאג אברהם על שאיחר לשוב. ליתא, דהא כתיב (בראשית כד, מב), ואבא היום אל העין, ואמרו חז\"ל (ב\"ר נט, יא ופרדר\"א פט\"ז), היום יצאתי והיום באתי, מלמד שקפצה לו הדרך. וא\"כ לפחות היה לו לחשב את זמן הדרך שהרויח ע\"י קפיצת הדרך, ואותו זמן יניח את רבקה אצל הוריה, ורק אחר כך ישוב לאדוניו. ועוד דעדיין היתה רבקה קטנה וצריכה להוריה (כמבואר בפרקי דר\"א פל\"א שהיתה רבקה בת שלש כשנשאה יצחק, ע\"ש), ולמה לא יתננה אליעזר להרגיע נפשה.","b":false},{"t":"אמנם צריך לומר שאליעזר שהיה דולה ומשקה מתורת רבו לאחרים, למד מאברהם כמה מסוכנת היא ההשפעה הרעה. וכמה צריך להתרחק ממנה. עד שלא היה מוכן להניח את רבקה במקום זה של אנשי רשע, אפילו יום אחד נוסף ולכן אמר \"שלחוני ואלכה לאדוני\". ונמצינו למדים חידוש נוסף, שאפילו שרבקה גדלה ונולדה באותו מקום, ואכלה מפיתם ומימם שתתה ועמם גדלה, וזו סביבתה הטבעית. והיה אפשר לומר, מה בכך שתשב רבקה עם הוריה ואחיה עוד כמה ימים. דממה נפשך אם היא מסוגלת לקבל השפעה, אזי כבר קיבלה השפעה רעה עד היום, ואם עד היום שמרה עצמה בגבורה נפלאה נגד השפעת בית אביה ומקום מולדתה, וכפי שכתב רש\"י על הפסוק (בראשית כה, כ), ויהי יצחק בן מ' שנה בקחתו את רבקה בת בתואל הארמי מפדן ארם אחות לבן הארמי לו לאשה, והקשה רש\"י ז\"ל, וכי עדיין לא נכתב על רבקה שהיא בת בתואל ואחות לבן, ומפדן ארם. אלא להגיד שבחה, שהיתה בת רשע ואחות רשע ומקומה אנשי רשע, ולא למדה ממעשיהם. עכ\"ל. ומקורו טהור בדברי רבותינו (ב\"ר סג, ד). וא\"כ מה היה לו לאליעזר לחשוש ולהקפיד שלא להניחה אצלם עוד ואפילו יום אחד.","b":false},{"t":"אבל כנראה שאין שום חסינות נגד השפעה רעה, ומי שעמד בה עד היום, עדיין אינו יכול להיות בטוח בעצמו שגם להבא יצליח להיות מוגן נגד ההשפעה, ותמיד הזהירות טובה ודרושה, מפני כחה ועוצמתה של ההשפעה הרעה, ואליעזר שלמד אצל אברהם אבינו ע\"ה, לא היה מוכן לשום פשרות בענין זה, אלא אמר מיד \"אל תאחרו אותי וה' הצליח דרכי\".","b":false},{"t":"* * *","b":false},{"t":"והדוגמא השלישית של ההשפעה השלילית, גם היא בפרשתנו, וממנה נלמד איך היא נראית בעיניו של אברהם אבינו ע\"ה, כמו שנאמר:","b":false},{"t":"וַיִּתֵּן אַבְרָהָם אֶת כָּל אֲשֶׁר לוֹ לְיִצְחָק, וְלִבְנֵי הַפִּילַגְשִׁים אֲשֶׁר לְאַבְרָהָם נָתַן אַבְרָהָם מַתָּנֹת וַיְשַׁלְּחֵם מֵעַל יִצְחָק בְּנוֹ בְּעוֹדֶנּוּ חַי קֵדְמָה אֶל אֶרֶץ קֶדֶם: (כה, ה-ו)","b":false},{"t":"כאן רואים את הכח הרוחני העצום שהיה לאברהם, ואת דאגתו הגדולה לבנו ליצחק גם אחר נישואיו, ושוב רואים את פחדו ויראתו מפני השפעה זרה, ואפילו כשמדובר בבניו, מכל מקום, כשראה וידע את דרכם של בני הפילגשים שאינם הולכים בדרך האמת, חשש שוב, שמא הם ישפיעו לרעה על יצחק ורבקה, שזה עתה החלו את חייהם העצמאיים, ואולי חשש גם על בניהם העתידיים של יצחק ורבקה שלא יהיו במחיצה אחת עם בני הפילגשים, ואעפ\"י שמדובר בבניו, וכפי שכתב רש\"י ז\"ל (שם), בשם רז\"ל (ב\"ר סא, ד), שכולם היו בניה של הגר, ומשום כך כתוב פלגשם חסר י', לומר שלא היתה אלא פילגש אחת, הלא היא הגר. ועל הגר נאמר, ויוסף אברהם ויקח אשה ושמה קטורה (בראשית כה, א), וכתב רש\"י ז\"ל (ומקורו מדברי רבותינו בב\"ר סא, ד), קטורה, זו הגר, ונקראה קטורה על שם שנאים מעשיה כקטורת. ע\"כ. והנה אעפ\"י כן לא היסס אברהם מלשלחם מעל פני בנו בעודנו חי, ונתן להם מתנות ושילחם, כדי שלא ישפיעו על יצחק בנו לרעה. ומכאן אנו רואים עד כמה צריך האדם להיות מוכן להקריב ולותר, וזאת, בשביל להתרחק בעצמו ולהרחיק כל השפעה רעה מעליו ומעל ב\"ב, שאפילו את בניו הוא מוכן לשלח, וכמו שאמרו חז\"ל (ב\"ר נג, יא), על שרה אמנו ע\"ה, כשאמרה \"גרש את האמה הזאת ואת בנה, כי לא ירש עם בני עם יצחק (בראשית כא, י). כי שרה חששה שישמעאל ישפיע על יצחק, והקב\"ה אמר לו לאברהם (שם שם, יב), כל אשר תאמר אליך שרה שמע בקולה. וכן עשה אברהם ושילח את הגר עם בנה ישמעאל. וכן נהג אברהם לפני מותו. ושילח את בני הפילגשים. כי אין פשרות בחינוך, ומי כמוהו יודע מהו חינוך, שהרי עליו העיד הקב\"ה \"כי ידעתיו למען אשר יצוה את בניו ואת ביתו אחריו, ושמרו דרך ה' לעשות צדקה ומשפט\" (בראשית יח, יט). ואם ביצחק הקדוש, נזהר אברהם אבינו כל כך, ואנן יתמי דיתמי מה נענה אבתרייהו.","b":false},{"t":"* * *","b":false},{"t":"וכמה לימוד יש לנו ללמוד מאבינו הראשון, לענין חינוך הבנים, והבנות, ולדאוג להם גם בהיותם גדולים, וצדיקים, דכל אשר לאדם יתן בעד נפשו, כי כל הרכוש וקנייני העולם הזה, אינם שוים למאומה כנגד עניני הנפש. ודרך העולם להיות זהירים וערים בעניני רכוש וקנייני העוה\"ז, ושמים את כל מעיינם, בהתעוררות נפלאה, שלא יחסר להם דבר מעניני העולם, והאדם טורח מאד להשיג את המותרות, לא ילוזו מנגד עיניו, ועיניו לנוכח יביטו, בזריזות וחריצות, יומם ולילה לא ישבותו, להשיג את מבוקשו ותאותו. אך בעניני תורה ומצות, וכן בענינים הנוגעים לחינוך הילדים בזה הוא מיקל ראש, וסומך על כל אחד, ועל כל מצב, באין חוקר ואין דורש, אשר זה לבד מראה לעיני כל, כי האיש הזה אינו מעמיד את ענין חינוך הבנים ועסק המצוות במשקל הנכון, ואינם ראשונים בסדר עניניו, רק דוחה אותם לתחתית הסולם, ולא חלי ולא מרגיש. ואם ישאלוהו, איך הוא מתנהג בענין חינוך הילדים ובשאר עניני התורה והמצוות ועבודת ה'. הלא מיד ישיב שזה בראש כל מעיניו, כראוי וכנדרש. אבל בפועל עודנו רחוק מקו האמת, ועדיין עיניו ולבו נתונים על ממונו, ועניני הנפש מונחים בקרן זוית, ורק אחת לכמה זמן, בבא איזה התעוררות בלבו, על ידי שקרא באיזה ספר מוסר, או ששמע איזו דרשה וכיוצא בזה, או אז הוא קם ומתעודד ושואל ודורש בתוקף לדעת מה עם הילדים, ואיפה נמצאים בשעות כאלה וכאלה, אך מיד מזניח את הדברים ושב לעניניו כבתחילה, אחת למעלה ושבע למטה, ושוקע בעניניו שוב, איזה ימים או שבועות, עד להתעוררות הבאה. ובצורה כזאת איך יצפה מבניו שילכו בדרך הטוב והישר.","b":false},{"t":"ועל כן ראוי לכולנו לשים לנגד עינינו את מעשיו של אברהם אבינו ע\"ה, ויהיו חקוקים לנגד עינינו, וראיתם אותם וזכרתם, איך צריכים להתייחס לענין חינוך הילדים לתורה ולמצוות ולהליכה בדרכי הי\"ת, ולהתרחק מכל השפעה רעה, והבא ליטהר מסייעין אותו מן השמים (שבת קד, ב ע\"ז נה, א מנחות כט, ב).","b":false},{"t":"(אור ליום ו' לסדר חיי שרה התש\"מ)","b":false}]},{"id":"17","t":"נבהל להון איש רע עין ולא ידע כי חסר יבואהו","p":[{"t":"וַתָּמָת שָׂרָה בְּקִרְיַת אַרְבַּע הִוא חֶבְרוֹן בְּאֶרֶץ כְּנָעַן וַיָּבֹא אַבְרָהָם לִסְפֹּד לְשָׂרָה וְלִבְכֹּתָהּ, וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וַיְדַבֵּר אֶל בְּנֵי חֵת לֵאמֹר, גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם תְּנוּ לִי אֲחֻזַּת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנָי, וַיַּעֲנוּ בְנֵי חֵת אֶת אַבְרָהָם לֵאמֹר לוֹ, שְׁמָעֵנוּ אֲדֹנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ בְּמִבְחַר קְבָרֵינוּ קְבֹר אֶת מֵתֶךָ אִישׁ מִמֶּנּוּ אֶת קִבְרוֹ לֹא יִכְלֶה מִמְּךָ מִקְּבֹר מֵתֶךָ, וַיָּקָם אַבְרָהָם וַיִּשְׁתַּחוּ לְעַם הָאָרֶץ לִבְנֵי חֵת, וַיְדַבֵּר אִתָּם לֵאמֹר אִם יֵשׁ אֶת נַפְשְׁכֶם לִקְבֹּר אֶת מֵתִי מִלְּפָנַי שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר, וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ אֲשֶׁר בִּקְצֵה שָׂדֵהוּ בְּכֶסֶף מָלֵא יִתְּנֶנָּה לִּי בְּתוֹכֲכֶם לַאֲחֻזַּת קָבֶר, וְעֶפְרוֹן ישֵׁב בְּתוֹךְ בְּנֵי חֵת וַיַּעַן עֶפְרוֹן הַחִתִּי אֶת אַבְרָהָם בְּאָזְנֵי בְנֵי חֵת לְכֹל בָּאֵי שַׁעַר עִירוֹ לֵאמֹר, לֹא אֲדֹנִי שְׁמָעֵנִי הַשָּׂדֶה נָתַתִּי לָךְ וְהַמְּעָרָה אֲשֶׁר בּוֹ לְךָ נְתַתִּיהָ לְעֵינֵי בְנֵי עַמִּי נְתַתִּיהָ לָּךְ קְבֹר מֵתֶךָ, וַיִּשְׁתַּחוּ אַבְרָהָם לִפְנֵי עַם הָאָרֶץ, וַיְדַבֵּר אֶל עֶפְרוֹן בְּאָזְנֵי עַם הָאָרֶץ לֵאמֹר אַךְ אִם אַתָּה לוּ שְׁמָעֵנִי נָתַתִּי כֶּסֶף הַשָּׂדֶה קַח מִמֶּנִּי וְאֶקְבְּרָה אֶת מֵתִי שָׁמָּה, וַיַּעַן עֶפְרוֹן אֶת אַבְרָהָם לֵאמֹר לוֹ, אֲדֹנִי שְׁמָעֵנִי אֶרֶץ אַרְבַּע מֵאֹת שֶׁקֶל כֶּסֶף בֵּינִי וּבֵינְךָ מַה הִוא וְאֶת מֵתְךָ קְבֹר, וַיִּשְׁמַע אַבְרָהָם אֶל עֶפְרוֹן וַיִּשְׁקֹל אַבְרָהָם לְעֶפְרֹן אֶת הַכֶּסֶף אֲשֶׁר דִּבֶּר בְּאָזְנֵי בְנֵי חֵת אַרְבַּע מֵאוֹת שֶׁקֶל כֶּסֶף עֹבֵר לַסֹּחֵר: (כג, ב-טז)","b":true},{"t":"ראינו בפסוקים אלו את אברהם מבקש מבני חת להשיג בעבורו את מערת המכפלה אשר לעפרון בן צוחר, ושוב ראינו את עפרון אומר לאברהם שהוא נותן לו את השדה ואת המערה חינם, ואברהם בשלו שרוצה לשלם, ואז עפרון משנה את טעמו, ובא להוציא מדברי בני חת שאמרו לאברהם נשיא אלהים אתה בתוכנו במבחר קברינו קבור מתך, והוא בא להוציא מזה, לכך נאמר, ויען עפרון, היינו שהתחיל בדבר חדש, והוסיף הכתוב ואמר \"לאמר לו\", ומה אמר, ארבע מאות שקל כסף \"ביני ובינך\" מה היא וגו'. והמשיך הכתוב ואמר \"וישמע אברהם\", שמיעה היינו הבנה, כמו שמצינו בתלמוד הרבה פעמים לשון \"שומע אני\" שפירושו מבין אני (לדוגמא עי' משנה סנהדרין א, ו ובפסחים צד, ב ור\"ה ו, א ועוד הרבה מקומות), והיינו שאברהם הבין היטב את דברי עפרון אשר דיבר לו, וישקול אברהם לעפרן וגו', ובלאו הכי ביקש אברהם ואמר, בכסף מלא יתננה לי, ועתה כששמע את רמזי עפרון הברורים אליו, הוסיף ושקל בכסף עובר לסוחר, כדי שלא יאמר עפרון אני העשרתי את אברהם, ובשביל זה מצינו שנאמר אח\"כ (בראשית כג, יז-יח), ויקם וגו' השדה לאברהם למקנה לעיני בני חת בכל באי שער עירו. והיינו שאברהם עשה הקנין בפרסום גדול לעיני הכל, שקנה את השדה בכסף מלא, כדי שידעו הכל את אמיתות הדברים, שהרי דרכם של אנשים להרבות דברים, ובפרט על מי שגדול כמו שנאמר (במדבר כא, ה), וידבר העם באלהים ובמשה, ע\"כ התווכח אברהם עם עפרון, וביקש לתת לו את כל אשר יבקש לעיני כל באי שער עירו.","b":false},{"t":"ועוד טעם שעשה אברהם אבינו פרסום כל כך בעת קניית המערה, לפי שראה את צרות עינו של עפרון, ורצה לפרסם את המקח לעיני כל, כדי שלא יבא עפרון ויערער עליו אחר זמן, ובשביל זה דאג אברהם לפרסם את המקח בגלוי וידוע ובפומבי. ואחר כל זאת נאמר (בראשית כג, יט), ואחרי כן קבר אברהם את שרה אשתו וגו'. כי אעפ\"י שמתו היה מוטל לפניו דאג תחילה להשלים את קנין השדה לעיני הכל, ורק אח\"כ התעסק בקבורת שרה כדת.","b":false},{"t":"והנה רבותינו במדרש (בראשית רבה נח, ז), דרשו על עפרון את הפסוק (משלי כח, כב), נבהל להון איש רע עין, ולא ידע כי חסר יבואהו. נבהל להון איש רע עין, זה עפרון, שהכניס עין רע בממונו של צדיק. ולא ידע כי חסר יבואהו, שחסרתו התורה וא\"ו, הדא הוא דכתיב וישמע אברהם אל עפרון וישקול אברהם לעפרן, עפרן כתיב, חסר וא\"ו. ע\"כ. והיינו שלמדתנו תורה שעפרון היה נבהל להון וצר עין בממונו של אברהם. כי מרוב בהילותו לממון, קפץ תיכף ומיד ואמר מחיר גבוה מאד לאברהם והדגיש לו את הענין היטב, כדי לזרזו ולהבטיח את מקחו, אך לא ידע כי חסר יבואהו, שהחסירו לו את האות וי\"ו משמו, כי לפני כן נכתב עפרון מלא וי\"ו, וכאן נאמר וישקול אברהם לעפרן, עפרן חסר וי\"ו.","b":false},{"t":"ובזמנו שמעתי ממגיד מישרים הרב הגה\"צ רבי שבתי יודולוביץ ע\"ה, שאמר להקשות בשם הגר\"א ז\"ל, וכי איזה חסרון יש לו לעפרון במה שהתורה לקחה לו את האות וא\"ו משמו, וכי הוא מבין בזה, ובכלל מנין ידע שיכתב שמו בתורה, ועוד שאינו יודע כלל איך כותבים \"עפרן\" אם עם אות וי\"ו או אות טי\"ת או אות למ\"ד, שאינו שייך כלל לעניני התורה, ואיזה חסרון הרגיש. ומה גם שהוא כשלעצמו אהב את הממון והרי קיבל את מבוקשו, כמו שמצינו ששקל לו אברהם ארבע מאות שקל כסף עובר לסוחר, ומה לעפרון ולאות וי\"ו.","b":false},{"t":"והגר\"א ז\"ל תירץ, דידוע שאבימלך נתן לאברהם עבור שרה, אלף כסף לכסות עינים את כל ונוכחת (כמבואר בבראשית כ, טז), ומן הסתם שאברהם אבינו לא רצה ליהנות מהכסף הזה כמו שלא נגע מחוט ועד שרוך נעל בממון ה' המלכים (בראשית יד, כג), ולכן שמר את הממון הזה לקבורתה של שרה. ועפי\"ז ביאר הוא ז\"ל, דאילו שתק עפרון, ולא היה נבהל להשיב ולהוציא רוחו בפחזותו, חשב אברהם לתת לו אלף כסף במושלם, שלשם כך הוא שמרם, ועתה שנבהל עפרון ואמר, ארבע מאות שקל כסף, נאמר וישקול אברהם לעפרן את הכסף אשר דבר באזני בני חת, ארבע מאות שקל כסף, ועפרן שמח מאד על כך שהשיג מבוקשו, אך לא ידע כי חסר יבואהו, שהחסירו לו וי\"ו, שהם \"השש מאות כסף\" שהפסיד בפחזותו. ואעפ\"י שאין לו השגה באות וי\"ו שהפסיד משמו, מ\"מ הפסד של שש מאות שקל כסף בודאי שהוא מבין, ואם כל מאמציו היו על ד' מאות. לבטח היה צערו רב כשנודע לו שהפסיד שש מאות. ודפח\"ח.","b":false},{"t":"וכמדומני שהגר\"ש יודולוביץ ז\"ל הוסיף על זה, דכל זה, הוא לפי דעתו של עפרן, אבל באמת עיקר הפסדו, הוא האות וי\"ו, דאברם לא היה מוליד, והוסיף לו הקב\"ה אות ה' בשמו, ושם את שמו אברהם כאשר נאמר (בראשית יז, ה), ולא יקרא עוד את שמך אברם והיה שמך אברהם כי אב המון גוים נתתיך. ומכח התוספת הזו של אות אחת, נולד לו יצחק וממנו בא יעקב שלם, וממנו י\"ב שבטים שבטי יה עדות לישראל, ומשם יצא משה רבינו ואהרן הכהן וכל הנביאים וכל חכמי ישראל, וכל עם ישראל עד סוף כל הדורות. וגם עפרון היה זוכה למעלות רבות ונישאות אם היה נשאר עם שמו מלא וי\"ו, כי מי יודע במה היה זוכה, ולאיזה מעלות היה מגיע, אך הוא בטפשותו שם לבו אל הממון בלבד, וגם בממון בא לו חסר גדול יותר ממה שהרויח בפועל, וק\"ו מה שהפסיד על ידי זה הוא וכל זרעו לדורות עולם, ודפח\"ח.","b":false},{"t":"ובפרט לפי מה שכתבתי בס\"ד, בהקדמה לשו\"ת שמע שלמה ח\"א, על הפסוק (שמות ח, יט), ושמתי פְדֻת בין עמי ובין עמך, למחר יהיה האות הזה, ונכתב פדת חסר וא\"ו, וכתבו על זה שהאות וא\"ו החסרה במילת פדות מראה על כך שאותה גאולה לא היתה שלמה, וכתב רבינו בחיי ז\"ל (שם), דהטעם שלא הושלמה גאולתנו ביציאת מצרים, ויש עוד גלות אחריה, לפי שעדיין לא ניתנה התורה לישראל. וביררתי שם באורך שאות וי\"ו היא בחינת התורה, כמבואר בזה\"ק פעמים אין ספור (לדוגמא ראה זוהר ח\"ב קיט, ב וראה תיקוני זוהר פב, ב), ועוד אמרו (ראה זוהר ח\"א רמא, ב), דוי\"ו הוא סימנא דחיי, וגם במסכת ב\"ב (יד, א), אמרו שהלוחות ארכן ו' טפחים ורחבן ו' טפחים, וכן ההיקף של הס\"ת הוא ו' טפחים. ע\"ש. נמצא שגם חז\"ל בגמרא רמזו את התורה בוא\"ו, ובתיקונים (תיקון כ\"ה), אמרו ומספרא דוא\"ו ואיהו ס\"ת. וכתב מרן החבי\"ף ז\"ל בספר סימנא דחיי (מערכת הוא\"ו אות ט\"ז), דמהאי טעמא נראה שניתנה תורה בששה בסיון, שהוא רמז לאות וא\"ו בחינת ס\"ת. והגה\"ק מהרצ\"ה מזידיטשוב ז\"ל אמר (והובאו דבריו בספר קרית ארבע להר\"א קליין ז\"ל פר' בראשית), שבאות ו' רמוזים קוב\"ה ואורייתא וישראל, כי וא\"ו במילוי א' עולה בגימטריא שלוש עשרה כמספר אח\"ד, לרמוז ליחידו של עולם. וי\"ו במילוי יו\"ד עולה בגימט' כ\"ב, ורומז לתורה היינו, כ\"ב אתוון דאורייתא. וכשהוא כתוב ו\"ו עולה בגימטריא י\"ב שבטי יה עדות לישראל, ובזה פירש מה שכתב האר\"י החי זיע\"א בשירו הנפלא \"אזמר בשבחין\" בווי\"ן תתקטר, היינו שע\"י הווי\"ן מתקשרים עם השכינה הקדושה. ולכן מצינו באות ו' שקורין אותה ו' החיבור (וראה זוהר ח\"ב קכז, א), שרומזת לחיבור הזה דקוב\"ה ואורייתא וישראל דחדא נינהו (ראה זוהר ח\"ג עג, א), וע\"ש באורך גדול ונפלא בס\"ד.","b":false},{"t":"ולכן דייקו רבותינו ודרשו על עפרון הנבהל לממון את הפסוק \"חסר יבואהו\", ולא אמר \"חסר בא לו\" בלשון עבר \"בא לו\", אלא \"יבואהו\", שהוא לשון הווה, להורות שחסרונו נמשך ולא נפסק רח\"ל, כי בפחזותו וכסילותו הפסיד את החיבור לה' ולתורתו, דמי יודע אם לא החסיר הוי\"ו אפשר שהיה זוכה להתחבר לעם ה' ונחלתו, והיה נוחל את שתי העולמות.","b":false}]},{"id":"17","t":"הנהגות דרך ארץ שנהג אברהם אבינו בבעת קניית מערת המכפלה","p":[{"t":"וַיָּקָם אַבְרָהָם מֵעַל פְּנֵי מֵתוֹ וַיְדַבֵּר אֶל בְּנֵי חֵת לֵאמֹר, גֵּר וְתוֹשָׁב אָנֹכִי עִמָּכֶם תְּנוּ לִי אֲחֻזַּת קֶבֶר עִמָּכֶם וְאֶקְבְּרָה מֵתִי מִלְּפָנָי, וַיַּעֲנוּ בְנֵי חֵת אֶת אַבְרָהָם לֵאמֹר לוֹ, שְׁמָעֵנוּ אֲדֹנִי נְשִׂיא אֱלֹהִים אַתָּה בְּתוֹכֵנוּ בְּמִבְחַר קְבָרֵינוּ קְבֹר אֶת מֵתֶךָ אִישׁ מִמֶּנּוּ אֶת קִבְרוֹ לֹא יִכְלֶה מִמְּךָ מִקְּבֹר מֵתֶךָ, וַיָּקָם אַבְרָהָם וַיִּשְׁתַּחוּ לְעַם הָאָרֶץ לִבְנֵי חֵת, וַיְדַבֵּר אִתָּם לֵאמֹר אִם יֵשׁ אֶת נַפְשְׁכֶם לִקְבֹּר אֶת מֵתִי מִלְּפָנַי שְׁמָעוּנִי וּפִגְעוּ לִי בְּעֶפְרוֹן בֶּן צֹחַר, וְיִתֶּן לִי אֶת מְעָרַת הַמַּכְפֵּלָה אֲשֶׁר לוֹ אֲשֶׁר בִּקְצֵה שָׂדֵהוּ בְּכֶסֶף מָלֵא יִתְּנֶנָּה לִּי בְּתוֹכֲכֶם לַאֲחֻזַּת קָבֶר: (כג, ג-ט)","b":true},{"t":"ראינו בפסוקים כי אברהם אבינו השתחוה לפני בני חת, ולא זאת בלבד, אלא הוסיף ואמר, אם יש את נפשכם לקבור את מתי שמעוני ופגעו לי בעפרן וכו'.","b":false},{"t":"וקשה, הלא בני חת אמרו כבר לאברהם, נשיא אלהים אתה בתוכנו במבחר קברנו וגו', ולמה אברהם צריך להשתחוות להם, ולהוסיף לבקש אם יש את נפשכם שמעוני ופגעו לי בעפרון, והלא התורה מציינת לנו (בראשית כג, י), ועפרון יושב בתוך בני חת, ומסתמא גם הוא היה בכלל האומרים במבחר קברינו וכו', ולכל הפחות, הדברים נאמרו גם על דעתו. כי הלא בני חת אמרו בפירוש, איש ממנו את קברו לא יכלה ממך מקבור מתך. ועיין באוה\"ח הקדוש שכנראה נרגש מזה, יע\"ש בדב\"ק.","b":false},{"t":"ובדרך פשוטה נלע\"ד, דהגם שבני חת אמרו לו כן, מכל מקום אינו מדת דרך ארץ, לבא וליטול את היפה והמשובח שיש להם. כי בני חת דברו עם אברהם בכבוד מופלג כראוי לנשיא אלהים, והנה גם אם היה אברהם מתרצה לדבריהם ויתנו לו חנם אחוזת קבר, מכל מקום אינו נאה ואינו יאה שיבקש הוא ליקח לעצמו חלקת אדמה מסויימת, אלא היה אומר להם תבחרו את הטוב בעינכם ותתנו לי.","b":false},{"t":"אמנם אברהם הכיר ברוממות גדולת מערת המכפלה ששם נקברו אדם וחוה, כמו שאיתא בזוה\"ק (ח\"א קכז, א ואילך), ולכן עשה כל טצדקי כדי להשיג מערה זו, ופנה בלשון בקשה גדולה שיפגעו לו בעפרון, וגם שילם כסף מלא כדי שלא יערערו עליו, ויאמרו בחינם לקח, ולכן עשה בטכסיס, שהניחם שיאמרו לו מעצמם שהם נותנים לו חינם אין כסף חלקת קבר במקום שירצה, ואחר שאמרו כך, הוא שינה את טעמו ויאמר להם שברצונו לשלם, ושידלם להשיג לו בדוקא את שדה עפרון, ולא רצה מתנת חינם אלא אמר, בכסף מלא יתננה לי.","b":false},{"t":"ועוד לימדה אותנו תורה דרך ארץ, ממעשה אבותינו, שלא יהיה האדם להוט אחר מתנת חנם, ותמיד יעדיף לקחת בכסף מלא, ויחיה בשלוה ונאמר (משלי טו, כז), ושונא מתנות יחיה. וידוע מאמר הרב מבריסק זלה\"ה \"הכי זול הוא לשלם\".","b":false},{"t":"וגם למדנו שאפילו שלא לקח אברהם את השדה בחנם כמו שאמרו לו, בכל זאת היה מודה להם ומכבדם, וישתחו אברהם לפני עם הארץ.","b":false}]},{"id":"17","t":"צדיקים במיתתן קרויין חיים","p":[{"t":"וַיִּהְיוּ חַיֵּי שָׂרָה מֵאָה שָׁנָה וְעֶשְׂרִים שָׁנָה וְשֶׁבַע שָׁנִים שְׁנֵי חַיֵּי שָׂרָה, וַתָּמָת שָׂרָה וגו': (כג, א-ב)","b":true},{"t":"לכשנתבונן בפרשה נראה כי כתוב בה ענין מיתתה של שרה אמנו ע\"ה, והנה פרשה זאת קרויה \"חיי שרה\", וכן מצינו בפרשת ויחי יעקב, שאע\"פ שהיא מספרת על הסתלקות יעקב, הריהי קרויה \"ויחי יעקב\".","b":false},{"t":"והביאור בזה, כי ידוע שכל חייהם של הצדיקים אינם בעבור העוה\"ז, אלא כל מה שהם עושים, דעתם על חיי העולם הבא, שהוא עולם הנצח, והם חיים כאן בהרגשה ברורה שהעולם הזה אינו אלא פרוזדור בפני העולם הבא, ומתקינים עצמם בזה הפרוזדור, כדי ליכנס לטרקלין שהוא העולם הבא (אבות ד, טז). ושם הוא עולם החיים, ולכן התורה מלמדתנו כי בעת מיתתן של צדיקים מתחילים החיים, כי נשמותיהם הולכות להסתופף בחצרות בית ה' חי החיים","b":false},{"t":"ומה נפלאו דברי רבותינו (ברכות יח, א-ב), שהצדיקים במיתתם קרויים חיים ואילו הרשעים אף בחייהם קרוים מתים. וביאור הדבר, כי הצדיקים אין מטרתם אל העולם הזה כלל, אלא מתכוננים לחיי הנצח של העוה\"ב, ולכן במיתתם הולכים מיד לאור באור פני מלך חיים, וכיון שהם דבוקים בחי החיים לכך אינם קרוים מתים.","b":false},{"t":"אמנם הרשעים דעה נפסדת להם, באמרם כי כל עיקר ביאתם לעולם הזה הוא כדי ליהנות ולא עוד, וכדברי הנביא ע\"ה אָכֹל בָּשָׂר וְשָׁתוֹת יָיִן אָכוֹל וְשָׁתוֹ כִּי מָחָר נָמוּת (ישעיה כב, יג). ונמצא כי כל מטרתם הוא רק העולם הזה, וכל חייהם בריצה מטורפת אחר הנאות העוה\"ז וגם את זה לא ישיגו, והם מצטערים שאין תאותם באה על סיפוקה, וחייהם אינם חיים כי תמיד מתאוים לעוד הנאות, מה שאינם יכולים להשיג, ולכן אף בחייהם הקצרים בעולם הזה הריהם דומים למתים כי אינם יכולים להשיג את כל אשר יחפוצו, וזאת, מלבד מה שמפסידים את חיי העוה\"ב. ועל כן פרשת מיתתן של צדיקים קרויה בלשון \"חיים\", חיי שרה, ויחי יעקב.","b":false}]}]},{"slug":"תולדות","name":"פרשת תולדות","items":[{"id":"14","t":"באיזה שם בירך יצחק את יעקב","p":[{"t":"וְאֵל שַׁדַּי יְבָרֵךְ אֹתְךָ וְיַפְרְךָ וְיַרְבֶּךָ וְהָיִיתָ לִקְהַל עַמִּים, וְיִתֶּן לְךָ אֶת בִּרְכַּת אַבְרָהָם לְךָ וּלְזַרְעֲךָ אִתָּךְ לְרִשְׁתְּךָ אֶת אֶרֶץ מְגֻרֶיךָ אֲשֶׁר נָתַן אֱלֹהִים לְאַבְרָהָם: (כח, ג-ד)","b":true},{"t":"רבינו יוסף חיים ז\"ל כתב בספר בן איש חי (שנה שניה ריש פר' תולדות), דברים נפלאים, וז\"ל:","b":false},{"t":"ואל שדי יברך אותך, נראה לי בס\"ד, הנה ברכה זו שבירך יצחק את יעקב באחרונה, מתחלת באות וא\"ו ומסיימת באות מ\"ם, והוא רמז למילוי שם הוי\"ה דיודי\"ן, שעולה מספר מ\"ו (יו\"ד ה\"י וי\"ו ה\"י מניינו ע\"ב, וכשתסיר מהם שם הוי\"ה יהיו בידך מ\"ו וזהו המילוי), אבל ברכה ראשונה שבירכו יצחק ליעקב (בראשית כז, כח), בויתן לך האלהים מתחלת באות וא\"ו ומסיימת באות כ\"ף (ויתן לך וגו' ומברכיך ברוך). הרי כ\"ו כמנין שם הוי\"ה כפשוטו (ללא מילוי).","b":false},{"t":"נמצא כי תחלה ברכו יצחק ליעקב כנגד מספר הפשוט, ואח\"כ ברכו כנגד מספר המילוי שהוא מ\"ו דהוא מילוי ע\"ב שעולה חסד (חסד גימ' ע\"ב).","b":false},{"t":"וידוע מה שאמרו בזוה\"ק בפרשה זו דף קמ\"ו, דיעקב וזרעו לא נשתמשו בעולם הזה אלא בברכה אחרונה של יצחק והיא זו. אבל ברכה ראשונה שמורה לימות המשיח. ומזה פירשתי בס\"ד רמז הכתוב (תהלים כט, יא), ה' עוז לעמו יתן ה' יברך את עמו בשלום. חלק תיבות \"שלום\" לשתים, וקרי בה ש\"ל ו\"מ. כלומר, יברכם עתה בזה\"ז בברכה של ו\"מ שהיא ברכה של ואל שדי, המתחלת באות וא\"ו ומסיימת באות מ\"ם. ובזה יובן בס\"ד רמז הכתוב (שמות טו, יז), תביאמו ותטעמו בהר נחלתך מכון לשבתך פעלת ה'. קרי בה תביא מ\"ו ותטע מ\"ו. דהיינו ברכת ואל שדי שראשה וא\"ו וסופה מ\"ם [תהיה] בהר נחלתך, רצונו לומר, קודם ביאת המשיח שאז נחלתך שהוא בהמ\"ק נקרא \"הר\" אך כשיהיה מכון לשבתך, [שיקרא בית] שבית שלישי נקרא \"בית\", אז פעלת ה', כלומר תפעול בברכה ראשונה של ויתן לך האלהים, שראשה וא\"ו וסופה כ\"ף כמנין שמך ה' (שם הוי\"ה) וכו', עכ\"ל.","b":false},{"t":"וקשה לי טובא, דאם כן למה בברכה הראשונה התנה בה יצחק תנאי, באמרו (בראשית כז, מ), והיה כאשר תריד ופרקת עולו וגו' וע\"ש בדברי התרגום ורש\"י, שאם ישראל אינם מקיימים את המצוות אז יהא לעשו פתחון פה על הברכות. ואם לפי דברי הזוה\"ק הנז', הרי הברכה הזאת היא שייכת לעתיד לבא אחר ביאת המשיח, וא\"כ כבר חזרו כולם בתשובה והרשעה כולה כעשן תכלה, ומה מקום לתנאי זה. ועוד מצאנו בתוך דברי הברכה שאמר יצחק ליעקב (בראשית כז, כב), \"הקל קול יעקב\", והנה רואים אנו שמילת הקל הראשונה חסרה וי\"ו, ופי' הגר\"א ז\"ל (בספר דברי אליהו פר' תולדות בשם ספר קול רינה), שאם הקו\"ל נעשה \"קל\" ויש רפיון וקול התורה איננו נשמע ברמה, אז ממילא ידי עשו קמים ח\"ו, אבל אם קולו של יעקב נשמע בבתי כנסיות ובתי מדרשות, והוא קול חזק ומלא וא\"ו, אז אין ידי עשו יכולים לעשות מאומה, ונשברים וכלים מאליהם. (ועי' מ\"ש בזה בהקדמת שו\"ת שמע שלמה בעה\"ו בהקדמת ח\"א ובספרנו פר' חיי שרה מאמר ג ופרשת וישב מאמר ב ופרשת ויחי מאמר יז ופרשתנו מאמר ח), וא\"כ מה ענין התנאי בברכה זו, הפועלת רק אחר ביאת המשיח ובנין בית שלישי.","b":false},{"t":"ואולי י\"ל דהתנאים הם לעצם השגת הזמן שיהיה ראוי לקיום ברכה זו. דהיינו ביאת המשיח ובנין המקדש, דכבר כתבתי (שם) בשם רבינו הקדוש בעל אור החיים ז\"ל וזיע\"א, דהגאולה תלויה אך ורק במצות עסק התורה כמו שכתב (שמות כז, כ), שהגאולה האחרונה שהיא הגאולה הד' היא בזכות משה רעיא מהימנא, ולזה נתארך הגלות, כי כל עוד שאין עוסקים בתורה ובמצות אין משה חפץ לגאול עם בטלנים מן התורה וכו'. ע\"ש. ועל כן אמר, הקל קול יעקב שצריך לחזק קול התורה, שהוא העיקר ובו תלויה הגאולה דוקא, ובזה יזכו לגאולה השלימה ותתקיים הברכה הזו, אבל אם ח\"ו יקל קול יעקב, אז ח\"ו מתגברים ידיו של עשו, רח\"ל. וכן כתב האוה\"ח הקדוש בפרשת ויחי (בראשית מט, יא), על הפסוק כיבס ביין לבושו, כלומר, איך האדם מכבס ומטהר את עצמו ומזכך את נפשו, הוא ע\"י לימוד התורה, והוא כיבס ביין לבושו שמכבס ומטהר את גופו ע\"י התורה הק' הרמוזה ליין. ואם לא יחפוץ בלימוד התורה כי אז יסבול מאד ח\"ו ויתקיים סוף הפסוק ובדם ענבים סותה, דהיינו ביסורים. וכתב שם, וז\"ל, כי אם יגיע זמן הגאולה, ולא ימצא יין, פירוש שאין בנו תורה, תהיה הגאולה באמצעות עול ותוקף הגלות אשר יצירון האומות לישראל, כאמרם ז\"ל (ראה סנהדרין צז, ב ובירושלמי ריש תענית), כי כשיגיע קץ הנחתם ולא יהיה בישראל זכות לגואלם, יעמיד להם מלך קשה כהמן וכו', [ע\"ש בדבריו הנפלאים הבאתים בהקדמה הנז']. וזהו, הקול קול יעקב, שבאחת מאלו תתקיים ברכה זו, או ע\"י התורה שקול יעקב יגדל ויתחזק כראוי, או ח\"ו ע\"י ידי עשו שיצירון להם וכו', וכמ\"ש האוה\"ח הק' ז\"ל. נמצא שזה תנאי לעצם השלמת הגאולה וביאת המשיח, שבו תלוי קיומה של הברכה הראשונה וכנ\"ל. והכל רמוז באות וא\"ו, שבזה תלוי השלמת פדותנו וגאולתנו השלמה שתהיה גאולה מלאה וא\"ו. כי תיבת \"גאולה\" מלאה וא\"ו עולה בגימט' מ\"ה, וזה שאומרים בתפילת העמידה, \"ומהר לגאלינו גאולה שלמה למען שמך\", ונדפס בסדורים שלנו בזה\"ל, יכוין יו\"ד ה\"א וא\"ו ה\"א שעולה מספר גאולה. והיינו שיכוין בשם הוי\"ה דאלפי\"ן העולה בגימטריא מ\"ה, ולהנ\"ל אתי שפיר דגם גאולה מלאה וא\"ו עולה מ\"ה.","b":false},{"t":"ובזמנו אמר לי הגה\"ק רבי ינון חורי זללה\"ה וזיע\"א, דזה רמוז בתיבת \"שְׁלֵמָה\", שהגאולה מלאה וא\"ו, והיינו שלמה, וגם שלמה היא מתחלקת לשנים ויוצא תיבות ש\"ל מ\"ה, שתלויה בהוי\"ה דאלפי\"ן העולה מ\"ה.","b":false},{"t":"וכבר ביארתי בהקדמה ההיא שהאות וא\"ו היא רומזת לתורה שבה תלויה גאולתינו, ועל כן בגאולת מצרים נאמר (שמות ח, יט), ושמתי פדת (חסר וא\"ו), בין עמי ובין עמך למחר יהיה האות הזה. דבגאולת מצרים לא היה וא\"ו, שעדיין לא ניתנה לנו תורה, וע\"כ כתוב פדת בלי וא\"ו, כי עיקר הגאולה היא בעבור התורה הקדושה, אבל למחר יהיה האות הזה, כלומר תהיה האות וא\"ו במקומה ותושלם הפדות בגאולה של מחר, כי תהיה פדות מלאה, כדכתיב (תהלים קיא, ט), פדות שלח לעמו ציוה לעולם בריתו. ושו\"ר שכ\"כ בספר הקדוש של\"ה (חלק תורה אור פרשת בא), בשם דורשי רשומות. ע\"ש. ויה\"ר שברית עולם תהיה לנו בעה\"ו בב\"א.","b":false},{"t":"[א\"ה - וראה דבר פלאי בדברי רבנו אפרים ז\"ל, הנד\"מ לסדר ויחי שביאר למה פרשת ויחי סתומה, וכתב כי היא מחוברת עם הפסוק שלמעלה שנאמר (בראשית מז, כז), על בני ישראל שהיו בארץ גושן ויאחזו בה ויפרו וירבו מאד, \"מאד\" בגימ' מ\"ה, כי מ\"ה ימים יש בין משיח אפרים למשיח בן דוד. ואחר \"מאד\" ימים שיהרג משיח בן אפרים, אז \"ויחי יעקב\", ויבא משיח בן דוד ויחיה אותו ואת כל עמו שנהרגו עמו, וזה שאמר הכתוב (חבקוק ב, ג), אם יתמהמה חכה לו, אותיות יתמה מ\"ה ימים חכה לו, ולמחרת שהוא יום מ\"ו יבא משיח בן דוד ועמו לעזור לו, וזה שאמר יהודה אתה יודות אחיך \"יודוך\" בגימ' מ\"ו, ולכך אנו מתפללין מ\"ו ברכות בכל שחרית ושחרית, ולכן מ\"ו אותיות בין יהודה ליהודה, כגון מן אתה יודוך עד גור אריה, ומ\"ו אותיות מן מטרף בני עלית, עד לא יסור שבט מיהודה. עכ\"ד והדברים נפלאים. ולפי\"ז יש לומר ד\"גאולה\" עולה בגימ' מ\"ה, והיא גאולה ראשונה של משיח בן יוסף, אך עם הכולל שהיא בגימ' מ\"ו היא גאולה שלמה, בביאת משיח בן דוד, ובזה יתבארו עוד דברי הרי\"ח הטוב ז\"ל דלעיל בענין מילוי שם הוי'ה דיודי'ן. ויה\"ר שנזכה בקרוב לגאולה השלמה, יראו עיננו וישמח לבנו אכי\"ר. יבח\"ר].","b":false},{"t":"(מוצש\"ק ויצא התשנ\"ב)","b":false}]},{"id":"14","t":"שם \"האלהים\" הוא שם שם של רחמים","p":[{"t":"וְיִתֶּן לְךָ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ וְרֹב דָּגָן וְתִירשׁ: (כז, כח)","b":true},{"t":"שמעתי דרבינו האר\"י זללה\"ה כתב (א\"ה – עי' שער הפסוקים פרשת תולדות דאי' שם דהאלהים הוא בינה עילאה, והנה מהבינה דינים מתערין, וכיון שהוא בחינת \"בינה עילאה\" אפשר דהוא רחמים. יבח\"ר), דכשכתוב שם \"אלהים\" לבד, אזי היא מדת הדין, אבל כשנכתב \"האלהים\" הוא רחמים, דע\"י תוספת ה', נעשה חשבונו תשעים ואחת, כמו הוי\"ה אדנו\"ת העולים יחד צ\"א כמו אמ\"ן שזה מורה על מיתוק הדין. [א\"ה - לכאו' מקרא מלא הוא (מ\"א יח, לט), ה' (הוי'ה), הוא האלהים היינו ששם הוי\"ה נחשב כשם \"האלהים\" כשהוא בתוספת ה\"א. יבח\"ר].","b":false},{"t":"וי\"ל בס\"ד, דעי\"ז הברכה גדולה יותר, דמלבד שדינים ממותקים, הם גדולים יותר מרחמים פשוטים, והדבר מבואר פעמים רבות בכתבי האר\"י ז\"ל, הנה יש כאן ענין מיוחד, שבא יצחק לברך את יעקב בברכה העומדת בכל זמן ובכל מצב.","b":false},{"t":"כי אם היה מברכו יצחק בשם הוי\"ה שהוא מדת הרחמים, אזי הברכה היתה חלה רק בעת המתאימה, אבל עתה שבירכו יצחק גם במדת הדין, יש נצחיות לברכה הזאת, כי המתיק לו את מדת הדין, וזה שרש ברכתו אליו, שגם כשיהיה הדין מתוח, יתמתק עליו בחסד ובחמלה, וכשהברכה באה משם, שוב אין עוררין עליה, ואולי זו היא כונת הכתוב (תהלים סז, ב), אלהים יחננו ויברכנו יאר פניו אתנו סלה, היינו, דאם מצד אלהים תבא ברכתנו, אזי מובטחת הארת פניו אלינו סלה.","b":false},{"t":"ועפי\"ז יובן היטב מה שאמר משה לישראל בעת מתן תורה, כשהם פחדו ונתיראו ואמרו אל משה (שמות כ, טז), דבר אתה עמנו ונשמעה ואל ידבר עמנו אלהים פן נמות. ומשה ענה להם (שם שם, יז), אל תיראו כי לבעבור נסות אתכם בא האלהים, ובעבור תהיה יראתו על פניכם לבלתי תחטאו. ולכאורה קשה מאי קאמר להו משה אל תיראו כי לבעבור נסות אתכם בא האלהים וגו', והלא זה עצמו הוא פחדם, שאמרו לו ואל ידבר עמנו אלהים, וא\"כ במה משה נותן מרגוע לנפשם בתשובתו.","b":false},{"t":"אמנם לפי מה שנתבאר אתי שפיר, כי בעת ששמעו ישראל את הקולות וכו', נתיראו מאד, בחשבם שאלו הן גבורות קשות והיינו שאמרו ואל ידבר עמנו \"אלהים\" שהוא מדת הדין. אבל משה רבינו ענה להם, שלא יפחדו, כי אכן הן גבורות, אבל הן ממותקות, וזהו בא \"האלהים\" שנוספה אות ה' על אלהים, ואז נתמתקו הגבורות, ואין להם מה לירא עוד (וראה מה שנתבאר עוד באורך בפרשת ויחי מאמר י).","b":false},{"t":"והכא נמי יצחק אבינו בירך את יעקב ואמר לו, ויתן לך \"האלהים\" שהוסיף אות ה\"א על אלהים, ונתמתקו כל הדינים. שהם ממותקים. ואולי לזה הקדים יעקב ומיתק את הדין, בנותנו מים ליינו של יצחק, דארמי ליה מיא ביינא למתק את הגבורות, כדאיתא בזוהר (פר' בלק ח\"ג קפט, א). וכנ\"ל (פרשתנו מאמר ט).","b":false}]},{"id":"14","t":"אפי' רשעי ישראל יש בהם ריח טוב של מעשים טובים","p":[{"t":"וַיִּגַּשׁ וַיִּשַּׁק לוֹ וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה': (כז, כז)","b":true},{"t":"והנה מצינו לרבותינו שאמרו (ראה סנהדרין לז, א וראה בילקו\"ש בראשית רמז קט\"ו), וירח את ריח בגדיו, אל תקרי בגדיו, אלא בוגדיו וכונתם לומר, דאפילו בוגדים ורשעים שבישראל יש בהן ריח טוב של מעשים טובים.","b":false},{"t":"ושמעתי בשם דורשי רשומות, ששואלים, דאם הכונה היא לבוגדיו, א\"כ למה נאמר בגדיו וצריכים לדרוש, אל תקרי בגדיו וכו' והיה לו לומר מיד וירח את ריח בוגדיו.","b":false},{"t":"ותירצו, שרצו רבותינו לומר, שראה יצחק אבינו ע\"ה, שאפילו בוגדיו דיעקב, הם לא בוגדים במהותם, אלא רק בבחינת \"בגדיו\", כלומר, שהבגידה אינה אצלם כדבר מהותי, אלא בבחינת בגד חיצוני, שאפשר לפושטו, והיינו שאע\"פ שבאה להם השפעה רעה מזרים, הרי מיד יכולים לפשוט מעליהם את בגדי החטא, ולהיות זכים וטהורים כבתחילה, וכאומרם (ע\"ז י, ב ושם יז, א), יש קונה עולמו בשעה אחת. ונעשים מיד כבריה חדשה ממש. וכשראה יצחק אבינו כי כך הוא זרעו של יעקב, מיד \"ויברכהו\".","b":false},{"t":"ודע לך כי ישראל כולם קדושים ואפילו אם ימצאו בהם אנשים עוברי עבירה ח\"ו, מכל מקום, מהותם היא אך טוב וחסד.","b":false},{"t":"והן היום בימינו, עדים כולנו לכך, כשרואים בעינינו רבבות אלפי ישראל, שמסירים מעליהם את כל אותם בגדים צואים, ומשליכים אחרי גיום את כל ההשפעות הרעות, ולובשים בגדי יקר לכבוד ותפארת, ומתעטרים בעטרת תורה ומצוות, וברוח נכון, ונתקיים בהם מאמר חז\"ל (ברכות לד, ב וסנהדרין צט, א), במקום שבעלי תשובה עומדים, אין צדיקים גמורים יכולים לעמוד בו.","b":false}]},{"id":"14","t":"איך ישראל נוטלין שכר בעוה\"ז","p":[{"t":"וְיִתֶּן לְךָ הָאֱלֹהִים מִטַּל הַשָּׁמַיִם וּמִשְׁמַנֵּי הָאָרֶץ וְרֹב דָּגָן וְתִירשׁ: (כז, כח)","b":true},{"t":"ובפירש\"י ז\"ל כתב, ויתן לך האלהים. מהו האלהים? בדין, אם ראוי לך יתן לך ואם לאו לא יתן לך. אבל לעשו אמר, משמני הארץ יהיה מושבך (בראשית כז, לט), בין צדיק בין רשע יתן לך. וממנו למד שלמה כשעשה הבית סידר תפלתו, ישראל שהוא בעל אמונה ומצדיק עליו הדין לא יקרא עליך תגר, לפיכך, ונתת לאיש כדרכיו אשר תדע את לבבו (מ\"א ח, לט). אבל נכרי מחוסר אמנה, לפיכך אמר ואתה תשמע השמים וגו', ועשית ככל אשר יקרא אליך הנכרי, בין ראוי בין שאינו ראוי תן לו, כדי שלא יקרא עליך תגר. עכ\"ל. וכ\"כ בעלי התוספות בספר דעת זקנים. ע\"ש.","b":false},{"t":"מתבאר מן הדברים, כי עם ישראל אינם זוכים למשמני הארץ בכל מצב, אלא בזמן שהם עושים רצונו של מקום. אמנם הגוי תמיד זוכה למשמני הארץ, וזאת כדי שלא יקרא תגר על הנהגת הי\"ת.","b":false},{"t":"וכן הוא בארצות, כי כל הארצות מקבלות את הראוי להם ללא תנאי, אך לא כן ארץ ישראל, ארץ אשר עיני ה' אלהיך בה וגו' (דברים יא, יב), ולפי ראות עיניו במעשי יושביה, כן תקבל שפע מלמעלה.","b":false},{"t":"והדבר מופלא ותמוה, יציבא בארעא וגיורא בשמי שמיא. וכי רק בשביל שלא יקרא הגוי תגר יקבל משמני ארץ וכו', והגם שאינו ראוי לכך. ואילו ישראל שהם בניו ועבדיו של הי\"ת (ראה קדושין לו, א), לא יזכו לברכה אלא בהיותם ראויים.","b":false},{"t":"ובמקום אחר (ראה פר' וישלח מאמר ב') פירשתי בס\"ד, דאחר שיעקב ועשו התחלקו ביניהם, ויעקב בחר לו לחלקו את העוה\"ב, ועשו בחר לו את חיי העוה\"ז (ראה תנדא\"ז פי\"ט), הרי מעתה אין לנו חלק ונחלה בזה העולם, וכבר שאלו כת הקודמין (וראה בנפש חיים למרן החבי\"ף מערכת היו\"ד אות נ' שהביא קושיא זו, והביא על זה ששה עשר תירוצים, ע\"ש), היאך אנו נהנים מן העוה\"ז שאינו שייך לנו, ותירצו דכיון שאנו לומדים תורה, ובזה מקיימים את העולם, דהא כתיב (ירמיה לג, כה), אם לא בריתי יומם ולילה, חוקות שמים וארץ לא שמתי, ע\"כ יש לנו חלק בעוה\"ז, כדי שנוכל להתקיים ולעסוק בתורה, אשר בלעדיה אין קיום לעוה\"ז כלל. והלומד תורה נצרך לכדי חיותו מן העולם כמאמרם (אבות ג, יז), אם אין קמח אין תורה.","b":false},{"t":"[א\"ה - ויותר אפשר להוסיף, דישראל ע\"י לימוד התורה מצילין את העוה\"ז מחורבן, ולולי הם היה נחרב העולם, והן קי\"ל (ב\"מ כד, א), המציל מזוטו של ים ומשלוליתו של נהר הרי אלו שלו, והיינו שמה שמציל הוא שלו, כי זכה בו. ועוד שיש ללומד תורה דין מבריח ארי מנכסי חבירו, שעכ\"פ כשהוא מדעת יש ליתן לו שכר (עי' היטב ב\"ק נח, א), ולכן נוטלין ישראל שכרן בעוה\"ז. אבל כל זה דוקא כשלומדים תורה ומקיימים מצוות אבל אם לא עשו כן לא מגיע להם כלום, כי אין העוה\"ז חלקם, ודוק.","b":false},{"t":"ובאמת שבספר היקר זקוקין דנורא וביעורין דאשא על תנד\"א (סא\"ז פי\"ט, כתב לבאר דזה היה מאמר עשו ליעקב (בראשית לג, ה), מי אלה לך, ופירש\"י מי אלה להיות שלך. דהיינו שאין מגיע לך כל הכבוד והעושר הזה, דהא העוה\"ז שלי הוא ולא שלך. ויעקב אבינו השיבו (שם), הילדים אשר חנן אלהים את עבדך, וביאר הרב הנ\"ל דיעקב כיון בזה לומר, דלקח לעצמו רק ההכרחי ביותר לעבודת הי\"ת ואינו נוטל יותר. ובזה ביאר ההיא דאמרו רבותינו (ע\"ז י, ב), דאנטונינוס היה שולח לרבי זהב הרבה ולא רצה רבינו הקדוש לקבל ממנו. דטעם הדבר, משום דאנטוניוס הוא גלגול עשו, ורבינו הקדוש היה גלגול יעקב, וכמו שרמזו לנו רבותינו (שם יא, א), בהדיא על הפסוק (בראשית כה, כג), שני גוים בבטנך, אל תקרי גוים אלא גיים זה אנטונינוס ורבי וכו', ע\"ש. והנה היה תנאי בין יעקב ועשו שיעקב נוטל לו העולם הבא ועשו נוטל העולם הזה, וכיון שרבינו הקדוש הוא גלגול יעקב אבינו ע\"ה לכך מצינו בו (כתובות קד, א), שבשעת פטירתו זקף רבי עשר אצבעותיו כלפי מעלה, אמר, רבונו של עולם, גלוי וידוע לפניך שיגעתי בעשר אצבעותי בתורה ולא נהניתי אפילו באצבע קטנה, יהי רצון מלפניך שיהא שלום במנוחתי, יצתה בת קול ואמרה יבא שלום ינוחו על משכבותם וכו'. והיינו טעמא שנזהר ביותר רבינו הקדוש שלא ליהנות כלום מן העוה\"ז. זת\"ד ודפח\"ח.","b":false},{"t":"ובהורמנותיה אני הייתי מוסיף ומבאר, כי יעקב אבינו אמר לעשו כמענה על שאלתו מי אלה לך, והוא ענה, הילדים אשר חנן אלהים את עבדך, ונקיט \"אלהים\" בדוקא ולא שם הוי\"ה, לומר דעל פי הדין מגיע לו, והוא מברכת ויתן לך \"האלהים\", היינו שזכה בעושר הזה על פי הדין, כיון שהוא צדיק גמור לכך מגיע לו שכר וריוח גם בעולם הזה. ולכן מצינו שעשו אמר ליעקב (בראשית לג, ט), \"יהי לך אשר לך\", ואמרו רבותינו (ב\"ר עח, יא), שהודה לו על הברכות, והובאו דבריהם בפירוש רש\"י ז\"ל שם, והיינו שראה עשו כי חזר יעקב שלם בתורתו ולא נגרע ממנו מאומה בהיותו בבית לבן, כי בתחילה עשו שמח שיעקב ברח לבית לבן, כי אמר לעצמו, אדרבה ילך לו יעקב לבית לבן, ושם ילמד ממעשיו הרעים ותסור ממנו הברכה. וכיון שעשו נתעשר אף הוא, חשב שזאת באה לו, בגלל שיעקב הפסיד את חלקו. ולכן נתירא שיעקב רוצה לחזור לארץ כנען, כי אמר בלבו, עתה יבא יעקב ויחזור לתורתו וצדקתו ואני אפסיד את עושרי לכך יצא לקראתו, ובראותו כי יעקב גם כן עשיר, אז הבין כי לא הלכה הברכה מיעקב והבין שנשאר יעקב צדיק גמור בבית לבן, וממילא הבין כי העושר שלו לא מפני שנסתלקה הברכה מיעקב אבינו ח\"ו. אלא שהיא מהברכה שברכו אביו ג\"כ, משמני הארץ יהיה מושבך (בראשית כז, לט). ולכך לא נתיירא עוד שמא יחסיר יעקב ממנו את עושרו, ולכן אמר לו יהי לך אשר לך. ודוק כי הוא פירוש נחמד. יבח\"ר].","b":false},{"t":"ומכל מה שנתבאר יובן היטב, דעשו אין לו תנאים, ובין צדיק ובין רשע יש לו משמני ארץ וכו', כי העולם הזה שייך לו. אבל יעקב שלקח לו את העוה\"ב, אין לו ברכת העוה\"ז אלא אם הוא ראוי לזה.","b":false}]},{"id":"14","t":"ההכנות לברכה מושלמת","p":[{"t":"וַיֹּאמֶר הַגִּשָׁה לִּי וְאֹכְלָה מִצֵּיד בְּנִי לְמַעַן תְּבָרֶכְךָ נַפְשִׁי וַיַּגֶּשׁ לוֹ וַיֹּאכַל וַיָּבֵא לוֹ יַיִן וַיֵּשְׁתְּ, וַיֹּאמֶר אֵלָיו יִצְחָק אָבִיו גְּשָׁה נָּא וּשֲׁקָה לִּי בְּנִי, וַיִּגַּשׁ וַיִּשַּׁק לוֹ וַיָּרַח אֶת רֵיחַ בְּגָדָיו וַיְבָרֲכֵהוּ וַיֹּאמֶר רְאֵה רֵיחַ בְּנִי כְּרֵיחַ שָׂדֶה אֲשֶׁר בֵּרֲכוֹ ה' וגו': (כז, כה-כז)","b":true},{"t":"מוכרחים לומר שכדי להשיג ברכה מושלמת, צריך ריצוי ופיוס למברך, עד שיהיה רצון מלא לפני המברך, וזהו שאמר לו, \"למען תברכך נפשי\", כלומר לא סתם ברכה, אלא ברכת הנפש, ולזה הדריך יצחק את יעקב כדת מה לעשות. תחילה, \"הגישה לי ואכלה\", ואח\"כ \"ויבא לו יין וישת\", ואז ביקשו יצחק לאמר, גשה נא ושקה לי בני, וכל זה כדי לעורר את אהבת האב על בנו.","b":false},{"t":"ולכן נאמר, ויאמר אליו יצחק אביו, ודקדק לומר \"ויאמר אליו\" ולא \"ויאמר לו\" שאליו הוא לשון ארוך יותר, וכלל בידינו שכל מקום שיש אריכות לשון, אות הוא על גודל הענין יותר ויותר, וזהו אליו, ולא לו, כי נצרך לאהבה עמוקה יותר, ולא סתם ציווי בעלמא. ולכן נזכר בכתוב ויאמר אליו \"יצחק אביו\" להגדיל ענין האהבה. ולכן נמי סיים ושקה לי \"בני\" להראות ולהגדיל אהבת בן לאביו ואב לבנו, כדי שיהא לברכה על מה לחול.","b":false},{"t":"וכן מצינו גם בתחילת הדרך הזו כשפנה יצחק לעשו בתחילה, אמר לו (בראשית כז, ג-ד), ועתה שא נא כליך וגו', ועשה לי מטעמים כאשר אהבתי, והביאה לי ואֹכֵלה, בעבור תברכך נפשי בטרם אמות. והיא היא.","b":false},{"t":"* * *","b":false},{"t":"מיתוק הדינים שעשה יעקב לפני שקיבל את ברכת יצחק","b":true},{"t":"ויש לומר עוד, דבא יצחק ללמדנו את הדרך הנכונה איך למתק את הדינים. שהרי יצחק הוא מדת הגבורה, שאין לגשת אליו מיד לבקש את בקשותיו, אלא בטרם יתפלל, לך יערוך ניבו (מתוך פיוט לרשב\"ג הנאמר בר\"ה), היינו שיש להקדים בדברי פיוס וריצוי לפניו יתברך, ורק אח\"כ יגש להתפלל ולבקש בקשותיו. וכמו שתיקנו לנו חז\"ל את סדר התפלה שמתחילה פותחים בברכות השחר, שהן הודאות ותשבחות על כל סדר הבריאה והתחדשותה דבר יום ביומו, ואח\"כ מזכירים את סדר קרבן התמיד וקטורת של שחר, וסדר העבודה, וכללות הקרבנות, כשהכל חרוז בפסוקים של חן ורחמים. ואח\"כ אומרים הודו לה' קראו בשמו, וה' מלך, וברוך שאמר שהוא כעין ברכה על פסוקי דזמרה, ופסוקי דזמרה, שהן שבחים והודאות מפורסמות שבהם מסתיים ספר תהלים, ואח\"כ שירת הים, וברכת החתימה על פסוקי דזמרה, ואח\"כ ק\"ש וברכותיה, ורק אחר כל זאת מתפללים תפלת שמונה עשרה, שגם היא פותחת בשלוש ראשונות שהן שבחי השם וקדושתו, ובאמצע התפילה מבקשים בקשות, ומסיימים בג' אחרונות שהן הודאות. וכל זה הוא כדי להמתיק את הדינים, בטרם יבקש בקשותיו.","b":false},{"t":"וזהו שאמרו בזה\"ק (פר' בלק ח\"ג קפט, א), על הפסוק (בראשית כז, כה), ויבא לו יין, דארמי ליה מיא ביינא, היינו שהטיל מים שהם חסדים כדי למתק את הגבורות שהוא היין. ויבא לו וישת. והוא בחינת העלאת מ\"ן (וכמבואר בלקוטי תורה פרשת תולדות), ואז באה התעוררות מלעילא שהוא, ויאמר אליו יצחק אביו, גשה נא ושקה לי בני. ואז הגיע זמן שתברכהו נפשו, ברצון ונדבה. והוסיף ריח טוב, שהנפש נהנית ממנו, וכמ\"ש הספורנו שם (בראשית כז, כז), וירח את ריח בגדיו, להרחיב את נפשו בתענוגות הריח, כאמרם ז\"ל (ברכות מג, ב), איזהו דבר שהנשמה נהנית ממנו, ואין הגוף נהנה ממנו, הוי אומר זה הריח. ויברכהו, כענין והיה כנגן המנגן ותהי עליו יד ה' (מ\"ב ג, טו).","b":false}]},{"id":"14","t":"הגאולה והישועה רק בזכות כח התורה","p":[{"t":"וַיִּגַּשׁ יַעֲקֹב אֶל יִצְחָק אָבִיו וַיְמֻשֵּׁהוּ וַיֹּאמֶר הַקֹּל קוֹל יַעֲקֹב וְהַיָּדַיִם יְדֵי עֵשָׂו: (כז, כב)","b":true},{"t":"ידועים הם דברי הגר\"א ז\"ל מוילנא (מובא בספר דברי אליהו פר' תולדות בשם ספר קול רינה), שדקדק שמילת \"הקל\" הראשונה חסרה וי\"ו, ופירש, שאם הקו'ל נעשה \"קל\" ויש רפיון וקול התורה איננו נשמע ברמה, אז ממילא ידי עשו קמים ח\"ו, אבל אם קולו של יעקב נשמע בבתי כנסיות ובתי מדרשות, והוא קול חזק ומלא וא\"ו, אז אין ידי עשו יכולים לעשות מאומה, ונשברים וכלים מאליהם.","b":false},{"t":"ומה הוא הדבר שהופך את הקול לקל, הוא חסרון האות וא\"ו, וביארתי בכמה מקומות (ראה בהקדמת שו\"ת שמע שלמה ח\"א וובפרשת חיי שרה מאמר ג ובפרשתנו מאמר יג ובפר' וישב מאמר ב ופר' ויחי מאמר יז), על הפסוק (שמות ח, יט), ושמתי פְדֻת בין עמי ובין עמך, למחר יהיה האות הזה, שנכתב \" פְדֻת\" חסר וא\"ו, והוא להורותינו, שאותה גאולה לא היתה שלימה כי לא היה בה כח התורה עדיין, וביארתי כי אות וא\"ו היא בחינת תורה, וזו בחינתו של יעקב ע\"ה \"תפארת\", ועל ידה מתחברים קוב\"ה ואורייתא וישראל, כי התורה היא הדבק המחבר בין ישראל לאביהם שבשמים, וע\"כ נקראת וא\"ו החיבור, ויש תיבות רבות שנהפכים מענין של תורה, לענין של חולין, ע\"י חסרון הוי\"ו, וכמו שמצינו בעפרון שהפסיד את האות וי\"ו משמו, ועי\"כ הפסיד את החיבור שלו מהי\"ת, ולעומתו מצינו ביתרו שמתחילה היה שמו יתר כמו שנאמר (שמות ד, יח), וילך משה וישב אל יתר חותנו, וכשנתגייר ונדבק בשכינה הוסיפו לשמו אות וא\"ו ונקרא יתרו (שמו\"ר כז, ח ומכילתא יתרו פרשה א וראה רש\"י שמות יח, א), וה\"נ \"הקול\" כשהוא מלא וא\"ו, הרי זה מראה על קול תורה ותפלה, בכל תוקפו והדרו, וכשנחסר הוא\"ו, אזי נהפך ונהיה קל.","b":false},{"t":"[א\"ה - עוד יש להוסיף בזה כמה ענינים פלאי פלאות בענין הזה, דע, כי הנה שאל מהר\"ש חכים ז\"ל את מרן החבי\"ף זללה\"ה (ראה ברכת מועדיך לחיים ח\"ב דרוש ג' לפרשת זכור), בההיא דמצינו בפרשת ויבא עמלק (שמות יז, ח-טז), שיש בה ט' פסוקים וכולם מתחילים באות וי\"ו, והלא דבר הוא, ויעו\"ש מה שביאר.","b":false},{"t":"ולהמבואר אתי שפיר, דזה כנגד זה עשה הי\"ת, כח הטומאה למול הקדושה, והנה בפרשת עמלק מצינו ויחנו ישראל ברפידים ואמרו רבותינו (בכורות ה, ב), שריפו ישראל עצמן מדברי תורה, לכך כתיב ויבא עמלק, והיינו שמיד כשנחסרה מהם אות וי\"ו הרומזת לתורה, מיד באה אות וי\"ו דויבא עמלק.","b":false},{"t":"ובאמת שזהו מאבק יעקב ועשו, כדאיתא בספר הקנה, כי \"יעקוב\" מלא וי\"ו, ולעתיד לבא יקח יעקב את הוי\"ו של עשו וישאר מעשו \"עש\" כי עש יאכלנו, וכן כתב רבינו החיד\"א בדבש לפי מערכת וי\"ו אות וי\"ו. ע\"ש. ונמצא זה לעומת זה, אם הוי\"ו אצל יעקב והיא יוצאת בקולו הקול קול עוז בתורת הי\"ת, אז הוא נוצח, ואם ח\"ו היא בחלקו של עשו, אז גובר עשו וכחות הטומאה רח\"ל.","b":false},{"t":"והנה מצינו (תענית ה, ב), אין משיחין בשעת הסעודה שמא יקדים קנה לושט. והנה יעקב אבינו בחינת קנה, שממנו האדם מוציא את הקול המדבר, ובושט מכניס את המזון. ומצינו ברעי\"מ (זוהר ח\"ג רלב, א ועי' שם קכא, ב), כי ה\"ושט\" ע\"י אכילה מתארך ונעשה הוי\"ו לנו\"ן והם אותיות \"שטן\", ואמנם הקנה אין בו אכילה ושתיה אלא קול תורה ועל זה נאמר (ראה משלי ד, ה), קנה חכמה קנה בינה, וע\"י קול יעקב ממיתין לשטנא שיצא מ\"ושט\" שהוא ענין עשו שנא' בו (בראשית כה, ל), הלעיטני נא, וזה לעומת זה עשה הי\"ת. וראה למרן החבי\"ף ז\"ל שהביא שם ובח\"א דרוש א' לס\"ת כמה דברים דשייכי לאות וא\"ו, וצרף לכאן ותראה פלאי פלאות, ואכמ\"ל. יבח\"ר].","b":false}]},{"id":"14","t":"\"תתן אמת ליעקב\"","p":[{"t":"וַיֹּאמֶר יַעֲקֹב אֶל אָבִיו אָנֹכִי עֵשָׂו בְּכֹרֶךָ עָשִׂיתִי כַּאֲשֶׁר דִּבַּרְתָּ אֵלָי קוּם נָא שְׁבָה וְאָכְלָה מִצֵּידִי בַּעֲבוּר תְּבָרֲכַנִּי נַפְשֶׁךָ וגו': (כז, יט)","b":true},{"t":"יעקב אבינו ע\"ה הוא בחינת אמת, והוכתר בכתר האמת, כמו שנאמר (מיכה ז, כ), תתן אמת ליעקב, ויעקב אבינו הוא גם כנגד מדת תפארת וידוע שמדת תפארת קרויה אמת (ראה שער מאמרי רשב\"י פרשת בראשית שמבאר באריכות איך מדת תפארת מכריעה בכל הספירות למעלה בראשן ובסופן ובאמצעיתן, ע\"ש דברים נפלאים), כי מדת תפארת ממזגת בתוכה את שני הקוים ימין ושמאל, ועל כן נאמר (בראשית לג, יח), ויבא יעקב שלם.","b":false},{"t":"והנה יש לשים לב שדוקא יעקב אבינו ע\"ה שנכתר בכתר האמת, הוא היה צריך ללבוש על ידיו את מלבוש עשו (בראשית כז, טו-טז), ולבא לפני אביו יצחק אבינו ע\"ה, ולומר, אנכי עשו בכורך (שם שם, יט). וגם הוא הוא שהיה צריך לקלף את המקלות ולהעמידם בפני צאן לבן הארמי, בעת אשר תיחמנה הצאן (ראה בראשית ל, לז-מג), ועוד כהנה רבות. וצריכים להבין מה פשר הענין, ולמה דוקא לאיש שאליו נזדמנו כל כך הרבה נסיונות בענין הזה והיה מהלך על חבל דק מאד בענינים האלו, דוקא הוא הנקרא איש האמת.","b":false},{"t":"ויש ליישב את זה עפ\"י מה שאמרו רבותינו ז\"ל (סוכה נב, א), כל הגדול מחבירו יצרו גדול הימנו, ודייקו לומר \"גדול הימנו\", כלומר דנותנים לאדם יצר גדול כפי גדולתו בכשרון ובחכמה, וכן מעמידים לו יצר מיוחד ונסיונות מיוחדים כפי בחינת נשמתו, דאם הוא גדול במיוחד בתחום מסויים, אז בזה מנסים אותו במיוחד. כי תכליתו לתקן אותה מדה, ולכן הוא נבחן באותה המדה דוקא.","b":false},{"t":"[א\"ה – וראיתי רמז נפלא על זה בספר בן ישכר, שכ' על הפסוק (תהלים קמז, טז), הנותן שלג כצמר כפור כאפר יפזר. דידוע שאם נותנים אפר על השלג והקרח הרי הוא ממיסו. וזה אומרו הנותן שלג, לפי מה הוא נותנו, לפי הצמר שיש לאדם להתכסות. כפור כאפר יפזר, כמו כן הוא נותן כפור לפי מדת האפר שיש ביד האדם, והיינו כי אין הקב\"ה בא בטרוניא עם בריותיו, ונותן להם נסיונות רק כפי הדרגה שלהם, והדבר ברור שאין הקב\"ה נותן נסיון אא\"כ יוכל האדם לעמוד בו. ולכן ככל שהאדם גדול יותר גם הנסיונות גדולים יותר.","b":false},{"t":"וראיתי להגאון מהריא\"ז ענזיל בהקדמתו לספר אבני מילואים שהביא בשם מורו הרב ז\"ל בשם מערכות אלקות, לבאר את טעם ענין כל הגדול מחבירו יצרו גדול ממנו, וז\"ל, מפני שאין דומה מי שיש לו פת בסלו למי שאין לו, וכל אשר הרוח יותר כלוא ומסוגר בו, יתאמץ ויתפעל ביתר עוז להרוס גדריו לצאת חוצה. לכן מי שאוחז בדרכי התורה לבלתי התגאל בחמדת התאוה, אין לו פת בסלו להשקיט את יצרו, כי כמעט נמנע הוא אצלו לעשות תועבה, על כן היצר הרע מתגבר עליו, וכח התאוה העצור בקרבו מתעורר ומתחזק לצאת אל הפועל. לא כן מי שאינו צדיק שיש ליצה\"ר פת בסלו, שהרי בידו להטותו אל אשר יהיה שמה רוח התאוה ללכת, ואחר שאינו כלוא ממילא אינו מתגבר לצאת, וכ\"כ התוספות בפ\"ק דקידושין (לא, א ד\"ה גדול), בהא דא\"ר חנינא, גדול המצווה ועושה וכו', דמי שאינו מצווה יש לו פת בסלו שאם ירצה יניח. ע\"ש. ואמנם ידוע כי ההרגל יבוז להנאות המתמידות ולא ינעמו לאדם תענוגי הזמן אם יום יום ישקוד עליהם, על כן מסגולת כח התאוה ותחבולותיו להתחדש בכל יום, כנודע דרכי שכורי יין חמדת הזמן יחפשו חפש מחופש חדשים לבקרים, להמתיק למו רגבי נחל עדניהם וכו', ע\"ש. יבח\"ר].","b":false},{"t":"וע\"כ אברהם אבינו ע\"ה שהיה בחינת חסד, נוסה בעקידת בנו יחידו אשר אהב יותר מנפשו, שזה היה נסיון מיוחד לבעל החסד, שמרחם על רחוקים וזרים ומפרנסם ודואג להם, ועומד ומתפלל במסירות נפש על אנשי סדום ועמורה שהם רעים וחטאים לה' מאד, וכאן מנסים אותו בבנו יחידו אהובו שיעלהו לעולה. וכן נוסה בנסיון של ישמעאל, שאמרה לו שרה גרש את האמה הזאת ואת בנה (בראשית כא, י), והי\"ת אמר לו, כל אשר תאמר לך שרה שמע בקולה (שם שם, יב), והוצרך לשלוח את שניהם, ועוד כהנה רבות.","b":false},{"t":"כמו כן ניסו את יעקב איש האמת בענינים דקים מאד שבין אמת לשקר, ורק אחר שעמד בנסיונות אלו, אז ניתנה לו מדת האמת, שנאמר (מיכה ז, כ), תתן אמת ליעקב. ונגזר עליו לחיות בצל לבן הארמי ראש בית אב לרמאים, והיה נאלץ ללכת בדרכים מיוחדות כדי להשיג את המגיע לו, ובתוך כל זה לשמור את עצמו שלא ישנה מן האמת בשום פנים, ואפילו כחוט השערה, עד שהיה יכול להעיד על עצמו לבסוף באומרו ללבן, (בראשית לא, לז), כי מששת את כל כלי מה מצאת. ואמרו רבותינו במסכת עבודה זרה (ג, א), יבא לבן ויעיד על יעקב אבינו שלא נחשד על הגזל, ופירש\"י ז\"ל שם, וז\"ל, שלא נחשד על הגזל - דכתיב מה מצאת, מכל כלי ביתך, אפילו סכין אפילו הימנק אפילו מחט, והחתן הדר בבית חמיו עשרים שנה, כשיוצא אינו נוטל עמו כלי קטן, ובני נח נצטוו על הגזל ויעקב קיים. וראינו בזה את גדלותו של יעקב אבינו ע\"ה, שאפילו מחט לא נמצאה אצלו משל לבן, למרות שהיה חמיו, וגר עמו יחד עשרים שנה, ועבד אצלו כל אותם שנים, ולבן החליף את משכורתו עשרת מונים, והיו לו היתרים רבים, לקחת מממונו של לבן, ועם כל זה מעידה עליו התורה הקדושה, שלא נמצא מאומה בידו, מכל אשר ללבן.","b":false},{"t":"וכן מצינו שיעקב אבינו ע\"ה נתנסה בענין הבכורה והברכה, אשר שניהם יחדיו היו שייכים לו, והיה צריך להאבק על כל אחת מהן מאבק גדול, ולעבור על אותו שביל דק המפריד בין האמת ובין השקר, ולא להכשל ועוד כהנה רבות. ורק אחר שעמד בכל אלו אז ניתנה לו האמת והוכתר בכתרה.","b":false},{"t":"(בעזהית\"ש ט\"ז טבת התשמ\"ח, מתוך דרשה שדרשתי בשבת וישב בביהכנ\"ס ע\"ש הרי\"ף בליל שבת).","b":false}]},{"id":"14","t":"מדוע זימנו מהשמים שיצחק יברך את יעקב בחשבו שהוא עשו","p":[{"t":"וַיְהִי כִּי זָקֵן יִצְחָק וַתִּכְהֶין עֵינָיו מֵרְאֹת וגו': (כז, א)","b":true},{"t":"חזות קשה ראיתי בדעת זקנים מבעלי התוספות, שכתבו, ותכהין עיניו מראת, משום שאהב את עשו כי ציד בפיו, וכתיב (שמות כג, ח), כי השחד יעור. דבר אחר, כדי שיבוא יעקב ויטול את הברכות וכו', עכ\"ל [ובאמת שהדברים הללו נכתבו בעוד מקומות, והובאו נמי בדברי רבינו בחיי ז\"ל, ומקורם בב\"ר סה ה-ז, וכ\"ה בתנחומא סדר תולדות פ\"ח, ברם הדברים קשים עד מאד להבין].","b":false},{"t":"ואמנם רש\"י ז\"ל (בראשית כז, א), פירש, שכהו עיניו של יצחק בעשנן של נשי עשו, שהיו מקטירות לע\"ז. דבר אחר, כשנעקד יצחק על גבי המזבח והיה אביו רוצה לשחטו באותה שעה נפתחו השמים וראו מלאכי השרת, והיו בוכים, וירדו דמעותיהם ונפלו על עיניו, לפיכך כהו עיניו. דבר אחר, כדי שיטול יעקב את הברכות, עכ\"ד רש\"י ז\"ל.","b":false},{"t":"והנה בעלי התוספות שם, לא ניחא להו בפירושו של רש\"י ז\"ל, שפירש שכהו עיני יצחק משום נשי עשו שהיו מקטרות לעבודה זרה, דא\"כ קשה למה לא כהו גם עיני רבקה, דהא כתיב (בראשית כו, לה), ותהיין מורת רוח ליצחק ולרבקה, ויעו\"ש בדברי בעלי התוספות שהביאו ממדרש תנחומא (פ\"ח), משל למה הדבר דומה, למקיש כלי עצם בכלי חרש, הכלי חרש משתבר, אבל מי שמקיש כלי עצם לכלי עצם, אין משתבר זה מזה. כך יצחק, נברא מן האדמה, לכך הזיקו לו מעשה כלותיו שנבראו מן הצלע, אבל רבקה שנבראה מן העצם כמו כן, לא הזיקו לה מעשי כלותיה, יעו\"ש.","b":false},{"t":"והרב כלי יקר שם כתב, וז\"ל, ויהי כי זקן יצחק ותכהין עיניו מראות. לא הזכיר לשון בא בימים, לפי שלשון בא בימים משמע, שאור שכלו היה הולך וגובר כדרך זקני ת\"ח שאור שכלם מוסיף והולך ביותר לעת זקנתם, וכאילו הם באים מן הלילות אל תוך הימים, כמבואר למעלה פרשת חיי שרה בפסוק ואברהם זקן בא בימים (בראשית כד, א). על כן אמר כאן אצל יצחק שאפילו לעת זקנתו תכהין עין שכלו מראות בתחבולות עשו, שהרי טעה בו והיה סבור שהוא צדיק, כי לא הרגיש ברמאותו, על כן לא נאמר בא בימים, כי אדרבה הלך חשיכים ואין נוגה לראות במראות האמת, בעניני הנהגת עשו בנו. ואולי על זה פירש\"י, ותכהין בעשנן של אלו, וכי ס\"ד שיצחק ראה אותן מקטירים לעבודה זרה ולא מיחה בם, כי אברהם היה מדקדק שלא להכניס ע\"ג, ובודאי היה יצחק נזהר בעבודה זרה כמותו, אלא ודאי שהיה יצחק סבור שהם מקטירים לשמים, ע\"כ אמר מיד אחר ותהיין מורת רוח ליצחק ולרבקה, ויהי כי זקן יצחק ותכהין עיניו, שלא היה רוחם נוחה ממעשיהם כי אע\"פ שאמרו שהם מקטרות לשמים מ\"מ לא היה רוחם נוחה ממעשיהם, כי חשדום שמא הם מפגלים הקרבן ע\"י איזו מחשבה זרה וכו'. עכ\"ל. ודבריו אלו נפלאו ממני לא אוכל להבינם, ואי לאו דמסתפינא הוה אמינא, דלא מהכלי יקר יצאו דברים אלו, אלא ידי זר נשתלחו בם, ובפרט בניסוח הדברים.","b":false},{"t":"והעיקר הוא דברי חכמינו ז\"ל במדרש תנחומא (פ\"ח), שהובאו ברש\"י ז\"ל, וגם בדברי בעלי התוספות, וגם הכלי יקר הביאם בסוף דבריו שם, שמאת ה' היתה זאת כדי שיעקב יטול את הברכות. וע\"ע בדברי הספורנו שם.","b":false},{"t":"אלא שצריכים אנו להבין דברי חכמים וחידותם, דאחר שרצונו יתברך שיעקב יטול את הברכות, וכפי שכן היה בסוף הענין, ועצת ה' היא תקום, וכן מפורש בתרגום יוב\"ע על הפסוק (בראשית כז, ה), ורבקה שומעת בדבר יצחק אל עשו וגו', תירגם ורבקה שמעת ברוח קודשא וכו', ועוד כתב שם (פסוק ו'), ורבקה אמרת ליעקב ברה למימר, הא ליליא הדין עילאי משבחין למרי עלמא, ואוצרי טלין מתפתחין ביה, ושמעית ית אבוך ממלל עם עשו אחוך למימר.","b":false},{"t":"וראה בפירושו של רבינו בעל אוה\"ח הקדוש זיע\"א (בראשית כז, ה), שכתב, ורבקה שומעת, פירוש מודיע הכתוב, כי רבקה נביאה היתה, ושומעת תמיד בדברי יצחק וגו', הגם שלא ידבר בפניה והבן וכו', וע\"ש בהמשך דב\"ק. ומכל זה פשוט וברור דמהשמים רצו שיתברך יעקב לבדו, וכן היה באמת.","b":false},{"t":"אלא שלפי כל המבואר קשיא טובא, דלמה לא יגלה ה' את דברו אל עבדו נביאו, יצחק אבינו ע\"ה, כאשר גילה לרבקה אמנו ע\"ה. ולמה הוצרך להכהות את אור עיניו של יצחק קדוש ה', כדי שיעקב יטול את הראוי לו, והיה אפשר לגלות את אמיתות הענין ליצחק אבינו ע\"ה, והוא היה קורא לבנו ליעקב ומברכו בשקט ובשלוה. וכל המתבונן בדברי רבותינו יסיק שכונת חז\"ל בדבריהם ללמדנו שמן השמים הטעו את יצחק, כדי שירצה לברך את עשו דוקא, והי\"ת כיוון את כל הדברים שבסופו של דבר יבא יעקב ויטול את הברכות.","b":false},{"t":"ובדרך פשוטה אמרתי בס\"ד, שמאת ה' היתה זאת, לטובתנו ולתועלתנו, שאם היה יצחק אבינו ע\"ה מברך את יעקב, מתוך הכרה וידיעה שאת יעקב אבינו הוא מברך, היה קשה לנו למשוך להשיג ברכות אלו בעבורינו. שכן, המקטרגים היו מעכבים ואומרים, יעקב הוא שהתברך ואעפ\"י שגם זרעו בכלל, אמנם הברכה חלה על זרעו רק אם הוא כיוצא בו, בתורה ובעבודת ה' בשלמות ובמסירות, אבל אם אינם כיוצא בו, לא יהיו זכאים לקבל את הברכות ח\"ו.","b":false},{"t":"אבל עתה שהקב\"ה הטעה את יצחק אבינו ע\"ה, והעלים ממנו את האמת, ובשעה שהיה מברך את יעקב, דעתו היתה על עשו בנו בכורו, יש לנו פתחון פה לסתור טענות המקטרגים ולפרוך אותם. כי אעפ\"י שלא הגענו עד מדרגתו של יעקב אבינו ע\"ה, על כל פנים טובים אנחנו שבעתים מעשו והמונו, ואם אליו התכוין יצחק בברכתו, בודאי שאנו ראויים והגונים לקבל את הברכה, ולכן מגיעה לנו הברכה בכל מקרה. ובאמת מצינו ביצחק כשנודע לו שבירך את יעקב ולא את עשו, שלא חזר בו מתנאי הברכה ואמר (בראשית כז, לג), \"גם ברוך יהיה\", היינו שישארו בו אותם תנאי ברכה שבירכו על דעת שהוא עשו, ולא נתן תנאים חדשים בברכתו, גם אחר שנודע לו שהוא יעקב.","b":false},{"t":"כי לא ינוח שבט הרשע על גורל הצדיקים","b":false},{"t":"עוד יש לומר, דידוע שיעקב ועשו התחלקו ביניהם, ויעקב אבינו ע\"ה לקח את העולם הבא לחבלו ונחלתו, אמנם עשו התאוה לעוה\"ז, וביקשו לעצמו (כמבואר בתנדא\"ז פי\"ט), והנה ברכות יצחק נאמרו על העולם הזה, ואם היה יצחק מברך את יעקב בשופי ולכתחילה, כי אז הסטרא אחרא וחילותיה היו מחריבין את העולם, ולא נותנים בשום אופן ליצחק לברך את יעקב, ויש להם כח לזה, אשר בא להם מכחו ורצונו של הקב\"ה, שהוא יוצר אור ובורא רע, וזה לעומת זה עשה אלהים, והם חיים ופועלים ג\"כ מכחו יתברך, שנאמר (נחמיה ט, ו), ואתה מחיה את כולם, ואין רשות אחרת ח\"ו, כי אפס זולתו ואין בלתו. והם ג\"כ צריכים לעולם לפי התכונה שבה ברא הבורא את עולמו. ויש להם גם רשות להלחם ולהפריע לכל דבר שבקדושה. וא\"כ בודאי שהיו מנסים בכל כחם להפריע ליצחק שלא יתן את הברכה המיוחלת ליעקב.","b":false},{"t":"אמנם הי\"ת עוזר לבניו אהוביו, ומבלבל את הסט\"א וחילותיה לבל ינוח שבט הרשע על גורל הצדיקים, ומבלבל אותם לגמרי, כדי שלא ייעבטון אורחותם, ולא יעוותו נתיבות עולם, וכאשר נאמר באיוב (יב, כג), משגיא לגוים ויאבדם וגו', כלומר, שהי\"ת מטעה אותם ומבלבל את דעתם, לאבדם ולהכותם לפי הצורך להם, וכן מצינו בענין עמון ומואב שמהם יצאו רות המואביה ונעמה העמונית, ומהם בא יבא המשיח (ראה ב\"ק לח, ב), וכן מתמר שבאו ממנה פרץ וזרח, וכל הרואה את הענין ההוא תמה מדוע הי\"ת זימן את הענינים שיהיו דוקא בצורה ההיא הנראית כלא הגונה לקדושי עליון כאלה, אך הענין הוא בא במכוון בדרך ההיא כדי להסיח את דעת הסט\"א מן הענין. וכן ראינו במצרים בזמן שקדם להולדת משה רבינו ע\"ה, איך נרעש כל העולם, ופרעה התחכם בכל כחותיו וכחות חכמיו עד שגילו את היום בו יולד מושיען של ישראל, ולכן גזר פרעה הרשע כל הבן הילוד וגו' (שמות א, כב), והצליח לעקוב אחר כל בנות ישראל לדעת מתי יבא עת לדתן, ועוד כהנה וכהנה פלאות מהתחכמותו, עד שהסטרא אחרא, חשבה שבאמת אין סיכוי למושיען של ישראל להולד ולהתקיים, ועמרם וכל ישראל עמדו וגירשו את נשותיהם. וכשראו כחות הטומאה כן נתייאשו מן המושיע ההוא, ואז הי\"ת עזרנו והציץ והפריח את ציץ ישועתינו ונולד משה.","b":false},{"t":"וכן היה אצל דוד המלך ע\"ה שנסתבבו סיבות מופלאות בלידתו (וראה ילקוט המכירי לתהלים מזמור קיח וראה מדבר קדמות למרן החיד\"א מערכת י' אות כ'), וגם אז דנו בו אם הוא ראוי לבא בקהל וכו'. וכן היה בעת הגיע הברכה שיצחק רצה לברך. כי הכחות של הטומאה לא היו נחים ושוקטים, אם היה יצחק מבקש לברך את יעקב בהדיא, ובפרט שיש להם כמין טענה שלהם ניתנה הארץ, בחלוקה שחלקו שני האחים ביניהם. והברכות הם לחיי עוה\"ז בלבד לפי דעתם, והקב\"ה ישתבח שמו כביכול משחק בהם, יושב בשמים ישחק ה' ילעג למו (תהלים ב, ד), והי\"ת שהוא עילת העילות וסיבת כל הסיבות, הניח את יצחק לטעות בעשו הרשע, ולחשבו שהוא צדיק גמור (כמבואר בב\"ר סג, טו ובדברי רש\"י בראשית כה, כז), עד שיצחק אבינו המתיק עמו סוד, וציוהו לצוד ציד ולהביא כדי לברכו ברכות שמים מעל וכו'. ובזה כחות הטומאה נרגעו ושקטו. ויהי אך יצא יצא עשו וגם כל כחות הטומאה יצאו ללוותו. או אז תיכף פעלה רבקה אמנו את פעולתה עפ\"י דבר ה' אליה בנבואה, ויעקב אבינו קיבל בסופו של דבר את הברכות המיוחלות.","b":false},{"t":"ויש לדעת שברכות אלו גורליות הן, והן הקובעות לדורות עולם, מי יהיה עם ה' וסגולתו, ומי יהיה העם הנצחי שיזכה לחיי עולם לנחול את שתי העולמות, שהרי בישר הקב\"ה לאברהם ואמר לו (בראשית כא, יב), כי ביצחק יקרא לך זרע, וכשאמר ביצחק יקרא, לא על כל זרע יצחק הבטיח זאת, כי ליעקב הבטיח ולא לעשו (ראה בדברי רש\"י בראשית כח, טו), שנאמר (תהלים קלה, ד), כי יעקב בחר לו יה ישראל לסגולתו.","b":false},{"t":"והנה היה מאבק איתנים בין יעקב לעשו, ועוד בהיותם בבטן אמם נאבקו זה בזה, מי הוא זה שיבחר להמשיך את זרעו של אברהם אבינו ע\"ה לדורות עולם. ועשו הבין והכיר ביקרת הענין הנשגב הזה להמשיך על עצמו את ברכת אברהם ויצחק ולהבחר הוא להיות ה\"ממשיך\". ומה היה עושה, היה מכבד את אביו ומפתהו בפיו ובלשונו, לצוד ציד להביא, וחשב כי ע\"י שיעשה על אביו רושם חיובי, לבסוף יבחר בו ויברך אותו וימסור לו את שרביט הברכות לדורות עולם. ואכן באמור אליו יצחק צודה לי ציד, שמח עשו מאד, כי לכאורה הצליח במשימתו, והיה שקט ובוטח בהצלחתו, בחשבו כי הברכות מונחות לו בכיסו, ובזה שקטו ונרגעו גם איספרווא דיליה, ויצאו לצוד ציד להביא טרף לנפשם הצמאה והרעבה אשר לא ידעה שבעה, ובינתיים עצת ה' קמה וגם נצבה, ונטל יעקב את הברכה.","b":false},{"t":"והנה רבינו האר\"י ע\"ה כתב (ראה עץ חיים שער ל\"ב מהדו\"ת פ\"ב), שגם בעולם העליון, דברים אלו חוזרים על עצמם בכל יום ויום ממש, שבכל יום, עשו בא ומבקש את הברכות, ומטעים אותו ע\"י שמשמיעים לו קולות שירה וצהלה, ואומרים לו לך נא לצוד ציד ובשדה יש חינגאות, והוא יוצא בריצה כדי ליהנות מאותה חינגא, ויהי אך יצא יצא, מיד מביאים את יעקב ונותנים לו את הברכות, וכשחוזר עשו, ושומע שיעקב נטל את הברכות, ויזעק זעקה גדולה ומרה, ולמחר שוב חוזר אותו ענין ממש, וכן בכל יום ויום, יעו\"ש באורך.","b":false},{"t":"ואם כי הדברים עמוקים מהשגתינו, עכ\"פ למדנו כדרכינו, דאין זה ענין אקראי בעלמא, שעשו הצליח לפתות את אביו בפיו ולהטעותו, אלא מאת ה' היתה זאת, ואם כי היא נפלאת בעינינו, מ\"מ זה דרכו של עולם לפי המטבע שהטביע הקב\"ה בהנהגת עולמו, להטעות את כחות הטומאה ולאבדם, ואשר ע\"כ בודאי שאין מקום לאותם דברים שנכתבו בספר כלי יקר היקר, שתולה הטעות בכהות עיני שכלו של יצחק אבינו ע\"ה, דאינו כן, אלא מאת הי\"ת היתה זאת לו.","b":false},{"t":"ובודאי יש טעמים חשובים לכהות עיני יצחק, וכפי שביארנו טעם אחד מהם, דזו הדרך שבה מנהיג הי\"ת את עולמו, מפני שיש כח לסטרא אחרא להתנגד ולעמוד בחוזק ובכח גדול, שבא להם מאתו יתברך, לצורך תיקון העולם. כי בלי האיזון הנורא הזה שבין כח הטומאה, לעומת כח הקדושה, לא יכון העולם במתכונתו המיוחדת, אשר חקק וקבע הקב\"ה.","b":false},{"t":"וכח הבחירה שהטביע הקב\"ה ביסוד יצירתו של האדם, שעיקרו מבוסס על כך שהאדם מורכב מגשמיות ורוחניות המשולבות זו בזו, כי הגוף יסודו מעפר, ויצר ה' אלהים את האדם עפר מן האדמה, ויפח באפיו נשמת חיים (בראשית ב, ז), והנשמה היא חלק אלוה ממעל, דמאן דנפח, מדיליה קא נפח (עי' זוהר ח\"א כז, א ודו\"ק, ובספר הפליאה ד\"ה שאל משה וכו' ובפירוש הרמב\"ן לתורה בראשית ב, ז ובספר התניא ח\"א פ\"ב מייתי כן מהזוהר). ושני כחות אלו שלובים זה בזה, ואינם נפרדים זה מזה, זה מושך לצד הזה וזה מושך לצד זה, ובחכמה נפלאה נתן הקב\"ה כח מיוחד באדם, שהוא כח המכריע, שעל ידו יכול האדם להטות עצמו לצד הטוב והמועיל, ותהא יד הנשמה והרוח על העליונה, ואם חלילה יהיה מטה לצד התאות והרצונות בלא שיקול דעת והבחנה, הרי שמצבו ילך וידרדר, ואחריתו מי ישורנו.","b":false},{"t":"והנה כשעולה לרצון לפניו יתברך לעשות איזה דבר לחזק ולהרחיב את גבולות הקדושה, כי אז, הצד שכנגד זועק ונלחם. אמנם הקב\"ה ישתבח שמו, משגיא לגוים, ומבלבל אותם כדי להביא ולקיים את דברו ואין עצה ואין חכמה ואין תבונה נגד ה'.","b":false},{"t":"וזה מה שהיה כאן, שהקב\"ה הטעה כביכול את יצחק ועלתה בדעתו לברך את עשו, ובזה הוסחה דעת הסט\"א, ולבסוף נטל יעקב אבינו ע\"ה את הברכות. וללא כל זה לא היה יכול יעקב אבינו ע\"ה ליטול את הברכות כביכול. ועוד, כי בזכות טעות יצחק אבינו ע\"ה גם לנו באה רווחה, גם מעצם הטעות שטעה יצחק ברצון ה', עי\"כ נוכל לקבל את הברכות וכנ\"ל.","b":false}]},{"id":"14","t":"המאבק על טהרתן של ישראל","p":[{"t":"וַיַּחְפְּרוּ עַבְדֵי יִצְחָק בַּנָּחַל וַיִּמְצְאוּ שָׁם בְּאֵר מַיִם חַיִּים, וַיָּרִיבוּ רֹעֵי גְרָר עִם רֹעֵי יִצְחָק לֵאמֹר לָנוּ הַמָּיִם וַיִּקְרָא שֵׁם הַבְּאֵר עֵשֶׂק כִּי הִתְעַשְּׂקוּ עִמּוֹ, וַיַּחְפְּרוּ בְּאֵר אַחֶרֶת וַיָּרִיבוּ גַּם עָלֶיהָ וַיִּקְרָא שְׁמָהּ שִׂטְנָה, וַיַּעְתֵּק מִשָּׁם וַיַּחְפֹּר בְּאֵר אַחֶרֶת וְלֹא רָבוּ עָלֶיהָ וַיִּקְרָא שְׁמָהּ רְחֹבוֹת וַיֹּאמֶר כִּי עַתָּה הִרְחִיב ה' לָנוּ וּפָרִינוּ בָאָרֶץ: (כו, יט-כב):","b":true},{"t":"אחר המאבק על הבארות של אברהם אבינו שסתמום פלשתים וחזר יצחר לחפור אותן, עוד נאבק יצחק אבינו ע\"ה על הבארות החדשות שלו. מאבק אחר מאבק, ויצחק אבינו ע\"ה לא נתייאש, עד שמצא מנוחה.","b":false},{"t":"ושמעתי בזמנו מכבוד הרב הגאון המנוח רבי ישעיהו משורר זללה\"ה, אב\"ד פתח תקוה ת\"ו, שפירש בזה פירוש נפלא, כי היה קשה לו, למה היה צריך יצחק אבינו ע\"ה, לכל המאבקים הללו, ובמקום להאבק עם הפלשתים, הלא היה יכול לקנות מהם מים בכסף מלא, שהרי עשיר גדול היה, כי הי\"ת ברכו במאה שערים של ברכה (ראה בראשית כו, יב). ואמרו חז\"ל (ב\"ר סד, ז ורש\"י בראשית כו, יג), על הפסוק (שם שם, יג), עד כי גדל מאד, שהיו אומרים הבריות זבל פרדותיו של יצחק, ולא כספו וזהבו של אבימלך. וא\"כ במעט כסף היה יכול יצחק אבינו לקנות מהם מים, וישאבו לו מים בששון ובשלום, בלא ריב ועשק.","b":false},{"t":"והוא ז\"ל פירש, דלא מדובר בבארות מים בעלמא, אלא במקואות לטהרה, שמים שאובים פסולים להם כידוע. ועל כן היה מתעקש למצוא דוקא באר מים שתהיה כשרה לטבילה. ואז בא השטן ושם בלבם לריב עמו, כדרך כל דבר שבקדושה, שהשטן וכל איספרווא (ראה כתובות ג, ב ורש\"י שפי', איספרווא - חיל המשרתים המכינים לו צרכי הסעודה), דיליה, מרבים ריב ומדון על זה, למנוע עושי מצוה.","b":false},{"t":"אך יצחק אבינו ע\"ה, לא נתייאש ולא נכנע ח\"ו, והמשיך לחפור עוד ועוד. וכשחפר את הבאר האחרונה, לא רבו עליה, כי סוף האמת לנצח וגבר ישראל, וקרא את שמה \"רחובות\", ואמר, כי הרחיב ה' לנו ופרינו בארץ. דתיבת ו\"פרינו\" שייכת למקוה דוקא (שבזכות המקוה זוכין לקיים מצות פו\"ר). ועוד הוסיף להוכיח, מההושענות של רב סעדיה גאון ז\"ל של יום שני לסוכות, שכתב, למען יצחק אשר חפר \"מקוות\" המים, ולא אמר בארות המים, כפי גירסתינו. ושפתים יושק, ויה\"ר שיהיו שפתותיו דובבות. ותנצב\"ה לעד.","b":false},{"t":"ויש להוסיף בזה, דאנו רואים שכבר בימי אברהם ויצחק, נאבקו על טהרת עם ישראל, ולא חדשים הם המקוה והטהרה. וצריכים כולנו ללמוד מהם להמשיך לעמוד על טהרתנו, ובסוף מובטח לנו וגבר ישראל, וזוכים להרחבת הדעת והשקט ובטחה.","b":false},{"t":"עוד יש לשים לב דבשתי הבארות הראשונות, נאמר, ויחפרו עבדי יצחק בנחל, ויחפרו באר אחרת, דע\"י עבדיו נחפרו אותן בארות, ורבו עליהן. אבל בשלישית נאמר, ויעתק משם, ויחפור באר אחרת וגו', ויקרא שמה רחובות, ולא רבו עליה. ואפשר דאחרי שכבר מסר נפשו עליה לחפור אותה בעצמו, ולא ע\"י עבדיו, כמבואר בתורה \"ויחפור\", לשון יחיד, אז קיבל סייעתא דשמיא ולא רבו עליה, בבחינת, ברצות ה' דרכי איש גם אויביו ישלים עמו (משלי טז, ז). ומשום הכי כתיב, ויעתק, ויחפור, ויקרא שמה. הכל בלשון יחד, לומר כי הכל נעשה על ידי יצחק אבינו ע\"ה לבדו.","b":false},{"t":"ואפשר שכשהוא עצמו חפר ועשה, בזה נעשה תיקון גדול ועצום, כשהוא בעצמו נחית להכי, ובזה מעלה ניצוצות הקדושה, ומברר אוכל מן הפסולת, וממילא אתיא מביניא, \"הרחיב ה' לנו ופרינו בארץ\" שע\"י עסק עבודת ה' במסירות נפש ע\"י הצדיק, הקב\"ה עוזרו ומצמיח ישועות בעבודתו הקדושה לכלל ולפרט.","b":false},{"t":"ומזה נלמד להבין חשיבות המצוה למי שעושה אותה בעצמו ולא ע\"י שליח ולא על ידי מלאך, אלא הוא בעצמו ממש. וזה שאמרו במסכת קדושין (מא, א), האיש מקדש בו ובשלוחו, ושאלו בגמרא, אם בשלוחו מקדש, בו מיבעיא, אלא לומר דמצוה בו יותר מבשלוחו. והנה למעשה מצד קידושי האשה, אין שום חילוק בין אם האדם מקדשה בעצמו, או על ידי שליח, כי בשני המקרים היא מקודשת לו במדה שוה ממש, ואין שום הבדל בינו ובין שלוחו. ומ\"מ יש חשיבות לאדם ותועלת רבה בעשותו את המצוה בעצמו. וזה מה שכתב רש\"י ז\"ל שם, מצוה בו, שגופו יעסוק במצוה. עכ\"ל. והיינו שכשהגוף עוסק במצוה, חלה עליו קדושת המצוה ומתקדש ממנה.","b":false},{"t":"והנה איתא בזהר הקדוש (ח\"ב ג, ב), גבי נדה שנאמר בה (ויקרא טו, כד), ותהי נדתה עליו. שיש רוח רעה ושמה נדה, שהנכשל באותו עון רח\"ל אותה קליפה תהיה עליו, ומלבישתו מכף רגל ועד ראש, ה' יצילנו. והנה מדה טובה כפולה ומכופלת, שכאשר גופו עוסק במצוה, קדושת המצוה עוטפת אותו ומתקדש ממנה. וע\"כ הגם שקיום המצוה שוה בין אם יעשנה בעצמו או ע\"י שליח, אבל כשמקיימה ע\"י עצמו, זוכה להתקדש ממנה. ומעלה זו אין האדם יכול להשיג כשהוא עושה את המצוה ע\"י שליח.","b":false},{"t":"ובמקום אחר (ראה לעיל פרשת וירא מאמר י), פירשתי בזה ענין הלכתי בשבת, והוא ענין בסיס לדבר האסור (מבואר במס' שבת בהרבה מקומות כיעוי' שם מז, א ושם קיז, א ושם קכ, ב ושם קמב, ב ובשו\"ע או\"ח סי' שט וסי' שיא), דגם הבסיס שעליו מונח הדבר המוקצה, הריהו מקבל את הדינים של האיסור המונח עליו. וכן הדבר באדם שעובר עברה, שאז גופו נעשה \"בסיס לדבר האיסור\", וטומאת האיסור חלה עליו.","b":false},{"t":"אבל כשעוסק במצוה בגופו, גופו נעשה בסיס למצוה ולקדושה העולה ממנה, וגופו מתקדש מאותה קדושה. ואשר על כן בשעה שיצחק הניח את עוזריו ושליחיו, והלך בעצמו לעסוק במצוה בגופו וחפר את הבאר, היתה לו סיעתא דשמיא, ולא רבו עליה, ואז אמר כי הרחיב ה' לנו, ופרינו בארץ.","b":false},{"t":"וגם סגולה נפלאה לכפרת עוונות יש בטורח במצוה בגופו דוקא, וכמו שדיבר בקדשו איש האלהים רבינו האר\"י (והובא דבר זה בשמו בספרים הרבה), כי הטורח ומזיע בעת אפיית המצות זוכה ומקדש עצמו, ומתכפר לו אשר פגם בקדושתו. והיטיבו רבותינו במאמרם (ויקרא רבה כא, ה), אם עשית חבילות של עבירות, עשה כנגדן חבילות של מצות. ע\"ש. ואת המעלה הזאת של מחילת עוונות אינו יכול להשיג כשהוא עושה מצוה ע\"י שליח.","b":false}]},{"id":"14","t":"צאי לך בעקבי הצאן","p":[{"t":"וַיָּשָׁב יִצְחָק וַיַּחְפֹּר אֶת בְּאֵרֹת הַמַּיִם אֲשֶׁר חָפְרוּ בִּימֵי אַבְרָהָם אָבִיו וַיְסַתְּמוּם פְּלִשְׁתִּים אַחֲרֵי מוֹת אַבְרָהָם וַיִּקְרָא לָהֶן שֵׁמוֹת כַּשֵּׁמֹת אֲשֶׁר קָרָא לָהֶן אָבִיו: (כו, יח)","b":true},{"t":"לומדים מכאן דבר חשוב מאד, והוא, שיצחק אבינו ע\"ה דאג לחפור אותם בארת ממש שחפרו בימי אברהם אביו. ולא עוד, אלא שגם קרא להם שמות כשמות אשר קרא להן אביו.","b":false},{"t":"וממה שהתורה הקדושה הדגישה לנו את כל זה, זה מלמדנו על חשיבות הענין שלא לסור מדרכי אבותינו כמלא נימה. וכמו שנאמר בשיר השירים (א, ח), אם לא תדעי לך היפה בנשים צאי לך בעקבי הצאן ורעי את גדיותיך על משכנות הרועים.","b":false},{"t":"אם האדם נבוך ואינו יודע איך לנהוג, אל לו להבהל, ילך בעקבות אבותינו רועי צאן קדשים, האבות הקדושים, ובכל מקרה שיזדמן לפניו, יאמר לעצמו, איך היו נוהגים אבותינו ורבותינו הקדושים בעת הזאת, וידבוק בדרכם, ואז מובטח לו שלא יכשל לעולם, אכי\"ר.","b":false}]},{"id":"14","t":"ויתרוצצו הבנים בקרבה","p":[{"t":"וַיֶּעְתַּר יִצְחָק לַה' לְנֹכַח אִשְׁתּוֹ כִּי עֲקָרָה הִוא וַיֵּעָתֶר לוֹ ה' וַתַּהַר רִבְקָה אִשְׁתּוֹ, וַיִּתְרֹצֲצוּ הַבָּנִים בְּקִרְבָּהּ וַתֹּאמֶר אִם כֵּן לָמָּה זֶּה אָנֹכִי וַתֵּלֶךְ לִדְרשׁ אֶת ה', וַיֹּאמֶר ה' לָהּ שְׁנֵי גוֹיִם בְּבִטְנֵךְ וּשְׁנֵי לְאֻמִּים מִמֵּעַיִךְ יִפָּרֵדוּ וּלְאֹם מִלְאֹם יֶאֱמָץ וְרַב יַעֲבֹד צָעִיר: (כה, כא-כג)","b":true},{"t":"וכתב רש\"י ז\"ל (בראשית כה, כב), ויתרוצצו, רבותינו (ראה ב\"ר סג, ו), דרשוהו לשון ריצה, כשהיתה עוברת על פתחי תורה של שם ועבר, יעקב רץ ומפרכס לצאת, עוברת על פתחי עבודה זרה עשו מפרכס לצאת. דבר אחר, מתרוצצים, זה עם זה, ומריבים בנחלת שני עולמות. ותאמר אם כן למה זה אנכי, מתאוה ומתפללת על הריון. ממעייך יפרדו, ממעים הם נפרדים, זה לרשעו וזה לתומו. מלאום יאמץ, לא ישוו בגדולה, כשזה קם זה נופל, וכן הוא אומר, אמלאה החרבה (יחזקאל כו, ב), לא נתמלאה צור, אלא מחרבנה של ירושלים. עכ\"ל.","b":false},{"t":"וצריכים להבין איך נרגעה רבקה בדברי הנביא שאמר לה, שני גויים בבטנך. והרי סוף סוף אחד מהם רשע מבטן ומלידה. והתעורר בזה בעל כלי יקר שם, ובסוף דבריו כתב בזה\"ל, ויאמר ה' לה שני גויים בבטנך, זה רבי ואנטונינוס (ראה ברכות נז, ב), והועילה תפלתה שגם עשו יצא ממנו זרע כשר, כאנטונינוס ושאר גרי צדק, מה שאין כן בישמעאל, ובזה את טובה מהגר. עכ\"ל.","b":false},{"t":"ובדרך כלל מפרשים, שרבקה חשבה שיש לה בן אחד, והוא פוסח על שתי הסעיפים, ורוצה לפרכס לצאת בבית המדרש, אך לא רק לבית המדרש אלא גם לפתח של עבודה זרה וע\"ז אמרה, אם כן למה זה אנכי. אבל כשאמר ה' לה, שני גוים בבטנך, אחד צדיק ואחד רשע. זה היה טוב ועדיף בעיניה, וכמו שמצינו בדברי אליהו הנביא זכור לטוב, שאסף את כל ישראל אל הר הכרמל, וַיִּגַּשׁ אֵלִיָּהוּ אֶל כָּל הָעָם וַיֹּאמֶר עַד מָתַי אַתֶּם פֹּסְחִים עַל שְׁתֵּי הַסְּעִפִּים אִם ה' הָאֱלֹהִים לְכוּ אַחֲרָיו וְאִם הַבַּעַל לְכוּ אַחֲרָיו וְלֹא עָנוּ הָעָם אֹתוֹ דָּבָר (מ\"א יח, כא).","b":false},{"t":"[א\"ה - והטעם שאסף אליהו את ישראל דוקא להר הכרמל. יש לבאר על פי דברי התוספות שבת (ו, א ד\"ה כרמלית), שהביאו בשם הירושלמי, תני ר' חייא כרמל, רך ומלא, לא לח ולא יבש אלא בינוני (וכ\"ה בספרא ויקרא דבורא דנדבה פרק טו). ובזה פירשו התוספות שם כרמלית, שאינה לא רשות היחיד ולא רשות הרבים. נמצינו למדים בדברי רבותינו שכאשר רוצים לפרש לנו מהו דבר \"שאינו מוגדר\" וזהותו מטושטשת, קוראים לו כרמל, או כרמלית, וזה הענין שאליהו הנביא קיבץ את ישראל להר ששמו כרמל, לרמוז להם, עד מתי אתם נוהגים בעצמכם ככרמל, עובדים את הי\"ת ומאידך גיסא עובדים גם לע\"ז רח\"ל. ודו\"ק, יבח\"ר].","b":false},{"t":"ונחזור לענינו. והנה אנו צריכים להוסיף ולומר כי ע\"י מה שנאמר לרבקה בבית שם ועבר, הבינה שתיקון העולם הוא, שיצאו ממנה שני לאומים, ולאום מלאום יאמץ, וכשזה עולה זה יורד וכו'. והבינה היטב שזהו הצורך שבשבילו ברא ה' את עולמו, כי הוא יוצר אור, ובורא רע, וזה לעומת זה עשה אלהים, כדי שיהיה המאבק בין הטוב והרע שוה, ותתחזק הבחירה בעולם. וה' חפץ למען צדקו, שבני אדם ילכו אחריו באש ובמים, ויאמרו ה' הוא האלהים, מתוך בחירתם החופשית. ושהיקף המאבק על הבחירה, לא יצטמצם רק בתוך האדם פנימה, אלא יחבוק זרועות עולם.","b":false},{"t":"כי המאבק הזה שבין הטוב המצוי ביעקב לבין הרע המתגלם בעשו, מאבק איתנים אדיר הוא, האבקות המעלה ענני אבק שמתמרים ועולים עד כסא הכבוד, וכמו שאמרו רבותינו (חולין צא, א וראה זוהר ח\"א קע, א), על הפסוק (בראשית לב, כד), ויאבק איש עמו, מלמד שיצא מהם אבק בהאבקם ועלה עד כסא הכבוד. ע\"ש. ורבינו האר\"י (לקוטי תורה פרשת וישלח), כתב, ויאבק גי' קי\"ט כמנין \"כסא הכבוד\", וזו שארז\"ל מכאן שהעלו אבק עד כסא הכבוד. ועכ\"פ כששמעה רבקה והבינה שזהו רצונו יתברך לקיום עולמו, נרגעה רוחה ושקטה, ותט שכמה לסבול צער חבלי לידה, גם התרוצצות הבנים. ביודעה שעושה בזה רצון בוראה, ולא אמרה עוד אם כן למה זה אנכי.","b":false},{"t":"ועיין בתרגום יוב\"ע שכתב, ורבא יהוי משתעבד לזעירא, אם בנוי דזעירא נטרין פיקודיא דאורייתא. עכ\"ל. היינו שעשו ובניו יהיו משועבדים לזרעו של יעקב אבינו אם זרע יעקב יהיו שומרים את מצוות התורה הק'. סוף דבר אין לנו אלא התורה הזאת, והיא שעמדה, והיא העומדת, והיא תעמוד לנו לדורות עולם.","b":false}]},{"id":"14","t":"שלא תעלה קנאת אדם עלי","p":[{"t":"וַיִּגְדַּל הָאִישׁ וַיֵּלֶךְ הָלוֹךְ וְגָדֵל עַד כִּי גָדַל מְאֹד, וַיְהִי לוֹ מִקְנֵה צֹאן וּמִקְנֵה בָקָר וַעֲבֻדָּה רַבָּה וַיְקַנְאוּ אֹתוֹ פְּלִשְׁתִּים, וְכָל הַבְּאֵרֹת אֲשֶׁר חָפְרוּ עַבְדֵי אָבִיו בִּימֵי אַבְרָהָם אָבִיו סִתְּמוּם פְּלִשְׁתִּים וַיְמַלְאוּם עָפָר, וַיֹּאמֶר אֲבִימֶלֶךְ אֶל יִצְחָק לֵךְ מֵעִמָּנוּ כִּי עָצַמְתָּ מִמֶּנּוּ מְאֹד: (כו, יג-טז)","b":true},{"t":"מסמיכות הפסוק המספר על גדלותו והתעצמותו של יצחק, לבין פגיעת פלשתים בבארות, וביצחק עצמו, שאבימלך מגרשו מארצו. נראה שהיא תוצאה של התגדלותו, ומפורש כתוב ויקנאו אתו פלשתים.","b":false},{"t":"וכנראה מזה למד יעקב אבינו ע\"ה, ואמר לבניו למה תתראו (בראשית מב, א). וגם חז\"ל אמרו (תענית ח, ב ב\"מ מב, א), אין הברכה שורה, אלא בדבר הסמוי מן העין. והרואה יראה בדבריהם שאמרו את זה על ההולך למוד את גורנו, שהיו נוהגים לברך שהקב\"ה יתן ברכה בתבואה, והנה אם מדד את התבואה לפני שבירך את הברכה, אפי' אם היה זה לצורך הפרשת תרו\"מ, מ\"מ לא יזכה לשפע הברכה ההיא. ומההיא ישמע חכם ויוסיף לקח.","b":false},{"t":"צא וראה מה שמבקשים שלש פעמים ביום בסיום תפילת שמונה עשרה (ונדפס בסדורים, ומקורו מהירושלמי דברכות), שלא תעלה קנאת אדם עלי.","b":false}]},{"id":"14","t":"כחה של ליצנות","p":[{"t":"ואמנם עדיין צריך להבין, מה הועילו \"ליצני הדור\" באומרם מאבימלך נתעברה שרה. והלא בעצם לידת שרה כבר היה נס עצום שאשה זקנה כשרה אמנו שהיתה בת תשעים שנה, והיתה ידועה כעקרה כל ימיה, ועכשיו ילדה גם הניקה בנים שרה, וזה הוא עיקר הנס, ודבר זה אינו ניתן להכחשה, א\"כ מה פעלו אותם ליצנים באמרם מאבימלך נתעברה שרה.","b":false},{"t":"אלא זוהי כחה של ליצנות, שאפי' שאומרים דברים שאין בהם ממש, ואין בהם טעם כלל, עכ\"ז יש בהם לדחות כל השפעה טובה, כאשר ידוע כי \"ליצנות אחת דוחה מאה תוכחות\".","b":false},{"t":"ורבינו משה חיים לוצאטו זיע\"א במסילת ישרים (פ\"ה בביאור מפסידי הזהירות), כתב וז\"ל, ותראה קושי הלצון והשחתתו הרבה, כי כמו המגן המשוח בשמן, אשר ישמיט ויפיל מעליו החצים ומשליכם לארץ, ולא יניח אותם שיגיעו אל גוף האדם, כן הלצון מפני התוכחה והמרדות, כי בליצנות אחד ובשחוק קטן יפיל האדם מעליו ריבוי גדול מן ההתעוררות וההתפעלות מה שהלב מתעורר ומתפעל בעצמו, מדי ראותו או שומעו ענינים שיעירוהו אל החשבון והפשפוש במעשים, ובכח הליצנות יפיל הכל לארץ ולא יעשה בו רושם כלל. ולא מפני חולשת הענינים ולא מפני חסרון הבנת הלב, אלא מפני כח הלצון ההורס כל עניני המוסר והיראה. ע\"כ.","b":false},{"t":"היינו שרבינו הרמח\"ל מבאר לנו, שהליצנות אינה \"סותרת\" או \"פורכת\" את התוכחות ואת ההתעוררות, אלא \"דוחה\" אותן, וכדוגמת מגן שהוא עשוי מברזל עב וחזק, שיוכל להתמודד עם מכת החרב והחץ וכו', וגם מורחים אותו בחלב ושומן עב, עד שכל חץ שיורים עליו מתחלק ונשמט הצידה, מבלי שיעשה שום רושם במגן עצמו, וכך היא הליצנות, דוחה את התוכחות ואת ההתעוררות מכל וכל, עד שאינן יכולות לעשות בלב שום רושם כלל. ולא מפני החכמה שבליצנות, כי הרבה פעמים אין הליצנות מתייחסת כלל לדברי התוכחה, וגם אם הליצנות מתייחסת לדברי התוכחה או ההתעוררות, מ\"מ אינה שוה כלום לעומתן, וגם אין בה כדי שתוכל להתמודד עם תוכחת חיים, ועכ\"ז היא דוחה אותה, כי פעולת הליצנות היא היסח הדעת. להסיר את הלב מן המחשבות הישרות והעיוניות, נמצא שלא יבואו הרהורי היראה בלבו כלל.","b":false},{"t":"ועל פי דבריו ז\"ל פירשתי, שהליצנות לא פועלת נגד התוכחה כי אין בכחה לעשות זאת. אלא מהי עושה, הולכת ופועלת על ראשו של האדם, להסיח דעתו מן העיקר, ובמקום שיתרכז ברצינות והתבוננות בתוכחה, או במעשה מסויים שיש בו כדי לעורר את לב האדם, לחשוב על מצבו ולעשות מאזן נפשי, שזו היא הדרך לכבוש את היצר. ואז באה הליצנות ומסיחה דעתו מזה, ומפנה את תשומת לבו לדבר צדדי ותפל, ובינתיים נשמטת מתחת ידו ההתעוררות לתשובה.","b":false},{"t":"וזה מה שעשו ליצני הדור בימי אברהם, שהואיל וכל אלו שהיו קשורים עם אברהם, בדרך כל שהיא, ראו כולם את הנס הזה שהי\"ת עשה לאברהם, והיתה התפעלות עצומה והתקרבות גדולה אל הי\"ת. ואז באו ליצני הדור ואמרו, מאבימלך נתעברה שרה, ועל אף שסוף סוף היה מקום לומר להם, הרי שרה לא ילדה עד כה וזה עיקר הנס, כי לאברהם יש לו כבר את ישמעאל. אבל נגד ליצנות אי אפשר להלחם בטעם והגיון, כי גם הליצנות לא באה בדרך זו, רק עצם העובדה שזרקו לחלל העולם את הרעיון הריק והשדוף הזה, אז כל קלי הדעת נתפסים לזה, ובמקום לחשוב ולהפיק לקחים מעצם הנס, הריהם מעסיקים את מוחם בדברי הבאי של הליצנות הזו, לדון בענינו של יצחק אם הוא כשר, ועיניהם עצומות ולבם כבד כאבן, ולא יתנו אל לבם להבין את המרמה שהיצה\"ר מרמה אותם ומשחק בהם. וזו היא הדחיה של הליצנות. וע\"כ חז\"ל קראו להם \"ליצני הדור\" ולא רשעי הדור, כי לא בטעם והגיון באו, רק בכחה של הליצנות.","b":false},{"t":"ומאת הי\"ת היתה זאת, שלידת יצחק תהיה סמוך ליציאת שרה מבית אבימלך, כדי שהרוצה לטעות יבא ויטעה, ולא תשלל מהם הבחירה. אך כדי שגם מי שרוצה לראות את האמת הפשוטה יראנה, צר הקב\"ה את דיוקנו של יצחק דומה לאברהם, עד שכל \"הרואה\", פירוש, הרואה ומתבונן, ומתעלה מעל לליצנות, מיד אומר \"אברהם הוליד את יצחק\".","b":false}]},{"id":"14","t":"הנסים באים בהסתר כדי שלא לבטל את כח הבחירה","p":[{"t":"וְאֵלֶּה תּוֹלְדֹת יִצְחָק בֶּן אַבְרָהָם אַבְרָהָם הוֹלִיד אֶת יִצְחָק: (כה, יט)","b":true},{"t":"ופירש רש\"י ז\"ל (שם), שהיו ליצני הדור אומרים, מאבימלך נתעברה שרה, שהרי כמה שנים שהיתה עם אברהם ולא נתעברה הימנו, מה עשה הקב\"ה צר קלסתר פניו של יצחק דומה לאברהם, והעידו הכל אברהם הוליד את יצחק. וזהו שכתב כאן יצחק בן אברהם, אברהם הוליד את יצחק. שהרי עדות יש שאברהם הוליד את יצחק. עכ\"ל (ומקור הענין במדרש תנחומא פרשת תולדות).","b":false},{"t":"והנה לכאורה הסמיכות שהיתה בין לידת יצחק ליציאת שרה מבית אבימלך, היא היתה המשענת עליה נשענו אותם ליצנים בליצנותם, עד שאמרו מאבימלך נתעברה שרה.","b":false},{"t":"וצריכים אנו להבין פשר ענין זה, דהנה אחר שנים רבות כל כך שלא נפקדו אברהם ושרה בבנים, ועלה לרצון לפניו ישתבח שמו, לפקוד אותם ברחמים ליתן להם בן לשמח את נפשם, א\"כ למה פקדם בסמוך ממש ליום שיצאה שרה מבית אבימלך, והיה לו לפקוד את שרה זמן מופלג אחר שיצאה מבית אבימלך. וזאת, כדי שלא יהיה פתחון פה לליצנים, והוא יכול על כל ובידו הכל, ויכול להקדים או לאחר כל ענין, ואין ספק דהכל נעשה במיוחד שיהיה סמוך זה לזה, ומה הטעם לזה, לגרום להם שיהיו לשיחה בפי הבריות.","b":false},{"t":"ואין לומר דהקב\"ה לא חשש לליצנות אנשי הדור ההוא, דהא חזינא דהקב\"ה צר קלסתר פניו של יצחק דומה לאברהם, כדי שיעידו הכל שאברהם הוליד את יצחק, ולמה יש צורך כלל בעדות זו, והרי היה יכול למנוע את ליצנותם מעיקרא, ע\"י שישים ריוח בין יציאתה מבית אבימלך, לבין פקידתה של שרה. וכנ\"ל. ולא יצטרך אח\"כ לצור את פניו של יצחק כפניו של אברהם.","b":false},{"t":"והנראה בס\"ד, בהקדים מה שאמרו רבותינו ז\"ל (סנהדרין לח, ב וב\"ר ח, ד), על הפסוק (בראשית א, כו), ויאמר אלהים נעשה אדם. ועיין שם בדברי רש\"י שכתב, וז\"ל, אע\"פ שלא סייעוהו ביצירתו, ויש מקום למינים לרדות, לא נמנע הכתוב מללמד דרך ארץ ומדת ענוה, שיהא הגדול נמלך ונוטל רשות מן הקטן, ואם כתב אעשה אדם לא למדנו שהיה מדבר עם בית דינו, אלא עם עצמו, ותשובתו כתובה בצדו, ויברא את האדם ולא כתיב ויבראו. ע\"ש.","b":false},{"t":"ובמדרש (ב\"ר ח, ח), אמרו, בשעה שהיה משה כותב את התורה היה כותב מעשה כל יום ויום, כיון שהגיע לפסוק הזה שנאמר, ויאמר אלהים נעשה אדם בצלמנו כדמותנו, אמר לפניו רבון העולם מה אתה נותן פתחון פה למינים אתמהא, אמר לו, כתוב, והרוצה לטעות יטעה. אמר לו הקב\"ה, משה! האדם הזה שבראתי לא גדולים וקטנים אני מעמיד ממנו שאם יבא הגדול ליטול רשות מן הקטן ממנו והוא אומר מה אני צריך ליטול רשות מן הקטן ממני, והן אומרים לו למוד מבוראך שהוא ברא את העליונים ואת התחתונים כיון שבא לבראת את האדם נמלך במלאכי השרת.","b":false},{"t":"וראיתי בספר מכתב מאליהו להגה\"צ מהר\"א דסלר זצ\"ל (ח\"א עמ' , מאמר עכובים כלליים לתשובה), שהקשה על הלשון הנזכר במדרש \"הרוצה לטעות\", דאם הוא טועה אין זה רצון, ואם האדם רוצה א\"כ אין זו טעות. והסביר את הענין כדלהלן: שאם רואים שאדם טועה בדבר שהוא ברור כל כך, ומפורש כמה פעמים בתורה, צריך לדעת שיש לו רצון למחשבה זו של הטעות, והרצון הזה בא מתוך כפירה ואפיקורסות, ומחפש במה ליתלות, ועל כן אין זו טעות רגילה, אלא טעות הנובעת מהרצון הטמון בלבו פנימה. כי הנה יש מקראות מפורשים למאות המעידים על יחודו ית', וגם באותו הפסוק ולפניו מפורש יחודו יתברך, בתחילה כתיב בראשית ברא אלהים, וכמה פעמים כתוב ויאמר אלהים, וגם בזה כתוב ויאמר אלהים, ואח\"כ בפסוק שאחריו ממש כתיב, ויברא אלהים את האדם בצלמו וכו' \"ויברא\" בלשון יחיד. וכמו שכתב רש\"י ז\"ל עצמו ע\"ז בסוף הדבור, וז\"ל, ותשובתו כתובה בצדו ויברא את האדם, ולא כתיב ויבראו. עכ\"ל.","b":false},{"t":"ואדם זה נתלה בלשון זה של \"נעשה אדם\", ומתעלם מכל הפסוקים המפורשים, זה סימן שרוצה לטעות. וגם כאן נשאלת אותה שאלה, למה הוצרך אח\"כ לתת תשובה. והיה יכול לכתוב \"אעשה אדם\", ולא להניח מקום אפילו למינים ולכופרים הרוצים לטעות. ואם הוא בשביל ללמד דרך ארץ לגדולים שיתייעצו בקטנים, הלא הרבה דרכים יש לפניו ללמדנו דרך ארץ, מבלי להניח מקום לרוצים לטעות.","b":false},{"t":"אלא יש כאן יסוד גדול, בהנהגת הבורא את עולמו, אשר יצר את האדם בצלמו, להיותו בחירי, שזה עיקר בריאת האדם וזו מעלתו. וקבע שהבחירה תהיה חופשית בידיו של אדם בכל עת ובכל ענין, עד שאפילו בתוה\"ק הניח מקום לרוצים לטעות, כדי שיוכלו לחזק טעותם מדברי התורה עצמה, וכן היה דרכם של הרבה כופרים כידוע. והרוצה את האמת, הלא היא מפורשת פעמים אין ספור בתוה\"ק, וכמו שכתב הנביא (הושע יד, י), \"כי ישרים דרכי ה' וצדיקים ילכו בם ופושעים יכשלו בם\". דאין הדרך קובעת אם יכשל בה, כי כל דרכי ה' ישרים בלי דופי ח\"ו. רק הדבר תלוי באדם עצמו, אם צדיק הוא הריהו הולך ללא שום פגע. אבל הפושע נכשל ונתקל על כל צעד ושעל. כי בלבו שם אורבו, עד שאפילו בדבר כה יסודי כבריאת האדם, ניתן בו מקום לרוצים לטעות. וכן בכל פעם שהקב\"ה עושה נס גלוי שהוא היפך הטבע, הריהו מניח בצדו מקום לרוצים לטעות ולהכחיש. וזאת, כדי לשמור על הבחירה שלא תישלל מן האדם, בראותו את הנס הגלוי, ויתחיל לעבוד את הי\"ת מכח הנס, ואין זו המטרה שלשמה נברא האדם, אלא רצונו יתברך שהאדם יעבוד אותו, מתוך החלטה פנימית הנובעת מתוך בחירה חופשית. עד שאפילו בנס קריעת ים סוף שהוא הנס הגלוי הגדול ביותר, נשאר מקום לטועים ומצאו להם יסוד לטעותם, כאשר יעויין בדברי רבינו אברהם אבן עזרא ז\"ל (שמות יד, כז), על קריעת ים סוף, מ\"ש בשם חוי הכלבי ישתחקו עצמותיו והפריך את דבריו. וגם בזמנינו, קמו חכמים בעיניהם לשלוח יד בקדשי ישראל, וגם על כל הניסים שנעשו לישראל פערו את פיהם בבלי חוק להכחיש ולסלף את הידוע והמקובל. והשאלה המתבקשת מאליה היא, מדוע לא עשה הבורא נס שיהיה כל כך ברור, עד שלא יוכלו לעשות בו שום פירושים ועיוותים, באופן שלא ישאר שום מקום לטעות ולסילוף. אמנם התשובה לזה ברורה, כי אדרבא זהו רצון הי\"ת, ומאתו היתה זאת, שישאר מקום לרוצים לטעות, כדי שהבחירה תשאר בידי האדם על כנה בכל תוקפה והדרה, כי זה כל האדם.","b":false},{"t":"והוא הדבר אשר היה גם בענין זה של אברהם אבינו ע\"ה, אשר כל ימיו היו קדש לעבודת הי\"ת, והיה מקרב נפשות לאמונה בהשגחתו יתברך, וקירבם ע\"י הכנסת אורחים, וע\"י שהיה מקהיל קהילות ברבים ומלמדם את דרכי ההשגחה וכו', והנה הי\"ת עושה לו ולשרה אשתו נס גדול כל כך, לפקדם בבן בימי זקנתם, כשאברהם בן מאה שנה ואשתו בת תשעים שנה, והדבר בודאי היה נותן הד גדול אצל כל אלו שנתקרבו ע\"י אברהם אבינו ע\"ה, ועלולים היו להכריע בסוגית אמיתות הי\"ת מתוך הנס שראו אצל אברהם אבינו ע\"ה. ואם כי אמנם, אחת ממטרות הנס היא לעורר ולחזק את האמונה, אבל עם כל זאת אין הקב\"ה מעונין בשלילת הבחירה לגמרי, אלא הוא משאיר מקום למי שמתעקש ורוצה לטעות, שיוכל לטעות. ואע\"פ שהנס מספק חומר להתבוננות ולמחשבה, והמתבונן בחסדי ה', יכול להתחזק ולהפיק תועלת גדולה מזה. אבל על כל פנים זה יוצא מן הבחירה החפשית, והנס רק מעורר ומקרב את האדם לבוראו, אך לא נשללת מן האדם הבחירה.","b":false},{"t":"ועל כן עשה הי\"ת את נס לידת יצחק סמוך ליציאת שרה מבית אבימלך, ובזה נתן מקום לרוצים לטעות, שיוכלו לומר מאבימלך נתעברה שרה, ובזה מחלישים את השפעת הנס, ואלה שרוצים לטעות יוכלו להמשיך בקשיות עורפם כבתחילה. ואמנם הרוצים למצא את האמת ימצאוה, כי ישרים דרכי ה'. ובכדי שלא יצליחו אלה הליצנים להטעות גם את אלו שאינם רוצים לטעות, ויצא לעז ועקשות פה על יצחק ח\"ו, לכך הי\"ת צר את קלסתר פניו של יצחק דומים לשל אברהם. עד שהרואה אומר אברהם הוליד את יצחק.","b":false}]}]},{"slug":"ויצא","name":"פרשת ויצא","items":[{"id":"18","t":"מי הם אותם מלאכי אלהים שפגעו ביעקב","p":[{"t":"וְיַעֲקֹב הָלַךְ לְדַרְכּוֹ וַיִּפְגְּעוּ בוֹ מַלְאֲכֵי אֱלֹהִים, וַיֹּאמֶר יַעֲקֹב כַּאֲשֶׁר רָאָם מַחֲנֵה אֱלֹהִים זֶה וַיִּקְרָא שֵׁם הַמָּקוֹם הַהוּא מַחֲנָיִם: (לב, א-ב)","b":true},{"t":"הן ידוע שיש מחנה מלאכים שסימנם ארגמ\"ן (ראה בתיקוני זוהר תקון ע קכז, ב וע\"ח שער נ' פרק ח וראה בשל\"ה תורה אור בביאורו לסדר נשא כשביאר את ענין המחנות), והם, אוריאל רפאל גבריאל מיכאל נוריאל, ואמרו שנוריאל ואוריאל אחד הם, והוא הנקרא מחנה שכינה.","b":false},{"t":"והרה\"ק רבי שלם בוזאגלו ע\"ה בעל מקדש מלך על הזהר הקדוש כתב (נדמה לי בהקדמה לפירושו הדרת פני מלך על האידרא), שפ\"א נרדם ובא אליו מורו ורבו רבי חיים ן' עטאר הזקן ז\"ל, ואמר לו תפתח את ידך, ופתח וראה שכתוב בו ארגמ\"ן, ושאלו מה זה והשיבו כהנ\"ל, ע\"ש.","b":false},{"t":"וראיתי באיזה סדורים שנכתב בהם כי המלאכים הללו היו מחנה שפגש יעקב אבינו ע\"ה, וזה אומרו, כאשר רא\"ם ר\"ת רפאל אוריאל מיכאל, וחסר גבריאל (אך נוריאל אינו חסר כי הוא אוריאל וכנ\"ל), לזה אמר מחנה \"אלהים\" זה, שהוא גבורה, והוא בחינת גבריאל, ואז נשלם מחנה שכינה שהוא \"ארגמן\". וטוב שיכוין אדם לזה בדרכים באומרו פסוק זה בתפלת הדרך.","b":false},{"t":"[א\"ה - מה מתקו לחכי לפי זה דברי זוהר חדש סדר חוקת דאיתא שם, מרכבו ארגמן - דא יעקב וכו', והדברים נפלאים. יבח\"ר].","b":false},{"t":"* * *","b":false},{"t":"הצדיקים שקולים כמלאכים","b":true},{"t":"וטעם הדבר שקרא יעקב למקום ההוא \"מחנים\", כבר כתב רש\"י ז\"ל, שהוא כנגד ב' מחנות, כנגד מחנה של מלאכי חוץ לארץ שבאו עמו עד כאן, וכנגד מחנה של מלאכי א\"י שבאו לקראתו. ע\"ש. ועיין להרמב\"ן ז\"ל מה שכתב על זה. ובליקוטי אנשי שם (הנדפס בחומש רב פנינים), כ' שיש מלאכים שנבראו בששת ימי בראשית, ויש מלאכים שנבראים ממדות ומעשים טובים. ואולי זו היא כונת הראב\"ע ז\"ל בפירושו לתורה (שם), שכתב \"מחנים\" על שם שנים, אחד שלו ואחד של מלאכים, ע\"כ. ואפשר שכונתו שיעקב ובני ביתו הם המחנה האחד, והמחנה השני הוא מחנה המלאכים. וכ\"נ מדברי רבנו עובדיה ספורנו ז\"ל בפירושו. ומזה נלמד על מעלת יעקב וביתו ששקולים המה כנגד מחנה של מלאכי עליון.","b":false}]},{"id":"18","t":"בטחו בה' עדי עד","p":[{"t":"וַיִּקַּח יַעֲקֹב אָבֶן וַיְרִימֶהָ מַצֵּבָה, וַיֹּאמֶר יַעֲקֹב לְאֶחָיו לִקְטוּ אֲבָנִים וַיִּקְחוּ אֲבָנִים וַיַּעֲשׂוּ גָל וַיֹּאכְלוּ שָׁם עַל הַגָּל, וַיִּקְרָא לוֹ לָבָן יְגַר שָׂהֲדוּתָא וְיַעֲקֹב קָרָא לוֹ גַּלְעֵד: (לא, מה-מז)","b":true},{"t":"שמעתי לפני שנים רבות ממו\"ר הרה\"צ חסידא קדישא רבינו משה חדאד ע\"ה וזיע\"א, בשם רבינו האר\"י דהשם שממנו שואבים ויונקים מדת הבטחון, הוא השם הק' אכדט\"ם שהוא חילוף שם אלהים, דהיינו, שהאותיות האמצעיות \"לה\"י\", מתחלפות באותיות הקודמות להם שהם אותיות \"כד\"ט\", והאות הראשונה והאחרונה של השם הזה לא מתחלפות, דהאות אל\"ף אין לפניה שום אות, והאות מ\"ם סופית, הרי לפניה יש מ\"ם ראשונה והיא היא, וע\"כ מהשם אלהים יוצא אכדט\"ם, ועולה בגימטריא ע\"ד, וזהו שאמר הכתוב (ישעיה כו, ד), בטחו בה' עדי עד.","b":false},{"t":"ואותיות כד\"ט שהן מתחלפות תחת אותיות לה\"י חשבונם עולה בגימטריא ל\"ג, וזהו הגל שעשה יעקב אבינו ע\"ה עם בניו, וקרא לו גלעד, שע\"י החילוף של אותיות לה\"י באותיות כד\"ט, שעולים ג\"ל בזה נהפך השם אלהים לשם אכדט\"ם, שהוא ע\"ד. וזהו ע\"ד הג\"ל הזה (ומבואר כל זה בשער הכונות דרושי הפסח דרוש י\"ב ובפע\"ח שער ספירת העומר פ\"ז, וביאר שם לפי\"ז שביום ל\"ג בעומר נתגבר שם של רחמים ופסקו מלמות תלמידי רבי עקיבא, ע\"ש וע\"ע בלקו\"ת לישעיה אות כ\"ו).","b":false},{"t":"[א\"ה - ברגלי הקדושים אעבורה ואימא בה מילתא, דהנה מצינו כתוב (ירמיה יז, ז), ברוך הגבר אשר יבטח בה' והיה ה' מבטחו. והנה מילת \"והיה\" הוא אותיות הוי\"ה שהן מסובבות את האדם, כשהוא בוטח בה' ואז הוא מסובב לגמרי בחסד, כמו שנאמר (תהלים לב, י), והבוטח בה' חסד יסובבנו, היינו שהכל מסביבו נהיה חסדים גמורים, ואין שום דינים ח\"ו והכל רחמים פשוטים.","b":false},{"t":"אמנם ע\"י שם אכדט\"ם הרי הוא ממתק לגמרי הגבורות דשם אלהים וזה יותר טוב מחסדים פשוטים דמעיקרא, והוא מה שנאמר, והיה ה' [הוי\"ה] מבטחו, כי ע\"י בטחון הוא זוכה לשם אכדט\"ם שהוא חילוף שם אלהים, וזוכה למתק הדינים לגמרי והכל נהפך לחסדים גמורים שזה יותר טוב מרחמים פשוטים דמעיקרא. ואמרתי לפרש בזה את מאמה\"כ (תהלים כו, א), ובה' בטחתי לא אמעד, היינו כי אחר שיש בטחון אין עוד גבורות כלל, אלא הכל רחמים גמורים, והנה אותיות אל\"ף ומ\"ם הראשונות ממילת \"אמעד\" הם אותיות אל\"ף ומ\"ם דאלהים שלא מתחלפות, ואותיות עי\"ן דל\"ת של מילת \"אמעד\" היינו ע - ד שהם גימ' אכדט\"ם שהוא שם הבטחון, והיינו שאין שום פתחון פה עוד למדת הדין והכל נהפך לחסדים גמורים. וזה אמרו, ובה' בטחתי לא אמעד, לא אמעד, היינו לא יש עוד שם אלהים שהוא גבורות ודינים הנרמז באותיות א - מ אלא רק \"עד\" שהוא בגימ' אכדט\"ם שהוא מיתוק כל הדינים. כי כיון שאני בוטח בהי\"ת זכיתי למתק הדינים לגמרי ע\"י שם אכדט\"ם, ולכן לא אמעד לעולם, והוא פלא.","b":false},{"t":"ואגב אודיעך כי בכונת כוס הראשון של ליל הסדר מכונים בשם אכדט\"ם שהוא בגימ' יין שהוא ע' עם חמשה אצבעות האוחזים בו הרי ע\"ה כמנין אכדט\"ם עם הכולל (ויעוי' באורך בשעה\"כ דרושי פסח דרוש ו' ופע\"ח שער חג המצות ח\"ב), ונראה דיש בזה עוד ענין, שכיון ששם אכדט\"ם הריהו ממתק את הדינים ממילא ראוי לכוין בתחילה על היין שהרי היין הוא גבורות כידוע, ומתמתק ע\"י תוספת ה' אצבעות שמוסיפים על גימ' יין וכל אצבע ממתק אות אחת משם אלהים ע\"י שנשלם לבסוף לשם אכדט\"ם שהוא ממתיק את הגבורות דשם אלהים, ואכמ\"ל.","b":false},{"t":"וכבר נאמר (תהלים ט, יא), ויבטחו בך יודעי שמך וגו' היינו שהיודעים בשמותיו יתברך, אינם מתיראים משמות דגבורה ודינים, כי תרופתם בצדם, שע\"י הבטחון ממתיקין את הדינים וע\"י בטחון מהפכים את הדין לרחמים שזה יותר טוב מרחמים מפשוטים דמעיקרא. וזהו \"ויבטחו בך\" יודעי שמך, שע\"י שהם בוטחים, אין להם מה לחוש מגבורות כי הכל נהפך לחסדים גמורים. יבח\"ר].","b":false},{"t":"ולהמבואר מובן למה יעקב אבינו ע\"ה עשה גל - עד, כי בכונה מכונת עשה כן, כדי לחזק את בטחונו בהי\"ת, כנגד לבן ובניו, וגם כדי לחזק בטחונו בהי\"ת ולא להתיירא מפני עשו אחיו, ולהראות שאינו ירא מרדיפתם, כי יעקב אבינו ובניו שמים את כל בטחונם בהי\"ת צור עולמים.","b":false},{"t":"(בעהית\"ש ערש\"ק מקץ נר חמישי דחנוכה - כ\"ט כסלו ער\"ח טבת התשס\"ו)","b":false}]},{"id":"18","t":"כבוד חכמים ינחלו – כבוד תורה הוא הכבוד האמיתי","p":[{"t":"וַיִּשְׁמַע אֶת דִּבְרֵי בְנֵי לָבָן לֵאמֹר לָקַח יַעֲקֹב אֵת כָּל אֲשֶׁר לְאָבִינוּ וּמֵאֲשֶׁר לְאָבִינוּ עָשָׂה אֵת כָּל הַכָּבֹד הַזֶּה: (לא, א)","b":true},{"t":"ואונקלוס תרגם, את כל הכבוד - ית כל נכסיא האלֵין. ויונתן בן עוזיאל תרגם, ית כל יקר נכסיא האלין. ולשניהם, כיונו בני לבן. אלא שבתרגום יונתן בן עוזיאל הוסיף תיבת \"יקר\", שזה תרגום המלה כבוד. ואונקלוס השמיטה. והרשב\"ם ז\"ל פירש, הכבוד, עוצם ממון, כמו ואברם כבד מאד במקנה בכסף ובזהב (בראשית יג, ב). עכ\"ל. ונראה דהוא מפרש תיבת כָּבֹד הנזכרת כאן, מלשון כָּבֵד בלבד, אשר ענינו הכבדת הממון והעצמתו, ואין כאן ענין של כבוד ויקר, והוא כתרגום אונקלוס.","b":false},{"t":"ושמעתי בשם הגר\"א מוילנא ע\"ה, שבדק בכל התנ\"ך ומצא, שכל מקום שמדובר בכבוד אמיתי, שהוא כבוד התורה נכתבה תיבת \"כבוד\", מלאה וא\"ו כמו שנאמר (משלי ג, לה), כבוד חכמים ינחלו, שמילת כבוד מלאה וא\"ו. אמנם כשמדובר בכבוד המדומה מעניני העוה\"ז, שהוא אך דמיון ותעתועים נכתבה תיבת \"כבֹד\" בלא וא\"ו, כמו כאן.","b":false},{"t":"והרב רי\"ב חרר נר\"ו הקשה על דברי השמועה הזאת, דהא מצינו במ\"א ג, יג ונתתי לך גם עושר גם כבוד, וכן בישעיה טז, יד ונקלה כבוד מואב, וכן באסתר ה, יא ויספר להם המן את כבוד וגו', וכולם מלאים בוי\"ו. ואולי כונת השמועה הוא דוקא על מילות כבוד הנאמרות בתורה, עכת\"ד.","b":false},{"t":"ויש מקום אתי ליישב כל המקומות הנ\"ל, דמה שנאמר \"ונתתי לך גם עושר גם כבוד\". הכי קאמר, גם עושר העוה\"ז וגם כבוד של תורה שבו תלוים חיי העוה\"ב. ומה שנאמר \"ונקלה כבוד מואב\". הכי קאמר, שהם מתפארים שיש להם כבוד אמיתי, אך הי\"ת אומר ונקלה כבוד מואב, היינו ש\"כבוד מואב\" נקלה הוא, ואינו הכבוד האמיתי. ומה שנאמר ויספר להם המן את \"כבוד\" וגו'. היינו, שהמן הרשע היה אומר שיש לו גם עושר וגם בנים, וגם כבוד רוחני אמיתי, וכדרך הגבירים העשירים שרוצים להתפאר במעמד רוחני גדול. כנלענ\"ד.","b":false},{"t":"ובזה פירש הרה\"ק מקאמרנא ע\"ה בספר היכל הברכה את מאמר יוסף לאחיו (בראשית מה, יג), והגדתם לאבי את כל כבודי בארץ מצרים, תיבת \"כבודי\" מלאה וא\"ו ללמד, שנתמלא הכבוד מן יוסף צדיק יסוד עולם, ואין בכל התורה כבוד אדם מלא חוץ מזה. ע\"ש. וראינו שאין ענין הכבוד ההוא כבוד גשמי, אלא כבוד מסטרא דקדושה, שבא ליוסף מחמת קדושתו וצדקתו.","b":false},{"t":"וכבר כתבתי בכמה מקומות (ראה בהקדמת שמע שלמה ח\"א ובספרנו זה פר' חיי שרה מאמר ג ופרשת תולדות מאמרים ח, יג ופר' וישב מאמר ב ופרשת ויחי מאמר יז), שהאות וא\"ו היא בחינת התורה הקדושה, והיינו ענינו, כלומר, כשהכבוד מחובר לתורה הקדושה, אז יש בו וא\"ו, ואם נחסר ממנו אות וא\"ו סימן מובהק הוא שלא מדובר בכבוד תורה ובכבוד אמת, אלא בהבלי העולם.","b":false},{"t":"ובני לבן לא ידעו ולא רצו לדעת ממעלותיו הרוחניות של יעקב אבינו ע\"ה, וכל עינם היתה על הממון לבדו, וע\"ז היו מתרעמים כאן באומרם, ומאשר לאבינו עשה את כל ה\"כבד\" הזה, שכל ענינם אך ורק בכבוד הגשמי שהוא חסר. ורמז גדול למדנו בזה דכשאין וא\"ו החיבור המחבר את האדם לתורה ולהי\"ת, אזי גם כבוד אין שם, רק הבל ודמיון, כי חן וכבוד יתן ה' (תהלים פד, יב), והוא נותנו לדבקים בו האוחזים בתורתו.","b":false}]},{"id":"18","t":"כח התפלה כשהיא באה מתוך לב נשבר","p":[{"t":"וַתַּהַר לֵאָה וַתֵּלֶד בֵּן וגו', וַתַּהַר עוֹד וַתֵּלֶד בֵּן וגו', וַתַּהַר עוֹד וַתֵּלֶד בֵּן וגו', וַתַּהַר עוֹד וַתֵּלֶד בֵּן וַתֹּאמֶר הַפַּעַם אוֹדֶה אֶת ה' עַל כֵּן קָרְאָה שְׁמוֹ יְהוּדָה וַתַּעֲמֹד מִלֶּדֶת. (בראשית כט, לב-לה), וַתֵּרֶא רָחֵל כִּי לֹא יָלְדָה לְיַעֲקֹב וַתְּקַנֵּא רָחֵל בַּאֲחֹתָהּ וַתֹּאמֶר אֶל יַעֲקֹב הָבָה לִּי בָנִים וְאִם אַיִן מֵתָה אָנֹכִי, וַיִּחַר אַף יַעֲקֹב בְּרָחֵל וַיֹּאמֶר הֲתַחַת אֱלֹהִים אָנֹכִי אֲשֶׁר מָנַע מִמֵּךְ פְּרִי בָטֶן: (ל, א-ב)","b":true},{"t":"ומצינו בדברי רבותינו (ראה ב\"ר עא, ז), שרחל אמרה ליעקב, הבה לי בנים, התפלל עלי לפני ה' כשם שעשה אביך לאמך, ויעקב ענה לה, אני איני כאבא, אבא לא היו לו בנים, אני יש לי בנים, וממך מנע ה' ולא ממני. וכן הוא בפירוש רש\"י ז\"ל (שם).","b":false},{"t":"והדברים מתמיהים מאד, וכי מפני שיש ליעקב בנים מלאה, אינו חפץ להתפלל בעד רחל שגם לה יהיו בנים, והאם יש צד מחשבה לומר שמפני שהוא יש לו בנים מאשה אחרת, משום כך הוא אינו כאביו, ועל כן אינו צריך להתפלל עבורה. ופשוט דאין זה כפשוטו. צא וחשוב אם יבא חשוך בנים לפני איזה צדיק ויבקש ממנו ברכה שיזכה לבנים, והצדיק יענהו, לי יש בנים ב\"ה ולך אין, תתפלל אתה! וכן בעניני פרנסה או שאר ענינים היתכן כדבר הזה בעולם.","b":false},{"t":"וכבר עמד ע\"ז רבנו הרמב\"ן ז\"ל בפירושו לתורה (בראשית ל, א), וז\"ל, ואני תמה, אם כן למה חרה אפו, ולמה אמר התחת אלהים אנכי, ושומע אל צדיקים ה' ומה שאמר יעקב, אבא לא היו לו בנים אני יש לי בנים, ממך מנע ממני לא מנע. וכי הצדיקים אינן מתפללים בעד אחרים, והנה אליהו ואלישע התפללו בעד נשים נכריות (מ\"א יז, כא, ושם ב' ד, טז). ונראה שבשביל זה תפסוהו רבותינו, ואמרו בבראשית רבה (עא, ז), אמר לו הקב\"ה כך עונין את המעיקות, חייך שבניך עתידין לעמוד לפני בנה וכו'. והאריך ליישב את הענין לפי הפשט, יעו\"ש.","b":false},{"t":"ואילולי דב\"ק של הרמב\"ן ז\"ל היה נראה דשני ענינים נזכרו במדרש. דמה שאמר הקב\"ה ליעקב כך עונין את המעיקות, הוא על שחרה אפו בה, ואמר לה התחת אלהים אנכי וגו'. שהיה לו להשיבה אמירה נעימה ורכה, להשיב נפשה ולפייסה בנועם אמריו, והוא דיבר עמה קשות בעת צערה, על זה אמר לו, \"וכי כך עונין את המעיקות\" אבל מה שאמר יעקב לרחל אני אינני כאבא, עדיין צריך הבנה, שהרי לא רק למעיקות אין צריך לענות כן, אלא אפילו לאדם שש ועליז אין עונין כן, וכיצד יתכן שעלתה על לב יעקב אבינו ע\"ה להשיבה מילין קשים כגידין, היורדות לחדרי הלב ודוקרות אותו כמדקרות חרב. וזה לא יתכן להאמר בשום אופן על יעקב אבינו בחיר שבאבות.","b":false},{"t":"והנה ידוע מאמר חז\"ל (ראה יבמות סד, א ושהש\"ר ב, מא ותנחומא תולדות פ\"ט), שאמרו, למה היו אבות האומה ונשותיהם עקרים, משום שהקב\"ה מתאוה לתפילתם של צדיקים. וכבר הקשו על זה כמה מבעלי המוסר שצריכים להבין את מאמר חז\"ל הנז', וכי אם לא יהיו האבות עקרים לא יתפללו. ותירצו, דאינה דומה תפלה של לב נשבר ונדכה, לתפלה של אדם שהוא נמצא במצב טוב.","b":false},{"t":"כי התפלה של בעל לב נשבר בוקעת ויוצאת מקירות לבו וממעמקים יקרא אל ה', מה שאין כן במי שנמצא במצב טוב. וזהו שביקש דוד המלך ע\"ה, להתפלל תפלת עני, באומרו (תהלים פו, א ואילך), תפלה לדוד הטה ה' אזנך ענני כי עני ואביון אני, שמרה נפשי כי חסיד אני וגו'. ובזהר הקדוש אמרו (פרשת בלק, ח\"ג קצה, א), וז\"ל, אבל תלתא אינון דאיקרון תפלה, תפלה למשה וכו', תפלה לדוד וכו', תפלה לעני, מאן חשיבא מכולהו, הוי אימא תפלה דעני, תפלה דא קדים לתפלה דמשה, וקדים לתפלה דדוד. וקדים לכל שאר צלותין דעלמא. מאי טעמא, בגין דעני איהו תביר ליבא, וכתיב (תהלים לד, יט), קרוב ה' לנשברי לב וגו', ומסכנא עביד תדיר קטטה בקודשא בריך הוא, וקודשא ב\"ה אצית ושמע מילוי וכו'. ונתבאר עוד שם שתפלת העני מתקבלת לפני כל שאר התפלות כיעו\"ש (ועי' עוד בזוהר ח\"א כג, ב ושם קסח, ב וח\"ב פו, ב ובח\"ג ברע\"מ רעג, ב).","b":false},{"t":"עוד איתא שם, משה צלי צלותיה ואתעכב כמה יומין וכו', דוד חמא דכל כוין וכל תרעי שמיא, כולהו זמינין לאפתחא למסכנא וכו', כיון דחמי האי, עבד גרמיה עניא ומסכנא, ופשט לבושא דמלכותא ויתיב בארעא כמסכנא, אמר תפלה, דכתיב, תפלה לדוד הטה ה' אזנך ענני, ואי תימא אמאי, בגין כי עני ואביון אני, אמר ליה קודשא ב\"ה, דוד, ולאו מלכא את ושליט על מלכין תקיפין, ואת עביד גרמך עני ואביון, מיד אהדר צלותיה בגונא אחרא, ושבק מלה דאביון ועני, ואמר שמרה נפשי כי חסיד אני, ועם כל דא כלא הוה ביה בדוד. עכלה\"ק. והנה ראינו שתפלת העני היא החשובה והמעולה שבתפילות, עד שדוד המלך פשט את בגדי מלכותו ולבש בגדי עוני, וישב על הארץ כדי להתפלל, והקב\"ה אמר לו אינך עני ואביון, ולמה אתה מתפלל כעני, ואז חזר דוד ואמר \"שמרה נפשי כי חסיד אני\".","b":false},{"t":"וצריך להבין למה אמר לו הקב\"ה לדוד למה תעשה עצמך עני ואביון, והרי אתה מלך וכו', והרי דוד בחר להתפלל תפלת עני ופשט את בגדי המלכות וישב על הארץ, להתפלל והתחנן כעני ואביון, ומה פסול יש בתפלה זאת.","b":false},{"t":"וצ\"ל דכיון שהי\"ת שמו אמת, ודובר שקרים לא יכון לנגד עיניו, ע\"כ אמר לדוד שאין זה נכון שיתפלל כעני כשאין הדבר כן. ועוד, כי העני לבו שבור מחמת העוני שמדכאו ומשפילו עד עפר, ולבו נשבר בקרבו, ומתוך המשבר הזה הריהו צועק אל ה' בצערו וכאבו, וצעקתו זאת שיוצאת מנאקת לבו, עמוק עמוק מקירות הלב ממש, ורחמנא לבא בעי (סנהדרין קו, ב), ותפלה היוצאת מעומק הלב באמת היא העולה לפני המקום ופותחת לפניו את כל החלונות והשערים. אבל כשאין הרגשת כאב בעומק הלב מתוך צור ומצוק אמיתי, לעולם לא יגיע אדם לאותם עמקים, ולאותו כח תפלה מיוחד שטמון בתפלתו של העני, ולעולם אי אפשר להגיע לאותו עומק כי אם בהיות המתפלל עני ואביון אמיתי, ודוד המע\"ה לא יכל להגיע לזה בעת מלכותו.","b":false},{"t":"ובזה יובן למה היו האבות והאמהות עקורים, והרי בלא\"ה גם היו מתפללים, אלא מכאן שהקב\"ה רוצה תפלות העולות מעומק הלב ממש, ולזה אמרו רבותינו (יבמות סד, א), כי הקב\"ה מתאוה לתפלתן של צדיקים, כי ע\"י שהיו האמהות עקרות, התפללו מתוך השברון הגדול הזה כי עני חשוב כמת, וכן מי שאין לו בנים חשוב כמת כמו שנאמר ואם אין מתה אנכי, ואמרו רבותינו (ב\"ר עא, ו), מכאן למי שאין לו בנים שחשוב כמת.","b":false},{"t":"והנה ע\"י הרגשת הכאב הזאת עולה התפלה מעומק שכזה, ובוקעת את כל המחיצות ושוברת את כל החומות, ומגעת עד לפני המקום ב\"ה, ואעפ\"י שגם אם לא היו האמהות עקרות, בכל זאת לא היו חדלות מלהתפלל ולהתחנן לפי ה' ב\"ה, יומם ולילה לא ישבותו. מכל מקום, אינה דומה לתפלה זו, ואע\"ג דבאמהות הקדושות עסקינן, אין זה דומה לתפלה היוצאת מלב נשבר.","b":false},{"t":"ובזה יובן היטב מאמרו של יעקב אבינו ע\"ה לרחל, \"אני אינני כאבא, לאבא לא היו בנים לי יש בנים\", היינו, שבודאי יעקב אבינו התפלל על רחל יומם ולילה, ומסתמא שגם היא ידעה מזה בלא שום ספק, רק אמרה ליעקב, הבה לי בנים, כלומר אני יודעת שאתה צדיק ואם תתפלל בכל לבך ודאי שהקב\"ה ישמע תפלתך, ותפלת אביך תוכיח, שנעתר לו ה', ותהר רבקה אשתו. ועל כן הנני דורשת ממך \"הבה לי בנים\", כלומר, אני רוצה תפלה כזאת שתביא לי בנים. וע\"ז השיב יעקב אבינו ע\"ה לרחל, \"התחת אלהים אני\", וכי מי אני שאוכל להבטיח שתתקבל תפלתי, ומה שאמרת שאעשה כאבא, אני איני כאבא, אשר הוא עצמו היה חשוך בנים, ואני לא, ועל כן אינני יכול להגיע לעולם לאותה עמקות ולאותה דרגה של תפלה אשר רק לב נשבר ונדכא מסוגל להגיע עד שם, ובזה גם רמז יעקב לרחל שתתעצם בתפלתה, וזה שאמר לה, \"ממך מנע ולא ממני\". כלומר, את יכולה להגיע לתפלה מעומק הלב ולא אני. ולמדנו מזה עוד באגב, ששברון הלב בתפילה גדול מזכות אבות.","b":false},{"t":"אשרי משכיל אל דל","b":true},{"t":"ומה שהקפיד הקב\"ה על יעקב ואמר לו, \"וכי כך עונים למעיקות\". הוא על שהקשה יעקב את דברו לרחל. כי אע\"ג שיעקב אבינו ע\"ה צדק בכל דבריו, מ\"מ, היה צריך להשיבה באמירה רכה ונעימה, בדברים המפייסים, וגדול המפייס (עי' לדוגמא ב\"ב ט, ב). ולכן מצינו שלא אמר הקב\"ה ליעקב שאינו צודק בדבריו, אלא רק אמר לו מדוע ענית כך לרחל וכי כך עונין את המעיקות. כי בשעת צרה צריך חכמה איך להשיב דברים המיישבים את הלב.","b":false},{"t":"ושמעתי בזמנו מהגה\"צ המפורסם כקש\"ת רבי רפאל ברוך טולידאנו ע\"ה אב\"ד מקודש דעי\"ת מכנאס, שהיה מפרש את הפסוק בתהלים (תהלים מא, ב), אשרי משכיל אל דל ביום רעה ימלטהו ה'. דלכאורה הוה ליה למימר, אשרי תומך בדל, או אשרי עוזר לדל, אבל מה שייך לשון \"השכלה\" בזה.","b":false},{"t":"ופירש הוא ז\"ל, שהדל אין דעתו מיושבת עליו, כי העניות מעבירה את האדם על דעתו, וכשהאדם מפייסו ומדבר על לבו, הריהו מחזיר לו את דעתו וחכמתו למקומה, ולזה אמר, אשרי משכיל אל דל. ושכרו עמו, ביום רעה ימלטהו ה' ומלבד זאת זוכה לאחד עשר ברכות המפורשות מפי רבותינו כמבואר במסכת בבא בתרא (ט, ב וראה מה שנתבאר בזה עוד להלן פר' ויחי מאמר כה).","b":false},{"t":"וזו הדרישה שהיתה מיעקב אבינו, ועל זה הוכיחו הקב\"ה, לאמר, כך עונין למעיקות. אבל לגופם של הדברים הצדק עמו. רק שהיה צריך להשיב לרחל בלשון רכה ובאמרי נועם.","b":false},{"t":"* * *","b":false},{"t":"בהדי דכבשי רחמנא למה לך","b":true},{"t":"עוד, יש לפרש את הענין הזה, דכשראתה רחל אמנו ע\"ה שאחותה לאה כבר ילדה בן רביעי ליעקב, ולא עוד אלא זכתה בְּלֵוִי, שממנו יצאו כהנים ולויים, וממנו יצאו משה ואהרן וכל קדושים עמם, והוסיפה וזכתה גם ביהודה שממנו יוצאת שושלת המלוכה, וממנו דוד המלך, וממנו מלך המשיח. אז, \"ותקנא רחל באחותה\". ובאה אל יעקב בטענה, שהוא יעדה לו להיות עקרת הבית, עיקרה של הבית, ועתה נהפכה לעקרה בבית.","b":false},{"t":"ועיקר קנאתה של רחל היה במעשיה הטובים של לאה וכמאמר רבותינו (ב\"ר עא, ו), שאמרה רחל אלולי שצדקה לאה ממני לא זכתה לבנים, וכן הוא בדברי רש\"י.","b":false},{"t":"ואולי טענת רחל ליעקב היתה \"הבה לי בנים\", כלומר, הלא אתה הבטחתני שאהיה עיקרו של בית, וא\"כ למה לא יצאו ממני המלכות והכהונה, והיתה לה תרעומת עליו, כי הוא נביא ויודע, ואיך הבטיחה להיות היא עקרת הבית, ולא נתקיים בה.","b":false},{"t":"ויעקב אבינו השיבה, \"התחת אלהים אנכי\", היינו, כי אלו דברים שהם \"כבשי דרחמנא\" ואין מי שידעם, רק האלהים לבדו, וזהו אומרו, התחת אלהים אנכי, כלומר, כן היו מחשבותי שאת תהיי עקרת הבית, אבל אין הדבר מסור בידי, רק לו נתכנו עלילות.","b":false},{"t":"וכן אמר ישעיהו הנביא לחזקיה מלך יהודה, שלא רצה לשאת אשה משום שראה שעתידין לצאת ממנו עובדי עבודה זרה, ואמר לו ישעיה (ראה ברכות י, א), מאי דמפקדת עביד, ובהדי כבשי דרחמנא למה לך. ע\"ש. כי אין שום בריה בעולם שיכולה להכניס את ראשה לענינים אלו, לדעת את חשבונותיו יתברך אשר לו לבדו נתכנו עלילות. ואין הדבר תלוי במעשים בלבד, אלא הרבה חשבונות יש לו להקב\"ה אשר הוא מביט וצופה עד סוף כל הדורות.","b":false},{"t":"ואפשר שיעקב אבינו כעס על רחל כי תלתה את חסרון הבנים בחוסר צדקתה, ופירש לה דלאו בזה לבד תליא מילתא, ויש לו להקב\"ה חשבונות עמוקים, ולא כמחשבותיו מחשבותינו, ושלא תוסיף להצטער גם על זה.","b":false},{"t":"ואעפ\"י שמחשבתו היתה אך ורק לטובתה, מכל מקום התרעם עליו הקב\"ה, ואמר לו, שלא כך עונים למעיקות, וצריך לבחור לשון למודים שיש בו כדי לפייסה, ויאמר את הדברים באמירה רכה ונעימה. כי לא די בצדקת הדברים, אלא צריך גם להלבישם בלבוש טוב ונעים ככל האפשר.","b":false}]},{"id":"18","t":"חילוף רחל בלאה מאת הי\"ת לטובת עם ישראל","p":[{"t":"וַיֹּאמֶר לָבָן לְיַעֲקֹב הֲכִי אָחִי אַתָּה וַעֲבַדְתַּנִי חִנָּם הַגִּידָה לִּי מַה מַּשְׂכֻּרְתֶּךָ וגו', וַיֶּאֱהַב יַעֲקֹב אֶת רָחֵל וַיֹּאמֶר אֶעֱבָדְךָ שֶׁבַע שָׁנִים בְּרָחֵל בִּתְּךָ הַקְּטַנָּה: (כט, טו-יח)","b":true},{"t":"ראינו שיעקב אבינו נותן ללבן שלשה סימנים המורים על חפצו לשאת לו לאשה דוקא את רחל בת לבן וכה אמר, אעבודך שבע שנים. א, ברחל. ב, בתך, היינו דוקא רחל בת לבן ולא רחל בת איש אחר. ג, הקטנה, שלא יחליף את שם בתו ויקרא לה בשם אחר, לכן אמר הקטנה, וכן מפורש בדברי רבותינו (ב\"ר ע, יז), וכ\"כ רש\"י ז\"ל (שם), וז\"ל ברחל בתך הקטנה, כל הסימנים הללו למה, לפי שהיה יודע בו שהוא רמאי. אמר לו, אעבודך ברחל, ושמא תאמר רחל אחת מן השוק. תלמוד לומר, בתך. ושמא תאמר, אחליף ללאה שמה, ואקרא שמה רחל. תלמוד לומר, הקטנה. ואעפ\"כ לא הועיל לו, שהרי רמהו. עכ\"ל.","b":false},{"t":"ויש להבין אחר שיעקב אבינו ע\"ה הכיר כל כך יפה את לבן, עד שהעלה על דעתו, שיכול להביא לו רחל אחרת מן השוק, ועוד שחשב שישנה את שם לאה לשם רחל שהם דברים רחוקים כל כך, א\"כ איך לא חשב ביום חתונתו שלבן יעמיד לו את לאה במקום רחל.","b":false},{"t":"אמנם באמת מצינו שיעקב חשב גם על זה, ועל כן מסר סימנים מיוחדים לרחל, אלא שרחל מסרתם ללאה, כי כשראתה רחל שמכניסין ליעקב את לאה, אמרה, עכשיו תכלם אחותי, עמדה ומסרה לה אותן סימנים, והוא שנאמר (בראשית כט, כה), ויהי בבוקר והנה לאה, ומשמע, שבלילה לא הכיר יעקב בלאה, כי רחל נתנה לה את סימניה. כאשר מפורש כל זה בדברי רבותינו (מגילה יג, ב ב\"ב קכג, א). וכ\"כ רש\"י בפירושו לתורה (שם). ואין ספק שגם מדת הצניעות המופלגת שהיתה נחלת אבותינו עד הדור האחרון, וק\"ו בן בנו של ק\"ו הצניעות שהיתה לסבא קדישא בחיר האבות יעקב אבינו ע\"ה, בודאי שגם זה היה טורד את מחשבתו, עד שמקשה עליו לשום את עיני שכלו לתחבולות לבן הארמי.","b":false},{"t":"ונראה שבודאי מאת ה' היתה זאת שישא יעקב אבינו גם את לאה, שהרי ידוע שאין אלו סתם נישואין, אלא בנין העולם ובנין בית ישראל, שעליו נצבים כל העולמות, והוא תיקון רחל ותיקון לאה.","b":false},{"t":"ובודאי שגם פרט זה היה מחושב מאתו יתברך, שימסור יעקב לרחל סימנים מיוחדים לרוב רמאותו של לבן, וניתנה בזה הזדמנות לרחל, להציל את אחותה מבושה גדולה כזאת, ע\"י שמסרה לה את אותם סימנים. ובזה יש פתחון פה לרחל אמנו לפני הקב\"ה בעת שהגלה את ישראל מארצם בעוון עבודה זרה, כי בעת ההיא הכל באים לפייס כביכול את הקב\"ה ואינו מתפייס, אך רחל היא זו שמצליחה לפייסו, כאשר אמרו רבותינו (פתיחה לאיכ\"ר פסקא כד), באותה שעה קפצה רחל אמנו לפני הקב\"ה ואמרה, רבש\"ע, גלוי לפניך שיעקב עבדך אהבני אהבה יתירה ועבד בשבילי לאבא שבע שנים. וכשהשלימו אותן שבע שנים והגיע זמן נשואי לבעלי, יעץ אבי להחליפני לבעלי בשביל אחותי, והוקשה עלי הדבר עד מאד, כי נודעה לי העצה, והודעתי לבעלי, ומסרתי לו סימן שיכיר ביני ובין אחותי, כדי שלא יוכל אבי להחליפני, ולאחר כן נחמתי בעצמי, וסבלתי את תאותי, ורחמתי על אחותי שלא תצא לחרפה, ולערב החליפו אחותי לבעלי בשבילי, ומסרתי לאחותי כל הסימנין שמסרתי לבעלי, כדי שיהא סבור שהיא רחל. ולא עוד, אלא שנכנסתי תחת המטה שהיה שוכב עם אחותי, והיה מדבר עמה והיא שותקת, ואני משיבתו על כל דבר ודבר [במקומה], כדי שלא יכיר לקול אחותי, וגמלתי חסד עמה ולא קנאתי בה, ולא הוצאתיה לחרפה. ומה אני שאני בשר ודם, עפר ואפר, לא קנאתי לצרה שלי, ולא הוצאתיה לבושה ולחרפה, ואתה מלך חי וקיים רחמן מפני מה קנאת לעבודת כוכבים שאין בה ממש, והגלית את בני ונהרגו בחרב, ועשו אויבים בם כרצונם. מיד נתגלגלו רחמיו של הקדוש ברוך הוא, ואמר, בשבילך רחל אני מחזיר את ישראל למקומן, הדא הוא דכתיב (ירמיה לא, יד-טז), כה אמר ה' קול ברמה נשמע נהי בכי תמרורים רחל מבכה על בניה מאנה להנחם על בניה כי איננו, וכתיב, כה אמר ה' מנעי קולך מבכי ועיניך מדמעה כי יש שכר לפעולתך וגו', וכתיב ויש תקוה לאחריתך נאם ה' ושבו בנים לגבולם. ע\"כ.","b":false},{"t":"ומצינו עוד (אגדת בראשית פנ\"ב), למה מתה רחל בדרך אפרת, אלא כך אמר הקב\"ה, בני צריכין לה בשעה שהם חוטאין וגוזלין והיא מזכרת אותי, כשם שזכרתיה אני. שנאמר, כה אמר ה' קול ברמה נשמע וגו', אמר לה מנעי קולך מבכי. ומה שכר יש לה על שנקצרו ימיה ומתה בדרך. כדי שתזכור אותי על בני, שנאמר, כי יש שכר לפעולתך נאם ה' וגו' ושבו בנים לגבולם.","b":false},{"t":"והיינו שהנסיון המופלא הזה שעמדה בו רחל, הוא זה שנותן לה את הכח לטעון בעוז לפני הקב\"ה ולקרב קץ ישועתינו, בב\"א.","b":false}]},{"id":"18","t":"יעקב והבאר והצאן - כנגד הצדיק והתורה וישראל","p":[{"t":"וַיִּשָּׂא יַעֲקֹב רַגְלָיו וַיֵּלֶךְ אַרְצָה בְנֵי קֶדֶם, וַיַּרְא וְהִנֵּה בְאֵר בַּשָּׂדֶה וְהִנֵּה שָׁם שְׁלשָׁה עֶדְרֵי צֹאן רֹבְצִים עָלֶיהָ כִּי מִן הַבְּאֵר הַהִוא יַשְׁקוּ הָעֲדָרִים וְהָאֶבֶן גְּדֹלָה עַל פִּי הַבְּאֵר, וְנֶאֶסְפוּ שָׁמָּה כָל הָעֲדָרִים וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר וְהִשְׁקוּ אֶת הַצֹּאן וְהֵשִׁיבוּ אֶת הָאֶבֶן עַל פִּי הַבְּאֵר לִמְקֹמָהּ, וַיֹּאמֶר לָהֶם יַעֲקֹב אַחַי מֵאַיִן אַתֶּם וַיֹּאמְרוּ מֵחָרָן אֲנָחְנוּ, וַיֹּאמֶר לָהֶם הַיְדַעְתֶּם אֶת לָבָן בֶּן נָחוֹר וַיֹּאמְרוּ יָדָעְנוּ, וַיֹּאמֶר לָהֶם הֲשָׁלוֹם לוֹ וַיֹּאמְרוּ שָׁלוֹם וְהִנֵּה רָחֵל בִּתּוֹ בָּאָה עִם הַצֹּאן, וַיֹּאמֶר הֵן עוֹד הַיּוֹם גָּדוֹל לֹא עֵת הֵאָסֵף הַמִּקְנֶה הַשְׁקוּ הַצֹּאן וּלְכוּ רְעוּ, וַיֹּאמְרוּ לֹא נוּכַל עַד אֲשֶׁר יֵאָסְפוּ כָּל הָעֲדָרִים וְגָלֲלוּ אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר וְהִשְׁקִינוּ הַצֹּאן, עוֹדֶנּוּ מְדַבֵּר עִמָּם וְרָחֵל בָּאָה עִם הַצֹּאן אֲשֶׁר לְאָבִיהָ כִּי רֹעָה הִוא, וַיְהִי כַּאֲשֶׁר רָאָה יַעֲקֹב אֶת רָחֵל בַּת לָבָן אֲחִי אִמּוֹ וְאֶת צֹאן לָבָן אֲחִי אִמּוֹ וַיִּגַּשׁ יַעֲקֹב וַיָּגֶל אֶת הָאֶבֶן מֵעַל פִּי הַבְּאֵר וַיַּשְׁקְ אֶת צֹאן לָבָן אֲחִי אִמּוֹ, וַיִּשַּׁק יַעֲקֹב לְרָחֵל וַיִּשָּׂא אֶת קֹלוֹ וַיֵּבְךְּ, וַיַּגֵּד יַעֲקֹב לְרָחֵל כִּי אֲחִי אָבִיהָ הוּא וְכִי בֶן רִבְקָה הוּא וַתָּרָץ וַתַּגֵּד לְאָבִיהָ: (כט, א-יב)","b":true},{"t":"הנה בענין יעקב והבאר יש אריכות בדברי רבותינו המפרשים, כל אחד לדרכו פנה, והרב כלי יקר (שם כט, ב), כתב, שחז\"ל (ב\"ר ע, ח-ט), פירשו את ענין הבאר בכמה אופנים, י\"א זה בית המקדש, וי\"א זה סיני, כי רבותינו רצו לפרש ענין הבאר והרועים שנזדמנו לו, מה באו לרמוז, יעו\"ש בדבריו.","b":false},{"t":"ואכן צריך להבין מה מלמדנו סיפור זה, ויש עוד קושיות ותמיהות, ונציין אחדים מהם.","b":false},{"t":"תחלה וראש, מהו ענין \"באר בשדה\", מה איכפת לן היכן הבאר נמצא, ומה נבין יותר אם נדע שהבאר הזאת היתה בשדה. דאם בא לרמוז על המקום, הרי עדיין לא ידענו שדה זה היכן היה. ועוד, והנה שם שלשה עדרי צאן, מה מלמדנו המספר של העדרים. ויותר קשה אומרו והאבן גדולה וכו', וכי לא די לכתוב ואבן גדולה, ולמה הוסיף בה אות ה\"א הידיעה [ועיין באור החיים הקדוש מש\"כ על קושיא זו]. ויותר קשה מה שנאמר אח\"כ, \"והשיבו את האבן על פי הבאר למקומה\", וכי לא ידענו שפי הבאר היא מקום האבן, ודי היה אם היה נכתב והשיבו את האבן למקומה, או והשיבו את האבן ע\"פ הבאר, ומהי תוספת הלשון \"למקומה\". וכן מה ששאל יעקב אבינו את הרועים, הידעתם את לבן בן נחור ולא אמר בן בתואל [ועי' בכלי יקר מש\"כ על קושיא זו]. וכן מה שיעקב אבינו הוכיח את הרועים באומרו הן עוד היום גדול, לא עת האסף המקנה השקו הצאן ולכו רעו, ומה ענינו בזה.","b":false},{"t":"ועד אחרון הגדיל מאי דכתיב \"ויגש יעקב ויגל את האבן מעל פי הבאר\". והנה רש\"י ז\"ל כתב, ויגש יעקב ויגל - כאדם שמעביר את הפקק מעל פי הצלוחית, להודיעך שכחו גדול. עכ\"ל. ומקורו בדברי רבותינו (ב\"ר ע, יב). וצריך להבין מה באה התורה לומר בזאת. האם בזאת יתהלל המתהלל (ראה ירמיה ט, כב-כג), ובפרט יעקב אבינו ע\"ה בחיר האבות, האם על זאת תהלתו שיודע להרים אבנים כבדות. וגם מש\"כ בזה רבינו האור החיים הקדוש ע\"ה (בראשית כט, ב), שבא הכתוב להודיע את העזר האלהי שבכח יעקב כיעו\"ש, מ\"מ עדיין לא יגהה מזור לשאלתנו מדוע היה צריך להודיע את הדבר הזה דוקא במעמד הזה.","b":false},{"t":"והנראה בס\"ד, שבא לרמז על המצב הרוחני של עם ישראל בדורות האחרונים, ואת קורות הדורות הללו הראה הי\"ת במחזה זה ליעקב אבינו ע\"ה. והנה ידוע ומפורסם שעיקר הבריאה אינה בשביל חיי העוה\"ז, כי אין העוה\"ז מטרה בפני עצמו, כי אם פרוזדור לעוה\"ב (כמבואר באבות ד, טז), והוא בבחינת הקדמה לעוה\"ב. וכל הנבראים נבחנים כאן בתחילה, ומכאן מקדמים מעשיהם לעולם הבא בטרם יבואו שמה, בבחינת והלך לפניך צדקך (ישעיה נח, ח), וזהו וישא יעקב רגליו וילך ארצה בני קדם. או ניתן לומר, שנשא רגליו והתקדם הלאה בכמה דורות, עד לבני קדם, לדור זה הקורא לעצמו דור מתקדם ופקח, והוא, \"בני קדם\".","b":false},{"t":"\"וירא והנה באר בשדה\", היא התורה הקדושה באר מים חיים, אשר היא בשדה, מונחת במקום שכל אדם יכול להגיע אליה ולהשיגה, וכמו שאמרו רבותינו (אדר\"נ פרק מ\"א ובדברי הרמב\"ם פ\"ג מהל' ת\"ת הלכה א), שכתר תורה שהוא החשוב מכל הכתרים מונח בקרן זוית וכל הרוצה יבא ויטלנו לעצמו. כי התורה הקדושה לא בשמים היא ולא מעבר לים (דברים ל, יב), ואינה ירושה, אלא היא במקום כזה שכולם שוים בו, ואין לאחד זכות בה יותר מחבירו, רק תלוי בבחירתו של כל אחד ואחד.","b":false},{"t":"\"והנה שם שלשה עדרי צאן רובצים עליה\", רומז לעם ישראל שהוא עם תליתאי (ראה שבת פח, א), כהנים, לויים, וישראלים, וכולם רובצים על התורה, ומצווים לשקוד על דלתותיה ולשמור כל מצוותיה וחוקותיה, והיא עץ החיים לכל נברא, כי מוצאי מצא חיים (משלי ח, לה).","b":false},{"t":"\"כי מן הבאר ההיא ישקו העדרים\" בא לרמוז גם על מנהיגי הדור ומוריו, המה הרועים את עדרי הצאן, כל מנהיג וצאן מרעיתו, שעליו להנחותם בדרך הנכונה ולישר את ליבותם, ולהחיות נפשם במים חיים, הם מי התורה, כי מן הבאר ההיא ישקו העדרים.","b":false},{"t":"* * *","b":false},{"t":"ויש לומר עוד, ד\"שלשה עדרי צאן\", רומז גם כן על מצבם הרוחני של ישראל, שכידוע נחלקים לשלשה, צדיקים, בינוניים, ורשעים. ולכאורה אין שום מניעה מכל אלו לבא וללמוד תורה, ולהתקרב אל הי\"ת מקור החיים, והדבר דומה אל הבאר הנמצאת בשדה והרוצה לשתות ולהחיות נפשו, יבא וישתה.","b":false},{"t":"אלא דא עקא \"והאבן גדולה ע\"פ הבאר\", רומז ליצר הרע, וכמ\"ש הנביא והסירותי את לב האבן מבשרכם ונתתי לכם לב בשר (יחזקאל לו, כו). ואף שבכל מצוה יש יצה\"ר המבקש למנוע מן האדם לעשותה, מ\"מ היצה\"ר של לימוד תורה קשה מכולם, כי כשם שמצוה זו היא כנגד כולם (כמבואר במתניתין ריש פאה א, א), ואין למעלה ממנה, כמו כן היצר הרע העומד עלינו למונענו ממנה קשה וגדול, וזה שנאמר \"והאבן גדולה\" האבן בה\"א הידיעה, שהיא היצר הרע הידוע, רובץ ע\"פ הבאר, כדי למנוע ולהרחיק, את כל מי שמתקרב אל הבאר להטהר ולהחיות את נפשו. כי יודע היצה\"ר שאם ישתו מהמים החיים, הוא כבר לא יוכל להם, שהרי כך אמרו חז\"ל (קדושין ל, ב בבא בתרא טז, א), \"בראתי יצה\"ר בראתי לו תורה תבלין\", אם אתם עוסקין בתורה אין אתם נמסרים בידו. ועל כן היצר הרע מרכז את כל כחו ועוצמתו, ובלבד שיוכל למנוע מן האדם שלא ישתה מים מן הבאר הזאת שהיא באר מים חיים, ואז ישאר תחת ידו.","b":false},{"t":"וכמו שעינינו רואות בעוה\"ר, כמה מתרחקים מהתורה ולימודה, עד שאפילו אנשים יראי שמים, רק מעטים מהם קובעים את עצמם ללימוד התורה, והיצר מטריד ומעסיק את האדם בעניני פרנסה ושאר ענינים, ולא מניח לו פנאי אפילו לזמן קל כדי שלא יחשוב ויתבונן במצבו.","b":false},{"t":"\"ונאספו שמה כל העדרים וגללו את האבן מעל פי הבאר והשקו את הצאן\", יעקב אבינו ע\"ה ראה בחזונו את הקורות אותנו בדור זה, שבכל השנה עוסק האדם בהבליו וחלומותיו, ורק באיזה ימים מיוחדים כמו יוה\"כ, או באיזה יום התעוררות מיוחד, אז נאספים כל העדרים, הן הם השלש כתות, צדיקים, בינוניים וכו', ואז במאמצים משותפים גוללים כולם יחד את האבן מעט מעט, ומשקים את הצאן, ומתעוררים בתשובה.","b":false},{"t":"ואמנם אם כל אחד ואחד ילבה את הניצוץ דקדושה שנתנוצץ בקרבו, כי אז הניצוץ הזה יהיה לאש שלהבת העולה על מוקד הקדושה והטהרה. ויהיה לו הדבר למקור חיזוק ועידוד לכל ימי השנה. ואולם יחידים הם הזוכים להיות יציבים במדריגה החדשה שהגיעו אליה זה עתה, בעת אַחֲזַתם התנוצצות דקדושה, אבל רבים נופלים מיד וחוזרים להרגלם כבתחילה, ותבאנה אל קרבנה ולא נודע כי באו אל קרבנה, ומראיהם רע כבתחילה, ועל זה אמר הכתוב \"והשיבו את האבן על פי הבאר למקומה\". שהגם שזכו וגללו את האבן ושתו מעט מהמים הללו, מכל מקום ע\"י מעשיהם, שוב הם משיבים את האבן על פי הבאר למקומה, ומתרחקים ממקור החיים ושבים למקומם הראשון כבתחילה, בלא שום שינוי בדרכם כלל, וזה שכתוב \"למקומה\".","b":false},{"t":"ואת האנשים האלה שואל יעקב ע\"ה \"אחי מאין אתם\"?, זכרו מאין באתם! וזכרו מהי סיבת ביאתכם לעולם, ולא תבואו לידי עבירה. אך הם כמשיבים דברים ויאמרו לו, מחרן אנחנו! עסוקים הננו וטרודים בחרון העולם, בטרדות הזמן וקשיי הפרנסה, ואין לנו לא זמן ולא כח לחשוב ולהתבונן, ולהתגבר ולהתרומם מכל עסקי העוה\"ז. ויען אבינו יעקב ויאמר להם, הידעתם את לבן בן נחור? והדגיש בשאלתו \"בן נחור\" ולא בן בתואל כי \"נחור\" אותיות \"חרון\", וזה כנגד מה שאמרו לו \"מחרן אנחנו\" ועסוקים בחרון העולם. והוא משיב ואומר להם, הנה גם מחרון יכולים להוציא דבר טוב ומלובן, אשר לזה רמז באמרו \"לבן\" בן נחור.","b":false},{"t":"וכדי שלא יאמרו הן כבר הורגלנו וגדלנו בדרכינו הרעה, ואיך נשוב ממנה עתה. לזה אמר להם \"הן עוד היום גדול\" לא עת האסף המקנה, כל עוד הנשמה בגוף אפשר עוד לתקן, וכמ\"ש חז\"ל (ראה ירושלמי חגיגה פ\"ב הלכה א וקה\"ר ז, טז), על הפסוק (תהלים צ, ג), תשב אנוש עד דכא ותאמר שובו בני אדם. היינו שהקב\"ה קורא אל האדם לשוב בתשובה אפילו כשהוא בסוף ימיו מדוכדך ונפשו עומדת לעזבו, גם אז הקב\"ה קורא ואומר \"שובו בני אדם\". ואחר שיעקב אבינו מסביר כל זאת, מהי התשובה.","b":false},{"t":"\"ויאמרו לא נוכל, עד אשר יאספו כל העדרים, וגללו את האבן מעל פי הבאר והשקינו הצאן\". אומרים אל יעקב אבינו הצדיק שמוכיחם, צודק אתה בדבריך, אך מ\"מ אין בנו את הכח והיכולת להלחם ביצה\"ר, כי הוא נדמה להם כהר תבור (ראה סוכה נב, א), עד שחושבים שאין בכחו של אדם יחיד לעמוד כנגדו ולהכניעו, עד אשר יאספו כל העדרים יחדיו, וגם אז לא יצליחו לגמרי להסיר את האבן בקלות, רק \"יגללו\" את האבן וכו'. וגם אחרי זה אמרו והשקו הצאן, ואחר כך, \"והשיבו\" את האבן על פי הבאר למקומה. כלומר, שגם אחר כל המאמץ המשותף, זוכים לשתות מעט מהמים, ומיד והשיבו את האבן ע\"פ הבאר למקומה, ושבים למעשיהם הראשונים בלא שום שינוי כלל ועיקר. ובראות יעקב כן, מיד.","b":false},{"t":"\"ויגש יעקב ויגל את האבן מעל פי הבאר וישק את צאן לבן אחי אמו\". ניגש יעקב אבינו שהוא הצדיק שבדור, להראות להם ולכל הדורות הבאים אחריהם, את הגבורה הרוחנית העילאית הטמונה בכל יהודי ויהודי. וכאשר יש לאדם רצון אמיתי, מיד יוכל להוציא את היצר הרע כמוציא פקק מן הצלוחית, ומובטח לו שהקב\"ה עוזרו, וכמו שראינו אצל אברהם אבינו, שנקרא אברהם העברי (בראשית יד, יג), שכל העולם היה מעבר אחד והוא היה מהעבר השני (כמבואר בב\"ר מב, ח), והצליח ועלתה בידו, ורבים השיב מעוון והכניסם תחת כנפי השכינה, וכמו שנאמר (בראשית יב, ה), ואת הנפש אשר עשו בחרן. והכל תלוי ברצונו של האדם, ומיד כשמחליט לצאת למלחמה הריהו מקבל את הסייעתא דשמיא הדרושה לו, ומתחזק בעוז ותעצומות, עד שרואה את היצה\"ר כחוט השערה ויכול לו.","b":false},{"t":"והיא היא הגבורה האמיתית והנצחית, גבורת הנפש והרוח, שנשארים ועומדים לו לאדם לנצח, וככל שיגדל ויזקין, הרי שכח זה הולך וגדל, הולך ומתחזק בקרבו, היפך הכח הגשמי שאינו אלא דבר חולף. ואשר על כן הולך וחסר הוא. והוא שאמרו רבותינו ז\"ל (אבות ד, א), איזהו גבור הכובש את יצרו. כי זו הגבורה האמיתית, וגבור כזה תמיד ישאר גבור. כי גבורה כזאת אינה חולפת עם הגיל ומקרי הזמן.","b":false},{"t":"וזה הוא כחו הגדול של סבא קדישא יעקב אבינו ע\"ה, ואותו הראה לבניו לדורות עולם, למען ידעו ויכירו בכחם וגבורתם, ולא יהיו בעיניהם כחגבים בעת המבחן והנסיון שמזמן להם היצה\"ר, אלא יכריזו נגדו מלחמה ולה' הישועה. ו\"מעשה אבות סימן לבנים\".","b":false},{"t":"(דרשה שדרשתי בביהכנ\"ס שער הרחמים כפר שלומי, שבת ויצא התשל\"ג. נכתב אור ליום ו' פר' ויצא ה' תש\"מ)","b":false}]},{"id":"18","t":"תפלה לאל חיי","p":[{"t":"וַיִּדַּר יַעֲקֹב נֶדֶר לֵאמֹר אִם יִהְיֶה אֱלֹהִים עִמָּדִי וּשְׁמָרַנִי בַּדֶּרֶךְ הַזֶּה אֲשֶׁר אָנֹכִי הוֹלֵךְ וְנָתַן לִי לֶחֶם לֶאֱכֹל וּבֶגֶד לִלְבֹּשׁ, וְשַׁבְתִּי בְשָׁלוֹם אֶל בֵּית אָבִי וְהָיָה ה' לִי לֵאלֹהִים, וְהָאֶבֶן הַזֹּאת אֲשֶׁר שַׂמְתִּי מַצֵּבָה יִהְיֶה בֵּית אֱלֹהִים וְכֹל אֲשֶׁר תִּתֶּן לִי עַשֵּׂר אֲעַשְּׂרֶנּוּ לָךְ: (כח, כ-כב)","b":true},{"t":"הנה העולם רגילים לפרש, לחם לאכול וגו', כלומר, שתתן לי לחם, וגם תתן לי את הבריאות שאוכל לאוכלו, וכן תן לי בגד, ולא שיהיה מונח בארון, אלא שאוכל ללבוש את הבגדים שתתן לי, ולצאת ולבא, והוא נכון ויפה.","b":false},{"t":"ועוד יש לומר, לחם לאכול, לא בשביל להרבות תאוות ותענוגות, רק לחם לאכול, כדי להתקיים, ועל דרך אומרם (אבות ו, ד), פת במלח תאכל. וכן בגד ללבוש, ולא מעבר לזה, אלא רק בגד שיוכל ללובשו כדי לצאת ולבא בין האנשים.","b":false},{"t":"ועוד מלמדנו הכתוב, כי גם כשמתפלל על דברים גדולים, כמו כאן שהקדים ואמר, אם יהיה אלהים עמדי וגו', היינו שביקש מהי\"ת והתפלל שינצל מאויביו מבקשי נפשו. ובכל זאת גם על הדברים הקטנים ביקש, לחם לאכול ובגד ללבוש. ומזה ילמד האדם לבקש על כל דבר ודבר, כדי לקבוע בלבבו שגם הדברים הקטנים ביותר באים רק מאתו יתברך.","b":false},{"t":"ועוד השלים יעקב את תפלתו באמרו, ושבתי בשלום אל בית אבי, והיה ה' לי לאלהים. שנראה שגם זה מן התפלה, שיזכה לשוב לבית אביו ויזכה להמשיך בעבודת ה', והנדר מתחיל בפסוק הבא, והאבן הזאת וגו' וכל אשר תתן לי עשר אעשרנו לך, והיינו שלעולם אדע שהכל משלך.","b":false}]},{"id":"18","t":"להשאר דבוק תמיד בחי החיים ולא להרדם בתרדמת הזמן","p":[{"t":"וַיִּיקַץ יַעֲקֹב מִשְּׁנָתוֹ וַיֹּאמֶר אָכֵן יֵשׁ ה' בַּמָּקוֹם הַזֶּה וְאָנֹכִי לֹא יָדָעְתִּי, וַיִּירָא וַיֹּאמַר מַה נּוֹרָא הַמָּקוֹם הַזֶּה אֵין זֶה כִּי אִם בֵּית אֱלֹהִים וְזֶה שַׁעַר הַשָּׁמָיִם: (כח, טז-יז)","b":true},{"t":"יש לומר שבא הכתוב לרמוז בזה לכל איש ואיש שיעורר עצמו, ויתנער מעפר הבלי העולם ורובי טרדות היצר הרע המעסיק את האדם ללא הרף, כדי להטרידו מן העולם, שלא ישאר לו זמן לחשבון נפשו ולהיטיב אחריתו. ומיד כשיקץ משנתו ותרדמת הזמן בה הוא מצוי, יראה מיד כי אכן יש ה' במקום הזה, ולא כל העולם הבל, אלא יש במקום הזה את האפשרות להשיג את ה' ולהתקרב אליו ולדָבְקה בו, ע\"י לימוד התורה וקיום מצוותיה, והעולם הזה הוא המקום היחידי בכל הבריאה להישגים כאלה, היום לעשותם ומחר לקבל שכרם (ראה עירובין כב, א וע\"ז ג, א ושם ד, ב).","b":false},{"t":"וזה אמרו \"ויקץ יעקב משנתו ויאמר אכן יש ה' במקום הזה\", אלא ש\"אנכי לא ידעתי\", משום שהייתי שקוע עמוק עמוק בשינה, וע\"כ לא ידע ולא היה מודע היכן הוא, ומה חובת האדם בעולמו, כי מרוב טרדות ורדיפת הבלי העולם, אינו חושב כלל.","b":false},{"t":"ואם יקיץ משנתו ויעמיק להתבונן כראוי, ירגיש בושה גדולה ויראה רבה מפני ה' והדר גאונו, והוא שנאמר בפסוק שאחריו, \"ויירא ויאמר\", ראה מה נותנים לנו קיום התורה והמצוות, הלא \"אין זה כי אם בית אלהים וזה שער השמים\", שע\"י הזכויות והמצוות זוכה שנפתחים לו שערי שמים לרווחה ונשמתו תתעדן בחלק הצפוי לצדיקים בעוה\"ב.","b":false},{"t":"ורבינו יעקב בעל הטורים ז\"ל כתב, \"ויקץ יעקב משנתו ויאמר\", ס\"ת \"צבור\" שאין תפלתו של אדם נשמעת אלא בצבור. \"משנתו\", קרי ביה \"ממשנתו\", מתוך שהוא הוגה בתורה ביום, גם בלילה לא שכב לבו מלהגות בה בחלומו, ע\"כ. והדברים נפלאים.","b":false}]},{"id":"18","t":"ארץ ישראל קנויה לעם ישראל בקנין נצח","p":[{"t":"וְהִנֵּה ה' נִצָּב עָלָיו וַיֹּאמַר אֲנִי ה' אֱלֹהֵי אַבְרָהָם אָבִיךָ וֵאלֹהֵי יִצְחָק הָאָרֶץ אֲשֶׁר אַתָּה שֹׁכֵב עָלֶיהָ לְךָ אֶתְּנֶנָּה וּלְזַרְעֶךָ: (כח, יג)","b":true},{"t":"אמרו רבותינו (חולין צא, ב), הארץ אשר אתה שוכב עליה וגו', מאי רבותיה, אמר רבי יצחק מלמד שקפלה הקב\"ה לכל ארץ ישראל והניחה תחת יעקב אבינו שתהא נוחה ליכבש לבניו. וכן הוא בדברי רש\"י ז\"ל. והיינו שהי\"ת רמז ליעקב אבינו כי כשם שאדם שולט בד' אמותיו, כך יהא קל לזרעו לכבוש ולשלוט בארץ ישראל.","b":false},{"t":"והנה צריך להבין מה הצורך בכך, ואם אכן היה נחוץ הדבר, א\"כ מדוע כשהקב\"ה הבטיח את הארץ לאברהם וליצחק לא קיפלה תחתיהם וכפי שעשה אצל יעקב.","b":false},{"t":"והנראה בזה, שע\"י שקיפל הקב\"ה את כל א\"י תחת יעקב אבינו והוא שכב עליה, הרי שקנאה בחזקה, ואין עוד שום מקום לערעור על קניינו. ואעפ\"י שבכדי לקנות חפץ אין צריך לאחוז בכולו ואפשר להחזיק רק במקום מסויים וקונה הכל (כמבואר בשו\"ע חו\"מ סי' ק\"צ ואילך), מ\"מ המקומות בהם מחזיקים אנשים ועמים אחרים צריכים תפיסה בכל, ולכן הקב\"ה קיפל את כל ארץ ישראל והניחה תחת יעקב אבינו ע\"ה.","b":false},{"t":"ומה שלא קיפל הי\"ת את הארץ לתתה גם לאברהם וליצחק, הטעם ברור, מפני שמאברהם יצא ישמעאל. וכן מיצחק יצא עשו, אשר אינם נוחלים את הארץ, וכדי שלא תהא בידם טענת ירושה, לכך לא קיפל את ארץ ישראל לתתה לאבותיהם, ולכן רק הבטיחה להם אך לא נתן להם בפועל כדי שלא יהא לבניהם ישמעאל ועשו בה טענת תפיסה מדין קנין ירושה, אבל יעקב אבינו מטתו שלימה, וכל בניו זרע קודש, ומהם נתהוה עם ישראל, ולהם מובטחת הארץ. לכן לו יאות שיקנה את הארץ, ותהא לבניו מורשה עד עולם. וזה שאמר הי\"ת ליעקב, \"אני ה' אלהי אברהם אביך ואלהי יצחק הארץ אשר אתה שוכב עליה לך אתננה ולזרעך\", היינו שהי\"ת אמר ליעקב אבינו, דע לך, כי זאת הארץ אשר הבטחתי לאבותיך היה בהבטחה בלבד, וזאת, בכדי שישמעאל ועשו לא יבואו בטענת ירושה. אבל אצלך לא כן הוא, כי אתה וזרעך קודש, ולכן הנני נותן לך את הארץ בקנין גמור, לך ולזרעך עד עולם.","b":false}]},{"id":"18","t":"סולם יעקב - רמז לחיי האדם בעוה\"ז","p":[{"t":"וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשֹׁתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ: (כח, י-יב)","b":true},{"t":"הנה הדברים מופלאים ומלמדים ואין חקר לתכליתם, ונלענ\"ד לפרש את הענין בדרך רמז. \"ויצא יעקב\", היא הנשמה שהיא בחינת יעקב. \"מבאר שבע\", הוא מקום מושב השכינה תחת כסא הכבוד, כי משם חוצבה באש להבה, והוא באר שבע, שהנשמה שבעה שם מזיו השכינה, ומתעדנת בעידון רוחני והוא לה למנה, ואמנם עתה הנשמה מוצאת בעל כרחה, והוא שנאמר ויצא יעקב מבאר שבע. \"וילך חרנה\", שבעל כרחה הנשמה יוצאת מעולם שכולו טוב, ובעל כרחה נכנסת לחרון העולם הזה, העולם השפל, ויורדת מאיגרא רמה לבירא עמיקתא, לגלות מעמקתא ומסתרתא. \"ויפגע במקום וילן שם\", המקום הוא העולם הזה והאדם שוקע בו בלינה ותרדמה. \"כי בא השמש\", ששקעה לה השמש העליונה, שהיא נמצאת בסתר המדרגה, והחשך יכסה ארץ, יונתי בחגוי הסלע בסתר המדרגה.","b":false},{"t":"ואומרו \"ויחלום\", לומר, כי מעתה מציאותה הוא בעולם הדמיון והתוהו, שאין בו מציאות כי אם ציור וחלומות, והגם שלעינינו נדמה כי זו היא המציאות, אין זה כי אם לרוב אמנות הציור הנפלא, אשר יתעתע בדמיון האדם, עד שחושב שזו המציאות ולא דבר אחר, אך באמת אין בזה כי אם מראות שוא ואחיזת עינים, שכך ברא יושב שמים, לעטר ולצייר את זה העולם בעדי עדיים, ציור שלא נגעו בו ידים, ונאמר (ש\"א ב, ב), אין צור כאלהינו, ואמרו חז\"ל (ברכות י, א מגילה יד, א), אין צייר כאלהינו, כי לרוב יופי הציור ושלמותו, יחשבו שזו היא מציאותו, ומתוך כך ישמח האיש בהצלחות העוה\"ז, כי נחשבים לו כאמיתיות ממש. ואם יכשל בדבר מה, יצטער ויעצב אל לבו, ובמר יאנח על רוע גורלו, כי לא צלח עליו מזלו, ואין האדם מבין כי הכל הבל, וגם ההצלחות וגם הכשלונות, המה דמיונות, כי הכל חלום. וכבר אמר המשורר הגדול רבי משה אבן עזרא ע\"ה (המכונה רבי משה הסלח, ע\"ש הסליחות שחיבר), שהעוה\"ז הוא חלום גדול, חלום שמתחיל בלידת האדם, ומסתיים בפטירתו, אבל הוא חלום. וכן יסד הקדוש רבינו אמנון בפיוטו שחיי האדם כחלום יעוף.","b":false},{"t":"והנה האדם בעת חלומו, חושב שזו המציאות בלא פקפוק, ופעמים הוא בחלום פחדים ובלהות והוא בהול ומפוחד, ואין מושיע לו, כגון שחולם שתולים אותו, או זורקים אותו מגבהים, ואינו ידוע מה יעשה ולמי יפנה לעזרה, ובתוך זה מעירים אותו לאמר, הגיע זמן ק\"ש של שחרית, וקם ורואה את עצמו על מטתו בתוך ביתו, הריהו שמח ושש שכל זה חלום ולא מציאות. ולפעמים הוא חולם בחלומו, שהוא יושב על כסא מלכות, ושרים ורוזנים רצים לקיים כל היוצא מפיו, והוא במלכים יתקלס, ועפרות זהב לו, ובתוך כל זה, בני ביתו מעירים אותו ואומרים לו, קום, הגיע זמנך לצאת לעבודה, והוא פוקח את עיניו והנה חלום. ומתאכזב ומתמרמר, ואומר חבל שכל זה היה רק חלום. אבל בשעת החלום הוא חושב שזו המציאות, וחי את המציאות, ואם היא של שמחה, הוא שמח בה בכל איבריו וגידיו, וכן להיפך אם הוא מצטער הריהו מרגיש את הצער והכאב בכל גופו.","b":false},{"t":"[א\"ה - צא וראה מה גדול כחו של חלום, כי הנה ידועים דברי רבנו הרמב\"ם בספר המורה (ח\"ב סי' מב), שהיאבקות יעקב עם המלאך היתה בחלום ולא בהקיץ, ובא רבינו הרמב\"ן ז\"ל בפירושו לתורה (פר' וירא בראשית יח, א), והקשה על דבריו, ואמר לא ידעתי למה היה צולע על ירכו בהקיץ ועוד האריך להקשות על שיטת הרמב\"ם. והנה בספר שער כבוד ה' להקדוש מוה\"ר אפרים אנקאווא ז\"ל כתב לתרץ תמיהת הרמב\"ן, וכה סיפר, כי פעם אחת היה מהלך בדרך ונזדמן לאיזה פונדק, בא אליו גוי רשע ואיים עליו להכותו, אך לא עשה לו כלום לבסוף, ונסתלק כלעומת שבא. ויהי בלילה בעלות על משכבו חלם והנה אותו גוי רשע בא ומכה אותו, ובבוקר קם וראה והנה במקום שהכהו בחלומו כולו נפוח וכואב, ובזה ישב ענין האבקות יעקב. וזה יורה לך עד כמה יכול חלום לפעול על האדם. יבח\"ר].","b":false},{"t":"וכן הוא בחיי העולם הזה, שכל זמן שהאדם כאן, ובונה וסותר, וקונה ומוכר וכו', הריהו חושב שזו המציאות הכי ברורה, ואלו הם החיים, ועל כן הוא מתפעל ומתרגש כל כך מהצלחות העוה\"ז ומכשלונותיו, אבל לעתיד לבא בשוב ה' את שיבת ציון היינו כחולמים (תהלים קכו, א), היינו, כי לעתיד נבין כי בימי חיינו בעוה\"ז היינו \"כחולמים\", כי רק אז נבין שהעוה\"ז הוא כחלום ממש רק שהוא חלום ארוך. וממילא, \"אז ימלא שחוק פינו\" (שם שם, ב), כי כשנשוב להתבונן על מה היינו שמחים, ועל מה היינו מצטערים, נראה שהכל הבל ורעות רוח, ופינו ישחק במלואו, באומרנו, איך התיחסנו כ\"כ בצער לדבר פלוני, ואיך שמחנו כל כך בדברים אחרים, כי לעתיד יתבהר המצב, ויוברר מה משקלו האמיתי של כל דבר.","b":false},{"t":"* * *","b":false},{"t":"ואולם עדיין יש הבדל בין חיי העולם הזה, ובין חלום רגיל, שבחלום רגיל בדרך כלל אין בו מציאות כלל. אבל בחיי העולם הזה יש מציאות אחת והיא חשובה מאד, והיא קיום המצות ולימוד התורה, שאין מקום אחר לקיומם, אלא בעוה\"ז בלבד, וזה סוד קיום העולמות כולם, ולזה מכוון מאמר הכתוב, ויחלום והנה סולם וגו'. ויחלום, כלומר שאחר שיצאה הנשמה מבאר שבע, ובאה חרנה הוא העולם הזה וכנ\"ל, עמד הצדיק והתבונן וראה, שבעצם כל חיי העולם הזה הם בחינת חלום בלבד, וחיפש למצא אם יש דבר מה מציאותי בעולם הזה, וראה, והנה סולם מוצב ארצה וראשו מגיע השמימה, שבמרכז החלום הגדול הזה, יש מציאות אמיתית וקיימת, והיא הסולם, והגם שהוא מונח ארצה, מ\"מ ראשו מגיע השמימה, שהוא עולה ומתרומם מעל הדמיונות של העולם הזה.","b":false},{"t":"ואולי יש לפרש עוד על פי מה שנאמר (קהלת א, ג), מה יתרון לאדם בכל עמלו שיעמול תחת השמש. ואמרו חז\"ל, תחת השמש אין יתרון, אבל מעל השמש יש יתרון (ראה הלשון בשבת ל, ב וראה פסיקתא דר\"כ ח, א). ואפשר שראשו של הסולם המגיע השמימה, הוא למעלה מן השמש, ועל כן יש בו יתרון על דמיונות העולם הזה.","b":false},{"t":"* * *","b":false},{"t":"\"והנה מלאכי אלהים עולים ויורדים בו\", אלו המלאכים הנבראים ממעשי בני אדם, כמאמרם ז\"ל באבות (ד, יא), רבי אליעזר בן יעקב אומר, העושה מצוה אחת קונה לו פרקליט אחד, והעובר עברה אחת קונה לו קטגור אחד. ע\"כ. ואלו הן המלאכים העולים ויורדים בו, שנבראו ממעשיו של כל אחד, ועולים להביא את המעשים הטובים שלנו לפני הקב\"ה, וחוזרים ומביאים את השפע הראוי מאותם מעשים לעושיהם, וזה הטעם שכתוב, עולים ויורדים בו, ולכאו' קשה כי היה צריך להקדים ירידתם לעליתם, שכן מקומם הוא בשמים, ומשם יורדים אל הארץ ורק אחרי כן עולים שוב, אמנם לפי מה שנתבאר אתי שפיר, כי מדובר במלאכים הנוצרים ממעשיהם של בני אדם, ולכן בתחילה הם עולים להביא את אותם מעשים למעלה, ואח\"כ יורדים עם השפע האלהי שניתן למעלה עבור כל מצוה ומצוה. ואם חלילה האדם עושה מעשים רעים, וברא במעשיו משלחת מלאכים רעים רח\"ל, הרי שהם מורידים לו מלמעלה כפי מעשיו, ומורידים גזירות ואסונות רח\"ל. וזהו עולים ויורדים בו, שתלוי \"בו\", כלומר באדם הבורא את המלאכים ע\"י מעשיו, כי השפע העליון בא לאדם לפי מעשיו, אם טובים אם רעים, והכל תלוי בו.","b":false},{"t":"ואולי לזה כיון יעקב אבינו ע\"ה באומרו (בראשית כח, טז), \"אכן יש ה' במקום בזה\", שגם במקום הזה שהוא עולם הדמיון והתוהו, גם בו יש קרבת אלהים. וגם בו אפשר להשיג דרגות גבוהות כמו שהשיג יעקב אבינו ע\"ה שנאמר בו (שם שם, יג), \"והנה ה' נצב עליו\", ופירש רבינו הקדוש בעל אור החיים שם וז\"ל, \"והנה ה' נצב עליו\", ירמוז גם על יעקב, על דרך אומרם ז\"ל (ב\"ר מז, ו), האבות הם מרכבה לשכינה, ולהיות שהוא רגל רביעי, יאמר בדיוק \"נצב עליו\", יותר מעל אברהם ויצחק, כי הוא עיקר העמדת הכסא. עכ\"ל.","b":false},{"t":"ולפי מה שנתבאר יש לומר שע\"י הסולם האמור מתברר, שהכל בנוי ועומד על מעשה האיש הישראלי כי ישראל יכולים ע\"י מעשיהם להגדיל את הכח האלהי בעולם הזה השפל, ולהרחיב את גבולות הקדושה, ולעשות את הארץ היבשה והצחיחה, למקום של רוחניות והתעלות, ודבקות בה'. ע\"י תורה ומצות ומעשים טובים.","b":false},{"t":"(ערש\"ק ויצא ו' כסלו התשס\"ה)","b":false}]},{"id":"18","t":"עולים ויורדים בו","p":[{"t":"וַיֵּצֵא יַעֲקֹב מִבְּאֵר שָׁבַע וַיֵּלֶךְ חָרָנָה, וַיִּפְגַּע בַּמָּקוֹם וַיָּלֶן שָׁם כִּי בָא הַשֶּׁמֶשׁ וַיִּקַּח מֵאַבְנֵי הַמָּקוֹם וַיָּשֶׂם מְרַאֲשֹׁתָיו וַיִּשְׁכַּב בַּמָּקוֹם הַהוּא, וַיַּחֲלֹם וְהִנֵּה סֻלָּם מֻצָּב אַרְצָה וְרֹאשׁוֹ מַגִּיעַ הַשָּׁמָיְמָה וְהִנֵּה מַלְאֲכֵי אֱלֹהִים עֹלִים וְיֹרְדִים בּוֹ: (כח, י-יב)","b":true},{"t":"ורבותינו במדרשים האריכו לבאר את חלומו של יעקב אבינו ע\"ה ומשמעותו (ראה חולין צא, ב ובספרי קורח פיסקא ד וב\"ר סח, יב ואילך ושמו\"ר לב, ז ויק\"ר כט, ב ובתנחומא ויצא פ\"ב ופרקי דר\"א פל\"ה ובילקו\"ש בראשית רמז קיט).","b":false},{"t":"ורבינו אברהם אבן עזרא ע\"ה כתב (בראשית כח, יב), דה\"ר שלמה הספרדי (אפשר שהוא ר\"ש ן' גבירול ז\"ל), אמר, כי סולם רמז לנשמה העליונה, ומלאכי אלהים מחשבות החכמה, ויאמר רבי ישועה כי טעם סולם, שעלתה בו תפלתו וירדה ישועתו מן השמים וכו', והטעם דרך משל כי כל דבר לא יכחד מן השם, ודברי מטה תלויים בעליונים, וכאילו סולם ביניהם שיעלו המלאכים בו להודיע הדברים אחר שיתהלכו בארץ, ג\"כ כתוב, כי מלאכים אחרים יורדים למלאת שליחות השם כדרך מלך עם משרתיו. עכ\"ד. ועיין ברמב\"ן (שם), שגם כן הלך בדרך זו.","b":false},{"t":"ונרחיב מעט את הענין לאור דברי רבינו הראב\"ע ז\"ל, ונפרש את הדברים הנאמרים על בחינת הנשמה השוכנת בכל אחד ואחד מישראל, ונאמר: האדם מישראל מוצב ארצה בגזירתו יתברך, כי ממנה לוקח עפר מן האדמה, אכן \"ראשו\" מגיע השמימה, היא הנשמה הקדושה שהיא חלק אלוה ממעל, שהיא \"ראשו\" וראשיתו של האדם ועיקרו, כי הגוף אינו אלא מלבוש בו מתלבשת הנשמה ברדתה אל העולם השפל הזה, והנשמה היא הסולם המקשר בין האדם ליוצרו, והיא המגשרת בין הרוחניות לגשמיות.","b":false},{"t":"ומלאכי אלהים עולים ויורדים בו, עיין בדברי רש\"י ובדברי שאר המפרשים שדקדקו למה הקדים את עליית המלאכים לירידתם. והרב רבי שלמה הספרדי כתב דמלאכי אלהים הם מחשבות החכמה כנ\"ל.","b":false},{"t":"והנה ידוע דמכל מעשה טוב ומכל מצוה שהאדם עושה נברא מלאך טוב, ומליץ עליו טובות לפני המקום ב\"ה ואם ח\"ו חוטא נברא מזה מלאך רע, כמבואר באבות (ד, יא), רבי אליעזר בן יעקב אומר, העושה מצוה אחת, קונה לו פרקליט אחד. והעובר עברה אחת, קונה לו קטיגור אחד. ומלאכים אלה הם העולים והיורדים בסולם. וכשהם מלאכים טובים שנבראו ממעשים טובים, אזי הם עולים ומליצים עליו יושר, ומעלים אתם את המצוות ומעשים טובים שעשה לנחת רוח לפני המקום ב\"ה, ויורדים ומורידים לו שפע ישועה ורחמים, וכמ\"ש רבי ישועה \"שעלתה בו תפילתו וירדה ישועתו מן השמים\". ואם ח\"ו עולים מלאכים שנבראו מהמעשים הלא טובים, אזי מורידים אתם ג\"כ באותה מדה שהוא מודד.","b":false},{"t":"ובמדרש רבה (ב\"ר סח, יב), מצינו פלוגתא מה הוא עולים ויורדים \"בו\", רבי חייא ורבי ינאי, חד אמר עולים ויורדין בסולם, וחד אמר עולים ויורדים ביעקב וכו'. ע\"ש. והנה יש שפירשו את הענין כפשוטו \"בו\" רצונו לומר, בסולם. וי\"א \"בו\" ביעקב, ולפי מה שנתבאר הדבר מובן היטב, דהכל תלוי באדם עצמו, כי נשמתו היא הסולם, ומעשיו הם המלאכים, ועלייתם וירידתם תלויה בו, כי במדה שאדם מודד בה מודדים לו (מתני' סוטה ח, ב וכ\"ה במגילה יב, ב וב\"ר ט, יג ושמו\"ר כה, יג וזוהר ח\"ג צב, ב ועוד הרבה מקומות), ובאדם עצמו תליא מילתא. ובזה יובן היטב מה שאמר הכתוב \"עולים ויורדים\" בו, תחילה עולים ואח\"כ יורדים, כי לכאורה קשה כיון שהמלאכים באים מלמעלה היה לו לומר יורדים ועולים. אך לפי מה שנתבאר מובן היטב, כי מלאכים הללו נבראו ממעשיו של האדם, ומקום בריאתם הוא כאן בעולם העשיה, ועל כן מצינו בתחילה לשון \"עולים\", ורק אח\"כ לשון \"יורדים\" בו.","b":false},{"t":"ובמעשיו של האיש תלויים מהלך העולמות כולם, עליותיהם ומורדותיהם, וכל אשר יעשה בהם, כי ע\"י מעשיו נקבעים עניניהם לטוב או חלילה לדרך אחרת, כי יוצר האדם יצרו בצלם דמות תבניתו, וישת עליו תבל ומלואה, והוא מקיים חוקות שמים וארץ, והציבו על האדמה שממנה חוצבו יסודותיו, והיא יניקתו הטבעית והקיומית, ויפח באפיו נשמת חיים חלק אלוה ממעל, ובזה הגביה את מעלתו יותר מן המלאכים, וזו היא דמות הסולם המוצב ארצה וראשו מגיע השמימה.","b":false},{"t":"כי האדם יסודו עפר מן האדמה, אך נשמתו באה מגבהי מרומים. וכל השפע בא לעולם על ידו. וכשבוחר בטוב, והולך בדרכי ה' ביושר, הריהו מביא שפע טוב לעצמו ולסביבתו, ולכל העולם כולו. ואם בחר בדרך השלילית הריהו מונע את השפע הטוב מן העולם, ויכול גם להביא רעה ח\"ו. ומעשיו הרעים עולים בסולם זה ומגיעים עד כסא הכבוד, ויורדים בו, ומורידים שפע היוצא מאותם מעשים, המורם מהם כיוצא בהם.","b":false},{"t":"ועל האדם המתבונן בדרכיו לדעת על מה הטבעו שרשיו, ומה רב ועצום כחו והשפעתו, וכל אחד מחוייב ליתן אל לבו את האחריות הכבדה הרובצת על שכמו. והרי הוא דומה לנשיא או מלך של מדינה גדולה ורבת עוצמה, ובידו לצוות על צבאו להטיב ולבנות ולהציל ולהגן, כמו שיכול גם לצוות עליהם להרוג ולהרוס ולהשמיד ולאבד, ואם ישים אל לבו וידע את גודל האחריות המוטלת עליו, אשר במאמר פיו יכול לקבוע גורלם של עמים רבים לחסד או לשבט, א\"כ כמה עליו להיות זהיר ולשקול את מעשיו במשקל ששוקלים בו זהב ויהלומים המורה על כל תנודה ולו הקלה ביותר.","b":false},{"t":"ומה נפלאו דברי רבותינו (קדושין מ, ב), עשה מצוה אחת, אשריו, שהכריע את עצמו ואת כל העולם לכף זכות. עבר עבירה אחת, אוי לו, שהכריע את עצמו ואת כל העולם לכף חובה. ע\"ש.","b":false},{"t":"ולכן בטרם יעשה האדם איזה צעד או מעשה, יבין וידע כי במעשהו זה הוא קובע גורלם של רבים, כי האדם הוא נזר הבריאה כולה, ואם זכה להיות מהעם הנבחר אחריותו גדולה ביותר, כי הוא נבחר לקבל תורת אלהים חיים, שהיא קיום העולמות כולם. וכמה אחריות מוטלת על כל איש מישראל. והאחריות הזאת מחייבת אותו לשים לבו ועיניו, ולשקול כל צעדיו במשנה זהירות, וכל מחשבותיו יהיו נתונות לראות כדת מה לעשות שיהיו כל מעשיו מתאימים לדרישות התורה הקדושה, כדי לעורר רחמים עליונים ולהשפיע שפע ישועה ורחמים לעצמו, ולכל העולם.","b":false},{"t":"ובמקום שהאדם יחשוב בתחילת כל מעשה, מה יצא לי, ומה יתן לי, מה ארויח ממעשה זה, ומה יוסיף לי דיבור זה. תהיינה מחשבותיו של האדם נתונות לאמות מדה שונות לגמרי, והן, מה רצוי ואהוב לפני המקום ברוך הוא ומה לא, ובאיזו דרך אהיה רצוי לפניו במעשי, ואיך וכיצד אנצל את זמני לזכות לקרבת אלהים, ולהיות מוצא חן ושכל טוב בעיני אלהים ואדם, ובזה יזכה לסייעתא דשמיא, ויקויים בו (משלי ג, ו), בכל דרכיך דעהו והוא יישר אורחותיך.","b":false},{"t":"(מוצש\"ק פרשת ויצא יעקב התדש\"מ)","b":false}]}]},{"slug":"וישלח","name":"פרשת וישלח","items":[{"id":"19","t":"תקות הגאולה","p":[{"t":"וְאֵלֶּה הַמְּלָכִים אֲשֶׁר מָלְכוּ בְּאֶרֶץ אֱדוֹם לִפְנֵי מְלָךְ מֶלֶךְ לִבְנֵי יִשְׂרָאֵל: (לו, לא)","b":true},{"t":"בספרי הקבלה כתוב שאלו העולמות שנשברו, והיא שבירת הכלים, שלא יכלו לסבול את זיו אורו הגדול יתברך. ואין להאריך כאן (והדברים ארוכים בכתבי האר\"י בהרבה מקומות, וראה בלקוטי תורה סדר וישלח).","b":false},{"t":"וראיתי דברי קדוש רבינו חיים ן' עטאר זיע\"א, שכתב, וז\"ל, ואלה המלכים וגו' יכוין בזה למנות כל אשר נתחתן לאדום או העמיד לה מלך וכדומה, כי הכל עומד לאבדון בנפול אדום, וכאומרם ז\"ל (ב\"ר פג, ג), בצרה לפי שהעמידה מלך לאדום עתידה ללקות עמהם, דכתיב (ישעיה לד, ו), כי זבח לה' בבצרה, ע\"כ. גם שאר הערים הגם שביני ביני קודם שיבא גואל צבי ישראל יכנסו ברשות מלך אחר, יבואו בני ישראל בטענה קדומה ויוציאוה ותשרף, ואין צל הזולת מצילתה.","b":false},{"t":"גם לקחת סימן לגאולה העתידה כי יאריכו הימים, והראיה כי ה' מנה מלכי אדום שקדמו למלכי ישראל, וכמותם קדמו מלכי ישראל למלכותם אחר שפסקה אחר מלכים הרשומים בתורה, ומעתה כמו כן ימלכו ישראל כמנין אשר מלכו באדום, והגם כי ששת אלפים עולם עומד, יאריך ה' ימי טובה כמאמרם ז\"ל, עכל\"ה.","b":false},{"t":"והיא בשורה גדולה יצאה מפה קדוש ה' אור משיחו, חפץ בחיים, וזה מישב תמיהות רבות, בענין הזמן המעט שנותר. וישועתו קרובה בשובה ונחת בב\"א.","b":false}]},{"id":"19","t":"לעמוד על משמר הצניעות","p":[{"t":"וַתֵּצֵא דִינָה בַּת לֵאָה אֲשֶׁר יָלְדָה לְיַעֲקֹב לִרְאוֹת בִּבְנוֹת הָאָרֶץ: (לד, א)","b":true},{"t":"ופירש\"י ז\"ל בת לאה, ולא בת יעקב, אלא על שם יציאתה נקראת בת לאה, שגם יצאנית היתה, שנאמר (בראשית ל, טז), ותצא לאה לקראתו. ועיין בדברי הקדוש רבינו חיים ן' עטאר זיע\"א בספרו אוה\"ח מש\"כ בזה.","b":false},{"t":"ויש לעורר בזה, דהנה לא יעלה בדעת איש לומר, שדינה לא היתה צנועה בתכלית, שהרי היתה בת לאה הצדקת שהיא מארבע אמהות אשר זכתה להעמיד ששה שבטים בישראל, ומהם לוי שממנו יצאו משה ואהרן וכל קדושי כהונה ולויה, וממנה יהודה שממנו יוצאת כל מלכות בית דוד עד מלך המשיח. והיא שזכתה להיות קבורה ליד יעקב אבינו ע\"ה בחיר האבות במערת המכפלה.","b":false},{"t":"וגם מה שיצאה לאה לקראת בעלה, היה מתוך יראת ה' טהורה אשר בערה בקרבה ורצתה לזכות בקיום דבר ה' להעמיד שבטי יה, ואעפ\"י כן תלו רבותינו את יציאת דינה ביציאתה של לאה, ובודאי שזה מלמד שגם דינה יצאה בצניעות ובכשרות, לראות בבנות הארץ כי היתה יחידה בין אחיה ואין לה עם מי להחליף מילה, ולכן יצאה, ואעפ\"י שנתפסה באונס גמור ביד בן מלך, שכם בן חמור אשר חיילים ושומרי ראש מקיפים אותו מכל צדדיו, וכל אשר יאמר הם עושים, ומה היתה יכולה לעשות נגדו. ועיין עוד בדברי קדוש באור החיים על פסוק וישכב אותה וגו', שכתב וז\"ל, יתבאר ע\"ד אומרם ז\"ל (ראה הוריות י, ב), במעשה יעל שהנאתם של רשעים צער הוא אצל צדיקים וכו', ע\"ש היטב.","b":false},{"t":"ועם כל זאת יש בפי חכמינו כעין ביקורת עליה ועל אמה. והדברים מזעזעים עד היכן הדרישה עמוקה מבת ישראל כשרה, שתהיה כל כבודה בת מלך פנימה.","b":false},{"t":"ובדורנו זה שמדת הבושה היא החומה בעד יראת ה' ועבודתו, ובעד צניעות וטוהר המדות, כמה יש ליזהר לחנך את בנות ישראל לבושה וצניעות. כי בימינו בטלה הבושה ונרמסה ברגל גאוה והיתה לאין, ורבות בנות נוהגות בהנהגות שונות רחוקות מדרכי אמותינו הקדושות, ונעשו הדברים סדירים ורגילים, ומי שנמנע להרבות דברים, או אשה שתשמור עצמה ולשונה, תהיה בעיניהם כמשונה.","b":false},{"t":"ואולי זהו הנסיון של הדור, שאעפ\"י כן, לא נשנה לבושנו ולא נשנה לשוננו, ולא נשנה הנהגתנו, ונזכור ונזכיר שכל בת ישראל היא בת מלך ממש, וכל כבודה בת מלך פנימה. וה' יערה עלינו רוח קדושה וטהרה בחן וחסד ובחמלה.","b":false}]},{"id":"19","t":"העוה\"ז עראי","p":[{"t":"וַיָּשָׁב בַּיּוֹם הַהוּא עֵשָׂו לְדַרְכּוֹ שֵׂעִירָה, וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת: (לג, טז-יז)","b":true},{"t":"אפשר לומר, דאפילו אחר שהצליח יעקב ולא נלחם בו עשו אחיו, מכל מקום ידע יעקב שלא הגיע עדיין אל המנוחה והנחלה, ולא ביקש להתישב וליהנות מן העולם הזה, ושינן לעצמו שהעוה\"ז בעבורינו אינו בבחינת בית שהוא קבע, אלא סוכות שהוא עראי וזמני בלבד.","b":false},{"t":"והענין הזה מלמדנו בינה, לדעת שאין לנו חלק בעוה\"ז, ובשביל לזכות אפילו במעט צריך זכויות, או זכות של תורה, שהיא סוד קיום העולם, על כן מי שעוסק בה זוכה גם לחיי העוה\"ז כדי שיוכל להמשיך ולקיים את העולם ללא טרדות וכנ\"ל וכן אמרו באבות (ו, ז), גדולה תורה שנותנת חיים לעושיה, בעוה\"ז ובעולם הבא. וגם יכול לזכות לחיי העוה\"ז ע\"י חסד, כי כשהאדם עושה חסד לאחרים בגופו וממונו, גם הקב\"ה נותן לו משל אחרים, וכאשר אמרו רבותינו (אבות ב, ד), בטל רצונך מפני רצונו כדי שיבטל רצון אחרים מפני רצונך, ועוד שגם החסד מקיים את העולם, כי על שלשה דברים העולם עומד, על התורה, ועל העבודה, ועל גמילות חסדים (שם א, ב), ונאמר (תהלים פט, ג), כי אמרתי עולם חסד יבנה.","b":false},{"t":"ובאחת מנסיעותי לארץ ברזיל היה אתי יהודי יקר, והיינו נוסעים בדרך רחוקה מאד, והיה רואה איך כל הדרך מלאה נהרות ואגמים, בבקעה ובהר על כל פינה ממש, ואמר לי איך זה שבארץ הזאת יש ברכה גדולה כזו, ובא\"י אין הרבה מים לשתות. ואמרתי לו שהעוה\"ז שייך לעשו, וע\"כ הם אינם צריכים זכויות כדי לזכות להנאות העוה\"ז, אבל אנן בדידן בניו של יעקב אבינו ע\"ה, ואנו נוחלי העוה\"ב, ובעוה\"ז אין לנו חלק ונחלה, לכן רק ע\"י זכויות מיוחדות אנו זוכים רק בכדי קיומינו בעוה\"ז, ואין לנו אלא להודות ולהלל, כי הכל בחסד ה' עלינו.","b":false},{"t":"ואולי זהו מה שנאמר (דברים יא, יא-יב), והארץ אשר אתם עוברים שמה לרשתה ארץ הרים ובקעות למטר השמים תשתה מים, ארץ אשר ה' אלהיך דורש אותה תמיד עיני ה' אלהיך בה מרשית השנה ועד אחרית שנה. והיינו שהגוים אינם מושגחים מאת הי\"ת כי נתן להם את העוה\"ז לנחלה, אבל אנחנו בניו בחיריו שלקחנו לנו את חיי העוה\"ב, ואיננו לוקחים מן העולם אלא כדי צרכינו ההכרחיים. לכך הקב\"ה מודד כל מה שנותן לנו, ולכן הכל תלוי בשמים, וזהו \"למטר השמים תשתה מים\". ולכך גם נאמר, \"ארץ אשר ה' אלהיך דורש אותה מתחילת השנה ועד סופה\", כי אנחנו מושגחים תמיד ממנו יתברך ליתן לנו את צרכינו ההכרחיים. והוא ישתבח שמו דורש ציון, לראות המצב. ולפי זה נותן את ברכתו, והיינו שנאמר עיני ה' אלהיך בה וגו', להביט ולהשגיח על דרכי בני ישראל היושבים על אדמתם, לראות איך הם שומרים את מצוותיו, ואיך עוסקים בתורת אלהים חיים, ועל פי ענינם הוא ממלא את כל צרכם.","b":false},{"t":"ומה טוב חלקנו ומה ומה נעים גורלנו שאנו מושגחים בהשגחה מתמדת כאשר ישא האומן את היונק.","b":false},{"t":"וצריך לידע ולשנן כי כל ענינינו כאן הוא בגדר סוכה בלבד, שאין זה מקומינו אלא עראי ממש, וזה הוא שנאמר (בראשית לג, יז), ויעקב נסע סֻכֹּתָה, אלא דקשה סוף הפסוק (שם), ויבן לו בית וגו', דזה סותר לרישא של הפסוק, דבתחילה כתוב שנסע סוכותה, ומיד כתיב ויבן לו בית.","b":false},{"t":"ופירשתי בס\"ד דהכי קאמר, \"ויבן לו בית\", לא לעצמו, אלא לעניניו הרוחניים. ולבנות בית לשכינה ובתי מדרש להוראה לזה עשה \"בית\" שהוא מורה על קבע. \"ולמקנהו\", אבל למקנהו שהם קנייני העוה\"ז, להם עשה סוכות, שלא הקדיש להם זמן, ולא החשיבם אלא כדבר עראי.","b":false},{"t":"והנה מצינו בפסחים (פב, א), אמר רבי אלעזר מאי דכתיב (ישעיה ב, ג), והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלהי יעקב וגו', אלהי יעקב ולא אלהי אברהם ויצחק. אלא, לא כאברהם שכתוב בו \"הר\", שנאמר (בראשית כב, יד), אשר יאמר היום בהר ה' יראה, ולא כיצחק שכתוב בו \"שדה\" שנאמר (בראשית כד, סג), ויצא יצחק לשוח בשדה, אלא כיעקב שקראו \"בית\", שנאמר (בראשית כח, יט), ויקרא את שם המקום ההוא בית אל. ע\"כ. וא\"כ ראינו בהדיא דיעקב הוא בונה הבית לשכינה וקרוי על שמו בית אלהי יעקב, וזהו שנאמר ויבן לו בית, שעשה את תורתו קבע ועבודת ה' שלו היא עיקר חייו בעולם הזה, ולצרכי גבוה בנה בית, כי לא באנו לעולם הזה אלא בשביל התורה והמצוות, ותו לא. אבל למקנהו שהם עניני הרכוש ושאר צרכי העוה\"ז, להם עשה \"סוכות\", שענינם עראי ודבר חולף.","b":false},{"t":"ויעקב אבינו ע\"ה ידע לחלק את עניניו, דבר דבור על אופניו. ולכן מיד נאמר בו (בראשית לג, יח), ויבא יעקב שלם, שזו השלימות לתת לכל דבר את המדה הנכונה, ורבותינו אמרו (שבת לג, ב וראה ב\"ר עט, ה), ויבא יעקב שלם, שלם בגופו, שלם בממונו, שלם בתורתו, שלא שכח תלמודו בבית לבן (והובאו דבריהם בפירוש רש\"י לתורה שם), דעל ידי שנתן יעקב אבינו לכל דבר את מדתו הנכונה לו, בזה בא לידי שלימות המעלות בכל מכל כל. וכמו שידועה שיטת רבנו הרמב\"ם (פ\"א מהלכות דעות), שדרך האמצע היא הדרך השלמה, שאינו הולך לא לקצה הזה ולא לקצה האחר, אלא יודע לכלכל מעשיו במשפט, ושומר על דרך האמצעית בכל דבר וענין, ועי\"ז הוא שלם.","b":false},{"t":"ואשרי השם אורחותיו, ושם לבו לדעת במה ישים את עיונו ורעיונו, לכוין דרכיו לפני קונו, דבר דבור על אופנו, כל דבר לפי ענינו, ויעשה תורתו עיקר וקבע, ומלאכתו טפל ועראי, ויהיה מושל ברצונותיו, בעוז וגבורה, וכל אשר יעשה יצליח.","b":false}]},{"id":"19","t":"אברהם קראו הר יצחק קראו שדה יעקב קרא לו בית","p":[{"t":"וְיַעֲקֹב נָסַע סֻכֹּתָה וַיִּבֶן לוֹ בָּיִת וּלְמִקְנֵהוּ עָשָׂה סֻכֹּת עַל כֵּן קָרָא שֵׁם הַמָּקוֹם סֻכּוֹת: (לג, יז)","b":true},{"t":"כבר פירשתי לעיל (מאמר הקודם), שאת הבית בנה יעקב אבינו לכבוד הי\"ת, והיינו ויבן \"לו\" בית, \"לו\" להי\"ת. אך לעניניו הגשמיים לא בנה בית שהוא מורה על קביעות בעוה\"ז, אלא \"ולמקנהו עשה סוכות\", כלומר, לקנייניו הגשמים בעולם עשה סוכות, שענינם עראי.","b":false},{"t":"ובפסחים (פח, א), איתא, אמר רבי אלעזר מאי דכתיב (ישעיה ב, ג מיכה ד, ב), והלכו עמים רבים ואמרו לכו ונעלה אל הר ה' אל בית אלהי יעקב וגו', אלהי \"יעקב\" ולא אלהי אברהם ויצחק. אלא לא כאברהם שכתוב בו \"הר\", שנאמר (בראשית כב, יד), אשר יאמר היום בהר ה' יראה. ולא כיצחק שכתוב בו \"שדה\", שנאמר (שם כד, סג), ויצא יצחק לשוח בשדה. אלא כיעקב שקראו \"בית\" שנאמר ויקרא את שם המקום ההוא בית אל (שם כח, יט), ע\"כ.","b":false},{"t":"וצריכים להבין דברי חכמים וחדותם, מהו \"הר\" ומהו \"שדה\" ומהו \"בית\".","b":false},{"t":"וי\"ל בעזר האל וישועתו, ע\"פ מה שאמרו המקובלים שכל תפלה שנאמר בה ב' פעמים נא אינה שבה ריקם, (א\"ה - כן הביא מרן החיד\"א בספרו נחל קדומים [דברים ג, כה], בשם חכמי קאשטילייא ז\"ל, והביא עוד משם ספר מאמר מרדכי סוף האזינו, שהתפילות הנמסרות למיכאל אינן צריכות בדיקה, ולכן אמר משה אל נא רפא נא [במדבר יב, יג], דב' פעמים \"נא\" הוא גימ' מיכאל, וכ' עוד בזה בקצרה בנחל קדומים סו\"ס בהעלותך, ע\"ש. וראה בענין השם \"נא\" בספר הפליאה ד\"ה שאלו לרבי, והדברים מופלאים. יבח\"ר), ולכן התפלל משה רבינו על מרים אחותו, \"אל נא רפא נא לה\" (במדבר יב, יג), ותפלתו לא שבה ריקם.","b":false},{"t":"ושמעתי בשם מרן החיד\"א ז\"ל לפרש, דהיינו ההיא דתנן במסכת שבת (סה, ב), הקיטע יוצא בקב שלו, שאפילו \"קיטע\" שאין לו רגלים, כלומר שאין לו זכויות שיעמידוהו, גם הוא יכול לצאת מצרותיו ותלאותיו \"בקב שלו\", היינו בתפילה שנאמר בה ב' פעמים נא. והיינו דאמר רב יהודה אמר רב (ברכות יז, ב תענית כד, ב חולין פו, א), בכל יום ויום בת קול יוצאת מהר חורב ואומרת כל העולם כולו נזונין בשביל חנינא בני וחנינא בני די לו בקב חרובין מערב שבת לערב שבת, ע\"כ. וקב אחד היינו ב' פעמים נא, והיינו דסגי ליה בתפלתו, ודפח\"ח.","b":false},{"t":"ודקדקתי לפי זה במאי דאמרו אדם יוצא בקב שלו, דהיינו, שכל אדם יראה לחדש תפלה משלו, ויהיה בה \"קב\", היינו ב' פעמים נא. וגם שתהא בהכנעה ותחינה, כי אין נא אלא לשון בקשה (ברכות ט, א סוטה י, ב וסנהדרין מג, ב ושם פט, ב), כי הכנעת הלב רצויה לפני הי\"ת ומקבל את תפלתו, כי שומע אל אביונים ה' (תהלים סט, לד), ונאמר (שם נא, יט), לב נשבר ונדכא אלהים לא תבזה.","b":false},{"t":"ויש להוסיף עוד, שלזה אמרו (ב\"מ לח, א), אדם רוצה בקב שלו מתשעה קבין של חברו. היינו שאדם רוצה בקב שלו, היינו בתפלה המקובלת שהיא ב' פעמים נא, ובאה ממנו, מפנימיותו ועצמותו, יותר מתשעה קבין של חברו, כי דבר הבא משלו מורה על הכנעת הלב האמיתית והרצויה.","b":false},{"t":"ועתה נבא לעניננו, כי אברהם אבינו ע\"ה הוסיף \"קב\" משלו, על ה\"קב\" שישנו [א\"ה - והקב הזה היה מלא בחסדים כמו שנאמר (בראשית יח, ג), אם \"נא, מצאתי חן בעיניך אל \"נא\" תעבור מעל עבדך, וב' פעמים \"נא\" עולה ק\"ב. יבח\"ר], והנה פעמיים ק\"ב עולה ר\"ד ועם הכולל הרי לך ר\"ה, והוא ענין שקראו אברהם \"הר\".","b":false},{"t":"ובא יצחק אבינו ע\"ה והוסיף על זה, \"קב\" משלו, ונמצאו ג' קבין שעולין בגימ' ש\"ו ואם תוסיף להם ג' כוללין של כל \"קב\", הרי לך מנין ש\"ט שעולה בגימ' \"שדה\".","b":false},{"t":"ובא יעקב אבינו בחיר שבאבות והוסיף \"קב\" על אבותיו, כמו שנאמר בעת שהתרחק יעקב מעשו אמר לו (בראשית לג, י), אל נא אם נא מצאתי חן בעיניך וגו'. והרב אוה\"ח הק' הקשה למה נצרך לומר, \"נא\" שני פעמים, ע\"ש. ולפי דברינו יש לומר דכאן פעל יעקב בשתי פעמים \"נא\", ובזה הוסיף גם הוא ק\"ב משלו, ו\"משדה\" נעשה \"בית\". ונמצאו א\"כ ד' קבין העולים למנין ת\"ח ועם ד' כוללים, עולה בגימ' \"בית\", ונמצא כי יעקב השלים את בית ה', והיינו דכתיב ויקרא שם המקום ההוא בית אל, וזהו ויבן \"לו\" בית.","b":false},{"t":"ויש להוסיף ולומר עוד על זה, שגם משה רבינו ע\"ה הוסיף נופך מדיליה, והוסיף \"קב\" משלו, וא\"כ הוו ליה חמשה קבין אשר עם הה' כוללין עולין תקט\"ו, והם תקט\"ו תפלות שהתפלל משה רעיא מהימנא כמנין, \"ואתחנן\", וכמנין \"תפלה\".","b":false},{"t":"ובאמת אמרו המקובלים, (וכ\"כ מרן החיד\"א ז\"ל בנחל קדומים סוף סדר בהעלותך וסדר ואתחנן), דהתחיל משה לומר אעברה נא (דברים ג, כה), והיה דעתו לומר עוד פעם \"נא\", ולכן הקב\"ה מנעו ואמר לו רב לך אל תוסף דבר אלי עוד בדבר הזה (שם שם, ד), כלומר אל תוסיף עוד \"נא\", כי אז מוכרחת התפלה להתקבל, ובכל תקט\"ו התפלות לא הפסיקו הי\"ת עד שביקש לומר \"נא\" עוד פעם, ודו\"ק.","b":false},{"t":"[א\"ה - עוד שמעתי בזה פעם מידידי הרה\"ח רבי אהרן הרשלר נר\"ו בשם הרה\"ק בוצינא קדישא מהר\"א מבעלזא ז\"ל זיע\"א, שאמר לבאר ענין אברהם קראו הר וכו', וכן ענין תקט\"ו תפלות שהתפלל משה רבינו ע\"ה. וביאר דלעתיד לבא הקב\"ה יבנה את ביהמ\"ק בכח השם מחנ\"ה, והקב\"ה בונה את הקיר הראשון, והקיר הב' בונה אותו אברהם אבינו ע\"ה, והקיר הג' בונה אותו יצחק אבינו ע\"ה, והקיר הד' בונה אותו יעקב אבינו ע\"ה, והתקרה בונה אותה משה רבינו ע\"ה. והנה \"מחנה\" בגימ' ק\"ג, וכשנתנוצץ השם הזה ע\"י אברהם אבינו הרי ב' פעמים \"מחנה\" והוא עולה מנין ר\"ו, ו\"הר\" עם הכולל הוא בגימ' ר\"ו, והיינו שאמרו רבותינו אברהם קראו \"הר\", ויצחק בא והוסיף עוד פעם התנוצצות אור היוצאת מ\"מחנה\", הרי לך ג\"פ מחנה שעולה מנין ש\"ט שהוא בגימ' \"שדה\", והיינו דאמרינן יצחק קראו \"שדה\", ויעקב הוסיף עוד פעם שם \"מחנה\" הרי לך מנין תי\"ב אשר עולה בגימ' \"בית\", והיינו יעקב קראו \"בית\". ובא משה רעיא מהימנא והוסיף עוד פעם התנוצצות שם \"מחנה\" הרי לך ה' פעמים \"מחנה\" שעולה תקט\"ו, והוא ענין תקט\"ו תפילות. והדברים מופלאים. יבח\"ר].","b":false}]},{"id":"19","t":"הלכה בידוע עשו שונא ליעקב","p":[{"t":"וַיָּרָץ עֵשָׂו לִקְרָאתוֹ וַיְחַבְּקֵהוּ וַיִּפֹּל עַל צַוָּארָו וַיִּשָּׁקֵהוּ וַיִּבְכּוּ: (לג, ד)","b":true},{"t":"וכתב רש\"י ז\"ל, וישקהו - נקוד עליו, ויש חולקין בדבר הזה בברייתא דספרי, יש שדרשו נקודה זו לומר שלא נשקו בכל לבו, אמר רבי שמעון בן יוחאי הלכה היא, בידוע שעשו שונא ליעקב אלא שנכמרו רחמיו באותה שעה ונשקו בכל לבו, עכ\"ל (וראה ספרי בהעלותך פיסקא יא ותנחומא שמות פכ\"ז).","b":false},{"t":"ושאלתי למה אמר רבי שמעון בר יוחאי \"הלכה\" שעשו שונא ליעקב, והיה לו לומר \"עובדא היא\" בידוע שעשו שונא ליעקב, או \"מציאות היא\" וכו', ומה ענין \"הלכה\" לדבר זה.","b":false},{"t":"והנראה בס\"ד דרשב\"י זיע\"א, מלמדנו, ששנאת עשו אלינו אינה דבר המתחלף ומשתנה, וע\"כ לא אמר \"עובדא\" כי העובדא משתנה, והמציאות בת חלוף היא, משנה עתים ומחליף את הזמנים, אבל ההלכה היא דבר קבוע אשר לא יזוע ולא ינוע, והוא אחד מי\"ג עיקרי האמונה, שהתורה לא תשתנה ולא תתחלף בשום זמן ח\"ו. וגם השנאה הזאת אינה תופעה זמנית ועראית, אלא \"הלכה\" היא.","b":false},{"t":"וזהו גם דקדוק הלשון \"הלכה בידוע\" דלכאורה קשה הלשון דאם הוא \"הלכה\" א\"כ למה צריכים אנו ל\"בידוע\", ואם הדבר \"ידוע\" א\"כ מדוע אנו צריכם ל\"הלכה\". אמנם זה מה שרשב\"י דקדק לומר, כי גם במקום שאין שנאת ישראל ידועה ורואים שבני אדום אוהבים אותם, דע כי הכל שקר וכזב, כי \"הלכה\" היא עשו שונא ליעקב.","b":false},{"t":"וכשאמרתי רעיון זה ברבים, היה מי ששאל ואמר, דלפי זה אנו במצב קשה שאין בו תקוה ח\"ו, כי נשאר שנואים לעולם.","b":false},{"t":"והשבתיו דאף על פי כן יש תקוה, כי אם אנו מטיבים את מעשינו, ועושים רצון בוראנו, הוא ברחמיו מכניע את לב שונאינו ומנדינו ונותן בלבם רחמים עלינו, ומקרא מלא דיבר הכתוב (משלי טז, ז), ברצות ה' דרכי איש גם אויביו ישלים עמו.","b":false},{"t":"וזה מה שהיה אצל יעקב דבאותו מקום שנאמרה הלכה זו שעשו שונא ליעקב, שם הוסיף רשב\"י ואמר, שבאותה עת נכמרו רחמי עשו על יעקב ונשקו באמת ובלב שלם.","b":false}]},{"id":"19","t":"הטומאה מנסה בכל כחה לינק מן הקדושה","p":[{"t":"עַל כֵּן לֹא יֹאכְלוּ בְנֵי יִשְׂרָאֵל אֶת גִּיד הַנָּשֶׁה אֲשֶׁר עַל כַּף הַיָּרֵךְ עַד הַיּוֹם הַזֶּה כִּי נָגַע בְּכַף יֶרֶךְ יַעֲקֹב בְּגִיד הַנָּשֶׁה: (לב, לב)","b":true},{"t":"ופירש מרן האוה\"ח הקדוש זללה\"ה (שם), וז\"ל, פירוש לצד שנזדעזע הגיד ממקור הקדושה, ושלט בו הקליפה, בחינה זו בכל מקום שהיא נטמאה, ואסרה הבורא כי הוא היודע, ותמצא סוד בזה, כי גיד זה אין בו טעם, והוא סימן לבחינת הקליפה, כי אין בה טעם כיון שנעקרה קדושה ממנו, ויש בזה פשטים לומר, אלא שהעיקר כמו שכתבתי, עכלה\"ק.","b":false},{"t":"ולהבין דברי קדוש, הנה ידוע שבמקום שהקדושה נמצאת, אין הקליפה יכולה לינק משם, כי האור הגדול של הקדושה הוא כל כך חזק ועצום, עד שאין הקליפה יכולה להתקרב לשם, ואשר על כן, פעמים רבות יונקת דרך אחוריים, ששם האור מועט ומצומצם. ואינה יונקת רק אחר הסתלקות הקדושה, דידוע שאחר שהקדושה מסתלקת נשאר שם רשימו דקדושה, ומשם הם יונקים.","b":false},{"t":"ובזה מתפרש היטב הענין שהמת הוא אבי אבות הטומאה, דבחיים חיותו של כל ישראלי, יש בקרבו נשמה טהורה שהיא חלק אלוה ממעל, ואין הקליפות יכולים לשלוט בו לינק ממנו, והם נאחזים רק בקצותיו, ומשום כך יש צפרנים בקצות האצבעות בידים וברגלים, ואנו קוצצים אותם למעט יניקתם, וכן השערות שהם קצוות נקצצות, וכן אות ברית, שהוא סיומא דגופא יש בה ערלה, ומצות המילה ביום השמיני באה לטהרת האדם והכשרתו לתורה ומצות וכו'.","b":false},{"t":"והנה אחרי מות האדם, הנשמה שבה לבית אביה כבתחילה, אל המקום שממנו חוצבה באש להבה, והגוף נשאר פנוי מן הקדושה. ורק הרשימו נשאר בו, ומיד כל כחות הטומאה נקבצים ובאים לינק ממנו מאותה לחלוחית דקדושה שנשארת בו, ולכן הוא אבי אבות הטומאה.","b":false},{"t":"ויבואר היטב עפ\"י המשל המופלא של מרן האוה\"ח הקדוש זיע\"א, בפרשת חוקת (במדבר יט, ב), וזה תוכן דבריו, משל לשני כלים שהיו אצל בעל הבית, אחת מלאה דבש, ואחת מלאה זפת, ופינה אותם והוציאם לחוץ מהחדר, אותה שהיתה מלאה דבש, מתקבצים לה כל הזבובים והרמשים, ואותה שהיתה מלאה זפת הגם שיכנסו לה קצת מהרמשים לא ישוה לשל דבש, כמו כן אדם מישראל שמת, להיותו מלא קדושה המתוקה והעריבה, בצאת הנפש ונתרוקן הגוף יתקבצו הקליפות לאין קץ, שהם כחות הטומאה, התאבים תמיד להדבק בקדושה ליהנות מהערבות, ולזה יטמא באהל, ואפילו אלף בתים מקורים, ואחת פתוחה לחברתה הטומאה תמלא כל החדר המקורה, מה שאין כן אשר לא מזרע ישראל להיותו מושלל מהקדושה אין כל כך התקבצות הטומאה אלא חלק הממית הנדבק בגוף, ואשר יסובב הכל היא התורה וכו', ע\"כ, ע\"ש ותרוה נחת.","b":false},{"t":"והנה בגמרא אמרו (שבת קנא, ב בראשית רבה לד, יז), רבי שמעון בן אלעזר אומר, תינוק בן יומו חי, אין צריך לשומרו מן החולדה ומן העכברים, אבל עוג מלך הבשן מת, צריך לשומרו מן החולדה ומן העכברים, שנאמר, ומוראכם וחתכם יהיה, כל זמן שאדם חי, אימתו מוטלת על הבריות, כיון שמת בטלה אימתו. ע\"כ.","b":false},{"t":"ואימה זו היא מכח הקדושה של הנשמה, אשר לרוב אורה אין החיצונים יכולים להתקרב אליה, ואעפ\"י שיש לכל אחד ואחד אלף מזיקים משמאלו, ורבבה מימינו, כמו שנאמר (תהלים צא, ז), יפול מצדך אלף ורבבה מימינך ומצינו בברכות (ו, א), תניא אבא בנימין אומר אלמלי נתנה רשות לעין לראות אין כל בריה יכולה לעמוד מפני המזיקין, אמר אביי אינהו נפישי מינן וקיימי עלן כי כסלא לאוגיא, אמר רב הונא כל חד וחד מינן אלפא משמאליה ורבבתא מימיניה וכו', יעו\"ש. מ\"מ ממשיך הכתוב (תהלים שם, שם-ח), אליך לא יגש רק בעיניך תביט וְשִׁלֻּמַת רשעים תראה. דאין למזיקין רשות לגשת לאדם ולינוק ממנו, כל זמן שהנשמה בקרבו, וכנ\"ל.","b":false},{"t":"ולפי גודל קדושתו ושמירתו של האדם, כך גודל אימתו וחיתתו מוטלת על הבריות, ומצינו בשבת (קנא, ב וראה סנהדרין לח, ב), אמר רב פפא, נקיטינן אריה אבי תרי לא נפיל, ומקשה בגמ', הא קא חזינן דנפיל. ומתרץ, ההוא כדרמי בר אבא דאמר רמי בר אבא, אין חיה שולטת באדם עד שנדמה לה כבהמה שנאמר (תהלים מט, יג ושם כא), אדם ביקר בל ילין נמשל כבהמות. ע\"ש. ולמדנו מדברי הגמ' שאימתו של האריה מוטלת על הבריות, מפני שהחטא גורם לחלישות הקדושה, וממעט את הדמות, עד שמסתלק ממנו הצלם האלהי, וחיתת החיות מוטלת עליו, אבל מי ששומר על הצלם אלהים שעליו ומשמר את עצמו מן החטא, הרי אימתו מוטלת גם על אריה ונמר.","b":false},{"t":"וכאשר כתב בספר שער בת רבים הנדפס בחומש רב פנינים, בפרשת נח על הפסוק (ט, א), ומוראכם וחתכם יהיה על כל חית הארץ. והקשה שם הרי ראינו כמה פעמים כי ארי או דוב ימית אדם ואינו ירא ממנו. וכתב לפרש שהענין הוא כי ה' יצר את האדם בצלמו בצלם אלהים על פניו, ובשומרו תורה ומצות, הריהו שומר בזה את צורתו וצלמו, צלם אלהים שבו בקדושה ובטהרה, ואז יראים ממנו כל הבעלי חיים ולא ישלטו בו, כמו שנאמר (תהלים צא, יג), על שחל ופתן תדרוך וגו', וכמו שמצינו ביוסף הצדיק שהשליכוהו אחיו בבור נחשים ועקרבים, ודניאל שהשליך אותו דריוש בגוב אריות, ור' תנחום דשדיוהו לביבר ולא אכלוהו (סנהדרין לט, א), והרב אוה\"ח הקדוש שהושלך לגוב אריות וניצול ממנו, והיה עי\"ז קדוש ה' גדול כדאיתא בשם הגדולים (אמנם בשם הגדולים לא נזכר זה על רבנו חיים בן עטר כי אם על רבינו יהודה בן עטר זללה\"ה, זיע\"א, מ\"מ יעוי' בספר מלכי רבנן למהר\"י ן' נאיים ז\"ל בערך הרב אוה\"ח הק' שסיפר שם שניצול מן האריות, יעו\"ש). אבל האדם אשר יחטא ונמשך אחר תאות העוה\"ז, אז נשתנה צורת פניו, והוא נמשל כבהמה, והוא קטן ושפל מהבעלי חיים, והיה כל מוצאו יהרגהו כדרך הטבע שהגבור יעוז על החלש, ורוב הבעלי חיים הם חזקים יותר מבני אדם וכו'. עכ\"ל.","b":false},{"t":"ופירשתי בס\"ד (ראה לעיל פר נח מאמר יא), דמה שאמרו בגמ' דשבת שם, עוג מלך הבשן מת צריך לשומרו מחולדה ומעכברים, הכונה היא לכחות הטומאה, כמ\"ש בירושלמי (הובא בתוס' ב\"מ מ, א ד\"ה וכי מה), דהני עכברי רשיעי נינהו, ואף החולדה היא בחינת נוקבא מהסט\"א (וראה חס\"ל מעין ה' נהר ל'), והיא קשה וחזקה יותר מן הזכר, וכמ\"ש האוה\"ח הקדוש בפרשת ויחי (בראשית מט, יא), על הפסוק אוסרי לגפן עירה ולשורקה בני אתונו, יע\"ש שהביא כן מדברי הזוה\"ק (ח\"ג רלא, ב).","b":false},{"t":"ועפי\"ז יובנו דברי רבנו בעל אוה\"ח הקדוש כאן, שכ' שלצד שנזדעזע הגיד ממקור הקדושה, ושולט בו הקליפה וכו'.","b":false},{"t":"והספורנו כתב (שם), בענין גיד הנשה, על כן לא יאכלו בני ישראל, כדי שיהיה ההיזק אשר הורע בנגיעת כף הירך, היזק בדבר בלתי חשוב אצלנו. עכ\"ל.","b":false},{"t":"וקשה להבין את זה, דאטו משום מעשה שהיה נתחדשה מצוה בתורה, והרי התורה קדמה לבריאת העולם תתקע\"ד דורות. ואע\"ג דיש מזה תוצאות, ונפקא מינה לדברים השייכים לכלל ישראל, מ\"מ לא יתכן שזה יהיה השורש למצות התורה [ובאמת שהספורנו ז\"ל דקדק כן מדכתיב \"על כן\" לא יאכלו וגו'].","b":false},{"t":"ואולי יש לומר, שעל כן ניתנה מצוה זו מראש ומעיקרא, כדי שבבא המעשה הזה לא יהיה ממנו היזק גדול. ודומה למצות פסח וסוכות, דאע\"ג דנכתבו בתורה בטרם הרים יולדו, מ\"מ נקבעו ע\"י בורא העולם ומנהיגו קורא הדורות מראש אשר לו נתכנו עלילות, והוא עילת העילות וסיבת הסיבות [א\"ה על ענין הזה שנכתבו בתורה קורות ישראל וגם אלו התלויים בבחירתם, ועל הקושי כיצד היה כדבר הזה, הנה הרב ברוך טעם בספר מרגניתא דרב הביא בזה דברים נפלאים בשם הגר\"א וכן הוא בענף יוסף על עין יעקב ב\"ב טו, א, ועי' עוד בזה בספר דברי יואל לקהלת אות ב'. יבח\"ר].","b":false}]},{"id":"19","t":"מנחת יעקב לעשו כמה היתה","p":[{"t":"וַיָּלֶן שָׁם בַּלַּיְלָה הַהוּא וַיִּקַּח מִן הַבָּא בְיָדוֹ מִנְחָה לְעֵשָׂו אָחִיו, עִזִּים מָאתַיִם וּתְיָשִׁים עֶשְׂרִים רְחֵלִים מָאתַיִם וְאֵילִים עֶשְׂרִים, גְּמַלִּים מֵינִיקוֹת וּבְנֵיהֶם שְׁלשִׁים פָּרוֹת אַרְבָּעִים וּפָרִים עֲשָׂרָה אֲתֹנֹת עֶשְׂרִים וַעְיָרִם עֲשָׂרָה: (לב, יג-טו)","b":true},{"t":"כתב ר\"י בעל הטורים וז\"ל, עזים מאתים, כל תיבה של זה הפסוק מסיים במ\"ם. וכן פסוק ומנחתם ונסכיהם (במדבר כט, לג). שבשביל הבהמות ששלח לעשו והם תק\"ן בהמות, ולא סמך על הבטחת הקב\"ה, הוצרכו בניו להביא תק\"ן קרבנות בשנה, כדמפרש בפרשת פנחס. והם ח' ממי\"ן וכנגדם מלכו ח' מלכים באדום לפני מלוך מלך בישראל. ע\"כ. ונראה שהבין שהגמלים המניקות ובניהם עולין יחדיו למנין שלשים, ולכן יצא לו מנין תק\"נ.","b":false},{"t":"ואולם רבינו בעל אוה\"ח הקדוש כתב, שמעתי ממורי זקני זצוק\"ל (הוא רבינו חיים ן' עטאר הזקן ז\"ל), שנתכוין יעקב בחשבון ששלח מהבעלי חיים כחשבון שעיר שעולה כמנין תק\"פ (580). עזים ורחלים ארבע מאות וארבעים, וגמלים שלשים עם בניהם, הם ששים, הרי חמש מאות, פרות ופרים חמשים, ואתונות ועירים שלשים הרי (חמש מאות ושמנים שהם), \"תקף\", לשבר תקפו. עכל\"ה.","b":false},{"t":"הרי לנו שהרב ז\"ל מפרש גמלים מניקות ובניהם שלשים, כלומר שלשים מהמניקות ושלשים מהבנים שלהם, שעולים ביחד לששים.","b":false},{"t":"ובזה יובן ענין שעיר המשתלח לעזאזל המדברה, שכנגדו שלח יעקב מנחה חמש מאות ושמנים בעלי חיים לעשו, שהוא כמנין שעי\"ר, ושלח שעי'ר לשעי'ר, כי עשו איש שעיר (בראשית כז, יא), ובכל ר\"ח גם כן מקריבים שעיר כדכתיב (במדבר כח, טו), ושעיר לכפר. ועוד אמר לו להלן (בראשית לג, יד), עד אשר אבא אל אדוני שעירה. ואמרו רבותינו (ב\"ר עח, יד והוב\"ד ברש\"י בראשית שם), שיעקב לא הלך לשעיר, ואימתי ילך, בימי המשיח שנאמר (עובדיה א, כא), ועלו מושיעים בהר ציון לשפוט את הר עשו. ולכן הכין יעקב מנחה לאחיו שיש בה תק\"פ בעלי חיים, כדי להכניעו באותו תוקף שלו, ואין הדין נמתק אלא משורשו (ראה ע\"ח שער י\"ג פי\"א ושעה\"כ דרושי העמידה דרוש ה' ובלקוטי תורה פרשת וישב ופע\"ח שער השופר פ\"א).","b":false},{"t":"* * *","b":false},{"t":"יעקב שלח לעשו אבנים טובות ומרגליות","b":true},{"t":"עוד אמר, ויקח מן הבא בידו מנחה, וכתב בעל הטורים, ששלח לו אבנים טובות שאדם צוררן בידו. \"מנחה\" בגימטריא \"אבנים\", עכ\"ל. וזכורני שבפירוש הקצר של הראב\"ע ז\"ל כתב ששלח לעשו מת ורגליו בתוכו. והוא מרגליות. כי \"מרגליות\" תחילת המלה וסופה הוא \"מת\" ובאמצעה הוא \"רגליו\", ודו\"ק.","b":false}]},{"id":"19","t":"המאבק עם היצה\"ר - מאבק ללא סוף","p":[{"t":"וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו אֶל עֵשָׂו אָחִיו אַרְצָה שֵׂעִיר שְׂדֵה אֱדוֹם וגו': (לב, ג)","b":true},{"t":"הנה כל ימיו של יעקב אבינו ע\"ה היו רצופים מאבקים קשים ומרים, עד שקרא על עצמו (ראה ב\"ר פד, ג), את מאמר הכתוב (איוב ג, כו), לא שלותי ולא שקטתי ולא נחתי ויבא רוגז, ובהיותו לפני פרעה אמר (בראשית מז, ט), מעט ורעים היו ימי שני חיי ולא השיגו את ימי שני חיי אבותי בימי מגוריהם. והנה עתה יעקב עומד ניצב בפני שני מאבקים קשים, המאבק עם אחיו עם עשו, וקדם לו המאבק עם המלאך שהוא שרו של עשו.","b":false},{"t":"והנה מצינו הבדל גדול בגישתו של יעקב אבינו לכל אחד משני המאבקים הללו, שכן לקראת המאבק עם אחיו עשו, הכין יעקב את עצמו לשלשה דברים, לדורון, לתפלה, ולמלחמה (רש\"י בראשית לב, ט), והתורה גילתה לנו מפורשת רק את הכנת הדורון שהכין יעקב, ורואים באיזה דקדוק נפלא הכין את הדורון, הכל במספר ובחשבון, ומצינו לו ששם ריוח בין עדר ובין עדר, והכין את שלוחיו מה יאמרו לעשו, והוא הולך אחר המנחה, עד שממש לא דילג על שום פרט ולו הקטן ביותר, ואם בדורון נהג כך, צא וחשוב איך היתה הכנת המלחמה, ובאיזה דקדוק נפלא, ומן הסתם עשה את כל הכנותיו בחכמה בדעת ובתבונה. ומי יוכל לתאר כמה השקיע אבינו הזקן בהכנת התפלה לעת כזאת.","b":false},{"t":"ואולם במאבק עם המלאך לא עשה שום הכנה, לא גדולה ולא קטנה, אלא מיד נאמר (בראשית לב, כה), ויאבק איש עמו, עד עלות השחר ולא נזכרה שום הכנה למאבק הזה כלל ועיקר.","b":false},{"t":"והנראה בזה בס\"ד, דהמאבק עם המלאך שרו של עשו, שהוא גם שר של סטרא אחרא, הוא היצה\"ר והוא השטן (ראה ב\"ב טז, א), הוא מאבק הכרחי ואין אפשרות להפטר ממנו, כי לכך נוצר האדם להאבק עם יצרו, ולעבוד את יוצרו מתוך בחירה חפשית, והשטן הוא היצה\"ר נברא לצורך הנהגת העולם, כי הי\"ת יוצר אור ובורא רע (ראה ישעיה מה, ז), וזה לעומת זה עשה אלהים (קהלת ז, יד). ואעפ\"י שלעתיד לבא עתיד הקב\"ה לשחוט את היצה\"ר (ראה סוכה נב, א), מכל מקום, לעת עתה יש בו צורך לעולם. והיצר לפתח חטאת רובץ (בראשית ד, ז), ומיום שנולד האדם הריהו נולד אל תוך המאבק הזה, ולא נפטר ממנו עד זיבולא בתרייתא ועד בכלל, ואין ענין מיוחד להתכונן אליו במיוחד לעת הזאת, כי הוא מאבק תמידי שאינו פוסק לעולם, ונאמר (קהלת ט, ח), בכל עת יהיו בגדיך לבנים ושמן על ראשך אל יחסר. אך אין צורך בהכנה מיוחדת לענין זה, אלא מיד החל המאבק, \"ויאבק איש עמו\".","b":false},{"t":"אבל המאבק עם אחיו עשו אינו הכרחי, אלא שהלכה היא שעשו שונא ליעקב (ראה ספרי בהעלותך פיסקא יא ותנחומא שמות פכ\"ז), ומבקש את נפשו לקחתה, ומלחמה זו היא מלחמה מיוחדת, וראה יעקב אבינו צורך מיוחד להתכונן אליה, ובפרט שעשו היתה לו טענה חזקה נגד יעקב, דמה לו ליעקב ולברכות ולכל עניני העוה\"ז, כי הרי מכבר חלקו ביניהם עוד בהיותם בבטן אמם, ויעקב לקח לו העוה\"ב ועשו לקח את העוה\"ז לחלקו ונחלתו (כמבואר בתנדא\"ז פי\"ט וראה מש\"כ לעיל פרשת וישלח מאמר ב). ועשו תמה איך יעקב אומר (בראשית לב, ו), ויהי לי שור וחמור צאן ועבד ושפחה. וידוע שחקרו הקדמונים ז\"ל (ראה בספר נפש חיים למרן החבי\"ף מערכת היו\"ד אות נ' שהביא קושיא זו והביא ע\"ז ששה עשר תירוצים), איך מותר לנו ליהנות מהעוה\"ז, והרי הוא חלקו של עשו, ותירצו דכיון דכתיב (ירמיה לג, כה), אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי, נמצא שע\"י לימודנו אנו מקיימים את העולם, ובלעדינו אין קיום לא לגוים ולא לעולם, ואנו נצרכים לקבל כדי חיותינו מן העולם כמאמרם ז\"ל (אבות ג, יז), אם אין קמח אין תורה, ע\"כ מותר לנו לקחת קיומנו מהעולם, כי בודאי ניחא להו לגוים לו חכמו ישכילו זאת, להבין שזה הקיום של העולם (ונתבאר עוד לעיל פר' וישלח מאמר ב). והנה עשו בא להלחם ביעקב בהיותו מצויד בטענה חזקה, שהעולם הוא עולמו שלו, ואין ליעקב שום חלק וזכות בו.","b":false},{"t":"ויעקב ע\"ה הכין עצמו לדורון, היינו לפייס את דעת עשו, כדי שיהיה מוכן להטות אזן ולשמוע את דבריו של יעקב, וכמובן הכין עצמו גם לתפלה כדי שאויבו עשו ישלים עמו, ובנוסף לזה עוד הכין את עצמו למלחמה, למקרה שבו יעמוד עשו בעקשנותו וירצה להלחם. כי האדם הוא בעל בחירה חופשית, ויכול לבחור ברע בדוקא, ע\"כ התכונן יעקב אבינו גם למלחמה עם עשו לעת הצורך.","b":false},{"t":"ואולי משום כך אמר יעקב לעשו עם לבן גרתי (בראשית לב, ה), ומילת גרתי הוא תרי\"ג, לומר, כי תרי\"ג מצות שמרתי ולא למדתי ממעשי לבן הרעים (רש\"י שם). ואמר יעקב את כל זה לעשו, כדי שיבין מדוע יש לו שור וחמור, וביקש להראותו כי על ידו מתקיים העולם, ולכן בדין הוא שיטול שכרו, וחלקו הוא נוטל. ובלעדי זה אין לו מובן, מה יוצא ליעקב אבינו במה שהוא מספר לעשו שהוא שמר את תרי\"ג מצות בהיותו אצל לבן.","b":false},{"t":"והקב\"ה סייע ביד יעקב אבינו והכניע את לבו הערל של עשו, ונמלא לבו באהבה ליעקב, ואע\"פ שהלכה בידוע שעשו שונא ליעקב, מכל מקום נכמרו רחמיו על יעקב באותה שעה ונשקו ליעקב ובכה על צואריו (ראה ספרי בהעלותך פיסקא יא ותנחומא שמות פכ\"ז).","b":false}]},{"id":"19","t":"המלאכים בעזר האבות הקדושים","p":[{"t":"וַיִּשְׁלַח יַעֲקֹב מַלְאָכִים לְפָנָיו אֶל עֵשָׂו אָחִיו אַרְצָה שֵׂעִיר שְׂדֵה אֱדוֹם: (לב, ג)","b":true},{"t":"ורבותינו אמרו (ב\"ר עד, ד), וישלח יעקב מלאכים, מלאכים ממש. ע\"ש. וצריך לומר שהיו ליעקב אבינו עוזרים ושמשים ממלאכי שמים, שהקב\"ה נתן לו לעזרו ולסייעו, וכן עשה לכל האבות הקדושים.","b":false},{"t":"שהרי מנהג העולם כן הוא, שכל ממשלה מעמידה לכל אחד מן השרים עוזרים ויועצים וכו', כדי שיהיו לו לעזר בביצוע תפקידו הרם, כל דבר לפי ענינו. והאבות הקדושים שהם שרים גדולים העוסקים במלאכת הי\"ת בעולמו, להביא דבר ה', ולקרב לבות בני אדם לאביהם שבשמים, וללמד דעת ה' וחכמתו, ועשיית צדק ומשפט, ומלמדים לבני האדם שיעשו חסד זה עם זה, ושיאהבו אמת ושלום וכו', אם כן, צריכים הם עוזרים נאמנים ומיומנים במלאכתם מלאכת שמים, והקב\"ה שבחר בהם בעבודתם הקדושה, העמיד להם מלאכים מן השמים להיות להם לאחיעזר ואחיסמך, ואינם צריכים לשום עזר אחר, כי מלאכי רום, עומדים הכן לשירותם, ולעשות כל חפצם.","b":false},{"t":"[א\"ה - ובזוהר פר' עקב (ח\"ג רעב, א), איתא, מיכאל גבריאל נוריאל שמשין דתלת אבהן, והם ר\"ת \"מגן\", וראיתי בשם ספר מעשה רוקח בפירושו למשניות חלה שכ' כי מיכאל גבריאל נוריאל עולה בגימ' אברהם יצחק יעקוב (מלא וי\"ו).","b":false},{"t":"ובילקוט שמעוני (בראשית רמז קל\"ב), כתב הקדמה נפלאה בשם מדרש אבכיר, וזה לשונו, בשעה שהיו מתאבקים יעקב והאיש שכנגדו, רצה כת של מיכאל לסכנו אלא שנגלה עליהן הקב\"ה, וכיון שראה להקב\"ה תשש כחו שנאמר וירא כי לא יכול לו ויגע בכף ירכו, אמר לו הקב\"ה למיכאל יפה עשית שעשית כהן שלי בעל מום. אמר לו, רבונו של עולם והלא אני כהנך, א\"ל אתה כהני ברקיע והוא כהני בארץ, מיד קרא מיכאל לרפאל אמר לו חברי בבקשה ממך עמוד עמי בצרה, שאתה ממונה על הרפואות ירד ורפאו וכו', אמר ליה הקב\"ה למיכאל למה עשית כן לבני בכורי, אמר לפניו לכבודך עשיתי. אמר ליה, מעכשיו תהא ממונה עליו ועל זרעו עד סוף כל הדורות, הדא הוא דכתיב (דניאל י, כא), כי אם מיכאל שרכם. וכתיב ובעת ההיא יעמוד מיכאל השר הגדול (שם יב, א), וכתיב, כי מי גוי גדול (דברים ד, ז-ח). יבוא גדול ויעמוד על הגדול. אתה אש דכתיב (עובדיה א, יח), והיה בית יעקב אש, יבוא אש ויעמוד על אש. אתה ראש למלאכי השרת והוא ראש לכל האומות, יבוא ראש ויעמוד על הראש. אתה עליון למלאכי השרת והוא עליון, דכתיב (דברים כח, א), ונתנך ה' אלהיך עליון יבוא עליון ויעמוד על עליון ויבקש מן העליון רחמים עליהם, דכתיב (קהלת ה, ז), כי גבוה מעל גבוה שומר וכו'. יבח\"ר].","b":false},{"t":"וזכורני שבסדור הנפלא תפלת החדש דפוס ליוורנו כנוסח החיד\"א זלה\"ה וכן הוא בסדור בית עובד, בתפלת שחרית אחר ק\"ש של שחרית כשאומרים \"עזרת אבותינו\" כתוב שם שיש לכוין בשמות המלאכים מיכאל, מלכיאל, שננדיאל, וחשבתי דרכי שהכונה היא ששלש שמות אלו שהם מלאכים, הן המה היו עזרת אבותינו, שהעמיד להם הקב\"ה לעזרתם, וכנ\"ל. ואם כנים דברינו אלה, נמצאו דברי רבותינו ז\"ל מדוקדקים מאד, שאמרו \"מלאכים ממש\", שהמילה \"ממש\" היא ר\"ת של אותם שלשה מלאכים הנזכרים, שהעמיד הקב\"ה לעזרתם, ואותם שלח יעקב להביא דברו עד עשו אחיו, והוא נפלא.","b":false},{"t":"והראני הרה\"ג ר' יעקב בצלאל חרר ישצ\"ו, בספר דבש לפי למרן החיד\"א זלה\"ה (מערכת מ אות לה), שכה כתב, כי יש מלאכים שעזרו ליעקב בעת צרתו מעשו, והיה זה בכח עליון, והם, מיכאל מלכיאל שננדיאל, גימטריא עזר\"ת, וצריך לכוין באומרו עזר\"ת אבותינו, כ\"כ בזהר חדש הובא בפליאה. וכתב הרב הקדוש מהר\"ש מאסטרופולי ז\"ל שהוא גימטריא \"וישלח יעקב מלאכים\" מספר תרע\"ז כמספר שמות המלאכים הנז', וזה שאמר רש\"י ז\"ל וישלח יעקב מלאכים, מלאכים \"ממש\", כי ר\"ת מלכיאל מיכאל שננדיאל \"ממש\". עכ\"ד. ושמחתי כמוצא שלל רב, שזכיתי לכוין לדברי קדשו, והי\"ת ינחנו תמיד בדרך אמת למען שמו.","b":false}]}]},{"slug":"וישב","name":"פרשת וישב","items":[{"id":"20","t":"בצר הרחבת לי - להתבונן תמיד אך ורק בטובות הי\"ת ולא להתפס לצרות בלבד","p":[{"t":"וַיְהִי כִשְׁמֹעַ אֲדֹנָיו אֶת דִּבְרֵי אִשְׁתּוֹ אֲשֶׁר דִּבְּרָה אֵלָיו לֵאמֹר כַּדְּבָרִים הָאֵלֶּה עָשָׂה לִי עַבְדֶּךָ וַיִּחַר אַפּוֹ, וַיִּקַּח אֲדֹנֵי יוֹסֵף אֹתוֹ וַיִּתְּנֵהוּ אֶל בֵּית הַסֹּהַר מְקוֹם אֲשֶׁר אֲסִירֵי הַמֶּלֶךְ אֲסוּרִים וַיְהִי שָׁם בְּבֵית הַסֹּהַר, וַיְהִי ה' אֶת יוֹסֵף וַיֵּט אֵלָיו חָסֶד וַיִּתֵּן חִנּוֹ בְּעֵינֵי שַׂר בֵּית הַסֹּהַר, וַיִּתֵּן שַׂר בֵּית הַסֹּהַר בְּיַד יוֹסֵף אֵת כָּל הָאֲסִירִם אֲשֶׁר בְּבֵית הַסֹּהַר וְאֵת כָּל אֲשֶׁר עֹשִׂים שָׁם הוּא הָיָה עֹשֶׂה, אֵין שַׂר בֵּית הַסֹּהַר רֹאֶה אֶת כָּל מְאוּמָה בְּיָדוֹ בַּאֲשֶׁר ה' אִתּוֹ וַאֲשֶׁר הוּא עֹשֶׂה ה' מַצְלִיחַ: (לט, יט-כג)","b":true},{"t":"ראינו בפסוקים כי שבר על שבר הושבר יוסף הצדיק. כי אחר שהשליכוהו אחיו אל בור, הוצא משם ונמכר לעבד מיד אל יד, עד שהגיע למצרים, וגם שם לא הונח לו, ובהיותו בבית פוטיפר נפל עליו הנסיון הקשה. ואחר שגבר ונתגבר, עוד הושלך לבית הסוהר.","b":false},{"t":"אמנם בתוך כל זה נגהו עליו שביבי אור, ונאמר עליו בהיותו בבית אדוניו (בראשית לט, ב), וגם בהיותו בבית האסורים \"ויהי ה' את יוסף\" כי הי\"ת נותן לו חן, ומתקיים בכבוד בתוך הענן והערפל שניתך עליו. ואם יוסף הצדיק היה רואה רק את רעותיו, ומתעלם מחסדי ה' עליו להושיעו ולהצילו, הרי שהיה נשבר לבו בקרבו, והיה מגיע עד יאוש בנפשו רח\"ל.","b":false},{"t":"אבל יוסף הצדיק נהג בדרכם של צדיקים, וכל הזמן היה מתבונן אך ורק בטובות הי\"ת עליו. וגם בעת שהיתה בו יד ה', אמר לנפשו הכל לטובה, כי היה יכול להיות בצרות גדולות יותר, באין חן ואין חנינה, והיה יכול לסבול בלא קץ, ולכן היה מודה להי\"ת על חסדיו עמו, והיה מתעודד בנפשו, ואז זכה לעמוד ולהתחזק.","b":false},{"t":"כי הבין שגם הרעות אינן לרעתו אלא לנסותו ולצרפו כצרוף זהב וכסף. כי אם היה רצון עליון להרע עמו, הרי שלא היה עושה הי\"ת עמו חסד ורחמים, בתוך כל הרעות והצרות, כי גם בהיותו בים צרותיו, זכה לקרן אורה בבחינת בצר הרחבת לי (תהלים ד, ב). והיינו, שאף בגוף הצרה עצמה, הי\"ת שולח איזו הרחבה, להורות שלא מפני שכלו רחמיו עמנו הוא מייסרנו, אלא כאשר ייסר איש את בנו ה' אלהיך מייסרך (דברים ח, ה), והכל הוא כדי לזכך ולצרף את האדם.","b":false},{"t":"וסופו הוכיח שהכל נעשה לטובה, כי הי\"ת העלהו מבור בית הסוהר אל כסא מלכות, ומצינו לו ליוסף שאמר לאחיו (בראשית נ, כ), \"אתם חשבתם עלי רעה אלהים חשבה לטובה למען עשה כיום הזה להחיות עם רב\", ולא זכר להם לרגע את כל הרעה שהיה סובל בעבורם.","b":false},{"t":"ואם יתבונן האדם יראה את חסדי ה' ונפלאותיו עמו בכל צעד ושעל, וגם הדברים הרעים שבאים עליו הם רק לטובתו ולהצלחתו, כאשר מצינו ביוסף, כי בתחילה ירד הוא למצרים, להכין דרך לאביו סבא קדישא ולאחיו, כדי שלא ירדו בשלשלאות של ברזל למצרים כמבואר בדברי רבותינו במדרש (ב\"ר פו, ב), משל לפרה שהיו מושכין אותה למקולין ולא היתה נמשכת, מה עשו לה, משכו את בנה לפניה, והיתה מהלכת אחריו על כרחה שלא בטובתה. כך היה יעקב אבינו ראוי לירד למצרים בשלשלאות ובקולרין, אמר הקב\"ה בני בכורי ואני מורידו בבזיון, ואם ליתן בלבו של פרעה איני מורידו פומבי. אלא הריני מושך את בנו לפניו, והוא יורד אחריו על כרחו שלא בטובתו, והוריד את השכינה למצרים עמו וכו'. ע\"כ. ומתבאר מדברי המדרש כי יוסף הצדיק לא היה יורד מצרימה ברצון ומותר על הישיבה עם אביו, ועל הנעימות לחיות בצלו. ועל כן גלגל עליו הקב\"ה שימכרוהו מיד ליד עד שהגיע למצרים, ושם נמכר לפוטיפר שהיה שר חשוב. ואולי זימנו מן השמים כך, כדי שילמד יוסף ממנו את טכסיסי ומנהגי מלכות מצרים, שבבא עת דברו לעמוד לפני פרעה ידע לשאת ולתת עמו, וכעין מה שכתב רבינו אברהם ן' עזרא ע\"ה בענין משה רבינו שמאת ה' היתה לו לגדול אצל פרעה כדי שילמדנו טכסיסי מלוכה ותגדל נפשו במדרגה עליונה (ראה בפירושו לשמות ב, ג). וכן נעשה עם יוסף הצדיק, ונשאר בבית פוטיפר עד הנסיון הגדול באשת פוטיפר אשר על ידו עלה במעלות התורה והקדושה, ונודעה צדקותו ויושר לבבו עם אלהים ואדם. ואז נסתבבה סיבה מאת הי\"ת להורידו אל בית הסהר, שם אסורים שרי המלך, ובזה נפתח אשנב להביא את יוסף לפני פרעה בבא היום.","b":false},{"t":"כי בבית הסוהר הכיר יוסף את שר המשקים ופתר לו חלומו כהוגן, וכן היה, שהמלך השיבו על כנו (ראה בראשית פרק מ), ולא זכר שר המשקים את יוסף. אך בהגיע העת, עת מלכותו של יוסף, עשה הי\"ת ופרעה חלם חלומות מבעיתים (כמבואר בפר' מקץ), ושר המשקים רצה לעזור למלך כדי למצוא חן בעניו, והעלה את זכרו של יוסף וחכמתו, ובזה עלה יוסף ונתעלה, עד אשר נהיה משנה למלך. ובעבורו נעשה הרעב במצרים, והוא חימש לכל הארץ, ועי\"ז גם אביו וביתו באו מצרימה בכבוד מלכים. וכן הוא מעשה מרדכי ואסתר כמבואר במגילה לכל מתבונן בעין פקוחה, וכן הם דרכי החיים כולם, שכל הנותן אל לבו לראות ולחשב את הקורות עמו יראה ויתבונן את חסדי הי\"ת עמו.","b":false},{"t":"(בס\"ד אור ליום י' אדר התשס\"ו)","b":false}]},{"id":"20","t":"ההצלה מן החטא באה לאדם בזכות עבודתו העצמית","p":[{"t":"וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת, וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה: (לט, יא-יב)","b":true},{"t":"וכתב רש\"י ז\"ל, לעשות מלאכתו, רב ושמואל, חד אמר מלאכתו ממש, וחד אמר לעשות צרכיו עמה, אלא שנראית לו דמות דיוקנו של אביו, כדאיתא במסכת סוטה (לו, ב). עכ\"ל.","b":false},{"t":"וצריכים להבין איך יתכן שהקב\"ה העמיד את יוסף בנסיון גדול כזה, וכשעמד להכשל ח\"ו, ובא לעשות מלאכתו עמה, אז באותה עת, באה דמות דיוקנו של יעקב אביו ע\"ה ונצטיירה בפניו, ואז נרתע לאחוריו, וינס החוצה. ואם הקב\"ה החליט לנסותו, א\"כ למה הוא מסייעו לעמוד בנסיון, והרי הקב\"ה לא מביא לאדם נסיון שהוא מעל לכחו, ובודאי שגלוי וידוע לפניו יתברך, שיוסף הצדיק היה יכול לעמוד בנסיון הזה אם ירצה. כי כל דרכיו משפט ואמונה ואין בו עול, וא\"כ למה יביא לפני יוסף את דמות אביו להרתיעו ולהבריחו.","b":false},{"t":"ופירשתי בזה בס\"ד, דאין כונת רבותינו לומר, שהקב\"ה הביא ליוסף את דמותו של יעקב אביו, אלא שמאליה נצטיירה לפניו. והיה זה מכח עבודת הקדש של יוסף, אשר מיום שעזב את בית אביו לא משה דמות אביו מנגד עיניו, כי בתחילה כשהיה יוסף בבית אביו היה אביו הקדוש עומד על גביו ומלמדו תורה ודעת ה', ומוכיחו לישר אורחותיו מרדת שחת, והיה מסתופף בצילא דמהימנותא ובטוח בכל צעדיו והליכותיו.","b":false},{"t":"אמנם כשנמכר בין ערלים שטופי זמה, היה עומד בנסיונות רבים, ויום יום היו לו שאלות ולא היה לו למי לשאול, וממי ליטול עצה, וחשב ומצא לו עצה והדרכה טובה, שבכל שאלה שתבא לפניו, ולכל בעיה ומבוכה אליה נקלע, היה עומד ומתבונן, ומצייר בדמיונו את דמותו הגדולה של אביו לנגד עיניו, עד שהיה מתמלא רגש של יראה ופחד, מפני קדושתו הגדולה של אביו סבא קדישא, ומרגיש בעצמו שאביו נצב עליו וצופה ומביט בעיניו בכל אשר הוא עושה, ואז היה מעמיד בעיני רוחו את שאלתו וספיקותיו, ומתבונן עוד לומר, האם היה עושה דבר כזה למול עיני אביו, או לא. וכך היה בוחן ומודד את הדברים. ואת הדבר הזה היה עושה בכל עת אשר נקרה לאיזה מצב, ובכל שאלה שבאה לדרכו, והיה שונה ומשלש בזה דבר יום ביומו, עד שההרגל נעשה טבע, ולא היה צריך כ\"כ להתאמץ אלא מאליו היה נעשה הדבר, ודמות אביו מצטיירת בפניו.","b":false},{"t":"ובעת הקשה ההיא כשגברו נסיונותיו, ואשת פוטיפר עשתה מעשה שתפסה בבגדו, והיה נתון בין שתי סכנות חמורות, בין סכנת העבירה לבין סכנת המות. ורובץ בין המשפתים, אם להכנע אליה, והיה חוטא לאלהים ח\"ו, או לברוח ולהניח את בגדו אצלה, והיא תאמר שהוא זה אשר בא לתקוף אותה, והיה עומד בסכנת חיים ממש.","b":false},{"t":"והיתה איזו התלבטות לרגע קט, שאת זה קראו חז\"ל, שבא לעשות מלאכתו עמה, ובאותו רגע, נצטיירה שוב מאליה דמות אביו מול עיניו, ולא שמהשמים הביאו לו דבר זה, רק היה זה בבחינת, נוצר תאנה יאכל פריה (משלי כז, יח), שהוא פרי עבודתו בקדש, אשר נהג בעצמו יום יום למען דעת את דרך ה' ומצוותיו, והיא שעמדה לו גם ברגע זה. ומיד פסק את הדין ועשה מעשה, וינס ויצא החוצה.","b":false},{"t":"[א\"ה - יש להביא בכאן דברי קדוש ה' מהר\"ח ן' עטאר ז\"ל באור החיים על הפסוק (ויקרא יט, ג), איש אמו ואביו תיראו, טעם סמיכות מצוה זו למצות קדושים, נתכוון לרמוז גם כן גדר לעריות, והוא על דרך מאמרם ז\"ל (סוטה לו, ב) שדרשו בפסוק ויפוזו זרועי ידיו מידי אביר יעקב וגו' (בראשית מט, כד), כי כשתקפתו אשת פוטיפר ליוסף ותקפו יצרו נזדמנה לו דיוקן אביו ואמר לו וכו' מיד ויפוזו זרועי וגו', ושמעתי משם אנשי אמת, כי דיוקן האב תגביר כח הקדושה בבן, ותמנעהו מבוא אל התיעוב, והוא אומרו סמוך למצות העריות, איש אמו ואביו תיראו, ולזה מי שתקפו יצרו יצייר בין עיניו יולדיו ויהיה לו למשיב נפש, ע\"כ. יבח\"ר].","b":false}]},{"id":"20","t":"מדוע ענה יוסף לאשת אדוניו","p":[{"t":"וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף וַתֹּאמֶר שִׁכְבָה עִמִּי, וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדֹנָיו הֵן אֲדֹנִי לֹא יָדַע אִתִּי מַה בַּבָּיִת וְכֹל אֲשֶׁר יֶשׁ לוֹ נָתַן בְּיָדִי, אֵינֶנּוּ גָדוֹל בַּבַּיִת הַזֶּה מִמֶּנִּי וְלֹא חָשַׂךְ מִמֶּנִּי מְאוּמָה כִּי אִם אוֹתָךְ בַּאֲשֶׁר אַתְּ אִשְׁתּוֹ וְאֵיךְ אֶעֱשֶׂה הָרָעָה הַגְּדֹלָה הַזֹּאת וְחָטָאתִי לֵאלֹהִים: (לט, ז-ט)","b":true},{"t":"העובר על דברי הפסוקים הללו עומד מתמיה כשהוא רואה את מאמר יוסף אל אשת אדוניו, שהוא נראה כמי שמתנצל בפניה, על שאינו מסכים לשמוע לה, בדרישתה הנפשעת. ואדרבה היה צריך להיות גאה בצדקת דרכו, ובגבורת רוחו. והיא זו הצריכה להתבייש במעשיה הרעים שרוצה למעול בבעל נעוריה במרד ובזדון, ותיסרה רעתה ובושתה.","b":false},{"t":"והנראה בזה בס\"ד דיוסף שהיה חכם ונבון וירא ה', הקדים ומיאן בנחרצות עצומה. ואמנם אח\"כ ישב ועשה חשבון בנפשו, איך ימשיך לעמוד בנסיונותיה, כי הרי הוא עבדה ויושב בביתה תמיד, מפיתה יאכל וממשקיה ישתה, ונתון לחסדה. וידע יוסף שלא יוכל לילך ולספר את הענין לאדונו פוטיפר, כי בזה לא ישיג מאומה שהרי היא תשיב אמריה לבעלה, ותהפוך את חטאה על יוסף, והוא יאמין לאשתו, ויאשים את העבד העברי, וכאשר כן היה בסופו של דבר, ורק נס היה מאת ה' שלא הרגו נפש, ותחת זאת השליכו לבית הסוהר (עי' רמב\"ן בראשית לט, יט).","b":false},{"t":"וחשב בדעתו שלא די לו במיאונו החזק, ועלול הוא לעמוד בעוד נסיונות רבים, והן קי\"ל (אבות ב, ד), אל תאמן בעצמך. ועל כן עלה בדעתו שיחד עם הסירוב הגדול, יאמר לה דברי תוכחה ומוסר, אולי יתעורר בלבה גודל הרעה שמשיבה לבעלה תחת טובתו, ונקט לשון ערומים, והיה תולה את הדבר בעצמו, באומרו, ואיך אעשה הרעה הגדולה הזאת לאדוני, תחת כל טובותיו ותחת אשר נתן כל אשר לו בידי, ועוד הוסיף ואמר, איננו גדול בבית הזה ממני, ולא חשך ממני וגו', כדי לעורר את לבה לאמר, והלא אני הגדולה בבית הזה, וגם אם כונת יוסף שאין בעבדים גדול ממנו, מ\"מ אני היא בעלת הבית, ואני צריכה לתת דוגמא ומופת, ותבוש במעשיה ותחזור בה, ותחדל מענות אותו בנסיונותיה יום יום.","b":false},{"t":"ועוד הוסיף ואמר, \"ואיך אעשה הרעה הגדולה הזאת\", כלומר שלא יקל בעיניה חומרת העבירה הזאת שהיא באמת רעה גדולה ושאין גדולה ממנה, ואם תאמר והלא אין רואה ואין איש בבית וכו', ע\"כ סיים אמרתו באומרו, \"וחטאתי לאלהים\". שהוא יודע הכל ואין נעלם מעיניו, ולפניו הכל גלוי, כחשכה כאורה. ואנה יסתר מפניו אדם במעלליו.","b":false},{"t":"באופן שדברי יוסף לאשת פוטיפר לא באו כהתנצלות, אלא היה מדבר עמה דברי מוסר חזקים בהוכיחו אותה על פניה בדברי אמת.","b":false},{"t":"ועוד אפשר לומר דראה יוסף והרגיש שבמקום הזה אין יראת ה', והם שטופים בזימה (כי מצרים ערות הארץ היא, ושטופים בזימה כאשר מבואר ביחזקאל כג, כ וראה רש\"י בראשית יב, יט), ונעשה הדבר קל בעיניהם והותרה להם עבירה זאת, עד שנעשית להם כהיתר (ראה יומא פו, ב ושם פז א ומו\"ק כז, ב וקדושין כ, א ושם מ, א וערכין ל, ב). ועד כדי כך היה הדבר מופשט וקל בעיניהם, עד שלא יכלה להבין את מיאונו של יוסף, וחשבה שהוא מייקר את עצמו וכדו', ועל כן היתה ממשיכה בנסיונותיה. וחשב יוסף בדעתו לנסות להסביר לה שבעצם עשיית העבירה יש גם השבת רעה תחת כל הטובות שעשה לו אדונו, ואיך ישיב לו כך. ואולי בזה תשתכנע שאכן יוסף ממאן באמת ותניח לו.","b":false},{"t":"(בעהית\"ש ברביעי בשבת שמנה ימים לאדר התשס\"ו - ג'נבה)","b":false}]},{"id":"20","t":"אין להכנס עם פתויי היצה\"ר בטוען ונטען","p":[{"t":"וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף וַתֹּאמֶר שִׁכְבָה עִמִּי, וַיְמָאֵן וַיֹּאמֶר אֶל אֵשֶׁת אֲדֹנָיו הֵן אֲדֹנִי לֹא יָדַע אִתִּי מַה בַּבָּיִת וְכֹל אֲשֶׁר יֶשׁ לוֹ נָתַן בְּיָדִי, אֵינֶנּוּ גָדוֹל בַּבַּיִת הַזֶּה מִמֶּנִּי וְלֹא חָשַׂךְ מִמֶּנִּי מְאוּמָה כִּי אִם אוֹתָךְ בַּאֲשֶׁר אַתְּ אִשְׁתּוֹ וְאֵיךְ אֶעֱשֶׂה הָרָעָה הַגְּדֹלָה הַזֹּאת וְחָטָאתִי לֵאלֹהִים: (לט, ז-ט)","b":true},{"t":"תיבת \"וימאן\" הכתובה בפסוק מוטעמת בטעם שלשלת, ומיד לאחריה מופיע טעם פסק. ונראה דזה בא ללמד, שיוסף הצדיק מיאן במיאון אדיר וחזק. וגם מיאונו היה פסוק וחתוך, כלומר שמיאונו של יוסף היה בעוצמה רבה ובאופן חד משמעי, ללא שום פתח וסדק לפשרה כל שהיא, ומבלי ליכנס לשום משא ומתן, ובלי להקדים שום הסברים, רק מיאון ברור וסתום.","b":false},{"t":"ורק אחרי המיאון הזה, נתן יוסף לאשת אדוניו דברי הסבר קצרים. באשר היא אשת אדוניו והיא גבירתו, ואפשר שתטען כלפיו, שהוא עבדה וחייב לשמוע לה לכל אשר תצוה אותו. לזה אמר לה, הן אדוני וגו', כלומר, שהוא מחוייב יותר לשמוע לאדונו שהוא פוטיפר, והרי פוטיפר עצמו חשך אותה ממנו, באשר היא אשתו.","b":false},{"t":"והתורה הקדושה מלמדת אותנו בזה, מהי הדרך להלחם ביצה\"ר בעת שהוא תוקף את האדם בחזקה. שאין לשאת ולתת עמו בשום דבר, ולחשוב מה בכך, אני אשיב ליצרי בדברים נכוחים בהגיון וסברא, ואסתום את טענותיו, ואדחה את דרישותיו. חלילה! חלילה לעשות כן. כי זו דרך מועדת הפותחת פתח לסכנה ח\"ו. כי לא בהגיון וחכמה תליא מילתא, אלא באומץ וגבורה אמיתית, להתגבר על הרצון ועל התאוות, ויש לאדם את הכח והיכולת לעמוד כגבר ולהתגבר על יצריו.","b":false},{"t":"אך אם יאריך האדם לשאת ולתת עם יצרו בדברים, הריהו מכניס את עצמו לסכנה עצומה. כי עצם המשא ומתן, נותן מעמד וחשיבות לצד שכנגד, כלומר שהוא ג\"כ מאן דאמר, וצריך לדון עמו. ולא היא, שהרי אין מקום ולו הקטן ביותר להעלות על הדעת דברים שכאלו, ועל כן צריך להמנע מהדיון הזה שעלול להיחשב להכרה במעמדו של היצה\"ר ועצתו, וצריך לצאת בחוזק יד ובגבורה אמיתית ולחתוך הענין בסכינא חריפא, וזהו מיאונו של יוסף, וזה סוד הצלחתו בנסיון הגדול הזה.","b":false},{"t":"[א\"ה - ראה מה שכתב קדוש ה' מכובד רבינו חיים ן' עטר זלה\"ה בספרו הקדוש אור החיים (ויקרא יח, ב), לפרש הפסוק, בני אם יפתוך חטאים אל תאבה (משלי א, י), פירוש בחינת החטא, אל תאבה, פירוש, \"לא תכנס עם פתוייך בטוען ונטען, כי אריכות הרגשת החושב אפילו לבחינת השולל תפעיל הגברת החפץ ותהפך הרצון אליה\", ומצות ה' ברה, באה על הדבר בבחינת דיבור ואמירה, דיבור, לומר גזירת מלך היא דבר מלך שלטון וכו', ע\"ש. ולכן אין לאדם לזוז במאומה מגזירתו יתברך, ויגער בים התאוה ויחרב.","b":false},{"t":"ובמאמר המוסגר יש להביא כאן מעשה נורא שהיה לרבנו אמנון והובא באור זרוע (הל' ראש השנה סי' רע\"ו), וממנו יש ללמוד עד כמה צריך ליזהר להיות נחרץ נגד עצת היצה\"ר ולא ליתן לו שום תירוצים. וזה לשונו, מעשה ברבנו אמנון ממגנצא שהיה גדול הדור ועשיר ומיוחס ויפה תואר ויפה מראה, והחלו השרים וההגמון לבקש ממנו שיהפך לדתם, וימאן לשמוע להם, ויהי כדברם אליו יום יום ולא שמע להם, ויפצר בו ההגמון.","b":false},{"t":"ויהי כהיום בהחזיקם עליו ויאמר חפץ אני להועץ ולחשוב על הדבר עד שלשה ימים. וכדי לדחותם מעליו אמר כן, ויהי אך יצוא יצא מאת פני ההגמון שם הדבר ללבו על אשר ככה יצא מפיו לשון ספק שהיה צריך שום עצה ומחשבה לכפור באלהים חיים, ויבוא אל ביתו ולא אבה לאכול ולשתות, ונחלה, ויבואו כל קרוביו ואוהביו לנחמו, וימאן להתנחם, כי אמר ארד אל ניבי אבל שאולה, ויבך ויתעצב אל לבו.","b":false},{"t":"ויהי ביום השלישי בהיותו כואב ודואג וישלח ההגמון אחריו. ויאמר, לא אלך! ויוסף עוד הצר שלוח שרים רבים ונכבדים מאלה, וימאן ללכת אליו. ויאמר ההגמון מהרו את אמנון להביאו בעל כרחו, וימהרו ויביאו אותו, ויאמר לו מה זאת אמנון למה לא באת אלי למועד אשר יעדת לי להועץ ולהשיב לי דבר ולעשות את בקשתי. ויען ויאמר אמנון, אני את משפטי אחרוץ! כי הלשון אשר דבר ותכזב לך דינה לחתכה, כי חפץ היה רבנו אמנון לקדש את ה' על אשר דבר ככה.","b":false},{"t":"ויען ההגמון ויאמר, לא, כי הלשון לא אחתוך כי היטב דברה! אלא הרגלים אשר לא באו למועד אשר דברת אלי אקצץ, ואת יתר הגוף אייסר. ויצו הצורר, ויקצצו את פרקי אצבעות ידיו ורגליו, ועל כל פרק ופרק היו שואלין לו התחפוץ עוד אמנון להפך לאמונתינו. ויאמר, לא!! ויהי ככלותם לקצץ, צוה הרשע להשכיב את רבנו אמנון במגן אחד וכל פרקי אצבעותיו בצידו, וישלחהו לביתו. הכי נקרא שמו רבנו אמנון, כי האמין באל חי וסבל על אמונתו יסורין קשין מאהבה, רק על הדבר שיצא מפיו.","b":false},{"t":"אחר הדברים האלו קרב מועד והגיע ראש השנה, ובקש מקרוביו לשאת אותו לבית הכנסת עם כל פרקי אצבעותיו המלוחים ולהשכיבו אצל השליח צבור. ויעשו כן, ויהי כאשר הגיע הש\"צ לומר הקדושה וחיות אשר הנה, אמר לו רבנו אמנון המתן מעט, ואקדש את השם הגדול, ויען בקול רם, ובכן לך תעלה קדושה, כלומר, שקדשתי את שמך על מלכותך ויחודך, ואח\"כ אמר, ונתנה תוקף קדושת היום, ואמר, אמת כי אתה דיין ומוכיח. כדי להצדיק עליו את הדין, שיעלו לפניו אותן פרקי ידיו ורגליו, וכן כל הענין, והזכיר וחותם יד כל אדם בו, ותפקוד נפש כל חי, שכך נגזר עליו בר\"ה. וכשגמר כל הסילוק נסתלק ונעלם מן העולם לעין כל ואיננו, כי לקח אותו אלהים, ועליו נאמר (תהלים לא, כ), מה רב טובך אשר צפנת ליראיך וגו'.","b":false},{"t":"אחר הדברים והאמת אשר הועלה רבנו אמנון ונתבקש בישיבה של מעלה ביום השלישי לטהרתו, נראה במראות הלילה לרבנא קלונימוס בן רבנא משולם בן רבנא קלונימוס בן רבנא משה בן רבנא קלונימוס ולימד לו את הפיוט ההוא ונתנה תוקף קדושת היום, ויצו עליו לשלוח אותו בכל התפוצות הגולה להיות לו עד וזכרון, ויעש הגאון כן, עד כאן המעשה הנורא. צא וראה עד כמה כאב לו לרבינו אמנון על עצם זה שהיה נראה בעיני האנשים כמסתפק. וישמע חכם ויוסיף לקח, וזיע\"א. יבח\"ר].","b":false},{"t":"אלא דלפי זה קשה מסוגיא דברכות (ה, א), שאמרו, לעולם ירגיז אדם יצר הטוב על יצר הרע, אם נצחו מוטב ואם לאו יעסוק בתורה, אם נצחו מוטב ואם לא יקרא קריאת שמע, אם נצחו מוטב, ואם לאו יזכור לו יום המיתה, שנאמר (תהלים ד, ה), אמרו בלבבכם על משכבם ודומו סלה.","b":false},{"t":"ולכאורה זה סותר למה שכתבנו בתחילת דברינו שאין להכנס בשום טענות עם היצר, וצריך למאן בדבריו מיאון חזק ופסקני, ולא להאריך בדברים ולשאת ולתת עמו. ואילו בדברי הגמרא ברכות אנו רואים, כי בתחילה האדם מנסה לראות אם יכול לנצח את יצרו, ואם לא נצחו עדיין, ילמד תורה. ואם לא נצחו גם בזאת, יקרא ק\"ש, ואם גם זה לא הועיל לו, אז ישתמש בנשק החזק ביותר, ויזכור לו את יום המיתה, ושב ורפא לו. ולכאורה נראה, שאדרבה אין להשתמש מיד בכל הכח נגד היצה\"ר, אלא מעט מעט תגרשנו מפניך, וללכת מחיל אל חיל, וממדרגה למדרגה והוא היפך מהנ\"ל.","b":false},{"t":"ובאמת שרבים הקשו איך אמרו חז\"ל ללכת נגד היצה\"ר במהלך ארוך שכזה, והלא יש לחוש ח\"ו שאדהכי והכי יקום עליו היצה\"ר והכהו ויפילנו ארצה, ולמה לא יקדים הוא להכות את יצרו מתחילה מכה רבה, דהיינו שיזכיר לו יום המות, ואז ישב בטח שקט ושאנן.","b":false},{"t":"ויש מקום בראש לחלק בין הדברים, כי מה שנזכר בגמרא ברכות הוא במצב רגיל, ובא האדם שמחפש את הדרך להתחזק בתורה ויראת שמים. ושואל, איך יתחזק? ועל זה באים חז\"ל ואומרים לו, לעולם ירגיז אדם יצר טוב על יצה\"ר, ואם רואה שדרכו צלחה בידו מוטב, ואם לאו, סימן הוא שאינו הולך במסילה הנכונה, וחסר לו ידיעה וגם כח ועוז כדי לעמוד במלחמה הגדולה שהיא מלחמת היצר, ועל כן יעסוק בתורה. כי גדולה תורה שנותנת חיים לעושיה בעוה\"ז ובעוה\"ב (אבות ו, ז וכלה פ\"ח), והיא תתן לו מכחה ויופיה, ויגבר ויהיה לאיש חיל. כי התורה\"ק תעטרהו בגבורה ועוז תפארה, כדי שיוכל לעמוד נגד יצרו וינצחו. ואם גם דרך זו לא הועילה לו ועדיין הוא מרגיש רפיון וחולשה וחושש לגורלו, יקרא ק\"ש, ואם התחזק ועלה על הדרך הנכונה, אשר בה ישכון אור, מוטב. וימשיך בדרכו בהצלחה, ואם לאו, יזכור לו יום המיתה, כי זכרון יום המות שובר את לבו של האדם, ותאוותיו נחלשות, ושב ורפא לו. וזו היא דרך החיים הרגילים, לאדם רגיל שחי את חייו על מי מנוחות, ובדרכו נתקל בעליות ומורדות, ומחפש את הדרך להתייצב ולעלות במעלות, ולהצליח.","b":false},{"t":"אבל אדם שנפל עליו נסיון קשה, ולפתע פתאום מוצא את עצמו, עומד בחזית המלחמה, והסכנה הגיעה עד לשד עצמותיו, אם יתמהמה ויערוך נסיונות, הרי בינתיים סכנתו מרובה מהצלתו, וכאשר אירע ליוסף הצדיק, שנמכר לעבד לעבדים, והדבר קרהו מידי אחיו בני אביו, אשר התאכזרו אליו באופן נורא, והשליכוהו לבור נחשים ועקרבים, ואמרו לשפוך את דמו כמים, ולבסוף מכרוהו לישמעאלים כחפץ אין חפץ בו, והיה נמכר מיד ליד עד שהגיע לידי פוטיפר רב קטוליא, והוא עדיין חובש פצעיו וכאביו, על אבדן בית אביו הקדוש בו מצא אהבה בתענוגים, והיה מסתופף בצילא דמהימנותא, ויונק חלב ודבש, ממעיני הישועה, כי אביו למדו את כל התורה שלמד בבית שם ועבר, ועתה היה למשל ולשנינה, עבד נרצע ונכנע, להני אינשי דלא מעלי, אנשי תאוה ובצע, והוא נאלץ לחיות בתוכם ולראות במו עיניו, מה שלא ראה ולא חש מעולם, וגם לעמוד לפניהם לשרתם, ויחד עם זאת לשמור במאמצים אדירים על שפיות דעתו, וטהרת נפשו, ולשמור על צלם אלהים שבו, ולבלתי השחית את נפשו, ושלא ללמוד ממעשי ארץ מצרים.","b":false},{"t":"ובעודנו נאבק על קיום נפשו, במציאות החדשה שלתוכה נקלע, ותשא אשת אדוניו את עיניה אל יוסף, ותאמר שכבה עמי. וכל כהאי גונא שאדם נקלע בפתע פתאום לסכנה מוחשית כל כך, כי אז אין אומר ואין דברים, שאין הוא יכול לעשות שום נסיון איך ללחום ביצרו, ואסור לו להכנס לשום משא ומתן בדבר, רק לעמוד כגבור חיל, ולהשתמש בכל הכחות האפשריים, ובבת אחת ובכל הכח להדוף את הנסיון הקשה מעליו. וצריך להיות חזק ופסקני ללא שום היסוס ובלא שום רפיון כלל ועיקר, וזהו מה שנאמר 'וימאן' שיש עליו טעם שלשלת, ובצדו טעם פסק. טעם 'שלשלת' להראותינו שנתן יוסף הצדיק את כל כחו כדי להציל את נפשו מרדת שחת, וטעם 'פסק' להראותינו שהיה יוסף הצדיק חד משמעי ונחרץ ביותר נגד יצרו.","b":false},{"t":"זה מה שנראה לענ\"ד לחלק בין המצב הרגיל שבו מתמודד האדם ונאבק על מצבו, לבין מצב מיוחד אליו נקלע האדם בפתע פתאום ובבת אחת, שאז צריך לחתוך את הענין בכל הכח והזריזות ללא רגע של מחשבה.","b":false},{"t":"* * *","b":false},{"t":"האפשרות היחידה לנצח את היצה\"ר היא בכח התורה","b":true},{"t":"והואיל ואתא לידן, אכתוב כאן עוד פירוש אחר שעלה בדעתי בס\"ד זה למעלה משלשים שנה, דהנה צריך להבין את דברי המאמר דמסכת ברכות הנ\"ל, מלבד הקושיא שכבר הקשינו דאיך נתנו עצה לאדם להתגרות ביצרו, והאריכו בדרכי המלחמה, ולא חששו שהאדם יפול ברשת היצר, ובפרט שהוא רואה שיצרו הולך וחזק עליו, עד שאפי' תלמוד תורה לא הצילו, וגם לא ק\"ש, וכנ\"ל.","b":false},{"t":"ובנוסף לזה הקשיתי עוד קושיא עצומה, דהרי חז\"ל אמרו במסכת קדושין (ל, ב וב\"ב טז, א), שהקב\"ה אומר, בראתי יצר הרע בראתי לו תורה תבלין, כלומר שהבורא ישתבח שמו, שהוא ברא את היצר הרע בעולם, ויודע על מה הושתתו אדניו, ומה כחו ומה גבורתו, הוא עצמו ברא גם את התרופה שלו, והיא, התורה הקדושה. כי היצר הרע הוא מאש (ככל המלאכים), ואנו בשר ודם, ואיך נוכל להתגבר עליו, ועל כן נתן לנו הקב\"ה את תורתו, שהיא יותר חזקה מהיצר, כמו שנאמר (ירמיה כג, כט), הלא כה דברי כאש נאום ה', והאש הזאת מבטלת את האש הזרה של היצר הרע, וכאשר נאמר בתורה (במדבר לא, כג), כל אשר יבא באש תעבירו באש וטהר. נמצא שהתרופה היחידה נגד היצה\"ר היא התורה, וכמו שאמרו רבותינו (סוכה נב, ב קדושין ל, ב), תנא דבי רבי ישמעאל, אם פגע בך מנוול זה משכהו לבית המדרש, אם אבן הוא נימוח, אם ברזל הוא מתפוצץ. אם אבן הוא נימוח, דכתיב (ישעיה נה, א), הוי כל צמא לכו למים, וכתיב (איוב יד, יט), אבנים שחקו מים. אם ברזל הוא מתפוצץ, דכתיב (ירמיה כג, כט), הלא כה דברי כאש נאם ה' וכפטיש יפוצץ סלע. וא\"כ נמצינו למדים שהתרופה \"היחידה\" נגד היצה\"ר הוא לימוד התורה הקדושה, ואין תרופה אחרת נגדו. וכיצד זה שבמסכת ברכות מנו עוד תרופות ולא זו בלבד, אלא שתלמוד תורה הוא הקטן שבתרופות, ולמעלה ממנו קריאת שמע, ולמעלה מהם זכרון יום המיתה, אתמהה.","b":false},{"t":"ועוד קשה הלשון של הגמרא במסכת ברכות, שאמרו יעסוק בתורה אם נצחו מוטב ואם לאו וכו'. ואטו יש ספק בדבר, אם ינצח אם לא ינצח, והרי הקב\"ה שברא את היצר הרע, הוא הוא שאומר לנו, בראתי לו תורה תבלין, ואיך יעלה על הדעת, לומר, אם נצחו מוטב \"ואם לאו\" יעשה דברים אחרים וכי יש צד ספק בדבר שלא יצליח לנצח ע\"י התורה. היתכן כדבר הזה, והרי הוא אמר ויהי, הוא ציוה ויעמוד. ומי איכא ספיקא במילי דשמיא חלילה וחס.","b":false},{"t":"ומכח כל הקושיות הללו אמרתי לבאר בעזר האל וישועתו, דבאמת אין דבר שיכול להכניע את האש של היצר הרע אלא התורה לבדה, וזה אומרם, \"בראתי לו תורה תבלין\", ואין עוד תרופות אחרות כלל ועיקר, אלא דאין התורה נקנית לאדם אא\"כ המית עצמו עליה (ברכות סג, ב ושבת פג, ב). וגם אין התורה נותנת את כחה אלא א\"כ לומדה בעמל ויגיעה כראוי. וגם שצריך להיות עוסק בה לשם הי\"ת ולא לשם מטרה אחרת כדי להיות זוכה לכל המעלות (המבוארות במאמר רבי מאיר אבות ו, א ופ\"ח דכלה), אבל אם מתעסק בה כמו שלומד אחת מן החכמות, אינה נותנת לו את כחה ואת סגולותיה כמו שאמרו (יומא עב, ב ותענית ז, א), זכה נעשית לו סם חיים לא זכה נעשית לו סם מיתה ח\"ו.","b":false},{"t":"כי אמנם נכון הדבר שהקב\"ה ברא לו ליצה\"ר תורה תבלין כנגדו, אך נתן את הבחירה ביד האדם אם להשתמש בתורה או לא להשתמש בה. ואם האדם החליט להשתמש בתורה, הרי יש הוראות וכללים כיצד לעסוק בה כדי שיזכה לקבל ממנה עוז ותעצומות.","b":false},{"t":"וכבר אמרו חז\"ל (ירושלמי פאה א, א שביעית א, ה שבת א, ד סוכה ד, א כתובות ח, יא), על הפסוק (דברים לב, מז), כי לא דבר רֵק הוא מכם. אם ריק, הוא מכם, לפי שאינכם יגעים בו. כי דבר ה' איננו ריק ח\"ו, ואם מרגיש האדם בריקנות, ידע לו שהריקנות באה ממנו.","b":false},{"t":"משל לאדם שקנה והתקין בביתו מכשיר \"מזגן\", אשר יעודו לחמם את הבית בחורף ולקררו בימי הקיץ הלוהטים. ובימי הקיץ המזגן היה מוציא הרבה קור ומקרר את הבית, אמנם אח\"כ כלה קיץ עבר קציר ובאו ימי החורף הקרים, וה\"מזגן\" ממשיך ומקרר, עד שהבית נהיה קר כקרח. הלך לו האדם הזה ובא בתרעומת גדולה אל מי שמכר לו את \"המזגן\", באומרו אליו למה רימיתני, ומכרת לי מכשיר שאינו מחמם כלל ועיקר, ובני ביתי סובלים מקור נורא. תיכף הלך המוכר לבית הקונה, ובדק את המכשיר, וראה שהוא פועל היטב, אלא שהכפתור שבו מקררים את הבית דולק, ואילו הכפתור שבו לוחצים כדי לחמם כבוי. ויאמר לו פתי, וכי לא תדע שעליך ללחוץ בלחיצת יד לקרר או לחמם את ביתך, ומה לך כי תלין עלי, ע\"כ המשל.","b":false},{"t":"והנמשל הוא התורה הקדושה, שאם ח\"ו לא יפעל בלימוד התורה כפי שהתורה דורשת ממנו, או שלומדה לחכמה בלבד והריהו נבל ברשות התורה, לא זו בלבד שלא יפיק ממנה תועלת, אלא שח\"ו תיהפך לו לסם המות, כאומרם (שבת פח, ב), דברי תורה יש בם להמית ולהחיות, היינו דאמר רבא למיימינין בה סמא דחיי, למשמאילים בה סמא דמותא ח\"ו.","b":false},{"t":"ועפ\"י זה יתפרש הענין אל נכון, דאם האדם רואה שיצרו מתגבר עליו יעסוק בתורה, והיא מגנא ומצלא, היינו שמגינה מן הפורענות, ומצילה מן החטא. ואם נצח ליצרו מוטב, כלומר, שהוא דבר נפלא וסימן מובהק שהוא עוסק בתורה כראוי, ועל כן גם התורה הקדושה נתנה לו מכחה, וזה פריה הטוב שעל ידה הוא מתגבר על יצרו ונוצחו, וגבר ישראל. ואם לאו, היינו, שלומד ולא גובר על יצרו, אות וסימן הוא שאינו לומד כראוי לו, ולא מכוין את לבו לשמים, רק עוסק בה כמו שלומד אחת מן החכמות של העולם ממדעי בני האדם, ועל כן לא הועילה לו. ומה יעשה אותו האיש? יקרא ק\"ש, כי בקריאת שמע האדם מקבל עליו עול מלכות שמים ועול מצוות, ועל ידי זה יתעורר לבו לאהבה את ה', ויתן את דעתו ללמוד תורה לשמה לכבוד הי\"ת, ויזכה לאור שבה, שעל ידי האור הזה הוא מכניע את היצר הרע (ראה הקדמה לאיכ\"ר פסקא ב'). ועל זה אמרו, אם נצחו מוטב, סימן שעתה עלה לדרך האמת וניצח. ואם לאו יזכור לו יום המיתה וכו', כלומר, אם גם ק\"ש לא הועילה לו לעורר את לבו ללמוד לשמו יתברך, סימן שלבו בל עמו, ורק שפתיו נעות, אבל הלב תפוס בתאוות העולם, ודעתו נתונה לענינים אחרים, וגם התורה, וגם הקריאת שמע, לא נגעו אל לבו פנימה, והם אצלו כמו דבר חיצוני, הרי בודאי לא יוכל לנצח את יצרו במצב זה, וע\"כ העצה היעוצה לו במצב הזה, היא, לזכור את יום המיתה, שבזה נשבר לבו בקרבו ומתמעטים תאוותיו, ונותן לבו ללמוד תורת אלהים חיים בקדושה וטהרה, מתוך הכנעת הלב, ואז התורה תתן בו את כחה וסופו שיהא מנצח את יצרו, ע\"י התורה, אשר ברא קודשא בריך הוא כנגד היצר הרע. וא\"כ אין כאן אלא תבלין אחד ויחיד, כאומרם, \"בראתי לו תורה תבלין\", וק\"ש ויום המיתה שהזכירו בזה הוא, התעוררות הלב, כדי ללמוד תורה באמת כראוי וכיאות, ולא שיש כאן עוד תרופות אחרות.","b":false},{"t":"ובזה מובן אומרם, אם נצחו מוטב \"ואם לאו\" וכו', דאין ספק בכח התורה ח\"ו, אלא שאין מדובר על הנלמד, כלומר על התורה הקדושה, אלא על הלומד, שאם הוא לומד כמו שנדרש ממנו ללמוד, כדי להפיק מן התורה את הכח הרוחני נגד היצר הרע מוטב. ואם לאו המציאו לו כמה עזרים שיגיע ללמוד תורה כהוגן.","b":false},{"t":"ולפי זה יובן ג\"כ, דאין כאן נסיונות לחפש דרך קלה ואח\"כ יותר חמורה, אלא באמת הדרך הנכונה היא להכות את היצה\"ר בכל הכח, ולא ברפיון ובחלישות, אלא יתן מיד את הכח הגדול והחזק, וע\"כ אמרו \"יעסוק בתורה\", שהיא התבלין נגד היצה\"ר, אלא דעם כל זה אפשר שלא תועיל לו, אם לא ישתמש בה כפי הראוי לו, ולכן נתנו חז\"ל עצות גם לזה, שיוכל להגיע לסגולותיה של התורה.","b":false},{"t":"אבל אם יתחיל בזכרון יום המיתה, לא יועיל לו מאומה, דבזה לבד אין כח נגד היצה\"ר, ואדרבה הרשעים אומרים (ראה ישעיה כב, ג), אכל בשר ושתות יין אכול ושתו כי מחר נמות. וגם בימינו הריקים אומרים, תיהנה מן העולם הזה כי חיים רק פעם אחת, וכיו\"ב מדברי ההבל, אשר זה עצמו יכול להרחיקו עוד ממטרתו מרחק גדול.","b":false},{"t":"אבל מי שנאבק ביצרו, ולוקח את התרופה הנכונה, שהיא לימוד התורה, אלא שהתברר לו שעדיין אינו יודע איך לומדים תורה לשמה, ומה הם התנאים הנדרשים להפעלת הכח הגדול של התורה, ולא נתייאש אלא המשיך וקרא ק\"ש וקיבל עליו עול מלכות שמים, אלא שגם זה עדיין לא השיב את לבו לכיוון הנכון, לאיש אשר אלה לו, אם יזכור יום המיתה, בודאי יהיה לו לתועלת, לשבר את כח התאוות הרעות, ולמעט מן הגשמיות, ואז תהיה דעתו על התורה, וילמד אותה בעמל וביגיעה ובכונה הרצויה, והיא תתן לו את כחה, וסופו להתחזק ולהיות לאיש חיל גבור ומושל ביראת אלהים, אכי\"ר.","b":false},{"t":"(בעהית\"ש. אור ליום שלישי שמנה ימים לאדר התשס\"ו - בדרך מנ\"י לג'נבה)","b":false}]},{"id":"20","t":"\"ויהי\" לשון שמחה או לשון צער","p":[{"t":"וַיְהִי ה' אֶת יוֹסֵף וַיְהִי אִישׁ מַצְלִיחַ וַיְהִי בְּבֵית אֲדֹנָיו הַמִּצְרִי: (לט, ב)","b":true},{"t":"הנה מצינו שנאמר בפסוק הזה ג' פעמים לשון \"ויהי\", והנה בגמרא מגילה (י, ב), אמר רבי לוי ואיתימא רבי יונתן, דבר זה מסורת בידינו מאנשי כנסת הגדולה, כל מקום שנאמר ויהי אינו אלא לשון צער, ובגמרא הקשו שמצינו ויהי שהוא לשון שמחה, ולכן מייתי שם דברי רב אשי שאמר, כי לשון ויהי פעמים שהוא לשון צער, ופעמים שהוא לשון שמחה, אבל \"ויהי בימי\" הוא לשון צער. ע\"ש.","b":false},{"t":"ברם נראה דלאו מילתא פסיקתא היא, דבמדרש (ב\"ר מג, ג), ס\"ל דכל לשון \"והיה\" לשון שמחה הוא, ולשון \"ויהי\" גם כשהוא לשון \"ויהי\" בלחוד ולא \"ויהי בימי\", אעפי\"כ, לשון צער הוא. והנה במדרש הזכיר את הפסוק שלנו, וז\"ל, והכתיב ויהי ה' את יוסף. ונמצינו למדים עוד מדברי המדרש דכל שאין השמחה שלימה לגמרי, שפיר קרי ביה \"ויהי\" שהוא לשון צער (וע\"ע בפסיקתא רבתי פרשה ה' ושם פרשה ז' ובילקו\"ש ירמיהו רמז שכז).","b":false},{"t":"אלא דעל כל פנים קשה, דהא במה שהיה ה' עם יוסף השמחה שלימה, ומה חסרון יש בשמחה זו.","b":false},{"t":"ומצאתי במאור ושמש, שכתב לפרש את זה בהקדים דברי רבותינו (ב\"ר פו, ב וראה ילקו\"ש בראשית רמז קמה), ששכינה ירדה עם יוסף למצרים, וכתיב (ישעיה סג, ט), בכל צרתם לו צר, והיה צער גדול ליוסף, הן מצד שגלה מעל שלחן אביו ויושב אצל איש מצרי וכו', והן מצד גלות השכינה אשר ירדה וגלתה עמו למצרים, והיה כואב את כאב השכינה.","b":false},{"t":"וזהו ויהי ה' את יוסף, שירד עמו מצרימה כדי להשתתף עמו בצערו על פרידתו מאביו, ויהי בבית אדוניו המצרי שהשכינה עמו שם, ומה שהמשיך הכתוב ואמר, ויהי איש מצליח, פירש הרב ז\"ל דאעפ\"י שהיה לו צער הרמוז בתיבת \"ויהי\", מ\"מ היה משכיח את צערו ע\"י שמחתו והיה מצליח, דבמדרש (ב\"ר פו, ד), אמרו איש מצליח, גבר קפוז, ופירש במתנות כהונה (שם), שהוא צוהל ושמח, וטוב לב משתה תמיד.","b":false},{"t":"כי יוסף הצדיק היה עושה עצות בנפשו שלא יפול בעצבות, שזו היא המניעה הגדולה מכל המניעות שיש בעבודת ה', בהיות האדם סר וזעף כידוע מדברי קדושים עליונים, ומקרא מלא דיבר הכתוב (דברים כח, מז), תחת אשר לא עבדת את ה' אלהיך בשמחה. ויוסף הצדיק היה מסיח את דעתו מדאגתו והיה בשמחה תמיד, כדי שיוכל לעבוד את השי\"ת בשמחה ובטוב לבב, ואע\"פ שהיה חסר מכל. והיה אוכל ושותה ומסלסל בשערו, כמ\"ש חז\"ל (ראה תנחומא וישב פ\"ח).","b":false},{"t":"וכן שמעתי לפרש את דברי המשנה (תענית כו, ב), משנכנס אב ממעטין בשמחה, פירוש ממעטין את הצער והדאגות בשמחה, כי ע\"י השמחה ממעטים גלות השכינה (ואולי זה מקור למנהג שנוהגים מזמן ר\"ח אב להרבות בסיומי מסכת), וזה מה שהיה עושה יוסף הצדיק בהיותו בגלות בין העכו\"ם שהיה מנסה לשמח את עצמו, ע\"ש בדבריו הנעימים.","b":false},{"t":"ואפשר לומר, דלא אמרו שויהי הוא לשון צער, אלא כגון ויהי בימי אחשורוש, ויהי בימי שפוט השופטים וכיו\"ב, אבל כשאומר עובדא עכשוית בלשון הוה נמשך, לשון ויהי אינו מורה בהכרח על צער. ואולם בענין יוסף הצדיק מצינו עוד לשונות ויהי, ויהי מאז הפקיד וגו' (בראשית לט, ה). ויהי יוסף יפה תאר ויפה מראה (שם שם, ו). ויהי אחר הדברים האלה ותשא אשת אדוניו וגו' (שם שם, ז), אח\"כ נאמר, ויהי כדברה אל יוסף יום יום וגו' (שם שם, י). ועוד נאמר, ויהי כהיום הזה ויבא הביתה לעשות מלאכתו וגו' (שם שם, יא). ושם נאמר ויהי כראותה (שם פסוק יג). ועוד נאמר, ויהי כשמעו כי הרימותי קולי וגו' (שם שם, טו). ועוד נאמר, ויהי כהרימי קולי וגו' (שם שם, יח). ועוד נאמר, ויהי כשמוע אדוניו את דברי אשתו וגו' (שם שם, יט). ועוד נאמר, ויהי ה' את יוסף ויט אליו חסד (שם שם, כא). ועוד נאמר, ויהי אחר הדברים האלה חטאו משקה מלך מצרים (שם מ, א). הרי ט\"ו פעמים לשון ויהי באותו הענין. ויש להתבונן בלשונות אלו מתי הוא לשון צרה ומתי הוא לשון ישועה.","b":false},{"t":"ועלה בדעתי לומר בעזר האל וישועתו, דמילת \"ויהי\" אינו מורה על לשון צער אלא כשהוא מיותר, אבל כשנצרך לעצמו אינו מורה בהכרח על צער, כמו מה שנאמר ויהי ה' את יוסף, שיש כאן שם הוי\"ה שהוא רחמים, א\"כ אינו מורה על צער, אבל ויהי בימי אחשורוש, מורה בודאי על צער, כי הלשון מיותר, ולא היה לו לכתוב ויהי בימי אחשורוש, ויכל לומר בשנת שלש למלך אחשורוש וכו'. ולכן יתור הלשון מורה על צער. ומ\"מ אף אצלינו כיון שנזכר בענין יוסף ט\"ו פעמים לשון \"ויהי\" בודאי שהוא בא להורות על צערו של יוסף, אשר בא לו שבר על שבר, כי נלקח מבית אביו, וגדל הכאב כי נמכר נמכר ע\"י אחיו, ועוד, נזדמן לבית פוטיפר הרשע רב קטוליא, ועוד, באה לו צרת אשת פוטיפר. וא\"כ גם מה שנאמר ויהי יוסף יפה תואר וגו' היה לו לצרה, כי עי\"ז נתגרה בו הדוב ונתנה אשת פוטיפר את עיניה בו. גם מה שנאמר ויהי ה' את יוסף, אע\"פ שהוא לטובתו, מ\"מ יש בזה צער, כי כיון שמצא יוסף חן בעיני שר בית הסוהר והפיק רצון משר המשקים, שם מבטחו ברהבים, וזה היה גורם לו להיות עוד שנתיים בבית האסורים. ובשאר המקומות שנאמר ויהי, הצער בהם גלוי ומובן לכל.","b":false},{"t":"[א\"ה - בעצם הענין, שמעתי בשם הגאון רש\"ר הירש ז\"ל, שפירש למה לשון \"והיה\" הוא לשון שמחה, ואילו לשון \"ויהי\" הוא לשון צער. כי הנה מילת \"היה\" הוראתה על העבר, וכשהאדם מוסיף לה אות וא\"ו \"והיה\" היא נהפכת ללשון עתיד כמו והיה אם שמוע תשמעו (דברים יא, יג). הרי זה מורה על הזמן החולף שהיה טוב, והאדם חפץ למשוך את טובת הזמן ההוא אל העתיד, ולכן כשנכתב בלשון זה הרי הוא מורה על שמחה. ואילו לשון \"ויהי\" הוא לשון צער, כי הנה לשון \"יהי\" הוא לשון עתיד, כמו יהי אור (בראשית א, ג), והנה כשנוספה לו אות וא\"ו ונהיה \"ויהי\" הרי הוא משנה את משמעותו ונהפך ללשון עבר, והיינו, שהלשון מורה כי האדם רוצה לסלק את הזמן הזה, וכביכול רוצה להוליכו אל העבר, ולכן הוראתו צער. ודפח\"ח. יבח\"ר].","b":false}]},{"id":"20","t":"ירידת יוסף למצרים","p":[{"t":"וְיוֹסֵף הוּרַד מִצְרָיְמָה וַיִּקְנֵהוּ פּוֹטִיפַר וגו': (לט, א)","b":true},{"t":"וכתב רש\"י ז\"ל, ויוסף הורד, חוזר לענין ראשון, אלא שהפסיק בו כדי לסמוך ירידתו של יהודה למכירתו של יוסף, לומר לך, שבשבילו הורידוהו מגדולתו וכו'. ע\"ש.","b":false},{"t":"הנה מלבד הקשר שבין שני המשיחים משיח בן דוד ומשיח בן יוסף, אשר הם סמוכים לעד לעולם (כמבואר בזוה\"ק בהרבה מקומות אשר נצרכים יחד זה לזה ושלובים זה עם זה. וראה שם ח\"ב קכ, א וח\"ג סח, א ושם רמג, א ושם רמו, ב ושם רעח, ב ובתקו\"ז כא, א ושם סז, א ושם קמד, א ושם קמז, ב), וכן רואים כאן שירידתו של זה גרמה את ירידתו של זה, ומזה גופא נלמד שבעלייתו של האחד תהיה גם עליית השני בב\"א.","b":false},{"t":"ויש עוד להתבונן בדרכי ה' ונפלאותיו עילת העילות וסיבת הסבות. כי ירידת יוסף היתה בה מעלה, שעל ידה זרעו של יוסף הושתת במצרים, וגם ע\"י ירידתו באו יעקב ובניו בכבוד מצרימה, והעלו משם ניצוצות הקדושה. וכמו כן, ירידתו של יהודה היא שהביאה לעולם את פרץ וזרח, שמהם יצאה מלכות בית דוד.","b":false},{"t":"וע\"כ גם אם באה ירידה לאדם, ילמד מאבותינו, ויבטח בהי\"ת ויאמין בו שהכל לטובה, ואז יתאמץ לבו ויתעודד.","b":false}]},{"id":"20","t":"לקחי מוסר במעשה יהודה ותמר","p":[{"t":"הִוא מוּצֵאת וְהִיא שָׁלְחָה אֶל חָמִיהָ לֵאמֹר לְאִישׁ אֲשֶׁר אֵלֶּה לּוֹ אָנֹכִי הָרָה וַתֹּאמֶר הַכֶּר נָא לְמִי הַחֹתֶמֶת וְהַפְּתִילִים וְהַמַּטֶּה הָאֵלֶּה, וַיַּכֵּר יְהוּדָה וַיֹּאמֶר צָדְקָה מִמֶּנִּי כִּי עַל כֵּן לֹא נְתַתִּיהָ לְשֵׁלָה בְנִי וְלֹא יָסַף עוֹד לְדַעְתָּהּ: (לח, כה-כו)","b":true},{"t":"אמרו רבותינו (סוטה י, ב), והובאו דבריהם בפירוש רש\"י ז\"ל היא מוצאת להשרף. והיא שלחה אל חמיה, לא רצתה להלבין פניו ולומר ממך אני מעוברת, אלא לאיש אשר אלה לו. אמרה, אם יודה מעצמו, יודה, ואם לאו ישרפוני ואל אלבין פניו. מכאן אמרו נוח לאדם שיפילוהו לכבשן האש, ואל ילבין פני חברו ברבים.","b":false},{"t":"ועיין בתרגום יונתן בן עוזיאל (בראשית לח, כה), שכתב דלא מצאה תמר את שלשת המשכונות, ותלתה עיניה לשמי מרום וביקשה רחמים, שהי\"ת יענה לה בעת צרתה, ויאיר את עיניה למצוא את שלשת העדים, והבטיחה שממעיה יצאו שלשה קדושים שיקדשו את שמו יתברך וירדו לכבשן של אש בבקעת דורא, ואז הקב\"ה רמז למיכאל והאיר עיניה ומצאתם, והניחה אותם לרגלי הדיינים, ואמרה לאיש אשר אלה לו, ממנו אני מעוברת. ואפילו אם אשרף לא אפרסם, ואני מתפללת לה' שישים בלבו שיכירם ויצילני, וכשראם יהודה הכירם, ואמר בלבו טוב לי להתבייש בעוה\"ז שהוא עובר, ולא אבעת בפני אבותי הצדיקים בעוה\"ב, טוב לי להשרף בעוה\"ז באש כבויה של העוה\"ז, ולא באש אוכלת אש, דמיכלא קבֵיל מיכלא הוא (מדה כנגד מדה), לפי שאמרתי ליעקב אבא הכר נא הכתונת בנך היא, ע\"כ אני צריך לשמוע בב\"ד למי החותמת והפתילים והמטה האלה. וע\"ש בתרגום ירושלמי שג\"כ כתב מעין זה ובאמת שכדמות דברים אלה מבואר נמי במסכת סוטה (י, ב), ושם איתא, שאחר שמצאה את סימניה בא סמאל וריחקן ובא גבריאל וקירבן וכו', יעו\"ש כל הענין.","b":false},{"t":"עוד כתב התרגום (שם), על הפסוק ויכר יהודה ויאמר צדקה ממני, שיצאה בת קול מן השמים ואמרה, מלפני היה הדבר הזה, וניצלו שניהם מן הדין, (תמר ניצלה מהאש, ויהודה ניצל מדינה של גהינם). ע\"כ.","b":false},{"t":"ובאמת כן כתב רש\"י ז\"ל ד\"ה ממני, וז\"ל, ורבותינו ז\"ל (סוטה י, ב), דרשו, שיצאה בת קול ואמרה, ממני ומאתי יצאו הדברים לפי שהיתה צנועה בבית חמיה, גזרתי שיצאו ממנה מלכים, ושבט יהודה גזרתי להעמיד מלכים בישראל. עכ\"ל.","b":false},{"t":"ומכל זה לומדים כמה דברים נפלאים. תחילה, חומרת עון מלבין פני חברו ברבים שהוא כל כך חמור, עד שהיתה מוכנה תמר למות בשבילו ולאבד עמה עוד ב' נפשות שהיתה מעוברת בהם, ובלבד שלא להלבין את פני יהודה ברבים.","b":false},{"t":"צא וראה דברות אדונינו החסיד רבינו יונה (שערי תשובה שער ג' אות קלט), שכ' וז\"ל, והנה אבק הרציחה, הלבנת פנים, כי פניו יחורו ונס מראה האודם, ודומה אל הרציחה. וכן אמרו רבותינו ז\"ל (בבא מציעא נח, ב). והשנית, כי צער ההלבנה מר ממות, על כן אמרו רבותינו ז\"ל (בבא מציעא נט, א), לעולם יפיל אדם עצמו לכבשן האש ואל ילבין פני חבירו ברבים. ולא אמרו כן בשאר עבירות חמורות, אכן דימו אבק הרציחה אל הרציחה, וכמו שאמרו (סנהדרין עד, א), כי יהרג ולא ירצח. ודומה לזה אמרו, שיפיל עצמו לכבשן האש ולא ילבין פני חבירו ברבים. ולמדו זה מענין תמר, שנאמר, היא מוצאת והיא שלחה אל חמיה וגו', הנה כי אף על פי שהוציאוה לישרף, לא גלתה כי היתה הרה מיהודה, שלא להלבין פניו, ועוד הוסיף שם דברים בחומרת המלבין פני חברו ברבים.","b":false},{"t":"וכן פירש הקדוש מהר\"ם אלשיך ז\"ל, על הפסוק (בראשית ט, ו), שופך דם האדם באדם דמו ישפך. דחז\"ל אמרו (סנהדרין נז, ב), זה ההורג עוברים במעי אמם, ולמדו כן ממה שנאמר \"דם האדם באדם\". והוא ז\"ל פירש פסוק זה על המלבין פני חברו ברבים דאזיל סומקא ואתי חיורא, כי בשעה שמביישו הדם עולה לראשו ופניו מאדימים, ואח\"כ יורד הדם אל הגוף ופניו מלבינים, ועל כן נקרא מלבין פני חברו, וזהו שופך דם האדם, אבל לא בחוץ אלא תוך גופו של אדם, וזהו \"שופך דם האדם\", והיכן שפיכות הדם הזאת, \"באדם\"! הי\"ת יצילנו מזה (וראה מה שנתבאר בפרשת נח מאמר יב).","b":false},{"t":"עוד למדנו בזה, גודל מעלת ההודאה בחטא ובכשלון, שהנה יהודה על אף הבושה הנוראה שהיתה לו לעיני כל העולם, בעת שכינס ב\"ד לדון את תמר בשריפה, והיא הציגה את מטהו פתילו וחותמו, ובאותה שעה היה במאבק אדיר בינו לבין עצמו, כי אע\"פ שלא היה ממית את תמר מ\"מ לא היה מוכרח לגלות כי ממנו היא הרה, והיה יכול לזכותה בדין, ולומר כי נאנסה ונתעברה, אבל לא היה צריך לגלות שזה בא ממנו, כי בזה יבא לו ולבית אביו בזיון נורא. אך יהודה לא שם לב לזאת, וכיון שבתחילה חשד בתמר ורצה לדון אותה כזונה, קם ואמר כי אין בה אפילו חששא דחששא ולו הקל ביותר, והיא כשרה וצדקת שבנשים, אשר כל מטרתה ותאותה הוא להעמיד קרן אורה בבית ישראל. ואחר זה נתעצם יהודה ביותר בגבורת הנפש, והוציא לעיני הכל את צדקתה של תמר. ואז נתלבשה בו רוח השכינה, וזכה למלכות, ונתקיים בו יהודה אתה יודוך אחיך (בראשית מט, ח), היינו כשם שלא שינית משמך יהודה, והודית על האמת, לכך לעולם יודוך אחיך ותזכה למלכות ולשאר ברכות מופלאות.","b":false},{"t":"ועוד למדנו על כחותיה ותעצומות נפשה של תמר, שאפילו בראותה שעומדים לשורפה לא נתיאשה מבעל הרחמים, וביקשה ממנו שיתן בלבו של יהודה לחון אותה, והראתה בזה לדורות עולם על גודל האמונה שבלבה. כי תחת שהיה לה לכעוס על יהודה ולגדפו, ולביישו, שתקה ובעינים דומעות ולב מלא תחינה דלו עיניה למרום ואמרה רבש\"ע, דלו עיני למרום אדני עשקה לי ערבני ערוב אמתך לטובה. ומהתנהגות מופלאה זו של אמונה ובטחון מופלא בהי\"ת השפיעה לזרעה עד עולם. כמו שמצינו בדוד שיצא מחלציה, ובעת ברחו מפני אבשלום בנו היה מהלך עיף בדרך, גולה ומטולטל, והנה שמעי בן גרא יוצא לקראתו ומקללו בקללות נמרצות ונוראות (כמבואר בשבת קה, א), ולא זו בלבד אלא שהיה הולך אחריו וסוקלו באבנים, ומלוי דוד המה ראו כן תמהו, וחרה אפם עד מאד עד אשר אבישי בן צרויה אמר למלך תנה לי ואסירה את ראשו מעליו, ודוד בצדקתו התרעם על אבישי, ואמר לו הנח לו כי ה' אמר לו קלל, כמבואר כל זה בספר שמואל ב' (פרק טז). וכל זה בא לו מורשה מתמר שהניחה הכל ביד הי\"ת, ומי שהוא בעל אמונה גדולה בהי\"ת אינו כועס מעולם על שום נברא, כי הוא יודע שהכל בא מעילת העילות וסיבת כל הסיבות, ורק אליו מגמתו. ויה\"ר שנדבק בדרכי אבותינו הקדושים לילך בדרכם ואורחותם, אורח חיים למעלה למשכיל.","b":false}]},{"id":"20","t":"נפלאים דרכי ה' - התבוננות במעשה יהודה ותמר שממנו בא מלך המשיח","p":[{"t":"וַיֹּאמֶר יְהוּדָה לְתָמָר כַּלָּתוֹ שְׁבִי אַלְמָנָה בֵית אָבִיךְ עַד יִגְדַּל שֵׁלָה בְנִי כִּי אָמַר פֶּן יָמוּת גַּם הוּא כְּאֶחָיו וַתֵּלֶךְ תָּמָר וַתֵּשֶׁב בֵּית אָבִיהָ, וַיִּרְבּוּ הַיָּמִים וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה וַיִּנָּחֶם יְהוּדָה וַיַּעַל עַל גֹּזֲזֵי צֹאנוֹ הוּא וְחִירָה רֵעֵהוּ הָעֲדֻלָּמִי תִּמְנָתָה, וַיֻּגַּד לְתָמָר לֵאמֹר הִנֵּה חָמִיךְ עֹלֶה תִמְנָתָה לָגֹז צֹאנוֹ, וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וַתְּכַס בַּצָּעִיף וַתִּתְעַלָּף וַתֵּשֶׁב בְּפֶתַח עֵינַיִם אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִוא לֹא נִתְּנָה לוֹ לְאִשָּׁה, וַיִּרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה כִּי כִסְּתָה פָּנֶיהָ, וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ וַיֹּאמֶר הָבָה נָּא אָבוֹא אֵלַיִךְ כִּי לֹא יָדַע כִּי כַלָּתוֹ הִוא וַתֹּאמֶר מַה תִּתֶּן לִי כִּי תָבוֹא אֵלָי, וַיֹּאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךָ, וַיֹּאמֶר מָה הָעֵרָבוֹן אֲשֶׁר אֶתֶּן לָךְ וַתֹּאמֶר חֹתָמְךָ וּפְתִילֶךָ וּמַטְּךָ אֲשֶׁר בְּיָדֶךָ וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ, וַתָּקָם וַתֵּלֶךְ וַתָּסַר צְעִיפָהּ מֵעָלֶיהָ וַתִּלְבַּשׁ בִּגְדֵי אַלְמְנוּתָהּ, וַיִּשְׁלַח יְהוּדָה אֶת גְּדִי הָעִזִּים בְּיַד רֵעֵהוּ הָעֲדֻלָּמִי לָקַחַת הָעֵרָבוֹן מִיַּד הָאִשָּׁה וְלֹא מְצָאָהּ, וַיִּשְׁאַל אֶת אַנְשֵׁי מְקֹמָהּ לֵאמֹר אַיֵּה הַקְּדֵשָׁה הִוא בָעֵינַיִם עַל הַדָּרֶךְ וַיֹּאמְרוּ לֹא הָיְתָה בָזֶה קְדֵשָׁה, וַיָּשָׁב אֶל יְהוּדָה וַיֹּאמֶר לֹא מְצָאתִיהָ וְגַם אַנְשֵׁי הַמָּקוֹם אָמְרוּ לֹא הָיְתָה בָזֶה קְדֵשָׁה, וַיֹּאמֶר יְהוּדָה תִּקַּח לָהּ פֶּן נִהְיֶה לָבוּז הִנֵּה שָׁלַחְתִּי הַגְּדִי הַזֶּה וְאַתָּה לֹא מְצָאתָהּ וגו' וַיְהִי בְּעֵת לִדְתָּהּ וְהִנֵּה תְאוֹמִים בְּבִטְנָהּ, וַיְהִי בְלִדְתָּהּ וַיִּתֶּן יָד וַתִּקַּח הַמְיַלֶּדֶת וַתִּקְשֹׁר עַל יָדוֹ שָׁנִי לֵאמֹר זֶה יָצָא רִאשֹׁנָה, וַיְהִי כְּמֵשִׁיב יָדוֹ וְהִנֵּה יָצָא אָחִיו וַתֹּאמֶר מַה פָּרַצְתָּ עָלֶיךָ פָּרֶץ וַיִּקְרָא שְׁמוֹ פָּרֶץ, וְאַחַר יָצָא אָחִיו אֲשֶׁר עַל יָדוֹ הַשָּׁנִי וַיִּקְרָא שְׁמוֹ זָרַח: (לח, יא-ל)","b":true},{"t":"פרשת יהודה ותמר מעוררת תהיות, ובפרט כשמדובר בלידת פרץ בן יהודה שממנו תוצאות חיים זרע מלכות בית דוד עד משיח צדקינו, הזאת נעמ'י, האם זו הדרך הישרה שנבררה ללידת נשמתו של רוח אפינו משיח ה', אם זאת היא ההכנה הראויה לדבר כזה גדול ונורא.","b":false},{"t":"אולם זהו פרי ההסתר הגדול בו נתון עולמנו זה, שהחושך מכסה ארץ וערפל לאומים. בהאי עלמא דשיקרא, שבו ניתנה רשות לכח הרע לעמוד בגאוה ובוז, כמתגבר כלפי הקדושה אבן הראשה, וכמתלהלה להתמודד נגד רצון השם ברוך הוא, כי מאת ה' היתה זאת, לתת כח לרע להתרועע, ואסתירא בלגינא קיש קיש קריא (ראה ב\"מ פה, ב).","b":false},{"t":"ואמנם אין צור כאלהינו (ש\"א ב, ב), אין כמוהו צייר מופלא (ברכות י, א ומגילה יד, א), עד שנראה החלום כמציאות, ונדמה הרע כגבור בגבורתו, והיא נפלאת בעינינו. אך יוצר העולם ומנהיגו עמד וימודד ארץ, והתוה את נתיביה וקבע אופני מהלכיה, וברא בעולמו מלאכים אופנים ושרפים וחיות הקדש, גם יצר אדם בחכמה, וברא בו טוב ורע, זה לעומת זה עשה אלהים, וכחות אדירים נטע בקרבו, וסביבתו כלהט החרב המתהפכת, ומראותיה מגוונים, כלים מכלים שונים, יש פנים מאירים, כזהר הרקיע מזהירים, וזה מוכן למחפשים והמבקשים את פני האדון ה', ורוצים את קצות דרכיו להשיג וללכת במסילה העולה, עדי הדום רגליו, הן הם פעליו.","b":false},{"t":"ויש פנים משחירות, אשר מטילות אימה וקדרות, בקולות ובגבורות, ובבא ענין של קדושה, לטהר את עולמנו ולקדשו בקדושה עליונה, מאת שוכן מעונה, הם מופיעים כקוצים הסובבים את השושנה, ומאיימים לדקור בלבה ולהמיתה, ביודעם שאין להם תקומה בהתחזקות הקדושה, ואין כחם כח עצמי וחיובי, אלא כל חיותם היא מהשלילה, מחלישות כח התורה ותומכיה, בבחינת והיה כאשר תריד ופרקת עולו מעל צואריך (בראשית כז, מ), וכפי שנאמר לעשו.","b":false},{"t":"וזהו שנאמר (שם שם, שם), ועל חרבך תחיה, דאפשר לומר, דהמכוון על כחות הסט\"א שכל חיותם היא מן החרבן, וכאשר אמרו רבותינו (ראה פסחים מב, ב ומגילה ו, א), לא נתמלאה צור אלא מחרבנה של ירושלים, כמאמר הנביא יחזקאל (כו, ב), אמלאה החרבה. וזה הוא מאמר ה' לרבקה אמנו ע\"ה (בראשית כה, כג), ולאם מלאם יאמץ.","b":false},{"t":"והנה לרגע נדמה שיש בכח הסט\"א להפריע בקיום דבר ה' ורצונו, אך לא היא, כי עצת ה' היא תקום, ולו נתכנו עלילות, סיבת הסיבות ועילת העלות, מכה אותם בסנורים שלא יוכלו לראות בקיום הקדש, או שיראו ולא יבינו, כי הוא שגיא כח ושליט בכל ברואיו, ומי יאמר לו מה תעשה ומה תפעל. ובדמיונם יחשבו שהם קובעים מהלכי עולם ויכינו צעדיו, ובינתיים הקב\"ה מעביר ראשון ראשון, ומכסה בידו הגדולה את עיניהם מהביט בעינא בישא, עד יעבור עמך ה', עד יעבור דבריו ומהלכיו, ע\"י מלאכיו מבורכיו, עושי רצונו לשמוע בקול דברו, והם נאלמים בזעקתם ושאטתם, ועל פניהם נהפכת שלייתם, ותתגלה בושתם.","b":false},{"t":"ודעת לנבון נקל, שבבא הזמן להוריד נשמה קדושה וגבוהה כזו אל העולם, מיד נקהלים כל כחות הרע, להחשיך עולם ומלואו, בכדי לעכב מהלך כזה, ובורא עולם ומנהיגו, רוצה בקיומו של עולם שינהג כמנהגו על מי מנוחות, ועל כן סיבב וגלגל אופני מרכבה זו, עד שתראה כענין של חולין, והחיצונים בראותם כן מניחים הדבר והענין, והולכים לחינגותיהם, ואל בית תענוגיהם. ודבר אלהינו יקום לעולם (וראה מה שנתבאר בפר' תולדות מאמר ו).","b":false},{"t":"ואם יקום איש צר ורע עין, התולה כחו ויניקתו מטומאתם וחלאתם, ויאמר להפר עצת ה', לא דיו שאינו יכול להסיט האמת ממקומו, אלא גם זאת נוספת, במופת ובטוטפת, שהוא עצמו במו ידיו יקימנה, וכאשר ראינו אצל פרעה, שהתחכם בכל חכמתו נגד ה' ונגד משיחו, שלא יולד ולא יקום, עד שגזר על כל עמו לאמר, כל הבן הילוד היאורה תשליכוהו (שמות א, כב), ונתן את כל חילו ועוצמתו על הדבר זה, ומה קרה לבסוף, בתו בתיה היא שהצילתו למשה, ומקופתו של פרעה אביה שילמה למניקתו, היא אמו יולדתו, ועל ברכי פרעה גדל משה ונשתעשע, והוא עצמו למדו טכסיסי מלוכה, אשרי שלו ככה.","b":false},{"t":"והכא נמי ממעשיהם הלא טובים של כחות הטומאה, לוקחה דרך זאת להטעותם, בחושבם שזה עוד מעשה כמעשיהם, וילכו להם לדרכיהם, ועצת ה' קמה וגם נצבה, ותמר הצדקת בתו של נביא ה' שם בן נח (כמבואר בב\"ר פה, י), אשר נבחרה מאתו יתברך להיות אמא של מלכות, בית פרץ אשר ילדה תמר ליהודה, והיתה לאשת ער וגם לאונן אשר מתו בעוונם, ויושבת אלמנה חיה ומצפה עד יגדל שלה האח הצעיר, ותנתן לו לאשה, ובזה הסיחו דעתם כל כחות הסט\"א, והיא עמדה והתעודדה, ודבר ה' קוים על ידה.","b":false},{"t":"ומה נעמו דברי קדוש ה' בעל אור החיים הקדוש ע\"ה, שכתב על הפסוק (בראשית לח, יד), כי ראתה כי גדל שלה \"והיא\" לא נתנה לו לאשה, וצריך לדעת למה הוצרך לומר \"והיא\" ולא הספיק לומר ולא נתנה לו לאשה. והדבר מובן שעליה הוא אומר. ואולי כי ב' דברים אומר הכתוב. האחד, כי ראתה כי גדל שלה, והדבר מובן שלא נתקיים מאמר חמיה שאמר עד יגדל שלה וגו', כי עודנה בבית אביה. והשני, \"והיא\" לא נתנה וגו', פירוש שראתה ברוח הקודש שאינו ראוי שתנתן היא לו לאשה, ולזה עמדה ועשתה והצליחה, וצא ולמד מה יצא ממנה לעולם, מנשים באהל תבורך (שופטים ה, כד), עכ\"ל הקדוש.","b":false},{"t":"וגם רבינו עובדיה ספורנו כתב (בראשית לח, טז), כי לא ידע כי כלתו היא, גם אחר שנטה אליה אל הדרך לא הכירה, שאם היה מכירה היה מדבר בה בשביל בנו, ולאל יתברך נתכנו עלילות, שרצה שיהיה זרעה מיהודה, שהיה יותר שלם ורצוי משֵלה בנו, וממנה יהיה משיח צדקנו. עכ\"ל. וראה עוד בזוה\"ק (ח\"א דף קפח ע\"א וע\"ב), דברים נפלאים בזה. ע\"ש.","b":false},{"t":"וגם היום אנו רואים מראות נוראות, אשר שוכן שחק מתעתע בבני האדם אשר ישאו בגאוה ראשם, ויאמרו מי אדון לנו, והוא ילעג למו, להטעותם ולהטותם מן הדרך, עד יעבור עמך ה' עד יעבור עם זו קנית, ויבא אל המנוחה ואל הנחלה, בבא חזיון תרועה, ויה\"ר שנשמע קול שופר גדול, הקורא נס לחרותינו, ופדיון נפשנו בישועה ורחמים, בב\"א.","b":false}]},{"id":"20","t":"ענין יהודה ותמר – רמז לאחרית הימים","p":[{"t":"וַיֹּאמֶר יְהוּדָה לְתָמָר כַּלָּתוֹ שְׁבִי אַלְמָנָה בֵית אָבִיךְ עַד יִגְדַּל שֵׁלָה בְנִי כִּי אָמַר פֶּן יָמוּת גַּם הוּא כְּאֶחָיו וַתֵּלֶךְ תָּמָר וַתֵּשֶׁב בֵּית אָבִיהָ, וַיִּרְבּוּ הַיָּמִים וַתָּמָת בַּת שׁוּעַ אֵשֶׁת יְהוּדָה וַיִּנָּחֶם יְהוּדָה וַיַּעַל עַל גֹּזֲזֵי צֹאנוֹ הוּא וְחִירָה רֵעֵהוּ הָעֲדֻלָּמִי תִּמְנָתָה, וַיֻּגַּד לְתָמָר לֵאמֹר הִנֵּה חָמִיךְ עֹלֶה תִמְנָתָה לָגֹז צֹאנוֹ, וַתָּסַר בִּגְדֵי אַלְמְנוּתָהּ מֵעָלֶיהָ וַתְּכַס בַּצָּעִיף וַתִּתְעַלָּף וַתֵּשֶׁב בְּפֶתַח עֵינַיִם אֲשֶׁר עַל דֶּרֶךְ תִּמְנָתָה כִּי רָאֲתָה כִּי גָדַל שֵׁלָה וְהִוא לֹא נִתְּנָה לוֹ לְאִשָּׁה, וַיִּרְאֶהָ יְהוּדָה וַיַּחְשְׁבֶהָ לְזוֹנָה כִּי כִסְּתָה פָּנֶיהָ, וַיֵּט אֵלֶיהָ אֶל הַדֶּרֶךְ וַיֹּאמֶר הָבָה נָּא אָבוֹא אֵלַיִךְ כִּי לֹא יָדַע כִּי כַלָּתוֹ הִוא וַתֹּאמֶר מַה תִּתֶּן לִי כִּי תָבוֹא אֵלָי, וַיֹּאמֶר אָנֹכִי אֲשַׁלַּח גְּדִי עִזִּים מִן הַצֹּאן וַתֹּאמֶר אִם תִּתֵּן עֵרָבוֹן עַד שָׁלְחֶךָ, וַיֹּאמֶר מָה הָעֵרָבוֹן אֲשֶׁר אֶתֶּן לָךְ וַתֹּאמֶר חֹתָמְךָ וּפְתִילֶךָ וּמַטְּךָ אֲשֶׁר בְּיָדֶךָ וַיִּתֶּן לָהּ וַיָּבֹא אֵלֶיהָ וַתַּהַר לוֹ, וַתָּקָם וַתֵּלֶךְ וַתָּסַר צְעִיפָהּ מֵעָלֶיהָ וַתִּלְבַּשׁ בִּגְדֵי אַלְמְנוּתָהּ, וַיִּשְׁלַח יְהוּדָה אֶת גְּדִי הָעִזִּים בְּיַד רֵעֵהוּ הָעֲדֻלָּמִי לָקַחַת הָעֵרָבוֹן מִיַּד הָאִשָּׁה וְלֹא מְצָאָהּ, וַיִּשְׁאַל אֶת אַנְשֵׁי מְקֹמָהּ לֵאמֹר אַיֵּה הַקְּדֵשָׁה הִוא בָעֵינַיִם עַל הַדָּרֶךְ וַיֹּאמְרוּ לֹא הָיְתָה בָזֶה קְדֵשָׁה, וַיָּשָׁב אֶל יְהוּדָה וַיֹּאמֶר לֹא מְצָאתִיהָ וְגַם אַנְשֵׁי הַמָּקוֹם אָמְרוּ לֹא הָיְתָה בָזֶה קְדֵשָׁה, וַיֹּאמֶר יְהוּדָה תִּקַּח לָהּ פֶּן נִהְיֶה לָבוּז הִנֵּה שָׁלַחְתִּי הַגְּדִי הַזֶּה וְאַתָּה לֹא מְצָאתָהּ וגו': (לח, יא-כג)","b":true},{"t":"והדברים אומרים דרשני, דפשוט וברור שיש כאן דברים נפלאים, אשר היו לו ליהודה בכונה גדולה מהי\"ת, כדי שעצת ה' היא תקום, ויתגלה אורו של משיח.","b":false},{"t":"ובכתוב מצינו כי תמר נהגה איך שנהגה, מפני שראתה כי גדל שלה והיא לא נתנה לו לאשה. ואינו מובן, שאם מכח טענה זו היא באה, א\"כ היה לה לשלוח מעוררין ליהודה, ולומר לו, הנה שלה בנך גדל, ומדוע לא תקיים את הבטחתך להשיא את שלה לתמר, ואז ידונו בענין. ותחת זאת מה עשתה תמר, הלכה וישבה בפתח עינים והפקירה עצמה ליהודה.","b":false},{"t":"ועוד יש לדקדק, מדוע מדגיש לנו הכתוב שיהודה ירד תמנתה, וכן אומר הכתוב שהוגד לתמר שיהודה עולה תמנתה, ומה לו לומר היכן היה הענין. וגם מדגיש מטרת בואו לשם שהיה כדי לגוז את צאנו.","b":false},{"t":"וכן נמי צריך להבין את הכפילות דמתחילה אמר \"ויחשבה לזונה כי כסתה פניה\", כלומר שלא הכירה, ושוב חזר בפסוק שאחריו ואמר, \"כי לא ידע כי כלתו היא\".","b":false},{"t":"וגם ענין גדי העזים שהבטיח לה, והערבונות שנתן לה פתיל חותם ומטה אומרים דרשני, לדעת מה הם, ועל מה באו.","b":false},{"t":"ובדרך רמז אפשר לומר, שיהודה היה מתבונן בדרכיו, ומביט לקץ אחרית הימים לעת שיתגלה בה מלך המשיח, ועל דרך זה נתהלכה ברחבה לבאר את הפסוקים אשר לפנינו.","b":false},{"t":"ובתחילה הקדים ואמר, וירבו הימים, ותמת בת שוע אשת יהודה, וינחם יהודה וגו'. כלומר, שאחר רבות ימים ושנים בגלות המר והנמהר, בזמן שהחשך יכסה ארץ וערפל לאומים, ותמת בת שוע. וינחם, כלומר אחר שקרה מה שקרה באה הנחמה, וכן הוא שאחר שנחרב הבית, הגיע הזמן ובא עת דודים, והי\"ת מקבל נחמה, וחפץ לבנות שוב את ביתו ולפקוד את עמו ונחלתו.","b":false},{"t":"ולזה אמר ויעל על גוזזי צאנו, שהגיעה עת פקודתם של רודפי ישראל אשר הן המה קרויים גוזזי צאנו שגזזו ובזזו את ישראל ואכלום בכל פה דורות על גבי דורות, ועתה הגיעה העת בה יפקוד הי\"ת על בני אדום, וישקם כוס של תרעלה על כל אשר עשו. והוא שנאמר ויעל על גוזזי צאנו, כי ידו גברה עליהם, ועלו מושיעים בהר ציון לשפוט את הר עשו (עובדיה א, כא).","b":false},{"t":"וזהו מה שנזכר תמנתה. כלומר, ירמוז אל העתיד לבא, שהוא תמנתה, מלשון תמניא שהוא מספר שמונה, שהוא בחינת הגאולה, ומצינו בגמרא (ערכין יג, ב ובתוספתא שם ב, ד), רבי יהודה אומר, כנור של מקדש של שבעת נימין היה שנאמר (תהלים טז, א), שׂבַע שמחות את פניך, אל תיקרי שובע אלא שבע, ושל ימות המשיח שמונה, שנאמר (תהלים יב, א), למנצח על השמינית, על נימה שמינית של עולם הבא. והנה כבר הודיעונו קדמונינו נ\"ע, שכל עניני העוה\"ז כלולים במנין שבעה, ומספר שמונה הוא מעל לטבע, ומעל עניני העולם הזה (עי' בספרי מהר\"ל מפראג, ולדוגמא ראה נצח ישראל פל\"ב וע\"ע בנר מצוה עמוד כא ובשאר ספריו).","b":false},{"t":"ויוגד לתמר לאמר, הנה חמיך עולה תמנתה, היינו, משנודע לשכינה הקדושה כי עתה יהודה עלה ונתעלה לבא אל העיקר אשר הוא מעל ומעבר להבלי הזמן, תיכף, ותסר בגדי אלמנותה, כי בתחילה אמר לה יהודה, שבי אלמנה בית אביך, כל ימי מיגר ארמלותך, אבל עתה בא זמן הישועה, ועת הזמיר הגיע, להסיר בגדי אלמנותה מעליה, וללבוש בגדי מלכות. ולמה הסירה בגדי אלמנותה ולבשה בגדי מלכות, כי ראתה כי גדל שלה והיא לא נתנה לו לאשה, ומצאתי כאן רמז למלך המשיח, שכן משיח עולה בגימ' שנ\"ח ותיבת \"שלה\" ותיבת \"והיא\" עם הכולל עולה שנ\"ח, וזה פירוש הענין, כי גדל שלה ע\"י תיבת \"והיא\" והוא משיח, \"והיא\", היינו השכינה לא ניתנה לו לאשה עדיין, ומזה הבינה שאין זה יעודה, להוליד משלה, כי אינה שייכת לחלקו, לפי ששלה הוא מבניה של בת שוע אשת יהודה הראשונה, המסמלת את הגלות והחשך, אבל עתה הבינה תמר שתפקידה להקים את הבית החדש אשר יהיה ממנו אור לכל בית ישראל. והיינו כי אחר שהתנחם יהודה אחרי בת שוע, ועלה ונתעלה לתמנתה, או אז יקים ה' את דברו הטוב להביא את אור המשיח לעולם, ואשר על כן לא ילדה תמר מער ואונן כי הם בניה של בת שוע, וגם לשלה לא נתנה, כי גם הוא בנה של בת שוע, שהיא בת איש כנעני (בראשית לח, ב).","b":false},{"t":"\"ותכס בצעיף\" לפי שכבוד ה' הסתר דבר (משלי כה, ב), וגילוי המשיח הוא לפתע פתאום מתוך היסח הדעת, ואין הברכה שורה אלא בדבר הסמוי מן העין (תענית ח, ב ב\"מ מב, א). והמשיך ואמר הכתוב, ותתעלף, ופירש\"י ז\"ל, ותתעלף, (שם), כיסתה פניה, שלא יכיר בה. והמכוון שכיסתה את הפנימיות שלה ואת כל אורותיה, כיסוי תוך כיסוי, חותם תוך חותם, כמו שנאמר (שיר השירים ב, יד), יונתי בחגוי הסלע בסתר המדרגה. והיינו הסתר על הסתר, כאשר גזרה חכמתו יתברך.","b":false},{"t":"ותשב בפתח עינים, וכתב רש\"י ז\"ל, רבותינו דרשו, (סוטה י, א), בפתח עינים, בפתחו של אברהם אבינו, שכל עינים מצפות לראותו. עכ\"ל. וכתב בשפתי חכמים שם (אות ק'), והיינו שהתפללה תמר שיזדמן לה איש מזרע אברהם, כדי להעמיד בנים ממנו.","b":false},{"t":"ולדרכנו יש לומר, פתח עינים, כמו פתח לתקוה, היינו, כי עד עתה עברו ימים ושנים בסתר ובחשך, ועתה הגיעה עת דודים, לפתוח עינים עורות ולהביט באור, ומתוק האור וטוב לעינים (קהלת יא, ז), ובפתח הזה ישבה תמר. גם אפשר לומר דהתכסתה והתעלפה שיהיה בבחינת כבוד אלהים הסתר דבר, וישבה על הפתח בדרך זו, כדי לכסות עינים, שלא יָרֵעוּ ולא ישחיתו בכל הר קדשי (ישעיה יא, ט).","b":false},{"t":"ואפשר עוד דיהודה הבין ששני בניו מתו כשנשאו את תמר, כי הוא ידע שהיא מיועדת לגילוי אורו של משיח ה', ועל כן פגעה בהם מדת הדין רח\"ל. ואמר לה יהודה שבי אלמנה בית אביך, כי עדיין לא הגיעה העת, ותמר ישבה ימים רבים בציפייתה, ויהי כי ארכו הימים, וראתה שהיא לא ניתנה לשלה, הבינה כי מאת ה' היא מיועדת ליהודה עצמו. וכן נאמר אצל אונן (בראשית לח, ט), וידע אונן כי לא לו יהיה הזרע. וגם תמר הבינה שתזכה להעמיד את המשיח רק מיהודה עצמו ולא מבניה של בת שוע. אמנם אמרה תמר לנפשה, שמן הסתם יהודה חושש לשאתה, כדי שלא יקרהו כאשר קרה לבניו ער ואונן וימות אף הוא. ולכך הלכה בסתר על סתר.","b":false},{"t":"ומתחילה חשבה יהודה לזונה, והיתה דעתו נוטה לדרכה, וזהו, \"ויט אליה אל הדרך\", אבל משהתקרב והביט לעומק הענין, הבין שאין כאן קדשה אלא קדושה ושליחות מאת הי\"ת, ואז אמר יהודה לתמר, הבא נא אבא אליך, כלומר לא באקראי ובדרך תאוה וכדומה, אלא בהכנה הראויה לבא אל הקדש פנימה, כי עתה כבר הרגיש בפנימיות הגדולה הנמצאת בה, אעפ\"י שכסתה פניה. אלא שמכל מקום אילו היה נודע ליהודה כי תמר היא כלתו, היה מתרחק ממנה מתוך חשש פן יפגע גם הוא כפגיעת בניו. ועל כן מדגיש הפסוק שוב, כי לא ידע כי כלתו היא.","b":false},{"t":"ותאמר מה תתן לי כי תבא אלי. כלומר מה הוא הפיוס שלי אחרי כל ימי הגלות הקשים על תלאותיהם ונוראותיהם, מה תתן לי כי תבא אלי, ובזה תבא אל המלך, כדת וכדין.","b":false},{"t":"ויאמר אנכי אשלח גדי עזים מן הצאן, היינו, שישלח את השעיר המשתלח הרמוז בגדי העזים, ולאן ישלחהו, לעזאזל המדברה, ויפרידהו מן הצאן, מתוך עם ה', ולא יהיה עוד רובץ עליהם ורודה בהם בשבט מושלים, ותתעורר חבצלת השרון, לתקן עולם במלכות שדי, כי המלכות שלך היא, ולעולמי עד תמלוך בכבוד, ויהיה כבוד ה' בתוכה למופת ולאות.","b":false},{"t":"ואולי הוא על דרך הכתוב (עובדיה א, כא), ועלו מושיעים בהר ציון לשפוט את הר עשו, והיתה לה' המלוכה. ואמר יהודה, \"אנכי אשלח\", אשלח לכשאשלח, אראנו ולא עתה, אשורנו ולא קרוב, אבל סוף סוף אנכי אשלח, והשתמש בתיבת \"אנכי\" לרמוז אל מתן תורה הנרמז כולו באנכי ה' (שמות כ, ב), וכמו שאמרו רבותינו (שבת קה, א), \"אנכי\", נוטריקון אנא נפשי כתיבת יהבית, ורמז בזה כי הגאולה תלויה בלימוד התורה.","b":false},{"t":"ותאמר אם תתן ערבון \"עד שלחך\", והנה ידוע כי \"עד\" עולה בגימ' כשם \"אכדט\"ם\" שהוא שם של בטחון ובו ממתיקים הגבורות כידוע בדברי רבינו האר\"י (ראה שעה\"כ דרושי הפסח דרוש י\"ב ונתבאר באורך לעיל פרשת ויצא מאמר י), והוא שנאמר (ישעיה כו, ד), בטחו בה' עדי עד, ורומז לשם אכדט\"ם העולה בגימטריא ע\"ד. והוא מחליף את האותיות האמצעיות דשם \"אלהים\" באותיות הקודמות להם, דהיינו \"לה\"י\" נהפך להיות \"כד\"ט\" והוא מקור הבטחון.","b":false},{"t":"ותמר הצדקת חששה שאחר זמן רב יכולים ישראל להתייאש מן הגאולה ח\"ו, ולכן ביקשה לערבון את מדת הבטחון, ולכן אמרה אם תתן ערבון \"עד\" שלחך, או אז אתרצה, כי לא רצתה שירדמו ישראל וירפו מתקות הגאולה, אלא ישארו ערים בבטחונם בהי\"ת, ואסורים בתקותם אליו, ועיניהם צופיות עליו, כעיני שפחה אל יד גברתה, כן עיננו אל ה' אלהינו עד שיחוננו ויושיענו ברחמיו שנית בקרוב.","b":false},{"t":"ויאמר מה הערבון אשר אתן לך, ותאמר חותמך ופתילֶך ומטך אשר בידיך, ויתן לה וגו'. וכתב רבינו עובדיה ספורנו ז\"ל, כי בחרה תמר באלו הדברים, לפי שהמה המורים על הגדולה והגבורה, כחותם ושבט המושל, והאזור, כאומרו (איוב לח, ג ושם מ, ז), אזור נא כגבר חלציך, ואת זה עשתה כדי שתהרהר במעלת יהודה וגדולתו. עכ\"ד, ועיין עוד בכלי יקר שם.","b":false},{"t":"ולדרכנו אפשר לומר, דיהודה שאל אותה, מהו הערבון עבורינו שנזכה להחזיק במדת הבטחון כל הדרך הארוכה הזאת עד ביאת גוא\"צ, ותמר השיבה אמריה לו, חותמך ופתילך ומטך וגו', דאם שלש אלה יעשה לה לא תצא ריקם ח\"ו, והם. \"חותם\", שיהיה חותם הקב\"ה ניכר עלינו, בבחינת וראו כל עמי הארץ כי שם ה' נקרא עליך (דברים כח, י), והיינו למוד התורה, דהוא חותמא דקוב\"ה שהתורה היא אמת והיא חותמו של הי\"ת שהוא אל אמת. \"ופתילך\", היינו הכסות, שהם המעשים והמצוות, שמהם עושים בגד וכסוי לאדם בעולם הבא, והיינו, שגם במעשינו יקרא שם הי\"ת עלינו. \"ומטך\", זו הציפיה להנהגת \"שבט מושלים\", וימשיכו ישראל בציפייתם לישועת ה' ולביאת משיח מזרע יהודה, וְלֹא יַעְדֵּי עֲבֵד שֻׁלְטָן מִדְּבֵית יְהוּדָה. ואלו הם הערבונות אשר יחזיקו את ישראל בימי גלותם ועניים, עד אשר יחוס הי\"ת על עמו, וישלח ויסיר מעלינו את צפיר העזים, וישלחהו לעזאזל, וימהר יחיש גאולתינו.","b":false},{"t":"או יאמר, שביקשה תמר שלשה ערבונות, לרמוז לשלשה דברים שבזכותם נגאלו ישראל ממצרים, שלא שינו את שמם ולשונם ומלבושם (ראה ויק\"ר לב, ה ובמדב\"ר יג, יט ושהש\"ר ד, כה), ויש לרמוז את זה בפסוק (בראשית לג, יח), ויבא יעקב שלם, מילת \"שלם\" ר\"ת שמם, לשונם, מלבושם. והן המה שהחזיקו את אבותינו בעבדות מצרים ולא נטמעו בגוים עד שעמד עליהם הקב\"ה וגאלם ביד חזקה ובזרוע נטויה, ובהם נחזיק גם אנו עד שישלח לנו את משיחנו. והיינו חותמך, הוא השם. ופתילך, הוא הלבוש. ומטך הוא \"הלשון\" המהלך לפני האדם ומקשרו עם אחרים, כמו המטה שמקדם לפני ההולך ומשמיע קול.","b":false},{"t":"ויבא אליה ותהר לו ותקם ותלך ותסר צעיפה מעליה ותלבש בגדי אלמנותה. מעתה היתה תמר שקטה וחזרה לבגדיה ללבוש את בגדי גלותה וארמלותה, ומעתה היא ממתינה וצופיה לישועת ה', וכמו שהמעוברת מצפה כל ימי הריונה לולד שיולד, ואינה מסיחה את דעתה ממנו, ואעפ\"י שיתמהמה מצפה לו, כן עינינו צופיות ומיחלות אל הגאולה ולמלך המשיח, ואעפ\"י שיתמהמה אנו מחכים.","b":false},{"t":"וישלח יהודה את גדי העזים ביד רעהו העדלמי. אפשר לרמוז בזה, כי שלח את העז מן הצאן, וע\"י מי היה זה, ע\"י רעהו העדלמי, שיש בתחילת שמו שם ע\"ד הנז' שהוא גימ' אכדט\"ם והוא שם הבטחון, שמתמתקין הדינים והגבורות על ידו וכנז'.","b":false},{"t":"ולא מצאה, בא השליח לבשר לישראל את הגאולה, אך ברוב הדורות ורוב השנים ורוב הנדודים, והתחלפות המלכויות, ושינוי גזרותיהם ושיעבודיהם אשר השחירו את פנינו לבלי הכר עד שנהיו כשולי קדרה. ובא השליח לבשר גאולתינו ולא מצאנו, על דרך מה שנאמר (שה\"ש ג, א-ב), אבקשה את שאהבה נפשי בקשתיו ולא מצאתיו.","b":false},{"t":"וישאל את אנשי מקומה לאמר וגו', ששאל אצל סביבותיה ושכנותיה, ואין מכיר ויודע בה איה מקומה. ויאמרו לא היתה בזה קדשה. כלומר, אותה קדושה ואותה הדמות שאתה מתאר לנו לא היתה בזה, ואין אנו מכירים דבר זה. אבל, הקדושה היא תלויה בעין העליונה, והקב\"ה שרואה ומביט, הוא רואה אותה, עד כמה היא כמהה לו ועד כמה ציפתה, ולא איבדה את דרכי אבותיה ח\"ו, כי לא תשכח מפי זרעו לעולם ועד, רק היא מסתתרת, אבל לעיני הי\"ת היא גלויה.","b":false},{"t":"ועל כן גם כאשר שב השליח ואמר ליהודה לא היתה בזה קדשה וגם אנשי המקום וגו', ענה יהודה ואמר, תקח לה וגו' ואתה לא מצאתה, המשך וקח לה, כי אע\"פ שאתה לא ראית אותה, אבל אני ראיתיה, וקרוב יום ה' לבא, וביום ההוא עליך יזרח ה' וכבודו עליך יראה, ויוציאנו מן הגלות המר לגאולת עולם.","b":false},{"t":"(בס\"ד. אור ליום ששי ערש\"ק תרומה שלשה ימים לחדש אדר המהודר התשס\"ו - בדרך מארה\"ק לארה\"ב)","b":false}]},{"id":"20","t":"תאות רשעים תאבד","p":[{"t":"וַיַּרְא שָׁם יְהוּדָה בַּת אִישׁ כְּנַעֲנִי וּשְׁמוֹ שׁוּעַ וַיִּקָּחֶהָ וַיָּבֹא אֵלֶיהָ, וַתַּהַר וַתֵּלֶד בֵּן וַיִּקְרָא אֶת שְׁמוֹ עֵר, וַתַּהַר עוֹד וַתֵּלֶד בֵּן וַתִּקְרָא אֶת שְׁמוֹ אוֹנָן, וַתֹּסֶף עוֹד וַתֵּלֶד בֵּן וַתִּקְרָא אֶת שְׁמוֹ שֵׁלָה וְהָיָה בִכְזִיב בְּלִדְתָּהּ אֹתוֹ, וַיִּקַּח יְהוּדָה אִשָּׁה לְעֵר בְּכוֹרוֹ וּשְׁמָהּ תָּמָר, וַיְהִי עֵר בְּכוֹר יְהוּדָה רַע בְּעֵינֵי ה' וַיְמִתֵהוּ ה', וַיֹּאמֶר יְהוּדָה לְאוֹנָן בֹּא אֶל אֵשֶׁת אָחִיךָ וְיַבֵּם אֹתָהּ וְהָקֵם זֶרַע לְאָחִיךָ, וַיֵּדַע אוֹנָן כִּי לֹּא לוֹ יִהְיֶה הַזָּרַע וְהָיָה אִם בָּא אֶל אֵשֶׁת אָחִיו וְשִׁחֵת אַרְצָה לְבִלְתִּי נְתָן זֶרַע לְאָחִיו, וַיֵּרַע בְּעֵינֵי ה' אֲשֶׁר עָשָׂה וַיָּמֶת גַּם אֹתוֹ וגו': (לח, ב-י),","b":true},{"t":"ותרגם אונקלוס (בראשית לח, ב), בת איש כנעני, גבר תגרא. וכן הוא בתרגום יוב\"ע (שם). וכן פירש\"י ז\"ל (שם), שהוא סוחר ולא כנעני ממש, (ועיין בשפתי חכמים שם אות ל'). וגם רבינו אברהם ן' עזרא ז\"ל (שם), כתב, י\"א סוחר, וכמו כנען בידו מאזני מרמה (הושע יב, ח), ועם תוספת יו\"ד, ולא יהיה כנעני עוד (זכריה יד, כא). ויתכן להיות כמשמעו. עכ\"ל.","b":false},{"t":"ורבינו בעל אוה\"ח הקדוש ז\"ל (שם), כתב, והגאון הראב\"ע כתב, יתכן שהוא כמשמעו, ואני אומר כי לא יתכן שידבקו בני יעקב בדבר שהקפידו עליו אבותיהן שלשתם יחד, וכאומרם בפסחים (נ, א), והכתוב שמר את הדבר במה שדקדק לומר, בת איש כנעני, פירוש אביה כנעני ולא היא כנענית, ובאיזה אופן יהיה הדבר, אם לא שתאמר \"סוחר\", ואילו היה כנעני ממש, ומודיע הכתוב, כי עשה יהודה דבר בלתי הגון, היה לו לומר, וירא שם בת כנענית ושם אביה שוע וכו'. עכ\"ל.","b":false},{"t":"וכבר קדם בזה רבינו הרמב\"ן ז\"ל (שם), שכתב ע\"ד התרגום שהוא סוחר, שדעתו לומר שבני יעקב ישתמרו מלישא כנעניות כאשר ציוה אביהם, יצחק גם אברהם, וכן הזכירו במסכת פסחים (נ, א) וכו'. ע\"ש.","b":false},{"t":"ועפ\"י דרך זו של רבותינו ע\"ה עולה שלא היה חטא בנישואין אלו, ומה שמתו ער ואונן, היה בעוונם בלבד, וכשנתבונן נראה ששרש רעתם נעוץ במה שביקשו להם חשבונות רבים, עד שנפלו בעון החמור של השחתת זרע רח\"ל, שגם ער מת מאותו עון, שכן נאמר באונן (בראשית לח, י), וימת גם אותו, וכתב רש\"י ז\"ל (שם שם, ז), כמיתתו של ער מיתתו של אונן, והוסיף וכתב, ולמה היה ער משחית זרעו, כדי שלא תתעבר ויכחיש יופיה. עכ\"ל. הרי שער עשה חשבון לעצמו איך לשמר את יופיה של תמר, ולא שת לבו לדרך ה', והמיט אסון לעצמו, וימיתהו ה'. וכל כך גדלה רעתו, שאפילו משם הוי\"ה שכולו רחמים, נקנסה לו מיתה רח\"ל, כי לא נאמר וימיתהו אלהים אלא וימיתהו ה' (הוי\"ה), וכאומרם ז\"ל (ב\"ר לג, ג ושם עג, ג ובילקו\"ש בראשית רמז נז), רשעים מהפכים מדת הרחמים למדת הדין.","b":false},{"t":"ואחיו אונן לא לקח מוסר ממיתת אחיו ולא שם על לבו, וגם הוא ביקש חשבונות, כמבואר בפסוק, וידע אונן כי לא לו יהיה הזרע וגו', לבלתי נתון זרע לאחיו, וירע בעיני ה' אשר עשה, וימת גם אותו [א\"ה – יש להוסיף בזה דברי רבנו מהרח\"ו ז\"ל בספר שערי קדושה ח\"ב שער ו' שכתב וז\"ל, קרי לבטלה קשה מן שפיכות דמים של אחרים, ועוד שדמן ודם זרעיותם שאין להם קץ נשפך דמן, ובספר הזוהר פרשת ויחי (דף רי\"ט ע\"ב) כלהו חייביא אית להו תשובה בר מהאי, וכל העבירות הקטן פטור, חוץ מזה, שהרי ער ואונן קטנים מבן שבע שנים היו, ומתו בידי שמים, ולא עוד אלא שעדיין לא נצטוו עליהם, וכן בדור המבול כתיב (בראשית ו, יב), כי השחית כל בשר את דרכו על הארץ, וכל הבריות נמוחו מאדם עד בהמה ועוף השמים וכל הרמש, ואפילו שלשה טפחים מן העפר נמוחו מה שלא היה כן מאז נברא העולם ואחריו לא יהיה כן, ולא עוד, אלא שלא נצטוו זולת שבע מצות. ועי' עוד למרן החיד\"א ז\"ל בספר ראש דוד סדר תרומה, ולרבינו החח\"מ ז\"ל בספר מכתב לחזקיהו בחי' לברכות לא, ב. יבח\"ר].","b":false},{"t":"והנה האריכה התורה בענין זה, ללמדנו בינה והשכל, שלא לשית לבנו לחשבונות ושאר פניות, המסירים את לב האדם מדרך האמת. ודברים אלו צריכים חיזוק גדול ותמידי, כי טבעו של אדם להמשך אחרי הברק והנוצץ, ובפרט שהיצה\"ר מתעתע בדמיונו של אדם, ומראה לו שההצלחה כל כך קרובה אליו, והיא בהישג ידו, ואומר לו רק תעשה פעולה זאת, ותקרב או תרחק דבר אחר, וכבר תהיה מאושר עלי אדמות. והפיתוי לדרוך בדרך הזאת, אשר רבים מחזיקים בה, הוא עצום ורב.","b":false},{"t":"ועל כן התורה האריכה בענין זה להראות לעיני הכל את תוצאותיה האיומות של חיפוש החשבונות שלא כדין כדי להשיג את תאוות הנפש, שיש אדם המוכן לעבור ולהפר כל מצוה ולהניח את הדרך הנכונה בעבור תאוותו, ולא חושב שיש דין ויש דיין, ובסופו של דבר הוא עלול למצוא את עצמו כ\"כ רחוק מאותו הישג, שבעבורו הוא מיפר את מצות אלהיו. ויראה ויתבונן, במעשה ער ואונן, שעשו מעשיהם, להשלים מאוייהם, ולהרבות תאוותיהם, ולבסוף מה קרה. המיתם הי\"ת, ולא נשאר בידם מאומה, כמאמר הכתוב (ירמיה יז, יא), עושה עושר ולא במשפט בחצי ימיו יעזבנו ובאחריתו יהיה נבל, רח\"ל. וזהו שנאמר (תהלים קיב, י), תאות רשעים תאבד, היינו כי גם מה שבידם סופו ליאבד מחמת תאוותם.","b":false},{"t":"ועוד האריכה התורה לפרט ולפרש לנו את פרטי חטאם של שני האחים הללו, וגודל עונשם אפילו בעולם הזה. וזה מלבד ההפסד הגדול, שאם היו זוכים היו יכולים לזכות ומזרעם היתה יוצאת כל שושלת מלכות בית דוד, עד המשיח, אך לאחר חטאם ניטלה מהם מעלה זו, וניתנה לאחיהם הטובים מהם, ונשארו קרחים מכל וכל.","b":false},{"t":"ואשרי השם אורחותיו, ומשוה את שם ה' לנגד עיניו, וגם ביושבו במסתרים, יפקח את עיני שכלו, ויראה והנה ה' נצב עליו, ורואה ומביט בו, וכל מעשיו בספר נכתבים, אם רעים ואם טובים, וישים אל לבו שכל קושי הנסיון הוא לרגעים מעטים, וחלף ואיננו, ולא יכירנו עוד מקומו, כי את מקומו תקח רוח האכזבה, העוכרת רוחו ונפשו של האיש הרפה ורך המזג, אשר לא צלח במאבקו נגד יצרו, אשר הרע לו והכהו שוק על ירך, והשחית את נפשו בהשחיתו דרכו.","b":false},{"t":"ואם יגבר ויתגבר ברגעים הקלים ההם, ויצא וידו על העליונה, יתמלא לבו בסיפוק רוחני אין סוף, וירגיש מעין עידוני עולם הנצח, וגבר ישראל. ורק המנצח הוא שיודע בטעמו של האושר האמיתי, שטעמו לא נמר. וכל זה בעוה\"ז, אבל הקרן עומדת לו לעד, לאכול מפריה ולשבוע מטובה, עין לא ראתה.","b":false}]},{"id":"20","t":"פקח סומים ישעך מצפים","p":[{"t":"וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים: (לז, ג)","b":true},{"t":"ורש\"י ז\"ל כתב שכתונת פסים הוא מלשון כלי מילת וכו'. והביא עוד מהמדרש (ב\"ר פד, ח), שהוא על שם צרותיו שנמכר לפוטיפר ולסוחרים ולישמעאלים ולמדינים. עכ\"ל.","b":false},{"t":"ורבינו יעקב בעל הטורים כתב, \"פסים\" נוטריקון פ'וטיפר ס'וחרים י'שמעאלים מ'דינים. \"פסים\" עולה בגימטריא \"קץ\". רמז לו שעל ידו ירדו למצרים וישתעבדו בניו. והקב\"ה יחסר ק\"ץ מן השעבוד. ורמז לו שמסר לו הקץ. ורמז שימלוך פ' שנים ממנין סי\"ם שהוא מנין שנותיו. דבר אחר, פסים לשון פסו תמו, שעל ידו מת קודם לאחיו, פסים. שגרם פיוסים בינו לבין אחיו. \"פסים\", בגימטריא \"לפס ידו\" וכו' ע\"ש.","b":false},{"t":"ואמרתי אולי \"פסים\" ר\"ת \"פקח סומים ישעך מצפים\" [דומה לשם הקדוש אנקת\"ם]. והכונה בזה, שאחי יוסף התנהגו עמו כסומים, שהקנאה שבערה בלבם העבירתם על דעתם וסימאה את עיניהם, עד שיצאו להלחם ביוסף ועשו את אשר לא יעשה, ולא פקחו עיניהם לראות כי מה' יצא הדבר, וחשבו להרחיק את יוסף מתכליתו, ובמו ידיהם שלחו אותו למקום יעודו. ויוסף היה סובל בגללם והגיע עד שערי מות, וע\"כ עשה לו אביו כתונת \"פסים\", \"פ - ס\" הוא כתפלה על אחיו, \"פקח סומים\", שה' יפקח עיני שכלם וייטיבו לראות. \"י - מ\", הוא על יוסף הצדיק, והיינו, \"ישעך מצפים\", שלא יטבע בים היאוש ח\"ו, אלא יתחזק בבטחונו ויחיה באמונתו.","b":false},{"t":"ואפשר דלזה הוסיפו ליוסף שנתים על שאמר (בראשית מ, יד) \"וזכרתני\" (ראה ב\"ר פט, ג הוב\"ד ברש\"י בראשית מ, כג), שלפי שרשו היה לו לצפות לישועת ה' בלבד.","b":false}]},{"id":"20","t":"פרשת וישב – חנוכה \"בימים ההם ובזמן הזה\"","p":[{"t":"אֵלֶּה תֹּלְדוֹת יַעֲקֹב יוֹסֵף וגו', וְיִשְׂרָאֵל אָהַב אֶת יוֹסֵף מִכָּל בָּנָיו כִּי בֶן זְקֻנִים הוּא לוֹ וְעָשָׂה לוֹ כְּתֹנֶת פַּסִּים, וַיִּרְאוּ אֶחָיו כִּי אֹתוֹ אָהַב אֲבִיהֶם מִכָּל אֶחָיו וַיִּשְׂנְאוּ אֹתוֹ וְלֹא יָכְלוּ דַּבְּרוֹ לְשָׁלֹם, וַיְקַנְאוּ בוֹ אֶחָיו וגו', וַיִּתְנַכְּלוּ אֹתוֹ לַהֲמִיתוֹ וגו', וַיְהִי כַּאֲשֶׁר בָּא יוֹסֵף אֶל אֶחָיו וַיַּפְשִׁיטוּ אֶת יוֹסֵף אֶת כֻּתָּנְתּוֹ אֶת כְּתֹנֶת הַפַּסִּים אֲשֶׁר עָלָיו, וַיִּקָּחֻהוּ וַיַּשְׁלִכוּ אֹתוֹ הַבֹּרָה וְהַבּוֹר רֵק אֵין בּוֹ מָיִם וגו', וַיַּעַבְרוּ אֲנָשִׁים מִדְיָנִים סֹחֲרִים וַיִּמְשְׁכוּ וַיַּעֲלוּ אֶת יוֹסֵף מִן הַבּוֹר וַיִּמְכְּרוּ אֶת יוֹסֵף לַיִּשְׁמְעֵאלִים בְּעֶשְׂרִים כָּסֶף וַיָּבִיאוּ אֶת יוֹסֵף מִצְרָיְמָה וגו', וְהַמְּדָנִים מָכְרוּ אֹתוֹ אֶל מִצְרָיִם לְפוֹטִיפַר סְרִיס פַּרְעֹה שַׂר הַטַּבָּחִים וגו', וַיְהִי אַחַר הַדְּבָרִים הָאֵלֶּה וַתִּשָּׂא אֵשֶׁת אֲדֹנָיו אֶת עֵינֶיהָ אֶל יוֹסֵף וַתֹּאמֶר שִׁכְבָה עִמִּי, וַיְמָאֵן וגו', וַיְהִי כְּדַבְּרָהּ אֶל יוֹסֵף יוֹם יוֹם וְלֹא שָׁמַע אֵלֶיהָ לִשְׁכַּב אֶצְלָהּ לִהְיוֹת עִמָּהּ, וַיְהִי כְּהַיּוֹם הַזֶּה וַיָּבֹא הַבַּיְתָה לַעֲשׂוֹת מְלַאכְתּוֹ וְאֵין אִישׁ מֵאַנְשֵׁי הַבַּיִת שָׁם בַּבָּיִת, וַתִּתְפְּשֵׂהוּ בְּבִגְדוֹ לֵאמֹר שִׁכְבָה עִמִּי וַיַּעֲזֹב בִּגְדוֹ בְּיָדָהּ וַיָּנָס וַיֵּצֵא הַחוּצָה וגו', וַיִּקַּח אֲדֹנֵי יוֹסֵף אֹתוֹ וַיִּתְּנֵהוּ אֶל בֵּית הַסֹּהַר מְקוֹם אֲשֶׁר אֲסִירֵי הַמֶּלֶךְ אֲסוּרִים וַיְהִי שָׁם בְּבֵית הַסֹּהַר: (פסוקים מלוקטים בפרשת וישב),","b":true},{"t":"בִּימֵי מַתִּתְיָה בֶן יוֹחָנָן כֹּהֵן גָּדוֹל חַשְׁמוֹנָאִי וּבָנָיו כְּשֶׁעָמְדָה מַלְכוּת יָוָן הָרְשָׁעָה עַל עַמְּךָ יִשְׂרָאֵל לְשַׁכְּחָם תּוֹרָתָךְ וּלְהַעֲבִירָם מֵחֻקֵּי רְצוֹנָךְ. וְאַתָּה בְרַחֲמֶיךָ הָרַבִּים עָמַדְתָּ לָהֶם בְּעֵת צָרָתָם. רַבְתָּ אֶת רִיבָם. דַּנְתָּ אֶת דִּינָם. נָקַמְתָּ אֶת נִקְמָתָם. מָסַרְתָּ גִּבּוֹרִים בְּיַד חַלָּשִׁים. וְרַבִּים בְּיַד מְעַטִּים. וּרְשָׁעִים בְּיַד צַדִּיקִים. וּטְמֵאִים בְּיַד טְהוֹרִים. וְזֵדִים בְּיַד עוֹסְקֵי תוֹרָתֶךָ. לְךָ עָשִׂיתָ שֵׁם גָּדוֹל וְקָדוֹשׁ בְּעוֹלָמָךְ. וּלְעַמְּךָ יִשְׂרָאֵל עָשִׂיתָ תְּשׁוּעָה גְדוֹלָה וּפֻרְקָן כְּהַיּוֹם הַזֶּה. וְאַחַר כָּךְ בָּאוּ בָנֶיךָ לִדְבִיר בֵּיתֶךָ וּפִנּוּ אֶת הֵיכָלֶךָ. וְטִהֲרוּ אֶת מִקְדָּשֶׁךָ. וְהִדְלִיקוּ נֵרוֹת בְּחַצְרוֹת קָדְשֶׁךָ. וְקָבְעוּ שְׁמוֹנַת יְמֵי חֲנֻכָּה אֵלּוּ בְּהַלֵּל וּבְהוֹדָאָה. וְעָשִׂיתָ עִמָּהֶם נִסִּים וְנִפְלָאוֹת וְנוֹדֶה לְשִׁמְךָ הַגָּדוֹל סֶלָה: (נוסח על הנסים הנאמר בתפלה ובבהמ\"ז)","b":false},{"t":"יש קשר חזק ואמיץ בין הנאמר בפרשתנו, פרשת וישב לבין מה שהיה בחנוכה, ולא בכדי הם באים בזמן אחד, קשורים זה בזה. וצריכים לעמוד על הקשר ביניהם.","b":false},{"t":"בפרשה זו, מדובר על מכירת יוסף ועל כל תלאותיו, כשבמרכזם עומד הנסיון הגדול שעבר עליו עם אשת פוטיפר. ולעולם לא נוכל להבין את גודל ועומק הנסיון הזה, אם לא נשים לבנו למצב המיוחד והקשה, בו היה נתון יוסף גם בלי הנסיון, כי הלא מדובר בבחור צעיר שנפל מאיגרא רמא, מבית אביו הגדול, אשר אהבו מכל בניו, ושם היה מסתופף בצילא דמהימנותא, ולומד תורת אלהים חיים מפיו של יעקב סבא קדישא, בחיר שבאבות. ומן המקום הנפלא והמרומם ההוא, משם נפל לבירא עמיקתא בור של נחשים ועקרבים, אליו נזרק באכזריות איומה ע\"י אחיו, וגם אחר שריחמו עליו והעלוהו מן הבור לא החזירוהו לבית אביו, אלא מכרוהו לעבד לעבדים בני קדר, ומשם הלך מדחי אל דחי עד בואו למצרים, ארץ זימה וזוהמא. וביד מי נפל, ביד פוטיפר (וראה את דברי רבותינו המבהילים על פוטיפר במסכת סוטה יג, ב), והוא בודד וזר בארץ זרה לרוחו ולנפשו.","b":false},{"t":"והנה טבע הדברים כשאדם נקלע לכגון זה, הריהו נכנס ליאוש ודכאון חמור, אשר עלול להביא פריקת כל עול, מתוך שמנסה להשכיח מעצמו את כל עברו, ולהתאים את עצמו למציאות החדשה, כדי למצוא חן בעיני אדוניו, או שהוא שוקע בים העצבות הארורה שתוצאותיה מי ישער, ובתוך מצב קודר זה, נקלע לנסיון גדול ביותר, של אשת פוטיפר, כשהוא עבד משרת אצלה בבית, באין שום אפשרות להתחמק מתחת ידה, והיא מדברת אליו יום יום, וכפי שתיארו רבותינו במדרשים באיזה לבושים ואיזה פיתויים וכו'. וכאשר מצינו במסכת יומא (לה, ב), אמרו עליו על יוסף הצדיק, בכל יום ויום היתה אשת פוטיפר משדלתו בדברים, בגדים שלבשה לו שחרית לא לבשה לו ערבית, בגדים שלבשה לו ערבית לא לבשה לו שחרית, אמרה לו השמע לי, אמר לה לאו. אמרה לו הריני חובשתך בבית האסורין, אמר לה ה' מתיר אסורים. הריני כופפת קומתך, אמר לה ה' זוקף כפופים. הריני מסמא את עיניך, ה' פוקח עורים. נתנה לו אלף ככרי כסף, לשמוע אליה לשכב אצלה להיות עמה, ולא רצה וכו'. ע\"כ מהגמ'. ועי' עוד בבראשית רבה (פז, י). ובמדרש תנחומא (פרשת וישב), מתואר בארוכה במה היתה מתלבשת, ובאי אילו קישוטים ובשמים כלים מכלים שונים היתה מקשטת עצמה וכו', עד אותו היום שהיתה אתו לבדה בבית, ואז אזרה את כל כחה וחילה להכניע עלם צעיר זה, ולהפילו ברשתה, ומשראתה את גבורתו כי רבה, וכי בורח הוא ממנה, החזיקה בכנף מעילו כדי להעליל עליו, ולאיים עליו בזה שהיא תאמר שהוא בא להתעולל, וכמו שהוכיח סופה.","b":false},{"t":"ואיש חכם ונבון כיוסף הצדיק, בודאי ידע את הסכנה החמורה העומדת למולו, בהשאירו את מעילו אצלה, ולא נעלמו ממנו מזימותיה ותעלוליה. אך כל פיתוייה לא השפיעו עליו, וגם הסכנה לא הרתיעתו, ולא עמדו לפניו לא תחנוניה ולא איומיה, וגם אחר שהיה בבית האסורים היתה באה אליו ומשדלתו לעבירה ואומרת לו שאם ימלא אחר דבריה היא תוציאנו משם, אך הוא בשלו, עומד בסירובו. כי רק דבר אחד הצטייר בפניו כפי שאמרו חז\"ל (סוטה לו, ב), והובאו דבריהם בפירוש רש\"י (בראשית לט, יא), \"שדמות דיוקנו של אביו הצטיירה בפניו\" ושמרה אותו מן החטא. אותה דמות מופת של הסבא קדישא יעקב אבינו, שהיה רגיל לעמוד כחלמיש צור בפני כל הנסיונות, היא שעמדה בעת הזאת למול עיני יוסף, והיא שמילאתו ברוח גבורה עילאית, עד שיכול היה לעמוד בכל זה.","b":false},{"t":"וצריך להבין מהיכן באה לו הדמות הזו ליוסף, וקשה לומר שמהשמים הראוהו את אביו ניצב עליו, כי הלא מן השמים העמידוהו בנסיון הגדול הזה, ואיך יביאו לו באותו רגע את דמות אביו הגדול, שתצילהו מן החטא, והלא הדבר דומה לקול ושוברו עמו.","b":false},{"t":"אלא הנראה בזה דזה היה פרי עבודתו העצמית של יוסף הצדיק ע\"ה, שכידוע יוסף לא היה רק בנו של יעקב אבינו, אלא גם תלמידו המובהק בתורה ובמצות וביר\"ש, וכמ\"ש חז\"ל (ב\"ר פד, ח והובא נמי בדברי רש\"י בראשית לז, ג), על הפסוק כי בן זקונים הוא לו (בראשית לז, ג), שכל מה שלמד יעקב אבינו בבית שם ועבר מסר ליוסף, עי\"ש.","b":false},{"t":"וכל זמן שהיה יוסף הצדיק בבית יעקב אביו, היתה עינו של הסבא קדישא, פקוחה עליו בהשגחה גדולה, להנחותו ולהדריכו בדרך העולה במעלות הקדושה מחיל אל חיל, כיאה לבנו ותלמידו של בחיר האבות.","b":false},{"t":"אך מיום שנמכר יוסף וגלה מבית אביו, הרגיש מיד בחסרון זה, וכמו שמצינו בגמרא (מו\"ק כד, א), שבפטירתו של רב קרע עליו שמואל שנים עשר בגדים ואמר אזל גברא דהוה מסתפינא מיניה, וכן מצינו ברבי יוחנן, שכשאמרו לו לרבי יוחנן נח נפשיה דרבי חנינא, קרע עליו שלשה עשר בגדי משי ואמר ווי דאזיל גברא דמסתפינא מיניה. וגם יוסף הצדיק פחד מהחסרון העצום של דמות אביו, ונתירא שלא יזיק לו הדבר. ומאז חיפש עצות בנפשו כדת מה לעשות, כדי שלא יכשל ולא יטה ימין ושמאל מהחינוך הקדוש שקיבל בבית אבא, ובחר לו דרך בטוחה וטובה, והיא שבכל דבר שעמד לפניו, והיה צריך להחליט אם לעשותו ואיך לעשותו, מיד היה מעלה בדמיונו את דמות יעקב אבינו ע\"ה שהוא נצב עליו ומתבונן בו בעינא פקיחא, והיה חושב יוסף בדעתו מה היה יעקב אביו אומר על שאלה זו, וכיצד היה מתייחס למעשה זה, וכל דבר שהיה בו ספק שמא אינו מתאים לרוחו של יעקב, מיד היה נמנע ממנו, וכך יכל יוסף הצדיק להחזיק מעמד בכל ימי גלותו הקשים, מבלי שום נגע ופגע.","b":false},{"t":"ובדרך זו התנהג יוסף הצדיק, ועל כל צעד ושעל שהלך, לא הסיח דעתו אף לרגע מהנהגת אבותיו הקדושים, עד שמרוב ההרגל, נהפך אצלו הדבר לטבע. ובבא עת מבחן, גם ברגעים הקשים ביותר, נצטיירה מאליה ועמדה לפניו דמות אביו הקדוש, אותה דמות נפלאה, של האדם הגדול בענקים, שעמד בכל המשברים והנסיונות ולא נע ולא זע מדרכו בקדש, ואפילו אחר צאתו מביתו, ושהייתו בבית לבן הרשע במשך עשרים ושתים שנה, לא זז כמלוא נימא מהנהגותיו הקדושות, וכשחזר לארץ ישראל נאמר בו, ויבא יעקב שלם (בראשית לג, יח), שלם בתורתו ויראתו (כמבואר במסכת שבת לג, ב), ואותה דמות עם כל משמעותה והדרה, היא שהפיחה בו ביוסף הצדיק רוח עוז וגבורה, אומץ ותוקף, כדי לעמוד נגד כל הרוחות הרעים שעמדו עליו להפילו ולהדיחו.","b":false},{"t":"ודרך זו של מסירות נפש וגבורת הרוח, שהיא תנאי הכרחי ביותר לקיומה של תורה ושמירת מצותיה, קיבלנו אותה במורשה מאבותינו הקדושים, מאברהם אבינו שמסר נפשו לכבשן האש, ומיצחק אבינו שנעקד על גבי המזבח על קדושת שמו יתברך, ועד יעקב אבינו ויוסף הצדיק ושאר הקדושים שבכל דור ודור.","b":false},{"t":"וסגולה נפלאה זו היא שעמדה לזרעם אחריהם בעמדם נגד היונים הרשעים שרצו להעבירם על דתם ועל דעתם, ולא בכדי חג החנוכה קשור תמיד עם הפרשה הזו. כי לכשנתבונן נמצא שגם בני חשמונאי הצדיקים וחבריהם עמדו בנסיונות דומים לאלו שבהם עמד יוסף הצדיק. נסיונות הכוללים פיתויים גדולים מחד גיסא, ואיומים קשים ומרים מאידך גיסא.","b":false},{"t":"כי גם אליהם באו היונים בכל מיני פיתויים (כמו אשת פוטיפר), ובנו גשרים ובתי מרחצאות, שוקים ובתי טרטיאות וקרקסאות וכו', שהם דברים המושכים לבו של אדם, ואמרו להם שכל רצונם לחיות עמהם יחד באהבה ובשלום. אלא שלצורך זה דרושה תרבות חדישה ומתקדמת, שתגשר על הפערים שבין שני העמים, היא תרבות יון הידועה לשמצה.","b":false},{"t":"וכשראו היונים שלא די בדרך זו כדי להטות את לב העם אחריהם, אז לא נמנעו גם מדרכים אחרות שונות ומשונות, כמו שמתואר כל זה בדברי רבותינו ז\"ל, עד שהגיעו גם לגזור גזירות מפורשות שכל הלומד תורה, וכל המקיים את דת ישראל אחת דתו להמית, ואמנם היו מתיונים שחלקם הסתנור מהברק החיצוני, הנראה לכאורה בתרבות קלוקלת ומופקרת זו, וכל שבהפקירא ניחא ליה, בחר לו דרך זו. וחלק מהעם הלך אחריהם מתוך פחד מגזירותיהם הקשות. וכלל עם ישראל עמדו במבחן קשה ביותר, בדומה למצבו של יוסף שיש פיתויים מצד אחד וסכנה מצד אחר.","b":false},{"t":"וגם כאן בעיני המכבים הקדושים נצטיירו אותם דמויות מופלאות של האבות הקדושים, ושל יוסף הצדיק וכל קדושים עמו, עם כל מעשי גבורתם ועוז רוחם, ולא שתו לבם לפיתויים ולברק החיצוני, גם לא נרתעו מהפחד והסכנות, רק אחזו את אומנות אבותם בידם, הלא היא המסירות נפש הנפלאה על שמירת חוקי התוה\"ק ומצותיה, שעוברת כחוט השני מאברהם ויצחק ויעקב ויוסף, וכן בכל דור ודור, והחליטו לעמוד איתנים כחלמיש צור מול כל נסיונות היונים, ויצאו להלחם מלחמת קדש נגד תרבות אנשים חטאים, והנושאים את דגלה של יון האדירה, ואם כי זה נראה יותר כהתאבדות המונית מאשר מלחמה. מפאת חולשתם של החשמונאים מול עוצמתם האדירה של היונים.","b":false},{"t":"מ\"מ אמרו מוטב למות בקדושה וטהרה על קיומה של תורה וקידוש השם, מאשר להתקיים על חורבנה של התוה\"ק, ומשהלכו שלא כדרך הטבע ומסרו נפשם על קידוש ה' ממש, בלי שום חשבונות, אז התחולל הנס הגדול והנפלא, ברחמי הי\"ת המרובים, שנתן גבורים ביד חלשים ורבים ביד מעטים, ורשעים ביד צדיקים וטמאים ביד טהורים. ומה שנראה מתחילה כדבר מגוחך, נהפך לחזיון נפלא ומרהיב מאין כמוהו. ונקבע לאות ולמופת לדורות עולם.","b":false},{"t":"וזה היה בימים ההם, בימי יוסף בשעתו, ובימי החשמונאים בשעתם ובזמנם, אכן גם בזמן הזה עדיין אנו זקוקים לאותה מסירות נפש, שאין קיום לתורה אלא במסירות נפש, שאמנם החשמונאים הכניעו את היונים, אך תרבותם עדיין מצויה בעולם, ואפילו התפתחה עם התפתחות הרע בכללותו והתגברותו, ונעשתה לאחד מכלי המשחית הגדולים בהם משתמש היצה\"ר וחילותיו, עלי אדמות, וגם בתוכינו לא חסרים המתיונים למיניהם, הזוממים לכלות כל חלקה טובה, ואינם בוחלים בשום דרך להפיק את זממם הרע, וחושבים שהם עושים את הדברים הנעלים ביותר עלי אדמות, עד שיראו צורך למסור נפשם על דרכם זו, ומוכנים להלחם בכל עוז בכל מי שיעמוד בדרכם, ולא חוסכים כל מאמץ ושום פיתוי לשבות את ילדי ונערי ישראל התמימים, וגם רבים מהמבוגרים שנתפסים לשעת חולשה ויורדים ממעלתם, וגם דרך האיום וההפחדה לא חסרים בימינו, אם זה ע\"י מקומות העבודה ומקורות הפרנסה, ועוד דרכים רבות, ובעת שכזאת שהיא מלאה בלבול ויסורים רבים, והיא עת נוראה המלאה בהסתר פנים, בבחינת כי הנה החשך יכסה ארץ וערפל לאומים (ישעיה ס, ב), ע\"י חולשת הדור והמצבים הקשים, מפאת המלחמות ויתר הצרות, וגם קושי הפרנסה.","b":false},{"t":"והנה דוקא בעת הזאת, נתרבו כלי המשחית הרוחניים לא פחות מהגשמיים, וכלים רבים עשו להם להביא את דעותיהם הנפסדות לכל פינה ומקום, והם התרבו והתעצמו במאד מאד ותמלא הארץ אותם, ועל מי יש לנו להשען ולמי נפנה לעזרה.","b":false},{"t":"אכן מעשי אבותינו וזכותם, היא שתעמוד לנו כי לא בדרכים החדשות ישועתינו, ולא עליהם תקותינו, כי אם בדרך הסלולה מימי קדם, דרך מסירות הנפש האמיתית והטהורה, ללא כחל וללא סרק, מסירות נפש נגד כל הפיתוים בעמידה איתנה ותקיפה, על דרכינו דרך התורה והיראה, ואל לנו להתפעל מהברק ומהנוצץ, אשר אין לו שום יסוד ובסיס, אלא רק על אבינו שבשמים אנו נשענים, ובו אנו בוטחים וסמוכים, ובתורתו נהגה יומם ולילה ומינה לא נזוע. ובבטחון זה נעמוד גם מול האיומים וההפחדות למיניהם, ולה' הישועה.","b":false},{"t":"ובהיותי בזה אמרתי להביא מה ששמעתי פעם מהגה\"צ רבי רפאל ברוך טולידאנו זיע\"א שפירש את הפסוק (תהלים לא, כ), מה רב טובך אשר צפנת ליראיך פעלת לחוסים בך נגד בני אדם. ושאל מהו \"נגד בני אדם\" האם כדי לעבוד את ה' צריך ללכת נגד בני אדם.","b":false},{"t":"אלא פירש הוא ז\"ל, שהכתוב מדבר, באנשים השולחים את בניהם ללמוד תורה בישיבות הקדושות, ויש בני אדם אשר יחשבום לשוטים באומרם להם, למה לא תלמדו את בניכם השכלה ורפואה והנדסה וכיו\"ב, להועיל להם בחיים, ושיהיה להם כדי קיומם וכו', וכל מיני טענות ומענות. אך הם חוסים בה' ובוטחים ברחמיו נגד בני אדם, על זה נאמר מה רב טובך אשר פעלת לחוסים בך, נגד בני אדם, כלומר, נגד הדעות המקובלות אצל רוב בני האדם, ודפח\"ח, וזיע\"א.","b":false},{"t":"וכאשר נשכיל לעמוד נגד בני אדם ודעותיהם בכל תוקף ועוז, גם הוא יתברך יעשה עמנו מעל לטבע, ויראנו נסים ונפלאות, כמו שעשה לאבותינו בימים ההם ובזמן הזה. ואז יקויים בנו, ועליך יזרח ה' וכבודו עליך יראה (ישעיה ס, ב). במהרה בימינו אמן.","b":false},{"t":"(דרשה שדרשתי בביכ\"נ שערי רחמים בשלומי [בכפר], בשבת וישב, נר ב' דחנוכה, התשל\"ג)","b":false}]},{"id":"20","t":"יעקב מבקש להביא גאולה לבניו","p":[{"t":"ועוד יש לבאר בזה בס\"ד והוא עיקר, דיעקב אבינו ע\"ה ראה את צערם של בניו במשך הגלות האחרונה, וראה שאינם נחים ואינם שוקטים והיה מיצר עליהם, ומבקש להם ריוח והצלה, וכמו שאמרו (פסחים נו, א וב\"ר צו, א ושם צח, ב), ביקש יעקב לגלות את הקץ. וגם כאן ביקש יעקב לישב בשלוה בשל-ו\"ה. כדי לקרב את ישועתם של ישראל ויתגלה קץ משיחיה.","b":false},{"t":"דידוע דהשלמת הגאולה תלויה בהשלמת שם הוי'ה ב\"ה, כדכתיב (שמות יז, טז), כי יד על כס יה מלחמה לה' בעמלק מדור דור. ואמרו חז\"ל (תנחומא תצא פי\"א ובמדרש תהלים מזמור ט' ובילקו\"ש שם וראה פסיקתא דר\"כ ג, טז ועי' תוס' ברכות ג, א ד\"ה היה לך), נשבע הקב\"ה שאין השם שלם ואין הכסא שלם, עד שימחה שמו של עמלק, דבכסא חסרה אות א' שהרי נאמר כי יד על \"כס\" ובשם הי\"ת חסרות אותיות ו'-ה' שהרי נאמר כס \"יה\".","b":false},{"t":"ובמקום אחר פירשתי ע\"פ דברי האר\"י זלה\"ה, דעצם קיומו של עמלק הוא מורה על ניצוצות של קדושה שנפלו והם בשבי של סטרא אחרא, שמזה הם מתקיימים, וזה מראה שאין השם והכסא שלמים, דהשלמתם היא בהשבת אותם ניצוצות למקורם וכשישובו הניצוצות למקורם אין עוד קיום לעמלק. עוד כתבתי שם (ראה לעיל פר' חיי שרה מאמר ז), שהשלמת ו'-ה' דהוי'ה תלויה במלחמה ותיגרא דוקא, דכתיב (שמות יז, טז), מלחמה לה' וגו', יעו\"ש.","b":false},{"t":"ויעקב אבינו ע\"ה שרצה לגלות את הקץ, ביקש לישב בשל - ו\"ה, היינו, להשלים את שם הוי'ה ב\"ה, ולהביא מנוחה לבניו, אלא שקפץ עליו רוגזו ושטנו של יוסף. ואולי רומז למשיח בן יוסף שרוגזו וכאביו קפצו עליו, שעל זה אנו מתפללים בכל יום בבונה ירושלים, שיחיה ולא יהרג ע\"י ארמילוס רשיעא (ראה שעה\"כ דרוש העמידה דרוש ו' ובפע\"ח שער העמידה פי\"ט). ואפשר שמלחמה זו היא שתביא להשלמת שם הוי'ה ב\"ה, וקץ זה ביקש יעקב לגלות, אלא שנסתם ממנו כל חזון.","b":false},{"t":"ואל תתמה על הדבר דרק יעקב אבינו מתעסק בזה, ולא שאר האבות, דכל אחד לפי בחינתו, ועל יעקב אבינו ע\"ה נאמר (בראשית לב, כד), ויאבק איש עמו עד עלות השחר, ואמרו חז\"ל מי שנאבק עם יעקב הוא שרו של עשו הממונה על סט\"א (ב\"ר עז, ג וראה תנחומא וישלח פ\"ח דהוא סמאל והוא שרו של עשו). ומזמן אבינו יעקב ועד עתה נמשך המאבק הזה, עד שיבקע שחר הגאולה, כמאמר הנביא (ישעיה נח, ח), אז יבקע כשחר אורך וארוכתך מהרה תצמח. וזה מלמד שמאבק זה דידיה הוא ועליה רמיא, וכן אמרו חז\"ל במפורש והביא דבריהם רש\"י ז\"ל בפרשת בחוקותי (ויקרא כו, מב), על הפסוק, וזכרתי את בריתי יעקוב, יעקוב - בחמשה מקומות נכתב מלא וא\"ו, ואליהו חסר בחמשה מקומות וא\"ו. יעקב נטל אות משמו של אליהו ערבון שיבוא ויבשר גאולת בניו. ע\"כ. ובמקום אחר פירשתי בס\"ד שזה כנגד האות ו' החסר בפדות של עם ישראל דכתיב (שמות ח, יט), ושמתי פדת בין עמי ובין עמך (חסר וא\"ו), וכשאליהו ישיב את האות וא\"ו של פדות למקומה, ישיב לו יעקוב אבינו את הוא\"ו שלו וא\"ו תחת וא\"ו. (ועיין בהקדמה לשו\"ת שמע שלמה ח\"א וראה עוד מה שנתבאר בפר' תולדות מאמר ח ומאמר יג ופרשת וישב מאמר ב), וזהו שהמשיך הפסוק (שם), ואמר, למחר יהיה האות הזה, כלומר, שהאות וא\"ו החסרה ב\"פדת\" דיציאת מצרים, תחזור למקומה למחר היינו בגאולה העתידה שאז יהיה \"פדות\" מלא. וכמו שנאמר (תהלים קיא, ט), פדות שלח לעמו צוה לעולם בריתו. [א\"ה - ובספר ובחרת בחיים (סדר בחוקותי), כ' כי נטל יעקב אבינו את האות וי\"ו של אליהו ולקח דוקא אות הזאת כי היא הרומזת לתורה, וכתב שם כי מנין חמשה ווי\"ן הם מנין שלשים, לרמוז על מלכות בית דוד, וידוע כי המלכות נקנית בשלשים מעלות (אבות ו, ו ובפ\"ח דכלה), ובזוהר הק' משפטים (ח\"ב קטו, א), \"הקם\" עם ו' עלאה משיח ראשון, \"תקים\" עם ו' תניינא, \"עמו\", דא בן עמרם וכו'. ע\"כ. יבח\"ר].","b":false},{"t":"והנה האות ו' היא רומזת לתורה וכמו שאמרו בזוה\"ק כמה פעמים (לדוגמא ראה זוהר ח\"ב קיט, ב וראה תיקוני זוהר פב, ב), ועוד אמרו (ראה זוהר ח\"א רמא, ב), דוי\"ו הוא סימנא דחיי, וגם במסכת ב\"ב (יד, א), אמרו שהלוחות ארכן ו' טפחים ורחבן ו' טפחים, וכן ההיקף של הס\"ת הוא ו' טפחים. ע\"ש. נמצא שגם חז\"ל בגמרא רמזו את התורה בוא\"ו. ובתיקונים (תיקון כ\"ה), אמרו ומספרא דוא\"ו ואיהו ס\"ת. וכתב מרן החבי\"ף ז\"ל בספר סימנא דחיי (מערכת הוא\"ו אות ט\"ז), דמהאי טעמא נראה שניתנה תורה בששה בסיון, שהוא רמז לאות וא\"ו בחינת ס\"ת. והנה יעקב הוא בחינת ו' תפארת (ראה זוהר ח\"א קנז, ב). ואית ביעקב וא\"ו (ראה זוהר ח\"ב כו, א ודו\"ק), שהוא בחינת תוה\"ק, שהיא תורת \"אמת\" וכמדתו של יעקב שהיא אמת (מיכה ז, כ), והיא גם חיי עולם, וע\"כ יעקב שהוא בחינת תורה לא נאמרה בו מיתה (כמבואר בתענית ה, ב - ואגב, דע כי בעל המימרא הוא ר\"י שהוא גלגול יעקב אבינו ע\"ה. יבח\"ר), וכיון שיעקב אבינו ענינו עסק התורה שע\"י תבא הגאולה, לכן עליו חיובא רמיא לבא ולגאול.","b":false},{"t":"וכבר כתב רבינו חיים ן' עטאר זיע\"א באוה\"ח הקדוש (ראה שמות כז, כ ובעוד הרבה מקומות), שהגאולה האחרונה תלויה בלימוד התורה הק', כי משה הוא הגואל, ואין משה חפץ לגאול עם בטלנים מתורה. עוד כתב דבר נורא (בפירושו לבראשית מט, יא), שאפילו אם יגיע העת, אם לא יהיה למוד תורה, כי אז תדחה הגאולה עד שילמדו תורה. ואכמ\"ל, ועוד כתב גבי יציאת מצרים שאפילו הגאולה הזמנית שהיא יציאת מצרים שהיתה קודם מתן תורה, אפ\"ה לא יהיה אפשר ליגאל ואפילו זמנית בלא תורה כלל. וע\"כ לפני שיצאו ישראל ממצרים נתן להם הקב\"ה את פרשת קרבן הפסח, כדי שילמדו אותה ועל ידה ינצלו, ויעקב שהוא בחינת תורה מתעסק בזה.","b":false},{"t":"ונלע\"ד דיותר שייך לגאולה תורה שלומדים בארץ ישראל, אשר עיני ה' אלהיך בה (דברים יא, יב), ובה תלוי השלמת ותיקון השם והכסא, שהוא תיקון כל העולמות, וכמו שדרשו דורשי רשומות על הפסוק (תהלים קלב, יג), כי בחר ה' ב\"ציון\" אוה למושב לו, שהמלה \"אוה\", יש בה א' של כסא וגם ו'-ה' של הוי'ה ב\"ה ומשלים הכל, (וראה אדרא זוטא רצו, א ובשל\"ה מס' פסחים מצה עשירה דרוש ב אות כג ובמסכת פסחים דרוש ו' אות כו).","b":false},{"t":"וחשבתי בס\"ד לרמוז את זה בפרטות דברי הפסוק, כי בחר ה' בציון וגו' היינו היכן בחר הי\"ת להשלים את שמו בציון דייקא, ששם מכון כסאו ושם יושלם הכסא.","b":false},{"t":"ואחר אשר הודיענו ה' כל זאת, יתעלה ויתהדר כבוד מלכותו לעד. אוסיף לכתוב מה ששמעתי באומרים לי, כי הענין הזה נרמז בבירור בנוסח התפלה באמת ויציב וכו', דאומרים, הוא קיים וכו'. דתיבת \"הוא\" יש בה השלמת השם והכסא כמו תיבת \"אוה\" הנ\"ל, והיא היא. וזה אומרו, הוא קיים, ושמו קיים, שמשלימים שם הוי'ה ב\"ה, וכסאו נכון, שגם הכסא הושלם, ואחר ששתיהם הושלמו, ומלכותו ואמונתו לעד קיימת. כי מאז אין שום הפסק עוד וגאולת עולם תהיה לנו. [א\"ה - ובשל\"ה הקדוש (תולדות אדם בית ה' בית דוד אות ד'), פירש על דרך זה את מאמה\"כ (זכריה יד, ט), ביום ההוא יהיה ה' למלך וגו', ביום ה\"הוא\" דייקא שהוא אותיות \"אוה\". יבח\"ר].","b":false},{"t":"ועתה עלה בדעתי לשאול בנוסח אמת ויציב למה מקדימים ואומרים אמת אלהי עולם מלכנו צור יעקב מגן ישענו, ורק אח\"כ אומרים לדור ודור הוא קיים וכו'. ועוד למה כל זה נאמר רק אחר ט\"ו ווי'ן דאמת ויציב ונכון וכו'.","b":false},{"t":"ולפי כל האמור נלע\"ד ק'לה כמות שהיא, דהט\"ו ווי\"ן הם מחולקים לשלשה, חמשה ווי\"ן ממה שנחסרו מאליהו, שחמש פעמים כתוב \"אליה\" חסר וא\"ו. וחמשה ווי\"ן כנגד ה' פעמים שכתוב \"יעקוב\" מלא וי\"ו, ועוד חמשה ווי\"ן כנגד ווי העמודים, שכל עמודי הספר תורה מתחילים באות וא\"ו. חוץ מחמשה עמודים שסימנם בי\"ה שמ\"ו כידוע, וכ\"כ רבינו הרמ\"א ז\"ל בהגה לש\"ע יו\"ד (רעג, ו), וכמ\"ש בהקדמה לשו\"ת שמע שלמה ח\"א, שמרן החיד\"א בברכ\"י (שם), כתב בשם ספר הציוני, שהוא סוד גדול לכתוב ווי העמודים ואין לבטל המנהג. ע\"ש. וכן נוהגין בכל המקומות. וכתבתי שם שהם כנגד חמשה ווי\"ן שלקח \"יעקוב\" מאליהו הנביא ז\"ל. וכנגד אלו החמשה ווי\"ן החסרים בראשי עמודי הס\"ת, אנו אומרים עוד חמשה ווי\"ן באמת ויציב, וכל הווי\"ן בכללותן עולין למנין חמשה עשר, שבהם תלויה פדותינו וגאולתינו השלמה בב\"א.","b":false},{"t":"ולכן רק אחר שאנו מזכירים כל זאת אומרים אמת אלהי עולם מלכנו צור יעקב מגן ישענו. לומר, שהגאולה היא בידי הי\"ת אלהי עולם לבדו, והמתעסק בזה מאז הוא יעקב אע\"ה ועל כן הוא נזכר באמת ויציב \"צור יעקב\" מגן ישענו. ואז ממשיכים ואומרים לדור ודור הוא קיים, ואפשר שזה כנגד מה שנאמר (שמות יז, טז), מלחמה לה' בעמלק מדור דור, על כן גם כאן הזכיר ואמר, \"לדור ודור\". ואח\"כ אמר \"הוא\" קיים, לרמוז כי במילת \"הוא\" היינו בזמן הגאולה תהא השלמת השם והכסא יחד.","b":false},{"t":"ואל ה' ויאר לנו באורו הגדול ואליו עינינו צופיות ומייחלות, כי לו משפט הגאולה להשלימה ולגלותה, ותראה ותגלה מלכותו עלינו מהרה לעיני כל חי לאמר, הן גאלתי אתכם אחרית כראשית, בישועה וברחמים, יראו עינינו וישמח לבנו ותגל נפשנו בישועתך מלכנו, להציל נחלתך ועדתך להושיעה ולהרגיעה, בשובה ונחת, את כל ונוכחת, כשמש זורחת, והיא פורחת, כל לב משמחת, שמחנו כימות עניתנו שנות ראינו רעה, יראה אל עבדיך פעלך והדרך על בניהם. במהרה בימינו אמן.","b":false},{"t":"(מתוך הקדמה לספר כרם שלמה ח\"ב)","b":false}]},{"id":"20","t":"אין לצדיק לבקש לו שלוה בעולם הזה","p":[{"t":"וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן: (לז, א)","b":true},{"t":"איתא במדרש רבה (ב\"ר פד, ג), א\"ר אחא, בשעה שהצדיקים יושבים בשלוה, מבקשים לישב בשלוה בעולם הזה, השטן בא ומקטרג, אמר לא דיין שהוא מתוקן להם לעולם הבא אלא שהם מבקשים לישב בשלוה בעולם הזה. תדע לך שהוא כן, יעקב אבינו ע\"י שבקש לישב בשלוה בעוה\"ז, נזדוג לו שטנו של יוסף. וישב יעקב, לא שלותי ולא שקטתי ולא נחתי ויבא רוגז (איוב ג, כו). לא שלותי, מעשיו. ולא שקטתי, מלבן. ולא נחתי, מדינה. ויבא רוגז, בא עלי רוגזו של יוסף. ע\"כ. וברש\"י ז\"ל מובא הענין בסגנון אחר ע\"ש. ועיין עוד בפירושו של הקדוש רבינו משה אלשיך ז\"ל.","b":false},{"t":"ובפשוטו נראה שעצם הביקוש והחיפוש אחר השלוה, והדאגה להבטיח את עניני העולם הזה, גורמים שניתן מקום לשטן לקטרג, כי הצדיק שאוחז בצדקות ה' ובוטח על שמו יתברך בכל עת ובכל מצב, הרי אצלו כמו חטא נחשב לפום מדרגתו, וכמו שמתרפה לרגע מבטחונו, וכעין ההשתדלות דיוסף הצדיק שאמר לשר המשקים (בראשית מ, יד), \"וזכרתני והזכרתני\" והוסיפו לו שנתים ימים בבית הסוהר כידוע (ראה ב\"ר פט, ב-ג). כי היה לו ליוסף לידע כי בכל צרתם לו צר (ישעיה סג, ט), ואליו ישא עיניו ורעיוניו אולי יחוס אולי ירחם. ואינו צריך לשוטט בדעתו אחר מקום מבטחים ומי מנוחות מפני קורות הזמן העלולים להפריע את מנוחתו ולהדריך את שלותו. רק ישליך על ה' יהבו, ויהא לבו שקט ובוטח.","b":false},{"t":"ועוד זאת שיש בזה גם מהרפיון בהתחזקות בעבודת הי\"ת, כי כחות האדם מוגבלים, וכשהוא מכוין את כחותיו להשגת דבר מה, לא יוכל לתת תשומת לב ראויה לענינים אחרים, דאיידי דטריד באותו ענין, אינו פנוי לדבר אחר כפי הראוי. ויותר מזה, כשראשו עסוק בענינים הגשמיים להכינם ולתקנם, בודאי שזה ממעט מהישגיו הרוחניים, וככל שירבה בזה ימעט בזה. וככל שיפנה לבו מעניני העוה\"ז, כן יתפנה לדרוש בעניני הנפש והרוח, ולהגדיל מאמציו בהשגת דעת ה' ודרך אורחותיו.","b":false},{"t":"ורמזתי על זה מה שאומרים בתפלת העמידה \"משיב הרוח ומוריד הגשם\", דמי שרוצה לנשב ברוח, כלומר, לחזק את רוחניותו ולרוממה, צריך תחלה להוריד מהגשמיות, ולהיות נכון לויתורים והקרבות, שזהו, \"ומוריד הגשם\". כי הא בהא תליא. וכבר כתבו התוספות כתובות (קד, א ד\"ה לא נהניתי), דאמרינן במדרש, עד שאדם מתפלל שיכנס תורה לתוך גופו יתפלל שלא יכנסו מעדנים לתוך גופו.","b":false},{"t":"וזהו שאמרו במדרש הנז', בשעה שהצדיקים יושבים בשלוה ומבקשים לישב בשלוה, בא השטן ומקטרג. כי אם האדם נקלע לצרה ח\"ו, ומשתדל לפרוק עצמו ממנה, בודאי שהוא דרך נכון וישר. אבל היושב בשלוה ומבקש לישב עוד בשלוה, להאריך מנוחתו ולהגן עליה מפני כל צרה שלא תבא, זו השתדלות יתירה, וכל יתר כנטול דמי, דממעט מבטחונו בהקב\"ה. וגם יש בו מרפיון העבודה המוטלת עליו ממלכו של עולם ב\"ה. ובא קטרוג חלילה וחס, אלא יתחזק ויקוה לה' ויקוה עוד ולא ירפה.","b":false},{"t":"* * *","b":false},{"t":"עוד נראה בעזר האל וישועתו לפרש בדרך הרמ'ז דהכי קאמר, בקש יעקב לישב בשלוה. בשלוה, בשֶל - ו\"ה, כלומר, שרצה לישב באותיות ו' - ה' משם ההוי\"ה ב\"ה. דהאותיות הראשונות של שם הוי\"ה ב\"ה (הם י' - ה'), והם דרגה גבוהה (או\"א עילאין), והאותיות האחרונות דשם הוי\"ה (ו' - ה'), הם דרגא פחות (זו\"ן). ורבינו האר\"י ז\"ל כתב (ראה בלקוטי תורה לתרי עשר-זכריה), דלעתיד לבא גם הזו\"ן יתעלו למדרגה הגבוהה וגם הם יהיו בבחינת י' - ה', כדכתיב (זכריה יד, ט), ביום ההוא \"יהיה\" ה' אחד ושמו אחד, דאז שמו יתברך יהיה (ב' פעמים י'-ה').","b":false},{"t":"והנה יעקב אבינו ע\"ה היה בבחינת \"סולם מוצב ארצה וראשו מגיע השמימה\" (בראשית כח, יב). דאע\"ג דמוצב ארצה כשאר הברואים, מ\"מ יניקתו מגובהי מרומים. ואפשר דכשחשב על הצרות התוכפות והרודפות, עוד זה מדבר וזה בא רח\"ל, אמר לעצמו דאפשר שגבהות מקור יניקתו, הוא דינא דגרמי לכל הני תלאות, והיינו מבחינת י-ה, ואפשר דזה רמוז בפסוק, כי יעקב בחר לו י-ה (תהלים קלה, ד). וע\"כ ביקש יעקב לישב בשל - ו\"ה שהיא דרגה פחותה מהראשונה, ומשם הוא קיום העולמות, ואולי על ידי זה דינחות דרגא ימצא השקט ובטחה על מי מנוחות.","b":false},{"t":"וכדי לבאר הענין נקדים את דברי חז\"ל (יבמות קכא, ב ב\"ק נ, א ובירושלמי ביצה ג, ח), על הפסוק (תהלים נ, ג), וסביביו נשערה מאד. ואמרו, מכאן שהקב\"ה מדקדק עם חסידיו כחוט השערה. וצריך להבין דאטו משום שחסידים הם, צריך לדקדק עמם עד כדי כך.","b":false},{"t":"ופירשתי את זה בס\"ד עפ\"י דברי מהר\"ח ן' עטאר זלה\"ה וזיע\"א, שכתב בספרו הקדוש אור החיים (בראשית א, א אות ג' ד\"ה גם), בזה\"ל: גם אנחנו נפרש שני מקראות הללו על זה הדרך, בראשית ברא אלהים את השמים, שם זה של אלהים, פי' מדה זו של הדין בלא שיתוף שם של רחמים, זהו דוקא למה שנוגע להשמים, ואינו חוזר לאומרו ואת הארץ. כי הארץ בראה בשיתוף שם של רחמים, ועל כתוב אחר סומך, והוא אמרו (בראשית ב, ד), ביום עשות ה' אלהים ארץ, כי אין עולם בני אדם יכול להתקיים בדין גמור בלא שיתוף רחמים וכו'. והמשיך וכתב, ולא יקשה לך מה משפט יערוך ה' לבני אלים יושבי שמים, הלא תמצא שאמרו (חגיגה טו, א), במעשה מט\"ט, שדנוהו לפני אלישע ומחיוהו שתין פולסין דנורא, וגם אליהו וכו' (ב\"מ פה, ב), וכמה משפטים לשרי מעלה (עי' יומא עז, א). והגם שאין להם יצר, עם כל זה ימצא בהם הטעות. כי לפעמים לא יכונו לאמת וישגו, וצא ולמד מהמעשה המלאך מט\"ט ואליהו כי שגגו, וכן יקר מקרה, ויענישם ה' אפילו על השוגג, מה שאין שופט במשפט זה ליושבי ארץ. ובזה יתאמת מה שפירשנו, ונכון. עכל\"ה.","b":false},{"t":"העולה מדברות קדשו ע\"ה, דבשמים דנים בדין לבני אלים שוכני השמים, ושיתוף הרחמים הוא לשוכני ארץ דייקא, וכדסמיך ארץ לה' אלהים, דכתיב (בראשית ב, ד), ביום עשות ה' אלהים ארץ ושמים.","b":false},{"t":"ובזה אמרתי לרמוז בעזר האל וישועתו, בפסוק לעולם ה' דברך נצב בשמים (תהלים קיט, פט), דעל העולם הזה הגשמי שאינו יכול להתקיים בדין, אמר לעולם ה' בשם הוי\"ה, שהוא מדת רחמים. אבל \"דברך\" שהוא דבור והוא לשון קשה (כדמצינן במכות יא, א דכל דיבור לשון קשה הוא), והוא ממדת הדין, אותו הדבור \"נצב בשמים\", כלומר, נשאר נצב בשמים, כי את יושבי השמים דנים במדת הדין. וכנ\"ל.","b":false},{"t":"ובזה יובן ענין חסידיו שמדקדק עמהם כחוט השערה, דהם בעלי דרגה רוחנית גבוהה ויניקתם והשפעתם משמי מרומים. וכפי המקום שממנו הם יונקים כך היא מדת הדקדוק עמם, ואין זה עונש ח\"ו, אלא כך היא המדה דמי שגדול יותר צריך להזהר יותר וזו המציאות שלהם, דההנהגה האישית חייבת להיות בהתאם למקור השפע שממנו הוא ניזון. וכשם שאי אפשר לתת מנוע של מכונית משא גדולה בלב מכונית קטנה, כן א\"א לקבל שפע גדול כ\"כ בתוך הנהגה קטנה כ\"כ.","b":false},{"t":"ובאמת יש שפחדו מזה וכמו שמצינו שענתה האשה השונמית לאלישע בעת ששאל אותה מה לעשות לך, היש לך לדבר אל המלך או אל שר הצבא. והיא ענתה ואמרה \"בתוך עמי אני יושבת\" (מ\"ב ד, יג). והנה מצינו בזוהר הקדוש בכמה מקומות (בראשית סט, ב ושם קס, ב שמות לג, ב ועי' שם מד, ב ובזו\"ח רות כט, א), שאלישע רצה לדבר על האשה השונמית טובות לפני מלך מלכי המלכים הקב\"ה ישתבח שמו, להיטיב לה. ואמנם האשה השונמית יראה מזה יראה גדולה, וענתה לו בתוך עמי אני יושבת, כי נתיראה שאם יעלו עניניה לגבהים כאלה, תדרש להנהגה גבוהה ומדוקדקת, וינהגו בה במדת הדין, ורצתה שימשיכו לנהוג עמה בהנהגה פשוטה השוה לכל נפש, שיש עמה מדת הרחמים, וזהו, \"בתוך עמי אני יושבת\". כלומר, יניח לי כבודו להשאר בפשיטותי. כי ככל שיגביה אדם במעלותיו כן חייב להרבות בזהירות ובשמירה (וראה מה שנתבאר לעיל פרשת בראשית מאמר ב).","b":false},{"t":"וכשיעקב אבינו ע\"ה ראה והביט איך הוא רדוף מבטן ומלידה ע\"י עשו ולבן, ושנזדמן לו ענינה של דינה וכו', בקש לנחות דרגא מן הבחינה הגבוהה שהיא י' - ה' ולישב בשלוה בשל - ו\"ה. אולי בזה ימצא מנוח ומזור מתלאותיו ומנסיונותיו הרבים.","b":false},{"t":"ואז בא השטן ואמר, לא דיין לצדיקים מה שמתוקן להם לעוה\"ב, שבדרגה גבוהה בונים בשמים עליותיהם, והם דואגים לפכים קטנים מעניני העוה\"ז. ואולי לזה התכונו רבותינו במאמרם בסוף מסכת ברכות (סד, א וכן במו\"ק כט, א), צדיקים אין להם מנוחה לא בעוה\"ז ולא בעוה\"ב, שנאמר (תהלים פד, ח), ילכו מחיל אל חיל יראה אלהים בציון. ובאבות (ד, טו), רבי ינאי אומר אין בידינו לא משלות הרשעים, ואף לא מיסורי הצדיקים. דלרשעים משלם להם באותה שלוה מדומה כדי להאבידם מן הטוב הצפון לחיי העוה\"ב, כמו שנאמר (דברים ז, י), ומשלם לשונאיו אל פניו להאבידו. אבל הצדיקים אין להם חלק בשלוה זו. רק מהלכים ועולים מחיל אל חיל.","b":false}]},{"id":"20","t":"\"ביקש\" יעקב לישב בשלוה","p":[{"t":"וַיֵּשֶׁב יַעֲקֹב בְּאֶרֶץ מְגוּרֵי אָבִיו בְּאֶרֶץ כְּנָעַן: (לז, א)","b":true},{"t":"כתב רש\"י ז\"ל (שם), ועוד נדרש בו, וישב יעקב, ביקש יעקב לישב בשלוה קפץ עליו רוגזו של יוסף, צדיקים מבקשים לישב בשלוה אמר הקב\"ה לא דיין לצדיקים מה שמתוקן להם לעוה\"ב אלא שמבקשים לישב בשלוה בעוה\"ז. ע\"כ. ומקורו טהור בדברי רבותינו בבראשית רבה (פד, ג וכ\"ה בילקו\"ש בראשית רמז קמ). ע\"ש.","b":false},{"t":"והדבר צריך הבנה וכי למה לא יזכו הצדיקים בשלוה גם בעוה\"ז, ויוכלו ללמוד ולעבוד את ה' ביתר עוז וביתר שאת, וכי משום שיש להם עוה\"ב אסור להם להיות שלוים בעוה\"ז.","b":false},{"t":"ואמנם נראה שהטענה בזה היא על \"הבקשה\" שביקש יעקב. צדיקים \"מבקשים\", דהיינו שעבודת ה' ותורתו לא מספקת אותם כביכול, ומבקשים להם עוד דברים כדי לישב בשלוה, אחד חושב שצריך יותר כסף, ואחד חושב שצריך בית יותר מרווח וכו', כל אחד ואחד כפי השגתו, וע\"ז קאמר, לא דיין לצדיקים מה שמתוקן להם לעוה\"ב, כלומר, שע\"י שהצדיקים מבקשים להם ענינים שונים בשביל לישב בשלוה, בזה הם מראים כאילו לא די להם במה שמתוקן להם לעוה\"ב, ושאין זה מספק אותם. ולכן הם מבקשים עוד דברים אחרים כדי למלאת בהם את החסר. וע\"ז מתרעם הקב\"ה עליהם.","b":false},{"t":"והגם שלכל אדם באשר הוא אדם, הרי סוף סוף הוא נברא ונוצר מעפר האדמה, ורבו חסרונותיו וצריך הוא לדברים רבים מהעוה\"ז, אחד המרבה ואחד הממעיט, ואינו יכול לוותר לגמרי על עניני העוה\"ז. אבל כאן הקפידא היתה על \"ביקוש\" דברים שאינם חיוניים ממש, והתביעה היא לפי ערכו ומעלתו של כל אחד ואחד, שככל שתגבה מדריגתו, כך נתבע ממנו להיות יותר קשור עם הקב\"ה ותורתו, ובה ימצא סיפוק ומרגוע לנפשו די והותר. ואם עם כל זאת הריהו מבקש דברים אחרים שיביאו לו את השלוה. סופו שיתבעוהו על זה, שמבקש למצוא שלוה לעצמו בעולם הזה שאינו אלא חיי שעה ודירת עראי, כי אין לצדיק לעסוק כי אם בדברים הנצחיים. כי בקשת השלוה והמנוחה בעניני העוה\"ז, נותנת לאדם הרגשה שכאן הוא מקום קביעותו, והוא עלול להיות פוחת והולך בערך העבודה והיראה ח\"ו, וע\"ז באה הטענה לא דיין לצדיקים וכו'.","b":false},{"t":"וכבר אמרו חז\"ל (ברכות לה, ב), ראשונים שעשו מלאכתן עראי ותורתן קבע זה וזה נתקיימו בידן, אחרונים שעשו תורתן עראי ומלאכתן קבע, זה וזה לא נתקיימו בידן. דאין זה תלוי רק בכמות לימוד התורה או כמות המלאכה, ולא לפי רוב הזמן המושקע בכל אחת מהן, כי אם במה שהאדם שם לעצמו לעיקר. והנה הראשונים שידעו והעריכו יותר את עניני התורה ועבודת ה', ונתברר ונתאמת אצלם חיובם בזה העולם, ממילא, עשו תורתן קבע, ואע\"פ שאפשר שעבדו הרבה לפי צורך המחיה והכלכלה, מ\"מ הקביעות שלהם והשלוה שלהם היתה בתורה, וגם כשעסקו במלאכה היה ניכר עליהם שעושים את זה דרך עראי, ומצפים מתי יגמרו את מלאכתם כדי לחזור ללמוד תורה, שהיא הקבע שלהם, ועל כן זה וזה נתקיימו בידם, דגם המלאכה שלהם לא חלפה מהם כשאר עניני העוה\"ז שהם חולפים עם חלוף הזמן, אלא מלאכה כזו שכל כולה באה לספק את צרכי האדם, בכדי שיוכל להתמסר לתורה, וגם בעת שעוסקים בה לא הופכים אותה לקבע, ולא משקיע בה את ראשו וכל רעיונותיו, (כמו קביעת סעודה), אלא מתעסק בה כמו אנוס עפ\"י ההכרח, ומצפה לגמור את חוקו שהוא חייב בו, ולחזור לחיי הקבע היינו לימוד תורה. והנה מלאכה כזו בכלל עבודת ה' היא, ואינה חולפת, אלא מתקיימת בידו.","b":false},{"t":"והאחרונים עשו מלאכתן קבע, היינו שכשהאדם יוצא למלאכתו או למסחר שלו, כל כולו שקוע בה למעלה ראש ולא נותר ממנו מאומה, והנותר באש תשרופו, כי האש של הדברים הבטלים מקיפה את כל חייו ושורפת לו כל זמן פנוי, ובמלאכתו הוא הוגה כל הזמן גם בעת האכילה והשינה, והיא שיחתו כל הימים. ממילא לימוד התורה הקדושה נהיה לעראי, כי גם כשכבר מוצאים איזה זמן לשבת ללמוד, הרי הוא עוסק בתורה כלאחר יד, בדרך של עראי כמו משאוי שהאדם מחכה מתי יוכל להסירו מעליו. ועל כן לא זה ולא זה מתקיימים בידו. כי המלאכה אינה אלא לשם עצמה, וגם תורתו אינה עשויה כדבעי, ולכן אינם מתקיימים בידו.","b":false},{"t":"וזהו \"מבקשים לישב בשלוה בעוה\"ז\", שאצל הגדולים עצם \"בקשת השלוה\" בדברים אחרים, אם אינו כדי צורך חיותם ממש, הרי שנחשב להם כחסרון, באמור להם לא דיין לצדיקים וכו', אבל מצד האמת ודאי ראויים הם לשלוה ואושר וכל הטוב, ככתוב (משלי ג, טז), אורך ימים בימינה ובשמאלה עושר וכבוד.","b":false},{"t":"[א\"ה – אמרתי לכתוב בכאן את אשר שמעתי תחת הש'יחים ממורי ורבי הרב חק\"ל כמוהר\"ר ששון עבדול עזיז מזרחי זללה\"ה מח\"ס באתי לגני, שאמר לי כי היה חסיד וקדוש עליון ואת שמו לא הגיד משום כבודו, שכשהיה נכנס לביהמ\"ד היה מחפש לו כר כדי לישב בנוח, ואחר שנתבקש בישיבה של מעלה, נתבע על זה בב\"ד של מעלה למה היה הולך לבקש לו כר, ונתגלה בחלום לאחד מחבריו וסיפר לו הענין, ומזה הענין תראה עד כמה הקב\"ה מדקדק עם חסידיו כחוט השערה. יבח\"ר].","b":false}]}]},{"slug":"מקץ","name":"פרשת מקץ","items":[{"id":"21","t":"מהי \"ההשתדלות\" הרצויה להשגת דבר","p":[{"t":"וַיְהִי כַּאֲשֶׁר כִּלּוּ לֶאֱכֹל אֶת הַשֶּׁבֶר אֲשֶׁר הֵבִיאוּ מִמִּצְרָיִם וַיֹּאמֶר אֲלֵיהֶם אֲבִיהֶם שֻׁבוּ שִׁבְרוּ לָנוּ מְעַט אֹכֶל, וַיֹּאמֶר אֵלָיו יְהוּדָה לֵאמֹר הָעֵד הֵעִד בָּנוּ הָאִישׁ לֵאמֹר לֹא תִרְאוּ פָנַי בִּלְתִּי אֲחִיכֶם אִתְּכֶם וגו', וַיֹּאמֶר יְהוּדָה אֶל יִשְׂרָאֵל אָבִיו שִׁלְחָה הַנַּעַר אִתִּי וְנָקוּמָה וְנֵלֵכָה וְנִחְיֶה וְלֹא נָמוּת גַּם אֲנַחְנוּ גַם אַתָּה גַּם טַפֵּנוּ, אָנֹכִי אֶעֶרְבֶנּוּ מִיָּדִי תְּבַקְשֶׁנּוּ אִם לֹא הֲבִיאֹתִיו אֵלֶיךָ וְהִצַּגְתִּיו לְפָנֶיךָ וְחָטָאתִי לְךָ כָּל הַיָּמִים וגו', וַיֹּאמֶר אֲלֵהֶם יִשְׂרָאֵל אֲבִיהֶם אִם כֵּן אֵפוֹא זֹאת עֲשׂוּ קְחוּ מִזִּמְרַת הָאָרֶץ בִּכְלֵיכֶם וְהוֹרִידוּ לָאִישׁ מִנְחָה מְעַט צֳרִי וּמְעַט דְּבַשׁ נְכֹאת וָלֹט בָּטְנִים וּשְׁקֵדִים, וְכֶסֶף מִשְׁנֶה קְחוּ בְיֶדְכֶם וְאֶת הַכֶּסֶף הַמּוּשַׁב בְּפִי אַמְתְּחֹתֵיכֶם תָּשִׁיבוּ בְיֶדְכֶם אוּלַי מִשְׁגֶּה הוּא, וְאֶת אֲחִיכֶם קָחוּ וְקוּמוּ שׁוּבוּ אֶל הָאִישׁ, וְאֵל שַׁדַּי יִתֵּן לָכֶם רַחֲמִים לִפְנֵי הָאִישׁ וְשִׁלַּח לָכֶם אֶת אֲחִיכֶם אַחֵר וְאֶת בִּנְיָמִין וַאֲנִי כַּאֲשֶׁר שָׁכֹלְתִּי שָׁכָלְתִּי: (מג, ב-יד)","b":true},{"t":"הנה יעקב אבינו ע\"ה אוחז בדרכו כמו שנהג עם עשו, והכין דורון, וגם תפלה, רק מלחמה לא היה שייך בזה, כי לא בא השליט לתוקפם כאשר בא עשו וארבע מאות איש עמו (בראשית לב, ו), ובשביל להוציא את שמעון ולהשיב את בנימין היה צריך השתדלות רבה, אבל אין דרך לתקוף את אנשי השלטון בכח כדי לשחרר את אחיהם.","b":false},{"t":"והנה אחר שדחה יעקב בתוקף את דברי ראובן שביקש לקחת את בנימין עמו למצרים ואמר (בראשית מב, לז), את שני בני תמית אם לא אביאנו אליך תנה אתו על ידי ואני אשיבנו אליך. ויעקב השיב לו דברים קשים, ואמר, בכור שוטה הוא זה. הוא אומר להמית בניו וכי בניו הם ולא בני (ב\"ר צא, ט). ואחר שיעקב אבינו ע\"ה פנה בעצמו לבניו ואמר להם, שובו שברו לנו מעט אוכל, ואחר כל המשא ומתן עם יהודה, שבזה השתכנע יעקב שאין עוד מנוס אלא לשלוח את בנימין, וראה את נחרצותו של יהודה וגודל האחריות שלקח על עצמו להציל את בנימין.","b":false},{"t":"מעתה חדל מהתלבטויות ומזרזם ללכת, ויחד עם זה מייעצם לקחת עמם צרי ולוט וכו' כדי לפייס את רוח המושל, וכן לקחת משנה כסף כדי לנקות את עצמם מכל חשד. ומעתה מברכם ומעורר עליהם רחמים שיצליחו בשליחותם.","b":false},{"t":"והנה אע\"פ שעד עתה יעץ להם עצות איך לנהוג עם מושל מצרים, מ\"מ אינו מסתפק בזה, אלא מתפלל עליהם ואומר אל שדי יתן לכם רחמים וגו'. ורש\"י ז\"ל פירש ואל שדי, מי שאמר לעולמו די, הוא יאמר די לצרותי ותצליחו בשליחותכם.","b":false},{"t":"ורצונו לומר, כי כל ההשתדלות שעשינו במנחה ובכסף, אין בה להצילנו אם הי\"ת לא יאמר די לצרותינו, כי הוא המוליך והמביא, וכל השתדלות אפילו הטובה והחשובה ביותר, יכולה להתברר כלא יעילה, ולפעמים גם להשיג את התוצאה ההפוכה. ואשר על כן הגם שחייבים להשתדל, מכל מקום חייבים לידע שלא ההשתדלות היא שמצילה אותנו.","b":false},{"t":"כי פעמים רבות ההשתדלות שעושה האדם להשיג מבוקשו, היא שמרחיקה אותו מלהשיגה, וכן להיפך, וע\"כ חובה לדעת שאין התועלת תלויה בהשתדלות, כי להי\"ת לבדו המלוכה, והוא מנהיג את הכל בהשגחה פרטית וממנו הכל.","b":false},{"t":"ואעפ\"י שחייבים להשתדל, כמו שאמרו (ספרי ראה אות ע), על הפסוק (דברים טו, יח), וברכך ה' בכל אשר תעשה, יכול בטל, תלמוד לומר, בכל אשר תעשה. מ\"מ לא יתלה את הצלחותיו בחריצותו ובהשתדלותו כי לא בכח ולא בחיל כי אם ברוחי אמר ה' (זכריה ד, ו). וראה מה שכתב משה איש האלהים רבינו הרמב\"ן (בראשית לז, טו), כי \"הגזירה אמת והחריצות שקר\".","b":false},{"t":"ואילולי שהאדם בוטח בהי\"ת ויודע שהכל ממנו, הוא עלול להמצא בסכנה עצומה, כי הוא תולה את פרנסתו וכל הצלחתו בכחו ובחכמתו, ויסיר את אמונת הי\"ת מלבו ויחדל מבטוח בו, חלילה וחס. וכבר אמר רבינו הרמח\"ל במסילת ישרים (פכ\"א בדרכי קניית החסידות), שצריך להשתדל ולעשות, אך לא שההשתדלות הוא המועיל, אלא שההשתדלות מוכרח, וכיון שהשתדל הרי יצא ידי חובתו, וכבר יש מקום לברכת שמים שתשרה עליו ואינו צריך לבלות ימיו בחריצות והשתדלות, יעו\"ש, (וראה מה שנתבאר בפרשת נח מאמר טו).","b":false},{"t":"וביארתי בטעם הדבר דההשתדלות הכרחית, דהוא משום שהאדם התקלל מאתו יתברך באמור לו (בראשית ג, יט), בזיעת אפיך תאכל לחם, אבל לא שהזיעה היא המאכילה אותו לחם, אלא הי\"ת הוא שזן ברחמיו את הכל, ולא החריצות מרבה הון, כי אם, ברכת ה' היא תעשיר (משלי י, כב).","b":false}]},{"id":"21","t":"מדוע יעקב סירב בתחילה לשלוח את בנימין עם אחיו למצרים","p":[{"t":"וַיֹּאמֶר אֲלֵהֶם יַעֲקֹב אֲבִיהֶם אֹתִי שִׁכַּלְתֶּם יוֹסֵף אֵינֶנּוּ וְשִׁמְעוֹן אֵינֶנּוּ וְאֶת בִּנְיָמִן תִּקָּחוּ עָלַי הָיוּ כֻלָּנָה, וַיֹּאמֶר רְאוּבֵן אֶל אָבִיו לֵאמֹר אֶת שְׁנֵי בָנַי תָּמִית אִם לֹא אֲבִיאֶנּוּ אֵלֶיךָ תְּנָה אֹתוֹ עַל יָדִי וַאֲנִי אֲשִׁיבֶנּוּ אֵלֶיךָ, וַיֹּאמֶר לֹא יֵרֵד בְּנִי עִמָּכֶם כִּי אָחִיו מֵת וְהוּא לְבַדּוֹ נִשְׁאָר וּקְרָאָהוּ אָסוֹן בַּדֶּרֶךְ אֲשֶׁר תֵּלְכוּ בָהּ וְהוֹרַדְתֶּם אֶת שֵׂיבָתִי בְּיָגוֹן שְׁאוֹלָה: (מב, לו-לח)","b":true},{"t":"וצריך להבין איך מעכב יעקב אבינו ע\"ה את בניו, מפני פחדו על בנימין, ולא חשש לשמעון שהוא אסור בפועל ונתון בסכנה בכל העת ההיא, והא קיימא לן (פסחים ט, א וש\"נ), דאין ספק מוציא מידי ודאי. ובבית יוסף חו\"מ סי' תכ\"ו כתב בשם ירושלמי דאדם מחוייב להכניס עצמו בספק סכנה כדי להציל את חבירו מסכנה ודאית. ע\"ש.","b":false},{"t":"ובתשובה שכתבתי בענין זה והיא נדפס'ה בשו\"ת שמע שלמה ח\"ה (חחו\"מ סי' ז), הארכתי להוכיח שגם תלמודא דידן הכי ס\"ל, דתנן בסנהדרין (עג, א), ואלו הן שמצילין אותם בנפשם, הרודף אחר חברו להורגו. וכן בברייתא שם, מנין לרואה את חברו שהוא טובע בנהר, או חיה גוררתו, או לסטים באים עליו, שהוא חייב להצילו. ת\"ל לא תעמוד על דם רעך. והרי בכל אלו, כשבא להציל את חברו מיד הרודפו, או מן החיה רעה או מן הנהר או מן הלסטים, בכל אלו המציל ג\"כ מכניס עצמו לידי סכנה כיון שהרודף יכול לפגוע בו עצמו, וכן החיה, וכן יכול לטבוע גם הוא, כמו שכן אירע כמה פעמים, ועם כל זה חייבוהו להציל. כי סכנת חברו היא סכנה ודאית, ואילו סכנת המציל היא ספק סכנה, ע\"ש שהארכתי בזה, והוכחתי שכן הוא דעת הרמב\"ם ושכן פסק מרן ז\"ל בשו\"ע, ודלא כמו שכתבו כמה מן המחברים שהרמב\"ם חולק על דברי הירושלמי הנ\"ל, עש\"ב.","b":false},{"t":"וראיתי למרן האוה\"ח הקדוש זיע\"א שעמד על זה בפירושו לפסוק כי אחיו מת (בראשית מב, לח), וזה לשונו, כי בא הכתוב לתת טעם איך הוא חש על ספקו של בנימין מודאו של שמעון האסור במשמר מצרים בערבון, וכשלא יביאו בנימין הנה הוא מחוייב מות, לזה אמר, כי לזה יש להקפיד כי אחיו מת מה שלא אירע כן לאחד משאר אחים, ועוד אין חסרונו כחסרון שמעון, כי הוא לבדו נשאר יחיד לאמו מה שאין כן שמעון כי חמשה אחים יש לו, ועוד ספק זה ספק מוכרע הוא, והוא אומרו וקראהו אסון ולא אמר אם יקראהו אסון וגו' ודקדק לומר בדרך אשר תלכו בה, רמז כי יוסף אחיו הלך בדרך שהם רגילים ללכת בה בתמידות מחברון לשכם, ואף על פי כן טרוף טורף, וכמו כן זה יש לחוש לו לאסון אפילו בדרך אשר אתם הולכים בו בתמידות בלא שום חשש. עכ\"ל.","b":false},{"t":"ואפשר לפרש עוד דיעקב אבינו ע\"ה כבר השיב על חשש זה באומרו אליהם, אותי שיכלתם יוסף איננו ושמעון איננו, ואת בנימין תקחו וגו'. כלומר, יוסף ושמעון כבר אינם אתנו, והשוה את שניהם יחד, דגם שמעון כבר נתון בתפיסה ומי יודע אם יוכלו להשיבו, ואת בנימין תקחו, כלומר ואתם עוד אומרים לקחת גם את בנימין להוסיפו על השנים, דאין כאן ענין של הצלת שמעון ע\"י ספק סכנה של בנימין, אלא מוסיפים עוד סכנה ודאית של בנימין שגם הוא יהיה נתון בידם, בשביל ספק הצלה של שמעון, דמי יערוב לנו שישחרר מושל מצרים את שמעון. כי הרי עיניכם הרואות שכל מעצר שמעון נעשה שלא כדין כלל. ועוד, שהרי המושל ההוא חושד אותכם למרגלים שהיא אשמה חמורה ביותר, ומי יודע מה יעשה עוד, ואיך נוכל לסמוך על אמרתו ונוסיף גם את בנימין אל תוך סכנה זו. ובזה מיושבת הקושיא.","b":false},{"t":"וזה מה שאמר יעקב, יוסף \"איננו\", ושמעון \"איננו\", דתיבת \"איננו\" משמעה שלילה מוחלטת. וכמ\"ש הרב אוה\"ח הקדוש גבי בן סורר ומורה שנאמר בו (דברים כא, יח), איננו שומע. והיינו ששמעון כבר חשוב כמי שאינו ולכן אין להכניס לסכנה את בנימין.","b":false},{"t":"ועוד אפשר לומר, דבני יעקב טענו לו שיתן עמהם את בנימין כי המושל אמר להם שיביאו את אחיהם עמהם, ואז ידע כי כנים דבריהם, ויתן להם לסחור כאות נפשם. אבל יעקב השיבם, שאין דבר זה נכון. כי כיון שהשליט חושד בהם שהם מרגלים, א\"כ במה יוסר החשד הזה ע\"י שיביאו את בנימין והרי אותו חשד ישאר, משום שיוסף איננו. ועל כן אמר יוסף שאין לסמוך על השליט. ואין ליקח את בנימין עמהם.","b":false}]},{"id":"21","t":"היצה\"ר מונע מן האדם להכיר בחטאו הכרה גמורה","p":[{"t":"וַיֹּאמְרוּ אִישׁ אֶל אָחִיו אֲבָל אֲשֵׁמִים אֲנַחְנוּ עַל אָחִינוּ אֲשֶׁר רָאִינוּ צָרַת נַפְשׁוֹ בְּהִתְחַנֲנוֹ אֵלֵינוּ וְלֹא שָׁמָעְנוּ עַל כֵּן בָּאָה אֵלֵינוּ הַצָּרָה הַזֹּאת, וַיַּעַן רְאוּבֵן אֹתָם לֵאמֹר הֲלוֹא אָמַרְתִּי אֲלֵיכֶם לֵאמֹר אַל תֶּחֶטְאוּ בַיֶּלֶד וְלֹא שְׁמַעְתֶּם וְגַם דָּמוֹ הִנֵּה נִדְרָשׁ: (מב, כא-כב)","b":true},{"t":"כשאנו מתבוננים בדברי האחים אנו רואים כמה דברים. הראשון הצדקת הדין. כי הנה בתחילה בעת שמכרו השבטים את יוסף לא חששו לעשות מעשה ולמכור את אחיהם, ולא חשו לקמחייהו, אולי דנו אותו מתוך נגיעה, שהיו פגועים ממנו מאד, בחושבם שהוא מלשין עליהם, וגם שהיו מקנאים בו על אהבת אביהם אליו, ונוסף על זה החלומות שחלם עליהם, כי הם חשבו שהיה רוצה לרדות בהם. ולכן ביקשו לדון אותו בחמורה שבחמורות. אבל מכל מקום בבא עליהם הצרה מיד הצדיקו עליהם את הדין, ואמרו \"אבל אשמים אנחנו\".","b":false},{"t":"אמנם יש לשים לב לכך שלא התחרטו השבטים על עצם המכירה אשר מכרו את יוסף ככלי אשר אין חפץ בו, אלא התחרטו על כך שלא שעו לתחינותיו. וכבר עמד על זה הרמב\"ן ז\"ל שכתב, חשבו להם האכזריות לעונש גדול, יותר מן המכירה, כי היה אחיהם בשרם, מתחנן ומתנפל לפניהם ולא ירחמו, ע\"ש (ועי' חידוש גדול בדברי רבינו בחיי שם שכ' כי לא מכרו האחים את יוסף, ועל כן לא התחרטו רק על מה שלא שמעו לקול תחנוניו, ע\"ש).","b":false},{"t":"גם הספורנו כתב, וז\"ל, בהתחננו אלינו ולא שמענו. והיינו אכזרים נגד אחינו, ואע\"פ שחשבנוהו לרודף, היה לנו לרחם בהתחננו. וכנגד מדת אכזריותינו זה האיש מתאכזר נגדנו. עכ\"ל.","b":false},{"t":"וראיתי בספר עניני הסדרה שכתב תוך דבריו, ומ\"מ לא שבו מדעתם הקודמת להחשיב את עיקר המכירה לחטא, אלא רק את אכזריותם לנגדו, שלא הטו אזן לתחנוניו, את זה חשבו לחטא, לצדיקים כמוהם. אמנם ראובן השיב להם, הלוא אמרתי אליכם לאמר אל תחטאו בילד ולא שמעתם וגם דמו הנה נדרש, והיינו, שכונתו היתה לומר להם, לא רק על עצם אי שמיעת התחנונים ראוי לכם להתחרט, אלא גם על עיקר המכירה ראוי לכם להתחרט כי חטאתם בה. לפי שגם אם יוסף היה חוטא נגדיכם אין לכם רשות לדונו, כי בעת ההיא יוסף היה ילד, ואין דנין את הקטן, כי אינו בר עונשין, לפי שקודם מתן תורה אין אדם נחשב בר עונשים, אלא מגיל עשרים שנה ומעלה (וראה שבת פט, ב), ויוסף היה אז בן י\"ז שנה, וחשוב ילד וקטן, ולכך אמר ראובן \"וגם דמו הנה נדרש\", שלבד מן האכזריות גם עצם דמו נדרש. ואחיו שתקו והיתה שתיקתם להודאה. ועל כן כשראה יוסף שהודו האחים לראובן שחטאו נגד יוסף והם שבים בתשובה, על כן תיכף ויסב מעליהם ויבך וכו' (בראשית מב, כד). עכ\"ל.","b":false},{"t":"והנה לימוד גדול יש בזה בתחבולות היצר הרע, כי בראשונה הוא מונע מן האדם את האמת, ומוליכו בכחש ובכזב, וגם כשמתעורר האדם בלבו להכיר את האמת ולהודות בה, שהוא יסוד התשובה, כדכתיב (משלי כח, יג), ומודה ועוזב ירוחם. אז בא היצה\"ר ועושה לו כעין פלגינן דבורא, ואומר אולי הפרזתי במעשי, או שהוספתי יותר ממה שהיה ראוי לי לעשות. אבל בעצם הענין האדם ממשיך להצדיק את עצמו בעקשנות, ולהתפס במעשהו. וע\"ז כתב הרב ז\"ל שראובן הוכיח את אחיו בתוכחת מגולה. והם קבלו ממנו את הענין, כי קשה לאדם להודות באמת, ולהאשים עצמו. וגם כשהוא נאלץ להודות עדיין הוא מתעקש להצדיק את מעשיו למחצה לשליש ולרביע.","b":false},{"t":"ולואי ונלמד מזה לאהוב את האמת ולהחשיבו גם כשהדבר מטיל בנו בעצמנו אשם, ולא בכדי מתחנן משיח ה' דוד המלך ע\"ה באומרו (תהלים פו, יא), הורני ה' דרכך אהלך באמיתך. כי בלי סיועו של הקב\"ה, בלתי אפשרי להגיע לאמת ממש.","b":false}]},{"id":"21","t":"המבחן שעשה יוסף לאחיו לראות אם שבו בתשובה על מכירתו","p":[{"t":"וַיַּכֵּר יוֹסֵף אֶת אֶחָיו וְהֵם לֹא הִכִּרֻהוּ: (מב, ח)","b":true},{"t":"וכתב רש\"י זל בשם מדרש אגדה (הוא בב\"ר צא, ז), ויכר יוסף את אחיו, כשנמסרו בידו הכיר שהם אחיו וריחם עליהם. והם לא הכירוהו כשנפל בידם לנהוג בו אחוה, ע\"כ.","b":false},{"t":"ולא זו בלבד שלא השיב יוסף לאחיו כמדתם, אלא הגדיל חסדו, והשיב להם טובה תחת רעתם, וכלכל אותם בעת הרעב, והשיב את נפשם ונפש בני ביתם באהבה ובכבוד.","b":false},{"t":"וזאת היתה לו ביודעו שמאת הי\"ת היתה זאת להורידו מצרימה, ירידה לצורך עליה עד עלותו על כס המלוכה להחיות עם רב, ולקיים את כל חלומותיו שחלם להם, וכפי שאמר להם (בראשית נ, כ), \"אתם חשבתם עלי רעה ואלהים חשבה לטובה\".","b":false},{"t":"אלא שעדיין נשארו כמה דברים שצריכים בירור בהתנהגותו של יוסף כלפי אחיו מהרגע בו הכירם ועד שהתוודע אליהם.","b":false},{"t":"שהרי מיד כשהכירם החליט להתנכר להם, וכמ\"ש הכתוב (בראשית מב, ז-ט), \"וירא יוסף את אחיו ויכירם ויתנכר אליהם וידבר אתם קשות ויאמר אליהם מאין באתם וגו' ויאמר אלהם מרגלים אתם לראות את ערות הארץ באתם\". ויש להבין מה ראה על זה להתנכר אליהם ולצערם בצער גדול כזה לומר להם מרגלים אתם. ועוד הגדיל הצער בעת שדרש מהם שיביאו אתם את בנימין, וכפי שאמר להם חי פרעה אם תצאו מזה כי אם בבא אחיכם הקטן הנה (שם שם, טו), ואח\"כ אספם למשמר שלשת ימים ואחר ששחררם החזיק את שמעון במשמר, ושוב חזר ואמר להם (שם שם, כ), ואת אחיכם הקטן תביאו אלי ויאמנו דבריכם ולא תמותו וכו', ועוד כהנה רבות כמפורט בפסוקים שם.","b":false},{"t":"והאחרון הגדיל הוא הצער של אביו יעקב, שבודאי היה יודע יוסף היטב את גודל צערו ואבלו עליו, וא\"כ איך דורש יוסף מאחיו שיביאו לפניו את בנימין, וכפי שתיאר זאת יהודה באמרו (בראשית מד, כ-כט), ונאמר אל אדני יש לנו אב זקן וילד זקונים קטן ואחיו מת ויותר הוא לבדו לאמו ואביו אהבו, ותאמר אל עבדיך הורידהו אלי ואשימה עיני עליו, ונאמר אל אדני לא יוכל הנער לעזוב את אביו ועזב את אביו ומת, ותאמר אל עבדיך אם לא ירד אחיכם הקטן אתכם לא תוסיפון לראות פני, ויהי כי עלינו אל עבדך אבי ונגד לו את דברי אדני, ויאמר אבינו שבו שברו לנו מעט אכל, ונאמר לא נוכל לרדת אם יש אחינו הקטן אתנו וירדנו כי לא נוכל לראות פני האיש ואחינו הקטן איננו אתנו, ויאמר עבדך אבי אלינו אתם ידעתם כי שנים ילדה לי אשתי, ויצא האחד מאתי ואומר אך טרוף טורף ולא ראיתיו עד הנה, ולקחתם גם את זה מעם פני וקרהו אסון והורדתם את שיבתי ברעה שאולה וגו'.","b":false},{"t":"והנה במקום שיוסף יקצר את צערו של אביו וימהר להתגלות אליו לאמר לו \"עוד יוסף חי\", הנה הוא מאריך טרח'א, ומכביד את צערו יותר ע\"י מאסרו של שמעון ולקיחת בנימין. וכפי שאמר יעקב אבינו ע\"ה לבניו \"אותי שיכלתם יוסף איננו ושמעון איננו ואת בנימין תקחו עלי היו כולנה\" (שם מב, לו).","b":false},{"t":"ועוד דגם אחר שהתוודע יוסף לאחיו, ראינו שהתיחס לבנימין ביחס מיוחד ונפלא משאר אחיו, ואף כששלח אותם לאביהם נאמר (שם מה, כב), לכולם נתן לאיש חליפות שמלות ולבנימין נתן שלש מאות כסף וחמש חליפת שמלות.","b":false},{"t":"והוא פלא דהנה יודע היה יוסף היטב מה סבל על כתונת אחת של פסים שעשה לו אביו ומה הגיע אליו, ואיך עתה חוזר על אותו ענין ביתר עוז וביתר שאת, כשלכולם נותן רק חליפה אחת לאדם ואילו לאחיו בנימין נתן חמש חליפות חמש, ועוד שלש מאות כסף, ואחר כל זאת אומר להם (שם מה, כד), אל תרגזו בדרך.","b":false},{"t":"והנראה בזה בס\"ד, דיוסף ידע שחזרתו לאחיו ובית אביו תעורר התרגשות גדולה, העלולה להביא גם למחלוקת ומריבות והאשמות הדדיות, כי הנה בא ההרוג ברגליו ועוד יוסף חי. ואילו האחים הטעו את אביהם במשך כ\"ב שנה לאמר לו (בראשית לז, כ), חיה רעה אכלתהו, ומטבע הדברים כ\"א ינסה לנער את עצמו ולתלות בחבירו, דבר העלול לגרום למחלוקת קשה, אשר אחריתה מי ישורנו.","b":false},{"t":"וע\"כ נהג יוסף במתינות והתאפקות גדולה, וכמה פעמים בעת שהמו רחמיו לאחיו ורבו געגועיו ורחמיו עליהם, היה יוצא חוצה ובוכה, וחוזר ומתאפק, כדי לנהל את הענין בחכמה ובתבונה.","b":false},{"t":"וראש דבר רצה לברר מה מצבם של האחים לעת עתה, אם חישבו דרכיהם במשך השנים הללו, ואם פשפשו במעשיהם כראוי, ואם תקנו את מדותיהם הרעות שהביאום לידי מעשה למכור את אחיהם. ועל כן החליט תחילה להביאם במבוכה בהאשימו אותם באשמה חמורה לאמר להם \"מרגלים אתם\".","b":false},{"t":"ואולם אחרי זה שמע אותם אומרים איש לאחיו (בראשית מב, כא), \"אבל אשמים אנחנו\", דבר שהראה על הודאתם בחטא ועל החרטה הגדולה שהם מתחרטים. והיה עוונם לנגדם תמיד, עד שבבא עליהם צרה לא תלו את זה במקרה אלא מיד תלו את זה בעוון מכירת אחיהם יוסף.","b":false},{"t":"ואח\"כ הוסיף יוסף דרישה שיביאו את אחיהם הקטן אליו, כדי שיוכל לעמוד על יחסם לאביהם ודאגתם הגדולה לגורל אחיהם, עד שיהיו מוכנים למסור את נפשם עליו, והם עמדו גם במבחן הזה עד שהיו מוכנים להיות כולם עבדים נרצעים יחד עם בנימין כדי שלא ישאר לבדו, ואח\"כ כשראו שבעלילה המושל בא עליהם, הכינו עצמם למלחמה, וגזרו אומר למסור את נפשם, ובלבד שישחררו את בנימין. כמבואר כל זה בפסוקי התורה ובדברי רבותינו במדרשים.","b":false},{"t":"והנה ידועים דברי רבותינו מהי התשובה המושלמת וכתבם רבנו הרמב\"ם עלי גליון ספרו הי\"ד החזקה, (פ\"ב מהל' תשובה הלכה א), אי זו היא תשובה גמורה, זה שבא לידו דבר שעבר בו ואפשר בידו לעשותו ופירש ולא עשה מפני התשובה, לא מיראה, ולא מכשלון כח וכו', עכ\"ל.","b":false},{"t":"וזה שנקרא בפי בעלי המוסר תשובת המשקל, והוא הדבר שביקש יוסף הצדיק לבחון בו את אחיו, כי גם אחר שראה את צערם הגדול על מכירתו והחרטה הגדולה שנתחרטו, בכ\"ז היה חושש שמא בשעת מעשה ונסיון אחר שעלול לבא לידם, לא יעמדו בנסיון וימשיכו בדרכם ויפוק מנייהו חורבא ח\"ו, וע\"כ דרש מהם במפגיע להביא את בנימין, ואפי' שהדבר היה כרוך בצערו הגדול של אביו יעקב אבינו ע\"ה, מ\"מ המבחן הזה היה חשוב בעיניו עד מאד, עד שאמר להם יוסף לא תוסיפו לראות את פני אם אין אחיכם הקטן אתכם.","b":false},{"t":"וזו גם הסיבה שאחר שבא אצלו בנימין העדיפו ביחס טוב, ובמתנות גדולות, ובקירבה יתירה שיש בה כדי לעורר קנאה מאחיו, וברור שהיה הדבר בכוונה תחילה, כי יוסף אחר שראה את כל מה שעבר עליו בעבור כתונת פסים ששוויה שני סלעים מילת, היה נזהר מאד שלא להעדיף אח על משנהו. אבל כאן נאלץ לעשות כן כדי להעמיד את אחיו בכור המבחן, ולראות ולבחון עד היכן הגיעה מדת תשובתם.","b":false},{"t":"ולכן תיכף בהגיע בנימין עם אחיו שם עליו את עינו לטובה וישנהו לטוב ולשבח מכל אחיו, וישא משאות אליהם והרבה במשאת בנימין חמש ידות ממשאות כולם (בראשית מג, לד). ובין כך ובין כך ציוה שישימו את גביעו באמתחת בנימין דוקא, ומיד שלח אחר האחים על מנת לראות ולבדוק כיצד מתנהלים הענינים ביניהם, וכמובן ציוה לשליחיו שישימו לבם לראות ולהשגיח אם כל האחים נוהגים כאיש אחד בלב אחד. וגם בזה עמדו האחים במבחן. ולא זו אף זו, אלא גם כשחיפשו באמתחותיהם ונמצא הגביע באמתחת בנימין ודרש מהם יוסף לקחתו לעבד, לא נמצא אף אחד מן האחים שהיה מוכן לוותר עליו ח\"ו. אלא כולם ניצבו כמו נד מסביבו והיו מוכנים להיות עבדים במקומו, ומשלא התקבלה הצעתם היו מוכנים גם להלחם ולמסור נפשם כדי להצילו, ובזה נתגלתה האמת בבירור, שאם היה לשום אחד מהם איזו קנאה ושנאה עליו, אז לפחות כשנתפס והגביע באמתחתו, היה טוען אותו אח מה לנו להלחם עבורו, והוא אשם במצבו, וכדו' טענות שונות, כדי להוציא ולפטור עצמם מאחריות. אך כאמור היו כולם מאוחדים למסור נפשם על הצלת בנימין.","b":false},{"t":"ומשראה יוסף עד היכן מגיעים הדברים, מעתה לא היתה שום מניעה מלהתגלות, ולבו בטוח וסמוך שאפשר שוב להיות עם אחיו יחד ללא שום חששות ובלי פחדים. כי שבו לגמרי מקנאתם ומדותיהם הלא טובות שהיו בהם, ובאו לחשוב חשבונו של עולם דרך כלל ופרט, עד שתיקנו כל מדותיהם וביערו כל שאור מקרבם, וחזרו בתשובה אמיתית, אז אמר להם יוסף (בראשית מה, ד), \"אני יוסף אחיכם\".","b":false}]},{"id":"21","t":"בענין עיבור נשמות השבטים בנשמות המרגלים","p":[{"t":"וַיַּכֵּר יוֹסֵף אֶת אֶחָיו וְהֵם לֹא הִכִּרֻהוּ, וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם לָהֶם וַיֹּאמֶר אֲלֵהֶם מְרַגְּלִים אַתֶּם לִרְאוֹת אֶת עֶרְוַת הָאָרֶץ בָּאתֶם: (מב, ח-ט)","b":true},{"t":"הרמב\"ן ז\"ל הקשה וז\"ל, ויאמר אליהם מרגלים אתם - העלילה הזאת יצטרך להיות בה טעם או אמתלא, כי מה עשו להיות אומר להם ככה, וכל הארץ באו אליו, והם בתוך הבאים, כמו שאמר לשבור בתוך הבאים כי היה הרעב בארץ כנען. ע\"ש מה שתירץ, וראה עוד בדברי רבנו בעל אוה\"ח הקדוש שם.","b":false},{"t":"ונראה לתת בזה טעם על פי מה שכ' מרן החיד\"א ז\"ל כתב בספר נחל קדומים (סדר שלח לך אות א), בשם האר\"י ז\"ל, שבשעה ששלח משה רבינו ע\"ה את המרגלים לרגל את הארץ, ידע שיעמדו בפני נסיונות קשים וחזקים ולכן עיבר את נשמותיהם מנשמות השבטים עצמם (וע\"ש מה שאכתוב בזה בס\"ד), יעו\"ש.","b":false},{"t":"ואשר על כן אמר להם יוסף מרגלים אתם. לרמוז להם שנשמותיהם עתידים להתלוות עם המרגלים, לנחותם הדרך אשר בה ישכון אור, שלא יכשלו בשליחותם, ויוכלו לעמוד בכבוד בנסיון הקשה שעמד לפניהם, ושוב ראיתי שכן הוא בשער הגלגולים (הקדמה לו), יעו\"ש. ואשר ע\"כ נאמר בפרשת המרגלים (במדבר יג, ג), כולם אנשים ראשי בני ישראל המה, שלא רק הנשיאים היו באותה שליחות, כי אם גם ראשי בני ישראל הן המה השבטים שבטי יה, הם עצמם היו מעוברים בנשמותיהם של הנשיאים, להיות להם לאחיעזר ואחיסמך לקיים את שליחותם כדת, אשר בה יבואו לתכלית הנכספת בבא עם ישראל הנבחר מכל עם ולשון, כי יעקב בחר לו יה, לארץ הנבחרת ראש לכל הארצות, כי בחר ה' בציון אוה למושב לו וזה שרמז להם יוסף בפגישתו עמם.","b":false},{"t":"ובאמת ששוב ראיתי בזה דברים נפלאים בספה\"ק שער הפסוקים סדר (שלח לך), וז\"ל תוך דבריו, והנה בלכתם לתור את הארץ, לקחו עצה רעה בעצמם, להוציא דיבה על הארץ, ולכך נסתלקו מהם נשמות של השבטים המתעברות מהם. כנודע, כי הנשמה המתחברת בגלגול עם האדם, אינה מסתלקת משם עד יום המיתה. אבל הנכנסת בסוד עיבור, מסתלקת ממנו, כאשר האדם חוטא, ואומרת (במדבר טז, כו), סורו נא מעל אהלי האנשים הרשעים האלה. ולא די בזה, אלא אפילו נשמת האדם עצמו, מסתלקת בעת שחוטא, בסוד הרשעים בחייהם קרויים מתים, ולכן נסתלקו מהם.","b":false},{"t":"וזה סוד וילכו ויבאו אל משה ואל אהרן (במדבר יג, כו), וכבר אמר וישובו מתור הארץ (שם שם, כה), אם כן איך חוזר להזכיר ההליכה, אחר ששבו, והיה לו לומר ויבאו אל משה. אבל הענין הוא, כי \"וילכו\" חוזר אל הסתלקות הנשמות ההם. ומלת \"ויבאו\", חוזר אל המרגלים עצמם, כי כשבאו אל משה, כבר נסתלקו מהם עיבור הנשמות ההם. אמנם יהושע וכלב, חיו מן האנשים ההם (במדבר יד, לח). והנה מילת \"חיו\" אינה מתיישבת, והענין הוא, כי אלו השנים לא נסתלקו מהם העיבורים שלהם, שהם, יהודה בכלב, ולוי ביהושע. והיה בהם חיות נוסף בעת ההיא, וזה שאמר \"חיו\", ולא אמר נשארו חיים. אבל השאר מתו תיכף בביאתם אל משה, בהסתלקות העיבורים מהם, בסוד הרשעים בחייהם קרויים מתים. ובזה יתורץ אומרו, מן האנשים ההם, שהם דברים מיותרים. אבל רמז אל הנזכר, כי אלו נסתלקו עיבוריהם, ואלו נשארו בהם, וחיו ממש.","b":false},{"t":"גם זהו ענין אומרו (במדבר יד, כד), ועבדי כלב עקב היתה רוח אחרת עמו. פירוש, כי שאר המרגלים, היתה רוח אחרת של השבטים מתעברים בהם. אבל לא מלאו אחרי, ונסתלקו. אבל זה, מתחלה היתה רוח אחרת של עיבור יהודה עמו, ולא חטא, ולכן וימלא אחרי, והשלים באחרונה כבראשונה.","b":false},{"t":"והטעם לאלו השנים היה, כי ליהושע הועילה תפילת משה, וקריאתו שם הזה בקבע, לא ינתק ממנו. ולכלב הועילה תפילה, שנשתטח על קברי האבות בחברון, ולא חטא במחשבה רעה וכו'. עכ\"ל. ויעו\"ש עוד דברים נפלאים.","b":false}]},{"id":"21","t":"בחובת האדם להיות צנוע","p":[{"t":"וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ: (מב, א)","b":true},{"t":"כתב רש\"י ז\"ל, למה תתראו - למה תראו עצמכם בפני בני ישמעאל ובני עשו, כאילו אתם שבעים, כי באותה שעה עדיין היתה להם תבואה. ע\"ש. והוא מדברי רבותינו במסכת תענית (י, ב), ויאמר יעקב לבניו למה תתראו, אמר להם יעקב לבניו אל תראו עצמכם כשאתם שבעין לא בפני עשו ולא בפני ישמעאל כדי שלא יתקנאו בכם. וראה עוד מה שכתבו בזה מפרשי התורה (שם), הלא המה, הראב\"ע, והרמב\"ן, והרשב\"ם, ורבינו עובדיה ספורנו ז\"ל.","b":false},{"t":"והנה יעקב אבינו ע\"ה מלמד בזה את בניו לדורות עולם, שלא יתראו בפני הגוים, כשהם שבֵעים, ואעפ\"י שלפעמים טוען האדם, למה אשקר ואראה את עצמי כעני ונזקק. מ\"מ תתן אמת ליעקב, ויעקב אבינו למדנו שזו הדרך האמיתית לנהוג כן שלא להראות את עצמו בפני אחרים ובפרט בשנת בצורת, והיא מחכמת החיים, שלא לבלוט בין בני אדם, ולא להבליט מעלותיך וסגולותיך, אלא הוי צניע ומעלי.","b":false},{"t":"וכבר שאל אלכסנדר מוקדון את זקני הנגב (ראה תמיד לב, א), מה יעביד איניש ויחיה, אמרו ליה ימית עצמו. ועוד שאל מה יעביד איניש וימות, אמרו לו יחיה את עצמו. ופירש רש\"י ז\"ל, יחיה את עצמו, יגביה את עצמו ומתוך כך יתנו בו הבריות עין רעה ויקנאו בו וימות. ולימדוך חכמים שאדם הרוצה שיחיה ישפיל את עצמו וירחמו עליו הבריות ויחיה שנים הרבה, ומגאוה ימנע את עצמו שלא יקצרו ימיו וימות בלא עתו. ע\"כ. ולשון חכמים מרפא.","b":false}]},{"id":"21","t":"מה טעם התנכרות יוסף לאחיו והנהגתו הקשה עמהם","p":[{"t":"וַיַּרְא יוֹסֵף אֶת אֶחָיו וַיַּכִּרֵם וַיִּתְנַכֵּר אֲלֵיהֶם וַיְדַבֵּר אִתָּם קָשׁוֹת וַיֹּאמֶר אֲלֵהֶם מֵאַיִן בָּאתֶם וַיֹּאמְרוּ מֵאֶרֶץ כְּנַעַן לִשְׁבָּר אֹכֶל, וַיַּכֵּר יוֹסֵף אֶת אֶחָיו וְהֵם לֹא הִכִּרֻהוּ, וַיִּזְכֹּר יוֹסֵף אֵת הַחֲלֹמוֹת אֲשֶׁר חָלַם לָהֶם וַיֹּאמֶר אֲלֵהֶם מְרַגְּלִים אַתֶּם לִרְאוֹת אֶת עֶרְוַת הָאָרֶץ בָּאתֶם, וַיֹּאמְרוּ אֵלָיו לֹא אֲדֹנִי וַעֲבָדֶיךָ בָּאוּ לִשְׁבָּר אֹכֶל, כֻּלָּנוּ בְּנֵי אִישׁ אֶחָד נָחְנוּ כֵּנִים אֲנַחְנוּ לֹא הָיוּ עֲבָדֶיךָ מְרַגְּלִים, וַיֹּאמֶר אֲלֵהֶם לֹא כִּי עֶרְוַת הָאָרֶץ בָּאתֶם לִרְאוֹת, וַיֹּאמְרוּ שְׁנֵים עָשָׂר עֲבָדֶיךָ אַחִים אֲנַחְנוּ בְּנֵי אִישׁ אֶחָד בְּאֶרֶץ כְּנָעַן וְהִנֵּה הַקָּטֹן אֶת אָבִינוּ הַיּוֹם וְהָאֶחָד אֵינֶנּוּ, וַיֹּאמֶר אֲלֵהֶם יוֹסֵף הוּא אֲשֶׁר דִּבַּרְתִּי אֲלֵכֶם לֵאמֹר מְרַגְּלִים אַתֶּם, בְּזֹאת תִּבָּחֵנוּ חֵי פַרְעֹה אִם תֵּצְאוּ מִזֶּה כִּי אִם בְּבוֹא אֲחִיכֶם הַקָּטֹן הֵנָּה, שִׁלְחוּ מִכֶּם אֶחָד וְיִקַּח אֶת אֲחִיכֶם וְאַתֶּם הֵאָסְרוּ וְיִבָּחֲנוּ דִּבְרֵיכֶם הַאֱמֶת אִתְּכֶם וְאִם לֹא חֵי פַרְעֹה כִּי מְרַגְּלִים אַתֶּם: (מב, ז-טז)","b":true},{"t":"נודעה קושיית הרמב\"ן (בראשית מב, ט), וז\"ל, ויאמר אליהם מרגלים אתם - העלילה הזאת יצטרך להיות בה טעם או אמתלא, כי מה עשו להיות אומר להם ככה, וכל הארץ באו אליו, והם בתוך הבאים, כמו שאמר לשבור בתוך הבאים כי היה הרעב בארץ כנען. ע\"ש מה שתירץ.","b":false},{"t":"ולפי פשוטו של מקרא יש לומר, כי בחכמה הטיל יוסף על אחיו אשמה חמורה כל כך, וזאת כדי לדוחקם וללחצם, כדי שיוציא מהם דברים שרצה לשמוע. כי ע\"י שיראו שהמושל חושדם בחמורות כאלה, יפתחו את פיהם ויאמרו לו דברים מתולדותיהם, כדי להסיר מהם חשד חמור שכזה. ואז אמרו לו, לא היינו מרגלים, אלא כולנו בני איש אחד נחנו, וכתבו בעלי התוספות בספר דעת זקנים משם רבינו מאיר ז\"ל, וז\"ל, כולנו בני איש אחד, תימה מה תשובה היא שלא היו מרגלים. וי\"ל שאילו היו מרגלים ששלחו אותם לרגל את הארץ היו שולחים בני אדם שהם נכרים זה לזה ולא אחים, ע\"ש. וכ\"כ רבנו הקדוש בעל אור החיים מדיליה בתוספת ביאור. יעו\"ש.","b":false},{"t":"ואחר שאמרו את דבריהם, דחה יוסף את דבריהם ואמר להם בתקיפות, לא! כי ערות הארץ באתם לראות (בראשית מב, יב). ואז ענו השבטים, ויאמרו שנים עשר עבדיך אחים אנחנו בני איש אחד בארץ כנען והנה הקטן את אבינו היום והאחד איננו (שם שם, יג). וזאת היתה מה שיוסף ביקש לשמוע, את מה שאמרו שאחד מאחיהם איננו, ומיד שאלם, ואם ידרשו מכם ממון הרבה עבור האחד הזה האם תפדוהו, אמרו לו הן. אמר להם, ואם יאמרו לכם שלא יחזירוהו לכם בשום ממון מה תעשו, אמרו לו, לכך באנו, להרוג או ליהרג. אמר להם הוא אשר דברתי אליכם להרוג בני העיר באתם. והוא מדברי רבותינו (ב\"ר צא, ז). וראה עוד בדברי הרב כלי יקר שם (בראשית מב, יג).","b":false},{"t":"וכך דרך החוקר את החשוד שמטיל עליו אשמה חמורה, כדי לדוחקו, ואז החשוד מודה בדברים קטנים יותר. ועשה יוסף את כל זאת כדי להשלים את ענינו שהיה בדעתו לכופם להביא את בנימין, ואז יעליל עליהם עלילה ויקח מהם את בנימין, כדי לבוחנם אם אין עוד שנאת אחים בניהם, ומוכנים למסור את נפשם בעד אחיהם. ואז יודע אליהם, ויעלו לשלום אל אביהם.","b":false},{"t":"ואילולי חומרת האשמה בה הם מואשמים, לא היתה הצדקה שכלית לדרישתו ופקודתו של יוסף, שאמר להם (בראשית מב, טו), חי פרעה אם תצאו מזה כי אם בבא אחיכם הקטֹן הנה. והבאת בנימין היתה חשובה בעיניו להשלמת האחוה ביניהם, בטרם יפגשו יחד ברינה. וא\"כ עיקר כונת יוסף בדבריו היתה לבחון אם חזרו אחיו בתשובה ועתה יש בהם אהבת אחים.","b":false},{"t":"ויש לחזק פירוש זה ממה שכתב הרמב\"ן ז\"ל שם (פסוק ט), גם הענין השני שעשה להם בגביע לא שתהיה כונתו לצערם, אבל חשד אולי יש להם שנאה בבנימין שיקנאו אותו באהבת אביהם כקנאתם בו, או שמא הרגיש בנימין שהיה ידם ביוסף ונולדה ביניהם קטטה ושנאה, ועל כן לא רצה שילך עמהם בנימין אולי ישלחו בו ידם עד בדקו אותם באהבתו. ולזה נתכונו בו רבותינו בבראשית רבה (צג, ט), אמר רבי חייא ב\"ר אבא כל הדברים שאתה קורא שדיבר יהודה בפני אחיו עד שאתה מגיע ולא יכול יוסף להתאפק, היה בו פיוס ליוסף, פיוס לאחיו, פיוס לבנימין, פיוס ליוסף, ראה היאך נותן נפשו על בניה של רחל וכו'.","b":false},{"t":"וכן אני אומר שכל הענינים האלה היו ביוסף מחכמתו בפתרון החלומות, כי יש לתמוה אחר שעמד יוסף במצרים ימים רבים והיה פקיד ונגיד בבית שר גדול במצרים, איך לא שלח כתב אחד לאביו להודיעו ולנחמו, כי מצרים קרוב לחברון כששה ימים, ואילו היה מהלך שנה היה ראוי להודיעו לכבוד אביו, ויקר פדיון נפשו ויפדנו ברוב ממון.","b":false},{"t":"אבל היה רואה כי השתחויית אחיו לו וגם אביו וכל זרעו אתו, אי אפשר להיות בארצם, והיה מקוה להיותו שם במצרים בראותו הצלחתו הגדולה שם, וכל שכן אחרי ששמע חלום פרעה שנתברר לו כי יבאו כולם שמה ויתקיימו כל חלומותיו, עכ\"ל. ע\"ש. והוא תנא דמסייע לן שכל מטרת יוסף היתה לבדוק את אחיו אם יש בהם צער על מכירתו, ואם יש ביניהם אהבת אחים. ומכבר כתבתי בחי' שיוסף נהג באחיו התנכרות גדולה כדי למרק את עוונם (ראה להלן מאמר י)","b":false},{"t":"ובס\"ד מצאתי תנא דמסייע לן הוא ניהו רבינו יעקב בעל הטורים ע\"ה שכתב על הפסוק (בראשית מב, יז), ויאסוף אותם אל משמר שלשת ימים, כנגד ג' דברים שעשו לו, ויפשיטו את כותנתו, וישליכו, וימכרו. עכ\"ל. והיינו שיוסף נהג כן כדי לכפר להם על עוונותיהם.","b":false},{"t":"(י\"ב אייר התשס\"ו – לונדון)","b":false}]},{"id":"21","t":"הנשמר במדת היסוד זוכה לפרנסה טובה ועושר וניצול מרעב ומיתה","p":[{"t":"וַתִּרְעַב כָּל אֶרֶץ מִצְרַיִם וַיִּצְעַק הָעָם אֶל פַּרְעֹה לַלָּחֶם וַיֹּאמֶר פַּרְעֹה לְכָל מִצְרַיִם לְכוּ אֶל יוֹסֵף אֲשֶׁר יֹאמַר לָכֶם תַּעֲשׂוּ: (מא, נה)","b":true},{"t":"ופירש רש\"י ז\"ל, שהרקיבה תבואתם שאצרו חוץ משל יוסף. והלכו המצרים אל פרעה וצעקו ללחם, והוא אמר להם לכו אל יוסף אשר יאמר לכם תעשו, לפי שהיה יוסף אומר להם שימולו, ורק אח\"כ יתן להם תבואה. וכשבאו אצל פרעה ואומרים כך הוא אומר לנו, אמר להם למה לא צברתם בר, והלא הכריז לכם ששני הרעב באים. אמרו לו, אספנו הרבה והרקיבה. אמר להם, אם כן כל אשר יאמר לכם תעשו, הרי גזר על התבואה והרקיבה, מה אם יגזור עלינו ונמות. ע\"כ ומקורו בדברי רבותינו (ב\"ר צא, ה).","b":false},{"t":"וצריך להבין למה דרש יוסף מהמצרים שימולו, והלא היא מצוה לישראל שהם בני ברית, ומה למצרים ולמצות מילה. ולמה תלה יוסף את ענין נתינת המזון במילה דוקא.","b":false},{"t":"אמנם ידוע דהמזונות תלויים בשמירת הקדושה, ומשום כך המזונות וענין הזנות שתיהן קשורים בשורש אחד, ומקרא מלא דיבר הכתוב (משלי ו, כו), כי בעד אשה זונה עד ככר לחם, ואמרו רבותינו (סוטה ד, ב), כל הבא על אשה זונה סופו לבקש ככר לחם. רח\"ל. וראה במסכת גטין (נז, א), מעשה ועמדו ארבעים מודיות בדינר, נחסר השער מודיא אחת, ובדקו ומצאו אב ובנו שבאו על נערה מאורסה ביום הכפורים, והביאום לבית דין וסקלום וחזר השער למקומו. ע\"כ.","b":false},{"t":"הנה כשנתייקרו השערים אפילו במעט, מיד אמרו בני הדור נחפשה דרכנו ונחקורה, בשלמי הרעה הזאת, ומי זה אשר בחטאו הביא עליהם את יוקר השערים. וגם ידעו שעוון של זימה הוא המביא את יוקר השערים רח\"ל, ולא תלו את ירידת ערך המטבע בעניני הטבע וניהול הכלכלה ותיחכום הסוחרים וכו', אלא חיפשו את שורש הרעה, וטיפלו בה כראוי, עד שביערו את הרע מקרבם, וחזר השער למקומו. ע\"ש. ולא בכדי הוא שמעשה זה נכתב בגמ' גטין בדף נ\"ז שהוא אותיות \"זן\". שהוא שורש שני הענינים כנ\"ל.","b":false},{"t":"ומרן החבי\"ף ביאר בזה בספרו הנפלא תוכחת חיים (סדר שמות), דזהו מה שתקנו אנשי כנסת הגדולה בברכת המזון, ועל בריתך שחתמת בבשרנו ועל תורתך שלמדתנו וכו' ועל חיים ומזון שאתה זן ומפרנס אותנו, היינו דזוכה לתורה ומזונות בשפע רק ע\"י ששומר בריתו, יעו\"ש.","b":false},{"t":"ובזה תבין את מה שנאמר ביוסף שאדוניו נתן כל אשר לו בידו, ולא ידע אתו מאומה כי אם הלחם אשר הוא אוכל (בראשית לט, ו), ואמרו רבותינו (ב\"ר פו, ו), שהכונה היא לאשת פוטיפר, אלא שדיבר הכתוב בלשון נקיה. אלא שעכ\"פ צריכים אנו להבין למה נרמז ענין האשה דוקא בלחם, אך לפי מה שביארנו מבואר שפיר, כי מזונותיו של אדם ולחמו, תלויים במדה בה הוא מקדש את עצמו.","b":false},{"t":"[א\"ה - גם אני ברגליו אעבורה לבאר בזה מאמה\"פ (תהלים כ, ג), ישלח עזרך מקודש ומציון יסעדך, כי ידוע שהפוגם בברית קודש ח\"ו מרחיק ממנו את זיווגו, ואם הוא נשוי הריהו מכניס בפגמיו קטטה בינו לבין אשתו ח\"ו, ועוד בה שמאבד את מזונותיו רח\"ל. כי גורם למניעת גשמים כמבואר בזוה\"ק (ח\"א קפט, ב) דמאן דלא נטיר להאי ברית קיימא דקודשא גרים פרישו בין ישראל לאבוהון דבשמיא, בגין דכתיב וסרתם ועבדתם וגו' ולא יהיה מטר, יעו\"ש. ומעתה זהו אומרו, \"ישלח עזרך מקודש\", היינו לפי המדה שאתה מתקדש בקדושת יסוד, לפי\"ז תזכה לעזר, שהיא האשה כמו שנא' (בראשית ב, יח) אעשה לו עזר כנגדו. ותהא אשתו עוזרתו, ואם אינו נשוי יזכה לאשה טובה. והמשיך ואמר, \"ומציון יסעדך\", כי הנה ידוע כי ציון גימ' יוסף והוא בחינת היסוד דנוקבא והוא יסוד המלכות (כמבואר בלקוטי תורה פר' ויצא ופר' נשא), והיינו כפי מה שיקדש האדם את עצמו במדת ציון הוא יוסף הרומז ליסוד כן יזכה לפרנסה טובה ומרווחת, ודוק. יבח\"ר].","b":false},{"t":"ויוסף הצדיק שומר הברית, הוא המשביר בר לכל הארץ, ולכן ציוה לכל המצרים למול להרחיקם מהזימה ומעוונות אלו כדי שיזכו לפרנסה וכלכלה טובה, בזכות הכנה זו. וצריך לומר שלא רק עם ה' המצווים ועושים, פרנסתם תלויה בשמירת הטהרה והקדושה. אלא חוק הוא לכל אדם ואדם ואפילו גוי שכאשר הוא שומר את עצמו מכל דבר רע זוכה לברכת ה' ומתעשר. וק\"ו בן בנו של ק\"ו לאיש ישראל כמה שהוא צריך לשמור את עצמו מכל דבר אשר אינו טהור, ולשמור את פיו ועיניו, ועי\"ז יזכה לשמור עצמו בטהרה, ועי\"ז שורה עליו ברכת ה'. ואולי זו כונת הפסוק (תהלים לז, כה), נער הייתי גם זקנתי ולא ראיתי צדיק נעזב וזרעו מבקש לחם (וראה דבר נפלא בפרי עץ חיים שער הלולב פ\"ג), היינו שהצדיק ששומר עצמו בקדושה מועיל לו ולזרעו שלא תחסר להם פרנסה.","b":false},{"t":"ורבינו האר\"י אמר (ראה שעה\"פ פר' מקץ ופר' ויגש), דאנשי מצרים שהיו בדורו של יוסף הם גלגול אנשי דור המבול ודור הפלגה שהיו צריכים לתקן פגם הוז\"ל שפגם אדה\"ר כשפרש מאשתו ק\"ל שנים, ואנשי דור המבול ודור הפלגה לא תיקנו והוסיפו פגמים. ולכך יוסף הצדיק ביקש לתקן הפגם שיש במצרים קצת, ולכן ציוה אותם למול. (ויש להמתיק ד\"ז כי יוסף הוא השליט, כי הוא בחינת יסוד, ורצה להקל את צער השעבוד מישראל, שיבואו למצרים שהם צריכים לתקן לגמרי ולהעלות את כל ניצוצות הקדושה שנפלו למצרים, ולהקל עליהם מטרחם לכן ציוה על כל מצרים למול), יעו\"ש באורך. וא\"כ למדנו מדברי רבינו האר\"י כי כיון שבני ארץ מצרים היתה נשמתם פגומה בפגם הברית לכך נתגבר עליהם הרעב, ויוסף הצדיק רצה למתק את הדינים ולכך אמר להם למול, כדי לחזק עצמם בקדושת היסוד. ודו\"ק.","b":false},{"t":"וההסבר לכל זה הוא משום שברכת ה' היא תעשיר (משלי י, כב), וכשחוטא ופוגם באות ברית קודש אזי השכינה מתרחקת ממנו, כדכתיב (דברים כג, טו), ולא יראה בך ערות דבר ושב מאחריך, ואם אין השכינה עמו, אין לו ברכה, ואין לו פרנסה רח\"ל.","b":false},{"t":"ועוד יש להוסיף את דברי רבינו האר\"י שהיסוד נקרא כל (ראה שער הפסוקים ולקוטי תורה פר' וישב ובלקוטי תורה לקהלת וראה בשעה\"כ דרושי תפלת השחר דרוש א). וגם כלכלה יש בו לשון \"כל\" פעמיים עם אות ה' שהיא כנגד ה' חסדים (עי' לקוטי תורה פר' מקץ), והיינו לרמוז שאדם זוכה לכלכלה טובה כשהוא שומר עצמו היטב במדת יסוד.","b":false}]},{"id":"21","t":"גם כשהקב\"ה מעלים מהצדיק איזה דבר הריהו רומזו לו","p":[{"t":"וַיַּרְא יַעֲקֹב כִּי יֶשׁ שֶׁבֶר בְּמִצְרָיִם וַיֹּאמֶר יַעֲקֹב לְבָנָיו לָמָּה תִּתְרָאוּ: (מב, א)","b":true},{"t":"ופירש\"י ז\"ל, וירא יעקב, ומהיכן ראה, והלא לא ראה אלא שמע, שנא' (להלן מב, ב), הנה שמעתי כי יש שבר במצרים, וא\"כ מהו וירא, אלא שראה באספקלריא של קדש שעדיין יש לו שֶׁבֶר במצרים, ולא היתה נבואה ממש להודיעו בפירוש שזה יוסף. עכ\"ל. ומקורו טהור בדברי רבותינו (ב\"ר צא, ו).","b":false},{"t":"והנה שמעתי באומרים לי כי מילת \"שבר\" בר\"ת, עולה, שָׁם בן רחל.","b":false}]},{"id":"21","t":"לשכוח מן הצרות ולדבוק במדת הבטחון","p":[{"t":"וּלְיוֹסֵף יֻלָּד שְׁנֵי בָנִים בְּטֶרֶם תָּבוֹא שְׁנַת הָרָעָב אֲשֶׁר יָלְדָה לּוֹ אָסְנַת בַּת פּוֹטִי פֶרַע כֹּהֵן אוֹן, וַיִּקְרָא יוֹסֵף אֶת שֵׁם הַבְּכוֹר מְנַשֶּׁה כִּי נַשַּׁנִי אֱלֹהִים אֶת כָּל עֲמָלִי וְאֵת כָּל בֵּית אָבִי, וְאֵת שֵׁם הַשֵּׁנִי קָרָא אֶפְרָיִם כִּי הִפְרַנִי אֱלֹהִים בְּאֶרֶץ עָנְיִי: (מא, נ-נב)","b":true},{"t":"הנה יוסף הצדיק ביטא בקריאת שמות שני בניו את הודאתו להי\"ת, לאפרים קרא בשמו, כדי להורות לכל, איך הקב\"ה הפרה אותו בארץ עניו ונותן הודאה על כך. אמנם בקריאת השם מנשה יש ב' ענינים. א, כי נשני אלהים את כל עמלי. ב, ואת כל בית אבי.","b":false},{"t":"והנה אומרו את כל עמלי, הוא מובן שמשבח יוסף את הי\"ת על שהשכיח ממנו את כל העמל והצער והתלאות שעברו עליו מיום שעזב את בית אביו, ואולי גם מה שהיה בבית אביו שאחיו שנאוהו ולא יכלו דברו לשלום, דהכל בכל כלול בזה. שהרי אמר את \"כל עמלי\", אבל את הענין השני שאמר יוסף שנשהו אלהים את כל בית אביו, אין לו מובן לכאורה, כי בבית אביו היה יושב בצלא דמהימנותא, וחוסה תחת כנפי אביו הגדול, שהיה יושב ומלמדו את כל התורה שלמד בבית מדרשו של שם ועבר (כמבואר ב\"ר פד, ח והובא נמי בדברי רש\"י בראשית לז, ג), והשכינה חופפת עליהם. וגם מעינוגי העוה\"ז לא חסר יוסף דבר, כי ישראל אהב את יוסף מכל בניו ועשה לו כתונת פסים (בראשית לז, ג), וגם אם היה לו הצער של שנאת האחים הלא מזער היה באותו זמן, כי טובה מרובה היתה לו קירבת אביו והיא השכיחה ממנו כל צער ויגון, וא\"כ מה נתינת הודאה יש כאן לקרא בשם בנו בכורו מנשה, על שהשכיחו הי\"ת את כל בית אביו.","b":false},{"t":"גם קשה עוד, שהרי מצאנו לחז\"ל (ב\"ר צד, ג ושם צה, ג ותנחומא ויגש פי\"א), שאמרו, שאחר שנתגלה יוסף לאחיו שלח להזכיר לאביו סימן שהוא יוסף באמרו שכשפירש ממנו היו עוסקים בהלכות עגלה ערופה, וזה שנאמר (בראשית מה, כז), וירא את העגלות אשר שלח יוסף, ולא נאמר אשר שלח פרעה. ועכ\"פ למדו שלא שכח יוסף ולא נשה את תורת אביו, וא\"כ מתעצמת השאלה מהו נשני את \"כל\" בית אבי. וגם איך משוה הכתוב את כל עמלו, לכל בית אביו, שהם תרתי דסתרי.","b":false},{"t":"והנראה בעזהית\"ש שיוסף מודה לה' הנותן ליעף כח, שחיזק את רוחו, ועזרו לשכוח את כל עמלו, הלא המה התלאות הרבות, ולא נתן למוט רגלו, למעוד וליפול בעצבות רעה המדכאת את הנפש, ומביאה את האדם ליאוש ומשבר בעבודת ה', אלא התחזק יוסף והמשיך בעבודת ה' בכל עוז, ולא שת לבו לעבר, כי אין. והיה חי כל יום באשר הוא שם, וכל יום מתחיל מחדש בעבודת הי\"ת כמו שנאמר (דברים ו, ו), והיו הדברים האלה אשר אנכי מצוך היום ואמרו על זה חז\"ל (ראה ספרי ואתחנן פיסקא ח וילקו\"ש ורש\"י דברים ו, ו), בכל יהיו בעיניך כדברים חדשים שאתה מתאוה להם.","b":false},{"t":"אמנם גם אם שכח יוסף את הצער שציערוהו אחיו, כאומרו להם (בראשית מה, ח), ועתה לא אתם שלחתם אותי הנה כי האלהים וגו'. אבל מ\"מ עצם השהיה במקומות המלאים טומאה, היא צער גדול ההווה ומתמשך בכל ימי גלותו, ואם יתן אל לבו לזכור את מצבו ומעמדו הרם והנפלא בבית אביו, וישוה את זה למצבו היום שנפל מאיגרא רמה לבירא כ\"כ עמיקתא רח\"ל, ושבר על שבר באו לו, שלא די לו במה שמכרוהו אחיו בני אביו לעבד נרצע בידי אדונים זרים וקשים, אנשי זמה ומרמה, אלא עוד נפל קרבן לעלילה בזויה והורד לבור האסירים וברזל באה נפשו. ובודאי שבכל עת שיזכור מטוב בית אביו והדרו. ישבר לבו בקרבו ויפול בים העצב והדכאון שהוא אם כל חטאת, ואם יהיה מניח לדמיונו לפרוח בלא ביקורת ושלטון עצמי לא היה מוצא נחמה אפילו לרגע קט, כי בכל דבר ודבר ירגיש בחסרון בית אביו, ועבודת ה' מה תהא עליה במצב הזה.","b":false},{"t":"אכן יוסף הצדיק חיזק את עצמו בבטחון נפלא, שהכל באשר לכל הוא מאת הי\"ת, ועם כל הצרות והתלאות היה שם הי\"ת שגור על פיו ובטחונו איתן. [ומה שאמרו חז\"ל (ב\"ר פט, ג), על הפסוק (בראשית מ, ג), ולא זכר שר המשקים את יוסף, שזה היה עונש של ששם את מבטחו בבשר ודם בשר המשקים שיוציאנו משביו, ולא היה לו לעשות כן והובאו הדברים גם בפירוש רש\"י ז\"ל (שם). אדרבא, משם ראיה על גודל בטחונו של יוסף בהי\"ת, דמשום שהיה כ\"כ גדול במדת הבטחון, לכך הענישוהו על דבר זעיר שלמעשה הוא בבחינת השתדלות, משום שהקב\"ה מדקדק עם חסידיו כחוט השערה, כי הרי לכשנתבונן נראה מיד כי יוסף הצדיק לא שם מבטחו בשר המשקים, רק עשה השתדלות מועטת כשנזדמן לו הענין ע\"י פתרון החלום, ואמר לו לזוכרו לטובה, והרי צריך וחייב האדם להשתדל, אלא רק דקדוק גדול יש בזה, ביחס לרום מעלתו הגדולה של יוסף ודי בזה].","b":false},{"t":"ומגודל בטחונו בה' האמין יוסף בכל לבו שהכל לטובה, וביטל את כל עצמיותו לפני רצון המקום ב\"ה, באומרו גם זו לטובה, שכן אמר לאחיו (בראשית נ, כ), אתם חשבתם עלי רעה אלהים חשבה לטובה, וכך נהג בכל צרותיו ותלאותיו.","b":false},{"t":"וע\"ז היה יוסף הצדיק משבח ומודה להי\"ת, שנתן לו כח לשכוח גם את העמל והצער, וגם את כל הטוב והעונג שהיו לו בבית אביו, כי אם לא היה יוסף שוכח את הנעימות שהיתה לו בבית אביו, והיה עושה כל הזמן השואות ביחס לבית אביו, לא היה יכול להחזיק מעמד לא ברוחניות ולא בגשמיות והיה ח\"ו יכול להגיע עד טירוף הדעת. ולכן שכחה זו מעולה וחשובה לו מאד מאד, ואלמלי היא לא היה מגיע עד הלום, וע\"כ קרא שם בנו בכורו מנשה, כי נשני אלהים את כל עמלי, ואת כל בית אבי.","b":false},{"t":"(ב\"ה ט\"ז טבת התשמ\"ח)","b":false}]},{"id":"21","t":"העולם הזה דומה לחלום ארוך","p":[{"t":"וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים וּפַרְעֹה חֹלֵם וְהִנֵּה עֹמֵד עַל הַיְאֹר, וְהִנֵּה מִן הַיְאֹר עֹלֹת שֶׁבַע פָּרוֹת יְפוֹת מַרְאֶה וּבְרִיאֹת בָּשָׂר וַתִּרְעֶינָה בָּאָחוּ, וְהִנֵּה שֶׁבַע פָּרוֹת אֲחֵרוֹת עֹלוֹת אַחֲרֵיהֶן מִן הַיְאֹר רָעוֹת מַרְאֶה וְדַקּוֹת בָּשָׂר וַתַּעֲמֹדְנָה אֵצֶל הַפָּרוֹת עַל שְׂפַת הַיְאֹר, וַתֹּאכַלְנָה הַפָּרוֹת רָעוֹת הַמַּרְאֶה וְדַקֹּת הַבָּשָׂר אֵת שֶׁבַע הַפָּרוֹת יְפֹת הַמַּרְאֶה וְהַבְּרִיאֹת וַיִּיקַץ פַּרְעֹה, וַיִּישָׁן וַיַּחֲלֹם שֵׁנִית וְהִנֵּה שֶׁבַע שִׁבֳּלִים עֹלוֹת בְּקָנֶה אֶחָד בְּרִיאוֹת וְטֹבוֹת, וְהִנֵּה שֶׁבַע שִׁבֳּלִים דַּקּוֹת וּשְׁדוּפֹת קָדִים צֹמְחוֹת אַחֲרֵיהֶן, וַתִּבְלַעְנָה הַשִּׁבֳּלִים הַדַּקּוֹת אֵת שֶׁבַע הַשִּׁבֳּלִים הַבְּרִיאוֹת וְהַמְּלֵאוֹת וַיִּיקַץ פַּרְעֹה וְהִנֵּה חֲלוֹם: (מא, א-ז)","b":true},{"t":"יש להתבונן ולבאר פסוקים אלו בדרך רמז. ויהי מקץ, מדבר על המראה אשר יראה האדם בקץ הימים. כי כל זמן שהאדם חי בזה העולם, הריהו חושב לעצמו שאלו הם החיים ואין אחריהם עוד חיים ממשיים, וגם בראותו שהאדם שב לעפר, והרוח תשוב אל האלהים, אינו ירא ואינו מתפעל, אלא מדמיין בדמיונו שבזה נגמר האדם. וכן האמת הוא אצל רוב היצורים, אבל אצל בניו של הקב\"ה ועם סגולתו, אין הדבר כן ואין העולם הזה בשבילם אלא פרוזדור, כדבר ארעי וחולף שהאדם חייב לעבור במעבריו ולהבחן במבחנותיו.","b":false},{"t":"וכל זה כהכנה לקראת החיים האמיתיים שבהם הנשמה מעותדת ליהנות מזיו השכינה. אך כל זה הוא נעלם מעיני כל חי בעודנו בזה העולם, אבל כאשר יבא אל תכליתו אז הוא מבין ויודע שכל חיי העוה\"ז תוהו, ואינו אלא חלום בעלמא, ואחר שהסתיים החלום, אז האדם מתעורר מחלומו הממושך, ורואה את האפסיות שבחיי העוה\"ז.","b":false},{"t":"וזה שאמר דוד המלך ע\"ה, בשוב ה' את שיבת ציון היינו כחולמים (תהלים קכו, א), היינו, כי לעתיד נבין כי בימי חיינו בעוה\"ז היינו כחולמים, כי רק אז נבין שהעוה\"ז הוא כחלום ממש רק שהוא חלום ארוך. וממילא, אז ימלא שחוק פינו (שם שם, ב), כי כשנשוב להתבונן על מה היינו שמחים, ועל מה היינו מצטערים, נראה שהכל הבל ורעות רוח, ופינו ישחק במלואו, באומרנו, איך התיחסנו כ\"כ בצער לדבר פלוני, ואיך שמחנו כל כך בדברים אחרים, כי לעתיד יתבהר המצב, ויוברר מה משקלו האמיתי של כל דבר.","b":false},{"t":"וזה אומרו ויהי \"מקץ\", היינו, כאשר כבר חלפו ועברו הימים והשנים, ופרעה חולם, אולי \"פרעה\" מלשון \"פרוע\", כאדם שהגיע זמנו לפרוע את שטר חובו, וכן הנשמה הגיע זמנה להפרד מן העולם וליתן דין וחשבון על מעשיה. ואז נתגלה כי כל מה שהאדם חשב ל\"חיים\" אינו אלא \"חלום\".","b":false},{"t":"והנה עומד על היאור, תיבת \"היאר\" בהיפוך האותיות הוא תיבת \"ראיה\" שהלא תיבת היאר כתיב חסר וא\"ו. והנה מן היאר עולות, היינו שהאדם צופה ומביט ורואה עולם הפוך, והַיְאֹר מלשון ראיה, שמתבונן היטב ורואה, שהדברים שהיו נראים יפים ביותר וטובים ביותר, הן המה החלשים והרזים, כמו שראינו כי שבע הפרות רעות המראה ודקות הבשר, הן החזקות והמוצלחות ביותר, ותאכלנה הפרות הרעות ודקות הבשר את שבע הפרות יפות המראה והבריאות, וזה יורה כי אל לו לאדם לטעות בדמיונו ולילך אחר הנאה והיפה כי לרוב אינו מחזיק.","b":false},{"t":"וכן הוא הענין בעולמנו זה, כי בני אדם הרואים את הצדיק האמיתי יושב בעוה\"ז בפינתו, ועוסק בתורת ה' יומם ולילה, ואין לו בעולמו אלא לעשות נחת רוח לאבינו שבשמים ולשמור חוקיו ומשפטיו. הריהם מסתכלים בו במראה מעורר חמלה ומלא רחמים והצדיק דומה בעיני הרואים אותו לשבע הפרות רעות המראה ודקות הבשר אשר צפד עורן על בשרן מרוב מאמץ. ואילו כשהם רואים את בעלי הנאות העוה\"ז מדושני עונג ומלאים בחמדות העוה\"ז ותאוותיו, הדומים לשבע הפרות יפות המראה והבריאות, כי בעלי החמדה והתאוה מעוררים את התפעלות הכל במעשיהם, כי הם דומים לפרות הרועות באחו, ומתחממות לאור השמש, ואין מי שיאמר להן מה יעשו, כי הן פטורות מכל עול ואין עליהם שום שלטון. אמנם לבסוף מתברר הענין הדק היטב, כי הפרות הדקות אכלו את הפרות הבריאות והשמנות, וכן הוא לעתיד לבא, אותם צדיקים מיוסרים, הם הזוכה לשבעה נחלי אפרסמון, ונהנים מזיו השכינה, ואילו הרשעים נבלעים וכלים באש הגהינם רח\"ל. ואז, ממשיך הכתוב, \"ויקץ פרעה\", שאז האדם מקיץ משינתו ותרדמתו \"תרדמת הזמן\" ונפקחו עיניו לראות את האמת לאמיתו.","b":false},{"t":"ויישן ויחלום שנית והנה שבע שבלים וגו'. שלא תאמר מקרה הוא שעלה להם לאותן פרות כך, אבל בדרך כלל, מה שרואים הוא האמת באין אומר ואין דברים, על זה אמר \"ויישן ויחלום שנית\", היינו שהדברים חוזרים על עצמם גם \"בשִׁבֳּלִים\" שהוא ענין אחר, וגם שם נאמר, ותבלענה השבלים הדקות, את שבע השבלים הבריאות והמלאות, ויקץ פרעה והנה חלום.","b":false},{"t":"ואמנם יש הבדל מהותי בין שתי המראות החלומיות הנ\"ל, כי הפרות דרכן לאכול ולבלוע, ויש רק פלא אחד שבלעו פרות אחרות. ועוד שהפרות שבלעו היו בריאות ומלאות מהן. אבל בשבלים הפלא גדול יותר שאין דרכן לבלוע כלל ובלעו, ונוסף על זאת בלעו את השבלים הבריאות והמלאות.","b":false},{"t":"וככל שנעמיק ונוסיף עוד שנית להעמיק בדבר הזה, נראה שאין ההגיון של העוה\"ז שליט בעניני האמת כלל, ולבסוף כשתתגלה האמת יעמוד האדם נפעם ונרעש מרוב השתאות, הפלא ופלא, כאדם שרואה פלא תוך פלא, כי הכל באשר לכל הוא הפוך ורחוק כ\"כ משכלנו ומהגיוננו, ולזה רמז הכתוב שאחריו באומרו, ויהי בבקר ותפעם רוחו. והיינו, ויהי בבקר כשיאיר אור בוקר שניתן הכח באדם לבקר ולהבחין בין הדברים, כי יפוצו ענני הלילה המסתירים מעינינו את האמת, והעוה\"ז דומה ללילה בו הכל נסתר הסתר על הסתר, והראיה מטושטשת ומעורפלת, עד שהטוב נראה רע והרע נראה טוב, וגם הטעם הוחלף והומר, ואין מבדילים בין מתוק ובין מר, והאדם מתרגל בזה עד שחושב שזו האמת הצרופה, ואין אחרת, ולכן העולם קרוי עולם מלשון העלם. אמנם בהגיע הבוקר ויזרח עליו אור האמת, תיכף נאמר בו, ותפעם רוחו, ואונקלוס תרגמו ומטרפא רוחיה, ורש\"י ז\"ל פירש מקשקשת בתוכו כפעמון, כי הכל נהפך עליו ברגע.","b":false},{"t":"אך האיש הירא וחכם הלב, אינו ממתין לעת קץ, ומקדים רפואה למכה, ומתעורר בעודו כאן, לחשוב על אחרית דבר מראשיתו, ואע\"ג דאנן לא חזינן, כי עיני בשר לנו ומוגבלות הן, ואינן מסוגלות לראות באור האמת בעודן בעולמנו, מ\"מ האדם הכשר סומך על דברי חכמינו ורמזי תורתנו, ומכניע את עצמו, ומקבל את האמת, מתוך אמונה בהי\"ת ובתורתו מתוך התבטלות, ואולי לזה רמזה תורתנו הקדושה במאמרה (דברים יז, י-יא), ועשית ככל אשר יורוך. ואמרו חז\"ל (ספרי שופטים פיסקא יא), לא תסור ימין ושמאל מדברי החכמים, ואפי' מראים בעיניך על שמאל שהוא ימין ועל ימין שהוא שמאל שמע להם. כי המראה הנגלה לעיני האדם הפשוט הוא ממש היפך המציאות, כי השמאל נראה ימין. אך הרואה נכוחה יודע את האמת, ואין מי שיכול לראות אמת זו בכח עצמו, אלא הזוכה לגילוי מלמעלה.","b":false},{"t":"וע\"ז התפלל דוד מלך ישראל בפסוקים רבים מאד בתהלים, וכאומרו (תהלים פו, יא), הורני ה' דרכך אהלך באמיתך. שאם לא יראוהו מן השמים איזו הדרך בה ידרוך, לא יוכל להשיג לעולם את אמיתות רצון האל ב\"ה. וכן פסוקים רבים מראים דבר זה. וא\"א להשיג את האמת אלא ע\"י שמיעה והכנעה, לדברי תורה ודברי חכמים, שמעו ותחי נפשכם (ישעיה נה, ג).","b":false},{"t":"כי הצדיק הריהו מושל יראת אלהים (ש\"ב כג, ג), היינו שהדבר היחיד המושל על הצדיק הוא יראת הי\"ת. וע\"י עבודתו להי\"ת בתמימות ויושר, הריהו זוכה ורואה מה שאין עין רגילה יכולה לראות, ועין הצדיק מבחינה בדקויות שאין עין אדם רגיל מבחינה בהם, ואולי זו היתה דמותו של יוסף בזמן ההוא. כי אחר שקרא פרעה לחרטומי מצרים וחכמיה לפתור את חלומו, ואין פותר אותם לפרעה, בא שר המשקים ומספר לפרעה על יוסף, ושם אתנו נער עברי וגו' איש כחלומו פתר (בראשית מא, יב). היינו כי פרעה וקרוביו היו משועבדים לעניני הגשמיות שעבוד גמור ומוחלט ושוקעים בהם עד צואר. וממילא הריהם נשלטים ע\"י יצר של גשמיות, ונדמו לבהמות, לפי שאינם יכולים לראות מאומה מבעד למסך המכסה על מקרי החיים, אבל יוסף הצדיק שהתנהג מעל הטבע ושלט ביצרו במסירות נפש, רוח ה' היתה שורה עליו, והיה רואה את האמת הנכוחה ללא כחל וללא סרק, באין מסכים המבדילים ומערפלים את הראיה.","b":false},{"t":"ובבוא יוסף לפני פרעה ושמע את החלומות, השיב ואמר (בראשית מא, טז), בלעדי אלהים יענה את שלום פרעה. ותרגם אונקלוס, לא מן חוכמתי אלהין מן קדם ה' וכו'. ואפשר ד\"בלעדי\" שאמר, הוא לומר שאין זה בכחי ואין זה ממני, שהרי א\"א לעין אדם לראות דברים כאלו, אמנם \"אלהים יענה\", שהוא הנותן בו כח מעל לטבע עד שרואה את האמת והוא עודנו מלובש במלבוש של בשר ודם, וְהַרְאִיָה הזאת אינה משתייכת ללבוש זה, וזה אומרו, בלעדי.","b":false},{"t":"ועוד י\"ל דשבע הפרות ושבע השבלים, רומזים אל שבעים שנות חיי האדם, ויש שרואה שבעים שנים של אושר ועושר וששון ושמחה, ויש ששבעים שנותיו רעות כאותן פרות דקות בשר ואותן שבלים שדופות קדים, אך אין להתפעל מטובתם ולא להבהל מרעתם, כי לא מה שרואים הוא האמת, ועפ\"י רוב האמת היא היפך גמור ממה שנראה לעינינו כאן.","b":false},{"t":"(בס\"ד י\"ג ניסן התשס\"ו)","b":false}]},{"id":"21","t":"ירידת האדם לעולם היא כדי לאסוף זכויות לנשמתו","p":[{"t":"וְעַתָּה יֵרֵא פַרְעֹה אִישׁ נָבוֹן וְחָכָם וִישִׁיתֵהוּ עַל אֶרֶץ מִצְרָיִם, יַעֲשֶׂה פַרְעֹה וְיַפְקֵד פְּקִדִים עַל הָאָרֶץ וְחִמֵּשׁ אֶת אֶרֶץ מִצְרַיִם בְּשֶׁבַע שְׁנֵי הַשָּׂבָע, וְיִקְבְּצוּ אֶת כָּל אֹכֶל הַשָּׁנִים הַטֹּבוֹת הַבָּאֹת הָאֵלֶּה וְיִצְבְּרוּ בָר תַּחַת יַד פַּרְעֹה אֹכֶל בֶּעָרִים וְשָׁמָרוּ, וְהָיָה הָאֹכֶל לְפִקָּדוֹן לָאָרֶץ לְשֶׁבַע שְׁנֵי הָרָעָב אֲשֶׁר תִּהְיֶיןָ בְּאֶרֶץ מִצְרָיִם וְלֹא תִכָּרֵת הָאָרֶץ בָּרָעָב, וַיִּיטַב הַדָּבָר בְּעֵינֵי פַרְעֹה וּבְעֵינֵי כָּל עֲבָדָיו, וַיֹּאמֶר פַּרְעֹה אֶל עֲבָדָיו הֲנִמְצָא כָזֶה אִישׁ אֲשֶׁר רוּחַ אֱלֹהִים בּוֹ: (מא, לג-לח)","b":true},{"t":"יש לפרש עפ\"י מה שכתבתי לעיל (מאמר הקודם), שכל ענין זה, בא ג\"כ לרמוז לאדם על עניני העוה\"ז שאין טובתם שלמה, ולא מה שנראה טוב הוא הטוב האמיתי.","b":false},{"t":"ובא יוסף הצדיק ע\"ה ואומר, ועתה ירא פרעה, היינו, כי כל איש ואיש הבא לחשוב חשבונו של עולם, ראשית חכמה יעשה חשבון אמיתי ונוקב כדת מה לעשות, ואיך לנהל עניניו, ומי ינהיג ומי יוליך. כי סוף מעשה צריך מחשבה תחילה. וכמו אדם שבא לנהל ממלכה, ראשיתו קובע מי ומי ההולכים והמוליכים בכל דבר וענין, כן הדבר אצל האדם, כי האדם הוא עולם קטן, וניתנו בו איברים וגידים רבים ומגוונים, ולכל אחד מאיבריו וגידיו יש תפקיד חשוב, לא הרי זה כהרי זה. וכל אחד משמש את חברו וגם משלים את פעלו, ומבין כולם יחדיו יוצא תיפקוד מושלם של האדם, בחכמה ובתבונה ובדעת.","b":false},{"t":"ויש מלחמה רצופה ובלתי פוסקת בין איבריו החשובים של האדם. כי הלב אומר לי משפט הבכורה שאני הוא העיקרי בין כל האברים, שאני נותן דם וחיות לכולם, ועל פי ישק כל דבר, ואני אמלוך. והמוח אומר, אני משכן החכמה ולי דעת ולי תבונה לשקול כל ענין בטעם ובהגיון צרוף, ולא כאשר ישא המזלג, לפי הרגש ומצב הרוח.","b":false},{"t":"ויוסף הצדיק בא ואומר, עתה, אחר הודיע ה' אותנו כל זאת, עליך לראות איש נבון וחכם, הוא המוח האנושי, וישיתהו על ארץ מצרים שימליך אותו על כל הגוף, שהוא נתון בין המשפתים, בין עולו של היצה\"ר ובין עולו של היצה\"ט, וכל איבר ואיבר חפץ בענינו הקרוב אליו, וצריך מלך שימלוך עליהם, כדי להנחותם הדרך ללכת בדרך הטובה ביושר וצדק, ולהאיר להם את חשכת הלילה השרויה בעוה\"ז (ראה פסחים ב, ב וחגיגה יב, ב).","b":false},{"t":"\"וחימש את ארץ מצרים בשבע שני השבע\", הן המה שבעים שנות חיי האדם, הנתון במקום שפל הוא העוה\"ז. כי רק בעוה\"ז יש אפשרות לקיים מצוות וללמוד תורה, ואין מקום אחר, וע\"כ נקראים בשם \"שבע שנות השבע\", ושמם נאה להם, כי בימים ההם יש לאדם אפשרות ללקט ולחמש את עצמו, להרוות נפש צמאה ושוקקה, מכל טוב העולם, ביודעו שבשעת פטירתו של אדם אין מלוין לו לאדם לא כסף ולא זהב ולא אבנים טובות ומרגליות, אלא תורה ומעשים טובים בלבד, (אבות ו, י).","b":false},{"t":"וכיון שהאדם יודע בבירור, שאין מקום להשיג בו תורה ומצות ומעשים טובים, כי אם בעוה\"ז בלבד. על כן ינצל את ההזדמנות שזימן לו הי\"ת יוצר האדם, וחימש את ארץ מצרים בשבע שני השבע, למלאת ולצבור מכל הטוב שזימן הי\"ת והרבה לנו תורה ומצות כדי לזכותינו (משנה מכות ג, טז), ואחרי כן יצא מן העוה\"ז ברכוש גדול, וזה שהמשיך ואמר: ויקבצו את כל אוכל השנים הטובות הבאות האלה, והיה האוכל לפקדון לארץ לשבע שני הרעב, וגו'. כי מה ששמר והכין ושלח צדקותיו לפניו בבחינת צדק לפניו יהלך (תהלים פה, יד), זה יעמוד לו למגן וצנה בבא ימי הרעב ויעמוד לדין, ליום הדין הגדול והנורא. כי אותם טובות שצבר יהיו מגיניו וסנגוריו, והמה יהיו למגן בעדו.","b":false},{"t":"ועוד דלא כל ימי העוה\"ז שוים, כי יש ימים רגועים, ויש ימי נסיונות ומהמורות, ואם הוא חכם הרואה את הנולד, ומביט מראש, עליו לצבור בר, ולנצל את ימי הטובה לחזק את עצמו ולהגדיל תורתו ויראתו, ואזי חיזוק זה עומד לו בהגיע עת הנסיון, וזהו אומרו, \"והיה האוכל לפקדון לארץ לשבע שני הרעב, אשר תהייןָ בארץ מצרים\", שהם ימי הנסיונות והמאבקים הרוחניים.","b":false},{"t":"ואם כך יעשה ימלא רוב נחת בהגיעו למקץ ימים ושנים, כי ימצא את עצמו בידים מלאות טובה וברכה מן התורה ומן המצוות ומעשים טובים, ולא יבוש ולא יכלם לפני בוראו, ולא יראו פניו ריקם, בבואו להראות את פני האדון ה' הוא אלהים חיים.","b":false},{"t":"(ערב פסח התשס\"ו)","b":false}]},{"id":"21","t":"הי\"ת מסובב כל הסיבות מסובב את יציאת יוסף מכלאו ומעלהו לגדולה כדי שיביא את בית אביו מצרימה","p":[{"t":"וַיְהִי מִקֵּץ שְׁנָתַיִם יָמִים וּפַרְעֹה חֹלֵם וְהִנֵּה עֹמֵד עַל הַיְאֹר: (מא, א)","b":true},{"t":"כתב בתרגום יוב\"ע, והוה מסוף תרתין שנין עאל דוכרנא דיוסף קדם מימרא דיי ופרעה הוה חלים והא קאי על נהרא וכו'.","b":false},{"t":"הנה פרעה מלך מצרים יושן על משכבו בשלום, והנה חלום, ויהי בבקר ותפעם רוחו לאמר, מה החלום המשונה הזה אשר חלם, ויקרא לכל חכמיו וחרשיו ואין פותר, ומי יכול להעלות על דעתו את סיבת הענין.","b":false},{"t":"אבל בורא העולם ומנהיגו אומר ועושה, והוא גזר בברית בין הבתרים על בניו של אברהם אבינו ע\"ה שיהיו גרים בארץ מצרים (בראשית טו, יג-יד), ועבדום ועינו אותם וגו', וסיבב הי\"ת בגזרתו שיוסף ירד למצרים כדי למשוך אחריו את יעקב אבינו (ראה מה שנתבאר לעיל בפרשתנו מאמרים ט, יד). וגלגל הי\"ת את הענין שיוסף הצדיק יהיה בבית האסורים מקום אשר שרי המלך אסורים שם, וכשהגיע ובא המועד, ועלה זכרונו של יוסף לפני הקב\"ה, נגזר על פרעה לחלום את החלום הזה, אשר לא נתן לו מנוח בנפשו, והיה דורש ומחפש את פתרונו, עד שנזדמן לו יוסף ופתר לו את חלומו כהוגן, ואז עלה יוסף לגדולה. וסוף דבר שירד יעקב בכבוד מלכים מצרימה, ועצת ה' היא תקום.","b":false}]}]},{"slug":"ויגש","name":"פרשת ויגש","items":[{"id":"23","t":"בחשיבות החזקת ידי לומדי התורה","p":[{"t":"רַק אַדְמַת הַכֹּהֲנִים לֹא קָנָה כִּי חֹק לַכֹּהֲנִים מֵאֵת פַּרְעֹה וְאָכְלוּ אֶת חֻקָּם אֲשֶׁר נָתַן לָהֶם פַּרְעֹה עַל כֵּן לֹא מָכְרוּ אֶת אַדְמָתָם: (מז, כב)","b":true},{"t":"הנה גם במצרים הבינו שיש צורך לתת הספקה וחוק המזון למי שרוצה ללמוד, כדי שבעתיד יהפכו הלומדים למורי הדרך עבור שאר העם. ולכן מחוקי פרעה הוא, שיהיה לחם חוקם נתון להם, כדי שלא יצטרכו להתעסק בדברים אחרים כדי לדאוג למחיתם, ונמצאים בטלים מלמודם.","b":false},{"t":"ולהבדיל בין הקדש ובין החול, תורתנו הקדושה, קבעה שיש לכהנים העובדים במשמרת המקדש לאכול מלחם אשי ה', ולקבל את התרומה והמעשר כדי שיהיו פנוים לעבודת הי\"ת.","b":false},{"t":"ואל זה מורין דברי רבינו הגדול הרמב\"ם בסוף הלכות שמיטה ויובל (פי\"ג הלכות יב-יג), שכתב, כי הקב\"ה מזכה ללומדי התורה חלק המספיק להם בעולם הזה, כאשר זיכה לשבט לוי, ולא עוד אלא שאינם יוצאים למלחמה וכו', ע\"ש היטב. שמתבאר כי כשם שהקב\"ה זיכה לכהנים וללוים מתנות כהונה ולויה, כך זיכה ללומדי התורה.","b":false},{"t":"וגם אנו צריכים ללמוד מזה, ולהחזיק בארון התורה לבל ימוט ולסייע בכל היכולת ללומדי התורה, אשר מהם יצאו מנהיגי העם ושופטיו. עץ חיים היא למחזיקים בה ותומכיה מאושר.","b":false}]},{"id":"23","t":"יבאר מה הטעם שקנה יוסף את אדמת מצרים בהמותיהם וגופם","p":[{"t":"וַיִּתֹּם הַכֶּסֶף מֵאֶרֶץ מִצְרַיִם וּמֵאֶרֶץ כְּנַעַן וַיָּבֹאוּ כָל מִצְרַיִם אֶל יוֹסֵף לֵאמֹר הָבָה לָּנוּ לֶחֶם וְלָמָּה נָמוּת נֶגְדֶּךָ כִּי אָפֵס כָּסֶף, וַיֹּאמֶר יוֹסֵף הָבוּ מִקְנֵיכֶם וְאֶתְּנָה לָכֶם בְּמִקְנֵיכֶם אִם אָפֵס כָּסֶף, וַיָּבִיאוּ אֶת מִקְנֵיהֶם אֶל יוֹסֵף וַיִּתֵּן לָהֶם יוֹסֵף לֶחֶם בַּסּוּסִים וּבְמִקְנֵה הַצֹּאן וּבְמִקְנֵה הַבָּקָר וּבַחֲמֹרִים וַיְנַהֲלֵם בַּלֶּחֶם בְּכָל מִקְנֵהֶם בַּשָּׁנָה הַהִוא, וַתִּתֹּם הַשָּׁנָה הַהִוא וַיָּבֹאוּ אֵלָיו בַּשָּׁנָה הַשֵּׁנִית וַיֹּאמְרוּ לוֹ לֹא נְכַחֵד מֵאֲדֹנִי כִּי אִם תַּם הַכֶּסֶף וּמִקְנֵה הַבְּהֵמָה אֶל אֲדֹנִי לֹא נִשְׁאַר לִפְנֵי אֲדֹנִי בִּלְתִּי אִם גְּוִיָּתֵנוּ וְאַדְמָתֵנוּ, לָמָּה נָמוּת לְעֵינֶיךָ גַּם אֲנַחְנוּ גַּם אַדְמָתֵנוּ קְנֵה אֹתָנוּ וְאֶת אַדְמָתֵנוּ בַּלָּחֶם וְנִהְיֶה אֲנַחְנוּ וְאַדְמָתֵנוּ עֲבָדִים לְפַרְעֹה וְתֶן זֶרַע וְנִחְיֶה וְלֹא נָמוּת וְהָאֲדָמָה לֹא תֵשָׁם, וַיִּקֶן יוֹסֵף אֶת כָּל אַדְמַת מִצְרַיִם לְפַרְעֹה כִּי מָכְרוּ מִצְרַיִם אִישׁ שָׂדֵהוּ כִּי חָזַק עֲלֵהֶם הָרָעָב וַתְּהִי הָאָרֶץ לְפַרְעֹה: (מז, טו-כ)","b":true},{"t":"צריך להבין מה היתה כונת יוסף הצדיק שלקח מאנשי מצרים את כל כספם ומקניהם וגם אדמותיהם בשביל להחיותם שלא ימותו מרעב. והלא הוא השליט ועליו מוטלת דאגת הצלת העם, וגם בלא שיקח את כל אשר להם, הוא צריך לתת להם כדי קיום, ובפרט שהדבר מתאפשר לו.","b":false},{"t":"ואולי כונתו היתה לטובתם, שלא תחול ירידה במצבם הנפשי, כתוצאה מהלחץ והדוחק, ומבהלת הרעב רח\"ל, וירדו לשחת את הנפש ללא רפאות תעלה, וגם אחר שיעבור הרעב מן העולם ישארו במדות הרעות שיקנו וידעו בנפשם בעת הרעה, כאשר יתרגלו לאכילה מופרזת כאשר קורה בעת הרעב רח\"ל, וכמ\"ש האוה\"ח על הפסוק ולחם אין (הובאו דבריו לעיל מאמר הקודם).","b":false},{"t":"וגם שבנוסף לזאת יתרגלו לאכול לחם חינם, שגם היא מחולאי הנפש, וגוררת אחריה מעשים רעים רבים, שכמעט ולא יוכלו להגמל מהם ותשחת נפש העם כולו. וגם בעת שתעבור מכת הרעב מהם, ישארו מוכים ונגועים במדות קשות ומושחתות, אשר תוצאותם מי יוכל לשער.","b":false},{"t":"אכן כאשר האנשים משלמים במיטב כספם ובמקניהם ואדמותיהם כדי להשיג מזון, הריהם שקולים יותר ומחושבים יותר. ויוסף הצדיק בחכמתו העמוקה ובהסתכלותו החודרת, וראיתו את הנולד. השכיל לנהל ענין זה בהדרגה ובתבונה נפלאה.","b":false},{"t":"והחכמה הזאת איך לנהל ולהנהיג את העם בעתות רעב, היתה גדולה מן החכמה הראשונה של איסוף וליקוט המזון בשבע שני השובע שקדמו לימי הרעב. זה הנראה לענ\"ד בהבנת דבר זה.","b":false},{"t":"ומצאתי מעט עזר לזה מדברי הספורנו ע\"ה שכתב, וינהלם בלחם. נהלם. לאט. כענין עלות ינהל (ישעיה מ, יא). נתן להם הלחם מעט מעט, אכול ולא לשבעה, כראוי בשני רעבון. כאמרם (תענית יא, א), המרעיב עצמו בשני רעבון ניצול ממיתה משונה. וכבר אמרו חכמי הרפואה שהשובע אחר הרעב גורם חולי ממית. ע\"כ. והוא ז\"ל דיבר על חולאי הגוף הנגרמים מתזונה לא מבוקרת בימי הרעב, שיש בהם להמית, והצילם מזה, אך זה תלוי בחלוקה מועטת, ולאו דוקא בענין התשלום. ובמה שכתבתי בדלותי על ענין חולאי הנפש הנגרמים בעת הרעב, נוכל להבין מעט מחכמתו הנפלאה של יוסף המשביר לכל הארץ.","b":false},{"t":"[א\"ה - הנה בשאלה הזאת נתעורר גם בספר טעמא דקרא למוהר\"ר חיים קנייבסקי נר\"ו, והוא ישב את הענין, באמרו שראה יוסף ברוה\"ק שעתיד הקב\"ה להביא מכות גדולות ונאמנות על מצרים בעבור פרעה שאינו רוצה לשלח את בני ישראל מארצו. והנה לכאורה יש למצרים טענה לפני הי\"ת מדוע יכה את כל ארץ מצרים, והלא אם פרעה חטא לפני הי\"ת במאנו לשלח את ישראל מה עשו הם שכולם יענשו באין יוצא מן הכלל. ולזה התחכם יוסף וקנה אותם ואדמתם לפרעה ואז כולם שייכים לפרעה, ולכן נענשים כולהו בבקתא חדא. זת\"ד.","b":false},{"t":"ולפנים שנים רבות העירותיהו להרב המחבר הנז' נר\"ו על זה, שלפי דבריו אלו לא היה להי\"ת להעניש לכהני מצרים, שהרי יוסף לא קנה את אדמותיהם ואותם, כמבואר בהדיא בפסוקים (בראשית מז, כב). ויען ויאמר לי, מי אמר לך שכהני מצרים נענשו, והשיבותי לו, מקרא מלא דיבר הכתוב, ובכל אלהי מצרים אעשה שפטים (שמות יב, יב), ונאמר, ובאלהיהם עשה ה' שפטים (במדבר לג, ד), ונאמר, ויהי חושך אפילה בכל ארץ מצרים ולכל בני ישראל היה אור בכל מושבותם (שמות י, כב-כג), ונאמר (שם יא, ה), ומת \"כל\" בכור. וכמה דוחק יש בדברים, לומר, שמכת דם וצפרדע ושאר המכות לא באו על כהני מצרים. והדברים פשוטים וברורים. יבח\"ר].","b":false}]},{"id":"23","t":"השפעת הרעב על האדם","p":[{"t":"וְלֶחֶם אֵין בְּכָל הָאָרֶץ כִּי כָבֵד הָרָעָב מְאֹד וַתֵּלַהּ אֶרֶץ מִצְרַיִם וְאֶרֶץ כְּנַעַן מִפְּנֵי הָרָעָב: (מז, יג)","b":true},{"t":"הפסוק אומר שאין לחם מפני הרעב, וקשה, כי לכאורה הוא בהיפך, שהרעב כבד משום שאין לחם. וכבר נרגש מזה רבינו הקדוש בעל אוה\"ח. וז\"ל, פירוש ולצד כובד הרעב היו אוכלים דבר מופלא, וכילו הלחם. והלא לראות עינינו דאבה נפשנו בשני רעב שהיה במערב, שהיה אדם אחד אוכל שיעור מאכל עשרה בני אדם, ועודנו רעב בבטנו רח\"ל. ע\"כ.","b":false},{"t":"וזכורני שזקן אחד (ר' משה אבוחצירא ז\"ל משלומי), אמר לי, שבכל העולם סבלו חרפת רעב בתקופות שונות, אלא יש שהרעב הכה בבטנם, ויש שהכה אותם במוחם, ואלה שהכה אותם הרעב בבטן כשאכלו ושבעו, נשכח הרעב ואיננו. אבל אלה, שלקו במוחם, גם כי יאכלו וישבעו, לעולם נשארים רעבים, רח\"ל. ישמע חכם וישכיל.","b":false}]},{"id":"23","t":"נקיון כפיו של יוסף","p":[{"t":"וַיְכַלְכֵּל יוֹסֵף אֶת אָבִיו וְאֶת אֶחָיו וְאֵת כָּל בֵּית אָבִיו לֶחֶם לְפִי הַטָּף: (מז, יב)","b":true},{"t":"מוסר גדול לימדנו יוסף ע\"ה עד כמה על האדם לנהוג בנקיות כפים, כי עם שהמלך אמר לו להושיב את אביו ואת אחיו במיטב הארץ, ולכלכלם בכבוד, וכמו שנאמר (בראשית מה, יז-כ), ויאמר פרעה אל יוסף, אמֹר אל אחיך וגו'. ואתנה לכם את טוב ארץ מצרים, ואכלו את חלב הארץ. ולא עוד אלא שיוסף הוא המשביר בר לכל הארץ והציל את המדינה כולה מלמות ברעב, ועשה הכל כדי להחיות עמים רבים. וא\"כ היה יכול להורות היתר לעצמו, לתת לאחיו מזון בשפע גדול ולפנקם. ובפרט שבודאי היה מעונין מאד לעשות נחת רוח לאביו, ועם כל זאת ראינו כי נתן להם לחם בחשבון ומדה כאומרו, \"לחם לפי הטף\".","b":false},{"t":"וכן הוא בפירוש רבינו עובדיה ספורנו ז\"ל, וז\"ל, לחם לפי הטף. אע\"פ שהיה בידו להרבות להם מזון, נתן להם במדה מספקת כאומרם ז\"ל (תענית יא, א), בזמן שהצבור שרוי בצער, אל יאמר אדם אלך אני ואוכל ואשתה ושלום עליך נפשי, ע\"כ. והוסיף וכתב להלן על הפסוק ויבא יוסף את הכסף ביתה פרעה (בראשית מז, יד), שלא הורה יוסף לעצמו היתר בכל עמלו לקחת דבר לעצמו. עכ\"ל. ישמע חכם ויוסף לקח.","b":false}]},{"id":"23","t":"יעקב אבינו נענש על שהתאונן על הצער והיסורים שעברו עליו","p":[{"t":"וַיֹּאמֶר פַּרְעֹה אֶל יַעֲקֹב כַּמָּה יְמֵי שְׁנֵי חַיֶּיךָ, וַיֹּאמֶר יַעֲקֹב אֶל פַּרְעֹה יְמֵי שְׁנֵי מְגוּרַי שְׁלשִׁים וּמְאַת שָׁנָה מְעַט וְרָעִים הָיוּ יְמֵי שְׁנֵי חַיַּי וְלֹא הִשִּׂיגוּ אֶת יְמֵי שְׁנֵי חַיֵּי אֲבֹתַי בִּימֵי מְגוּרֵיהֶם: (מז, ח-ט)","b":true},{"t":"ראיתי להביא בכאן דברים נוראים מדברי רבותינו בעלי התוספות בספר דעת זקנים, אשר ראוי לכל נבון לשים את הדברים הללו אל לבו, וז\"ל, פשוט לפי שראהו זקן מאד, ושערות ראשו וזקנו לבנות מרוב הזקנה שאל כן. והוא ענהו ימי מגורי שלשים ומאת שנה מעט ורעים, כלומר מעטים הם שנותי, אלא מתוך רעות שהיו לי קפצה עלי זקנה. מדרש, בשעה שאמר יעקב \"מעט ורעים היו ימי שני חיי\", אמר לו הקב\"ה אני מלטתיך מעשו ומלבן והחזרתי לך את דינה וגם את יוסף, ואתה מתרעם על חייך שהם מעט ורעים היו, חייך שמנין התיבות שיש מן ויאמר עד בימי מגורי, כך יחסרו משנותיך שלא תחיה כיצחק אביך, והם ל\"ג תיבות, וכמנין הזה נחסרו מחייו, שהרי יצחק חי ק\"פ שנה, ויעקב לא חי אלא קמ\"ז. עכ\"ל.","b":false},{"t":"והנה חז\"ל גילו לנו זאת, כדי ללמדנו שעל אף הצרות הרעות והרבות שסבל יעקב אבינו כל ימי חייו, צרת עשו, וצרת לבן, וצרת דינה, וצרת יוסף כ\"ב שנים, והיו אלו יסורים קשים ונוראים למעלה מהשגתינו. מ\"מ כיון שהחזיר לו הי\"ת לבסוף את בנו ואת דינה וכו', היה אסור ליעקב להתאונן, וכיון שהתאונן מעט ורעים היו ימי שני חיי, מיד נתבע באופן החמור ביותר, ועל כל תיבה ותיבה שהוציא מפיו איבד שנת חיים.","b":false},{"t":"ויותר מזאת ראיתי להגר\"ח שמואלביץ ז\"ל (שיחות תשל\"א - מאמר ג), שהוסיף בזה הערה נפלאה כדרכו, שהרי בכלל הל\"ג תיבות שנאמרו בפסוקים חשבו ליעקב גם את שמונה התיבות של שאלת פרעה \"ויאמר פרעה אל יעקב כמה ימי שני חייך\", ומה לתיבות אלו וליעקב ולמה נתבע גם עליהן, אמנם נראה שבעלי התוספות טמנו זאת בדבריהם, כי כיון שראה פרעה את יעקב וראה את שערות ראשו וזקנו לבנות מאד, שהלבינו מפני הזקנה שאלו לגילו, ויעקב השיב שאמנם צעיר הוא אלא שהצרות הביאו עליו זקנה בלא עת, ולולי היה מרגיש יעקב בצרותיו לא היתה זקנה קופצת עליו, ועל זה נתבע גם על דברי שאלות פרעה. כי שאלת פרעה ליעקב בן כמה הוא, באה מפני שראה פרעה את מראהו הלבן, שנבע מרוב צערו ורגישותו, עכת\"ד. והדברים נוקבים עד תהומות הנפש.","b":false},{"t":"וזכורני ששמעתי ממגידי אמת, בת\"ח ויר\"ש גדול וחשוב שהיה לו צער גדול מבנו שלא התנהג כשורה, והיה מצטער ע\"ז מאד, והתאונן אצל הגה\"ק בעל קהלות יעקב מוה\"ר י\"י קנייבסקי זללה\"ה. ואמר לו הגריי\"ק ז\"ל, שידע שגם על הצער הזה שמזיק לבריאותו הריהו עתיד ליתן הדין. וא\"ל הת\"ח שהוא מצטער על חסרון יר\"ש וכדו'. ואמר לו הגריי\"ק ז\"ל, צריך להשתדל ולעשות מה שיכולים, והשאר ביד הי\"ת. וחייבים להתחזק ולהתעודד.","b":false}]},{"id":"23","t":"ברכת יעקב לפרעה","p":[{"t":"וַיָּבֵא יוֹסֵף אֶת יַעֲקֹב אָבִיו וַיַּעֲמִדֵהוּ לִפְנֵי פַרְעֹה וַיְבָרֶךְ יַעֲקֹב אֶת פַּרְעֹה: (מז, ז)","b":true},{"t":"ופירש\"י ז\"ל והיא שאלת שלום כדרך כל הנראים לפני המלכים לפרקים. עכ\"ל. והרמב\"ן ז\"ל (שם), כתב שאינו נראה כן, שאין מדרך מוסר המלוכה שישאל אדם בשלום המלך. וכמו שאמרו (שבת פט, א), כלום יש עבד שנותן שלום לרבו. אלא היא ברכה ממש. שדרך הזקנים והחסידים הבאים לפני המלכים לברך אותם בעושר נכסים וכבוד והתנשא מלכותם, וכעין שאמר הכתוב (מ\"א א, לא), יחי אדוננו המלך דוד לעולם. וכו' ע\"כ.","b":false},{"t":"ואילולי דב\"ק של רבינו הרמב\"ן ז\"ל היה מקום לומר, שלזה התכוין אף רש\"י ז\"ל, והכי קאמר, ויברך יעקב, היא שאילת שלום. כלומר, דכיון דאינו דרך ארץ לשאול בשלום המלך כדבר איש אל רעהו, על כן שאלת שלום המלך היא בדרך הזאת, שיברך אותו בשלום ובהצלחה ונשיאות חן וכו' ובצאתו מלפניו חזר [יעקב] ובירך אותו, [כדי] ליטול רשות מלפניו, ואמרו רבותינו (ראה במדב\"ר יב, ב ותנחומא נשא פכ\"ו), שברכו שיעלה נהר הנילוס לקראתו. ע\"כ.","b":false},{"t":"ומזה מצאנו מקור למנהג הנפוץ בקהילות ישראל שמברכים את המלך בימי שבת ומועד ובפרט ביום הכיפורים, ותיקנו קדמונינו ברכה מיוחדת על זה, הנותן תשועה למלכים וממשלה לנסיכים וכו', הלא היא כתובה בסדורי התפלה ובמחזורים.","b":false},{"t":"ומ\"ש הרמב\"ן ז\"ל בסוף דבריו שם, ובצאתו מלפניו חזר ובירך אותו ליטול ממנו רשות, ואמרו רבותינו שברכו שיעלה נילוס לרגלו. עכ\"ל. נראה שהיה קשה לו מה שאמר הפסוק (להלן מז, י), ויברך יעקב את פרעה ויצא מלפני פרעה. דהרי כבר אמר הכתוב בתחילה שיעקב בירך את פרעה ומה לו לחזור על ענין הברכה, ולכן פירש שהיא נטילת הרשות. ולפי מש\"כ בדעת רש\"י ז\"ל דבמקום שאילת שלום רגילה הנהוגה בין אנשים בירך יעקב את פרעה ולא עשה זאת כשאלת שלום מפני כבוד המלכות. אתי שפיר גם ענין היציאה, דגם ביציאתו שב יעקב ובירכו והוא ענין אמירת שלום, ונטילת רשות ביציאתו. ועי' בדברי רש\"י ז\"ל על פסוק זה שכן משמע ממנו, שכן כתב, ויברך יעקב - כדרך כל הנפטרים מלפני שרים מברכים אותם ונוטלים רשות, ומה ברכה ברכו, שיעלה נילוס לרגליו וכו', ודוק.","b":false}]},{"id":"23","t":"למה אבותינו הקדושים בחרו להיות רועי צאן","p":[{"t":"וַיֹּאמֶר פַּרְעֹה אֶל אֶחָיו מַה מַּעֲשֵׂיכֶם וַיֹּאמְרוּ אֶל פַּרְעֹה רֹעֵה צֹאן עֲבָדֶיךָ גַּם אֲנַחְנוּ גַּם אֲבוֹתֵינוּ, וַיֹּאמְרוּ אֶל פַּרְעֹה לָגוּר בָּאָרֶץ בָּאנוּ כִּי אֵין מִרְעֶה לַצֹּאן אֲשֶׁר לַעֲבָדֶיךָ כִּי כָבֵד הָרָעָב בְּאֶרֶץ כְּנָעַן וְעַתָּה יֵשְׁבוּ נָא עֲבָדֶיךָ בְּאֶרֶץ גּשֶׁן, וַיֹּאמֶר פַּרְעֹה אֶל יוֹסֵף לֵאמֹר אָבִיךָ וְאַחֶיךָ בָּאוּ אֵלֶיךָ וגו', הוֹשֵׁב אֶת אָבִיךָ וְאֶת אַחֶיךָ יֵשְׁבוּ בְּאֶרֶץ גּשֶׁן וְאִם יָדַעְתָּ וְיֶשׁ בָּם אַנְשֵׁי חַיִל וְשַׂמְתָּם שָׂרֵי מִקְנֶה עַל אֲשֶׁר לִי: (מז, ג-ו)","b":true},{"t":"הנה רעיית הצאן שבה עסקו אבותינו, היתה להם למחיה, אך יותר למחיה רוחנית מאשר למחיה גשמית, וכמו שנאמר במשה רעיא מהימנא (שמות ג, א), ומשה היה רועה את צאן יתרו חתנו כהן מדין וינהג את הצאן אחר המדבר וגו'. ואיתא בזוה\"ק שהיה משה מתרחק מהמון העם, ומתבודד במדברות, בד קדש, ושם היה מתייחד עם קונו ומייחד יחודים ומזוג זיווגים, ומתקדש ועולה, עד שהיה מוכן ומזומן לנבואה (ראה ח\"ב דף כא ע\"א, ודוק היטב), ודעת לנבון נקל, שלא יעלה בדעת שפתאום ביום אחד יצא וקרא אליו מלאך ה' מתוך הסנה, וגם דיבר עמו אלהים, ופשוט וברור שאי אפשר להשיג נבואה כזאת ללא הכנה דרבה. ואת ההכנה הזאת היה עושה משה רבינו תוך כדי רעיית הצאן. וזה היה מעשה אבותינו, אברהם יצחק ויעקב, ולזה הכין יוסף את אחיו ומאידך הכין לזה גם את פרעה, ועתה האחים אומרים לפרעה רועי צאן עבדיך, גם אנחנו גם אבותינו.","b":false},{"t":"[א\"ה - והרמח\"ל בפירושו לתורה כתב וירא אלהים וגו' (שמות ג, ב). כאן נרמזו תיקונים של זו\"ן לצורך הגאולה. כבר ידוע שפגם הראשון שהיה באותו הזמן היה שלא היו מאירים המוחין בז\"א ולכך עכשיו נזדמנו ביאת המוחין. וזהו \"וירא\" בסוד מוח חכמה, דכבר ידוע שראיה בחכמה, \"אלהים\" בסוד מוח בינה, \"וידע\" בסוד מוח הדעת, ולכך אומר אח\"כ, \"ומשה היה רועה\", שמשה עומד בדעת, וכיון שנתגלה למעלה שרשו, היה יכול גם הוא למטה לתקן תיקונים לצורך הגאולה. אבל היה רועה צאן. צאן, כבר נתפרש שהם בסוד הז' תחתונות דז\"א בסוד, \"צאן אדם\", והיה עושה פעולת שרשו למעלה, שהוא הדעת המתקן הז' תחתונות, וגם הוא היה עושה תיקונים למטה לתיקון זה. זהו תיקונו של ז\"א. אח\"כ תיקונו של נוק', \"ויבא אל הר האלהים\" שהיא המלכות. ויש כאן סוד שארז\"ל \"ומשה היה רועה\", כתיב (תהלים יא, ה), \"ה' צדיק יבחן\", [היינו כי] הקב\"ה בוחן הצדיקים במרעה, וכמו שהיה במשה ובדוד. יש להבין וכי זהו כל כך נסיון שנאמר, \"ה' צדיק יבחן\" - לרעות צאן. [אמנם] כבר ידוע שנשמת ישראל נקראים צאן, ובכל מקום ראינו שהצדיקים הגדולים היו רועי צאן, דרך משל - יעקב, כבר נתפרש ש[רועה] ר\"ל בירור הניצוצות הטובות שיש בתוך הקליפות, והרי הוא באמת נסיון גדול להם, לפי שהם צדיקים גמורים ומצד עצמם היו ראויים לכל טוב. אבל נוטלים על עצמם לילך בתוך הקליפות לעשות הבירור, וזהו צרה גדולה להם, ששם סובלים דוחק גדול. הרי הוא נסיון גדול לצדיקים לרעות צאן, שכשהם רועים צאן למטה זה רומז הליכת נשמתם בתוך הקליפות לעשות הבירור. ומשה היה מכוין לזה לעשות הבירור להביא הגאולה. ע\"כ. והדברים משלימים זא\"ז. יבח\"ר].","b":false},{"t":"וזו התשובה שענו אחי יוסף על שאלת פרעה מה מעשיכם. כי תמיד האדם עומד בפני שאלה זו, לדעת בכל עת מה מעשיו, ומהי תכליתו, ואל מה ישים מגמתו בכל ימי חייו. וזה שענו לפרעה, רועי צאן עבדיך, היינו, שמטרתינו היא לייחד את שמו יתברך בעולמו, ולנצל את החיים לעשות רצונו, ובכל מה שאנו עוסקים, אנו מכונים את מעשינו לקיים רצונו לעשות נחת רוח לפניו, בבחינת בכל דרכיך דעהו, ואנו עושים את זה בעת שאנו עוסקים ברעיית הצאן בין נאות דשא, ועל מי מנוחות, רחוקים מהמון חוגג ורועש, בהתבודדות והתקשרות בקשרא דמהימנותא ללא היסח הדעת ממנו יתברך.","b":false},{"t":"ומה נעמו בזה דברי הרב מאור ושמש ע\"ה, על הפסוק (בראשית מז, ה), ויאמר פרעה אל יוסף לאמר וכו', שהזכיר את מאמר חז\"ל (פסחים נו, א), שאמרו, כי יעקב קודם מותו, אמר לבניו שמא יש פסול במיטתי וכו', פתחו כולם ואמרו שמע ישראל ה' אלהינו ה' אחד, כשם שאין בלבך אלא אחד, כך אין בלבנו אלא אחד, פתח ואמר ברוך שם כבוד מלכותו לעולם ועד, וכתב הרב מאור ושמש ז\"ל כי זה כל עבודתם לעשות את היחוד, שיהיה ה' אחד ושמו אחד.","b":false},{"t":"וע\"ש שכתב שזה רמוז בפסוקים הנ\"ל, \"ישבו בארץ גשן\", דהיינו, ג'ש לנו'ן שערי בינה, שהוא עולם התשובה. עו\"כ, ושמתם \"שרי מקנה על\", ר\"ת \"שמע\". \"אשר לי\", הם אותיות \"ישראל\". דהיינו, שמע ישראל, שזו היא עבודת יעקב ובניו לייחד יחודים, שיהיה ה' אחד ושמו אחד. ודפח\"ח.","b":false}]},{"id":"23","t":"בטעם ששלח יעקב דוקא את יהודה לפניהם לגושן","p":[{"t":"וְאֶת יְהוּדָה שָׁלַח לְפָנָיו אֶל יוֹסֵף לְהוֹרֹת לְפָנָיו גּשְׁנָה וַיָּבֹאוּ אַרְצָה גּשֶׁן, וַיֶּאְסֹר יוֹסֵף מֶרְכַּבְתּוֹ וַיַּעַל לִקְרַאת יִשְׂרָאֵל אָבִיו גּשְׁנָה וַיֵּרָא אֵלָיו וַיִּפֹּל עַל צַוָּארָיו וַיֵּבְךְּ עַל צַוָּארָיו עוֹד, וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף אָמוּתָה הַפָּעַם אַחֲרֵי רְאוֹתִי אֶת פָּנֶיךָ כִּי עוֹדְךָ חָי: (מו, כח-ל)","b":true},{"t":"כתב רש\"י ז\"ל בשם מדרש אגדה, להורות לפניו, לתקן לו בית תלמוד, שמשם תצא הוראה. ע\"כ. וכתב השפתי חכמים (שם אות ת'), שיצא להם כן, מדכתיב בפסוק להורת חסר וא\"ו שניה, ויש בו אותיות תורה.","b":false},{"t":"ואולי יש ענין בזה שיפגשו בית יהודה ובית יוסף יחדיו כי הגאולה יוצאת מבין שניהם. שכבר פירשתי בפרשת וישב (מאמר ב), במ\"ש חז\"ל (בבראשית רבה פד, ג וכ\"ה בילקו\"ש בראשית רמז קמ), ביקש יעקב לישב בשלוה קפץ עליו רוגזו של יוסף, היינו, שרצה יעקב אבינו כבר אז בעת ההיא לקרב ולגלות את הקץ תיכף ומיד, ע\"י שרצה לישב בשֶל-ו\"ה ולהשלים שם הוי\"ה ב\"ה שלא יהיה חסר, וקפץ עליו רוגזו של יוסף, באמור לו משיח בן יוסף עדיין לא בא, ואתה רוצה להביא את משיח בן דוד.","b":false},{"t":"וכאן שלח את יהודה לפניו, להכין לו את הדרך לבית תלמוד להורות לפניו, אבל משלוח זה הוא הכנה, שהרי אין מלך המשיח בא אלא ע\"י תורה, וכמ\"ש רבנו בעל אוה\"ח הקדוש בפרשת ויחי, על הפסוק כבס ביין לבושו (בראשית מט, יא), שהוא יינה של תורה, אשר בו יתוקן כל ענין, ויכובס כל עון וכל חטאת, ורק אחרי שיעסקו בתורה יתגלה אורו של משיח, ועוד כתב כן על פני ספרו במקומות רבים מאד, שכל הגאולה תלויה רק בתורה, וכתב (בפירושו לשמות כז, כ), כי משה הוא גואל ראשון והוא גואל אחרון, ואין משה חפץ לגאול עם בטלנים מתורה, כלשונו הקדוש. ע\"ש.","b":false},{"t":"[א\"ה - מן הראוי להביא כאן דברות קדשו של מרן רבינו חיים פלאג'י זצוקללה\"ה במכתב שכתב לה\"ר צבי הירש לעהרן מאמשטרדם (נדפס מכת\"י בירחון כרם שלמה דחסידי באבוב), אחר השריפה הנוראה שפקדה את העיר איזמיר בי\"א אב שנת תר\"א ובה עלו כל בתי היהודים באש, ונשרפו הבתי כנסיות ובתי המדרשות, ובתוכם נשרפו להחבי\"ף נ\"ד חיבורים עצומים ונוראים בכל חלקי התורה הקדושה (ואם תרצה להבין מה היו חיבוריו בהלכה, ראה תראה את ספרו לב חיים ח\"א שנדפס לפני השריפה הנ\"ל, ויש בו ק\"א תשובות מסודרות לפי סדר השו\"ע או\"ח וזה מגיע עד סי' י\"ז בשו\"ע או\"ח, ורבינו החבי\"ף ז\"ל כתב בהקדמת ספר חיים לראש, שהיה לו חיבור כזה מסודר על כל סדר השו\"ע, והיו תשובות לאלפים ולרבבות, וע\"ש עוד ממה שנשרף), ובנוסף לזה כל רכושו היה למאכולת אש, ובכלל זה נשרפה נדוניית שלש בנותיו. ובבוא מרן החבי\"ף לבקש עזרה מרצ\"ה לעהרן לא ביקש עזרה עבור בני משפחתו, אלא ביקש ספרים ללמוד ולעיין בהם, כדי שיוכל לכתוב פסקים ולעסוק בלימוד תורה. וכתב שם להעיד על עצמו כי קשה לו חסרון הספרים יותר מן המות. ובזה פירש סמיכות הפרשיות ויגש לויחי, שבסוף ויגש נאמר ואת יהודה שלח לפניו, כדי להכין לו בית מדרש, ורק אחר שיש בית מדרש ולימוד התורה, אז ויחי יעקב. זת\"ד המרטיטים כל לב. יבח\"ר].","b":false},{"t":"ולכן יעקב שלח את יהודה דוקא שילך להורות לפניו גושנה להכין לו בית מדרש. דאפשר שגם ההכנה הזו שעושים כדי להרבות תורה ולהפיצה ברבים, חשוב שתעשה ע\"י יהודה וביתו, וכמו שמצינו בחזקיה מלך יהודה שהרבה תורה בישראל כידוע ומפורסם לכל (ראה סנהדרין צד, ב), וע\"כ שלח יעקב את יהודה בכבודו ובעצמו. אך אמר לו שכל זה צריך להיות בשיתוף עם יוסף שגם הוא יקדים ויתקן חלקו, להכרית קוצים וחוחים מכרם בית ה' צבאות, וע\"כ אמר הכתוב, ואת יהודה שלח לפניו אל יוסף, להורות לפניו, ויש לרמוז דמילת \"לפניו\" השני קאי על יעקב שהוא בחינת תורה - תפארת, כדכתיב (מיכה ז, כ), תתן אמת ליעקב, וזה שנאמר ל\"הוֹרֹת\" שהוא אותיות תורה, ומשם תצא הוראה לכל בית ישראל.","b":false},{"t":"פגישת יעקב ויוסף","b":true},{"t":"וסמיך ליה, ויאסור יוסף את מרכבתו, ויעל לקראת ישראל אביו גושנה, היינו, כי מיד שראה יוסף שממנו עתיד לצאת משיח בן יוסף כי השעה כשרה ומתקרבת הגאולה, והנה המלכים נועדו, תיכף, אסר וקשר את מרכבתו, שזה רומז על עניני הגשמיות וכבוד המלכים. \"ויעל\", שעלה ונתעלה. לקראת ישראל אביו, למעלות התורה והקדושה, להתחזק ולרומם את קרן התורה, ולהרחיב את גבולות הקדושה.","b":false},{"t":"וכתב רש\"י ז\"ל, ויאסור יוסף מרכבתו. הוא עצמו אסר את הסוסים למרכבה להזדרז לכבוד אביו. והוא מתאים מאד במה שרמזתי בו בס\"ד.","b":false},{"t":"ושוב ראיתי בספר דעת זקנים מבעלי התוספות ז\"ל, שכתב, ויעל לקראת ישראל, פירוש עליה היתה לו על שהלך לקראת אביו לכבדו וכו', וגשן נתן פרעה לשרה אמנו, ולכך בחרו בה ישראל, ונפלה בחלקם ולא ערערו בה מצריים. עכ\"ל, והיא היא העליה שעלה יוסף, היינו, שאסר את כל הכחות הגשמיים, והעלה אותם לקראת התורה והקדושה, שזהו לקראת ישראל אביו, כי כידוע יעקב רומז לתורה הקדושה.","b":false},{"t":"ונאמר עוד שם, \"וירא אליו ויפול על צואריו, ויבך על צואריו עוד\". וכתב רש\"י ז\"ל שיוסף הרבה והוסיף בבכי יותר על הרגיל, אבל יעקב לא נפל על צוארי יוסף ולא נשקו, ואמרו רבותינו, שהיה קורא את שמע. עכ\"ל. ובשפתי חכמים שם (אות ד'), הקשה ולמה יוסף לא קרא ג\"כ ק\"ש באותה שעה, ותירץ דיוסף היה עסוק בכבוד אביו, והעוסק במצוה פטור מן המצוה (ראה סוכה כו, א). עוי\"ל דיוסף היה פוטר את עצמו בפסוק ראשון, מפני שהיה טרוד, כדאמרינן (ברכות יג, ב), שמע ישראל וגו' זו היא ק\"ש של רבי יהודה הנשיא, מפני שהיה טרוד בגירסא עם התלמידים. ע\"כ.","b":false},{"t":"ואפשר דאם היה יוסף מתעלה עוד ברגע הזה אל אביו בעליה נוספת, והיה קורא עמו ק\"ש, שיש בו קבלת עול מלכות שמים ועול מצוות (מתני' ברכות ב, ב ובגמ' שם יד, ב), כי ע\"י ק\"ש מכניעים את היצה\"ר (ראה ברכות ה, א), ומתעלים בלימוד תורה שיהיה לשם ה' ב\"ה בנקיות הדעת וזכות הנפש (כמו שנתבאר לעיל פרשת וישב מאמר יא), ואפשר שהיו משלימים בעת ההיא את תיקון העולם במלכות שדי, ויה\"ר שנזכה לזה מהרה שיקרבנו הי\"ת לעבודתו ויקרב קץ משיחיה.","b":false},{"t":"ואולי ע\"ז נאמר מיד שם )בראשית מו, ל), ויאמר ישראל אל יוסף אמותה הפעם אחרי ראותי את פניך, כלומר, שיעקב אבינו ציפה שבעת שיפגוש ביוסף יתקנו יחדיו את העולם במלכות שדי, ואמנם יוסף לא כיון בעת ההיא אל התיקון שביקש יעקב אבינו ע\"ה לעשות, וחלפה הלכה עת רצון ההיא. אבל היה יעקב מתנחם בכך שראה את בנו יוסף חי וגדול בתורה וביראת ה' טהורה. אבל את קירוב הישועה שעליה נאבק יעקב כל ימיו ללא הרף לא השיג גם בפעם ההיא. והוא ממשיך עד היום בדרך זו להשתדל על גאולתינו ופדות נפשנו, צור יעקב מגן ישענו.","b":false}]},{"id":"23","t":"מדרש רבה הוא אגדות שלא באו בירושלמי","p":[{"t":"וּמִקְצֵה אֶחָיו לָקַח חֲמִשָּׁה אֲנָשִׁים וַיַּצִּגֵם לִפְנֵי פַרְעֹה: (מז, ב)","b":true},{"t":"ורש\"י ז\"ל כתב, ומקצה אחיו, מן הפחותים שבהם לגבורה שאין נראים גבורים. שאם יראה אותם גבורים יעשה אותם אנשי מלחמתו. ואלה הם ראובן שמעון לוי יששכר ובנימין. אותם שלא כפל משה שמותם כשברכם. אבל את שמות הגבורים כפל, וזאת ליהודה ויאמר שמע ה' קול יהודה (דברים לג, ז), ולגד אמר ברוך מרחיב גד. ולנפתלי אמר נפתלי. ולדן אמר דן. וכן לזבולן, וכן לאשר. זהו לשון בראשית רבה (צה, ד), שהיא אגדת א\"י, אבל בגמרא בבלית שלנו (ב\"ק צב, א), מצינו, שאותם שכפל משה שמותם הם החלשים, ואותן הביא לפני פרעה. ויהודה שהוכפל שמו לא הוכפל משום חלשות, אלא טעם יש בדבר כדאיתא בב\"ק וכו'. ע\"ש.","b":false},{"t":"ובתשובה בעניני בשר בחלב אשר נדפסה בשו\"ת שמע שלמה (ח\"ב חיו\"ד סימן ג' אות ה', ועי' עוד בכרם שלמה ח\"א בתשובות דשייכי להל' ערלה סי' ד), ישבתי את דברי הרמב\"ם ז\"ל בהלכות מאכלות אסורות (ט, א-ב), שכתב וז\"ל, בשר בחלב אסור לבשלו ואסור לאכלו מן התורה ואסור בהנאה וקוברין אותו ואפרו אסור כאפר כל הנקברין, ומי שיבשל משניהם כזית כאחד לוקה שנאמר לא תבשל גדי בחלב אמו. וכן האוכל כזית משניהם מהבשר והחלב שנתבשלו כאחד לוקה ואף על פי שלא בישל, לא שתק הכתוב מלאסור האכילה אלא מפני שאסר הבישול. כלומר, ואפילו בישולו אסור ואין צריך לומר אכילתו כמו ששתק מלאסור הבת מאחר שאסר בת הבת. ע\"כ.","b":false},{"t":"ומקור דברי הרמב\"ם הללו הוא מדברי המדרש רבה (כמש\"כ הרב המגיד שם). ברם נושאי כלי הרמב\"ם ז\"ל (עי' לחם משנה שם), המה ראו כן תמהו על המראה, מדוע הרמב\"ם עזב את דברי התלמוד (חולין קטו, ב), שאמר כי נזכר ג' פעמים בתורה לא תבשל גדי, אחד לאיסור בישול ואחד לאיסור אכילה ואחד לאיסור הנאה, ומה לו להרמב\"ם להביא ענין זה מדברי המדרש שלמדו איסור אכילה מדין קל וחומר, והא אין צריך לזה כיון שהוא מפורש.","b":false},{"t":"וישבתי את דברי הרמב\"ם עפ\"י מ\"ש רש\"י ז\"ל אצלינו, דמדרש רבה, הוא אגדת א\"י, כלומר, שהנה ידוע כי התלמוד הבבלי בלול הלכה ואגדה בהדי הדדי, אבל מסדרי הירושלמי הניחו לאגדות ומדרשים מקום נפרד, וקראום מדרש רבה. והנה ידועים דברי הגר\"א ז\"ל ביו\"ד בהל' ס\"ת (סימן רפ\"ב ס\"ק יז), דדרכו של הרמב\"ם לפסוק כמו הירושלמי (ועי' יד מלאכי כללי התלמודים אות ג' ולענין שאר ספרי חז\"ל עי' שם בכללי הרמב\"ם אות ט), ופירשתי דכל זה הוא כשיש מחלוקת בבבלי, ובירושלמי הובאה ההלכה באין חולק, אז הרמב\"ם ז\"ל פוסק כהירושלמי. ובאמת שבתלמוד חולין הנ\"ל יש כמה דעות בדין בשר בחלב מהיכן נלמד. אמנם בדברי המדרש שהוא אגדת הירושלמי, הובא דין איסור בישול ואין צריך לומר איסור אכילה בלא שום חולק. לכך עזב הרמב\"ם את דברי התלמוד ואזיל בתר המדרש, ודו\"ק.","b":false},{"t":"[א\"ה - עוד יש להוסיף בה מילתא, שהנה בתרגום אונקלוס בשלשת המקומות שנאמר בתורה לא תבשל גדי בחלב אמו (שמות כג, יט ושם לד, כו ושם יד, כא), תרגם לא תבשל לא תיכלון בשר בחלב. ותמיד הוקשה בעיני, דהיה נראה דלא ס\"ל להנך דרשות דדרשו חז\"ל (חולין קטו, ב), ממה שנא' ג\"פ לא תבשל ש\"מ אחד לאיסור בישול ואחד לאיסור אכילה ואחד לאיסור הנאה. ברם יש לומר דאונקלוס ס\"ל כהמדרש דהוא על דרך אין צריך לומר, והיינו ק\"ו, ולכן תרגם במובן הפשוט לא תבשל, לא תיכול, ודו\"ק ואכמ\"ל. יבח\"ר].","b":false}]},{"id":"23","t":"אם מונים את יוכבד בכלל הנפשות הבאות עם יעקב מצרימה","p":[{"t":"אֵלֶּה בְּנֵי לֵאָה אֲשֶׁר יָלְדָה לְיַעֲקֹב בְּפַדַּן אֲרָם וְאֵת דִּינָה בִתּוֹ כָּל נֶפֶשׁ בָּנָיו וּבְנוֹתָיו שְׁלשִׁים וְשָׁלשׁ: (מו, טו)","b":true},{"t":"ואמרו רבותינו (ב\"ב קכג, ב ובמדב\"ר יג, יט), וכן כתב רש\"י ז\"ל (בראשית מו, טו), ובפרטן אי אתה מוצא אלא ל\"ב, אלא זו יוכבד שנולדה בין החומות בכניסתן לעיר, שנאמר אשר ילדה אותה ללוי במצרים. לידתה במצרים ואין הורתה במצרים. עכ\"ל.","b":false},{"t":"ורבינו אברהם ן' עזרא ע\"ה, במק\"א (בראשית מו, כג), כתב, יש אומר, כי מספר שבעים בעבור שהוא סך חשבון כי ששים ותשע היו. וזה המפרש טעה בעבור שמצאנו כל נפש בניו ובנותיו שלשים ושלש. והם שלשים ושתים ובדרש כי יוכבד נולדה בין החומות. גם זה תימה למה לא הזכיר הכתוב הפלא שנעשה עמה בהולדת משה והיא בת ק\"ל שנה ולמה הזכיר דבר שרה שהיתה בת תשעים. ולא די לנו זה הצער עד שעשו פייטנים פיוטים ביום שמחת תורה, יוכבד אמי אחרי התנחמי והיא בת ר\"נ שנה וכי אחיה חי כך וכך שנים [והם] דרך אגדה או דברי יחיד. והנכון בעיני וכו'.","b":false},{"t":"והרמב\"ן ז\"ל (בראשית מו, טו), הביא את דברי ראב\"ע הנ\"ל, והאריך לדחות את דבריו.","b":false},{"t":"וגדול דורינו וג\"ע מרן בעל יביע אומר שליט\"א, בפירושו חזון עובדיה להגדה של פסח (בפיסקא ויהי שם לגוי גדול), כתב בשם המגיד מדובנא ז\"ל, ליישב את קושיית הראב\"ע הנ\"ל, למה לא הזכירה התורה נס כזה מופלא שתלד יוכבד בת ק\"ל, והוא נס גדול מהנס שנעשה לשרה שילדה בת תשעים. וישב הוא, על פי משל בשני עניים מארחי פרחי שהיו מהלכים בדרך, ובאו בשיחה האחד עם רעהו, וכל אחד מהם היה מספר לחבירו על נגידי העיר וצדקתם, ויען האחד ויאמר, הנדיב רבי ישעיה מתושבי עירנו אין נדיב כמותו בכל האיזור, ותוך כדי סיפר, כי פעם ניגש לרבי ישעיה וביקש צדקה, ויושט לו רבי ישעיה שני זהובים שלמים. ויען חבירו לעומתו, לא כן הוא, אלא הנדיב רבי משה הוא הנדיב היותר גדול באיזורנו. כי פעם ניגשתי אליו וביקשתי ממנו צדקה ותיכף פשט רבי משה את ידו ויתן לי זהוב שלם. ויצחק חבירו ויאמר, וכי לא תדע כי ב' זהובים הם יותר מזהוב אחד. ויען חבירו ויאמר לו, אמור לי אימתי נתן לך ב' זהובים, ויאמר לו ביום פורים נכנסתי אליו והיה מבוסם כדבעי, ומרוב שמחה נתן לי ב' זהובים. ויאמר חבירו הלא כה דברי כי אין נדיב כר' משה, כי ביום פורים הכל שמחים ומתנדבים בעין יפה וברוח נדיבה ואם נתן לך בעת שמחתו ב' זהובים אין בזה כל חידוש. אבל אני הייתי אצל ר' משה בחודש תמוז ואעפ\"כ נתן לי זהוב אחד, וזה יורה על גודל נדיבותו.","b":false},{"t":"והנמשל הוא, כי הנה יוכבד ילדה את משה במצרים בעת שכל בתי ישראל היו מלאים בנסים מופלאים שהיו נשי ישראל יולדות ששה בכרס אחד (ראה שמו\"ר א, ח), ושאר נסים מופלאים, ואין נס לידת יוכבד נחשב לחידוש בעת ההיא. ברם שרה שילדה לתשעים שנה, הריהי דומה לר' משה הנדיב שמתנדב נדבה גדולה בחודש תמוז, ואף היא, בזמנה לא היו הרבה נסים כאלו, ולכן הנס ניכר ביותר, ולכן הזכירו הכתוב. וש\"י משיב דברים נכוחים.","b":false},{"t":"ואולי יש לומר שבאמת יוכבד לא נולדה בין החומות, אלא נולדה במצרים שנים רבות אחר ששהו שם, ועם כל זאת נכללה בחשבון השבעים נפש, שהרי גם בני יוסף מנשה ואפרים שנולדו במצרים נכללו בחשבון הזה, כמו שאמר הכתוב (להלן בראשית מו, כו-כז), כל הנפש הבאה ליעקב מצרימה, יוצאי ירכו וגו' כל נפש ששים ושש, ובני יוסף אשר יולד לו במצרים נפש שנים, כל הנפש לבית יעקב הבאה מצרימה שבעים. הרי מפורש שכלל הכתוב במנין השבעים אף את בני יוסף שנולדו במצרים, ואל תתמה למה מנה רק את יוכבד ולא את שאר הנולדים. דיש לומר שהיא הראשונה שנולדה שם, והשלימה את מספר נפש בית יעקב לשבעים (אלא שבזה ניתן לפרש את חשבון יוכבד במנין השבעים אבל במנין השלשים ושלש קשה לדחוק כן, וראה להלן בדברי הדעת זקנים והראב\"ע).","b":false},{"t":"והרשב\"ם ז\"ל (שם), כתב, שיוצאי ירכו של יעקב, היו ששים ותשעה, ויעקב עצמו הוא המשלים לשבעים נפש. ע\"ש. וכ\"כ בדעת זקנים מבעלי התוס' על הפסוק (בראשית מו, כז), כל הנפש לבית יעקב הבאה מצרימה שבעים, פירוש עם יעקב, וראש הענין מוכיח כך, דכתיב אלה שמות וכו', להודיע שיעקב מן המנין עם בניו, ונכלל עם בני לאה, שאין בפרטן אלא ל\"ב, והכתוב מונה אותם ל\"ג עם יעקב, לפי שהוא מן הנפש לבית יעקב הבאה מצרימה, ואם תרצה לידע מנינם מנה גם יעקב ותמצאם שבעים, ולפי מה שפירשתי למעלה (בפסוק אנכי ארד עמם, ע\"ש), א\"צ לומר שיהא יעקב מן המנין, כי הקב\"ה נמנה עמהם ומשלים המנין. עכ\"ל.","b":false},{"t":"וכן היא מסקנת רבינו אברהם ן' עזרא ע\"ה (בראשית מו, כג), וז\"ל, והנכון בעיני שיעקב בחשבון, וממנו יחל, כאילו אמר כל נפש בניו ובנותיו עם נפשו שלשים ושלש. והראיה שאמר בתחילה יעקב ובניו, וע\"ש שהאריך להוכיח כן מן הכתובים.","b":false},{"t":"ומה שאמרו רבותינו שיוכבד ילדה את משה בת ק\"ל, אפשר שחז\"ל באו לרמוז בזה ענין חשוב מאד, באומרם בת ק\"ל שנים ילדתו אמו למשה רעיא מהימנא ע\"ה. דהמקובלים אמרו (ראה פרשת לך לך מאמרים ח-ט ושם נתבאר הענין באורך), שכל ירידתנו מצרימה היא לקבץ פזורים, אותם ניצוצות הקדושה שירדו ונפלו ונתפזרו בין החומר והלבנים ע\"י אדם הראשון משך ק\"ל שנים שפירש מחוה והיה שרוי לבדו, יעו\"ש.","b":false},{"t":"והנה משה הוא שר צבא ישראל העומד עליהם לנחותם הדרך ולגואלם ממצרים, ואשר אליו ציוה ה' (שמות יא, ב), דבר נא באזני העם וישאלו, ועליו נאמר וַיַסַע משה את בני ישראל (שם טו, כב). כי הוא המוליך והוא המביא, ואיהו גופיה נולד לאמו בהיותה בת ק\"ל שנים, כי נשמתו הגיעה לאמו מקיבוץ גדול ומופלא הכולל את כל הק\"ל שנים שתקנו ישראל בהיותם במצרים כנגד פגם אדם הראשון, ודוק.","b":false},{"t":"[א\"ה - דבר ה' אמת בפי מרן המחבר נר\"ו, שכן מפורש בדברי רבינו האר\"י ז\"ל בספר לקוטי תורה פרשת שמות שכה כתב עה\"פ (שמות ב, א-ב), וילך איש מבית לוי ויקח את בת לוי, ותהר האשה ותלד בן ותרא אתו כי טוב הוא ותצפנהו שלשה ירחים. ויש לדקדק איך כשלקח עמרם את יוכבד קראה \"בת\", דכתיב ויקח את \"בת לוי\" ותיכף קרא אותה \"אשה\", דכתיב \"ותהר האשה\", וכי בזמן מועט כזה נעשית מבת לאשה.","b":false},{"t":"והענין כי ארז\"ל כי יוכבד בת ק\"ל שנה היתה וחזרה להיות בת, והסוד הוא כי יוכבד היתה גלגול חוה אשת אדה\"ר, וכמו שאדה\"ר פירש מחוה ק\"ל שנה עד שהוליד את שת, כן יוכבד גלגול חוה לא ילדה למשה שהוא גלגול שת עד ק\"ל שנה, ולכן נקראת \"בת\", לפי שאז נתעברה בה [נשמת] חוה, ואח\"כ תיכף נקראה \"אשה\", לרמוז על חוה האשה אשר נתת עמדי (בראשית ג, יב), כי להיותה עיבור חדש נקרא בת, ונקראת ג\"כ אשה, על שם האשה אשר וכו' כי גם חוה אחר ק\"ל שנה ילדה שת שהוא גלגול משה, ותבין בזה מאמרם ז\"ל (במדב\"ר יד, יא וראה שם יג, יט וראה לר\"י בעה\"ט בפי' לתורה במדבר ז, יג), על פסוק קערת כסף שלשים ומאה משקלה (במדבר ז, יג ועוד מקומות שם), ק\"ל כמנין ק\"ל שנה שפירש אדם מאשתו ועשה תשובה וזהו \"משקלה\" אותיות \"משה קל\" כי יוכבד אמו ילדתו לק\"ל שנה.","b":false},{"t":"ותרא אותו כי טוב. דע לך סוד נמרץ כי ביארנו כי יעקב אמר שני מגורי ק\"ל שנה מעט ורעים היו לתקן בו עון אדה\"ר באותן ק\"ל שנה שהוליד שידין רוחין לילין לכן קראם רעים, וכבר ביארנו לך כי סוד אלו שידין הנבראים מבעלי קריין הם סוד טיפות נשמות קדושות שמתלבשות בגוף כגון שידין ולילין הנעשין מן לילית אשה זרה וחוזרים להיות רעים מצד הרע. אמנם אלו נשמות היו צריכין תיקון בהכרח, לכן כל ק\"ל שנה הראשונים שהיו ישראל במצרים כל אותן הנשמות שנולדו בזמן ההוא היו אותן טפות שהוליד אדה\"ר בק\"ל שנה, שידין רוחין ולילין. וכשנולד משה אז כלו ונפסקו כולם, והוא התחיל להיות מצד הטוב ולא מצד הרע כבראשונה, וזה סוד ותרא אותו כי טוב (שמות ב, ב), והנה אם תסיר פ' שנה משנולד משה עד שיצאו ישראל ממצרים שהיו שם רד\"ו שנה ישאר ק\"ל נגד ק\"ל שנה של אדה\"ר שהוליד רוחין ולילין, ואח\"כ הוליד שת בנו כדמותו וכצלמו, וכן משה שהוא גלגול שת נולד אחר ק\"ל שנה, ע\"כ. והדברים נפלאים וכ\"ה בשער הגלגולים הקדמה לו, ובשער הפסוקים סדר נשא ושם בתהלים מזמור קלה, ע\"ש. ואוסיפה לך, באגב מה שעלה ברעיוני בהיותי בזה, דהנה אמרו רבותינו (שמו\"ר א, ח), שנשי ישראל במצרים היו יולדות ששה בכרס אחד, ונראה לפרש הטעם, משום דהיה ענין תיקון חטא טיפי הזרע של אדה\"ר ומנין שש הוא רומז אל מדת \"יסוד\", לכן עשה הי\"ת להם הך סימנא, להראות להן שירדו למצרים כדי לתקן החטא הזה, ודו\"ק. יבח\"ר].","b":false}]},{"id":"23","t":"הבן דומה לאמו בתכונותיו והבת דומה לאביה בתכונותיה","p":[{"t":"אֵלֶּה בְּנֵי לֵאָה אֲשֶׁר יָלְדָה לְיַעֲקֹב בְּפַדַּן אֲרָם וְאֵת דִּינָה בִתּוֹ וגו': (מו, טו)","b":true},{"t":"ופירש\"י ז\"ל, אלה בני לאה וגו' ואת דינה בתו, הזכרים תלה בלאה [שנא' בני לאה], והנקבות תלה ביעקב, [שנא' ואת דינה בתו], ללמדך, אשה מזרעת תחילה יולדת זכר. איש מזריע תחילה יולדת נקבה. עכ\"ל. ומקור הענין בדברי רבותינו במסכת נדה (לא, א).","b":false},{"t":"והנה השם לבו לראות את טבעי בני אדם ושאר תכונותיהם, בשכלו יבין ובעיניו יראה כי טבעי הבת והנהגותיה דומים בדרך כלל לאביה, ואילו התכונות של הבן דומים בדרך כלל לאמו.","b":false},{"t":"ואמרתי בס\"ד, שלזה דקדקו חז\"ל ואמרו (מו\"ק יח, ב סוטה ב, א), בת פלוני לפלוני, והיינו כי על הבת אמרו \"בת פלוני\" ותלו אותה באביה, ואילו אצל הבן לא אמר \"לבן פלוני\", אלא \"לפלוני\". והטעם, כי הבן אינו דומה בהכרח לאביו.","b":false},{"t":"ועוד שהבת צנועה היא, כמו שנאמר (תהלים מה, יד), כל כבודה בת מלך פנימה, וא\"א להכיר את טבעיה ותכונותיה, על כן אמר בת פלוני, שאם אתה מכיר את האב, הרי תוכל להבין ולהכיר את בתו ואת פעליה. אבל את הבן לא תוכל להכיר מתוך מעשי האב, כי הבן דומה לאמו. ואמו טמונה וספונה בבית פנימה, ועל כן אמר בת \"פלוני\" היינו שתוכל להכיר את טבע הבת ע\"י שתכיר את אביה שהוא הפלוני שאמרו חז\"ל. ופעם כשאמרתי דבר זה בהיותי במסיבת שבע ברכות, אמרו לי כי דבר זה כתבו מרן החיד\"א ז\"ל. ות\"ל שכיונתי לד\"ק.","b":false},{"t":"[א\"ה – ועפי\"ז יש לפרש הפסוק (משלי טו, כ) בן חכם ישמח אב וכסיל אדם בוזה אמו, וכן נאמר (שם י, א) בן חכם ישמח אב ובן כסיל תוגת אמו. והיינו כי בעת שהאדם רואה שבנו חכם הריהו שמח גם באשתו, כי ממנה תוצאות החכמה. אבל כשהבן הוא כסיל, מגיע תוגה ובזיון לאמו כי בעלה תולה הכסילות בה, ודוק. יבח\"ר].","b":false}]},{"id":"23","t":"אין להקל ראש בענין יחוס המשפחות","p":[{"t":"וּבְנֵי שִׁמְעוֹן יְמוּאֵל וְיָמִין וְאֹהַד וְיָכִין וְצֹחַר וְשָׁאוּל בֶּן הַכְּנַעֲנִית: (מו, י)","b":true},{"t":"ופירש\"י ז\"ל בן הכנענית בן דינה שנבעלה לכנעני וכו'. ומקור הדברים בדברי רבותינו (ב\"ר פ, יא).","b":false},{"t":"ויש ללמוד מזה כמה צריך האדם להזהר בעניני יוחסין. ולא יקל ראש בחשיבותם, ולא יתפתה ללכת אחר תאות לבו ולשאת אשה שאינה מיוחסת ואינה הוגנת ואינה ראויה לו, שהרי דינה, בתו של יעקב אבינו ע\"ה היתה, ובתה של לאה אמנו היתה, והיא אחותם של השבטים שבטי י-ה, ונלקחה באונס אל בית שכם בן חמור אשר עינה אותה, ועם כל זה נשאר הדבר לדראון עולם, עד שנכתב בתורה, ושאול בן הכנענית.","b":false},{"t":"ועיין עוד בדברי הראב\"ע ע\"ה (שם), שהלך בדרך אחרת, ואמר שפירש לנו הכתוב שאול בן \"הכנענית\" כי כל השבטים נזהרו שלא לשאת כנעניות, אלא ארמיות ומצריות, ואדומיות, ומדיניות, והזכיר זו לבדה, בעבור שעשה שמעון שלא כהוגן לקחת כנענית, וע\"ז הדבר הזכיר מות ער ואונן בעבור היותם בני כנענית, עכ\"ל, וגם מזה אנו למדים עד כמה חמור הענין לשאת אשה שאינה הוגנת, עד שהתורה הזכירתו לגנאי רח\"ל, ואשרי השם לבו.","b":false},{"t":"וראה מה שאמרו רבותינו (קדושין ע, א ותנדא\"ר פ\"א), כל הנושא אשה שאינה הוגנת לו אליהו כופתו והקדוש ברוך הוא רוצעו, ותנא, על כולם אליהו כותב והקדוש ברוך הוא חותם אוי לו לפוסל את זרעו ולפוגם את משפחתו, ולנושא אשה שאינה הוגנת לו.","b":false}]},{"id":"23","t":"ויקם יעקב","p":[{"t":"וַיָּקָם יַעֲקֹב מִבְּאֵר שָׁבַע וַיִּשְׂאוּ בְנֵי יִשְׂרָאֵל אֶת יַעֲקֹב אֲבִיהֶם וְאֶת טַפָּם וְאֶת נְשֵׁיהֶם בָּעֲגָלוֹת אֲשֶׁר שָׁלַח פַּרְעֹה לָשֵׂאת אֹתוֹ: (מו, ה)","b":true},{"t":"יש לומר בזה, שאם עד עתה היה יעקב הולך למצרים רק מפני אהבתו לבנו וגעגועיו עליו אשר רבו כמו רבו, ולא יכול עוד להתאפק. הרי מעתה אחרי החזון הנורא, שנגלה אליו האלהים במראות הלילה והבטיחו לרדת עמו למצרים. מעתה שמח יעקב וקם ונתעודד, בכחות חדשים, ובהתרוממות הנפש, כי עתה קיבל אישור וחיזוק מאת הי\"ת על מעשיו.","b":false},{"t":"ועל כן נאמר, \"ויקם\" יעקב מבאר שבע, כי שם שבע רוב נחת דקדושה מהחזון הגדול שראה, כי נגלתה לו השכינה, והבטיחו הי\"ת לרדת עמו מצרימה ולהעלותו הוא וזרעו משם. והיתה לו תקומה גדולה כל כך, שהשפיעה שפע גדול עליו ועל בניו וכל אשר להם, ויבואו מצרימה יעקב, וכל זרעו אתו.","b":false}]},{"id":"23","t":"מעלת הקבורה בארץ ישראל ומעלת נפשות ישראל","p":[{"t":"אָנֹכִי אֵרֵד עִמְּךָ מִצְרַיְמָה וְאָנֹכִי אַעַלְךָ גַם עָלֹה וְיוֹסֵף יָשִׁית יָדוֹ עַל עֵינֶיךָ: (מו, ד)","b":true},{"t":"וקשה שהרי לא מצינו שעלה יעקב לארץ ישראל, אלא מת במצרים. ולכן פירש רש\"י ז\"ל, גם עלה, שנקבר עם אבותיו, במערת המכפלה. עכ\"ל. וכן הוא בפירוש רבינו אברהם אבן עזרא ז\"ל, וז\"ל וטעם אעלך גם עלה, שיקבר בארץ ישראל. עכ\"ל. וכן פירש הרשב\"ם ז\"ל.","b":false},{"t":"ולמדים אנו מזה את גודל מעלתה של ארץ ישראל, כי גם לאחר מיתתו של אדם היא נותנת לו מעלות ועולה ומתעלה על ידה. וכבר אמרו רבותינו (תוספתא ע\"ז פ\"ה וכתובות קיא, א), כל הקבור בארץ ישראל כאילו קבור תחת המזבח, כתיב הכא (שמות כ, כא), מזבח אדמה תעשה לי וכתיב התם (דברים לב, מג), וכפר אדמתו עמו. ואעפ\"י שאמרו בגמרא (שם), אינו דומה קולטתו מחיים, לקולטתו אחר מיתה, מ\"מ חשיבותה של ארץ ישראל שהיא מכפרת ומטהרת את הנפש גם אחר מיתה. וכן מצינו בהדיא בירושלמי (כלאים ט, ג וכ\"ה שם בכתובות יב, ג וכ\"ה בב\"ר צו, ה), רבי בר קיריא ורבי לעזר הוון מטיילין באיסטרין, ראו ארונות שהיו באין מחוצה לארץ לארץ. אמר רבי בר קיריא לרבי לעזר מה הועילו אלו, אני קורא עליהם ונחלתי שמתם לתועבה בחייכם ותבואו ותטמאו את ארצי במיתתכם (ירמיה ב, ז). אמר ליה כיון שהן מגיעין לארץ ישראל הן נוטלין גוש עפר ומניחין על ארונן, דכתיב וכפר אדמתו עמו. והיינו דס\"ל דגם זה מתכפר, ודי בנתינת גוש עפר של ארץ ישראל על הארון, וכבר הוא מתכפר, וראינו ששתק רבי בר קיריא כששמע את תשובת רבי לעזר, ובאמת שמצינו בתלמוד (מו\"ק כה, ב), שהעלו כמה וכמה צדיקים לקוברם בארץ ישראל אחר מיתה, וקי\"ל מעשה רב, (וראה בענין זה לג\"ע מרן שליט\"א בשו\"ת יביע אומר ח\"ו חיו\"ד סי' ל\"א שהאריך בהך ענינא, לך נא ראה נפלאות מתורתו). וע\"כ מבטיחו הקב\"ה ליעקב אבינו שלא יתיירא מרדת מצרים כי הוא מבטיחו שיעלהו משם ויזכה להיות קבור בארץ ישראל.","b":false},{"t":"ועוד רואים מזה את יחודם וגדולתם של עם ישראל, שאינם כלים במיתת הגוף, אלא יש להם נפש רוח ונשמה דקדושה שהם חיים וקיימים לעד, ועדיין עולים ומתעלים גם לאחר מיתה והיינו דכפל הכתוב בלשונו אנכי \"אעלך גם עלה\", כלומר, עליה אחר עליה, וכמאמר חז\"ל (ראה ברכות סד, א וראה מו\"ק כט, א), צדיקים אין להם מנוחה, לא בעוה\"ז ולא בעוה\"ב, אלא הולכים מחיל אל חיל, וגם אחרי מותם. דאי לאו הכי מה תועלת להעלות את גוף האדם אחר מותו. וא\"כ נמצינו למדים מכאן גודל שבח הארץ, וגם שבח עם ישראל.","b":false}]},{"id":"23","t":"הצדיקים צועקים אל הי\"ת ונענים מיד","p":[{"t":"וַיֹּאמֶר אֱלֹהִים לְיִשְׂרָאֵל בְּמַרְאֹת הַלַּיְלָה וַיֹּאמֶר יַעֲקֹב יַעֲקֹב וַיֹּאמֶר הִנֵּנִי, וַיֹּאמֶר אָנֹכִי הָאֵל אֱלֹהֵי אָבִיךָ אַל תִּירָא מֵרְדָה מִצְרַיְמָה כִּי לְגוֹי גָּדוֹל אֲשִׂימְךָ שָׁם: (מו, ב-ג)","b":true},{"t":"אשרי העם שככה לו, ואשרי האיש אשר מקריב קרבן ומתחנן לפני קונו, ומיד נענה, וה' נגלה עליו בבירור, ואומר לו, תפילתך התקבלה, אל תירא מרדת מצרימה, כלומר אם מן הירידה אתה מתיירא, אין לך מה לירא עוד, כי אנכי ארד עמך מצרימה, ואנכי אעלך גם עלה.","b":false},{"t":"ולפי מה שכתבתי לעיל (מאמר י), משם הרמב\"ן ז\"ל, שיעקב אבינו נתיירא ממדת הדין, ועל כן זבח זבחים לאלהי אביו יצחק, כדי למתק את מדת הדין שהיא מדת אביו יצחק. נמצא א\"כ שמיד נענה יעקב כפי שביקש. וזה אמרו, ויאמר אלהים לישראל במראות הלילה וגו' אל תירא מרדה מצרימה, כלומר שתפלתו התקבלה, וקרבנו היה רצוי, עד שמדת הדין שהיא בחינת אלהים, אף היא נתהפכה לרחמים, ואמרה לו \"אל תירא\", כי נתמתקו הדינים, ואפילו הדינים הקשים ביותר שהם בבחינת \"במראות הלילה\". וגם את זה אמר לו הי\"ת בנעימה, וכפל \"יעקב יעקב\", שהוא מורה על החיבה, ואח\"כ גילה לו הי\"ת איך נתמתקה מדת הדין, ויאמר, אנוכי \"האל\" אלהי אביך, היינו, כי הן אמת שאביך יצחק שורשו במדת הדין ולכן לו יאות הנהגת הדין, אבל אתה אל תירא מזה, כי לך הקדמתי תיבת \"אל\" שהיא מן החסדים, כדכתיב (תהלים נב, ג), חסד אל כל היום. ונהפכה מדת הדין למדת רחמים. ומשם צוה לו הי\"ת את הברכה, ומשם הבטיחו \"אל תירא\", ומשם נתברך \"לגוי גדול אשימך\".","b":false},{"t":"והוא מפליא לעשות, איך יעקב אבינו ע\"ה צועק ונענה תיכף ומיד, כ\"כ מהר וברור. ישתבח שמו לעד. וזה כחם ומדרגתם של אבותינו הקדושים, שהם מרכבה למקום ברוך הוא.","b":false}]},{"id":"23","t":"למה זבח יעקב זבחים ל\"אלהי יצחק אביו\" ולא לאלהי אברהם ויצחק","p":[{"t":"וַיִּסַּע יִשְׂרָאֵל וְכָל אֲשֶׁר לוֹ וַיָּבֹא בְּאֵרָה שָּׁבַע וַיִּזְבַּח זְבָחִים לֵאלֹהֵי אָבִיו יִצְחָק: (מו, א)","b":true},{"t":"ופירש\"י ז\"ל, חייב אדם בכבוד אביו יותר מכבוד זקנו. לפיכך תלה ביצחק ולא באברהם. עכ\"ל. ורשב\"ם ז\"ל פירש, שעשה שם יצחק מזבח בבאר שבע, כשנגלה לו הקב\"ה כמו שנאמר בפרשת אלה תולדות יצחק, ועשה גם הוא שם זבחים, כמו שעשה אביו. עכ\"ל.","b":false},{"t":"ואפשר לומר שגם הרשב\"ם מודה למה שכתב רש\"י ז\"ל, אלא שהוסיף בדבריו טעם נוסף. והוא, כי יעקב היה יכול לומר שעושה זבחים לאלהי אבותיו והיה כולל בזה את אברהם ואת יצחק יחדיו, ולמה הזכיר את שם אביו יצחק לחוד. לזה פירש הרשב\"ם ז\"ל שנהג יעקב כאביו יצחק שעשה מזבח בבאר שבע ועשה עליו זבחים.","b":false},{"t":"שוב ראיתי להרמב\"ן ז\"ל שכתב על פירש\"י ז\"ל שאינו מספיק, שהרי היה ראוי לומר שעשה יעקב מזבח לאלהי אבותיו בלי שייחד אדם וכו', ועוד שיכול לומר, ויזבח זבחים לה', כמו שנאמר גבי אברהם (בראשית יב, ז), ויבן מזבח לה'. וכתב בתוך דבריו בזה\"ל, אבל הפסוק הזה יש בו סוד, יגלה לנו אותו שם בבראשית רבה (צד, ה), כי כאשר בא יעקב לרדת מצרימה, ראה שהגלות יתחיל בו ובזרעו, ופחד ממנה, וזבח זבחים רבים לפחד אביו יצחק, שלא תהא מדת הדין מתוחה כנגדו, ועשה זה בבאר שבע, שהיא בית תפלה לאבותיו, ומשם נטל רשות בלכתו לחרן. ואמר הכתוב זבחים, להודיע עולות כאבותיו, שאברהם עולות הקריב, ורבותינו אמרו (זבחים קטז, א), לא הקריבו בני נח שלמים, אלא עולות הקריבו וכו', אבל יעקב מפני פחד ה' הקריב שלמים להשלים אליו כל המדות. וכמו שדרשו (ספרא ויקרא טז, א), שלמים שמשלימים שלום בעולם, והנה היתה תחלת כונתו במדת הגבורה שהיא הקרובה אליו, וזהו הטעם שהזכירו בבראשית רבה (צד, ה), שחייב אדם בכבוד אביו יותר מכבוד זקנו, וזהו הטעם שאמרו שם בלשון אחר, בתחלה שואלין בשלום התלמיד, ואח\"כ שואלין בשלום הרב. וע\"ש שהאריך עוד בעומק וברוחב כדרכו הקדושה הפלא ופלא. ועל כל פנים לפירוש רשב\"ם ז\"ל אתי שפיר שאמר לאלהי אביו יצחק ואחז בדרכו של הרמב\"ן ממש. וכנ\"ל.","b":false},{"t":"והנראה בכונת דברי הרמב\"ן ז\"ל הנ\"ל, שיעקב חשש ממדת הדין שהיא בחינת אלהים כידוע, והיא היא מדתו של אביו יצחק, וחשש שמא יפגע ממדת הדין, דלאו כל מוחא סביל דא, וראה שאין בניו יכולים לעמוד במדה זו כאביו יצחק שהיה קדש קדשים, ולכן רצה למתק את הדינים, ועל כן נאמר, ויזבח זבחים לאלהי אביו יצחק, דאין הדין נמתק אלא משרשו (ראה ע\"ח שער י\"ג פי\"א ושעה\"כ דרושי העמידה דרוש ה' ובלקוטי תורה פרשת וישב ופע\"ח שער השופר פ\"א). ועל כן זבח זבחים שהם שלמים שמשלימים וממתקים את מדתו של יצחק, ומשך להם המיתוק מן שם אלהים, משורש הדינים, ודינים ממותקים גדולים מן החסדים דמעיקרא כאמור בדברי רבינו האר\"י ז\"ל במקומות רבים, ולא אמר לאלהי אביו אברהם דהוא ממותק ועומד, דהא חסד לאברהם כתיב (מיכה ז, כ), ולא על זה היה יעקב צריך לדאוג בשעה זאת, אלא מפחד יצחק מדת הגבורה.","b":false},{"t":"ושו\"ר במאור ושמש שם שכתב כעין הדברים הללו מדנפשיה, ע\"ש ותרוה נחת, ולענ\"ד הן הן דברי הרמב\"ן ז\"ל, ויעו\"ש בדברי הרמב\"ן ששידד מערכות בכל התורה, ורמז בדבריו את כל מה שביארו האחרונים, לכל הרמ'ז הרומ'ז על האר'ש. זכותו יגן עלינו אמן.","b":false},{"t":"ועוד יש לומר דזבחים אלו זבחי תודה הם, כמאמר הכתוב בתהלים (קז, כב), ויזבחו זבחי תודה ויספרו מעשיו ברינה וגו'. ואחר הבשורה הגדולה שקיבל יעקב אבינו ע\"ה, כי עוד יוסף חי, וגם חי בקדושה ובטהרה, ועודנו לומד תורת ה', ודבק בדרכי אבותיו. מיד כשהגיע למקום הראוי לזבוח, זבח תודות להי\"ת, כדי להודות ולהלל על כל טובותיו ונפלאותיו.","b":false}]},{"id":"23","t":"עיקר שמחת האב בבניו היא כשהבנים הולכים בדרך ה'","p":[{"t":"וַיֹּאמֶר יִשְׂרָאֵל רַב עוֹד יוֹסֵף בְּנִי חָי אֵלְכָה וְאֶרְאֶנּוּ בְּטֶרֶם אָמוּת: (מה, כח)","b":true},{"t":"כתב הרשב\"ם ז\"ל, וז\"ל, ואני הצעיר שמעתי, רב עוד יוסף בני חי, אתם אומרים עוד יוסף חי, וכי הוא מושל, רב לי במה שהוא עדיין חי אפילו אינו מושל, אלכה ואראנו בטרם אמות וכו'. עכ\"ל.","b":false},{"t":"ואולי זו היא כונת רבינו הראב\"ע ז\"ל (שם), שכתב, רב עוד יוסף, רב לי זאת השמחה. עכ\"ל. דאפשר שבא ג\"כ להדגיש שיעקב אומר שדי לו בשמחה זאת שבנו עדיין חי. וכמ\"ש הרשב\"ם ז\"ל.","b":false},{"t":"ויומתק עפ\"י מה שאמרו רבותינו שכשבאו האחים לבשר לאביהם שמצאו את יוסף, נתנו לו את הסימן שאמר להם יוסף, והם הלכות לויה ועגלה ערופה שלימדו יעקב אבינו בעת שנפרד ממנו. ובנוסף לזאת ראה יעקב את העגלות אשר שלח יוסף (בראשית רבה צד, ג ושם צה, ג וראה תנחומא ויגש פי\"א).","b":false},{"t":"ולפי זה יש לפרש דהכי אמר יעקב אבינו ע\"ה אל בניו, אתם אומרים לי שיוסף בני חי והוא מושל בכל ארץ מצרים וכו', אך כל זה איננו שוה לי, אם ח\"ו אינו הולך בדרך שהדרכתיו מיום לידתו, והשקעתי את כל כחי בחינוכו, כדי שימשיך בדרך אבותי אברהם ויצחק. וכבר דרשו חז\"ל (ב\"ר פד, ח), על הפסוק (בראשית לז, ג), כי בן זקונים הוא לו, שכל מה שלמד יעקב אבינו ע\"ה משם ועבר מסר לו ליוסף. וכדתרגם אונקלוס (שם), ארי בר חכים הוא ליה. אך כאשר ראה יעקב את העגלות ומסרו לו את הסימן שמסר בזמנו ליוסף, אז ידע והבין שיוסף נשאר באמונתו ותומתו עם ה' אלהיו, והוא שומר את מסורת אבותיו, כאשר היה עוד בבית אביו, ולא נבהל בזמן העבדות, ולא זחה דעתו עליו מן המלכות, אז שמח יעקב ולבו רחב בקרבו, ויאמר ישראל \"רב עוד יוסף בני חי\", היינו, חי בתורתו וחי ביראתו, שזו היא החיות האמיתית, כי הם חיינו, וחי בהם. ובזה היתה שמחת יעקב שלמה, ותיכף אמר אלך ואראנו.","b":false}]},{"id":"23","t":"בחיוב מצות לויה","p":[{"t":"וַיְשַׁלַּח אֶת אֶחָיו וַיֵּלֵכוּ וגו: (מה, כד)","b":true},{"t":"צריכים להבין מהו שאמר הכתוב וישלח את אחיו, שלכאורה הוא לשון מיותר, כי מה לו להאריך בזה. ורבינו עובדיה ספורנו כתב, פטרן ונתן להם רשות, כמו שלחני כי עלה השחר (בראשית לב, כז). וכן, שלחני ואלכה לאדוני (שם כד, נו). עכ\"ל.","b":false},{"t":"ובאור החיים הקדוש כתב, וישלח את אחיו, פירוש כולם, ובנימין עמהם, וכן הוא אומר בדברי יוסף מהרו ועלו וכו' והנה עיניכם וגו', ועיני אחי בנימין. הרי כי מצדיק את הדברים בלב יעקב, מעדות בנימין הרואה וכו'. עכ\"ל.","b":false},{"t":"ואפשר להוסיף שבכונה תחילה נאמר וישלח את אחיו, ללמדנו שיוסף ליוה את אחיו בדרכם בלוית חן וחסד, ואז הלכו לדרכם לבטח. ובזה הענין גופו הזכיר להם את ענין פרשת עגלה ערופה שלימדו אביו, אשר מביאים אותה זקני העיר, ואומרים ידינו לא שפכו את הדם, כמו שמפורש בתורה בסוף פרשת שופטים (דברים פרק כא), כי ימצא חלל באדמה וגו', לא נודע מי הכהו ויצאו זקניך ושופטיך ומדדו אל הערים וגו'. והיה העיר הקרובה אל החלל, ולקחו זקני העיר עגלת בקר, אשר לא עובַּד בה, אשר לא משכה בעול. וכל זקני העיר ההיא וגו'. וענו ואמרו ידינו לא שפכו את הדם הזה, ועינינו לא ראו. כפר לעמך ישראל וגו'.","b":false},{"t":"ואמרו חז\"ל (משנה סוטה ט, ו), והביאו רש\"י ז\"ל (דברים כא, ז), ידינו לא שפכו - וכי עלתה על לב שזקני בית דין שופכי דמים הם, אלא לא ראינוהו ופטרנוהו בלא מזונות ובלא לויה.","b":false},{"t":"ואפשר שראו האחים שיוסף מלוה אותם בכבודו ובעצמו, ואמרו לו שלא יצא מביתו ללוות אותם מפני כבוד המלכות, אך הוא סירב ויצא ללוותם, וביאר להם את חשיבות המצוה ותוצאותיה שלמד אצל אביו, ובהיותו בזה אמר להם לספר את הענין לאביו, ואז יהא לו סימן מובהק שיוסף בנו חי.","b":false},{"t":"ושו\"ר בדעת זקנים מבעלי התוספות, (בראשית מה, כז), שכתבו וז\"ל, וידברו אליו את כל דברי יוסף - פירש\"י, סימן מסר להם, כשפירש ממנו היה עוסק בפרשת עגלה ערופה. וצריך פירוש לפירושו. והכי רוצה לומר, כי כשפירש יוסף מאביו היה מלוה אותו כדכתיב (בראשית לז, יד), וישלחהו, שהוא לשון לויה כמו וישלחו דכתיב גבי אברהם (בראשית יב, כ), דמתרגמינן ואלויאו. ואמר לו יוסף חזור בך, ואמר לו יעקב, בני גדולה לויה שעליה נתוספה פרשה אחת בתורה דכתיב (דברים כא, ז), ידינו לא שפכה, וכי תעלה על דעתך שב\"ד שופכי דמים אלא לא ראינוהו ופטרנוהו בלא לויה, הא אם ראוהו ולא ליווהו מעלה עליהם כאלו שפכו דמים. והיינו פרשת עגלה ערופה שהיה עסוק בה וכו'. ע\"כ.","b":false},{"t":"ושמחתי ע\"ז שלפי זה גם הוא נהג באֶחיו, כאשר נהג בו אביו, וכפי שכתבתי. כי האחים היו אומרים לו שלא יטרח ללוותם כי הוא מלך, ואז פירש להם יוסף את חשיבות מצות הלויה, ובודאי אמר את הדברים משם אומרם, וכל זה סיפרו לאביהם, ותחי רוח יעקב.","b":false}]},{"id":"23","t":"הטעם למה נתן יוסף לבנימין כסף וחליפות ולשאר האחים לא נתן","p":[{"t":"לְכֻלָּם נָתַן לָאִישׁ חֲלִפוֹת שְׂמָלֹת וּלְבִנְיָמִן נָתַן שְׁלשׁ מֵאוֹת כֶּסֶף וְחָמֵשׁ חֲלִפֹת שְׂמָלֹת: (מה, כב)","b":true},{"t":"ורבותינו במסכת מגילה (טז, ב), אמרו על זה, וכי אפשר דבר שנצטער בו אותו צדיק יכשל בו, א\"ר בנימין בר יפת רמז רמז לו, שעתיד לצאת ממנו בן שיצא מלפני המלך בחמשה לבושי מלכות. שנאמר (אסתר ח, טו), ומרדכי יצא מלפני המלך בלבוש מלכות תכלת וחור ועטרת זהב גדולה ותכריך בוץ וארגמן.","b":false},{"t":"ובאמת עדיין קשה שגם כדי לרמוז לו רמז חשוב זה, היה לו להטמין את הענין ברמז באופן אחר, ולא לתת לו חמש חליפות ושלש מאות כסף, לעין כל ונוכחת. כי הרי יוסף אמר לאחיו אל תרגזו בדרך (בראשית מה, כד). ומה גם, הלא הוא בעצמו סבל ושתה את כוס תרעלת הקנאה עד תומה, מפני כתונת פסים אחת שעשה לו אביו. ואיך עתה עושה דבר גדול יותר להפלות בין האחים.","b":false},{"t":"ולפי מה שביארנו, בפרשת מקץ (מאמר י), שכל מה שהתנכר יוסף לאחיו, היה כדי לבחון אותם ולראות האם שבו בתשובה אמיתית, או שהיו אלה רק רגעי התעוררות חולפים, והעמידם למבחן בדבר השקול למה שנכשלו בו, לראות התעמוד להם תשובתם, ולהמשיך באחוה גם בעת כזאת. ולפי מה שאמרו בגמ' הנ\"ל אתי שפיר, דלפי האמת לא העדיף יוסף את בנימין על פני שאר האחים, אלא בא לרמוז לבנימין על מרדכי הצדיק, ואתיא ממילא שיוסף בחן בזאת את שאר האחים שלא ידעו מהרמז, לראות האם יעמדו בנסיון ולא יקנאו.","b":false},{"t":"ובזה מובן שבכונה תחילה הבדיל ביניהם, והעדיף לבנימין, על אחת כמה וכמה, ובכל זאת הלכו לשלום לאביהם, ושבו כאיש אחד בלב אחד, אז ידע כי סרה מהם הקנאה והשנאה, ומעתה מה טוב ומה נעים שבת אחים גם יחד.","b":false},{"t":"[א\"ה - אעתיק בזה ממש\"כ בעניי בהך ענינא, דהנה הרב מהרש\"א בח\"א למגילה (שם), כתב בזה, דבכסף שנתן יוסף לבנימין אין סיבה שיהא לשאר האחים קנאה עליו, כיון דהוא אחי יוסף גם מאמו, ומובן הדבר שיאהבהו יותר ממה שיאהב אותם, אלא דעל כל פנים יש חשש קנאה על הבגדים שהם בגלוי, והיה נראה כי יוסף בא לרמוז בנתינתם שאינו שונא לבנימין לפי שבנימין לא היה שותף במכירתו, ובזה יש חשש קנאה בינו לשאר האחים, לזה קאמר בגמ' שהוא לרמוז לבנימין שיצא ממנו מרדכי שיצא מלפני המלך בחמשה בגדים. זת\"ד ע\"ש.","b":false},{"t":"ותירוץ אחר שמעתי בזה, והוא, כי קודם שנמכר יוסף היה מנהג השבטים שכל אחד מן הבנים משמש את אביו חודש אחד בשנה, והנה אחר שנמכר יוסף נשאר חודש אחד פנוי, וחלקוהו בין שאר האחים, והנה לכשתצא ותחשב תראה כי היו עשרים ושנים חודשי עבודה. שהרי מעת שיצא יוסף מבית אביו עד שנתראה עם אחיו עברו כ\"ב שנה. וא\"כ הרי שנוספו בזמן ההוא לכל אחד מן האחים ב' חודשים שצריכים לשמש את אביהם יתר על מה שהיו נוהגין בתחילה. וגם בנימין עבד חודשיים נוספים, והן שכר פועל ליום חמש כסף, ולכשתכפיל חמש כסף בששים יום הרי לך שלש מאות כסף, ומה שנתן יוסף שלש מאות כסף לבנימין הוא עבור טרחתו במה שטרח ושימש את אביו במקומו. אמנם לשאר האחים לא נתן מעות, לפי דאיהו אזיקו אנפשייהו במה שמכרוהו. ע\"כ. אמנם קשה לי דלפי\"ז היה ליוסף ליתן שלש מאות כסף גם לראובן, שהרי גם הוא לא נשתתף במכירתו. וגם מה יענו על חמש החליפות.","b":false},{"t":"ולכן לענ\"ד נראה בס\"ד, דהנה כל השבטים באו למצרים וקנו תבואה ויוסף השיב לכל אחד מהם את צרור כספו בשקו, וגם שמעון אע\"פ ששם אותו בבית האסורים מ\"מ נתן לאחיו שיקחו את שקו ובו צרור כספו לארץ כנען, והיחיד שלא קיבל היה בנימין, לכך נתן לו יוסף שלש מאות כסף עם שלש חליפות יתירות על אחיו שזה היה שיעור הכסף שהחזיר לכל אחד, ולכן בודאי שאין שום סיבה לקנאה. ומה שלא נתן לבנימין כסף לבד, על זה בא מאמר חז\"ל לאמר, שבא לרמוז לו על מרדכי הצדיק שיצא ממנו, והוא יצא מלפני המלך בחמשה מלבושי מלכות, ודוק. יבח\"ר].","b":false}]},{"id":"23","t":"ההבדל בין הכבוד האמיתי לכבוד המדומה","p":[{"t":"וְהִגַּדְתֶּם לְאָבִי אֶת כָּל כְּבוֹדִי בְּמִצְרַיִם וְאֵת כָּל אֲשֶׁר רְאִיתֶם וגו': (מה, יג),","b":true},{"t":"שמעתי באומרים לי שהגר\"א ז\"ל אמר, שבכל מקום שכתוב בתנ\"ך, כבוד מלא וא\"ו, אות הוא שמדובר על כבוד הי\"ת או על כבודה של תורה, כגון, כבוד חכמים ינחלו (משלי ג, לה), וכבד בלא וא\"ו, רומז על הצלחות העוה\"ז, וכמו שאמרו בני לבן על יעקב אבינו ע\"ה (בראשית לא, א), ומאשר לאבינו עשה את כל הכבד הזה. וכונתם לצאן ולבקר ושאר קניני העוה\"ז, וע\"כ חסר שם אות וא\"ו, (וראה מנחת שי במדבר יד, כא).","b":false},{"t":"והרה\"ק מקאמרנא ע\"ה בספר היכל הברכה פירש את מאמר יוסף לאחיו (בראשית מה, יג), והגדתם לאבי את כל כבודי בארץ מצרים, תיבת \"כבודי\" מלאה וא\"ו ללמד, שנתמלא הכבוד מן יוסף צדיק יסוד עולם, ואין בכל התורה כבוד אדם מלא חוץ מזה. ע\"ש. וראינו שאין ענין הכבוד ההוא כבוד גשמי, אלא כבוד מסטרא דקדושה, שבא ליוסף מחמת קדושתו וצדקתו.","b":false},{"t":"וכבר כתבתי בכמה מקומות (ראה בהקדמת שמע שלמה ח\"א ובספרנו זה פרשת וישב מאמר ב), שהאות וא\"ו היא בחינת התורה הקדושה, והיינו, כשהכבוד מחובר לתורה הקדושה, אז יש בו וא\"ו, ואם נחסר ממנו אות וא\"ו סימן מובהק הוא שלא מדובר בכבוד תורה ובכבוד אמת, אלא בהבלי העולם.","b":false},{"t":"ובאמת לא האמין יעקב אבינו לבניו שיוסף עודנו חי, עד שמסרו לו דברי תורה שלמד עם יוסף בעת פרידתו ממנו, כדכתיב (בראשית מה, כז), וידברו אליו את כל דברי יוסף אשר דיבר אליהם, וירא את העגלות וגו', ופירש\"י ז\"ל, סימן מסר להם במה היה עוסק כשפירש ממנו, בפרשת עגלה ערופה. וזהו שאמר וירא את העגלות אשר שלח יוסף, ולא נאמר אשר שלח פרעה. עכ\"ל. ומקור דבריו בבראשית רבה (צד, ג ושם צה, ג וראה תנחומא ויגש פי\"א).","b":false},{"t":"נמצא שעיקר הדבר שרצה יוסף שיגידו לאביו היא התורה הקדושה שלמד עמו ולכן נאמר פה והגדתם לאבי את כל כבודי וכבודי מלא וא\"ו.","b":false},{"t":"[א\"ה - עוד יראה בהקדים דברי הרה\"ק מוהר\"ן מברסלב בספר לקו\"מ (ח\"א סי' יא), שכתב שם בענין הכבוד האמיתי ותוך הענין כתב, וכבוד בשלמות, אינו כי אם על ידי וא\"ו שימשיך לתוכה, כי בלא וא\"ו נשאר כבד פה (שמות ד, י), ועל ידי וא\"ו הוא בבחינת (תהלים ל, יג), \"כבוד ולא ידם\", כי כל מקום שנאמר וא\"ו, הוא מוסיף כמו שאמרו רבותינו בפסחים (ה, א), שהוי\"ו ענינו הוספה, והוא בחינת תוספת דקדושה, והיינו דשמירת הברית נצרך לה גדרות ותוספות דקדושה, והיינו מאמרם ז\"ל, כל מקום שאתה מוצא גדר ערוה, אתה מוצא קדושה (ויקרא רבה כד, ו וכ\"ה בילקו\"ש סדר קדושים רמז תרא), כי זה תלוי בזה, גאות וניאוף, כמו שאמרו חכמינו זכרונם לברכה (סוטה ד, ב), על פסוק (משלי ו, כו), ואשת איש נפש יקרה תצוד, והאריך שם בענין ע\"ש בצוף נועם דבריו. וא\"כ יוצא שהשומר אות ברית קודש זוכה לכבוד.","b":false},{"t":"ולכן מצינו ביוסף הצדיק דנטיר אות ברית קיימא קדישא, דלו יאה ולו נאה שיהיה נאמר בו והגדתם לאבי את כבודי מלא וא\"ו, וביקש יוסף הצדיק שיאמרו השבטים ליעקב אביהם שיוסף שמר ברית קודש בהיותו במצרים ולכן זכה לכבוד מלא, ודו\"ק. יבח\"ר].","b":false}]},{"id":"23","t":"בחובת השמירה להתגונן מהשפעות זרות ומזיקות, ובפרט לעוקר דירתו למקום אחר בלתי מוכר","p":[{"t":"וְיָשַׁבְתָּ בְאֶרֶץ גּשֶׁן וְהָיִיתָ קָרוֹב אֵלַי אַתָּה וּבָנֶיךָ וּבְנֵי בָנֶיךָ וְצֹאנְךָ וּבְקָרְךָ וְכָל אֲשֶׁר לָךְ: (מה, י)","b":true},{"t":"צריך להבין למה בחר יוסף בארץ גושן לישיבת אביו ואחיו. ומהפסוקים דלהלן (בראשית מו, לד ושם מז, א ושם שם, ד), אנו רואים שיוסף עומד על ענין זה מאד, כאשר נאמר והיה כי יקרא לכם פרעה וגו'. ואמרתם אנשי מקנה וגו', בעבור תשבו בארץ גושן וגו'. ועוד נאמר, ויבא יוסף ויגד לפרעה ויאמר אבי ואחי וצאנם ובקרם וכל אשר להם באו מארץ כנען והנם בארץ גושן. וגם האחים אמרו לפרעה, רועי צאן עבדיך וגו' ויאמרו אל פרעה לגור בארץ באנו וגו', ועתה ישבו נא עבדיך בארץ גושן. וגם פרעה השיב ליוסף (בראשית מז, ו), ארץ מצרים לפניך היא במיטב הארץ הושב את אביך ואת אחיך, ישבו בארץ גשן וגו'.","b":false},{"t":"ובודאי שחשב יוסף מחשבות בחכמה להביא את בית אביו לארץ גושן דוקא, והיה הדבר חשוב בעיניו כל כך עד שמיד בתחילת דבריו אמר זאת לאחיו, ושיאמרו כן לאביהם, ועוד שציוה את אחיו שיאמרו לפרעה שהם חפצים בארץ גושן, וגם הוא אמר כן לפרעה, וגם בעיני יעקב ובניו היה הרעיון מקובל ונכון.","b":false},{"t":"והרמב\"ן ז\"ל (בראשית מו, י), כתב, וישבת בארץ גשן. היה יוסף יודע באביו, שלא ירצה לעמוד במצרים אשר שם הבירה למלכות, על כן שלח לו מעתה כי בארץ גושן יושיבנו. עכ\"ל.","b":false},{"t":"והנה דברים גדולים ועצומים רמוזים וחתומים בדברי קדשו של הרמב\"ן ז\"ל. כי הנה אחד הדברים המסוכנים ביותר לקיום הרוחניות, הוא השינוי החזק ממקום שבו היה האדם גר ויושב שנים ארוכות, והולך ומשנה את מקומו אל מקום אחר שהוא זר לו, וככל שהשינוי יהיה חזק וחד, כך הסכנה מרובה וקרובה רח\"ל.","b":false},{"t":"ויעקב ובניו אשר היו עם לבדד ישכון (במדבר כג, ט), ומובדלים מן הסביבה, ומתרחקים מבני הכנעני אשר הם בקרבו, לבל יתערבו עמם רח\"ל. וכמה הזהיר אברהם אבינו ע\"ה את אליעזר עבדו נאמן ביתו המושל בכל אשר לו, ולא סמך עליו, ולא נח ולא שקט, עד אשר השביעו בנקיטת חפץ בשם ה' אלהי השמים והארץ, שלא יקח ליצחק אשה מבנות הכנעני אשר הוא יושב בקרבו. ודי לראות מה עשו בני יעקב לאנשי שכם בעבור שלקחו את אחותם, ומזה נבין עד כמה התרחקו וחששו יעקב ובני ביתו מן הגוים אשר סביבותיהם.","b":false},{"t":"ועתה חששו יוסף ובית אביו לבא מצרימה ולגור בעיר המלוכה, כי שם יפגעו בתרבות זרה להם ורחוקה מדרכם כמטחוי קשת, ויפגשו בדברים חדשים אשר לא שערום אבותיהם, והם עלולים להטלטל בטלטלה קשה וחזקה כל כך, שתעשה בהם רושם קשה, ובפרט בילדים הרכים, וכאשר מצינו ביעקב אבינו, שבעת שהציע לו עשו אחיו ואמר (בראשית לג, יב), נסעה ונלכה ואלכה לנגדך. ענה לו יעקב ואמר (שם שם, יג-יד), אדוני יודע כי הילדים רכים והצאן והבקר עלות עלי ודפקום יום אחד ומתו כל הצאן, יעבור נא אדוני לפני עבדו ואני אתנהלה לאטי לרגל המלאכה אשר לפני ולרגל הילדים עד אשר אבא אל אדוני שעירה. כי היה יעקב היה ירא מעשו וממלחמותיו, ומפחד עוד יותר מקרבתו וידידותו. ולזה רמז בתפלתו (בראשית לב, יא), הצילני נא מיד אחי מיד עשו, כי גם אם ינהג בו עשו כאח, התפלל שינצל מהשפעתו הרעה.","b":false},{"t":"צא וראה עד היכן מגיעה השפעת הגוים, דאיתא במסכת סוטה (מט, ב), אמר רב יהודה אמר שמואל משום רבן שמעון בן גמליאל מאי דכתיב (איכה ג, נא), עיני עוללה לנפשי מכל בנות עירי, אלף ילדים היו בבית אבא, חמש מאות למדו תורה וחמש מאות למדו חכמה יונית ולא נשתייר מהן אלא אני כאן ובן אחי אבא בעסיא. ושם בגמרא אמרו דחכמים התירו להם ללמוד חכמה יונית מפני שהיו קרובים למלכות. הרי לך שעם כל מה שהתירו להם, בכל זאת אבדו כולם ולא נשארו מהם אלא שנים.","b":false},{"t":"ויוסף הצדיק שהיה בנו ותלמידו הנאמן של יעקב, ידוע ידע את רוח אביו ואת הלך מחשבתו העמוקה, ואת דאגתו הכנה לחינוך בניו בעבודת ה' ואמונתו, וכמה הוא נזהר להרחיק את בני ביתו מכל חשש השפעה זרה ורעה, ובפרט במצרים ערות הארץ שהיו תושביה שטופי זימה, שהדבר יכאיב עד מאד ליעקב ובני ביתו. ואל זה כיון הרמב\"ן ז\"ל, שהיה יוסף יודע באביו, שלא ירצה לעמוד במצרים וכו'. וע\"כ שלח לו מעתה שיושיבנו בארץ גושן. כדי שלא יסרב לבא מצרימה. כי יוסף ידע באביו שיעדיף את הרעב של ארץ כנען עם הצניעות שבה הם חיים, על פני השבע והמלכות שבמצרים שהרבה סכנות רוחניות טמונות בה. וטובה פת חרבה ושלוה בה וגו' (משלי יז, א).","b":false},{"t":"והנה כזאת ממש ראינו בעינינו, בעת עלותינו לארץ אבותינו, אחר ציפיה בת אלפים שנות גלות, שלא חדלנו מציפייתנו אפילו רגע כמימריה, ובתומתינו חשבנו שבארה\"ק כולם חכמים בחכמת התורה, ועמך כולם צדיקים, והמציאות היתה שונה ורחוקה כל כך, והשינויים בהנהגה ובתפיסת חיים, היו חדים ורחוקים ממה שהורגלנו בו, כרחוק מזרח ממערב, והתרבויות התנגשו זו בזו בעוצמה חזקה, עד שנעו אמות הסיפים, של מסורת אבותינו הנפלאה רבת השנים, ונגלו בה סדקים רבים אשר הלכו והעמיקו ככל שהזמן חלף. ובפרט אצל בני הדור הצעיר, שעדיין היו רכים בדעותיהם, ונטו לחשוב שהוריהם ומוריהם אינם מפותחים וחכמים מספיק, ונשארו כלואים תוך תרבות ישנה ועתיקת יומין, אשר אור הדרור והחופש לא נגה עליה, ושמש המודרניזציה לא זרחה שם מעולם. ומתוך זה עמדו והתרחקו מדרכי אבותיהם וממסורתם אשר היתה באמנה אתם דורות רבים כל כך, ואשר כל רוחות הגלות וסערותיה לא יכלו להכניעה, ובבואה לפני המלך אל טרקלינו, היא הארץ הקדושה אשר עיניו נתונות עליה, שם היה משבר גדול, מן ההתנגשות החזקה בתרבות זרים. עד שרוב הצעירים גלו משלחן אביהם ועזבו מקור מים חיים, לחצוב להם בורת נשברים אשר לא יכילון המים, ונשארו קרחים מכל הכיוונים, ובאו עד משברים קשים ומרים, והדברים ידועים ומפורסמים.","b":false},{"t":"והמשלתי על זה משל בכדי להבין את עומק הענין, במעשה שהיה בחלבן ושמו ר' יעקב שהיה גר בכפר קטן, והיה משכים להתפלל שחרית בבית הכנסת, ומיד שב לביתו לחלוב את פרותיו, ולחלק חלב לכל תושבי הכפר, והיה אוכל פת של שחרית, ונח מעט מעמל העבודה, ותיכף קם ולומד חק לישראל, וקורא מעמדות של אותו יום, וכן מזמורי תהלים כהלכתם ופרקי נביאים, ופרקי משנה, ואחר הצהרים הולך שוב לבית הכנסת המקומי, ומתפלל מנחה בצבור, ובין תפלת מנחה וערבית, שומע שיעור קבוע מרב המקום, אשר בדברו מערי'ב ערבי'ם, בחכמה ובמשל, להמתיק הדברים על שומעיהם, ואחר כל אלה מתפללים ערבית בנעימה, ומברכים איש את רעהו ונפטרים לביתם לשלום. ויהי למחרת שוב משכים לשחרית וממשיך את סדר יומו כתמול שלשום. וכך היה חי כל ימיו בשלוה ובבטחה, עובד עבודתו באמונה, ועובד את הי\"ת בכל לבו ובתומתו. והחלבן הזה היה עטור בזקן מהודר וארוך המשתלשל ויורד עד למתניו, וכל אנשי הכפר נהגו בו כבוד אם מפני הדרת פניו וזקנו הארוך, ואם מפני שהעריכו את יושר לבבו ומדותיו הטובות, והנהגתו בשובה ונחת עם כל אדם. וכולם ידעו שהאיש הזה אינו משנה בדבורו, והיה אהוב לכל, וקראוהו בחיבה ובכבוד \"רבי יעקב\".","b":false},{"t":"ויהי היום מיודענו יצא מבית הכנסת אחר תפלת ערבית, כדי ללכת אל ביתו, והנה ניגש אליו אחד מתושבי הכפר, שהיה ידוע לכל שהוא לץ ואיש משחק, וניגש אליו וברכו בברכת לילה טוב, והלה השיבו בברכה כראוי, ויאמר אליו האיש, שאלה לי אליך רבי יעקב. וזה השיבו וכי חכם אני, שאתה אומר לשאול לדעתי, ענהו הלה, לא בהלכה אני שואל, אלא שאלה פרטית לי אליך. ויאמר שאל ואשתדל להשיבך כפי השגתי, אז אמר לו הלה, אמור לי ר' יעקב, איך אתה יושן. מיד ענה לו, מה שאלה היא זו, אני יושן כמו שכל בני אדם ישנים, אמר לו האיש מחילה, אני מתכוין, איך אתה מסתדר עם זקנך הארוך בעת השינה, האם אתה מניח אותו מתחת לשמיכה או מעליה. הרהר רגע קט ר' יעקב בשאלה. ומתחילה אמר תחת השמיכה, ומיד תיקן את עצמו ואמר, לא! מעל השמיכה. ושוב נתהרהר, ואמר בעצם אני לא יודע, ומה זה מענין אותך, ומה לך לחקירות אלו בענינים לא לך, והלך ועזבו לנפשו. בלילה ההוא נדדה שנתו של ר' יעקב מיודענו, ולא נתן שינה לעיניו ולעפעפיו תנומה, מתחלה, שם זקנו מתחת לשמיכה, ומיד היה מסתבך בין ידיו ובין רגליו, ולא ידע מנוחה, ושב והוציא את זקנו מעל השמיכה, וגם בזה לא הונח לו, כי כל פעם הפך את ראשו לצד אחר, הולך אל צפון וסובב אל דרום וגו'. וכך היה מתהפך מצד לצד, עד שהאיר השחר, ונתגבר כארי וקם לעבודת בוראו, אך היו איבריו כבדים וראשו עליו סחרחר, ועיניו מנמנמות כל אותו היום כולו, ויהי לעת ערב והוא יוצא מתפלת ערבית, ורואה את הלץ ההוא שבא ובפיו עוד שאלה אליו, מיד גער בו בחזקה ושילחו מעל פניו. והלץ משיב אמריו מה לך ר' יעקב כי נזעקת, ומדוע אתה נוזף בי בחומרה, והרי לא עשיתי לך דבר, ורק שאלה קלה שאלתיך. ענהו ר' יעקב, זו שאלה קלה! אני חי ארבעים שנה עם הזקן הזה בגודלו ובצלמו, ומעולם לא הפריע לי בשנתי, ולא הייתי יודע היכן הוא מונח, עד ששאלת את שאלתך, והִדַרת שינה מעיני כל הלילה, ע\"כ המעשה.","b":false},{"t":"ובכן הזקן של מיודעינו החלבן דומה ליהדותנו ולמסורת אבותינו, אשר היא היתה לנו לחומה ומגן בכל אורך ימי גלותינו, והיא היתה המשענת שלנו בשבתינו בביתנו, ובלכתינו בדרך לעבודה, ובכל עת ובכל שעה מעולם לא זזה מידינו, והיא היתה נר לדרכנו. ומעולם לא הפריעה לנו ולא הרגשנו כאילו מכבידה עלינו ח\"ו, וגם לא שאלנו שאלות ולא הקשינו קושיות, אלא קיימנו בנפשנו, תומת ישרים תנחם (משלי יא, ג), כפשוטו, באין חקירות והרהורים אחר הנהגת הי\"ת.","b":false},{"t":"וכשהגענו לארצנו, ופגשנו אנשי תרבות זרה לדרך אבותינו, והתחילו לשאול אותנו שאלות ריקות ושדופות, בלא טעם ובלא ריח. מפני ההעזה והשינוי החריף, התבלבלנו, ואיבדנו את שיווי המשקל של איזון רוחנו, וכששאלו איך אתם מסוגלים לחיות באופן זה וזה, היו הרבה שהחלו להרהר בדברים חלולים אלו, בחושבם שיצאו באמת וביושר מפי השואלים מתוך חקירה ענינית, והלכו בראש כבד, כי לא ידעו את עומק הענין, ואיך לסלק את העננים הריקים ולתפוס בדרך האמת, וזה גרם למשברים בדרך האמונה, ובשמירת מעשי אבותינו. ורבים חללים הפילה התנגשות התרבויות הזאת.","b":false},{"t":"ומזה היה חושש יוסף הצדיק, אשר בחכמתו העמוקה, ראה את הנולד, וידע מה תהיינה תוצאות המפגש הקשה עם התרבות הזרה והמוזרה של מצרים, וכל אשר היא מיצגת. ולכך חישב ומצא שהדרך הטובה היא להושיב את בית אביו בארץ גושן. כי היא מיטב הארץ עבורם ללא ספק. ועשה מיד כל הכנה נדרשת להשגת מטרה זו.","b":false},{"t":"ונרמז הדבר במאמר פרעה (בראשית מז, ו), ארץ מצרים לפניך היא במיטב הארץ הושב את אביך ואת אחיך ישבו בארץ גשן וגו'. כלומר, ארץ מצרים ידועה וגלויה לפניך במיטב הארץ וגו', כל אחד ומיטבו, ואם בחרת בגושן, ישבו בארץ גושן. וסמך פרעה על חכמת יוסף שידע לבחור לאחיו ובני ביתו את הטוב הראוי להם, ומה נעמו דברי רבינו יעקב בעל הטורים, שכתב, \"במיטב הארץ\", בגימטריא \"גושן\". ע\"כ.","b":false}]},{"id":"23","t":"איך גלגל הי\"ת את ירידת יעקב למצרים","p":[{"t":"מַהֲרוּ וַעֲלוּ אֶל אָבִי וַאֲמַרְתֶּם אֵלָיו כֹּה אָמַר בִּנְךָ יוֹסֵף שָׂמַנִי אֱלֹהִים לְאָדוֹן לְכָל מִצְרָיִם רְדָה אֵלַי אַל תַּעֲמֹד, וְיָשַׁבְתָּ בְאֶרֶץ גּשֶׁן וְהָיִיתָ קָרוֹב אֵלַי אַתָּה וּבָנֶיךָ וּבְנֵי בָנֶיךָ וְצֹאנְךָ וּבְקָרְךָ וְכָל אֲשֶׁר לָךְ, וְכִלְכַּלְתִּי אֹתְךָ שָׁם כִּי עוֹד חָמֵשׁ שָׁנִים רָעָב פֶּן תִּוָּרֵשׁ אַתָּה וּבֵיתְךָ וְכָל אֲשֶׁר לָךְ: (מה, ט-יא)","b":true},{"t":"הנה לפי פשוטו של מקרא, יוסף הצדיק ממהר ומזרז את אחיו, כדי למעט בצער האב הרחמן סבא קדישא, אשר עד עתה מתאבל על בנו, וכיון שהגיע הזמן שהתודע יוסף לאחיו, אי אפשר לעכב עוד כלל. וכן נראה מפירוש רבינו עובדיה ספורנו, וז\"ל, מהרו, שלא יצטער יותר. עכ\"ל.","b":false},{"t":"ועל כרחנו צריכים אנו לומר שיוסף חישב ומצא, שקיומו של אביו וכל ביתו בכבוד ובהדר, לא תיתכן בארץ כנען לעת הזאת, ועל כן אמר, כה אמר בנך יוסף וגו', רדה אלי אל תעמוד. וכילכלתי אותך שם וגו'. ולא עוד, אלא שכדי לטרוח ולהכין מקום אשר יטב לאביו ולכל בני ביתו, היה נאלץ יוסף להשאר במצרים, ולא עלה יוסף עם אחיו לראות את פני אביו, משום שהיה יקר בעיניו לזרז כל הכנה אפשרית לקראת בואם, ושיהיה הכל בדרך טובה ונכבדה.","b":false},{"t":"ומאת ה' היתה זאת לשים עצות בלב יוסף, להביא את אביו אליו לקיים את מאמר ה' שירדו למצרים, אשר לזה יוסף בעצמו הגיע למצרים כדי להביא את אביו ובני ביתו אחריו. כמו שאמרו חז\"ל (ראה סוטה יא, א וב\"ר פד, יג), על הפסוק (בראשית לז, יד), וישלחהו מעמק חברון, שאמרו, והלא חברון בהר היא שנאמר (במדבר יג, כב), ויעלו בנגב ויבא עד חברון. אלא מעצה עמוקה של אותו צדיק הקבור בחברון, לקיים מה שנאמר לאברהם בין הבתרים (בראשית טו, יג-יד), כי גר יהיה זרעך וגו'.","b":false}]},{"id":"23","t":"מחשבות הי\"ת גבוהות ממחשבות בני אדם לאין חקר ואין תכלית","p":[{"t":"וְעַתָּה אַל תֵּעָצְבוּ וְאַל יִחַר בְּעֵינֵיכֶם כִּי מְכַרְתֶּם אֹתִי הֵנָּה כִּי לְמִחְיָה שְׁלָחַנִי אֱלֹהִים לִפְנֵיכֶם, כִּי זֶה שְׁנָתַיִם הָרָעָב בְּקֶרֶב הָאָרֶץ וְעוֹד חָמֵשׁ שָׁנִים אֲשֶׁר אֵין חָרִישׁ וְקָצִיר, וַיִּשְׁלָחֵנִי אֱלֹהִים לִפְנֵיכֶם לָשׂוּם לָכֶם שְׁאֵרִית בָּאָרֶץ וּלְהַחֲיוֹת לָכֶם לִפְלֵיטָה גְּדֹלָה, וְעַתָּה לֹא אַתֶּם שְׁלַחְתֶּם אֹתִי הֵנָּה כִּי הָאֱלֹהִים וַיְשִׂימֵנִי לְאָב לְפַרְעֹה וּלְאָדוֹן לְכָל בֵּיתוֹ וּמשֵׁל בְּכָל אֶרֶץ מִצְרָיִם: (מה, ה-ח)","b":true},{"t":"הנה המתבונן בפסוקים אלו, יראה עד כמה גדולת הי\"ת, ועד כמה עמקו מחשבותיו ממחשבותינו, ואיך הי\"ת צופה ומביט מכאן ועד סוף כל הדורות.","b":false},{"t":"כי הנה כשהתראו אחי יוסף עמו אחר כ\"ב שנים שמכרוהו ונתגלה אליהם, בא יוסף ואומר להם, אחי, אל תעצבו על מכירתי ואל יחר בעיניכם, כי הי\"ת שלחני לכאן במחשבה תחילה כדי להחיות עם רב. ומסביר יוסף ומפרש לאחיו שעתיד להיות רעב עוד חמש שנים, ואת כל זה השיג יוסף בחכמתו המופלאה וברוח הקודש שנוססה בו, אבל, החקר אלוה תמצא אם עד תכלית שדי תמצא (איוב יא, ז). וגם יוסף לא ראה בכל ירידתו למצרים אלא \"הצלה\" מן הרעב ולא עוד.","b":false},{"t":"אך כמה רחוקים דרכי הי\"ת מהשגת אנוש, ואפילו מאדם גדול כיוסף הצדיק, עמקו מאד מחשבותיו יתברך, עד שאפילו אחרי כ\"ב שנים שחשבו יוסף ואחיו כי עתה הכל גלוי וידוע להם. מכל מקום, עוד לא השיגו את אפס קצה מחשבתו יתברך, ששלח את יוסף מצרימה כדי שיבא יעקב אחריו ולא יצטרך לרדת בשלשלאות של ברזל לשם (ראה ב\"ר פו, ב), כדי לקיים את מה שאמר לאברהם אבינו ע\"ה, ידוע תדע כי גר יהיה זרעך וגו' (בראשית טו, יג-יד).","b":false},{"t":"ולא זו אף זו, אלא גם אחר שהגיע יעקב אבינו ע\"ה למצרים, וגם אחר שמתו יוסף ואחיו וכל הדור ההוא, וקם מלך חדש אשר לא ידע את יוסף, והחל השעבוד בחומר ובלבנים ובכל עבודה בשדה, גם אז לא ידעו ישראל ולא תיארו לעצמם, מה העבודה הזאת להם, ועל מה עשה להם ה' ככה, שישתעבדו בשעבוד כה גדול.","b":false},{"t":"והמטרה העיקרית היא שיצאו ברכוש גדול, אחר שיקבצו את ניצוצות דקדושה אשר נתפזרו ונפלו למצרים ע\"י אדם הראשון באותם ק\"ל שנים בהיותו לבדו, אשר כולם נקבצו ובאו מצרימה שהיא ערות הארץ, וכמו שביארנו (לעיל פר' לך לך מאמרים ח-ט).","b":false},{"t":"וגם בשביל להראות לישראל את יד ה' עין בעין, באותות ומופתים בעשר מכות שהביא הקב\"ה על המצריים במצרים, ונכללו במכות ההם כל כחות הטבע אחת מהם לא נעדרה, להראות לישראל וללמדם כי מלכות הי\"ת בכל משלה, ואפס זולתו, ולמען ידעו כי הי\"ת נמצא ומושל גם בקרב הארץ, ואין מידו מציל, ואי אפשר לברוח מפניו ישתבח שמו.","b":false},{"t":"וכל זה כדי לנטוע את אמונת הי\"ת ובטחונו בלבם ובלב בניהם ובני בניהם עד עולם, והאמונה והבטחון בהי\"ת הוא הבסיס והתשתית לקבלת התורה, בבחינת דרך ארץ קדמה לתורה (ויק\"ר ט, ג תנדא\"ר פ\"א), ומהי\"ת מצעדי גבר כוננו, להביא את יוסף, למשול במצרים, ולהחיות עם רב, ולשום לאביו ואחיו שארית, כדי שיבואו בכבוד, ואח\"כ יבא השעבוד כאשר דיבר ה' אל אברהם אוהבו, ולבסוף יצאו ישראל ברכוש גדול, ויקחו עמהם את כל אשר אצר יוסף, ויקבלו למתנת עולם את הרכוש הגדול ביותר, והוא, שיבאו לפני הר סיני, ויתעלו במעלות רבות ונישאות עד שתפסק מהן זוהמת חטא אדה\"ר, ואז יכרות הי\"ת עמהם ברית עולם, וישמיעם את קולו מתוך האש, ויתן להם תורת אמת, תורת אלהים חיים מידו יתברך, כי לא נברא העולם אלא בשביל התורה הקדושה (ראה ב\"ר א, א), ולהי\"ת נתכנו עלילות, ישתבח שמו לעד.","b":false}]},{"id":"23","t":"אוי לנו מיום הדין ואוי לנו מיום התוכחה","p":[{"t":"וַיֹּאמֶר יוֹסֵף אֶל אֶחָיו אֲנִי יוֹסֵף הַעוֹד אָבִי חָי וְלֹא יָכְלוּ אֶחָיו לַעֲנוֹת אֹתוֹ כִּי נִבְהֲלוּ מִפָּנָיו: (מה, ג)","b":true},{"t":"איתא במסכת חגיגה (ד, ב), רבי אלעזר כי מטי להאי קרא בכי ולא יכלו אחיו לענות אתו כי נבהלו מפניו ומה תוכחה של בשר ודם כך תוכחה של הקדוש ברוך הוא על אחת כמה וכמה. ע\"כ. וכתבו רבותינו בעלי התוספות שם (ד\"ה של הקב\"ה), של הקב\"ה על אחת כמה וכמה, שלא יוכל להשיב תשובה מעלייתא, להיפטר לגמרי וכו'. ע\"ש.","b":false},{"t":"וכתב מהרש\"א ז\"ל שם, ואע\"ג שלא אמר להם כלל יוסף מענין התוכחה, מ\"מ היו יראים שהוא יבא להוכיחם אח\"כ על מה שעשו לו, ונבהלו מפני הבושה, שלא יוכלו לעמוד בתוכחתו. תוכחה של הקב\"ה, מפורש בב\"ר (צג, י), לכשיבא הקב\"ה ויוכיח כל אחד ואחד לפי מה שהוא, שנאמר (תהלים נ, כא), אוכיחך ואערכה לעיניך וגו', על אחת כמה וכמה. עכ\"ל.","b":false},{"t":"והרב תורה תמימה כתב לדקדק, מה מקום יש לשאלה זו, העוד אבי חי, והלא השבטים אמרו ליוסף כמה וכמה פעמים מעניני אביהם, וגם איך מתקשרת השאלה הזאת עם מה שאמר אני יוסף.","b":false},{"t":"ופירש דבזה היה מתמיה יוסף עליהם ואומר, האמנם היה בו באבי כח לסבול יגון וצער על אבדתי, האם עודנו חי מן הצער שהיה לו. והנה במעט דברים אלו די להם ונקוט בפניהם על כל מה שעשו, ומבואר דבדברים אלו אמנם הוכיחם תוכחה נמרצת הראוי לעשות שרט בנפש החייבת בה. ודו\"ק. עכ\"ד.","b":false},{"t":"וכונתו פשוטה שבתיבות אלו ששאלם יוסף העוד אבי חי, תיאר להם את גודל הצער שגרמו, ואת רוע מעשיהם, שהיה בו להמית אפילו אדם גדול כאביהם, ועל כן היה יוסף עומד ומתמיה, העוד אבי חי.","b":false},{"t":"ויש שפירשו שהוכיחם על מה שחזרו לפניו כמה פעמים, שלא יוכלו להניח את בנימין כי נפשו קשורה בנפש אביו, ועזב את אביו ומת, ועתה אומר להם, אני יוסף, העוד אבי חי, ואיך לא דאגתם לאבא כשמכרתם אותי והיא תוכחה גדולה וכמדומני שכ\"כ הגה\"צ המפורסם רבינו אליהו לאפיאן ע\"ה בספרו לב אליהו (פרשה זו מאמר האימה והבושה מהדין והתוכחה).","b":false},{"t":"ובעלי המוסר רגילים לפרש דהתוכחה היא בעצם גילוי האמת, שאמר להם \"אני יוסף\", אשר בזה התנפץ השקר הגדול שאותו אמרו כ\"ב שנים, למן העת שאמרו לאביהם, זאת מצאנו הכר נא הכתונת בנך היא טרוף טורף יוסף חיה רעה אכלתהו (בראשית לז, לב-לג). ועתה בצאת האמת לאור, אין אומר ואין דברים, ונסתתמו כל טענותיהם, ולא יכלו לענות אותו, ולא רק טענתם החיצונית שהיו אומרים לכל נסתרה ע\"י התגלות האמת, אלא גם כל הטענה שטענו בינם לבין עצמם, להצדיק את מעשיהם, באומרם בן מות הוא יוסף, וכל מזימותיו הם למלוך ולמשול בנו ולהפוך אותנו לעבדים, ודנו אותו למיתה והביאו ראיה לדבריהם מחלומותיו אשר חלם להם, ויוסיפו עוד שנא אותו על חלומותיו ועל דבריו. גם טענה זו נסתרה כעת. והנה עתה קמה אלומתו וגם נצבה, ואכן הוא מלך והם משתחוים לו, והתברר לכולם שהחלומות ההם לא היו פרי מחשבותיו הפרועות, כאשר דימו הם, אלא חלומות נבואיים היו, ובאמירה זו שאמר להם \"אני יוסף\" נפל כל בנין הטענות שהיו לאחיו עליו, והיה כלא היה, וכנגד זה לא יכלו האחים לעמוד ובודאי לא לענות אותו.","b":false},{"t":"ואמרתי על זה שכשמתגלה האמת, אין שום אדם שיכול לעמוד כנגדה, ואפילו אם האמת תצא על ידי ילד קטן, או אפילו ע\"י בריה כל שהיא, אי אפשר לעמוד נגדה, וק\"ו לפני הקב\"ה, ומי ישיבנו.","b":false},{"t":"ואמרתי משל למה הדבר דומה, לאיש אשר הלך בערב פסח אל השוק, וקנה קניות רבות מאד, בשר, דגים, ופירות, ושאר ירקות, ופירות יבשים, ותבלינים, וכלים מכלים שונים. והיו לו כמה וכמה סלים מלאים והיתה כבודה רבה ולא יכל לנושאם לבדו. והיה מחפש בעל עגלה שיקח לו את כל כבודתו לביתו, אך כל בעלי העגלות כבר נשכרו ע\"י האנשים, כי בערב פסח הכל קונים קניות רבות וצריכים את בעלי העגלות להוביל לביתם את אשר קנו. והלך אל תחנת העגלונים, אך גם שם לא מצא עגלון פנוי שיסיענו לביתו. והיה עומד עם הסלים סביבו והשמש קודחת על ראשו, וכל גופו מזיע והוא סר וזעף. לפתע עבר ברחוב אחד ממכריו, ויאמר לו מה לך עומד עצוב, ואז הסיח את צרתו לפניו שאינו מוצא בעל עגלה, כי כולם יצאו לדרכם ולא שבו עדיין, ובימים האלה שהענינים מרובים, יקשה עד מאד למצוא בעל עגלה, כי לא יספיקו בעלי העגלות לשוב למקומם וכבר יקפצו עליהם נוסעים מהכא להתם, ולכן הוא דואג כיצד יגיע לביתו עם משאותיו.","b":false},{"t":"ויאמר לו חברו, אוי ידידי יקירי, לחינם תעמוד כאן. והרי הפתרון הוא קל ופשוט, הלא ידידך פלוני, שאתה משתבח בידידות שיש ביניכם גר קרוב לכאן, מהלך כמה פסיעות. ויאמר לו בעל החבילות, ומה אעשה בידידותינו, ומה תועיל לי קרבת חברי. ויען ויאמר לו, הלא שמעת אם לא ידעת כי חברך קנה עגלה וגם חמור טוב וחזק, ואם ידע את צערך ודאי שיעזרך במיטב היכולת ויקחך לביתך. לכן לך מהר חושה אל תעמוד, רוץ אל ביתו ואני אעמוד כאן לשמור על חפציך עד שתשוב, וישמח על ההצעה הזו, ותיכף קם ונתעודד ונחפז אל בית חברו. ואחר ברכת שלום ושאלות של נימוס כנהוג, ביקשו חברו שישב לטעום דבר מה כהלכות גוברין יהודאין, וזה השיבו שאין לו זמן כי כבר כמה שעות הוא עומד בשוק, וכל מה שקנה מונח עדיין שם, כי לא מצא עגלה לאסוף מרכולתו. והיה בטוח שמיד שיוציא מפי את מילת הקסם \"עגלה\" יקפוץ חברו ידידו ויאמר לו, יש לי עגלה וגם חמור ואין לך מה לדאוג ועתה נלכה אל ביתך באהבה ולשלום. אך התאכזב מאד, כאשר שמע את ידידו אומר לו הצעות ועצות שונות, אולי במקום פלוני או מקום אלמוני תשיג עגלה, וזה אומר לו, לא הנחתי זוית ופינה ואין.","b":false},{"t":"ואז אמר לידידו, שמע נא ידידי, הלא פלוני מיודענו אמר לי שקנית עגלה וחמור נאה ומהודר, וידידו השיב, לא היו דברים מעולם, וכי יעלה בדעתך שיהיה לי חמור, ואני יושב ומייעץ עצות לידידי ואהובי ולא לוקחו. והנה תוך כדי שהוא אומר את הדברים הללו, נשמע קולו של החמור נוער בקול צלול וברור, שלא השאיר כל מקום לספק, וזה אומר הנה יש לך חמור, אמר לו בעל החמור, ידידי! אתה מאמין לחמור, ולא מאמין לידידך הנאמן....","b":false},{"t":"וכדאי בזיון וקצף, דאחר שיצאה האמת לאור, אפילו אם תצא מתוך גרונו של חמור נוער, אי אפשר להכחישה ולעמוד נגדה וכאשר מצינו באתונו של בלעם שהוכיחתו ולא יכל לעמוד כנגדה, ק\"ו אם התוכחה יוצאת מפיו של אדם ואפילו אם יהא קטנם של האחים. ולכן, מיד נבהלו ורעדו, ולא יכלו לענות אותו.","b":false},{"t":"וע\"ז בוכה רבי אלעזר ועושה ק\"ו לתוכחתו של הקב\"ה.","b":false},{"t":"ובמדרש איתא (ב\"ר צג, י), אמר אבא כהן ברדלא אוי לנו מיום הדין אוי לנו מיום התוכחה, בלעם, חכם של העובדי כוכבים לא יכול לעמוד בתוכחתה של אתונו וכו', וכן יוסף קטנן של שבטים היה, ולא היו יכולים לעמוד בתוכחתו ההוא דכתיב ולא יכלו אחיו לענות אותו כי נבהלו מפניו. לכשיבא הקב\"ה ויוכיח כל אחד ואחד לפי מה שהוא שנאמר (תהלים נ, כא), אוכיחך ואערכה לעיניך, על אחת כמה וכמה. ע\"כ. ובאמת הדברים נוראים כי לעתיד לבא ביום הדין והמשפט הקב\"ה שואל את האדם מתוך הנהגתו שלו, ומראה לו איך כל הנהגתו מלאה סתירות.","b":false},{"t":"והנה נקטו רבותינו במדרש \"יום הדין\" וגם \"יום התוכחה\" ומשמע דהם שני ימים שונים, אלא שקשה למה הקדימו רבותינו בדבריהם את \"יום הדין\" ל\"יום התוכחה\" והלא התוכחה קודמת לדין.","b":false},{"t":"וידוע דהמפרשים אמרו טעם למה הקדימו רבותינו בדבריהם את \"יום הדין\" לפני \"יום התוכחה\", כי בתחילה ישאלו את האדם בב\"ד של מעלה מה דינו של אדם שעשה כך וכך, והוא בטוח שלא עליו מדברים, כי בטוח הוא בצדקת דרכו, וחורץ את הדין של ההוא גברא, ומדבר בו קשות לאמר, איככה העיז פניו בפני יוצרו וכו', ואחר שגמר לפסוק בדינו של אותו נעלם, מיד מוכיחים אותו, ומתגלה לו שהוא עצמו עשה את כל המדובר, וכי את דינו שלו הוא חרץ. ולזה אמר אוי לנו מיום הדין, ועוד קשה ממנו הוא יום התוכחה, ולפי זה התוכחה היא עצם התוכחה שמוכיחים לאדם שהוא הוא החוטא, והוא שעשה את הדברים בהם דנו קודם, וכמו שהיה במעשה נתן הנביא עם אדוננו המלך דוד ע\"ה (ראה שמואל ב' פי\"ב). ולפי\"ז גם אם נלך בדרכו של מהרש\"א ז\"ל שיוסף לא הוכיח את אחיו כלל, מ\"מ בעצם אמירתו \"אני יוסף\" נבוכו האחים מאד ונבהלו ונסוגו אחור, וע\"ז הוא שאומר אוי לנו מיום הדין, אוי לנו מיום התוכחה.","b":false},{"t":"ודברים אלו צריכים להיות חקוקים מול עינינו, וכתובים על לוח ליבנו, שלא נסיח דעתנו מהם בכל מצב ובכל זמן, וה' הטוב לא ימנע טוב להולכים בתמים.","b":false}]},{"id":"23","t":"דברי יהודה ליוסף ותשובת יוסף לאחיו","p":[{"t":"מאמר שנכתב לכבוד האי תנא דידן נר המערבי, ענף עץ אבות, חמדת הלבבות, ציר שלוח מרוכב ערבות, קדוש ישראל מופת הדור ופלאו רבינו ישראל אביחצירא ע\"ה וזיע\"א, ינון שמו לעד, וזכותו תעמוד לזרעו לברכה ולכל בית ישראל, וגדולים צדיקים במיתתם יותר מבחייהם, כי לא ישקוט האיש ולא ינוח, כי אם כילה מלאכתו בקודש, אשר בה עסק כל ימי היותו על האדמה, לקרב את גילוי משיח צדקינו, עד כי יבא שילה בשובה ונחת, את כל ונוכחת, בשוב ה' את שבותינו בב\"א.","b":false},{"t":"וַיִּגַּשׁ אֵלָיו יְהוּדָה וַיֹּאמֶר בִּי אֲדֹנִי יְדַבֶּר נָא עַבְדְּךָ דָבָר בְּאָזְנֵי אֲדֹנִי וְאַל יִחַר אַפְּךָ בְּעַבְדֶּךָ כִּי כָמוֹךָ כְּפַרְעֹה, אֲדֹנִי שָׁאַל אֶת עֲבָדָיו לֵאמֹר הֲיֵשׁ לָכֶם אָב אוֹ אָח, וַנֹּאמֶר אֶל אֲדֹנִי יֶשׁ לָנוּ אָב זָקֵן וְיֶלֶד זְקֻנִים קָטָן וְאָחִיו מֵת וַיִּוָּתֵר הוּא לְבַדּוֹ לְאִמּוֹ וְאָבִיו אֲהֵבוֹ, וַתֹּאמֶר אֶל עֲבָדֶיךָ הוֹרִדֻהוּ אֵלָי וְאָשִׂימָה עֵינִי עָלָיו, וַנֹּאמֶר אֶל אֲדֹנִי לֹא יוּכַל הַנַּעַר לַעֲזֹב אֶת אָבִיו וְעָזַב אֶת אָבִיו וָמֵת, וַתֹּאמֶר אֶל עֲבָדֶיךָ אִם לֹא יֵרֵד אֲחִיכֶם הַקָּטֹן אִתְּכֶם לֹא תֹסִפוּן לִרְאוֹת פָּנָי, וַיְהִי כִּי עָלִינוּ אֶל עַבְדְּךָ אָבִי וַנַּגֶּד לוֹ אֵת דִּבְרֵי אֲדֹנִי, וַיֹּאמֶר אָבִינוּ שֻׁבוּ שִׁבְרוּ לָנוּ מְעַט אֹכֶל, וַנֹּאמֶר לֹא נוּכַל לָרֶדֶת אִם יֵשׁ אָחִינוּ הַקָּטֹן אִתָּנוּ וְיָרַדְנוּ כִּי לֹא נוּכַל לִרְאוֹת פְּנֵי הָאִישׁ וְאָחִינוּ הַקָּטֹן אֵינֶנּוּ אִתָּנוּ, וַיֹּאמֶר עַבְדְּךָ אָבִי אֵלֵינוּ אַתֶּם יְדַעְתֶּם כִּי שְׁנַיִם יָלְדָה לִּי אִשְׁתִּי, וַיֵּצֵא הָאֶחָד מֵאִתִּי וָאֹמַר אַךְ טָרֹף טֹרָף וְלֹא רְאִיתִיו עַד הֵנָּה, וּלְקַחְתֶּם גַּם אֶת זֶה מֵעִם פָּנַי וְקָרָהוּ אָסוֹן וְהוֹרַדְתֶּם אֶת שֵׂיבָתִי בְּרָעָה שְׁאֹלָה, וְעַתָּה כְּבֹאִי אֶל עַבְדְּךָ אָבִי וְהַנַּעַר אֵינֶנּוּ אִתָּנוּ וְנַפְשׁוֹ קְשׁוּרָה בְנַפְשׁוֹ, וְהָיָה כִּרְאוֹתוֹ כִּי אֵין הַנַּעַר וָמֵת וְהוֹרִידוּ עֲבָדֶיךָ אֶת שֵׂיבַת עַבְדְּךָ אָבִינוּ בְּיָגוֹן שְׁאֹלָה, כִּי עַבְדְּךָ עָרַב אֶת הַנַּעַר מֵעִם אָבִי לֵאמֹר אִם לֹא אֲבִיאֶנּוּ אֵלֶיךָ וְחָטָאתִי לְאָבִי כָּל הַיָּמִים, וְעַתָּה יֵשֶׁב נָא עַבְדְּךָ תַּחַת הַנַּעַר עֶבֶד לַאדֹנִי וְהַנַּעַר יַעַל עִם אֶחָיו, כִּי אֵיךְ אֶעֱלֶה אֶל אָבִי וְהַנַּעַר אֵינֶנּוּ אִתִּי פֶּן אֶרְאֶה בָרָע אֲשֶׁר יִמְצָא אֶת אָבִי: (מד, יח-לד)","b":true},{"t":"המביט אל כל דבריו של יהודה, רואה אותו במר נפשו, הולך ומתחנן בעד אחיו, כי הוא הוא שנכנס להיות ערב עבור בנימין, כמו שנאמר (בראשית מג, ט), אנכי אערבנו מידי תבקשנו אם לא הביאתיו אליך והצגתיו לפניך וחטאתי לך כל הימים. ואחר שראה יהודה שנתפס אחיו בנימין, והתחננו כולם בעדו, וכלו כל הקיצין, והשליט עודנו מתעקש להחזיק אצלו את בנימין ולשלחם ריקם אל אביהם בלעדיו. תיכף אזר עוז וניגש לדבר את כל אשר על לבו, והיה נחוש ונחרץ בדעתו שיעשה כל מה שאפשר לו לעשות, כדי להשיב את בנימין לפני אביו.","b":false},{"t":"אך למרבה הפלא, כשנתבונן בדברי יהודה, לא נמצא בדבריו איומים למלחמה, או כל מיני שידולים ותחינה ובקשה. אלא רק פירוט השתלשלות הענינים, מה היה מן הפעם הראשונה שבאו למצרים ועד המצב הזה שנלקח בנימין, ומזכיר את דאגתם לאביהם ולא עוד כלום. ויש להבין מה חשב יהודה ומה עלתה בלבו שיוכל להועיל בסיכום הדברים הללו לפני השליט.","b":false},{"t":"ועוד יותר תמוה, שמיד כשגמר יהודה לומר את דבריו ולספר מה שעבר עליהם מתחילת ביאתם אליו למצרים בפעם הראשונה תיכף נאמר, (בראשית מה, א-ג), ולא יכל יוסף להתאפק לכל הנצבים עליו, ויקרא הוציאו כל איש מעלי וגו', ויתן את קולו בבכי וגו', ויאמר יוסף אל אחיו אני יוסף העוד אבי חי וגו'. וצריכים להבין מה הזכיר יהודה בדבריו שריגש כל כך את יוסף, עד שלא יכל להתאפק עוד ובכה ונתגלה אל אחיו, והלא אפילו כשראה לראשונה את בנימין אחיו היחיד מאמו, ונכמרו רחמיו, בכ\"ז מיהר לצאת החדרה ולבכות, ורחץ את פניו ונכנס אליהם והיה מתאפק עוד. ומה גרם לו כעת שלא יכול עוד להתאפק, והרי לא נתחדש דבר ולא חצי דבר, בכל מה שדיבר אליו יהודה. וקשה לומר שעצם החזרה על הענין בתמציתיות ריגשה את יוסף וריככה את לבו, עד שלא היה יכול עוד להתאפק.","b":false},{"t":"והנראה בזה בס\"ד, דיהודה ואחיו היו בטוחים וסמוכים ביושרו של בנימין, וידעו היטב שלא גנב ולא ראה את הגביע כלל ועיקר, וכי רק תואנה מבקשים השליט ואנשיו, כדי להתנפל עליהם, ולקחת את אחיהם הקטן מידיהם, ביודעם שנפש כל האחים קשורה בו, וכי לא יותרו עליו בשום פנים שבעולם. אך לא ידעו את פשר הדבר, מה מבקשים השליט ואנשיו מבנימין דוקא. ומאידך, השבטים לא יכלו להכחיש את השליט ולומר לו שתואנה הוא מבקש. כי הוא טוען בתוקף שעושה את כל מעשיו בצדק ויושר, ואין להם שום הוכחה לסתור את דבריו וטענותיו, ולכן היו מנסים לפייסו בכל כחם ולמלאת את משאלותיו, והתאמצו עד כדי כך שהוציאו את בנימין מיד אביהם. אך כל זה לא הועיל להם, ולא נצלו ממזימות השליט. כי אדרבה הוא המשיך בדרכו ותחבולותיו, והפיל על בנימין עלילה נוראה שהוא גנב את הגביע, ועל ידי כן ביקש להשאירו אצלו לעבד.","b":false},{"t":"וכשראה יהודה כי כלה ונחרצה מעם השליט להחזיק בבנימין, ניגש אליו ודיבר עמו קשות. וביקש סליחתו באומרו, בי אדוני וגו', כלומר, הרשיני בבקשה לדבר עמך בגילוי לב וביושר. ומן הסתם יוסף אמר לו, בבקשה, אמור דבריך בגלוי, שאם לא כן לא היה יהודה ממשיך בדיבורו.","b":false},{"t":"והיה יהודה חוזר ומסכם את הענין, ומוכיח ליוסף מתוך הדברים, שאין זו אלא עלילה, ותו לא. ומוכיח לו את הדבר בפשיטות, והתחיל במה שאמר לו, אדוני שאל את עבדיו לאמר היש לכם אב או אח. כלומר, שמתחילה אתה מתענין באח הזה, אע\"פ שעוד לא ראית אותו וגם לא ראית את אבינו, ולא שמעת מקיומם, ואתה כבר שואל עליהם היש לכם אב או אח. ואנו השבנו בכנות וביושר כמסיחים לתומנו, ונאמר אל אדוני, יש לנו אב זקן, וילד זקונים וגו'. ומאז לא הרפית בשום פנים, וגזרת אומר שלא נוסיף לראות עוד את פניך אם לא נביא אותו עמנו. ועם כל מה שהסברנו בדברי אמת ויושר, שיש בזה משום פיקוח נפש לאבינו הזקן, וכי הדבר מעל לכחנו, בכל זאת, אתה לא זזת מפקודתך בשום אופן. ומזה אנו לומדים בבירור שיש לך בו ענין, ולא עוד אלא שמראש הכנת בעורמה את כל המהלך הזה כדי לקחת את אחינו הקטן, והוכיח סופו, שמיד כשבא אחינו הקטן, לא העלמת עינך ממנו, ובסוף דאגת שיושם הגביע באמתחתו, כדי לתופסו אצלך, ועוד שכספנו הושב וכו'. הרי אנחנו יודעים ומכירים את בנימין וקים לן בגויה, שבשום אופן שבעולם לא ישלח ידו במה שאינו שלו, וגם ברור מכל מהלך הענין, שהכל מזומן מראש ומעיקרא על ידך. ואותה יד שהניחה כספנו באמתחינו, היא היא היד שהניחה את הגביע שלך באמתחת בנימין.","b":false},{"t":"ואחר שבירר יהודה לפני יוסף את כל האמת הפשוטה הזאת, ואמר את דבריו בחוזק ובהחלטיות, מובן מאליו, שמעתה כל אחי בנימין אינם מוכנים להשלים עם משפטו של השליט. כי הם טוענים נגדו שהכל בנוי על שקר וכזב. ופשוט הדבר, שאם החליט יהודה לדבר עמו בגלוי ובתקיפות שכזו, א\"כ מעתה יעשו השבטים את כל אשר לאל ידם, וגם התכוננו למאבק חזק ונועז, כדי להשיב את אחיהם לאביהם כאשר מבואר כל זה בדברי רבותינו (ראה בראשית רבה פרשה צג שהאריכו לספר מה ביקשו השבטים לעשות).","b":false},{"t":"ומשראה יוסף את מסירות נפשם של האחים על הצלת בנימין, לא היה יכול להתאפק עוד, שעתה התברר לו באר היטב שחזרו בתשובה שלימה, ולא יהיו מוכנים עוד להפקיר את אחיהם בשום פנים שבעולם.","b":false},{"t":"ועוד יותר יש בזה, שלא היה יכול יוסף להכחיש את האמת הפשוטה הזו, כפי שהעמידה יהודה, ולא היה יכול להמשיך להסתיר את עצמו כפי שעשה עד עתה, כי מטרתו היתה להביא את אחיו לשיחה גלויה זו, וגם לבחון אותם ולראות אם יעמדו בנסיון להציל את אחיהם בכל מחיר. ואמר הגיע העת לגלות את כל האמת. ועל כן לא היה יכול יוסף להתאפק עוד, כי אין שום כח שיכול לעמוד נגד האמת.","b":false},{"t":"ואז אמר להם אני יוסף וגו', ויש בזה תשובה ניצחת כנגד כל מה שאמר וטען יהודה כלפיו, והרי זה כאומר לו ליהודה, השתא דאתית להכי, וירדת לעומקה של האמת, א\"כ בוא ונבדוק גם את אמיתות דבריכם. הרי אתם מעמידים את הדאגה לאבא בראש כל מעייניכם, א\"כ אמרו לי מה חשבתם כשמכרתם אותי הנה. איפא היתה דאגתכם לאבא. ומדוע אז לא חששתם שימות מרוב צערו על אבדני וזהו \"אני יוסף העוד אבי חי\".","b":false},{"t":"ובאמת שראוי לכל אחד לנסות ולתאר בדמיונו את אותו מעמד נורא. יוסף עומד בטרם שאחיו הכירוהו. והאחים האומללים בדמעות בעיניהם מסבירים ליוסף את מצבו של אביהם, ושהוא לא יוכל לחיות אפילו רגע בראותו שבנימין איננו. ואז יוסף אומר להם צודקים אתם! אבל כיצד אבא חי עד עתה עם הכאב על אובדני? האמנם הוא חי עדיין? האמנם לא נדם לבו מכאב כשבאתם ואמרתם לו טרוף טורף יוסף! איפה היתה רחמנותכם אז? איפה היתה הדאגה שלכם אז?","b":false},{"t":"והאחים נבהלו מאד מפניו ולא יכלו לענותו דבר, וכמעט פרחה נשמתם מן הכאב ומן הבושה. ועל זה אמר אבא כהן ברדלא (ב\"ר צג, י וראה ילקו\"ש תהלים רמז תשס\"ב), אוי לנו מיום הדין אוי לנו מיום התוכחה, בלעם, חכם של העובדי כוכבים לא יכול לעמוד בתוכחתה של אתונו וכו', וכן יוסף קטנן של שבטים היה, ולא היו יכולים לעמוד בתוכחתו, ההוא דכתיב ולא יכלו אחיו לענות אותו כי נבהלו מפניו. לכשיבא הקב\"ה ויוכיח כל אחד ואחד לפי מה שהוא, שנאמר (תהלים נ, כא), אוכיחך ואערכה לעיניך, על אחת כמה וכמה. ע\"כ. ובאמת הדברים נוראים כי לעתיד לבא ביום הדין והמשפט הקב\"ה שואל את האדם מתוך הנהגתו שלו, ומראה לו איך כל הנהגתו מלאה סתירות.","b":false},{"t":"ונחזור לעניננו שיוסף פנה לאחיו ואמר להם, בואו ואראה לכם איך היתה הנהגתכם עמי רעה ונלוזה. כי אתם דנתם אותי כאויב ורודף, וסמכתם בטענותיכם על החלומות אותם סיפרתי לכם כמסיח לפי תומי, שהאלומות והשמש והירח משתחוים לי, ואתם טענתם שחלומות אלו הם תוצאות ההרהורים שבהם הגיתי במשך הימים (ראה ברכות נ, ב), ומזה למדתם שאכן כל מחשבותי הן רק להשתלט עליכם ולמשול בכם, והוספתם על זה עוד טענות כהנה וכהנה, כיד הדמיון המלובה ע\"י הקנאה שהתעוררה בלבכם וילדה שנאה כדרכה. ואחר זה הכל התהלך לפי נטיית לבכם. כי כל ישרה עיקשו (ראה ישעיה נט, ח ובמפרשים שם), כדרך השונא, שגם אם יראה דברים ישרים אצל שנואו, יטה אותם לכיוון הרע בלא היסוס. וזה מה שקרה עם אחי יוסף.","b":false},{"t":"והמשיך יוסף ואמר לאחיו, הלא אתם אנשי אמת ושונאי שקר, ועם כל זה לקחתם את כתונתי שהפשטתם ממני וטבלתם אותה בדם גדי עזים והבאתם אותה לאבינו הזקן, ובצורה נוראה אמרתם לו, \"הכר נא הכתונת בנך היא\", ואחר שאבא ראה זאת הוכרח לצעוק ברב יגון \"טרוף טורף יוסף\", ולא התנחם מאבלו.","b":false},{"t":"והנה בודאי שמעשה נורא זה נבע אצלם מכך שידעו כי אביהם לא יקבל את פסק דינם על יוסף שהוא בבחינת רודף וצריך להרגו. כי לרוב אהבתו הטבעית ליוסף לא יוכל לראות בו שום עולה. ולא יסכים למעשה האחים בשום פנים שבעולם. ועל כן אמרו לו, \"הכר נא\" משום דרכי שלום בית.","b":false},{"t":"והאחים דימו להשקיט את מצפונם, באמרם, שגזר הדין שחרצו על יוסף, אמת וישר הוא, כי כן ראוי לנהוג במי שרוצה לשלוט עליהם ולרדותם, ולעשותם לו לעבדים. ועל מה סמכו באמרם שיוסף רוצה לשלוט עליהם ולרדות בהם ולעשותם לעבדים. על החלומות! אבל לא נתנו את לבם אל האמת היותר פנימית, שלחלומות שחלם יוסף קדמה שנאה אחרת, והיא השנאה והקנאה שבאה בשביל \"כתונת הפסים\", ושנאו את יוסף כל כך עד שלא יכלו דברו לשלום. ואחר שכבר שנאו את יוסף, אז גם בשמעם את דברי חלומותיו, תיכף יחסו לו דברים שלא נתכוין אליהם כלל. וגמרו בדעתם שהוא רוצה להזיק להם ולרדותם ולהפכם לעבדים, מה שלא חשב ולא עלתה על לבו מעולם.","b":false},{"t":"ואלו הן תוצאות השנאה, אשר עיורה עיני שכלם לגמרי. כי הנה אחי יוסף \"החליטו בדעתם\" שגם במעשה הזה דעת יעקב נוטה לדברי בנו יוסף ולא לדבריהם, כי אותו אהב אביהם מכל בניו. ולכן עיותו את דינו לגמרי, ולא ביקרו את מעשיהם, בשמיעת חות דעת נוספת, ולא שמו לב שהם הם שנטו מקו האמת. וכבר אמרו רבותינו (תוספתא הובאה בדברי התוס' יבמות צד, א ד\"ה כי תבעי, ובדברי הרא\"ש שילהי יבמות), גדולה שנאת השונאות מאהבת האוהבות, כלומר, שמה שאדם מוכן לעשות בשביל השנאה הוא יותר ממה שאדם יעשה בעבור האהבה. ולכן האחים לא חשבו בדעתם שום לזכות את יוסף ולומר, ראו איזה נער תמים בן שבע עשרה חולם חלומות של גדולה, יערבו עליו חלומותיו. והם לא עשו כן, אלא תיכף נכנסו להתמודדות וקנאה עצומה, והסיתו את הכל לענין אחר לגמרי, \"המלוך תמלוך עלינו אם משול תמשול בנו\" (בראשית לז, ח), ולא יכלו לראות את הדברים בצורה אחרת. אבל יעקב אבינו שהיה נקי מקנאה ושאר נגיעות, הוא שמר בלבו את חלום בנו וציפה מתי יתקיים החלום כמבואר (שם שם, יא ובפירש\"י שם). כי זו היא דרך השונא, כל דבר שיראה בחבירו אפילו אם יהיה טוב ונחמד יצבע אותו בצבעים קודרים, ויעות אותו ויתן בו פירושים לא נכונים.","b":false},{"t":"וכך חיו האחים בטעות זאת, שיסודה בנוי וסמוך על שנאה שיצרו בלבם כלפיו במשך כ\"ב שנים, ולא עלתה בלבם לחשוב אולי אין הדבר כן, ואולי בסך הכל חלומות יוסף היו חלומות אמת של נער תמים וישר. וכל אותם שנים המשיכו האחים בדרכם זו, ולא שמו לב לבקר את מעשיהם אפילו פעם אחת. ועתה המשיך יוסף ואמר להם, כיון שכל מטרתכם היא בירור האמת, א\"כ תנו נא לי ואשאלה מכם שאלות, אני יוסף העוד אבי חי? ענו לי, איך לא חשתם על צערו של אבא. ועוד ענו לי במה היה בטחונכם כה רב שחלומותי באו רק לבזותכם ולרדות בכם, הלא תראו כי כל מה שחלמתי הכל נתקיים לגמרי לא נפל דבר אחד מכל החלומות ארצה, וא\"כ על מה היתה סמיכתכם לדון אותי לכף חובה. וכשראו האחים את האמת יוצאת לאור בגלוי ובבהירות נפלאה, נבהלו מפניו מאד ולא יכלו לענות אותו.","b":false},{"t":"ואפשר עוד להוסיף, שיוסף חישב והכין את הענין מראש, להביא את בנימין אליו, למרות ידיעתו הברורה שהדבר יצער את אביו מאד. כי רצה לבחון את אחיו בטרם יודע אליהם, לראות האם שבו מדרכם הרעה, ועד כמה הם נכונים למסור את נפשם על הצלת אחיהם. וגם להביא את יהודה שנתן את העצה למכרו למצב בו יגיעו שניהם להידברות גלויה בכדי ללבן את הענין. ולכן חיכה יוסף שיהודה ראש האחים ידבר ואז השיבו אף הוא דברים נכוחים, וזאת היתה השעה הכשרה והמתאימה בעיניו לגלות את עצמו לאחיו. כדי להפיק מזה את החיזוקים הראויים ללמוד, מכל אשר עבר עליהם, כדי שישובו לחיות יחדיו כמשפחה מלוכדת ומאוחדת.","b":false},{"t":"וכח אמונתו ותומתו של יוסף הם שעמדו לו בכל אשר עבר עליו, הן מתלאותיו עם אחיו בני אביו, והן עם הסוחרים והמדינים והמצרים, ועד אחרון הגדיל הנסיון הקשה שעבר עליו בבית פוטיפר, ואשר בעקבותיו הושם בבית האסורים, על לא עול בכפו, וגם הנסיונות של המלוכה והממשלה. ועם כל הנסיונות האלו יוסף הצדיק נשאר בצדקתו ותומת יראתו, ולא נע ולא זע מדרך אביו הגדול אפילו כמלא נימא, ועיניו נשואות צופיות לעתיד בית אביו ובניהם, לראות כדת מה לעשות כדי להטיב אחריתם מראשיתם.","b":false},{"t":"וכן דרכן של הצדיקים בכל הדורות, אשר מתעלמים מהצרות העוברות עליהם, ועיניהם לנוכח יביטו, להתפלל ולדרוש טובת עמנו ואחריתו, דרך כלל ופרט. ועינינו הרואות פני צדיק קדוש ה' המופלא וכבוד ה' מלא, אשר על ידו התקדש שם ה' בכל אתר, והתאהב על הבריות, אשר למרות אשר עברו על ראשו מים הזדונים, ברדיפות אויבי ישראל, עד להריגת אחיו הגדול, קדוש ה' מכובד, עטרת ראשינו המלך דוד זצללה\"ה והי\"ד. אשר אותו העריץ רבנו והוקיר, וראהו כאב רחמן, והאח הקדוש הזה נהרג על קדושת שמו יתברך, כדי להציל את כל עדת ה' מכליה רח\"ל. ועוד כמה וכמה הרפתקי דעדו עליו, ומעולם לא שינה רבנו דרכו, ולא הסיר לרגע את עיניו ולבו מדאגה לכלל ישראל, עד שכל כולו היה מסור לטובת הכלל. ימיו צומות, ולילותיו תפלות, זכות וסלולות, מקירות לבו עולות, לפני כסא כבוד ה' ב\"ה, ומי יוכל לשער ולמדוד כמה ישועות נעשו בכח תפלותיו ותורתו.","b":false},{"t":"וגם מהפרט לא הניח את ידו, וכאשר ראינו באותם שנים ששב לאה\"ק וקבע בה ישיבתו, אשר ביתו היה פתוח לכל דורש ומבקש, אחד חכם ואחד תם, כולם נקבצו באו, להביא מרירותם וסבלותם, ולתנותם לפניו שיעתיר בעדם לפני הקב\"ה, ולבו היה פתוח לו כאולם, וקיבלם באהבה ובנדבה, ובמאור פנים, ואמרי נועם, לעודדם ולחזקם, והיה מחיה מתים במאמרו, עד אשר אדם שבא שבור ונדכה, ומיואש כמאן דליתיה, היה מקבל את ברכתו אשר ברכו, ומילת העידוד שהיתה שגורה על פיו, לכל סובל ונדכא לפי ענינו, דבר דבור על אופנו. והיו הכל יוצאים מלפניו בשמחה.","b":false},{"t":"וכמה ישועות נפלאות נעשו על ידו בגלוי ובבירור, לאין קץ ואין תכלה, ודורות רבים לא נראה כבושם הזה, אשר כל העולם ראו ואמרו, שכל היוצא מפיו נעשה ומתקיים, וראו כי שם ה' נקרא עליו, ודבר ה' היה בפיהו אמת. ואם אנו רואים עד היום. שהאמונה מתפשטת ומשתרשת בלב רחוקים וקרובים, ומאמינים בה' ובמשה עבדו, ודורשים ברכות ובקשות מן החכמים, ורבים מהם מתיהדים, וחוזרים לדרכי אבותיהם, באהבה ובדבקות, אשר לא יאומן כי יסופר, הרי בודאי שהיה בזה חלק הראוי להתכבד לרבינו זיע\"א.","b":false},{"t":"וגם מקום מנוחתו, ציו'ן המציונת, הפכה לאבן שואבת לרבבות אלפי ישראל בכל ימות השנה, והיה כאשר יחשוש אדם הן גדול והן קטן, איש או אשה, באיזה כאב או מיחוש, או קושי פרנסה, או עיכוב בנישואין, וכן כל מי שעדיין לא נפקד בזרע קודש של קיימא, מקיימים בנפשם וקמת ועלית אל המקום, ושם נפתחים מעינות לבם ועיניהם, ושופכים שיחם ומר רוחם לפני ה' ב\"ה וברוך שמו, בפני עבדו חסידא קדישא רבינו ישראל אביחצירא זללה\"ה וזיע\"א, באמונה שבזכותו יתקבלו התפלות, ויתבטלו הגזירות הרעות מעליו ומעל בני ביתו. כי הקב\"ה ישתבח שמו חס על כבוד עבדיו האמיתיים, ולא משיב פניהם ריקם, והם גוזרים והוא מקיים (ראה מו\"ק טז, ב ותנדא\"ר פ\"ב), ובפרט לצדיקים המוסרים את כל כחם למען כלל ישראל, אשר אין לו להקב\"ה יקר מזה. ורואה במדה הנפלאה הזו שמניחים צרותיהם ותלאותיהם, ועומדים ומעוררים רחמים על צרות הכלל והפרט, וגם הוא ישתבח שמו נוהג בהם בעין חמלתו. ומקדש שמו על ידם, להראות לכל באי עולם את יקרתו ואהבתו לעושי רצונו, לעיני כל באי עולם. אשרינו אנו שזכינו לראות הוד פני קדשו בחיים חיותו, ונהנינו מאמרי פיו כי נעמו, ובני הדור הצעיר שלא זכו לראותו, ישאלו את אבותיהם ויגידום, זקניהם ויאמרו להם, ויקחו עמם דבריהם, וישובו אל ה' ב\"ה.","b":false},{"t":"וזכות הצדיק הקדוש הזה תעמוד לנו בעת ובעונה הזאת להושיענו בישועה וברחמים, ובא לציון גואל במהרה בימינו אמן.","b":false},{"t":"(בעזהית\"ש, מוצש\"ק ויגש התשס\"ז ערב צום עשרה בטבת יה\"ל וששון ושמחה בב\"א)","b":false}]}]},{"slug":"ויחי","name":"פרשת ויחי","items":[{"id":"22","t":"ברכה בשם \"האלהים\" היא ברכה תמידית המתקיימת לעד","p":[{"t":"וַיְבָרֶךְ אֶת יוֹסֵף וַיֹּאמַר הָאֱלֹהִים אֲשֶׁר הִתְהַלְּכוּ אֲבֹתַי לְפָנָיו אַבְרָהָם וְיִצְחָק הָאֱלֹהִים הָרֹעֶה אֹתִי מֵעוֹדִי עַד הַיּוֹם הַזֶּה, הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים וְיִקָּרֵא בָהֶם שְׁמִי וְשֵׁם אֲבֹתַי אַבְרָהָם וְיִצְחָק וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ: (מח, טו-טז)","b":true},{"t":"בשעה שבירך יעקב את יוסף פתח בשם \"האלהים\" והמשיך ב\"המלאך\" הגואל אותי מכל רע וגו'. ויש להבין למה לא בירכם יעקב בשם הוי\"ה שהוא שם של רחמים.","b":false},{"t":"אמנם יש לומר שיעקב אבינו ע\"ה אחז בדרך אביו בברכו אותו, שיצחק אמר ליעקב (בראשית כז, כח), ויתן לך האלהים מטל השמים וגו'. והנה בכתבי האר\"י ז\"ל איתא, דאע\"ג דשם אלהים הוא דין, מכל מקום, כאשר מוסיפים אות ה' לשם אלהים, הריהו מתמתק ואין בו מדת הדין אלא רחמים, כי אלהים עולה בגימ' פ\"ו, ולכשתוסיף אות ה' עולה בגימ' צ\"א כמספר הוי\"ה אדנו\"ת המורה על מיתוק הדינים. כי שם הוי\"ה שהוא רחמים מתלבש על אותיות דאדנו\"ת וממתיק אותם. והכי נמי אות ה' ממתקת את שם אלהים, ואפשר שהאות ה' רומזת לחמשה חסדים, חסד, גבורה, תפארת, נצח, הוד. והם ממתיקים את חמש האותיות דאלהים שהם כנגד ה' גבורות. ועל כן בירך יצחק את יעקב במדה זו, ויתן לך האלהים (וראה מה שנתבאר בפרשת תולדות מאמר יב).","b":false},{"t":"ונראה לענ\"ד דיש בזה ברכה גדולה, כי אם היו יצחק ויעקב מברכים בשם הוי\"ה, אזי המתברכים היו זוכים לברכה רק כשהם ראויים למדה זו, אבל אם יחטאו ח\"ו, הרי כבר אמר רבותינו (ב\"ר לג, ג ושם עג, ג ובילקו\"ש בראשית רמז נז), שהרשעים מהפכים את מדת הרחמים למדת הדין רח\"ל. וא\"כ לא יוכלו לזכות לברכות.","b":false},{"t":"לכן בחכמה עשו אבותינו ובירכו את יוצאי חלציהם בשם \"האלהים\" שענינו מיתוק הדינים, וגם בשעה שמדת הדין מתוחה, הרי הדינים מתמתקים מכח שם \"האלהים\".","b":false},{"t":"ובזה פירשתי מה שנא' (תהלים סז, ב), אלהים יחננו ויברכו יאר פניו אתנו סלה. היינו, שאם זוכים, אז גם מדת הדין מסכמת לברכה ע\"י ההתמתקות, וזהו \"אלהים יחננו ויברכנו\", ואז הברכה הזו היא המעולה שבברכות, ונמשכת לעולם, כמו שממשיך ואומר, יאר פניו אתנו \"סלה\", היינו שהיא ברכה ללא הפסק, באין מקטרג ומחריד.","b":false},{"t":"ועל כן בירך יעקב את יוסף ואמר, \"האלהים\" אשר התהלכו אבותי לפניו אברהם ויצחק, כלומר, זו היא המדה שבה בירכוני אבותי אברהם ויצחק. ואם תשאל במה היה להם כח לברך בשם \"האלהים\" היינו שיכולים להמתיק את הדינים. לזה המשיך ואמר, אשר התהלכו אבותי לפניו, היינו, כי האבות הקדושים היו עובדים את הי\"ת עבודה שלימה ותמה, עד שלא היה למדת הדין שום פתחון פה עליהם, ולכן לא נזקקו לרחמים כלל, ולכן יכלו לברך את יוצאי חלציהם בשם \"האלהים\", כי בדרך שאדם מודד מודדין לו מדה כנגד מדה (ראה משנה סוטה א, ז ובגמ' סנהדרין ק, א).","b":false},{"t":"ואחר כך המשיך יעקב אבינו ע\"ה ואמר, \"האלהים\" הרועה אותי מעודי עד היום הזה, כלומר, שגם הוא המשיך את דרך אבותיו בקודש, וכאשר היתה עבודתם כן היתה עבודתו בקודש, ולכן גם עליו לא היה למדת הדין שום פתחון פה, ולכן גם הוא יכול לברך את בניו כפי שנתברך מאבותיו, וזה מה שעשה ויברך את יוסף וגו'","b":false},{"t":"והנה ראיתי להרשב\"ם ז\"ל שכתב ויברך את יוסף, ברכת הבנים היא ברכת האב, וכן נראה גם דעת הרמב\"ן ז\"ל. ורבינו הקדוש מהר\"ח ן' עטאר זלה\"ה בספר אוה\"ח הקשה למה לא יברך את יוסף עצמו. וכתב לתרץ וזה לשונו: והנכון בעיני, כי בתיבת \"ויברך\" רשם הכתוב כי בירך [יעקב] ליוסף שיהיה תמיד מבורך. עוד יתבאר על פי דבריהם שאמרו (במדב\"ר יא, ב), שמפתח הברכות היה ביד אברהם ומסרו ליצחק, ויצחק מסרו ליעקב, ויעקב מסרו ליוסף, והוא אומרו ויברך וגו', פירוש מסר בידו [את] מפתח הברכות.","b":false},{"t":"ועל פי מה שביארתי בס\"ד עולה שיעקב אבינו ע\"ה מסר את מפתח הברכות ליוסף ממש באותה מדה כפי שנמסרה לו הברכה, והיא הברכה בשם \"האלהים\", וכאמור.","b":false},{"t":"ועדיין צריך להבין למה בהגיע יעקב לבני יוסף, עזב את שם \"האלהים\" ואמר המלאך הגואל אותי וגו', ולמה הוצרך לברכם ע\"י המלאך.","b":false},{"t":"אמנם נראה בזה, כי \"מלאך\" עולה בגימטריא צ\"א שהוא גם עולה בגימ' הוי\"ה אדנו\"ת וכמו שם \"האלהים\", שענינם מיתוק הדינים. והנה אפשר שחשש יעקב אבינו ע\"ה שבני יוסף לא יוכלו להגיע לדרגתו ולדרגת אבותיו להתהלך לפני \"האלהים\", והיה חושש שלא יוכלו להשיג את אותה ברכה. לכך תיכף אחר שבירך את יוסף ב\"האלהים\" וגו', בירך את בניו ב\"המלאך\" הגואל אותי וגו' יברך את הנערים. כי את הברכה הזאת יוכלו להשיג על כל פנים. ושוב ראיתי לרבנו עובדיה ספורנו ז\"ל שכתב, וז\"ל, המלאך הגואל אותי מכל רע יברך וגו', ציוה שהמלאך הגואל אותי יברך את הנערים, אם אינם ראויים לברכתך בלתי אמצעי. עכ\"ל. ושמחתי שכיונתי לדב\"ק בזה.","b":false},{"t":"ומיד הוסיף יעקב ובירכם \"ויקרא בהם שמי ושם אבותי\", כלומר, שלא יתנתקו מאבותיהם ח\"ו, כאשר הם לא זוכים להתברך בשם \"האלהים\" כאבותיהם, אלא ע\"י מלאך, לזה אמר ויקרא בהם וגו', כלומר, שגם אם יהיו במצב שאינם ראויים לילך במדת אבותיהם אברהם יצחק ויעקב, בכל זאת ויקרא בהם שמי ושם אבותי וידגו לרוב בקרב הארץ.","b":false}]},{"id":"22","t":"חינוך הילדים לכתחילה אך ורק לתורה","p":[{"t":"וַיִּקַּח יוֹסֵף אֶת שְׁנֵיהֶם אֶת אֶפְרַיִם בִּימִינוֹ מִשְּׂמֹאל יִשְׂרָאֵל וְאֶת מְנַשֶּׁה בִשְׂמֹאלוֹ מִימִין יִשְׂרָאֵל וַיַּגֵּשׁ אֵלָיו, וַיִּשְׁלַח יִשְׂרָאֵל אֶת יְמִינוֹ וַיָּשֶׁת עַל רֹאשׁ אֶפְרַיִם וְהוּא הַצָּעִיר וְאֶת שְׂמֹאלוֹ עַל רֹאשׁ מְנַשֶּׁה שִׂכֵּל אֶת יָדָיו כִּי מְנַשֶּׁה הַבְּכוֹר: (מח, יג-יד)","b":true},{"t":"דבר ברור שהיו כאן שני הסתכלויות שונות, שיוסף שקל במאזני חכמתו, והעדיף את מנשה מאפרים לפי שהוא הבכור, וגם הוא לומד תורה וירא שמים. וגם היה יד ימינו בעניני המדיניות, והנהגת העם והממלכה. ואיש כזה הקרוב לשלמות, ומשלב בקרבו את שתי התכונות, הוא המיומן והמזומן לברכה המיומנת והנבחרת, והוא האיש הראוי שהסבא קדישא ישית על ראשו את יד ימינו. והיה הדבר הזה ברור לפניו כל כך, עד שחשב שאביו טועה בין שניהם, וע\"כ שם את יד ימינו על ראש אפרים והוא הצעיר. ולכן תמך יוסף ביד אביו כדי להסיר אותה מעל ראש אפרים, וליתנה על ראש מנשה, ואמר לו תוך כדי כך, לא זה הבכור אלא זה.","b":false},{"t":"ואולם אביו רוח אחרת עמו, וגם ראיה אחרת לו בענין זה, והוא מחשיב את הת\"ח המשקיע כל כחותיו בלמוד התורה, לעיקר, כי אעפ\"י שזה ג\"כ ת\"ח ויר\"ש ומדקדק בקלה כחמורה, ועוד מעלה יש בו שהוא מבין יפה ומנהל מצוין את עניני הממלכה והעם, אבל לא זו התכלית ולא זו המטרה של היהודי בעולם, שכן לא נברא העולם אלא בשביל התורה, ולא מתקיים אלא על ידי התורה, ואין קיום לתורה אלא על ידי ישראל, אשר להם נתן הי\"ת את התורה, ועיקר קניני התורה הוא רק לממיתים עצמם, ומתנזרים מתאוות העולם, ונותנים את כל כחם עליה, ועל כן מיאן יעקב להסיר את יד ימינו מעל ראש אפרים, וגם דאג להבהיר לו ליוסף שהוא יודע היטב מי הבכור ומי הצעיר, כאומרו (להלן מח, יט), ידעתי בני ידעתי גם ידעתי, היינו, ידעתי את מציאות הענין, מיהו הבכור ומיהו משנהו, וגם ידעתי את הלך מחשבתך, שזו הדרך היותר מקובלת בעולם. אבל יודע אני עוד מה העיקר ומה החשוב יותר בחובתו של האדם בעולמו, ומה התכלית אליה הוא נברא.","b":false},{"t":"ובתוך הדברים אמר יעקב ליוסף שאינו שולל לגמרי את הדרך של מנשה, כי גם הוא יהיה לעם וגם הוא יגדל, כלומר, בודאי שלא כל העם יכולים לעמוד ברום המדרגות, ולהיות לנים בעומקה של הלכה יומם ולילה, ולתת את כל כחם ועמלם רק בתורת ה'. כי לרוב העם יש צורך לעסוק בעניני המחיה והכלכלה, והנהגת העם והממלכה. אך מכל מקום צריך לחזק אותם, שלא יעזבו את למוד התורה ויעסקו בה בכל עת פנאי, ויחזיקו ביראת ה' טהורה לעולם. ואולי לזה רמז יעקב באומרו על מנשה (להלן מח, יט), גם הוא יהיה \"לעם\", כלומר, יודעני שזו הדרך היותר מקובלת לרוב העם, ואולם אחיו הקטן יגדל ממנו. כי זו המעלה הגדולה ביותר שאליה צריך לשאוף כל איש מישראל. ומשאת נפש כל הורה צריכה להיות שיזכה לבן גדול בתורה כאפרים, אשר כל כחותיו מנוצלים לתורה ודעתו עליה בכל עת בשבתו ובלכתו, ובכל צרכיו.","b":false},{"t":"ולא הסתפק יעקב אבינו ע\"ה בכל זה, אלא תיכף ומיד, כאב האומה ומנהיגה עשה מעשה רב, ומיד קבע מטבע קבוע לברכה זו, אשר בו ישתמשו כל בית ישראל עד עולם, כאמור (להלן מח, כ), ויברכם ביום ההוא לאמר, בך יברך ישראל לאמר, ישימך אלהים כאפרים וכמנשה, וישם את אפרים לפני מנשה.","b":false},{"t":"ופירש\"י ז\"ל (שם), בך יברך ישראל, הבא לברך את בניו, יברכם בברכתם, ואמר איש לבנו ישימך אלהים כאפרים וכמנשה. והראב\"ע ז\"ל כתב (שם), בך יברך ישראל, כל בני ישראל, והרשב\"ם ז\"ל (שם), כתב, בך יברך ישראל, איש איש את בנו. ועיין בדברי הרמב\"ן ז\"ל (שם). והברכה הזאת שגורה מאז בפי כל אב ואם מבני ישראל, בבואם לברך את בניהם, בלא שום שינוי כלל.","b":false},{"t":"וצריכים אנו לשים ליבנו לנוסח ברכה זו, אשר יש בה פסיקה וקביעה לדורות, שהיא, וישם את אפרים לפני מנשה (להלן מח, כ). ושימת הלב צריכה לבא לידי ביטוי בדרך בה הננו מחנכים את ילדינו, ובקביעת אמות המדה ורמת המדרגות, אותה אנו מציבים לפני ילדינו, ולכונם אל הדרך המובחרת ביותר. כי מלכתחילה כולם צריכים לשאוף אל היותר טוב ולא להתפשר עליו. ורק אם מתברר בבירור גמור שהילד לא יוכל להגיע אל הדרגה הנכספת שהיא דרגת \"אפרים\", וזאת, מפאת מגבלות מסויימות ברמת הכשרון, או ביכולות הגופניות שלו, רק אז יש לסגת מעט ולחפש חלופות המתאימות אל נפש הנער.","b":false},{"t":"ואת זה לימדנו יעקב אבינו איש האמת, מה היא מדת האמת בענין חינוך ילדינו, ואל מה צריכים לשאוף. ולזה אמר, בך יברך ישראל וגו', וישם את אפרים לפני מנשה. שהמעלה הראשונה היא מעלת אפרים אשר כל כולו עמלה של תורה וקדושה, ולא כפי המקובל לחשוב. ולכן, וישם את אפרים לפני מנשה.","b":false},{"t":"ובזה תתיישב קושיא שמקשים, איך מברך אדם את בנו לאמר, ישימך אלהים כאפרים וכמנשה, והרי צריך להחליט ולברכו ברור שיהיה או כאפרים, או כמנשה, אבל לא כשניהם שזה דבר לא נכון ולא יתכן כלל, ברם לפי מה שביארתי יש כאן מסירת \"אמת המדה\" של לכתחילה, ומה שבא לאחריה, והואיל ולא כל אחד יכול לעמוד בדרגה גבוהה כל כך ולעמול בתורה הי\"ת יומם ולילה, וא\"א לנעול השערים בפני כל אדם, באמור לו כזה ראה וקדש, ואין שום דרך אחרת.","b":false},{"t":"על כן אומרים לו שיש גם את דרכו של מנשה, שהוא ת\"ח ויר\"ש וגם עוסק בענין עוה\"ז, אבל מדגישים לו ונוטעים בלבו את הידיעה הברורה והאמיתית, \"וישם את אפרים לפני מנשה\".","b":false},{"t":"ובאמת שכבר נחלקו בזה רבותינו (ברכות לה, ב), דתנו רבנן, ואספת דגנך (דברים יא, יד), מה תלמוד לומר, לפי שנאמר (יהושע א, ח), לא ימוש ספר התורה הזה מפיך, יכול דברים ככתבן, תלמוד לומר ואספת דגנך, הנהג בהן מנהג דרך ארץ, דברי רבי ישמעאל. רבי שמעון בן יוחאי אומר אפשר אדם חורש בשעת חרישה וזורע בשעת זריעה וקוצר בשעת קצירה ודש בשעת דישה וזורה בשעת הרוח, תורה מה תהא עליה? אלא בזמן שישראל עושין רצונו של מקום מלאכתן נעשית על ידי אחרים, שנאמר (ישעיה סא, ה), ועמדו זרים ורעו צאנכם וגו', ובזמן שאין ישראל עושין רצונו של מקום וכו', אמר אביי הרבה עשו כרבי ישמעאל ועלתה בידן. ע\"כ. והנה רבינו הגר\"א הדגיש \"רבים עשו כרבי שמעון ולא עלתה בידם\", אבל מעטים עשו כרבי שמעון והצליחו.","b":false},{"t":"[א\"ה הנה מכל זה מתבאר החיוב לבחור בתחילת את הדבר היותר נעלה עבור הבנים, שיהיו עסוקים אך ורק בתורה כדרגת אפרים, ולא יעלה על הדעת לחפש בשביל הילדים דבר שהוא \"בדיעבד\" ולא \"לכתחילה\". ומה נפלאו דברי רבותינו (ויקרא רבה ב, א), במה שדרשו על הפסוק (ירמיה לא, יט), הבן יקיר לי אפרים, ביוקר ישראל עומדים לי, בנוהג שבעולם אלף בני אדם נכנסין למקרא יוצאין מהם מאה, מאה נכנסין למשנה, יוצאין מהן עשרה לתלמוד, עשרה נכנסין לתלמוד אחד יוצא [להוראה] יעו\"ש. והנה בודאי שכל אדם צריך לחפוץ שבנו יהיה אותו האחד שבאלף בחורי ישראל הוא יוצא ומשתבח, יבח\"ר].","b":false}]},{"id":"22","t":"כשאדם מברך את חברו וקרובו הברכה צריכה לבא מתוך התעוררות אהבה והכנה ושימת לב","p":[{"t":"וַיּוֹצֵא יוֹסֵף אֹתָם מֵעִם בִּרְכָּיו וַיִּשְׁתַּחוּ לְאַפָּיו אָרְצָה: (מח, יב)","b":true},{"t":"צריך להבין מה היה טעמו של יוסף בהוצאה זו, והלא יעקב אבינו עוד לא בירך את בניו, כפי שרואים ממהלך הפסוקים, אלא רק חיבקם ונישקם ותו לא.","b":false},{"t":"ונראה שיש מכאן לימוד דרך ארץ, שגם בבוא יוסף לבקש ברכת אביו עבור בניו שהם נכדי יעקב, עדיין צריך לשמור חוק דרך ארץ ולא יעבור. כי יוסף ראה את מעשה אביו מתוך התבוננות עמוקה, ורצה להבין עניניו בכובד ראש הראוי. והבין יוסף שהחיבוק שחיבקם ונישק יעקב את בניו, הוא כהכנה לברכה שתהיה מתוך התעוררות של חיבה, ואתערותא דלתתא גורמת התעוררות דלעילא (זוהר ח\"ב קפד, ב). וכן מה שאמר יעקב אבינו ע\"ה ליוסף ראה פניך לא פללתי וגו' (בראשית מח, יא), הוא ג\"כ כדי לעורר בעצמו התרגשות פנימית מעומק לבו הטהור כדי שתהיה הברכה מלאה.","b":false},{"t":"ורצה יוסף לתת רווח בין הענינים, כדי שאביו ינוח מעט, ויכין הראוי לו, כדי שיברך אותם ברכה מתוקנת בכל מכל כל, ולא יתקל בלשונו, ותהי תפלתו עליהם מסודרת ושלמה.","b":false},{"t":"ובספר דעת זקנים מבעלי התוספות כתבו, שמפני שרצה יוסף לסדרם כדי שיניח ידו עליהם לכך הוצרך להוציאם מעם ברכיו, ולהרחיקם מעט, ולשום אותם למול ידיו. ע\"ש. ועיין במה שכתב הראב\"ע ז\"ל. ומ\"מ קשה כי הלא עדיין היה אפשר לעשות כן בלא להוציאם מעם פניו. ולכן י\"ל דרצה יוסף לנהוג באביו בדרך ארץ ובנחת, ולשים רווח בין עדר ובין עדר.","b":false},{"t":"[א\"ה ומתוך כל זה יראה האדם ויקח לקח לעצמו, בבואו לברך את חברו או אחד מבני ביתו, שלא תהא ברכתו כשיגרת לשון ולא עוד. כמו שנזדמן לידי פעם שבא לפני אדם מלא ביסורין ותינה בפני את צרותיו, ואז אמרתי לו יה\"ר שהי\"ת יעזור לך בכל עניניך. ואז הוא אחז בידי ואמר לי, רבי! למה אינך מברכני מכל לבך, והוכיחני על פני, ואמר, לא די לי בכאבי אלא שאתה פוטר אותי במטבע לשון שגורה בפי הכל. ואז אמר לי כשבא לפניך אדם הנצרך לישועה תחשוב על מצבו ועל כאבו, ואז תפנה מעומק הלב לפני הקב\"ה ותברכהו ותתפלל שתתקבל ברכתך. והוסיף ואמר, שמובטח לו שאם היו מברכים האחד את רעהו בצורה הזאת היו נושעים. והדברים מחייבים. ולכן כמה חשוב שכל אדם בשמעו את צרת אחיו אל יאטום לבו במהרו לזרוק איזה משפט ברכה כגון רפואה שלימה וכדו', אלא לרגע ידום ויחשוב על כאבו של השני, ואז יתעורר לברכו מכל לבו, ואז הברכה תעשה פירות, אכי\"ר. יבח\"ר].","b":false}]},{"id":"22","t":"בכל דרכיך דעהו וכבדהו","p":[{"t":"וַיֹּאמֶר יוֹסֵף אֶל אָבִיו בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה וגו': (מח, ט)","b":true},{"t":"ראיתי להביא מדברי קדוש ה' מכובד רבינו חיים ן' עטאר זיע\"א מש\"כ בספר אור החיים בזה, וזל\"ה:","b":false},{"t":"בני הם אשר נתן לי אלהים בזה, דרך הצדיקים כשזוכרים הטוב אשר הגיעם, חולקים כבוד לה', כי הוא הנותן, כאומרו (לעיל לג, ה), הילדים אשר חנן אלהים וגו'. ואומרו \"בזה\" כפי הפשט כי אפילו בימי גלותו בארץ נכריה חננו ה'. גם רמז למאמרם ז\"ל (סוטה לו, ב ופרדר\"א פל\"ח), כי עתיד היה יוסף להוליד י\"ב שבטים, וע\"י מעשה אשת פוטיפר נרזבו מבין צפורני ידיו י' טיפות ולא נשארו אלא ב', והוא שרמז באומרו בזה \"זה\" בגימטריא \"יב\" במקום \"יב\" נתן לו אלהים ב', ודקדק לומר אלהים, שיורה על המשפט. עכ\"ל.","b":false},{"t":"ויש בזה חידוש, בהנהגה שהזכיר קודם, שדרך הצדיקים שחולקים כבוד להי\"ת. ואפילו בכה\"ג שיוסף הצדיק הפסיד עשרה שבטים ונשארו רק שני שבטים במקום י\"ב, אפילו הכי היה מודה לה' וחולק לו כבוד על שני השבטים שנתן לו אלהים. ואילו את צערו על ההפסד הגדול שהפסיד עשרה, היה טומן ברמ'ז ומעלימו, וכמאמר בעל חובות הלבבות (שער הפרישות פ\"ד), על החסיד אשר צהלתו על פניו, ואבלו בלבו. טמון בעומק ובהעלם.","b":false},{"t":"וכן ראיתי מהזקנים, שתמיד היה כל דיבורם בשבח והודיה להי\"ת, ועל כל טובה, גדולה או קטנה, פיהם מלא הודאות ותהלות לאל עליון גואלם ברוך הוא לעד, ועל כל דבר שירצו לעשות, היו מקדימים לתלות הדבר ברצון העליון ובעזרתו, ואומרים אם יגזור ה' בחיים, ואם ירצה הקב\"ה, ולשונם לשון מרפא וברכה, ובקשת רחמים ורפואה וארוכה, והיה אצלם הדבר למטבע קבוע, אשר לא יסורו ממנו לעולמים. וזכורני שאבא מארי ז\"ל מעולם לא אמר שאינו רוצה לחם או מאכל אחר, אלא אם צריך לומר כעין זה, היה אומר הלחם לא רוצה אותי, וכהנה רבות. וכל זה מרוב הוקרה והערכה לכל מה שהי\"ת נותן, ואפילו הדבר הקל ביותר. ישמע החפץ ללמוד ויוסיף לקח וברכה.","b":false}]},{"id":"22","t":"להשתדל בחינוך הבנים עד קצה האפשרי – אמנם תוצאות העמל לא בידינו אלא ביד הי\"ת","p":[{"t":"וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיֹּאמֶר מִי אֵלֶּה, וַיֹּאמֶר יוֹסֵף אֶל אָבִיו בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה וַיֹּאמַר קָחֶם נָא אֵלַי וַאֲבָרֲכֵם: (מח, ח-ט)","b":true},{"t":"כתב רש\"י בשם חז\"ל (ראה תנחומא ויחי פ\"י), שנסתלקה ממנו שכינה, לפי שעתיד ירבעם ואחאב לצאת מאפרים, ויהוא ובניו ממנשה, וע\"ז שאל ליוסף מי אלה, מהיכן יצאו אלה שאינן ראויין לברכה. ויוסף השיבו, בני הם אשר נתן לי אלהים בזה. שהראה לו שטר אירוסין ושטר כתובה, וביקש רחמים על הדבר, ונחה עליו רוח הקדש.","b":false},{"t":"ויש לעיין בדבר, דאחר שיעקב ראה את בני יוסף ותמה ואמר לו, מהיכן יצאו אלו שאינן ראויין לברכה דהיינו ירבעם ואחאב ויהוא, א\"כ למה יוסף הוציא והראה לאביו שטר כתובה, ומה תועלת יש בזה.","b":false},{"t":"אמנם על כרחינו לומר, שיעקב אבינו חשש לברכם שמא שורש קלקולם של ירבעם אחאב ויהוא נעוץ ומושרש במנשה ואפרים, ולכך אינם ראויים לברכה. לזה בא יוסף ואמר, כי מנשה ואפרים באו בקדושה ובטהרה, והוא עשה את כל המוטל עליו בעבודת הקודש של חינוך הבנים. ולכן הוציא והראה לאביו את שטר הכתובה, להורות כי בניו יצאו מזיווג קדוש.","b":false},{"t":"וכבר מצאנו בחזקיה מלך יהודה שהיה צדיק גמור, ואמרו עליו (סנהדרין כ, א), שקר החן זה דורו של משה, והבל היופי זה דורו של יהושע, אשה יראת ה' היא תתהלל, זה דורו של חזקיה מלך יהודה. וחזקיהו הרבה תורה בדורו כל כך, עד שאמרו רבותינו (שם צד, ב), כי חיפשו מדן ועד באר שבע, ולא מצאו תינוק ותינוקת שאינן בקיאים בהלכות טומאה וטהרה. והוא הגבר הוקם על, שהקים עולה של תורה. ומצינו (ברכות י, א), שבא אליו הנביא ישעיהו ע\"ה ואמר לו בשם ה', הנך מת ולא תחיה, מת בעוה\"ז ולא תחיה לעוה\"ב, והודיעו שסיבת הדבר היא מפני שלא קיים מצות פריה ורביה. ואמר לו חזקיה ע\"ה, שהוא נמנע כי ראה ברוח הקדש, שעתיד לצאת ממנו מנשה, שיחטיא את ישראל בע\"ז, וכדי להציל את עצמו ואת עם ישראל, בחר להמנע ולא לשאת אשה כלל. והשיבו הנביא, מאי דמיפקדת איבעי לך למיעבד ובהדי כבשי דרחמנא למה לך. ואז אמר לו חזקיה לישעיה שיתן לו את בתו אולי זכות שניהם יעמדו לבני חזקיהו, ואכן נשא חזקיהו את בתו של ישעיהו הנביא שהיה גם נביא ה' וגם הוא מזרע בית דוד (ראה מגילה י, ב וסוטה י, ב), ועם כל זה יצא מנשה מחלציהם והוא הרבה לחטוא ולהרשיע מן המלכים הרשעים שהיו בדורות הקודמים לו (ראה במלכים ב' פרק כא), וסופו של דבר שהגלוהו לבבל והיו מצערים אותו וקרא לכל העבודות זרות שהיה רגיל לעבוד, עד שנתיאש מהם, ואז נשבר לבו וקרא אל ה', והושיעו ועשה עמו נס ופלא, והגיע לירושלים ושב אל ה' בכל לבו, והיה עובד ה' (כמבואר כל זה בדברי הימים ב' פל\"ג ובגמ' סנהדרין קא, ב).","b":false},{"t":"ועל כל פנים ברור ופשוט שחובת ההורים לעשות כל אשר לאל ידם בחינוך הילדים בקדושה ובטהרה, ובמדות טובות וישרות. וזה דורש יגיעה גדולה ועצומה, וכבר אמרו רבותינו (סדר הגדה של פסח), \"ואת עמלינו\" אלו הבנים. שבהם צריך להשקיע את כל עמלו לחנכם בדרך ישראל סבא. וגם אחר שעשה כל השתדלותו, אל יחשוב האדם בדעתו שכיון שכבר עשה את ההשתדלות הראויה די לו בזה, וצריך גם תפלה ותחינה דבר יום ביומו, וכולי האי ואולי.","b":false},{"t":"וכמו שראינו בזה שיוסף הראה לאביו את שטר האירוסין ושטר הכתובה, שהשתדל בקדושת הבית למרות התנאים הקשים, ולא עזב את מנהג אבותיו הק' ומצוותיהם. ולא הסתפק בכל זה אלא גם ביקש רחמים מלפני ה' על בניו, וכמש\"כ רש\"י ז\"ל.","b":false},{"t":"ועם כל זה עדיין אין הדבר תלוי רק בזה בלבד, כי יש דברים עמוקים מאד בשרשי הנשמות, שאין אדם יכול להבין ולידע בהם, ומי יעמוד בסוד ה', כי גם אחרי כל ההשתדלות של יוסף שהוא צדיק יסוד עולם, שמסר נפשו על טהרתו ועל טהרת בניו, ויעקב אבינו השתכנע שעשה את כל מה שיכל, ואמר לו, קחם נא אלי ואברכם, ובירכם, ונקבעה ברכתו למטבע קבוע לכל בני ישראל, לכל הבא לברך את בניו, בך יברך ישראל לאמר ישימך אלהים כאפרים וכמנשה (בראשית מח, כ), ועם כל זאת יצאו מהם ירבעם ואחאב וכו'.","b":false},{"t":"וזה בא ללמד שלא על ההשתדלות לבדה יחיה האדם, אלא יש ענינים אחרים שאינם תלויים בו, והוא שאמר הנביא ישעיהו לחזקיה המלך (ברכות י, א), בהדי כבשי דרחמנא למה לך. כי בכל הענינים האדם רשאי ויכול לחקור ולדרוש, אבל בענין הזה איך יהיו בניו וצאצאיו, הם דברים מופלאים, ונמצאים גבוה מעל גבוה, מה שאין אדם יכול להשיג בדעתו.","b":false},{"t":"אך מ\"מ אם באמת עשה את כל מה שבידו, השאר הוא בידי שמים ואין לו לעסוק בתוצאות, וגם זה הוא בכלל מאמר התנא באבות (ב, טז), לא עליך המלאכה לגמור, ואין אתה בן חורין ליפטר הימנה.","b":false},{"t":"וזה הענין כאן, כי יעקב אבינו ע\"ה שאל את יוסף מי אלה לך, ויוסף הצדיק הבין בחכמתו על מה אביו שואל, ולכך הראהו שטרי קדושין וכתובה, ללמדו שעשה את כל המאמצים הראויים מצדו, ובנוסף לאלו ביקש רחמים והתפלל, ומעתה הוא תלוי רק בחסדי ה' בלבד.","b":false},{"t":"וכשראה יעקב אבינו ע\"ה את כל זה, אמר, קחם נא אלי ואברכם. כי למרות שנשארה הנבואה במקומה, שעתידים לצאת מהם ירבעם וכו', מ\"מ משנודע לו, שיוסף נשא את אשתו בכתובה וקידושין ועשה כדין, ועשה את כל המוטל עליו בחינוך בניו, אין מעכב עוד על עצם נתינת הברכה, ולכן אמר, קחם נא אלי ואברכם. ושוב ראיתי בכלי יקר שגם הוא פירש בזה כדרכו בקודש, יעו\"ש. ויש חיזוק מדבריו למה שכתבתי בס\"ד.","b":false}]},{"id":"22","t":"במעלת קבורת אשה ליד בעלה - תפלת רחל על בניה","p":[{"t":"וַאֲנִי בְּבֹאִי מִפַּדָּן מֵתָה עָלַי רָחֵל בְּאֶרֶץ כְּנַעַן בַּדֶּרֶךְ בְּעוֹד כִּבְרַת אֶרֶץ לָבֹא אֶפְרָתָה וָאֶקְבְּרֶהָ שָּׁם בְּדֶרֶךְ אֶפְרָת הִוא בֵּית לָחֶם: (מח, ז)","b":true},{"t":"כתב רש\"י ז\"ל (וראה נמי בב\"ר פב, י), ואני בבאי מפדן וגו' - ואע\"פ שאני מטריח עליך להוליכני להקבר בארץ כנען ולא כך עשיתי לאמך שהרי מתה סמוך לבית לחם וכו'. ואקברה שם - ולא הולכתיה אפילו לבית לחם להכניסה לארץ, וידעתי שיש בלבך עלי, אבל דע לך, שע\"פ הדיבור קברתיה שם, שתהא לעזרה לבניה כשיגלה אותם נבוזראדן והיו עוברים דרך שם, יצאת רחל על קברה ובוכה ומבקשת עליהם רחמים שנאמר (ירמיה לא, יד), קול ברמה נשמע וגו', והקב\"ה משיבה יש שכר לפעולתך נאם ה' וגו' ושבו בנים לגבולם (שם טו, טז). ע\"כ. וכן הוא בפירוש רבינו אברהם ן' עזרא ז\"ל (שם), שכתב כעין זה. וכ\"נ גם מפירוש הרשב\"ם ז\"ל (שם). אמנם הרמב\"ן ז\"ל (שם), כתב שצריך על כל פנים שיהיה רמז במקרא לטעם זה שאמר באגדה זו. ועי' בדבריו שדקדק קצת בפסוק. יעו\"ש.","b":false},{"t":"ובתשובה שכתבתי בענין פינוי מת כדי לקוברו ע\"י קבר אשתו, (נדפסה בשו\"ת שמע שלמה ח\"ה חיו\"ד סימן י\"ט), הבאתי את דברי הירושלמי (סוף פ\"ב דמועד קטן), דאין מפנין את המת מקבר לקבר, מלבד לקבר אבותיו. כי ערב לו לאדם שיהא נח אצל אבותיו. ויש דיון אם ההיתר הוא בקבר אבותיו דוקא, או שהוא הדין נמי לפנותו ממקומו ולקוברו ליד קבר אשתו. והבאתי שם מדברי הפוסקים שרובם מקילים בזה.","b":false},{"t":"והזכרתי שם מה שאמרו רבותינו במסכת עירובין (נג, א), בטעם קריאת שם מערת המכפלה ואמרו שם, מערת המכפלה, רב ושמואל, חד אמר שני בתים זה לפנים מזה, וחד אמר בית ועליה על גביו, בשלמא למאן דאמר זה על גב זה היינו מכפלה, אלא למאן דאמר שני בתים זה לפנים מזה מאי מכפלה, שכפולה בזוגות. ממרא קרית ארבע, אמר רבי יצחק קרית הארבע זוגות, אדם וחוה, אברהם ושרה, יצחק ורבקה, יעקב ולאה. ע\"כ. וכתבתי שמזה נראה שערב לו אדם לשכב עם אבותיו והוא הדין נמי עם אשתו שהיא ג\"כ מכללם.","b":false},{"t":"וזו היא הסיבה שיעקב היה מדבר עם יוסף על ענין קבורת רחל אמנו בבית לחם, כדי שלא יהא בלבו עליו, שלא נקברה במערת המכפלה, ורואים מכאן כמה החשיבו את הענין הזה של קבורת האשה ליד בעלה, והשוו את הדבר לקברי אבות, וכן עיקר להלכה. ע\"ש. ולכן אמר יעקב ליוסף כי טעם קבורת רחל בבית לחם היה על פי הגבורה, כדי שתעמוד רחל בתפלה על בניה בעת שיצטרכו לה.","b":false},{"t":"וידוע המעשה בהגאון הצדיק מוהר\"ח שמואלביץ זצ\"ל ראש ישיבת מיר, כשהלך בפעם הראשונה להתפלל אל ה' על קברה של רחל אמנו, וכשסיים את תפלתו אמר, אמא רחל, הקב\"ה אמר לך מנעי קולך מבכי, ועיניך מדמעה. ואני בנך הקטן אומר לך, תבכי ותבכי ולא תמנעי את קולך מבכי, עד שהקב\"ה יביא גאולה לבניך, זיע\"א.","b":false}]},{"id":"22","t":"וישם את אפרים לפני מנשה","p":[{"t":"וַיַּרְא יִשְׂרָאֵל אֶת בְּנֵי יוֹסֵף וַיֹּאמֶר מִי אֵלֶּה, וַיֹּאמֶר יוֹסֵף אֶל אָבִיו בָּנַי הֵם אֲשֶׁר נָתַן לִי אֱלֹהִים בָּזֶה וַיֹּאמַר קָחֶם נָא אֵלַי וַאֲבָרֲכֵם, וְעֵינֵי יִשְׂרָאֵל כָּבְדוּ מִזֹּקֶן לֹא יוּכַל לִרְאוֹת וַיַּגֵּשׁ אֹתָם אֵלָיו וַיִּשַּׁק לָהֶם וַיְחַבֵּק לָהֶם, וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף רְאֹה פָנֶיךָ לֹא פִלָּלְתִּי וְהִנֵּה הֶרְאָה אֹתִי אֱלֹהִים גַּם אֶת זַרְעֶךָ, וַיּוֹצֵא יוֹסֵף אֹתָם מֵעִם בִּרְכָּיו וַיִּשְׁתַּחוּ לְאַפָּיו אָרְצָה, וַיִּקַּח יוֹסֵף אֶת שְׁנֵיהֶם אֶת אֶפְרַיִם בִּימִינוֹ מִשְּׂמֹאל יִשְׂרָאֵל וְאֶת מְנַשֶּׁה בִשְׂמֹאלוֹ מִימִין יִשְׂרָאֵל וַיַּגֵּשׁ אֵלָיו, וַיִּשְׁלַח יִשְׂרָאֵל אֶת יְמִינוֹ וַיָּשֶׁת עַל רֹאשׁ אֶפְרַיִם וְהוּא הַצָּעִיר וְאֶת שְׂמֹאלוֹ עַל רֹאשׁ מְנַשֶּׁה שִׂכֵּל אֶת יָדָיו כִּי מְנַשֶּׁה הַבְּכוֹר, וַיְבָרֶךְ אֶת יוֹסֵף וַיֹּאמַר הָאֱלֹהִים אֲשֶׁר הִתְהַלְּכוּ אֲבֹתַי לְפָנָיו אַבְרָהָם וְיִצְחָק הָאֱלֹהִים הָרֹעֶה אֹתִי מֵעוֹדִי עַד הַיּוֹם הַזֶּה, הַמַּלְאָךְ הַגֹּאֵל אֹתִי מִכָּל רָע יְבָרֵךְ אֶת הַנְּעָרִים וְיִקָּרֵא בָהֶם שְׁמִי וְשֵׁם אֲבֹתַי אַבְרָהָם וְיִצְחָק וְיִדְגּוּ לָרֹב בְּקֶרֶב הָאָרֶץ, וַיַּרְא יוֹסֵף כִּי יָשִׁית אָבִיו יַד יְמִינוֹ עַל רֹאשׁ אֶפְרַיִם וַיֵּרַע בְּעֵינָיו וַיִּתְמֹךְ יַד אָבִיו לְהָסִיר אֹתָהּ מֵעַל רֹאשׁ אֶפְרַיִם עַל רֹאשׁ מְנַשֶּׁה, וַיֹּאמֶר יוֹסֵף אֶל אָבִיו לֹא כֵן אָבִי כִּי זֶה הַבְּכֹר שִׂים יְמִינְךָ עַל רֹאשׁוֹ, וַיְמָאֵן אָבִיו וַיֹּאמֶר יָדַעְתִּי בְנִי יָדַעְתִּי גַּם הוּא יִהְיֶה לְּעָם וְגַם הוּא יִגְדָּל וְאוּלָם אָחִיו הַקָּטֹן יִגְדַּל מִמֶּנּוּ וְזַרְעוֹ יִהְיֶה מְלֹא הַגּוֹיִם, וַיְבָרֲכֵם בַּיּוֹם הַהוּא לֵאמוֹר בְּךָ יְבָרֵךְ יִשְׂרָאֵל לֵאמֹר יְשִׂמְךָ אֱלֹהִים כְּאֶפְרַיִם וְכִמְנַשֶּׁה וַיָּשֶׂם אֶת אֶפְרַיִם לִפְנֵי מְנַשֶּׁה (מח, ח-כ ועי' בדברי רש\"י ז\"ל שם)","b":true},{"t":"בפרשתינו ראינו כי יעקב אבינו ע\"ה אמר לבנו יוסף הצדיק שיביא לו את שני בניו מנשה ואפרים כדי שיברכם קודם מותו, ורצון יעקב לברך את שניהם ברור, כמאמר הפסוק \"קחם נא אלי ואברכם\", עוד אמר, המלאך וגו' יברך את \"הנערים\" ויקרא \"בהם\", רק הויכוח בין יעקב ליוסף היה מי מהבנים יזכה לברכה המיומנת, שהסבא קדישא ישית על ראשו את יד ימינו, ומי מהם יזכה להיות גדול מהשני, וגדולה זו מתבארת בדברי חז\"ל (ראה תנחומא ויחי פ\"ו וכן בדברי רש\"י בראשית מח, יט), על הפסוק (בראשית מח, יט), ואולם אחיו הקטן יגדל ממנו, שנתנבא יעקב על אפרים שעתיד יהושע לצאת ממנו שינחיל את הארץ וילמד תורה לישראל, והועילה ברכתו לשבט אפרים להקדימו למנשה בחנוכת הנשיאים שהקריבו שבט אפרים לפני שבט מנשה.","b":false},{"t":"והנה יוסף הצדיק ע\"ה חשב בדעתו, שמנשה ראוי לגדולה הזאת שיצאו ממנו מנהיגי ישראל, ולא רק מפני שהוא הבכור, אלא גם מפני שהוא ממזג בתוכו תורה ודרך ארץ, שבודאי גם הוא היה עוסק בתורה ויר\"ש, דבזה אין ויכוח כלל, רק שהיה עוסק גם בעניני המלוכה כידוע, שלכאורה זו מעלה נוספת שבגללה היה הוא האיש המתאים וראוי לברכה שמזרעו יהיו מנהיגי ישראל. כי הרי מנשה משלב תורה ומדיניות, אבל אפרים היה רק יושב אהלים והיה לומד תורה מסבו (ראה תנחומא שם). ולכן בעיני יוסף הצדיק היתה נראית דמות מנשה כדמות שאותה יש להעמיד לעסוק בהנהגת העם, כי ידיו של מנשה רב לו בטכסיסי וגינוני המלוכה ונהירין לו שבילי דעלמא, ויחד עם זאת אינו מניח ידו מתורת ה' ועבודתו.","b":false},{"t":"אבל יעקב אבינו ע\"ה סירב לרעיון הזה ולא הסכים לו, כי בעיניו אפרים עדיף ממנשה, כי אפרים היה שקוע לגמרי בלימוד התורה, ומיום שבא יעקב למצרים לא זזה ידו מתוך ידו, משך שבע עשרה שנה (גם יוסף היה אצל אביו י\"ז שנה). והגם שלא עסק במדיניות והנהגת מדינה, מ\"מ הוא ראוי והגון להנהגה, כי התורה הנלמדת לשמה, מזכה את הלומד אותה בדברים הרבה ובסגולות רבות, וכמו שנאמר, בי מלכים ימלוכו (משלי ח, טו), ובי שרים ישורו (שם שם, טז), והוא עדיף, ויגדל יותר מאחיו.","b":false},{"t":"ומה נפלאו דברי התנא רבי מאיר (כלה פ\"ח אבות פ\"ו משנה א ועי' תנדא\"ז פי\"ז), רַבִּי מֵאִיר אוֹמֵר, כָּל הָעוֹסֵק בַּתּוֹרָה לִשְׁמָהּ, זוֹכֶה לִדְבָרִים הַרְבֵּה, וְלֹא עוֹד אֶלָּא שֶׁכָּל הָעוֹלָם כֻּלּוֹ כְּדַאי הוּא לוֹ, נִקְרָא רֵעַ, אָהוּב, אוֹהֵב אֶת הַמָּקוֹם, אוֹהֵב אֶת הַבְּרִיּוֹת, מְשַׂמֵּחַ אֶת הַמָּקוֹם, מְשַׂמֵּחַ אֶת הַבְּרִיּוֹת, וּמַלְבַּשְׁתּוֹ עֲנָוָה וְיִרְאָה, וּמַכְשַׁרְתּוֹ לִהְיוֹת צַדִּיק, חָסִיד, יָשָׁר, וְנֶאֱמָן. וּמְרַחַקְתּוֹ מִן הַחֵטְא. וּמְקָרַבְתּוֹ לִידֵי זְכוּת. וְנֶהֱנִין מִמֶּנּוּ, עֵצָה, וְתוּשִׁיָּה, בִּינָה, וּגְבוּרָה, שֶׁנֶּאֱמַר (משלי ח, יד), לִי עֵצָה וְתוּשִׁיָּה אֲנִי בִינָה לִי גְבוּרָה, וְנוֹתֶנֶת לוֹ מַלְכוּת וּמֶמְשָׁלָה וְחִקּוּר דִּין, וּמְגַלִּין לוֹ רָזֵי תוֹרָה, וְנַעֲשֶׂה כְּמַעְיָן הַמִּתְגַּבֵּר וּכְנָהָר שֶׁאֵינוֹ פּוֹסֵק, וְהוֹוֶה צָנוּע וְאֶרֶךְ רוּחַ, וּמוֹחֵל עַל עֶלְבּוֹנוֹ, וּמְגַדַּלְתּוֹ וּמְרוֹמַמְתּוֹ עַל כָּל הַמַּעֲשִׂים.","b":false},{"t":"והגם דיש מקום לדון בדבר, ולטעון בזכותו של מנשה לברכה המיומנת. מכל מקום, יעקב איש האמת קבע בזה הלכה לשעה ולדורות שאפרים קודם למנשה, ומי כמוהו מורה. כי המדה של האמת נתנה לו, כמו שנאמר (מיכה ז, כ), תתן אמת ליעקב. והנה ידוע כי כל חפץ מחפצי העולם צריך לאומן מומחה שיקבע את הסוג והמעלה שלו. דרך משל, כשאדם רגיל רואה מתכת מוזהבת או מוכספת, אינו יכול להבחין בין זהב אמיתי לחיקוי, ובין כסף לסיגים או בין זכוכית מלוטשת ליהלום אמיתי, וכשהוא רוצה לברר את הדבר הריהו הולך לשאול בעצת המומחה לדבר. אך בעניני רוחניות וירא\"ש כל אחד ואחד חושב שהוא המומחה ואינו צריך לעצת אחרים, וזה גורם לחסרונות רבים שהאדם נכשל בהם ואינו יודע במה, ובפרט בענין האמת שבזה צריך סיעתא דשמיא מיוחדת, וכמו שהתפלל דוד המלך ע\"ה (תהלים פו, יא), הורני ה' דרכך אהלך באמתך. וכהנה רבות, כי פעמים רבות האדם אוחז בשקר אבל בלבו הוא חושב כי זו האמת צרופה, והדברים ידועים.","b":false},{"t":"ויעקב אבינו ע\"ה אשר לו ניתנה מדת האמת, ראה צורך ללמד את יוסף וכל בניו את מדת האמת בענינים שונים, שדרך בני אדם לטעות בהם מתוך ראיה שטחית ומוטעית.","b":false},{"t":"וכמו שאמר יעקב ליוסף (בראשית מח, כב), ואני נתתי לך שכם אחד על אחיך אשר לקחתי מיד האמרי \"בחרבי ובקשתי\", ותרגם אונקלוס (שם), בצלותי ובבעותי, וכאן לימדנו יעקב אבינו שהאמת היא שמי שעושה את המלחמה ומנצח בה, אינם החרב והקשת הידועים, כי אם התפלה והתחינה ששופכים לפני הי\"ת. עד שאמר על עצמו אשר \"לקחתי\" מיד האמורי, למרות שלא יצא למערכה זו כלל ולא השתתף בה בפועל. וזהו שנאמר (במדבר כא, יד), על כן יאמר בספר מלחמות ה'. מהן מלחמות ה', \"יאמר בספר\", היינו ילמד תורה ויעסוק בתפילה והריהו נוצח.","b":false},{"t":"וגם בענין אפרים ומנשה קבע יעקב שהאמת היא שיש להקדים את אפרים לפני מנשה. ולא את אפרים ומנשה בלבד הוא לימד זאת, כי אם את כל בני ישראל בכל הזמנים לימד, שלעולם \"אפרים\" השקוע בתורה קודם לכל ואפילו ל\"מנשה\" אחיו הבכור העוסק בעניני המלוכה, והדגיש יעקב ביותר את הענין, כמו שנאמר, ויברכם ביום ההוא לאמר, בך יברך ישראל לאמר, ישימך אלהים כאפרים וכמנשה, וישם את אפרים לפני מנשה. ע\"כ.","b":false},{"t":"ביום ההוא קבע יעקב אבינו לדורות להלכה ברורה, שהראוי לברכה המיומנת ולכל לראש, זה מי שהוא בבחינת \"אפרים\", אשר בתורת ה' חפצו ובתורתו יהגה תמיד, וכל הבא לברך את בניו ולבחור לו דרך אמיתית ומוצלחת ביותר, יש לו להקדים את ה\"אפרים\" ל\"מנשה\", ובכל בן ובן יראה להקדים תחילה את הבחינה של \"אפרים\", להדריכו ללימוד התורה, וכמו שאמר רבי נהוראי (קדושין פב, ב), מניח אני כל אומנות שבעולם ואיני מלמד את בני אלא תורה.","b":false},{"t":"ואם בבניו של יוסף שהיו מחוסנים וחזקים בדעותיהם, כי רוח אביהם עליהם וכחם במתניהם לעמוד נגד כל רוחות הזמן, עם כל זאת יעקב אבינו העדיף את אפרים. קל וחומר אצלינו ובזמנינו שכל הדרכים בחזקת סכנה, ולא נשאר מפלט כי אם ד' אמות של תורה ויראה, שצריך להעדיף את הדרך של אפרים ולהיות שקוע רק בתורה הקדושה כל הזמן.","b":false},{"t":"ועל זה אמר יעקב ליוסף \"ידעתי בני ידעתי\", ב' פעמים, כלומר ידעתי שמנשה הוא הבכור, וגם ידעתי את הטענה הזאת שיש להעדיף את מנשה, שבעיסוקו בישוב העולם הוא מתאים יותר לגדולה לפי טענת יוסף, וגם הוא יגדל, שאין יעקב מזלזל בו, ואולם אחיו הקטן יגדל ממנו וגו', \"וישם את אפרים לפני מנשה\", וכתב רש\"י ז\"ל (מח, כ), אפרים לפני מנשה, להקדימו בדגלים ובחנוכת הנשיאים, ומקור הדברים בדברי רבותינו (ב\"ר צז, ה). א\"כ למדנו כי מי שקודם למשנהו בתורה, הוא הקודם גם בדגלים ובנשיאים ובכל הענינים.","b":false},{"t":"הוא שדרש בר קפרא בכתובות (ה, א), גדולים מעשה צדיקים יותר ממעשה שמים וארץ. היינו, שגדולים מעשה צדיקים הפורשים מכל הענינים וממיתים את עצמם באהלה של תורה, יותר ממעשה שמים וארץ, היינו, מאותם שעוסקים בישובו של העולם. כי אע\"פ שגם הם קובעים עתים לתורה ומדקדקים במצוותיה, וממזגים יחד גם את מעשה שמים עם מעשי ארץ, והיינו חושבים לומר שהנהגתם טובה מאלו שפורשים מכל עניני העוה\"ז לגמרי ועוסקים רק בתורה. לכך בא בר כפרא ואמר גדולים מעשי צדיקים שעליהם העולם קיים בבחינת וצדיק יסוד עולם (משלי י, כה), ומועילים הם לקיום העולם ושלמותו ושלותו יותר מכל אדם העוסק בזה בפועל, כי כל הדברים הם בחינה של השתדלות שנתחייבנו בה מיום שאכל אדם הראשון מעץ הדעת ונתקלל, בזיעת אפך תאכל לחם (בראשית ג, יט). שאינו זוכה ללחם עד שיזיע עליו, וכן בשאר עניני העולם.","b":false},{"t":"אבל חלילה לחשוב שהזיעה היא המפרנסת את האדם ומשביעה אותו לחם, כי ה' הוא הזן ומפרנס, וזיעה זו והשתדלות זו, היא רק כדי לצאת ידי חובת הקללה ההיא ולסלק מניעיה, ואז תאכל לחם ממנו יתברך, וכבר קבע בזה גדר רבינו הקדוש רמח\"ל בספר מסילת ישרים וכתב (פרק כ\"א בדרכי קניית החסידות), כי \"ההשתדלות הכרחית אבל אינה מועילה\".","b":false},{"t":"הרי שכל העסק בישוב העולם וכדו', הוא בבחינת השתדלות שמטרתה לסלק את המניעים והמפריעים, אבל העוסק בתורה הוא מחיה את העולמות בפועל, ומושך שפע מלמעלה ומרבה ברכה ושלום בעולם, כמאמר הכתוב (ירמיה לג, כה), אם לא בריתי יומם ולילה חוקות שמים וארץ לא שמתי. ועל כן גדולים מעשי צדיקים יותר ממעשה שמים וארץ. וזהו \"וישם את אפרים לפני מנשה\".","b":false},{"t":"(ב\"ה ט\"ו טבת התשמ\"ח מתוך דרשה שנאמרה בביכ\"נ מגן דוד ב\"ב - בשבת החולפת פרשת ויחי)","b":false},{"t":"* * *","b":false},{"t":"מכתב","b":false},{"t":"בעהית\"ש, מוצש\"ק ויחי, התשס\"ה","b":false},{"t":"לתלמידי תלמוד תורה \"עוללים\" היקרים מאד.","b":false},{"t":"נועם ה' עליכם!","b":false},{"t":"בתחילת הפרשה שקראנו השבוע, מסופר שיוסף בא עם שני בניו מנשה ואפרים, לבקר את הסבא קדישא יעקב אבינו ע\"ה. וכשרצה יעקב אבינו ע\"ה לברכם, הגיש אותם יוסף לפני אביו בסדר נכון, שאפרים יהיה בשמאלו של יעקב ומנשה מימינו. אך יעקב אבינו שיכל את ידיו ושם את יד ימינו על ראש אפרים הצעיר, ואת יד שמאלו על ראש מנשה. ובתרגום אונקלוס (בראשית מח, יד), נאמר \"אחכמינון לידוהי\", כלומר, שבחכמה ניהל יעקב אבינו ע\"ה את ידיו.","b":false},{"t":"והנה מנשה ואפרים, שניהם היו תלמידי חכמים ויראי שמים. אלא שמנשה היה יד ימינו של אביו יוסף הצדיק בניהול ממלכת מצרים, והיה חכם ומצליח היטב בתפקידו הרם. ואפרים היה ממית עצמו כל הזמן באהלה של תורה.","b":false},{"t":"ויוסף חשב שמנשה קודם לאפרים וחשוב ממנו, כי בנוסף להיותו בכור ותלמיד חכם וירא שמים, הוא גם חכם גדול בניהול ובמדיניות. ולכן מגיעה לו הברכה \"המיומנת\".","b":false},{"t":"אבל יעקב אבינו ע\"ה שהוא בעל מדת \"האמת\" כמו שנאמר (מיכה ז, כ), תתן \"אמת\" ליעקב, קבע שאפרים עדיף, ובחכמה שם את יד ימינו על ראש אפרים. ואמר, בך יברך ישראל לאמר, ישימך אלהים כאפרים וכמנשה, וישם את אפרים לפני מנשה. כאן קבע לנו אבינו הזקן לדורות עולם, ש\"אפרים הוא לפני מנשה\", והגם שמנשה הוא הבכור, וגם הוא תלמיד חכם וירא שמים, אבל עם כל זאת, אפרים עדיף ממנו, כי הוא התלמיד חכם שממית עצמו באהלה של תורה.","b":false},{"t":"וזה היפך המקובל אצל רוב בני אדם, שהרי אפילו יוסף חשב להעדיף את מנשה על פני אפרים. אך מדת האמת ניתנה בידיו של יעקב כנ\"ל, והוא קבע לשים את אפרים לפני מנשה, וכי הברכה הניתנת ביד ימין תנתן לאפרים שממית עצמו באהלה של תורה.","b":false},{"t":"ולא רק לזמנו ולדורו קבע כן, אלא גם לכל הדורות הבאים אחריו עד עולם קבע כן, באמרו (בראשית מח, כ), \"בך יברך ישראל לאמר, ישימך אלהים כאפרים וכמנשה, וישם את אפרים לפני מנשה\", שלעולם אפרים קודם למנשה, כי אין לך דבר חשוב בעולם כמו לימוד התורה בעמל וביגיעה.","b":false},{"t":"וכמה יקר בעיני ה' לימוד תורה של \"תינוקות של בית רבן\", שזה עומד לכל בית ישראל, למגן וחומה נגד כל האויבים והשונאים. ועל זה נאמר (תהלים ח, ג), מפי עוללים ויונקים, יסדת עוז, להשבית אויב ומתנקם.","b":false},{"t":"ילדים חביבים! תתחזקו בלימוד התורה, ותחזקו את ה\"קול יעקב\" כמו שנאמר (בראשית כז, כב), הקול קול יעקב והידים ידי עשו, ואמרו רבותינו, כי בשעה שנשמע קולו של יעקב בתורה אז אין ידי של עשו שולטות בנו, (עי' ב\"ר סה, כ), והקול הזה של לימוד התורה יעלה עד לפני כסא כבוד ה', ויקרב לנו את הגאולה והישועה, בשובה ונחת, במהרה בימינו אמן.","b":false},{"t":"זכרו שעיני כל ישראל נשואות אליכם.","b":false},{"t":"אוהבכם ומברככם מעומק הלב","b":false},{"t":"שלמה משה עמאר","b":false}]},{"id":"22","t":"שם שדי וסגולתו לפריה ורביה","p":[{"t":"וַיֹּאמֶר יַעֲקֹב אֶל יוֹסֵף אֵל שַׁדַּי נִרְאָה אֵלַי בְּלוּז בְּאֶרֶץ כְּנָעַן וַיְבָרֶךְ אֹתִי, וַיֹּאמֶר אֵלַי הִנְנִי מַפְרְךָ וְהִרְבִּיתִךָ וּנְתַתִּיךָ לִקְהַל עַמִּים וְנָתַתִּי אֶת הָאָרֶץ הַזֹּאת לְזַרְעֲךָ אַחֲרֶיךָ אֲחֻזַּת עוֹלָם, וְעַתָּה שְׁנֵי בָנֶיךָ הַנּוֹלָדִים לְךָ בְּאֶרֶץ מִצְרַיִם עַד בֹּאִי אֵלֶיךָ מִצְרַיְמָה לִי הֵם אֶפְרַיִם וּמְנַשֶּׁה כִּרְאוּבֵן וְשִׁמְעוֹן יִהְיוּ לִי: (מח, ג-ה)","b":true},{"t":"אפשר דיש קשר בין שם שדי לברכת הבנים, שכן מצאנו ביצחק אבינו ע\"ה בעת שציוה ליעקב ללכת לפדן ארם לשאת לו אשה ברכו בשם שדי, כמו שנאמר (בראשית כח, ב-ג), קום לך פדנה ארם ביתה בתואל אבי אמך וקח לך משם אשה מבנות לבן אחי אמך, ואל שדי יברך אתך ויפרך וירבך והיית לקהל עמים. הרי שגם יצחק אבינו כשבירך את יעקב בברכת הבנים ברכו בשם שדי. ובאמת שמצינו כי גם בעת שבירך הי\"ת את אברהם אבינו ע\"ה שיפרה וירבה, נגלה אליו הי\"ת בשם \"אל שדי\", כמו שנאמר (בראשית יז, א-ו), וירא ה' אל אברם ויאמר אליו אני אל שדי וגו' והפרתי אותך במאד מאד וגו'.","b":false},{"t":"ושוב ראיתי בפירוש ר\"י בעה\"ט דהוא תנא דמסייען לזה, שכתב על הפסוק (בראשית לה, יא), אני אל שדי פרה ורבה, הוא שם של פריה ורביה כי נעלם שלו, שי\"ן דל\"ת יו\"ד עולה ת\"ק, כמנין איברים שבאיש ושבאשה. והיינו רמ\"ח איברי האיש ורנ\"ב איברי האשה (כי האשה יתירה על האיש ארבעה איברים, כמבואר בבכורות מה, א), אשר יחדיו עולין לחמש מאות.","b":false},{"t":"והלום ראיתי בילקוט תפלות שחיבר הרה\"ק רבי יהודה פתאיה זללה\"ה הנקרא חסדי דוד, ושם תפלה על חשוכי בנים, ונאמר בה, ותקיים בהם מקרא שכתוב וכו', ולמען שמך הקדוש שם שד\"י, אשר מלוי שלשה אותיות שלו [ש]י\"ן, [ד]ל\"ת, [י]ו\"ד, עולים בגימטריא פר\"ו ורב\"ו, וסוף אותיותיו נ' ת' ד' גימטריא ב\"ן ב\"ת. וכן מזכיר שם את הפסוקים אני אל שדי פרה ורבה, ואל שדי יברך אותך ויפרך וירבך. ע\"ש (וראה עוד להלן מאמר כב).","b":false},{"t":"ואם כן זהו שאמר לו כאן יעקב ליוסף אל שדי נגלה אלי וגו' הנני מברך וגו' ונתתיך לקהל עמים, ואמרו רבותינו (ב\"ר פב, ד), וכן הוא בפירוש רש\"י ז\"ל שם (בראשית מח, ד), ונתתיך לקהל עמים, בשרני שעתידים לצאת ממני עוד קהל ועמים וכו', ושוב לא נולד לי בן, לימדני שעתיד אחד משבטי ליחלק ועתה אותה מתנה אני נותן לך. ע\"ש.","b":false},{"t":"וזה שהמשיך יעקב ואמר, ועתה שני בניך הנולדים לך בארץ מצרים וגו' לי הם אפרים ומנשה כראובן ושמעון יהיו לי. כלומר, שהגם שהיית לבדך בארץ מצרים ולא ידעתי כלל מקיומך, בכל זאת, ברכת הקב\"ה היתה מכוונת בעבורך.","b":false},{"t":"ומה נפלאים דברי בעלי התוספות בספר דעת זקנים, וכן דברי רבינו יעקב בעל הטורים (בראשית מח, ה), שכתבו, אפרים ומנשה עולה בגימטריא ראובן ושמעון ואחד יותר. ע\"ש. [והאחד יותר, אפשר שהוא כנגד יוסף]. ועל כל פנים, רואים בזה את רצון הי\"ת למנות את מנשה ואפרים בכלל שבטי יה.","b":false}]},{"id":"22","t":"יוסף זכה לנחלה כפולה משאר אחיו","p":[{"t":"וַיֹּאמֶר אֵלַי הִנְנִי מַפְרְךָ וְהִרְבִּיתִךָ וּנְתַתִּיךָ לִקְהַל עַמִּים וְנָתַתִּי אֶת הָאָרֶץ הַזֹּאת לְזַרְעֲךָ אַחֲרֶיךָ אֲחֻזַּת עוֹלָם: (מח, ד)","b":true},{"t":"כאן ביררה לנו התורה הקדושה שאותה הבטחה שהבטיח הקב\"ה לאברהם וליצחק אותה הבטיח גם ליעקב אבינו, שתהיה הארץ הקדושה לו ולזרעו אחריו אחוזת עולם.","b":false},{"t":"וכתב רבינו אברהם ן' עזרא וז\"ל בתוך דבריו, והנכון בעיני שאמר, השם אמר לי כי ארץ כנען תהיה לזרעי אחוזת עולם. ואני אתן לך בנחלת הארץ הבכורה ויקחו אפרים ומנשה חלקם בארץ כאשר יקח ראובן ושמעון שהם הגדולים מבני. ואשר תוליד אחרי אפרים ומנשה יקראו על שם אחיהם הנזכרים שירשו עמם בנחלתם וכו'. ע\"כ.","b":false},{"t":"וכעין זה ממש פירש גם הרשב\"ם ז\"ל על הפסוק (בראשית מח, ה), ועתה שני בניך הנולדים לך וגו' אפרים ומנשה כראובן ושמעון יהי לי, ועתה שני בניך וגו', כלומר, מאחר שנתן לי הקב\"ה את ארץ כנען, הרי ברשותי לעשותך בכור ליטול פי שני שבטים, ולכך שני בניך יטלו כנגד ראובן ושמעון.","b":false},{"t":"וגם הרמב\"ן ז\"ל (בראשית מח, ו), הביא דברי רש\"י ז\"ל שכתב, ומולדתך אשר הולדת אחריהם, אם תוליד עוד בנים לא יהיו במנין בני אלא בתוך שבטי אפרים ומנשה יהיו נכללין, ולא יהא להם שם כשאר השבטים לענין הנחלה ואף על פי שנתחלקה ארץ ישראל למנין גולגלותם, כדכתיב (במדבר כו, נד), לרב תרבה נחלתו, וכל איש נטל בשוה, חוץ מן הבכורות, מכל מקום לא נקראו שבטים אלא אלו. ע\"כ. ודחה הרמב\"ן את דבריו, וכתב, וזה איננו נכון, שאם כן אין הבכורה ליוסף אלא לענין הכבוד בלבד שיקראו בניו שבטים, והכתוב אומר בנחלתם, ובגמרא אמרו, לנחלה הקשתים לראובן ושמעון ולא לדבר אחר וכו', כדאיתא בהוריות (ו, א), והזכירו רבותינו (ב\"ב קכג, א), בכל מקום שהיה יוסף בכור לנחלה וירש פי שנים כאחד כמשפט כל בכור, ולא היתה בכורתו להקרא שבטים בלבד כדברי הרב, ומזה נלמוד עוד שלא חלקו הארץ לכל שבטי ישראל לגולגלותם, שאם כן מה הבכורה הזאת בירושה ואם נאמר שנתנו לכל אחד ואחד מבני יוסף פי שנים כאחד מכל אישי שאר השבטים, לא הוזכר זה בכתוב כלל, ולא מצינו ביעקב שיתן בכורה ליוסף אלא שאמר בכאן \"כראובן ושמעון יהיו לי\", ומזה אמר הכתוב (דהי\"א ה, א), נתנה בכורתו לבני יוסף בן ישראל, אם כן היו לגמרי כשני שבטים והיא בכורתו, וכך הם דברי חכמים בכל מקום (ב\"ב קכג, א).","b":false},{"t":"אבל הענין איננו כלל כמו שאמר הרב, שארץ ישראל לשבטים נתחלקה, שנים עשר חלקים שוים עשו ממנה, ונטל שבט שמעון המועט שבהם כשבט יהודה שמרובה באוכלוסין, ונטלו אפרים ומנשה כראובן ושמעון בשוה וכך העלו בגמרא פרק יש נוחלין (ב\"ב שם), וכתוב (יחזקאל מז, יג), תתנחלו בארץ לשנים עשר שבטי ישראל יוסף חבלים. וכן אמר אונקלוס (להלן מט, כב), תרין שבטין יפקון מבנוהי יקבלון חולקא ואחסנתא, שיהיו שוים בקבלת הנחלה וכו'. עכ\"ל.","b":false},{"t":"ויש לשים לב שכל הזמן משוה הכתוב את הבטחת הארץ להבטחת הזרע, שכבר בברית בין הבתרים הבטיח הי\"ת לאברהם את שניהם, וכן תמיד. וגם כאן י\"ל כי אלו ואלו דברי אלהים חיים, ונאמר, כי יעקב העביר המתנה ליוסף בשני בדברים, האחת, שבניו אפרים ומנשה יקראו בין השבטים כראובן ושמעון. והשנית, שגם יקחו פי שנים בחלוקת הארץ.","b":false},{"t":"ואולי א\"א לזה בלא זה. וע\"כ אמר יעקב ליוסף, אפרים ומנשה כראובן ושמעון יהיו לי, ואחר שקבעם כשנים מבניו, ממילא יוצא הדין דנוטל כל אחד מהם חלקו בנחלת הארץ כאחד השבטים, וממילא יוצא דיוסף נטל פי שנים, כדין בכור לנחלה.","b":false}]},{"id":"22","t":"האבות הקדושים עבדו את הי\"ת מתוך צער","p":[{"t":"וַיֹּאמֶר יַעֲקֹב אֶל יוֹסֵף אֵל שַׁדַּי נִרְאָה אֵלַי בְּלוּז בְּאֶרֶץ כְּנָעַן וַיְבָרֶךְ אֹתִי, וַיֹּאמֶר אֵלַי הִנְנִי מַפְרְךָ וְהִרְבִּיתִךָ וּנְתַתִּיךָ לִקְהַל עַמִּים וְנָתַתִּי אֶת הָאָרֶץ הַזֹּאת לְזַרְעֲךָ אַחֲרֶיךָ אֲחֻזַּת עוֹלָם: (מח, ג-ד)","b":true},{"t":"מצינו ששם שדי הוא שם המורה על גבול הצרות, כמו שאמרו רבותינו (תנחומא מקץ פ\"י הובא ברשי בראשית מג, יד), על הפסוק (בראשית מג, יד), ואל שדי יתן לכם רחמים, מי שאמר לעולם די יאמר לצרותי די וכו', ע\"ש. נמצא כי הוא הנהגת הי\"ת בעת שאומר די לצרות.","b":false},{"t":"ופה יעקב אבינו ע\"ה הזכיר שם \"אל\" ושם \"שדי\", ואל הוא שם של רחמים כמו שנא' (תהלים נב, ג), חסד אל כל היום.","b":false},{"t":"ואולי הקדים יעקב ענין זה ליוסף לפני שבירך את בניו, כי ראה יעקב שיתחיל השעבוד, והיה מקום לומר למה לנו בנים, כדי שישתעבדו בהם המצרים ויכאיבו להם, וימיתו אותם ביאור, ולמה ניגע לריק ונלד לבהלה.","b":false},{"t":"לזה הקדים יעקב לומר שנגלה אליו אל שדי וברכו, ואמר לו, הנני מפרך והרביתיך וגו'. כלומר, אמר יעקב ליוסף שלא יבהלו מהשעבוד ולא יתיאשו ח\"ו, כי יש גבול ליסורים ולצרות, והבטיחו על ישראל שיגדלו וירבו ויעצמו ויתחזקו, ולבסוף יגאלו. ולכן הזכיר שם \"שדי\", לומר שלבסוף יהא די לצרות השעבוד ויצאו ישראל ממצרים וישובו אל הארץ, וגם בהיותם במצרים ימשך עליהם חסד האל ויפרו וירבו.","b":false},{"t":"וזהו שנאמר, (שמות ו, ב-ג), וארא אל האבות באל שדי ושמי ה' (הוי\"ה), לא נודעתי להם. שהי\"ת מתאונן על פטירת האבות הקדושים ואומר חבל על דאבדין, ואומר אל משה, ראה את אבותיך הקדושים, שנגליתי עליהם בשם אל שדי, שמשמעות השם הזה הוא קץ וגבול לצרות מלשון די, ומשמעות הדברים, שה' לא נתודע לאבות כי אם בשם שדי, שהוא מגיע אחר הדינים והיסורין, אבל בשם הוי\"ה שהוא שם של רחמים מעולם לא נגליתי להם, ובכל זאת האמינו בי ולא הרהרו כלל אחר מדותי. ואילו אתה משה הלא נגליתי עליך בסנה בשם הוי\"ה, ואמרתי לך לומר לבני ישראל (שמות ג, יד), אהיה אשר אהיה שלחני אליכם, והוא שם הוי\"ה שכולו רחמים, וא\"כ היה לך להשכיל ולהבין כי כל מה שאני עושה הוא טובה עצומה לישראל, ומה שאני נותן בלב פרעה להכביד עולו עליהם, הוא כדי לקרב עד מהרה את קץ גאולתם. ושורש הענין יוצא מפסוק זה.","b":false}]},{"id":"22","t":"אל יתהלל גבור בגבורתו","p":[{"t":"לִישׁוּעָתְךָ קִוִּיתִי ה': (מט, יח)","b":true},{"t":"בתרגום יונתן בן עוזיאל כתוב, בעת שראה יעקב בנבואה את תשועת גדעון בן יואש, ואת תשועת שמשון בן מנוח, שעומדים להושיע את ישראל, אמר, לא לישועת גדעון אני מצפה, ולא לישועתו של שמשון אני אקוה, כי ישועתם ישועת שעה. אלא לישועתך ה' אני מקוה ומצפה, כי ישועתך ישועת עולמים. וכעין זה הוא בתרגום ירושלמי שם.","b":false},{"t":"ועיין בדברי הרמב\"ן ז\"ל שהם כמשלימים את הדברים הנ\"ל. שכתב, וז\"ל, לישועתך קויתי ה', לא היה בכל שופטי ישראל מי שנפל ביד אויביו זולתי שמשון שהוא הנחש הזה, כדכתיב (שופטים ב, יח), והיה ה' עם השופט והושיעם מיד אויביהם כל ימי השופט והוא היה האחרון לשופטים, כי שמואל נביא היה ולא נלחם להם, ובימיו מלכו המלכים, וכאשר ראה הנביא את תשועת שמשון כי נפסקה, אמר לישועתך קויתי ה', לא לישועת נחש ושפיפון [אני מקוה], כי בך אושע לא בשופט, כי תשועתך תשועת עולמים. ע\"כ.","b":false},{"t":"ואפשר לומר עוד דכשראה יעקב את שמשון ואת גבורתו הגדולה, אמר לישועתך קיויתי ה', לומר, דאל יתלה האדם את הצלחתו בכחו ובגבורתו, כי לא בכח יגבר איש (ש\"א ב, ט).","b":false},{"t":"כי כמה גבורים גבורתם נשתה (ראה ירמיה נא, ל), וכמה חכמים ונבונים הושבה דעתם אחור, וכמה עשירים אבדו את ממונם והיו נצרכים ללחם. כי לא לחכמים לחם ולא לקלים המרוץ ולא לגבורים מלחמה (ראה קהלת ט, א). ונאמר (ירמיה ט, כב-כג), אל יתהלל חכם בחכמתו ואל יתהלל הגבור בגבורתו, אל יתהלל עשיר בעשרו, כי אם בזאת יתהלל המתהלל השכל וידוע אותי.","b":false},{"t":"אמנם בשעת גבורתו של אדם קשה לו לחשוב על כל זה, ולזה הדגיש יעקב אבינו לשמשון ולכל באי עולם, שלא יקוו לגבורתם, ולא ישענו אל בינתם, ולא יסמכו על עושרם, אלא לישועתך קיויתי ה'.","b":false},{"t":"ושוב מצאתי לרבותינו בעלי התוספות בספר דעת זקנים שכה כתבו, לישועתך קויתי ה' - כיון שראה יעקב אבינו את גבורת שמשון אמר אע\"פ שזה גבור נוצח, אין נכון להתהלל בגבורתו. וכן מצינו בשעה שנתהלל אמר (שופטים טו, טז), בלחי החמור הכתי אלף איש, מיד ויצמא מאוד (שם שם, יח), עד שהודה ואמר (שם), ה' אתה נתת ביד עבדך את התשועה וגו', שהודה שאין הגבורה רק מהשם לבדו, והדא הוא דכתיב (לעיל מט, יז), יהי דן נחש עלי דרך, ואפילו הכי, הגבורה והנצוח להקב\"ה, כדכתיב לישועתך קויתי ה'. ע\"כ. והדברים נפלאים ומלמדים.","b":false}]},{"id":"22","t":"שעבוד כל כחות הגוף והנפש אל הי\"ת","p":[{"t":"וַיַּרְא מְנֻחָה כִּי טוֹב וְאֶת הָאָרֶץ כִּי נָעֵמָה וַיֵּט שִׁכְמוֹ לִסְבֹּל וַיְהִי לְמַס עֹבֵד: (מט, טו)","b":true},{"t":"ופירש רבינו אברהם ן' עזרא ז\"ל, כאשר ראה ארצו ומקום מנוחתו נעימים, נטה שכמו לסבול כל משא, כאשר ישא החמור, ושם כעבד נותן מס וכו'.","b":false},{"t":"ורש\"י ז\"ל פירש, וירא מנוחה כי טוב, ראה לחלקו ארץ מבורכת וטובה להוציא פירות. ויט שכמו לסבול, עול תורה. ויהי, לכל אחיו. למס עובד, לפסוק להם הוראות של תורה וסדרי עבורין, שנאמר (דהי\"א לב, יג), ומבני יששכר יודעי בינה לעתים, לדעת מה יעשה ישראל וגו'.","b":false},{"t":"וגם רבינו עובדיה ספורנו ז\"ל כתב שיששכר נושא עליו עול תורה ועול דרך ארץ, והנהגת המדינות כראוי לחכם שלם במדות ובמושכלות.","b":false},{"t":"והנה רואים דרכים שונים שהצד השוה שבהם, שיששכר נושא בעול, ומטה שכמו לסבול, והיא מעלתו.","b":false},{"t":"ואמרתי אענה חלקי גם אני הדל, דמה שכתב וירא מנוחה כי טוב, והארץ כי נעמה. הכי קאמר, ראה והביט אל העולם וראה שיש שני סוגי הנהגה, יש האוהבים את המנוחה והעינוגים כמפנקי דמערבא, ואומרים שהוא הטוב, ובזים הם בלבם לאלה המתאמצים ועובדים קשה, ויהיו בעיניהם לפתאים שאינם יודעים בטיב החיים. ויש סוג אחר של אנשים, שרואים את נעימות חייהם על הארץ בעבודת כפיים בנטיעה ובחרישה, או במסחר ויומם ולילה לא ישבותו. או בטיולים ברחבי הארצות, יעלו שמים ירדו תהומות אזלא וקדמא, ולא יתנו מנוח לכף רגלם.","b":false},{"t":"והנה יששכר ראה כל זה, ראה את חכלילי עינים מיין, ולבן שנים מחלב. וכן ראה את השוכנים לחוף ימים בספינות ובאניות, ההולכים ימה וקדמה צפונה ונגבה, והוא ראה את הטוב שבהם, ונעימות חייהם, ולא התפעל מכל זה, ולא נמשך אחריהם. ויט שכמו לסבול, ויהי למס עובד, ועשה עצמו כחמור גרם לשאת ולסבול את עול התורה, והזיר את עצמו מחמודות העולם וממנעמיו, והמית את עצמו באהלה של תורה, לפסוק הוראות לכל העם, אשר אין עמל ויגיעה גדולה ממנה.","b":false}]},{"id":"22","t":"לפום צערא אגרא","p":[{"t":"יִשָּׂשׂכָר חֲמֹר גָּרֶם רֹבֵץ בֵּין הַמִּשְׁפְּתָיִם: (מט, יד)","b":true},{"t":"פירש\"י ז\"ל, חמור בעל עצמות, סובל עול תורה כחמור חזק שמטעינין אותו משא כבד והוא מדברי רבותינו (ב\"ר צט, ט). וכעי\"ז פירש הראב\"ע ז\"ל (שם), ועיין עוד בדברי רבינו עובדיה ספורנו ז\"ל (שם).","b":false},{"t":"אך במסכת נדה (לא, א), אמרו, חמור גרם ליששכר שיולד, כי כשבא יעקב מן השדה, ושמעה לאה את חמורו נוער, יצאה לקראתו וכו', ובאותו לילה נתעברה מיששכר. והובא כל זה בדעת זקנים מבעלי התוספות (שם), וכן הוא בפירוש ר\"י בעל הטורים (שם). ולפי\"ז \"גרם\" אינו לשון עצם, אלא מלשון \"גרמא\", שהחמור הוא שגרם שיולד יששכר.","b":false},{"t":"והרב בני יששכר (מאמרי השבתות – מאמר ב'), פירש דבר נפלא אשר על ידו ניתן ליישב שאלה נפלאה, והיא, כי יש לשאול למה יזכה אדם לשכר העוה\"ב בעבור המצוות שקיים, והלא כבר קיבל את שכרו בעצם עשיית המצוה, כי הרי אין הנאה גדולה בעולם מההנאה שהאדם מקיים מצוה, וכמו שאמרו באבות (ד, יז), יפה שעה אחת של תשובה ומעשים טובים בעולם הזה מכל חיי העולם הבא, ולמה יקבל עוד שכר על המצות שמקיים.","b":false},{"t":"ולזה יש להשיב בהקדים את דברי הרב בן יששכר על הפסוק יששכר חמור גרם רובץ בין המשפתים, וירא מנוחה כי טוב ואת הארץ כי נעמה ויט שכמו לסבול ויהי למס עובד. כי הנה השם יששכר אפשר לחלקו לב', כלומר, יש - שכר, והיינו החמור הרובץ תחת משאו אפילו בין המשפתים שהוא מקום מישור, והיינו שרובץ ועוסק בתורה יותר מכפי היכולת, ולכן זוכה ליש - שכר מהקב\"ה. ומפרש הכתוב, וירא מנוחה כי טוב, כי מנוחה הוא שכר העוה\"ב שכולו טוב, ומאידך ראה את הארץ כי נעמה, את ארציות העוה\"ז שהיא נעימה רק לפי שעה ואינה טובה בעצם. על כן החליף עולם עובר בעולם עומד, ויט שכמו לסבול את טורח משא הקודש יותר מן הראוי לו. ויהי למס עובד שעובד יותר ומצטער בעבודתו, כי \"ויהי\" לשון צער, ואעפי\"כ אינו פוסק אלא טורח בעבור הי\"ת, ולכן זוכה ליש – שכר. ע\"ש.","b":false},{"t":"וזהו יששכר חמור גרם, היינו, \"יש שכר\", וכי תשאל מדוע. לזה משיב ואומר, \"חמור גרם\", שחומריות העולם הזה שיששכר מותר עליה היא היא הגורמת לו לחיי הנצח בעוה\"ב.","b":false}]},{"id":"22","t":"גאולה ותורה – תרי ריעין דלא מתפרדין","p":[{"t":"אֹסְרִי לַגֶּפֶן עִירֹה וְלַשּׂרֵקָה בְּנִי אֲתֹנוֹ כִּבֵּס בַּיַּיִן לְבֻשׁוֹ וּבְדַם עֲנָבִים סוּתֹה: (מט, יא)","b":true},{"t":"ותירגם יונתן בן עוזיאל, מה יאי מלכא משיחא דעתיד למיקום מדבית יהודה, אסר חרצוי ונחית ומסדר סדרי קרבא בעלי דבבוי ומקטל מלכין עם שולטניהון, ולית מליך ושולטן דיקום קדמוי, מסמק טוריא מן אדם קטיליהון לבושוי מעגעגין באדמא (פי' נצבעים באדום), מדמא לעצור דענבין. וכן הוא בתרגום ירושלמי. ע\"ש.","b":false},{"t":"נמצא דמדובר במלך המשיח, והכתוב מתאר את כחו ויופי הדרו, ועוצם מלכותו וכו'. ובאמת שגם בתרגום אונקלוס, על הפסוק עד כי יבא שילה (לעיל מט, י), תירגם עד דייתי מלכא משיחא, דדיליה היא מלכותא, וליה ישתמעון עממיא. ובפסוק אוסרי לגפן וגו' תירגם, יסחר ישראל לקרתיה, עמא יבנון היכליה, יהון צדיקיא סחור סחור ליה, ועָבדי אורייתא באולפן עימה וכו'.","b":false},{"t":"הרי שגם אונקלוס מדבר על מלך המשיח, ומקשר את זה עם הצדיקים ועמלי תורה, ובודאי שלזה רומז היין ודם ענבים. וכן הוא בפירוש רבינו עובדיה ספורנו ז\"ל שמבאר את הענין על אותות המשיח, אשר אחד מהם הוא, שיבא על חמור, ויקשור את חמורו, ויהיה משכנו בשורק שהוא מבחר הגפן, וזה שיאיר פניו אל צדיקים שבדור וכו', יע\"ש.","b":false},{"t":"והנה כבר כתבתי בס\"ד, בהקדמה לשו\"ת שמע שלמה ח\"א, על הפסוק (שמות ח, יט), ושמתי פְדֻת בין עמי ובין עמך, למחר יהיה האות הזה, ונכתב פדת חסר וא\"ו, שהוא להורותינו שהאות וא\"ו החסרה במילת פדות מראה על כך שאותה גאולה לא היתה שלמה, וכתב רבינו בחיי ז\"ל (שם), דהטעם שלא הושלמה גאולתנו ביציאת מצרים, משום שיש עוד גלות אחריה. ולענ\"ד נראה להוסיף שלא היתה הגאולה שלימה לפי שעדיין לא ניתנה התורה הקדושה, וביררתי שם באורך שאות וי\"ו היא בחינת התורה, כמבואר בזה\"ק פעמים אין ספור (לדוגמא ראה זוהר ח\"ב קיט, ב וראה תיקוני זוהר פב, ב), ועוד אמרו (ראה זוהר ח\"א רמא, ב), דוי\"ו הוא סימנא דחיי, וגם במסכת ב\"ב (יד, א), אמרו שהלוחות ארכן ו' טפחים ורחבן ו' טפחים, וכן ההיקף של הס\"ת הוא ו' טפחים. ע\"ש. נמצא שגם חז\"ל בגמרא רמזו את התורה בוא\"ו, (וראה עוד לעיל פרשת וישב מאמר ב). והנה כל זכות הגאולה העתידית תהא בזכות התורה הקדושה.","b":false},{"t":"ורבינו הקדוש בעל אוה\"ח כתב, דעל כן ציוה הי\"ת למשה ללמד את בני ישראל במצרים את ענין קרבן הפסח קודם צאתם, וזאת בכדי שיהיה להם לזכות ויוכלו לצאת. ואילולא דברי האוה\"ח הק' היינו חושבים שיצאו ישראל ממצרים בזכות קרבן פסח, וכמו שדרשו חז\"ל (שמו\"ר יז, ג ושם יט, ה. ושהש\"ר א, לד ושם ה, ג. ורו\"ר ו, א. ותנחומא וירא פ\"ד. ומדרש תהלים פ' קי\"ד. ותנדא\"ר פכ\"ז. ופסיקתא דר\"כ ז, ד. ופרדר\"א פכ\"ח), על הפסוק (יחזקאל טז, ו), ואעבור עליך ואראך מתבוססת בדמיך ואומר לך בדמיך חיי, דהיינו דם הפסח ודם הברית. ועל זה באו דברי האור החיים הק' לומר, דזה לבדו אינו מספיק, אלא התורה של קרבן הפסח היא שעמדה לאבותינו לצאת, כי אפילו גאולה זמנית לא תיתכן כלל בלא זכות התורה. אלא שעדיין לא ניתנה תורה ואם כן לא היו נגאלין, לכך נתן להם הקב\"ה את פרשת קרבן הפסח כדי שיתעסקו בה, ועל ידה יצאו ממצרים, ובין מכת חשך למכת בכורות, קיבץ משה את כל ישראל. ובו בעת שכל המצריים היו באנדרלמוסיא נוראה, ופחד ואימה נפלו עליהם, היה משה יושב עם כל ישראל, ומלמדם דיני שחיטה, ודיני בדיקת הסכין, והולכת הדם והזאתו, ואח\"כ דיני הקרבת הקרבן, וככה תאכלו אותו מתניכם חגורים ומקלכם בידכם ואמרתם זבח פסח הוא לה' (שמות יב, כז).","b":false},{"t":"ואשר על כן לא יפלא איפא, שכבר יעקב אבינו ע\"ה, קשר וכרך בדבריו את ענין ביאת המשיח עם ענין לימוד התורה, דהא בהא תליא, ואי אפשר להפריד ביניהם כלל ועיקר. ויעקב אבינו שהוא בחינת תורה, תתן אמת ליעקב, מדת תפארת, הוא הוא שמטפל בעניני הגאולה, והוא שדיבר על המשיח עד כי \"יבא שילה\" גימטריא משיח, וכל הפסוקים של ברכת יהודה סובבים הולכים על ענין המשיח. ובאמת אנשי כנסת הגדולה, הטביעו לשון מיוחדת באמת ויציב, \"צור יעקב מגן ישעינו\", לרמוז על יעקב אבינו שהיה כל עיסוקו בקירוב הגאולה לבניו. וגילו לנו בדבריהם שיעקב הוא המגן על ישועת ישראל, ואשר על כן יעקב אבינו ע\"ה, הוא זה שלקח האות וא\"ו מאליהו הנביא זכור לטוב, ואמר לו לא אשיב לך אות זה, עד שתבשר גאולה לבני. (ונתבאר לעיל באריכות פרשת וישב אות ב'). ולכן יעקב הוא שהקדים ושלח את יהודה לפניו גושנה, כדי להכין לו בית תלמוד שממנו תצא הוראה, כי התורה היא שורש הגאולה, ולכן יש להקדימה לפני שהתחילה הגלות בבא יעקב ובניו מצרימה, כענין שאמרו בקוב\"ה (מגילה יג, ב), שמקדים רפואה למכה.","b":false},{"t":"ויעקב הוא זה זה שבא לבשר בראשונה על ביאת המשיח, ואם כי נסתלקה ממנו שכינה, ולא היה יכול לגלות לבניו את הקץ ולקרבו, מ\"מ נתן להם סוד תורה, שהוא התבלין לקרב את ביאת המשיח.","b":false},{"t":"ודבר נורא דיבר בזה קדוש ה' רבינו חיים ן' עטאר זיע\"א, באור החיים אצלינו בד\"ה אסרי לגפן וכו' שמלך המשיח יכניע את הסטרא אחרא להשביתה, והכתוב הזה מדבר בשתי הגאולות המפורסמות, גאולת מצרים וגאולה העתידה בעה\"ו, וכנגד גאולת מצרים, אמר אסרי לגפן עירה. שביציאת מצרים נקראו ישראל גפן, שנאמר (תהלים פ, ט), גפן ממצרים תסיע, ואז הכניע הי\"ת לפניהם את בחינת הזכר של הסטרא אחרא הנקרא עיר ושעבדו להם, וזהו, אסרי לגפן עירה. שאסר לפניהם את העיר. וְלַשּׂרֵקָה בני אתונו, מדבר על הגאולה העתידה, שאז נקראים ישראל שורקה שנאמר (זכריה י, ח), אשרקה להם ואקבצם, ואז יכניע הי\"ת לפניהם גם את הנקבה של הסט\"א הנקראת אתון. והוא על דרך מה שאמרו בזוה\"ק (ח\"ג רלא, ב), שבסטרא אחרא, הנקבה היא יותר חזקה מהזכר. ע\"ש.","b":false},{"t":"ואחר שהביא כל זה כתב בזה\"ל: וכדבר הזה וכחזיון הזה הראוני בחלום, שנאבקתי במלחמה עם הזכר, (של הסט\"א), ויהי נקל בעיני להכניעו, והפלתי אותו בכחי. ולנקבה נתאמצתי בכל כחי כמה פעמים, ואחר כמה טרחות יכולתי להשליכה כמה מעלות למטה לארץ, אך לא כבעלה הזכר. (כלומר שבזכר הצליח להשליכו בקלות טפי, וגם לעומק גדול יותר). ובזה מפרש, ולשורקה שהיא הגאולה העתידה, אז יכניעו גם את הנקבה של הסט\"א שהיא בחינת בני אתונו, יעו\"ש. ומהחזיון הנפלא הזה יבין כל משכיל שהרב הקדוש ז\"ל היה בחינת משיח, אם היה הזמן ראוי, וכמו שכן אומרים בשם הבעש\"ט ע\"ה, שהרי איהו גופיה ז\"ל אמר שזו מלאכת קדש של מלך המשיח. ומה לו לחזיון זה, אלא שמן השמים גילו לו על תפקידו ויעודו, זיע\"א.","b":false},{"t":"ולכאורה היה ניתן להקשות למה בגאולת מצרים לא הכניעו ישראל אלא את הזכר של הסט\"א אעפ\"י שמשה היה הגואל, ולמה לעתיד לבא יכניעו גם את הנוקבא, והלא גם בעתיד משה הוא יהיה הגואל, וכמ\"ש באוה\"ח שם בשם הזוה\"ק, ומאי שנא זה מזה.","b":false},{"t":"אמנם התשובה פשוטה, כי בגאולה העתידה יהיה ביד ישראל משנה כח ותוקף, וזאת, מכח התורה הקדושה שבידם. כי הנה בגאולת מצרים עדיין לא ניתנה התורה בשלימות, רק פרשת קרבן הפסח, וזה היה די לזכר שהוא הַעַיִר ואסרוהו והכניעוהו, אבל לגאולה של העתיד שהיא אחר מתן תורה לבני אדם, כחנו גדול, ויכולים להכניע את הסט\"א לגמרי. ואחריתו עד אובד, וגם הנוקבא הרשעה כעשן תכלה. בב\"א.","b":false},{"t":"והואיל ובגאולה עסקינן אוסיף עוד מעט להביא מדב\"ק של האוה\"ח זיע\"א, ממה שראוי שנשים לבנו אליו, והיא המעלה הגדולה של הגאולה כשבאה ע\"י לימוד התורה, שאז הגאולה תהיה בשובה ונחת, כשמש זורחת והיא כפורחת, בלי יסורים מיותרים, אשר לזה רמז הכתוב, כִּבֵּס ביין לבושו שהוא יינה של תורה, וז\"ל, שיתעסקו ישראל ביינה של תורה, ואמר כי באמצעות התורה, יהיה לבושו שהוא כינוי למלכות נכון אליו ללובשו, ואמר ובדם ענבים סותה, נתכוין לומר, כי אם יגיע זמן הגאולה ולא ימצא יין פירוש שאין בנו תורה, תהיה הגאולה באמצעות עול ותוקף הגלות, אשר יצירון האומות לישראל, כאמרם ז\"ל (סנהדרין צז, ב), כי כשיגיע קץ הנחתם ולא יהיה בישראל זכות לגואלם, יעמיד להם הי\"ת מלך קשה כהמן וכו', והוא אומרו ובדם ענבים, כי באמצעות היסורין יזדככו הנפשות ויתבררו ניצוצי הקדושה, כדרך שיתבררו באמצעות בחינת התורה, אלא שזו מלאכתו נאה, וזו מלאכתו בלתי נאה וכו'.","b":false},{"t":"וע\"ש עוד שכתב, דלכן נכתב בפסוק \"ענבים\", לרמוז שלא ישלטו הגוים לשפוך דם לזמור אילן או ענף או אשכול, אלא ענבים, פי' גרגרים. ע\"כ. ויש בזה נחמה פורתא שגם אם ח\"ו ישפך דם של שונאי ישראל ח\"ו, יהיה גרגרים אחדים ולא אשכול ולא זמורה רח\"ל. וככל שנרבה בתורה כן יתמעטו הדמים.","b":false},{"t":"ולא עוד אלא שיש עוד הפרש גדול, בין גאולה בזכות התורה לבין גאולה בזכות היסורין, כי אם תהיה הגאולה באמצעות התורה והמצות, אז יתגלה הי\"ת בגילוי מלכות עליון, בבחינת הנה ה' בא על עב קל, ואילו אם תהיה באמצעות היסורים כהנ\"ל, אז יהיה בבחינת עני ורוכב על חמור (זכריה ט, ט), עכתד\"ק.","b":false},{"t":"[א\"ה - מה נאוו דברי רבינו הקדוש בעל אור החיים לפרש דבר נפלא, והוא, כי הנה כתב מרן החיד\"א ז\"ל בספר פני דוד (סדר ויחי עה\"פ דן ידין), משם הרב המקובל מהר\"י פייאמיטה ז\"ל אב\"ד באנקונה, שאמר כי כשהישועה היא מצד רחמיו יתברך היא ישועה אחת, וכשהיא מצד הדין נחשבת שתי ישועות, וזה כונת הכתוב מי יתן מציון ישועת ישראל בשוב ה', שם המיוחד שהוא שם של רחמים מצד רחמיו, ואז היא ישועת ישראל ישועה אחת, וזהו אומרו בתהלים מזמור יד (פסוק ז), מי יתן מציון ישועת ישראל בשוב ה' שבות עמו. אך במזמור נג (פסוק ז), אמר מי יתן מציון ישועות ישראל בשוב אלהים שבות עמו, דכשזוכים בזכותם לעשות הישועה אז היא ישועות תרתי, וזה שאמר \"ישועות\" ישראל בשוב \"אלהים\", מדת הדין. ע\"כ. ומרן החיד\"א האריך והרחיב את הדברים עוד, יעו\"ש.","b":false},{"t":"ברם לפי מה שנתבאר כאן, יש לפרש ולומר, דהנה האות וא\"ו היא נותנת ההפרש בין ישועת לישועות, והאות וא\"ו רומזת לתורה כאשר ביאר מרן המחבר נר\"ו בדבריו, והיינו כאשר זכו ישראל והגאולה באה בזכות לימוד התורה, אז גם מדת הדין מסכמת לגאולה ויש גאולה גדולה ונפלאה. ואילו כשאין תורה אלא יסורין אז היא גאולה זוטא שבאה רק מכח מדת הרחמים ולא עוד, והדברים מופלאים. יבח\"ר].","b":false},{"t":"ישמע ישראל ונשים הדברים אל לבנו, מי יתן מציון ישועת ישראל בשוב ה' שבות עמו, יגל יעקב ישמח ישראל (תהלים יד, ז).","b":false}]},{"id":"22","t":"המלכות שייכת ליהודה לנצח","p":[{"t":"לֹא יָסוּר שֵׁבֶט מִיהוּדָה וּמְחֹקֵק מִבֵּין רַגְלָיו עַד כִּי יָבֹא שִׁילֹה וְלוֹ יִקְּהַת עַמִּים: (מט, י)","b":true},{"t":"אמרו רבותינו (סנהדרין ה, א), לא יסור שבט מיהודה, אלו ראשי גלויות שבבבל, שרודים את העם בשבט, הממונים ע\"פ המלכות, ומחוקק מבין רגליו, אלו הנשיאים שבארץ ישראל. והביא דבריהם רש\"י ז\"ל בפירושו.","b":false},{"t":"והרמב\"ן ז\"ל כתב שאין ענינו שלא יסור לעולם, כי כבר כתוב (דברים כח, לו), יולך ה' אותך ואת מלכך אשר תקים עליך אל גוי אשר לא ידעת אתה ואבותיך. והנה הם בגולה ואין עוד מלך, וימים רבים אין מלך בישראל וכו'. אבל ענינו שלא תסור המלכות מבית דוד אל שבט אחר, וכן מחוקק אשר לו טבעת המלך ממנו יהיה, עד כי יבא שילה שהוא המשיח. ע\"ש. עוד כתב, דמלכות שאול שהוא מבנימין ולא מיהודה היתה בעבור ששאלו מלך והיה נתעב בעיני ה', על כן לא רצה להמליך עליהם משבט המלוכה שלא יסור ממנו לעולמים, ונתן להם מלכות שעה. וע\"ש שכתב שעל כן נהרג שאול ובניו רח\"ל, והיה כל זה מפני שהיה שמואל שופט ונביא ולוחם מלחמותיהם ע\"פ ה' ומושיע אותם, ולא היה להם לשאול מלך בימיו, כמו שאמר להם (ש\"א יב, יב), וה' אלהיכם מלככם, ואומר (שם ח, ז), לא אותך מאסו כי אם אותי מאסו ממלוך עליהם, ולפיכך לא נתן להם מלכות של קיימא. עוד כתב, וכאשר האריכו להמליך מלכים משבט אחר ולא משבט יהודה, עברו על צואת הזקן ונענשו, וזה היה עונש החשמונאים שמלכו בבית שני, כי היו חסידי עליון, ואלמלי הם נשתכחו התורה והמצוות מישראל. ואעפי\"כ נענשו עונש גדול, כי ארבעת בני חשמונאי הזקן החסיד, המולכים זה אחר זה נפלו בידי אויביהם, והגיע העונש לבסוף למה שאמרו חז\"ל (ראה ב\"ב ג, ב), כי מי שיאמר שהוא מבית חשמונאי, עבד הוא, כי נכרתו כולם בעוון הזה, והוא מדה כנגד מדה, שהסירו מזרע יהודה שבט ומחוקק לגמרי, והמשיל הקב\"ה עליהם את עבדיהם והכריתום. וע\"ש שכתב עוד טעם, משום שבני חשמונאי היו כהנים, ואין להם למלוך אלא לעבוד את הי\"ת. יעו\"ש באריכות.","b":false},{"t":"ועוד אפשר לומר בס\"ד, לא יסור שבט מיהודה, היינו הממשלה והשלטון. ומחוקק, היא התורה הק', כמו שנאמר (שמות טו, כה), שם שם לו חוק, וכן נאמר על משה רבינו (דברים לג, כא וברש\"י שם), שם חלקת \"מחוקק\" ספון, וכן הוא בפירוש יונתן בן עוזיאל (בראשית מט, י), וכן בתרגום ירושלמי (שם).","b":false},{"t":"והכונה בזה היא שגם הגוף וגם הנשמה, יהיו משבט יהודה בכל המלכים אשר ימלכו מזרעו עד כי יבא שילה, שהוא מלך המשיח (ב\"ר צט, ח), דאז יהיה רק גופו (השבט), מיהודה, אבל נשמת המשיח תהיה נשמת משה רבינו ע\"ה, כמפורש בדברי רבינו אוה\"ח הקדוש זיע\"א על הפסוק (בראשית מט, יא), אוסרי לגפן, שהביא דברי הזוה\"ק (ח\"ב קכ, א וראה עוד שם ח\"ג רמו, א ושם רפ, א), כי משה הוא הגואל אשר גאל את אבותינו והוא יגאל אותנו בדרא בתראה וישיב בנים לגבולם וכו'. ולא יקשה בעיניך דבר זה, באומרך הלא מלך המשיח משבט יהודה, מזרעו של דוד המלך ע\"ה, וא\"כ היאך אנו אומרים שהוא משה שהוא משבט לוי. יש לך לדעת כי בחינת \"נשמת משה\" היא כלולה מי\"ב שבטי ישראל וכו', ולעתיד לבא תתגלה בעולם, שורש המלכות שבמשה, שהוא עצמו מלך המשיח, והוא דוד והוא ינון ושילה, עכלה\"ק.","b":false},{"t":"וזהו לא יסור שבט מיהודה ומחוקק מבין רגליו, שבכל מלכי בית דוד גם הגוף וגם הנשמה הם משורש יהודה, וזהו דדייק קרא מבין רגליו. עד כי יבא שילה, הוא מלך המשיח, ואז יהיה השילוב הנורא, שהנשמה נשמת משה רעיא מהימנא, תזדוג ותתעבר עם משיח בן דוד שיתגלה בב\"א.","b":false},{"t":"עוד יש לומר, דמה שאמר \"ומחוקק מבין רגליו\", הוא משה רבינו ע\"ה, שעליו נאמר שם חלקת \"מחוקק\" ספון, ומשה הוא בחינת התוה\"ק שקרויה על שמו כדכתיב (מלאכי ג, כב), זכרו תורת משה עבדי, והוא בא בזרע יהודה בבן פרצי שהוא מלך המשיח, שהוא אחרית ותכלית מלכות בית דוד, וזה שאמר \"ומחוקק\", היינו משה, והמשיך \"מבין רגליו\" לרמוז על הסוף והאחרית, בגאולה העתידה לבא בב\"א","b":false}]},{"id":"22","t":"מהו \"קץ הימין\"","p":[{"t":"הִקָּבְצוּ וְשִׁמְעוּ בְּנֵי יַעֲקֹב וְשִׁמְעוּ אֶל יִשְׂרָאֵל אֲבִיכֶם: (מט, ב)","b":true},{"t":"כתב בעל הטורים, ושמעו אל ישראל. בגימטריא זהו קצו של מלך המשיח.","b":false},{"t":"וגם בפסוק הקודם (לעיל מט, א), שנאמר, ויקרא יעקב אל בניו ויאמר האספו ואגידה לכם את אשר יקרא אתכם באחרית הימים, כתב הרמב\"ן ז\"ל (שם), שהם ימות המשיח, כי יעקב רומז על זה בדבריו, כמו שאמר (להלן מט, י), עד כי יבא שילה וגו'. וכעין זה כתב בפירוש רבנו עובדיה ספורנו ז\"ל (שם).","b":false},{"t":"וכנראה שעפי\"ז כתב המשורר בפיוט יגדל אלהים חי בסופו, ישלח לקץ ימין משיחנו לפדות מחכי קץ ישועתו.","b":false},{"t":"ובסוף דניאל (יב, יג), כתיב, ואתה לך לקץ ותנוח, ותעמוד לגורלך לקץ הימין. ומשמע שקץ הימין הוא תחית המתים, שעל כן כתב ותעמוד לגורלך וכו' [א\"ה ובאמת מנהג ישראל היה לחרות על מצבות הקבורה את הפסוק הזה ואתה לך לקץ וגו', וכאשר ראיתי בבתי החיים דעי\"ת אזמיר וקושטא. יבח\"ר]. ואולי מחשיב כל זה לקץ הימין, שגם ביאת המשיח וגם תחית המתים, כולם הם לעתיד לבא.","b":false}]},{"id":"22","t":"בענין מלחמת יעקב ובניו עם בני העיר שכם","p":[{"t":"שִׁמְעוֹן וְלֵוִי אַחִים כְּלֵי חָמָס מְכֵרֹתֵיהֶם, בְּסֹדָם אַל תָּבֹא נַפְשִׁי בִּקְהָלָם אַל תֵּחַד כְּבֹדִי כִּי בְאַפָּם הָרְגוּ אִישׁ וּבִרְצֹנָם עִקְּרוּ שׁוֹר, אָרוּר אַפָּם כִּי עָז וְעֶבְרָתָם כִּי קָשָׁתָה אֲחַלְּקֵם בְּיַעֲקֹב וַאֲפִיצֵם בְּיִשְׂרָאֵל: (מט, ה-ז)","b":true},{"t":"כל המפרשים כתבו שהוכיחם יעקב על מעשה שכם, וכאשר פירשו רש\"י ז\"ל (מט, ה), והראב\"ע ז\"ל (שם), וגם הרמב\"ן ז\"ל (שם), ושאר מפרשים. ומפשטות המקרא נראה שהוא כועס עליהם על מעשה שכם וגם על מכירת יוסף וכמ\"ש רש\"י ז\"ל שם. ואשר על כן אמר יעקב, בסודם אל תבא נפשי וגו'.","b":false},{"t":"וכן הוא בפירוש הרמב\"ן ז\"ל שכתב, וז\"ל, וכבר פירשתי (לעיל לד יג), כי יעקב קצף על שמעון ולוי בהרגם אנשי העיר (שכם), בעבור שעשו חמס, כי הם לא חטאו כלל (בענין דינה), ובאו בברית ונימולו, ואולי ישובו אל ה', ויהיו כולם בכלל אנשי בית אברהם ומן הנפש אשר עשו. ועוד חרה לו שלא יאמרו שבעצתו נעשה הדבר, ויהיה חלול ה', שיעשה הנביא חמס ושׁוד, וזה טעם בסודם אל תבא נפשי, התנצלות שלא היה בסודם, בענותם במרמה. ובקהלם לא נתיחד, כשבאו על העיר והרגום, ולכן יקלל אפם ועברתם, וכן תירגם אונקלוס ברזיהון לא הות נפשי וכו'. עכל\"ק.","b":false},{"t":"ובימינו רבים המלעיזים על אבינו בחיר האבות איש האמת והצדק, איך עלתה לו כזאת להרוג עיר שלמה בגלל חטא של יחיד, ויהיה חמור כמה שיהיה, וחשבו שגם יעקב אבינו ע\"ה, הסכים על ידם, וכמו שהוא עצמו אמר ליוסף כאן (לעיל מח, כב), ואני הנה נתתי לך שכם וגו' אשר לקחתי מיד האמורי בחרבי ובקשתי, אך לא שמו לבם לפסוק זה בו הוכיחם בדברים עזים, ובודאי לא ראו דברי הרמב\"ן ז\"ל הללו.","b":false},{"t":"ומה שאמר יעקב (שם), בחרבי ובקשתי, תירגם אונקלוס בצלותי ובבעותי, ורש\"י ז\"ל (שם), כתב, בחרבי ובקשתי בחכמתו ותפלתו. וע\"ש בדברי הרא\"ם ז\"ל דא\"א לומר בחרבי ובקשתי על חרבם של שמעון ולוי, דהא לא עשו מדעתו של יעקב, שהרי כעס עליהם על זה. ועוד כתב, ולענ\"ד בלאו הכי אי אפשר לומר על חרבו ממש, דא\"כ איזה נתינת טעם יש בזה שלכן הוא מוסרה ליוסף. והרי זה ראוי לראובן ושמעון שהם נלחמו בעיר וכבשוה. וע\"ע בשאר דברי המפרשים (שם). וע\"כ יחתמו פי השטנים המשטינים על עם ה' רעה, לאמור ליסטים אתם ח\"ו.","b":false},{"t":"ושמעון ולוי שעשו כן, כתב רבינו הקדוש בעל אוה\"ח זלה\"ה (בראשית מט, ה), שהיה טבע שמעון ולוי חם כאומרו (ש\"א טז, יב), והוא אדמוני. כי מי שיגבר בו יסוד האש עם היות שיתעצם בכל עוצם הזריזות בעבודת ה' לא ימלט משגגות וכו'. ע\"ש. וא\"כ האש הטבעית שהיתה מרובה בהם, העבירתם על דעתם ועשו מעשה חמור שעליו כעס אביהם מאד, ואמר עליהם דברים חמורים, וגם קילל את אפם ואת עברתם.","b":false},{"t":"ועיין עוד ברש\"י ז\"ל פרשת וישלח (בראשית לד, כה), שני בני יעקב, בניו היו ואף על פי כן נהגו עצמן שמעון ולוי כשאר אנשים שאינם בניו, שלא נטלו עצה ממנו. ומקור דבריו בב\"ר (פ, י).","b":false},{"t":"ואולם הרב אוה\"ח הקדוש (שם), כתב, דשמעון ולוי רצו להרוג רק את בעל העבירה בלבד, אלא שכל בני העיר עמדו כנגדם להציל את שכם בן חמור שהיה מלכם, ונאלצו שמעון ולוי להלחם אתם, ולהורגם מדין רודף, ואשר על כן כתוב, ויהרגו כל זכר. ואת חמור ואת שכם בנו הרגו לפי חרב ויקחו את דינה אחותם (בראשית לד, כה-כו), יעו\"ש.","b":false},{"t":"ואפשר להוסיף עוד עפ\"י דברי קדשו של הרב אוה\"ח הק', דמטרתם שמעון ולוי בהריגת שכם בן חמור היתה כדי להציל את דינה אחותם, כי בעל העבירה לא הסכים לשחררה [א\"ה ועוד כי מפני הבושה סירבה לחזור לבית אביה כמפורש בב\"ר (פ, יא), והובא ברש\"י (בראשית מו, ח), ולכן הוכרחו להורגו כדי שתתרצה לשוב לבית אביה. יבח\"ר]. וכל אנשי שכם נקהלו ועמדו נגדם להציל את מלכם, וממילא ביקשו למנוע את הצלת דינה אחותם, ורצו להרוג את שמעון ולוי, והם חירפו את נפשם למות בעד אחותם, והי\"ת עזרם, אך בהיותם נלחמים על נפשם להצילה נאלצו להרוג כל זכר וסוף דבר שלקחו את דינה אחותם.","b":false}]},{"id":"22","t":"ברוך שם כבוד מלכותו לעולם ועד ויהא שמיה רבה מברך לעלמי עלמיא, ענינם שוה","p":[{"t":"וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו וַיֹּאמֶר הֵאָסְפוּ וְאַגִּידָה לָכֶם אֵת אֲשֶׁר יִקְרָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים: (מט, א)","b":true},{"t":"אמרו רבותינו (פסחים נו, א ב\"ר צו, א ושם צט, ה ותנחומא ויחי פ\"ח), ביקש יעקב לגלות הקץ, ונסתלקה ממנו שכינה. וכן הוא בתרגומים כאן ובדברי רש\"י ז\"ל.","b":false},{"t":"ובתרגום ירושלמי הוסיף וכתב בזה, ענה אבונא יעקב, ואמר להון [לבניו] אברהם אבוי דאבא קם מיניה פיסול ישמעאל וכל בני קטורה. ויצחק אבא קם מיניה פיסול עשו אחי. ואנא דחיל דלא יהא ביניכון גבר ליביה פליג על אחוי, למיזל למפלח קדם טעוון אוחרנין. [פירוש, שאמר יעקב לבניו פן יש בכם ח\"ו מי שלבו פונה מעם ה', וע\"כ נסתלקה השכינה]. ענו כולם ואמרו לו, שמע מינן ישראל אבונא, ה' אלהינו ה' אחד. ענה יעקב ואמר יהא שמיה רבא מברך לעלמי עלמין, עכ\"ל התרגום.","b":false},{"t":"ובגמרא פסחים (נו, א), ג\"כ אמרו, שבני יעקב השיבו לו, שמע ישראל ה' אלהינו ה' אחד. ובזה השיבו לו שאין בהם שום פיסול ח\"ו. והוא ענה אחריהם, ברוך שם כבוד מלכותו לעולם ועד. ולכאורה נראה שהבבלי והתרגום ירושלמי חולקים מה היתה תשובתו של יעקב אבינו ע\"ה, כי בתרגום ירושלמי אמרו שהשיב יהא שמיה רבא וכו', ואילו בתלמוד בבלי אמרו שהשיב יעקב ברוך שם וגו'.","b":false},{"t":"וזכורני שראיתי בהקדמה לח\"ב מספר שערי אורה להרה\"ג רמ\"צ ברגמן שליט\"א חתנא דבי נשיאה של בעל \"אבי עזרי\" זיע\"א שכתב בשם הגאון בעל עמודי אור, שיהא שמיה רבא וכו' הוא תרגום של ברוך שם וגו'. והוכיח שכבוד מלכותו יתברך, היא גדולתו של המקום ברוך הוא. ע\"ש. ובאמת שבמסכת יומא (לז, א), אמרו שכשהכהן הגדול אומר, שם המפורש, הכהנים והעם עונים ברוך שם וגו', משום דכתיב (דברים לב, ג), כי שם ה' אקרא הבו גודל לאלהינו, ובשעה שמזכירין שם ה' צריכים לתת לו כבוד. נמצא דהבו גודל, הוא לומר ברוך שם כבוד מלכותו לעולם ועד.","b":false},{"t":"וא\"כ יהא שמיה רבה מברך, שהוא, יהא שמו הגדול מבורך, זהו עצמו, ברוך שם כבוד מלכותו. לעלם ולעלמי יתברך, זהו לעולם ועד. ונמצא דהירושלמי והבבלי לא פליגי, רק בתרגום ירושלמי כתב בלשון ארמית, ואילו בתלמוד בבלי נקט בלשון הקודש ברוך שם וכו'.","b":false},{"t":"והנה ידוע שברוך שם כבוד מלכותו לעולם ועד אומרים אותו בלחש, כמו שכן נפסק בשו\"ע או\"ח (סי' ס\"א סעיף יג). וטעם הדבר כמו שמצינו בפסחים (נו, א), אמרי רבנן, היכי נעביד, נאמרוהו לא אמרו משה רבינו, לא נאמרוהו אמרו יעקב, התקינו שיהו אומרים אותו בחשאי. אמר רבי יצחק אמרי דבי רבי אמי משל לבת מלך שהריחה ציקי קדירה, אם תאמר יש לה גנאי. לא תאמר יש לה צער, התחילו עבדיה להביא בחשאי וכו', יעו\"ש. ברם רבותינו במדרש רבה (דברים רבה ב, לה), אמרו, שמע ישראל, רבנן אמרין בשעה שעלה משה למרום שמע למלאכי השרת שהיו אומרים להקב\"ה בשכמל\"ו, והוריד אותה לישראל. ולמה אין ישראל אומרים אותו בפרהסיא, א\"ר אסי למה הדבר דומה לאחד שגנב קוזמין (פירוש מין תכשיטין), מתוך פלטין של מלך נתנה לה לאשתו ואמר לה אל תתקשטי בה בפרהסיא, אלא בתוך ביתך אבל ביום הכפורים שהן נקיים כמלאכי השרת הן אומרים אותו בפרהסיא בשכמל\"ו, ורבינו הטור הביא את דברי המדרש הזה באו\"ח סי' תרי\"ט, (א\"ה - ועי' יפה ללב או\"ח סי' ס\"א אות יו\"ד מש\"כ בזה. וראה לרבינו הרמב\"ם פ\"א מק\"ש הלכה ד' שנראה שעירב דברי התלמוד עם דברי המדרש, יעו\"ש. יבח\"ר). ועל כן כל השנה אומרים בשכמל\"ו בלחש, מלבד יום הכיפורים, שאז אנו כמלאכים, ואומרים אותו בקול רם.","b":false},{"t":"ולפי הדברים הנ\"ל יוצא דבר חשוב ונפלא, כי כשאנו אומרים ברוך שם כבוד מלכותו לעולם ועד, אנו אומרים אותו בלשון הקדש כמו שהמלאכים אומרים אותו ממש, ולכן אנו אומרים אותו בלחש מפני הכבוד. אבל כדי שלא יראה שאנו מקילים בכבוד הי\"ת ח\"ו לומר שבחו בלחש, על כן אנו אומרים אמן יהא שמיה רבא בקול רם כי הוא בלשון ארמית ואין חשש מפני המלאכים. ואנו אומרים אותו בארמית בקול רם כנגד מה שאומרים אותו בלשון הקדש בלחש, ועל כן אמרו חז\"ל, כל האומר יהא שמיה רבה בכל כחו קורעים לו גזר דינו של שבעים שנה (שבת קיט, ב - ומה שנזכר קריעת גזר דין של שבעים שנה הוא ברי\"ף ברכות דף י\"ג ע\"ב מדפי הרי\"ף), כי בארמית גם כשהאמירה באה בקול רם אין פגיעה במלאכים, לפי שאינם יודעים ארמית.","b":false},{"t":"ועיין בבעל הטורים שכתב שיעקב אמר לבניו שמע ישראל, ונרמז בכתוב, הקבצו ושמעו בני יעקב, שמעו הן אותיות שמע ו', שאמר להם שמ'ע ישראל שיש בו ו' תיבות עכ\"ל, וצ\"ע שבגמרא נאמר שהם אמרו לו שמע ישראל וגו' ולא הוא שאמר להם [א\"ה – בפי' בעל הטורים הנדפס עפ\"י כת\"י, איתא, שבני יעקב אמרו לו שמע ישראל, והוא כדברי הגמ' ולק\"מ. יבח\"ר].","b":false}]},{"id":"22","t":"אי אפשר להשיג השגות גדולות ללא הכנה מראש","p":[{"t":"וַיִּקְרָא יַעֲקֹב אֶל בָּנָיו וַיֹּאמֶר הֵאָסְפוּ וְאַגִּידָה לָכֶם אֵת אֲשֶׁר יִקְרָא אֶתְכֶם בְּאַחֲרִית הַיָּמִים: (מט, א)","b":true},{"t":"ובתרגום יונתן בן עוזיאל כתב: וקרא יעקב לבנוי ואמר להום אדכו מסואבותא, ואחוי לכון רזייא סתימיא קיצייא גניזיא, ומתן אגרהון דצדיקייא. ופורענותהון דרשיעיא, וטלניתא דעדן מה היא, כחדא מתכנשין תריסר שבטי ישראל, מקפין דרגשא דדהבא דרביע עלה, מן דאיתגלי איקר שכינתא דה' קיצא דעתיד מלכא משיחא למיתי איתכסי מיניה, ובכן אמר איתו ואיתני לכון מה דיארע יתכון בסוף יומיא [תרגום - ויקרא יעקב לבניו ואמר להם, הִטהרו מטומאתכם, ואגלה לכם סודות סתומים והקץ הגנוז, ומתן שכרם של צדיקים ופורען הרשעים וכו'], וכן הוא בתרגום ירושלמי.","b":false},{"t":"וכנראה שלמדו בתרגומים את ענין ההטהרות מהטומאה מהלשון הכפול שבפסוק זה, ויקרא יעקב אל בניו ויאמר האספו ואגידה וגו'. והיה די שיאמר ויאמר יעקב לבניו האספו, ומהו לשון ויקרא יעקב וגו' \"ויאמר האספו\". אלא מכאן שאמר להם להכין עצמם לפני האסיפה, בבחינת והכינו את אשר יביאו (בראשית טז, ב), כי ידע יעקב אבינו את חשיבות השעה הזאת בה הוא רוצה לגלות לבניו רזין טמירין, ולגלות להם את זמן הקץ הנחתם, ובפרט למה שפירשתי בס\"ד, דכונת הגילוי הזה הוא כדי לקרב קץ משיחיה. שבזה יעקב אבינו השתדל בכל זמן, ולזה תירגם ביונתן בן עוזיאל, שאמר להם הטהרו מטומאתכם.","b":false},{"t":"והמעיין בתחילת האידרא רבה קדישא (זוהר ח\"ג קכז, ב), בעת הילולת קדוש ה' מכובד התנא רבי שמעון בר יוחאי זיע\"א, בעיניו יראה את הדמיון הגדול לכאן, כי גם הוא אסף את תלמידיו הקדושים לגלות להם רזין טמירין שלא גילה עד אז, ודרש מהם הכנה רבה לקראת מעמד זה, ואביא מעט מן הלשון שם:","b":false},{"t":"אמר ר\"ש לחבריא עד אימת ניתיב בקיימא דחד סמכא וכו', אתכנשו חבריא לבי אדרא מלובשין שריין סייפי ורומחי בידיכון אזדרזו בתקוניכון, בעיטא בחכמתא, בסוכלתנו, בדעתא, בחיזו, בידין, ברגלין, אמליכו עליכון למלכא דברשותיה חיי ומותא. למגזר מילין דקשוט מילין דקדישי עליונין צייתי להו, וחדאן למשמע להו ולמנדע להו. יתיב ר\"ש ובכה ואמר וי אי גלינא וי אי לא גלינא. חבריא דהוה תמן אשתיקו. קם ר' אבא ואמר ליה אי ניחא קמיה דמר לגלאה, הא כתיב סוד ה' ליראיו והא חבריא אלין דחלין דקב\"ה אינון, וכבר עאלו באדרא דבי משכנא מנהון עאלו מנהון נפקו וכו'. תאנא אתמנו חבריא קמיה דר\"ש ואשתכחו רבי אלעזר בריה. ור' אבא. ור' יהודה. ורבי יוסי בר יעקב. ור' יצחק. ור' חזקיה בר רב. ור' חייא. ור' יוסי. ור' ייסא. ידין יהבו לרבי שמעון ואצבען זקפו לעילא, ועאלו בחקלא ביני אילני ויתבו. קם ר\"ש וצלי צלותיה. יתיב בגווייהו ואמר כל חד ישוי ידוי בתוקפוי. שוו ידייהו ונסיב לון וכו'. ע\"כ.","b":false},{"t":"וגם כאן גילה לנו התרגומים את הרמוז בפסוק, שדרש יעקב אבינו ע\"ה מבניו, שיטהרו מכל טומאה, והוא מעט המכיל את המרובה הנדרש באותה עת, כדי שיהיו ראויים לשעה הגדולה, ושתשרה עליהם השכינה. ויוכלו לשמוע מאבינו הגדול, את הגילוים הנוראים.","b":false},{"t":"ומשראה יעקב אבינו ע\"ה שנסתם ממנו הקץ וזמן התגלות המשיח, וכדברי רבותינו בגמרא (פסחים נו, א), וכן בתרגומים הנ\"ל שם, וכן נזכר בדברי רש\"י ז\"ל (שם), ביקש יעקב לגלות את הקץ ונסתלקה ממנו שכינה והתחיל לומר דברים אחרים.","b":false},{"t":"ואביא עוד מדברי בעלי התוספות בספר דעת זקנים שכתבו, את אשר יקרא אתכם - פירוש בסוף ארבע מאות ושלשים שנה של גלות מצרים, [דמילת] \"הימים\" מכריחנו לפרש כן, דאי לא, הוה ליה למכתב באחרית ימים, בסוף ימי העולם. ושמעתי באחרית הימים, של הקב\"ה, דהיינו, בסוף חמשת אלפים. וביקש יעקב לגלות הקץ ונסתלקה ממנו שכינה, ותמה ואמר, למה אלו אין ראויים לגלות להן הקץ והלא אין בהם חטא, כלומר, אין בכל שמות השבטים לא חי\"ת ולא טי\"ת. השיבו רוח הקדש גם אין בכל אותיות שמות השבטים לא קו\"ף ולא צד\"י, אם כן אינן ראויין לגלות הקץ, ועל אשר קראת לבניך, להם אתה קורא, לי אין אתה קורא, כמה דאת אמר ולא אותי קראת יעקב כי יגעת בי ישראל (ישעיה מג, כב), אין המדה זו שלך הולך רכיל מגלה סוד וגו', כשראה יעקב כך, הפליגן בדברים ואמר, ראובן בכורי אתה, ומעין זה כתב בפי' ר\"י בעל הטורים.","b":false},{"t":"והמעיין היטב בדברי האדרא רבה שם, יראה כמה דברים שוים יש בין שתי ההתכנסויות, ויבין מעט מן הקורות בעת הקיבוץ של יעקב אבינו ע\"ה עם בניו שבטי יה עדות לישראל.","b":false}]},{"id":"22","t":"בעת אבלות שולטת מדת הדין","p":[{"t":"וַיֹּאמֶר יִשְׂרָאֵל אֶל יוֹסֵף הִנֵּה אָנֹכִי מֵת וְהָיָה אֱלֹהִים עִמָּכֶם וְהֵשִׁיב אֶתְכֶם אֶל אֶרֶץ אֲבֹתֵיכֶם: (מח, כא)","b":true},{"t":"כאן לא אמר יעקב \"האלהים\" שהוא רחמים, וכפי שאמר ליוסף בעת שברכו. ואפשר שמכאן נלמד, שהאבלים בזמן אבלם מדת הדין מתוחה עליהם, וצריכים רחמים. וידוע שלכן אין אומרים תחנון בבית האבלים, וגם ענין הקדיש הוא להמתיק את הדינים, ונרמז הענין כאן באומרו, הנה אנכי מת והיה אלהים עמכם.","b":false},{"t":"ומיהו לא נמנע מרחמים לגמרי, וע\"כ הקדים תיבת והיה שהוא אחד מי\"ב צירופי שמות הוי\"ה ב\"ה (והוא צירף הח' כמש\"כ בפע\"ח שער הזמירות פ\"ד), לפני מדת אלהים, וגם זה הוא מיתוק גדול. וזהו שממשיך והשיב אתכם וגו'.","b":false}]},{"id":"22","t":"בחיוב לקבל את הגלות באהבה ולא לבעוט בגזירות הי\"ת","p":[{"t":"וַיַּשְׁבַּע יוֹסֵף אֶת בְּנֵי יִשְׂרָאֵל לֵאמֹר פָּקֹד יִפְקֹד אֱלֹהִים אֶתְכֶם וְהַעֲלִתֶם אֶת עַצְמֹתַי מִזֶּה: (נ, כה)","b":true},{"t":"הנה משמעות הכתוב שהשבועה היתה גם על פקד יפקוד ולא רק על והעליתם את עצמותי מזה אתכם. והנה צריך להבין מה שבועה יש על ענין פקוד יפקוד. ועי' בדעת זקנים מבעלי התוספות מה שכתבו בזה.","b":false},{"t":"ובתרגום יוב\"ע תרגם, ואומי יוסף ית בני ישראל למימר לבניהון, הא אתון משתעבדין במצרים, ולא תזידון למיסוק ממצרים, עד זמן דייתון תרין פרוקין ויימרון לכון מדכר דכיר ה' יתכון, ובעידן דאתון סלקין תסקון ית גרמי מיכא.","b":false},{"t":"כלומר שהשביעם יוסף שלא ידחקו את הקץ, ולא יזידו לצאת ממצרים קודם הזמן הקצוב להם, ולא יצאו ממצרים עד שיבא נביא ה' ויאמר להם פקד יפקד אתכם. ובאמת מצינו שאמר הי\"ת למשה שיאמר לבני ישראל פקד פקדתי אתכם (שמות ג, טז), וכשאמר משה את דבר ה' אל העם, נאמר (שם ד, לא), ויאמן העם וישמעו כי פקד ה' את בני ישראל וכי ראה את עניים, ויקדו וישתחוו. ואמרו רבותינו (שמו\"ר ה, יג), וישמעו כי פקד ה', על השמועה האמינו ולא על ראיית האותות, ובמה האמינו, על סימן הפקידה שאמר להם, שכך היה מסורת בידם מיעקב, שיעקב מסר את הסוד ליוסף, ויוסף לאחיו, ואשר בן יעקב מסר את הסוד לסרח בתו, ועדיין היתה היא קיימת. וכך אמר לה, כל גואל שיבא ויאמר לבני פקוד פקדתי אתכם הוא גואל של אמת, כיון שבא משה ואמר פקוד פקדתי אתכם, מיד ויאמן העם, במה האמינו, כי שמעו הפקידה, ההוא דכתיב, כי פקד ה' את בני ישראל וכי ראה את עניים, ויקדו וישתחוו. ויקדו, על הפקידה. וישתחוו, על כי ראה את עניים. ע\"כ.","b":false},{"t":"והנה כמו שהשביע יוסף את אבותינו שלא ידחקו את הקץ, כן הוא בגלות החל הזה, שגם בגלות הזאת השביענו הקב\"ה, שלא נעלה בחומה ולא נמרוד באומות וכו' כמפורש בסוף כתובות (קיא, א). ויה\"ר שיקויים בנו כימי צאתך מארץ מצרים אראנו נפלאות (מיכה ז, טו), בב\"א.","b":false}]},{"id":"22","t":"בטחון בהי\"ת בכל עת ובכל זמן","p":[{"t":"וַיֹּאמֶר יוֹסֵף אֶל אֶחָיו אָנֹכִי מֵת וֵאלֹהִים פָּקֹד יִפְקֹד אֶתְכֶם וְהֶעֱלָה אֶתְכֶם מִן הָאָרֶץ הַזֹּאת אֶל הָאָרֶץ אֲשֶׁר נִשְׁבַּע לְאַבְרָהָם לְיִצְחָק וּלְיַעֲקֹב: (נ, כד)","b":true},{"t":"כתב ר\"י בעל הטורים ז\"ל, אנכי מת ואלהים פקד יפקד אתכם, פירוש אנכי בשר ודם, היום כאן ומחר בקבר, אבל מלך אל חי וקיים הוא יפקוד אתכם. ע\"כ. ויש לבאר את דב\"ק דהכי קאמר יוסף לבני דורו, עד עתה הייתם סומכים עלי שאפרנס ואכלכל אותכם ואת טפכם, אבל אתם צריכים לבטוח בהי\"ת, כי אנוכי מת, וגם אם אחיה שנים רבות, הלא סוף אדם למיתה, ואין לכם לשים את מבטחכם בבשר ודם. ואלהים פקוד יפקוד, הוא אלהים חיים לעד לעולם, בו תבטחו, ועליו תהיה משענתכם, והוא יפקדכם ברחמים, ברוך הגבר אשר יבטח בה' והיה ה' מבטחו.","b":false},{"t":"ועוד כתב ר\"י בעל הטורים, שאמר יוסף פקוד, לרמוז שמנין פקוד חסר מארבע מאות שנה וישאר רד\"ו. ע\"כ. ופירוש דבריו, כי מנין פקוד עולה ק\"צ, וכן יחסיר הקב\"ה מן הזמן המיועד לגלות מצרים, ובמקום ארבע מאות שנות שעבוד במצרים יהיו רק מאתיים ועשר. כי ארבע מאות פחות ק\"צ נשאר רד\"ו שהם מאתיים ועשר.","b":false}]},{"id":"22","t":"מקור לכיבוד הסב בסנדקאות","p":[{"t":"וַיַּרְא יוֹסֵף לְאֶפְרַיִם בְּנֵי שִׁלֵּשִׁים גַּם בְּנֵי מָכִיר בֶּן מְנַשֶּׁה יֻלְּדוּ עַל בִּרְכֵּי יוֹסֵף: (נ, כג)","b":true},{"t":"אפשר לפרש את הפסוקים הללו על דרך המוסר, שבאו ללמדנו על חינוך הילדים. שעל האב להעמיד לפני בניו את הדמות של הסבא קדישא, שישאף לעלות ולהתעלות, ולהתגדל בדרכו של הסבא קדישא. וזהו שתרגם אונקלוס, ורבי יוסף, היינו שיוסף גידל את בניו ונכדיו וניניו, ודמותו הקדושה היתה חופפת עליהם כל היום, על דרך מה שנאמר (דברים לב, ז), שאל אביך ויגדך זקניך ויאמרו לך.","b":false},{"t":"ובתרגום יוב\"ע תירגם יולדו על ברכי יוסף, אתיילידו וגזרינון יוסף, והיינו שנימולו על ברכי הסבא שהוא שימש להם סנדק. וכן כתב בפירוש יונתן שם שיש לפרש בזה ב' פירושים, או שיוסף מל אותם על ברכי הסנדק, אי נמי שיוסף היה הסנדק. ע\"ש. והרי יש לנו מקור לסנדקות ושיש לכבד את הסב בסנדקאות, ונגד זקניו כבוד (ישעיה כד, כג).","b":false},{"t":"[א\"ה - לענ\"ד יש לפרש בדברי תרגום יוב\"ע, שיוסף היה גם הסנדק וגם המוהל, דהא בקרא כתיב יולדו על ברכי יוסף, ובזה כבר נזכר ענין סנדקאות. אמור מעתה שבתרגום יוב\"ע הוסיף דיוסף נמי גזרינון, והיינו שהיה גם סנדק וגם מוהל, וזה מתאים מאד ליוסף שמדתו יסוד. ועי' בספר אות חיים ושלום לאדמו\"ר ממונקאטש ז\"ל בענין מוהל וסנדק יחד אי יש לחוש בזה לאין עושין מצוות חבילות חבילות, והאריך בזה, והעלה דשרי להיות מוהל וסנדק גם יחד. ע\"ש. וכן שמעתי ממרן הגרע\"י נר\"ו לפני שנים רבות שכן נראית דעתו להלכה.","b":false},{"t":"או יש לומר דהנה עיקר מעלת הסנדק היא משום דהוא מסייע במילה במה שאוחז בתינוק בידיו והוי כמל בעצמו, וזה שכתב יוב\"ע וגזרינון יוסף. והיינו שהיה סנדק, ודו\"ק. יבח\"ר].","b":false}]},{"id":"22","t":"פיוס המיצר והדואג או העני","p":[{"t":"וַיֹּאמֶר אֲלֵהֶם יוֹסֵף אַל תִּירָאוּ כִּי הֲתַחַת אֱלֹהִים אָנִי, וְאַתֶּם חֲשַׁבְתֶּם עָלַי רָעָה אֱלֹהִים חֲשָׁבָהּ לְטֹבָה לְמַעַן עֲשׂה כַּיּוֹם הַזֶּה לְהַחֲיֹת עַם רָב, וְעַתָּה אַל תִּירָאוּ אָנֹכִי אֲכַלְכֵּל אֶתְכֶם וְאֶת טַפְּכֶם וַיְנַחֵם אוֹתָם וַיְדַבֵּר עַל לִבָּם: (נ, יט-כא)","b":true},{"t":"ראינו בפסוקים כי בתחילה אחי יוסף חששו ממנו, ויוסף השיבם אל תיראו, והמשיך ואמר אל תיראו אנכי אכלכל אתכם וגו', וא\"כ קשה מה לו עוד להוסיף לנחמם ולדבר על לבם. וצריך לדחוק ולומר, דהכי קאמר קרא דבדברים הנאמרים קודם, בזה היה מנחם את אחיו ומדבר על לבם.","b":false},{"t":"וראיתי בלקוטי אנשי שם, שפירש, דאחר שיוסף הבטיח לאחיו שיכלכלם היה צריך לדבר על לבם, כי אמרו רבותינו (ביצה לב, ב), כל המצפה על שלחן אחרים חשך עולם בעדו, ועל כן היה צריך לנחמם. וזה שאמר דוד המלך (תהלים קיב, ה), טוב איש חונן ומלוה יכלכל דבריו במשפט, והיינו, כי אחר שהאדם חונן דלים ומלוה לעניים, יכלכל את דבריו עמהם במשפט לנחמם ולפייסם, ולומר להם כי בזכותם מתקיימים הנותנים, והם הנותנים וכו', והכי נמי עשה יוסף, לכלכל את אחיו ולנחמם. וזה מה שאמרו רבותינו (בבא בתרא ט, ב), הנותן צדקה לעני מתברך בשש ברכות והמפייסו מתברך בי\"א ברכות, וכוונתם לומר, כי הנותן ואינו מפייס מתברך רק בשש ברכות, אבל העושה מעשה מושלם שגם נותן לעני צדקה וגם מפייסו בדברים ומרחיב את דעתו זוכה ומתברך בי\"א ברכות.","b":false},{"t":"[א\"ה – ושמעתי רמז נאה על זה במה שפותחים בסדר הגש\"פ \"הא לחמא עניא\", כי הנה בליל פסח בעה\"ב מכניס אורחים ועניים אל הבית, ובעת הזאת הזהירוהו חכמים מתקני נוסח ההגדה, שלא יתן לעניים את מאכלם ודי, אלא יאיר להם פנים ואז יזכה לי\"א ברכות, וזהו \"הא לחמא\" כלומר שמי שנותן הלחם ולא עוד זוכה לשש ברכות הרמוזות במילת \"הא\" שעולה בגימ' ו'. אך העונה בדברים ומפייס את העני מתברך בי\"א ברכות וזהו \"עניא\" ענ – י\"א, כלומר, שהעונה בדברים ומפייס את העני מתברך בי\"א ברכות. יבח\"ר].","b":false},{"t":"ושמעתי בזמנו מהגה\"צ המפורסם כקש\"ת רבי רפאל ברוך טולידאנו ע\"ה אב\"ד מקודש דעי\"ת מכנאס, שהיה מפרש את הפסוק בתהלים (תהלים מא, ב), אשרי משכיל אל דל ביום רעה ימלטהו ה'. דלכאורה הוה ליה למימר, אשרי תומך בדל, או אשרי עוזר לדל, אבל מה שייך לשון \"השכלה\" בזה.","b":false},{"t":"ופירש הוא ז\"ל, שהדל אין דעתו מיושבת עליו, כי העניות מעבירה את האדם על דעתו, וכשהאדם מפייסו ומדבר על לבו, הריהו מחזיר לו את דעתו וחכמתו למקומה, ולזה אמר, אשרי משכיל אל דל. ושכרו עמו, ביום רעה ימלטהו ה'. ומלבד זאת זוכה לאחד עשר ברכות המפורשות מפי רבותינו כמבואר (ב\"ב ט, ב וראה לעיל פר' ויצא מאמר ח).","b":false},{"t":"ואני עני מוסיף ומפרש, אשרי משכיל אל דל, אשרי אותו צדיק שכשבא אליו עני לבקש צדקה, אינו מוציא מכיסו מה שיש לו ונפטר ממנו כמקיים את חובתו, אלא טורח וחושב ומעמיק בדעתו למצוא באיזה הדרך ישכון אור לעני הזה, שיוכל לעמוד על רגליו בעמידה איתנה למען יצא מעניותו, וכלשון רבינו יונה (שערי תשובה שער ג אות יג), כי חייב אדם לטרוח בדרישת טוב לעמו ולשקוד בעמל נפשו על תקנת חברו אם דל ואם עשיר, וזאת מן החמורות ומן העקרים הנדרשים מן האדם, שנאמר (מיכה ו, ח), הגיד לך אדם מה טוב ומה ה' דורש ממך כי אם עשות משפט ואהבת חסד וכו'. והן הנה דרכי האיש המאושר אשר משעבד את כל מוחו לתקן את חברו האומלל. ע\"כ.","b":false},{"t":"וזה מדוקדק היטב בדברי הכתוב אשרי משכיל \"אל דל\", שכתוב \"אל דל\" ולא \"את דל\", כי אין ההשכלה לדל, אלא למי שעושה חסד עם הדל, שהוא משתמש בכל חכמתו כדי לסייע לחברו הדל. וזהו \"אשרי משכיל\".","b":false},{"t":"ומהו שכר המשכיל, ביום רעה ימלטהו ה'. מדה כנגד מדה, דבאותה מדה שחושב ומתאמץ לסייע ולתמוך בדלים, כמו כן הקב\"ה דואג לכל מחסורו, ומציל אותו מן הרעה קודם שידע ממנה, ושולח לו ישועה קודמת, ושב ורפא לו.","b":false}]},{"id":"22","t":"במעלת לימוד זכות","p":[{"t":"וְאַתֶּם חֲשַׁבְתֶּם עָלַי רָעָה אֱלֹהִים חֲשָׁבָהּ לְטֹבָה לְמַעַן עֲשׂה כַּיּוֹם הַזֶּה לְהַחֲיֹת עַם רָב: (נ, כ)","b":true},{"t":"בתרגום יוב\"ע איתא, ואתון חשבתון עלי מחשבין בישין, דמא דלא הוינא מסתחר עמכון למיכל מן בגלל דנטיר לכון בבו הוא וכו'. והיינו שיוסף לימד זכות על אחיו, שחשבו עליו מחשבות רעות לומר, שמה שלא היה מיסב ואוכל עמהם בהיותו בבית אביו הוא מפני שהיה שונא אותם. ויוצא לפי זה דיוסף לימד זכות על אחיו במה שמכרוהו ודן אותם כשוגגים, והמשיך וביאר להם שלא היה מיסב עמהם מפני שאביו קרא לו, וכיבוד אב עדיף, ולא מפני שהיה שונא אותם.","b":false},{"t":"ולפי הפשט היה נראה לפרש, \"אתם חשבתם עלי רעה\", כלומר, אתם חשבתם במכירתי שתהא לרעה ואני אהפוך לעבד עולם, ואהיה שוקע בתהום הנשיה. אמנם הי\"ת חשבה לטובה שהגעתי למלכות בזכות זה. אלא שלפי זה היה נראה יוסף כמקנטר אותם על מעשיהם ועל מחשבותיהם. ואמנם דבר זה אינו עולה בקנה אחד עם הפסוק שלפניו ויאמר אליהם יוסף אל תיראו, וכן בפסוק שלאחריו ועתה אל תיראו אנכי אכלכל אתכם וגו'. וא\"כ מה לו לקנטרם באמצע דבריו. אמנם לפי דברי התרגום, עולה דגם הפסוק האמצעי אתם חשבתם עלי רעה וגו', הוא פיוס. והרי יוסף כאומר להם, אין זו אשמתכם כי אני במעשי גרמתי שתחשדו בי.","b":false},{"t":"ושוב ראיתי לרבינו עובדיה ספורנו שכתב, ואתם חשבתם עלי רעה, הנה פעולתכם היתה בשגגה שחשבתם אותי לרודף, ואם היה זה האמת היה פעולתכם בדין. אלהים חשבה לטובה, המציא בכם זאת השגגה לתכלית טוב. עכ\"ל. וגם בפירוש הרשב\"ם כתב בדרך הזו, וז\"ל, אלהים חשבה לטובה - הקב\"ה גרם לכם ואתם לא פשעתם כי לטובתכם נתכוין הקב\"ה. ע\"כ.","b":false}]},{"id":"22","t":"בענין מי שחטא לחברו אם צריך שיבקש בעצמו מחילה מחברו, או די במה שמחל לו חברו מעצמו","p":[{"t":"וַיִּרְאוּ אֲחֵי יוֹסֵף כִּי מֵת אֲבִיהֶם וַיֹּאמְרוּ לוּ יִשְׂטְמֵנוּ יוֹסֵף וְהָשֵׁב יָשִׁיב לָנוּ אֵת כָּל הָרָעָה אֲשֶׁר גָּמַלְנוּ אֹתוֹ, וַיְצַוּוּ אֶל יוֹסֵף לֵאמֹר אָבִיךָ צִוָּה לִפְנֵי מוֹתוֹ לֵאמֹר, כֹּה תֹאמְרוּ לְיוֹסֵף אָנָּא שָׂא נָא פֶּשַׁע אַחֶיךָ וְחַטָּאתָם כִּי רָעָה גְמָלוּךָ וְעַתָּה שָׂא נָא לְפֶשַׁע עַבְדֵי אֱלֹהֵי אָבִיךָ וַיֵּבְךְּ יוֹסֵף בְּדַבְּרָם אֵלָיו, וַיֵּלְכוּ גַּם אֶחָיו וַיִּפְּלוּ לְפָנָיו וַיֹּאמְרוּ הִנֶּנּוּ לְךָ לַעֲבָדִים, וַיֹּאמֶר אֲלֵהֶם יוֹסֵף אַל תִּירָאוּ כִּי הֲתַחַת אֱלֹהִים אָנִי, וְאַתֶּם חֲשַׁבְתֶּם עָלַי רָעָה אֱלֹהִים חֲשָׁבָהּ לְטֹבָה לְמַעַן עֲשׂה כַּיּוֹם הַזֶּה לְהַחֲיֹת עַם רָב: (נ, טו-כ)","b":true},{"t":"מצינו לרבותינו שאמרו במסכת יומא (פה, ב), וכן בבבא קמא (צב, ב), עברות שבין אדם למקום יום הכפורים מכפר, עברות שבין אדם לחברו אין יום הכפורים מכפר עד שירצה את חברו, וכן פסק הרמב\"ם בהלכות תשובה (פ\"ב הלכה ט), ובטור ושו\"ע (או\"ח תרו, א).","b":false},{"t":"עוד איתא ביומא (פז, א), א\"ר חסדא וצריך לפייסו בשלש שורות של שלשה בני אדם, שנא' ישור על אנשים ויאמר חטאתי וגו' (איוב לג, כז). אמר רבי יוסי בר חנינא, כל המבקש מטו מחברו אל יבקש ממנו יותר משלש פעמים שנא' (בראשית נ, יז), אנא, שא נא, ועתה שא נא. ופירש רש\"י ז\"ל אין נא אלא לשון בקשה. ע\"כ. וצריך לומר דכונת חז\"ל היא ממה שנאמר בו בפסוק ג' פעמים \"נא\".","b":false},{"t":"והנה בשו\"ת דברי יציב להגה\"ק מקלויזנבורג זלה\"ה בחאו\"ח [ח\"ב] סי' רנ\"ח, דן במי שחטא לחברו אם צריך שיבקש בעצמו מחילה מחברו, או שדי אם מחל לו חברו מעצמו בלא בקשת מחילה. וכתב דנראה לו בפשטות דאם לא ביקש ממנו אלא חברו מחל מעצמו דיו. וכתב להוכיח כן מאחי יוסף שאמרו לו אנא שא נא וגו' ומזה למדו ביומא שהמבקש מחילה לא יבקש יותר משלש פעמים, והקשה הרב ז\"ל למה המתינו אחי יוסף עד מות אביהם ורק אז ביקשו מחילה מיוסף ולא ביקשו ממנו בעת שהתגלה אליהם בראשונה.","b":false},{"t":"וכתב שאחי יוסף חשבו שהוא כבר מחל להם במה שאמר להם (בראשית מה, ה-ח), אל תעצבו וגו' לא אתם שלחתם אותי הנה כי האלהים וגו', ומצינו (שם שם, כב), ולכולם נתן חליפות שמלות וגו', וע\"כ לא הוצרכו לבקש ממנו מחילה. ברם אח\"כ כשמת אביהם ויוסף לא קירבם, וכמו שאמרו רבותינו (ב\"ר ק, ח), והובא נמי בדברי רש\"י ז\"ל על הפסוק ויראו אחי יוסף כי מת אביהם (בראשית נ, טו), וכתב רש\"י ז\"ל שם, מהו ויראו, הכירו במיתתו אצל יוסף, שהיו רגילים לסעוד על שולחנו של יוסף והיה מקרבן בשביל כבוד אביו, ומשמת יעקב לא קרבן. ע\"כ. ולמדו מזה האחים שעדיין לא מחל להם יוסף בלב שלם, ולכן שלחו לבקש ממנו מחילה. ומזה הוכיח הרב דברי יציב שהעיקר הוא שימחל להם אע\"פ שלא בקשו ממנו מחילה, ואשר על כן לא ביקשו האחים מיוסף מחילה בתחילה בעת בה נגלה אליהם, כי סמכו על דבריו וחשבו שמחל להם והסתפקו בזה. והרב דברי יציב שם ציין לדברי בעלי התוספות בספר דעת זקנים.","b":false},{"t":"וזה לשונם בספר דעת זקנים (בראשית נ, טז), ויצוו אל יוסף - ובחיי אביהם למה לא צוו. אלא אמרו מה לנו לעורר השנאה, שהרי כבר שכחה והלכה לה, כיון שחזרו מלקבור אביהם ועבר יוסף על הבור שהשליכוהו אחיו, אמר ברוך שעשה לי נס במקום הזה אמרו עדיין יש שנאה טמונה בלבו מיד ויצוו אל יוסף. ע\"כ. ובאמת שכל דברי הרב דברי יציב כלולים בדבריהם.","b":false},{"t":"ובתשובה (שו\"ת שמע שלמה ח\"ו חאו\"ח סי' יא), הזכרתי את דעתו של מהר\"י ן' חביב בעין יעקב יומא (שם), דס\"ל דלא די שימחל לו חברו, אלא צריך החוטא בעצמו לבקש מחילה ולפייס את חברו. ותוך דבריו כתב, דטעות מה שנוהגין בזמנינו שאם אחד חוטא לחברו נכנס ביניהם מתווך שלום, ודי, ולא כן הוא אלא בעינן שהעולב ילך לפני העלוב ויאמר לו סלח לי. והובאו דבריו בכה\"ח (או\"ח סי' תרו ס\"ק יא), וכתב שהפר\"ח כתב שאין דברי מהר\"י ן' חביב מוכרחין, וגם הרב מטה אפרים כתב דאם קשה עליו לילך בעצמו תחילה, או שהוא יודע שהפיוס קרוב יותר ע\"י איש אמצעי שיתווך ביניהם, יכול לעשות ע\"י אמצעי. וכ\"כ הרב משנה ברורה (סי' תר\"ו ס\"ק ב').","b":false},{"t":"ושם כתבתי לבאר דברי הר\"י ן' חביב, דלשיטתו יוקשה למה לא בקשו אחי יוסף מחילה ממנו בעת שהתודע אליהם, ואין די במה שחשבו שמחל להם, דהא לדבריו צריך להוציא בפיו ולבקש מחילה, וכעין שאמרו הפה שאסר הוא הפה שהתיר, הכי נמי הוא פגע בחברו והשפיל את כבודו, הוא ילך עתה וישפיל עצמו לפני חברו ויבקש ממנו מחילה. וא\"כ אע\"פ שחשבו אחי יוסף שמחל להם, מ\"מ היה להם לבא ולבקש ממנו מחילה בעצמם.","b":false},{"t":"וכתבתי בזה דכיון שבא בזיון גדול לאחי יוסף כשהוכיח אותם קשות, ושוב השיב כספיהם באמתחותיהם ויצא לבם, ושוב הניח את שמעון בבית האסורים והכריחם להביא את בנימין לפניו, ואז העליל עליו עלילה, ולבסוף פרחה נשמתם כמעט כשאמר להם אני יוסף וכו', ובזה כבר כיפר להם על מכירתו, לכך סגי מחילה בלב ואינם צריכים לבקש מחילה בפה אף לשיטת מהר\"י ן' חביב ז\"ל. [א\"ה - ובזה איתנח עוד קושיא אליבא דמהר\"י ן' חביב, דהלא גם כשביקשו מחילה מיוסף לא ביקשו בעצמם אלא ע\"י שליח מתווך שלום, כמו שנא' בהדיא כה תאמרו ליוסף, אבל הם לא בקשו ממנו. ולהנ\"ל ניחא. יבח\"ר].","b":false},{"t":"ועוד יש לומר דבאמת ביקשו ממנו מחילה גם בפעם הראשונה, אלא שהוא השיב להם בדברים טובים ודיבר על לבם, וחשבו שמחל להם לגמרי, ואחר פטירת אביהם שראו שאינו מקרבם חששו שאינו מוחל להם לגמרי ולכן בקשו שוב מחילה.","b":false},{"t":"וצריך עוד לומר דלפי\"ז לא בקשו מחילה בפעם הראשונה בפני ג' שורות בני אדם, ולכן עתה בקשו שוב ושוב מחילה ג\"פ.","b":false},{"t":"ואולם דעת רבינו בחיי (בראשית נ, יז), הבי\"ד הרב דברי יציב שם, דיוסף לא מחל לאחיו, וז\"ל, והנה אחיו בקשו ממנו מחילה, ולא ביאר הכתוב שמחל להם, וכבר ביארו רז\"ל שכל מי שחטא לחברו ועשה תשובה, אינו נמחל לעולם עד שירצה את חברו, ואע\"פ שהזכיר הכתוב וינחם אותם וידבר על לבם, שנראה בזה שהיה להם ריצוי מיוסף מכל מקום לא ראינו שיזכיר הכתוב מחילה ביוסף, ולא שיודה להם שישא פשעם וחטאתם. ואם כן מתו בענשם בלא מחילת יוסף, ואי אפשר להתכפר עונם רק במחילתו, ועל כן הוצרך העונש להיותו כמוס וחתום להפקד אחר זמן בענין עשרה הרוגי מלכות. ע\"כ.","b":false},{"t":"והרב דברי יציב הקשה עליו, שהרי ביקשו אחי יוסף ממנו מחילה ג\"פ, וקשה לומר דיוסף נחשב כרבם, שאפילו אלף פעמים חייבים לשוב ולבקש ממנו מחילה, כמו שנלמד ממעשה רב שמצינו ביומא (פז, ב). ועוד, דאם יש ליוסף דין רב א\"כ כיצד למדו ממנו בגמ' דיומא הנ\"ל, דצריך לבקש מחילה ג\"פ ולא עוד, והא אם היה רבם צריכים לבקש מחילה ואפילו אלף פעמים. וא\"כ קשיא מיניה וביה, עכד\"ק.","b":false},{"t":"ואפשר לומר דאכן היה ליוסף דין רב, כי מלך הוא, ולכן היו צריכים האחים לבקש מיוסף מחילה ואפילו אלף פעמים, ומה שבגמ' למדו מבקשת המחילה של אחי יוסף שצריך לבקש מחילה ג\"פ ולא עוד, אפשר לומר דאסמכתא בעלמא הוא.","b":false},{"t":"ועוד יש לפרש דבאמת לא היה ליוסף דין של רב, ובג' פעמים די לבקש מחילה ואינם חייבים לבקש עוד, וכאשר אמרו בגמרא. אמנם יש לומר דכל זה שאמרו בגמרא הוא כשבא המבקש וביקש מחילה בכל לב, דאז אינו צריך לבקש מחילה יותר מג\"פ. אמנם אחי יוסף לא באו מתוך הכנעה וחרטה גמורה, אלא מפני אימת המלכות, שנתייראו שאחיהם יצר ויציק להם וייסר אותם על אשר עשו לו, אך לא היתה הבקשה מתוך חרטה גמורה, ולכן נשאר העוון הזה תלוי ועומד ונפקדו בגללו עשרת הרוגי המלכות.","b":false},{"t":"וקצת ראיה לזה יש מלשון הפסוקים, שנאמר, ויראו אחי יוסף כי מת אביהם, ויאמרו לו ישטמנו יוסף, והשב ישיב לנו את כל הרעה אשר גמלנו אותו. והיינו כי בחיי אביהם לא נתיראו שהיו סומכין על אותו זקן, שיוסף לא ירצה להכאיבו ולכן לא יקח מהם נקם. אבל עתה אחר שמת אביהם נתיראו, וזו הסיבה שרק אז באו לבקש מחילה.","b":false},{"t":"וברור שבקשת מחילה כזאת לא שמה בקשה ולא היה חייב יוסף למחול להם, כי גם אם יבקשו מחילה יותר מג\"פ אינו נחשב לכלום. ודימיתי דבר זה להלכה ידועה הנזכרת במסכת יבמות (כד, ב), ופסקה הרמב\"ם ז\"ל (פי\"א מהל' איסו\"ב הלכה יד), ובטוש\"ע יו\"ד (סי' רסח), שאין מקבלין גרים לא בימי דוד ולא בימי שלמה. בימי דוד, שמא מן הפחד חזרו. ובימי שלמה, שמא בשביל המלכות והטובה והגדולה שהיו בה ישראל חזרו, שכל החוזר מן העבודת כוכבים בשביל דבר מהבלי העולם, אינו מגירי הצדק. והוא הדין והוא הטעם גם בבקשת המחילה שצריכה להיות אמיתית ומעומק הלב. מתוך הכרה בפגיעה שפגע בחברו, ולא מסיבה אחרת כפחד ויראה. ואחי יוסף לא הכירו בחטאם, ורק מיראה ופחד באו לבקש מחילה, ולכן אינו חייב למחול להם בכה\"ג. וזה מש\"כ רבינו בחיי שאחי יוסף מתו בעוונם, ועל כן פקד עליהם הי\"ת את עוונם בעשרה הרוגי המלכות.","b":false},{"t":"והנה לדעת בעלי התוספות בספר דעת זקנים הנ\"ל שיוסף מחל לאחיו, קשה א\"כ למה פקד הי\"ת על ישראל את עוון מכירת יוסף ולקח עשרה קדושי עליון מזיותני העולם כדי לכפר על העוון הנורא הזה.","b":false},{"t":"ויש לומר דאעפ\"י שיוסף מחל לאחיו מטוב לבו, מפני שראה והבין שמאת הי\"ת היתה זאת, ולטובה היה הדבר, בכדי להחיות עם רב. אבל האחים לא שבו בתשובה שלמה, ולא התחרטו כראוי, והחרטה וההודאה בחטא היא מיסודי התשובה. והי\"ת שהוא בוחן לבות וכליות, הביט לעומק לבם ופקד עליהם את עוון מכירת יוסף, כי בחטא שבין אדם לחבירו אין הי\"ת מוחל עד שיפייס וירצה את חברו (ראה יומא פה, ב), אך גם אחר שפייס את חברו ואחר שחברו מחל לו צריך מחילה מהי\"ת כי בעוון שנאתו פגם גם בחלק גבוה. וכמו שכתב מרן החיד\"א ז\"ל בברכי יוסף (סי' תרו אות א), בשם הרב פרי חדש בשם מהר\"ש גארמיזאן ז\"ל, דבעבירות שבינו לבין חברו איכא נמי חלק גבוה, וכל שלא פייס את חברו גם חלק גבוה אשר בו לא נתכפר, יעו\"ש. והנה בחלק גבוה לא נשלמה תשובת אחי יוסף, כי הי\"ת לא מחל להם על חלקו בענין הזה, ולכן לא נתכפר אותו עוון עד זמן עשרה הרוגי המלכות. כן י\"ל לדעת בעלי התוספות ז\"ל. ועוד הארכתי בתשובה ההיא במו\"מ של הלכה בענין הזה. ע\"ש.","b":false}]},{"id":"22","t":"גדולת יעקב אבינו וגדולת אבותיו הקדושים","p":[{"t":"וַיְצַו אוֹתָם וַיֹּאמֶר אֲלֵהֶם אֲנִי נֶאֱסָף אֶל עַמִּי קִבְרוּ אֹתִי אֶל אֲבֹתָי אֶל הַמְּעָרָה אֲשֶׁר בִּשְׂדֵה עֶפְרוֹן הַחִתִּי, בַּמְּעָרָה אֲשֶׁר בִּשְׂדֵה הַמַּכְפֵּלָה אֲשֶׁר עַל פְּנֵי מַמְרֵא בְּאֶרֶץ כְּנָעַן אֲשֶׁר קָנָה אַבְרָהָם אֶת הַשָּׂדֶה מֵאֵת עֶפְרֹן הַחִתִּי לַאֲחֻזַּת קָבֶר, שָׁמָּה קָּבְרוּ אֶת אַבְרָהָם וְאֵת שָׂרָה אִשְׁתּוֹ שָׁמָּה קָבְרוּ אֶת יִצְחָק וְאֵת רִבְקָה אִשְׁתּוֹ וְשָׁמָּה קָבַרְתִּי אֶת לֵאָה: (מט, כט-לא)","b":true},{"t":"שמעתי בשם הגאון הקדוש רבינו מאיר אביחצירא זיע\"א משם אביו הקדוש המלוב\"נ קדוש ישראל זיע\"א, שהקשה, איך ביקש יעקב אבינו שיקברוהו עם אבותיו, והא אין קוברין צדיק גדול עם מי שפחות ממנו במעלה (ראה טוש\"ע יו\"ד שסב, ה), ויעקב אבינו הוא בחיר שבאבות כמו שנאמר בו ויבא יעקב שלם (בראשית לג, יח).","b":false},{"t":"ותירץ על פי מה שמצינו ביעקב (בראשית מט, לג), ויגוע ויאסף אל עמיו, ואמרו רבותינו (תענית ה, ב), יעקב אבינו לא מת, שהרי לא נזכרה בו לשון מיתה, וכ\"כ רש\"י ז\"ל (בראשית מט, לג). ועל פי זה אתי שפיר, כי הן נודע דגדולים צדיקים במיתתן יותר מבחייהם (חולין ז, ב). אבל יעקב אבינו \"לא מת\", וממילא לא נוספה לו גדולה זו, וא\"כ הוא באותה מעלה כאבותיו, ולכן שפיר צוה שיקברוהו עמהם. ודפח\"ח ש\"י.","b":false}]},{"id":"22","t":"למה נתברך יוסף בפריה ורביה - ובמהות השם שעל ידו מתברכין בפו\"ר","p":[{"t":"מֵאֵל אָבִיךָ וְיַעְזְרֶךָּ וְאֵת שַׁדַּי וִיבָרֲכֶךָּ בִּרְכֹת שָׁמַיִם מֵעָל בִּרְכֹת תְּהוֹם רֹבֶצֶת תָּחַת בִּרְכֹת שָׁדַיִם וָרָחַם: (מט, כה)","b":true},{"t":"כתב רש\"י ז\"ל, ברכות שדים ורחם - ברכתא דאבא ודאמא. כלומר יתברכו המולידים והיולדות שיהיו הזכרים מזריעין טיפה הראויה להריון, והנקבות לא ישכלו את הרחם שלהן להפיל עובריהן. ע\"כ.","b":false},{"t":"ואפשר דטעם הענין שבירך יעקב את יוסף בפריה ורביה ושלא יפילו הנשים את עובריהן, משום שאמרו רבותינו (סוטה לו, ב ופדר\"א פל\"ח), תניא היה ראוי יוסף לצאת ממנו י\"ב שבטים כדרך שיצאו מיעקב אביו, שנאמר (בראשית לז, ב), אלה תולדות יעקב יוסף, אלא שיצא שכבת זרעו מבין ציפורני ידיו וכו', ויצאו ממנו עשרה טיפות וכנגדן הפסיד עשרה שבטים, ולזה בירכו יעקב שיהיו הזכרים מזריעין טפה הראויה להריון והנקבות לא יפילו. ולזה גם בירכו בשם אל שדי שהוא השם שבו מתברכים בפריה ורביה (ונתבאר לעיל בפרשתנו מאמר א).","b":false},{"t":"אל - שדי","b":true},{"t":"והנה מצינו לאבות הקדושים שנשתמשו כולם בשם אל שדי, כמו שנאמר, ויהי אברם בן תשעים שנה ותשע שנים כמו שמצינו באברהם נאמר (בראשית יז, א), וירא ה' אל אברם ויאמר אליו אני אל שדי התהלך לפני והיה תמים. ויצחק אמר ליעקב (שם כח, ג), ואל שדי יברך אותך ויפרך וירבך וגו', והי\"ת קרא ליעקב בשם זה כמו שנא' (שם לה, יא), ויאמר לו אלהים אני אל שדי פרה ורבה וגו'. ויעקב נשתמש בשם זה גם הוא ואמר לבניו (שם מג, יד), ואל שדי יתן לכם רחמים לפני האיש וגו', וכן אמר ליוסף (שם מח, ג), אל שדי נראה אלי בלוז וגו'. וכן מצינו במשה (שמות ו, ג), שאמר לו הי\"ת, וארא אל אברהם אל יצחק ואל יעקב באל שדי ושמי ה' לא נודעתי להם. ובכולם נזכר אל שדי סמוכים זה לזה. וא\"כ יש להבין למה כאן חילקו את השם הנזכר לשנים, מ\"אל\" אביך ויעזרך, ואת \"שדי\" ויברכך.","b":false},{"t":"ואולי יש בזה בחינת \"אל\" שהוא בחינת דוכרא בחינת חסד אל כל היום (תהלים נב, ג), ושם \"שדי\" הוא בחינת נוקבא. ויעקב אבינו בירך את הזכרים לחוד ואת הנקבות לחוד, וכמבואר בלשון רש\"י על הפסוק כאן. וכנ\"ל.","b":false},{"t":"והלום ראיתי לקדוש ה' רבינו חיים ן' עטאר ז\"ל בספר אור החיים שכתב, ואומרו, ואת שדי, פירוש גם שם שדי שהוא השם שבסעד בחינת נפש יוסף כידוע למביני סודי התורה, גם זה היה בעזרו להצילו מבת אל נכר וברכו בו. עכ\"ל.","b":false},{"t":"נמצא דהוא ז\"ל ביאר לנו דשם שדי הוא בחינת נפש, והיינו בחינת נוקבא, והוא סיוע גדול למה שכתבתי, דיעקב אבינו חילק כל שם ושם לבדו, לברך את הזכרים בשם \"אל\" שיזכו לפו\"ר וכנ\"ל. ואת הנקבות בירך בשם \"שדי\" שלא תפלנה את פרי בטנם.","b":false},{"t":"ואפשר שזה רמוז בפסוק מאל אביך, שאביך הוא בחינת זכר, ואח\"כ אמר \"ואת\" שדי וגו', וכל אתין לרבויי אתו, והכא \"את\" לרבות הנקבות. וזהו שממשיך הכתוב ואומר, \"ברכות שמים מעל\", היינו הזכר המשפיע מלמעלה. \"ברכות תהום רובצת תחת\", לרמוז אל האשה שהיא קרקע עולם. והוסיף הכתוב לבאר, שהם ברכות שדים ורחם. ודו\"ק.","b":false}]},{"id":"22","t":"השיר והשבח לחי העולמים","p":[{"t":"נַפְתָּלִי אַיָּלָה שְׁלֻחָה הַנֹּתֵן אִמְרֵי שָׁפֶר: (מט, כא)","b":true},{"t":"ורש\"י ז\"ל כתב, הנותן אמרי שפר - כתרגומו, דבר אחר על מלחמת סיסרא נתנבא, ולקחת עמך עשרת אלפים איש מבני נפתלי וגו' (שופטים ד, ו), והלכו שם בזריזות וכן נאמר שם לשון שלוח, בעמק שולח ברגליו (שם ה, טו). הנותן אמרי שפר. על ידם שרו דבורה וברק שירה. ורבותינו דרשוהו, על יום קבורת יעקב כשערער עשו על המערה במסכת סוטה (יג, א). ותרגומו, יתרמי עדביה, יפול חבלו, והוא יודה על חלקו אמרים נאים ושבח. וכ\"כ הראב\"ע ז\"ל. ע\"ש.","b":false},{"t":"ורבינו יעקב בעל הטורים כתב, הנותן אמרי שפר, על שם ותשר דבורה. \"אמרי שפר\" בגימטריא שיר ושבחה. \"אילה שלוחה הנותן אמרי שפר\" בגימטריא \"ותשר דבורה וברק בן אבינועם ביום ההוא\". עכ\"ל. והוא פלא.","b":false},{"t":"ואגב אורחא למדנו את חשיבות השיר והשבח לחי העולמים, בעת שהם יוצאים בטהרה מהמית הלב והנפש, להודות להלל ולפאר לשמו יתברך, על ישועותיו, טובותיו, ונפלאותיו, שבכל עת ובכל שעה עמנו. עד כמה רמה מעלתם בקודש, עד שיעקב אבינו בשעת רעוא דרעוין, בעומדו לעלות לשמי רום, ומברך את בנו נפתלי, הריהו מזכיר \"אמרי שפר\". שעתידין לצאת מבני נפתלי אחר שנים רבות, דבורה וברק בן אבינועם שעתידין לשיר ולזמר לפני הי\"ת, ויעקב אבינו ראה כבר בעת ההיא עד מה גדלה שירתם ועד כמה היא פועלת את פעולתה בעולמות העליונים.","b":false},{"t":"ומינה ילמד האדם כמה עליו להזהר משירים תפלים, כי זה לעומת זה עשה אלהים, כי כשם שגדול כח השירה להעלות את האדם ולזככו ולטהרו ע\"י הדבקות שישיג מן השיר, כן ביד השירים הטמאים לטמאו ולהורידו לבאר שחת רח\"ל, והריהו פוגם בעלמות העליונים כשמשורר לדברי הבל ורעות רוח רח\"ל.","b":false},{"t":"כי ידוע שכל דבור שיוצא מן הפה כחו גדול עד מאד, כמו מי שמוציא מפיו דבורי תורה ותפלה לחי העולמים, והמה דברים העומדים ברומו של עולם. ולעומתם לשון הרע שיוצא מן הפה שקול כנגד ג' עברות החמורות ע\"ז ג\"ע ושפיכות דמים (ראה ערכין טו, ב), וכן ניבול הפה מטמא את כל הגוף. כי מדיבורי נבלה יוצאת אש אשר עד אבדון תאכל, כי בעון נבלות הפה בחורי ישראל מתים כאשר אמרו רבותינו (שבת לג, א וע\"ע כתובות ח, ב). והוא הדין והוא הטעם נמי בשירה, כי אם היא לכבוד הי\"ת, הריהי מרוממת את האדם עד לרוח הקדש, ואם ח\"ו היא שירה של הבל הריהי מורידה את האדם לשפל המדרגה.","b":false},{"t":"והי\"ת יעזרנו שיהא כל דיבורנו בקדושה ובטהרה, לעשות נחת רוח ליוצרנו ולעשות רצון בוראנו, אכי\"ר.","b":false}]}]}];